Object.assign(window.__LB,{"0": ["病机", "脉数经停，数主热，经停为血枯，热灼阴血，故现虚劳之候。原文谓“先天既弱而水亏，壮火复炽而金燥”，水亏火旺，金受其燥，脉数正是壮火内炽之征，与骨小肉脆之体相应，主虚劳病机。", ["数"]], "1": ["病机", "原文未出脉名，但以“骨肉柔脆之人，其质本弱”言体质，又述咳属手太阴，误补误泻致邪升元虚。虽无脉象，然从脉症较之，可知其咳因质弱而邪侵，补泻失宜，遂成虚实错杂之机，非单纯外感或内伤。", []], "2": ["病机", "脉象左弦数，右搏而长。弦主风木，数主热，搏长主邪盛。值风木旺令，病目黄、遗精淋浊、膝胫肿痛，面沉紫作呕，是肝木化火，下扰肾关，上逆胃腑，由下蒸上，肾胃相关，同一邪气缠绵三病，根本久拨，故脉见弦数搏长。", ["弦", "数", "长"]], "3": ["病机", "右三部洪数弦急并现，左上数中紧。洪数主阳热有余，弦急主木火亢盛，紧主邪结。阳精不升则失精，阳络不固则吐红，先后天俱病。脉见洪数弦急，是至真有余之躯亦难供渐耗，示阳热亢盛、阴精亏耗之病机。", ["洪", "数", "弦", "急"]], "4": ["病机", "脉弦劲如循刀刃，全无冲和之气，是水气太过、金令不及，从后来者谓之贼克。弦劲为肝木偏旺，失其柔和，木亢克土侮金，致阴失潜藏、阳无所倚，故主贼克病机，预后险恶，嘱未雨绸缪。", ["弦", "劲"]], "5": ["病机", "原文谓“脉宜缓而流利”，今洪搏太过，洪搏主邪热亢盛，失其缓滑冲和之常。面黄气重，是湿热内蕴，若处故乡则脉当血溢，示热伤血络之机。今虽在浙，亦当早服丸滋，以制洪搏之太过。", ["洪", "搏"]], "6": ["病机", "寸来空大，心不藏神；关脉滑数，木无水养；尺来浮大，水气不衡。空大主心虚，滑数主肝热，浮大主肾不藏。三脉并见，是心肾不交、肝木失养、水火不济之病机，故见恍惚悸动、肢末不利，治当滋营卫、交心肾。", ["空", "滑", "数", "浮"]], "7": ["预后", "脉象较前稍和，两手平均，俱就六阳本体，可卜无外来之气，惟营卫少虚耳。脉和是胃气渐复、邪气已退之征，故预后良好，但营卫少虚，需培补心阴肾阳，以供日用精神，自当日臻康泰。", ["和"]], "8": ["病机", "原文未出脉名，仅言「从脉色较之」，以脉色合参推断三阳结膈之病机。指出少阴厥阴亦病，胃关不通，郁火挟木邪横亢中州，肝邪逆上因水不生，胃病不纳因肺气不降，津液真精亏乏为关键。脉色所见反映郁火与木邪交争、津液耗损之机，故先以五汁饮生津为治。", []], "9": ["病机", "脉象「虚细无力，弦象俱退」，虚细为元气亏弱之征，弦退则肝邪已减。手足颤振亦由元气不能充养四肢。原文强调「元气不克载药行令」，病机与元气此长彼消，故汤药次之，当以直走先天之品为膏丸久服，使元气元精渐复，后天饮食自强，属虚损病机而非暴感内伤。", ["虚", "细"]], "10": ["主病", "脉空弦而腹中急痛，弦为肝脉，空则中虚，木失所养而横逆，故主肝病急痛。治肝不应则治脾，取培土以御木、补中以实空之意。此段以脉空弦定肝病之位，又以治脾为良法，示弦空之脉非纯实，当兼顾中气之虚。", ["弦", "空"]], "11": ["预后", "脉弦数而上承鱼际，弦属肝风，数属暑热，上承鱼际为邪热上炎之象。暴受暑邪类中，遗溺目瞑，手足厥阴同病，瘖不能言。原文断为「不治」，属邪闭清窍、肝风暑风交炽之危候，故移凉处外解暑邪、内服对证之药以救其逆，示预后不良。", ["弦", "数"]], "12": ["病机", "原文未出脉名，以经脉循行立论：胸走手、腹走足，周于一身。沉寒之邪伤筋损下，先后异时而患则一，非艾灸针刺不能愈，内服八味汤温补。此段从经络受寒、下元受损言病机，强调沉寒痼冷非汤药独能胜任，需灸针并用，属寒伤筋脉、下焦虚寒之候。", []], "13": ["主病", "须眉自落、皮毛淖泽而脉来浮涩，浮为风邪在表，涩为血少滞涩，风邪外袭、营卫不利故脉浮涩。原文断「此风也，非衰白也」，说明须眉脱落非因衰老，乃风邪所致，属三十六种风病之一，非浅表易治之疾，故以香风蛇煮鸡食之祛风。", ["浮", "涩"]], "14": ["病机", "阳明脉实，气急而喘，实为邪热壅盛之象。壮火食气，消烁真阴，阳明热盛上迫于肺故喘急。夏气开张而剧，至剥枣时稍坦，示热盛随天时起伏。此刻以温胆汤少衰其热、以保伤金，说明脉实主阳明壮火、真阴受烁之病机，治在清热保肺。", ["实"]], "15": ["兼症", "体盛之人气本弱，寒热乍起即见小便短数、头项𥆧动、舌干齿燥、气促，脉左弦右弱，渴不欲饮。左弦为邪扰肝经，右弱为中气不足，皆「元不胜邪之象」。恐津液衰而邪遽内陷，值燥令尤须谨慎，示脉症合参以辨正虚邪恋、防其内陷之机。", ["弦", "弱"]], "16": ["病机", "脉数主热，五六日不更衣、舌黄唇焦，显系胃热炽盛，灼伤津液。前服辛温耗阴之品，更助热伤阴，致热邪深入阴中，阳气独亢。故脉数在此反映胃热炽盛、阴伤阳亢之病机，治当寒凉清热，兼顾护阴。", ["数"]], "17": ["病机", "原文未明言脉象，仅述“脉象尚悍”，指脉势强悍有力，提示邪气深入、病根未除。病由食柿过多，寒邪入肺，发为气哮，久则肾水无本，虚而上泛为痰，胃为贮痰之器。脉悍说明邪实深伏，故当深入病所，拟仲景方法逐邪。", []], "18": ["病机", "嗽而失血三载，色黯脉弦，环口色黄，乃肝脾及肾同病。脉弦为肝旺克脾，脾失统血，肾失摄纳，上藏取给不能应，饮邪从而为患。弦脉主肝主饮，故治宗建中法，涤饮升阳，继补太阴，渐入纯阴。", ["弦"]], "19": ["病机", "脉弦数，尺独大，咳而喉痛失音，乃数载失红之后，阴亏火炎之象。弦为肝旺，数为火盛，尺大主肾阴亏虚，虚火上炎，灼肺金则咳、喉痛失音。故当用至静之品引阳入阴，使阴秘阳密，坎离相交。", ["弦", "数", "大"]], "20": ["病机", "形瘦脉虚极，气怯偶咳，目黑脉弦，忽忽不乐，乃气血大虚，阴不敛阳。虚极为正气亏耗，弦为肝木失养、虚风内动。目黑不乐，阴精亏虚不能上奉。故补气补血之外，宜将阴兽引入阴中，以滋填真阴。", ["虚", "弦"]], "21": ["预后", "原文未明言具体脉象，但“色脉形骸俱惫”指色、脉、形皆衰惫，提示正气大虚。禀性好食辛，辛散耗气伤阴，久则形脉俱衰。虽不暴卒，亦难长生，预后不佳，故宜持其病，先服三生欲以缓图。", []], "22": ["预后", "未过五旬，形脉色俱衰，又连丧三子、复伤其孙，悲忧过度，耗伤正气。形脉色俱衰为精气神皆损之象，非药饵所能挽回。此段重在预后判断，说明情志所伤、正气衰败，药力难及。", []], "23": ["病机", "脉数而弦，数主虚火，弦主肝旺，此阴亏症也，非外感。虚火升而头痛，渐有金水两伤之势。数弦并见，反映阴虚阳亢、虚火上炎之病机，故治以熟地、女贞、麦冬、龟板等滋阴潜阳，静摄为要。", ["数", "弦"]], "24": ["病机", "脉细数而微，细为阴伤，数为热邪，微则正气已衰。原文谓「下多伤阴，热邪因之而内陷」，下利伤津，舌干黄、身焦燥不润，皆阴液耗损、热陷于里之象。细数本主阴虚内热，兼微则正虚无力抗邪，故言「大可虑也」，提示邪陷正伤之危候。", ["细", "数", "微"]], "25": ["病机", "原文未明言脉形，仅言「胃气不能脉中流布」，即脉中胃气不充、流布不畅，断为「元气中馁」。中焦为气血津液朝会之所，元气不足则脉道失于充养，故以酸摄、辛流、甘培为法，因增肿患而却甘。此段重在论元气中馁、胃气不布之病机，非专主一脉。", []], "26": ["病机", "引仲景「疟脉自弦」，以弦为疟邪与正气相争之象。今三部九候「并无一毫弦象可见」，则知所感非春之风、夏之暑、南方之瘴等常邪，正气与邪相战之势不显。原文由弦之有无推究疟邪性质，重在以脉辨病机，故归病机。", ["弦"]], "27": ["病机", "「脉愈按愈大」，按之不减反大，是阴气不足、虚阳外浮，疟邪得以深入。原文指出漏芦、鳖甲补阴太过，非花甲劳心之体所宜；汗泄过多则阳气亦虑，胃间伏邪、水饮不入。脉大为阴不敛阳、邪深正伤之征，故诫不可再从汗解。", ["大"]], "28": ["病机", "左尺脉碎乱搏指，碎乱者脉道失其常度、搏指不宁。原文断为「肝风上冒」，又谓「乙癸同源，肾肝同病」。左尺属肾，碎乱搏指示肾阴亏而肝风动，风阳上扰。少阴之脉不至巅，故以肝为重、肾次之，说明病机重心在肝风上冒而非肾。", ["碎", "乱"]], "29": ["病机", "右脉如革，革脉中空外急、如按鼓皮，主虚主革。原文见短气失音、喉中水鸡声、面浮色痿、心下痞硬，谓「肺胃应之」，是肺胃气虚而水饮内停、气机壅塞。补泻纷更无效，甚于水令，故拟苇茎越婢汤以宣肺化饮，脉革正示虚而夹饮之病机。", ["革"]], "30": ["病机", "「弦动无情之脉，即名胃少」，谓脉弦劲而乏柔和胃气，虽非《难经》但弦无胃之甚，久病见此亦属不宜。原文诫莫因失血久进纯阴之药，致「阳气抑而阴无所恃」，主张进甘温。弦动无情示胃气衰少、阳气受抑，故归病机。", ["弦"]], "31": ["病机", "原文未出具体脉形，而言「病在奇经，治他经不应」，又谓血行清道、清气不肃，致鼻红昏晕，二者皆出督脉。此段以奇经督脉立论，说明病机不在常经而在奇经，故治他经无效，当以古法从督脉论治。无脉象描述，脉素取空。", []], "32": ["病机", "脉迟软为阳气衰微之象。暑邪本为热中之阴邪，先犯心胞，今脉迟软，渐见四末渐冷，乃阳衰不能温煦，有内闭外脱之虞。迟主阳微，软主气弱，故急用通阳救逆之法，仿大顺散之义，以挽欲脱之阳。", ["迟", "软"]], "33": ["病机", "右脉芤搏，芤主血虚失血，搏为邪热内郁。耳聋、血下溢、寒热不已，乃阴络所伤，厥阴不摄，血溢于下而热扰于上。芤脉中空，正合阴血亏耗之机，故当从至阴中宣出热邪，以存阴为第一义。", ["芤"]], "34": ["病机", "右脉一息七至弦、六至紧，数急而弦紧，为阴气已弱，金水同病。弦紧主饮邪内停，数主虚热，咳而不得息乃肺肾俱伤，水气上逆。脉至急迫，示病势较急，故议景岳六君煎以培土生金、温养水脏。", ["弦", "紧", "数"]], "35": ["病机", "原文未出脉名，然禀质既薄，咳红极易伤阴，明示阴虚之体。不可理肺者，因水出高原，肺为气母，借以生津补液，周环百脉。此论肺肾相生、金水同源之理，强调治当滋水补液以养肺阴，非单纯治肺可解。", []], "36": ["病机", "两关脉弦，为肝木偏亢、土受克侮；今弦象已减而虚象彰著，是药已应而阳明宿垢未去，煎熬津液，下流不通则上流上泛。虚脉示正气已伤，弦减示肝亢渐平，然暴渴欲饮仍如故，故拟缓法推陈致新，去宿垢以存津液。", ["弦", "虚"]], "37": ["其他", "此段述古方书源流及医事考稽制度，未及脉象。文中所举长桑君禁方、葛洪肘后方、孙思邈千金方等，皆方书著录之事；周礼医师岁终稽医事、宋代颁行名方，亦属医政方剂之考镜，与脉诊病机无直接关联。", []], "38": ["其他", "此段为甘仁先生行医经历及学术心得，未涉脉象。其谓脑疽属少阴、发背属太阳，不当误投寒凉；又论夏至一阴生、冬至一阳生，阴气渐长中阳渐虚，过饮冷则洞泄寒中，因悟附子理中及通脉四逆方治，属医理与治法之论。", []], "39": ["主病", "脉浮滑，浮主表邪，滑主湿痰。外寒束于表分，故寒热无汗、头疼；湿痰内蕴中焦，故胸闷泛恶、纳谷减少，苔白腻。太阳阳明同病，表里俱实，故拟汗解化滞，重用表药，取“体若燔炭，汗出而散”之义。", ["浮", "滑"]], "40": ["病机", "脉浮紧为寒邪外束肌表，卫阳被遏；滑主痰饮内搏。外寒引动内饮，支塞肺络，故咳嗽气喘、难于平卧；寒热无汗为表闭，烦躁为胃有蕴热。脉象与“寒邪外束，痰饮内搏”相应，揭示表寒里饮兼胃热之病机。", ["浮", "紧", "滑"]], "41": ["病机", "左脉郁数，郁为气机不畅，数为热象。无形之邪与有形痰滞互阻阳明，气机郁滞化热，故身热不扬、烦躁不寐、时欲呕；苔薄腻尖红亦为痰热内蕴之征。脉郁数正反映邪郁阳明、痰滞互结之病机。", ["数"]], "42": ["病机", "脉弦滑而数，弦主气滞，滑主痰饮，数主热。太阳阳明未解，痰滞逗留中焦，气滞宣化失司，故发热不退、胸闷呕吐；舌中白苔亦示痰滞。脉象揭示表邪未解、痰热内阻中焦之病机。", ["弦", "滑", "数"]], "43": ["病机", "脉浮滑而数，浮为太阳之邪未罢，滑数为阳明热炽。热熏心包则神明无主，故发热谵语、口渴欲饮；脊背微寒为表邪未尽。脉象反映太阳阳明合病、热盛伤津之病机。", ["浮", "滑", "数"]], "44": ["病机", "脉浮滑而数，浮主太阳表邪未罢，滑数主阳明热盛。热熏蒸肠中浊垢不得下达，故身热十余日不解、五六日不更衣；脊背微寒、苔黄腻亦为表邪兼里热之征。脉象揭示太阳阳明同病、肠腑燥实之病机。", ["浮", "滑", "数"]], "45": ["病机", "脉象沉数，沉主里，数主热。邪已化热由阳明传厥阴，阴液已伤，燥矢不下，热深厥深，故壮热无汗、谵语烦躁、肢反逆冷；舌焦无津为阴伤之象。脉沉数反映热陷厥阴、阴伤燥结之病机。", ["沉", "数"]], "46": ["病机", "脉数未静，数主热，示阳明伏热尚炽；虽得便畅、壮热渐减、四肢转温，但口干欲饮、谵语、舌干糙未润，为少阴津液已伤。脉数未静说明邪热未清、阴津未复，病机仍属少阴阴伤、阳明热炽。", ["数"]], "47": ["病机", "脉数溲赤，数主热，溲赤为热移小肠。壮热大减、谵语止，但舌糙黑未润、口干欲饮，示阴液被热销铄，津无上承。脉数溲赤反映余热未清、阴津亏耗之病机，故再拟甘凉生津以清邪热。", ["数"]], "48": ["预后", "原文述四诊时表里之邪大减，舌焦黑转红绛，为津液来复、邪热退化之机；脉由前之数疾转为“脉数较和”，数象未全消而渐趋和缓，说明余热未尽而正气渐复，故仍守甘凉生津以清余焰，属病势向愈之预后判断。", ["数"]], "49": ["病机", "伤寒一候经水适来，邪热陷入血室，瘀热交结，外无向表之机、内无下行之势，故发热恶寒早轻暮重、神糊谵语、少腹痛拒按。脉弦数者，弦主枢机不利、痛胀，数主邪热内炽，正合瘀热交结血室之病机，症势重险，恐入厥阴。", ["弦", "数"]], "50": ["病机", "肾阴本亏而寒邪外受，太阳少阴同病。寸关浮紧而数，浮紧为风寒束表、营卫不通，数为寒邪郁而化热；尺弱则反映少阴肾气本虚，邪乘虚入。腰为少阴之府，故腰痛如折，脉象正示两感之虚实夹杂病机。", ["弱", "浮", "紧", "数"]], "51": ["病机", "脉浮紧而弦，浮紧为寒邪由皮毛袭肺、束于表分，弦则示寒邪乘夺精之虚直入少阴，逼水中之火飞越于上，故身热不扬、恶寒、咳逆不得卧、咽痛淡红、两颧赤色，成戴阳重症；脉弦紧正是寒束阳浮之象。", ["浮", "紧", "弦"]], "52": ["病机", "太阳少阴两感，寒入少阴，阴盛火衰，故完谷不化、腹痛洞泄；食滞中宫、浊气上逆则胸闷呕吐、苔白腻。脉沉迟而细，沉主里、迟主寒、细主阳虚阴盛，与仲圣“脉沉细，反发热，为少阴病”吻合，示挟阴挟食之重证。", ["沉", "迟", "细"]], "53": ["病机", "服温经达邪、和中消滞后得微汗，恶寒发热较轻，而胸闷呕吐、腹痛泄泻依然，苔腻不化。脉沉略起，说明太阳经邪有外解之势，然少阴伏邪未达、中焦食滞互阻，清浊升降失司，故沉脉虽略起而未复常，恙势尚在重途。", ["沉"]], "54": ["病机", "三诊脉沉已起，恶寒罢而身热未退，泄泻止而呕恶胸闷，渴喜热饮、心烦少寐、舌转灰腻。沉脉起表示少阴之邪已转出阳明之经，然中焦食滞与素蕴湿浊互阻不化，故脉虽起而证未清，脉证参合渐有转机，拟透解阳明、宣化湿滞。", ["沉"]], "55": ["病机", "得汗后表热大减而里热尚炽，渴喜冷饮、心烦少寐、小溲短赤、舌边尖红绛碎痛，为寒已化热、热又伤阴，津少上承而心肝火炽。脉濡数，濡主津伤湿滞、数主内热，正合热伤阴津之病机，故虑劫液之变，拟生津清解降浮火。", ["濡", "数"]], "56": ["病机", "脉左弦数，右濡数。弦主肝火，数主热，濡主湿。阴液已伤，津乏上承，心肝之火内炽，伏热蕴湿交蒸。症见渴喜冷饮、心烦少寐、小溲短赤、舌红绛碎痛糜点，皆阴伤火旺、湿热熏蒸之象。", ["弦", "数", "濡"]], "57": ["病机", "脉数不靖，热势渐退而舌糜亦化，但心烦少寐、渴喜冷饮仍在。数脉主热，不靖示虚火易升。阴液伤而难复，邪热已解，余焰未清，故脉仍数。此虚火旺而易升之病机，非实热未退。", ["数"]], "58": ["病机", "脉象沉细而迟。沉主里，细主虚，迟主寒。伤寒两感，太阳少阴同病，因经后房劳而得，下焦蓄瘀，阳气不足。恶寒发热、头痛无汗为太阳表证；胸闷腹痛拒按、腰酸骨楚、苔白腻为少阴里虚兼瘀滞。脉沉细迟正合阳虚寒凝、瘀阻下焦之机。", ["沉", "细", "迟"]], "59": ["病机", "脉象沉迟。沉主里，迟主寒。昨投麻黄附子细辛汤得畅汗，寒邪外达，发热退、腹痛减，但头胀痛、胸闷不思纳食，苔薄腻。余邪瘀滞未楚，阳气不通，脾胃健运失司，故脉仍沉迟。此里阳未复、瘀滞未净之病机。", ["沉", "迟"]], "60": ["病机", "右脉象浮弦。浮主表，弦主痛、主气滞。汗多如雨、恶风发热不解、遍体骨楚为风入太阳，皮毛开而经腧闭；少腹痛拒按为蓄瘀积而气滞阻。病从房劳经后而得，两感重症。浮弦脉示表邪未解而里瘀气滞，正合温经达邪、去瘀消滞之法。", ["浮", "弦"]], "61": ["病机", "脉沉苔腻，脉沉非表。沉主里，示邪陷于里。外邪由太阳陷于太阴，不得泄越，阳气被遏，胃阳不宣，故口干不欲饮、四肢逆冷、呕恶呃逆、大便不实。四肢逆冷为阳气衰于下之寒厥。此伤寒内陷重症，脉沉非表，为邪陷于里之明证。", ["沉"]], "62": ["病机", "脉象左尺细数，左寸关浮弦而滑，右尺软数，右寸关滑数不扬。细数主阴亏火旺，浮弦滑主风温痰热壅肺。风温秋燥蕴袭肺胃，木火乘势升腾，扰犯肺金，肺炎叶举，故咳嗽胁痛、肌热不退、口渴唇燥。阴分素亏，邪火充斥，症非轻浅。", ["细", "数", "浮", "弦"]], "63": ["病机", "脉象两尺濡数，两寸关滑数无力。濡数主湿温阴伤，滑数无力主痰热而气阴不足。风燥外受，温从内发，蕴蒸肺胃，木火乘势升腾，扰犯于肺，燥痰恋肺，肺炎叶举。尺肤热甚为病温，脉数者曰温，皆伏温熏蒸之象。平素阴亏，温病化热伤阴，阴液愈伤而痰患愈烈。", ["濡", "数", "滑"]], "64": ["病机", "脉象寸关滑数不靖，尺部无力，滑主痰，数主热，寸关候肺胃，提示伏温夹燥痰胶结于肺胃，热势未靖；尺部无力则真阴亏耗，津少上承，故见口干唇燥、溲赤、肌肉消瘦。此脉证反映正虚邪恋，阴液亏而温邪重，虚则多变，预后须防正不胜邪。", ["滑", "数"]], "65": ["病机", "右脉滑数较和，左脉弦数不靖。右候肺胃，滑数较和示痰热渐化；左候肝胆，弦数不靖乃肝热内炽、阴液素亏，木火易炽。气液亏耗，肺胃受摧残，输化失职，故唇燥口干、睡则惊悸、小溲未清。脉证参合，险关已逾而余焰未清。", ["滑", "数", "弦"]], "66": ["病机", "右脉滑数较和，左脉弦数不静。右脉滑数较和示肺胃痰热渐退，左脉弦数不静乃阴液亏耗、肝火易炽。肺金风燥未清，余热留恋，火灼津液为痰，故喉痒、鼻孔烘热、口干唇燥。脉证参合，渐有转机，但燥痰未澈，不可早进滋阴。", ["滑", "数", "弦"]], "67": ["病机", "左脉弦数已缓，右脉滑数亦和。左弦数缓示肝火渐平，右滑数和示肺胃痰热渐化。伏邪已解，肺炎亦消，惟阴分本亏，津少上承，余燥留恋气分，厥阳易升，故口干唇燥、头眩且痛、小溲带黄。脉证示恙已转机，仍须清余燥以化痰热。", ["弦", "数", "滑"]], "68": ["病机", "脉滑数，滑主痰，数主热，风温痰热互蕴肺胃，热盛生痰，风善上升，痰热蒙蔽清窍，故神识模糊、谵语妄言、起坐如狂。胸腹闷胀、唇焦、苔黄腻，内夹宿食。前医投犀羚不应，邪在气不在营。脉证参合，痉厥之险不可不虑。", ["滑", "数"]], "69": ["病机", "脉滑数不扬，滑数主痰热，不扬示邪郁不达。风温伏邪蕴袭肺胃，蓄于经络，不能泄越于外，势有内陷之象。肺邪移大肠则便溏，阳明邪不达则肢冷，热扰则烦躁懊𢙐、抽搐如惊。此非慢惊之虚，恐痧疹内伏，亟宜疏透。", ["滑", "数"]], "70": ["病机", "脉滑数，滑主痰，数主热。服疏透剂后得汗，烦躁泛恶减，面额项颈红点隐隐，痧疹见象。伏温之邪有外达之机，但肺胃之气窒塞不宣，咳嗽痰多、身热不退、舌红苔黄腻。脉滑数示痰热尚盛，仍从辛凉清解，冀痧透热退。", ["滑", "数"]], "71": ["病机", "脉濡数，濡主湿，数主热，温邪夹湿郁于阳明，不得外达。身热有汗不解、口渴欲饮、烦躁不安、舌黄，皆湿热内郁化火之象。脉濡数示湿遏热伏，虑其化火入营，急宜清解伏温而化痰热。", ["濡", "数"]], "72": ["病机", "脉濡数，濡主湿，数主热，为湿热内蕴之象。伏温之邪在营，逼血妄行，故见鼻衄如涌、吐血盈碗；热扰营阴则入夜烦躁；湿阻气机则口干不多饮、苔薄腻。此脉说明湿热郁蒸营分，迫血上溢，非单纯阴虚，故大忌骤用滋阴，恐恋邪不解。", ["濡", "数"]], "73": ["病机", "脉仍濡数，示湿热未清。药后吐衄止而身热转盛，乃伏温由营达气、由里出表之佳象。濡数脉反映气分湿热仍盛，故身热、苔腻稍化。此脉说明邪有外透之势，仍当辛凉清解以泄温邪，不可因热盛而误用寒滞。", ["濡", "数"]], "74": ["病机", "脉滑数，滑主痰湿，数主热，为痰热内蕴之征。风温袭肺胃，湿热蕴蒸气分，故身热旬日、咳嗽痰腥、舌红苔黄；湿热下迫则大便不实；白疹布而未透，示邪郁气分。此脉说明痰热壅盛，症势非轻，治宜轻清宣解，千金苇茎加味。", ["滑", "数"]], "75": ["病机", "脉滑数不扬，滑主痰，数主热，不扬示邪郁不达。风温与痰热互阻肺胃，肃降不行，故咳嗽气急、喉中痰声漉漉；阳明热炽则咬牙嚼齿、抽搐；筋纹色紫达气关，为痰热闭阻之候。此非真痉厥，乃马脾风重症，徒治厥阴无益，当宣肺化痰泄热。", ["滑", "数"]], "76": ["病机", "脉滑数，痰热仍盛。药后发热轻、抽搐定，为佳兆；但咳嗽气逆、喉中痰声、口干溲赤，示风温痰热交阻肺胃，一时未清。滑数脉说明痰热未净，余邪留恋，故仍击鼓再进，清化痰热。", ["滑", "数"]], "77": ["病机", "脉仍滑数，示痰热余焰留恋。三诊后身热减、气急平、抽搐止，风温外解，痰热有下行之势；但咳嗽痰多、口干溲赤、便溏色黄，为痰热未清、肺胃未和。此脉说明邪势已衰而未尽，质小体稚，宜制小其剂，勿使过之。", ["滑", "数"]], "78": ["病机", "脉洪数，洪为阳明热盛之象，数主热。伏温化热，蕴蒸阳明气分，故壮热有汗不解、口渴烦躁；热上熏心包则夜谵语；舌边红中黄，示热炽气分。此脉说明阳明热盛，虑其入营劫津，急拟白虎汤甘寒生津，专清阳明。", ["洪", "数"]], "79": ["病机", "脉沉细而数，沉细主里虚，数主热，示温邪伏营，郁而化火，灼津为痰，痰火蒙蔽心包，肝风骤起，故神识昏糊、谵语、角弓反张、唇焦。脉不洪数，非阳明里热可比，乃厥闭之险。此脉说明邪陷营血，内闭心包，亟宜清温熄风、清神涤痰。", ["沉", "细", "数"]], "80": ["病机", "脉数而乱、脉散，数主热，乱与散示正气溃散、心气无主。原文谓暑热伤津耗气，肺金化源欲绝，肺虚不能下荫于肾，肾不纳气，故发热汗多、气短而喘；肺主皮毛，肺伤卫气失守则汗出甚多。脉散正是肺肾化源将竭、卫外不固之危候，症势危笃。", ["数", "散"]], "81": ["病机", "脉沉数无力，沉主邪郁不达，数主温邪发热，无力示阴液已伤、正气不足。原文谓汗泄不畅、渴而引饮、神昏谵语、叠见呃逆，乃暑热痰浊互阻，木火夹冲气上逆，胃气不得下降，清窍被蒙。脉沉数无力正合阴伤邪郁、痰浊内阻、冲胃之气上逆之机。", ["沉", "数", "虚"]], "82": ["病机", "脉细小而数，右寸微浮而滑。细小为阴液已伤，数为热，右寸浮滑主痰热恋肺。原文谓风温伏邪始在肺胃，继传少阴，津乏上承，热灼津液为痰，痰热弥漫心包，灵机堵塞，肺炎叶枯，有化源告竭之虞。脉象正示阴伤痰热内闭、化源将竭之危。", ["细", "小", "数", "滑"]], "83": ["预后", "原文未识脉名，仅言脉息如昨、数象较和。前诊脉细小而数，今数象转和，结合舌干涸转有润色、神色较清、迷睡亦减，示津液有来复之渐、邪热稍退之机；然里热依然、咳痰艰出、小溲不通，伏温燥痰互阻肺胃未解，故守原意出入。此段重在以脉判预后。", []], "84": ["病机", "脉细滑带数，细主阴液伤而难复，滑主痰，数主热。原文谓神识已清、身热较退，而咳痰艰出、口干欲饮，乃肝火旺而易升，木叩金鸣，火烁津液为痰，痰稠如胶而咳逆难平。脉细滑数正合阴伤未复、肝火痰热留恋肺金之病机。", ["细", "滑", "数"]], "85": ["病机", "脉弦滑而数，弦主厥阳升腾，滑主痰热，数主温邪。原文谓风温伏邪蕴袭肺胃，引动厥阳升腾，扰犯清空，阳升则痰热随之，蒙蔽灵窍，故头痛如劈、神识时明时昧、梦语如谵。脉弦滑数正示痰热与厥阳并升、有痉厥之变之机。", ["弦", "滑", "数"]], "86": ["病机", "脉滑数，滑主痰，数主热。原文谓神识已清、头痛亦减，惟身热未退、咽痛焮红、咽饮不利、口干溲赤、咳痰不爽，舌红苔黄。风为阳邪，温为热气，火为痰之本，痰为火之标，脉滑数正合痰火未清、温邪留恋肺胃之病机，故仍从辛凉解温、清火涤痰。", ["滑", "数"]], "87": ["病机", "脉象弦滑，弦主少阳不和、气机郁滞，滑主痰。原文谓风温伏邪夹痰交阻，肺胃不宣，少阳不和，故寒热往来、咳嗽胸闷、甚则泛恶，舌前半无苔、中后薄腻。脉弦滑正示痰邪交阻、枢机不利之病机，故治以和解枢机、宣肺化痰。", ["弦", "滑"]], "88": ["病机", "脉数不静，为热邪内盛、阴液已伤之象。原文述‘阴液已伤，阳明腑垢不得下达’，数脉主热，不静示热扰阴亏，津伤则肠燥，故五六日未更衣；热灼肺津则口干欲饮、咳嗽痰多。脉数不静正合阳明腑实兼阴伤之病机。", ["数"]], "89": ["病机", "脉滑数，滑主痰湿滞，数主热。原文‘风温伏邪，挟滞交阻，邪不外达，移入大肠’，热邪与滞相搏，故身热复重、大便溏泄；舌苔灰腻而黄亦为湿热滞交阻之征。滑数脉反映邪热内迫、滞阻肠道之病机。", ["滑", "数"]], "90": ["病机", "脉象滑数有力，滑主痰浊，数主热，有力为实。原文‘浊垢不得下达’，热与浊垢结于阳明，故发热、口渴烦躁、谵语妄言、舌糙黄、多日未更衣。滑数有力正是阳明腑实、浊热内结之征，故宜急下存阴。", ["滑", "数"]], "91": ["病机", "脉数主热。原文‘无形之伏温，与有形之痰浊互阻，清阳被灼，君主乃昏’，热邪内炽故脉数；痰浊蒙蔽清阳，则入夜神糊谵语、胸闷烦躁；苔黄亦为热象。数脉在此反映伏温痰浊互阻、热灼神明之病机。", ["数"]], "92": ["预后", "脉濡细，濡为阳气衰微、细为阴血不足。原文‘伏邪不得从阳分而解，而反陷入少阴，真阳外越，神不守舍，阴阳脱离’，故汗多神糊、谵语郑声、如见鬼状。濡细脉示阴阳两伤、真阳外越，脉证参合，危在旦夕，属预后险恶之候。", ["濡", "细"]], "93": ["预后", "脉已沉细，沉主里、细主虚，为阳气衰微、邪陷少阴之象。原文‘邪不得从阳明而解，反陷入少阴，神不守舍，痰浊用事’，故神识模糊、谵语郑声、汗多肢冷；太谿、趺阳脉模糊更示肾胃气衰。沉细脉兆阴阳脱离，预后危急。", ["沉", "细"]], "94": ["其他", "原文未识脉名，仅言‘脉略起’。此乃二诊记录，前方服后肢渐温、汗渐收，脉由沉细略起，示阳气渐回、阴寒渐退之佳兆。‘略起’虽非具体脉象，但反映回阳敛阳治疗后气机渐复，故原方加杏仁以肃肺化痰。", []], "95": ["其他", "原文未识脉名，仅言‘脉亦渐起’。三诊时肢温汗收，脉渐起，阳气已得内返，神识渐清，谵语郑声止，示回阳见效。惟咳嗽痰多、夹血点、喉有痰鸣，舌苔转黄，为伏温外达、痰浊逗留肺胃，故拟清彻余温、宣肺化痰。", []], "96": ["病机", "脉濡小而数，濡为湿象，小为阴伤，数为热存。原文谓“肺阴暗伤，痰热未楚”，咳嗽气逆痰鸣虽减，但咽喉干燥、痰内带红、舌边绛，皆肺阴亏耗、虚热内灼之征；神疲肢倦、脉濡小，又示气阴两伤、痰湿未净。故脉象反映肺阴暗伤为本、痰热未清为标，属虚实夹杂之候。", ["濡", "小", "数"]], "97": ["病机", "脉象濡数，濡主湿，数主热，合为暑湿蕴蒸之象。原文述发热有汗不解、口渴欲饮、胸闷气粗、入夜烦躁、梦语如谵、小溲短赤、苔薄黄，皆暑邪湿热蕴蒸阳明、漫布三焦所致。脉濡数正应暑湿化热、湿热交蒸之病机，故虑暑热逆传厥阴而致昏厥。", ["濡", "数"]], "98": ["病机", "脉象濡数，右部洪滑。濡数主暑湿化热，洪滑为阳明里热炽盛之象。原文谓“暑湿化热，蕴蒸阳明之里”，胃热上蒸心包，扰乱神明，故见汗多发热不解、烦闷谵语、口渴欲饮、舌边红苔黄。右部洪滑尤显胃热壅盛，脉证合参，病机为暑湿化热、阳明热盛上扰心包。", ["濡", "数", "洪", "滑"]], "99": ["病机", "脉伏，为暑热内闭、气机闭塞之征。原文述赤日中暑，忽然跌仆、不省人事、牙关紧闭、肢冷脉伏，谓“暑遏热郁，气机闭塞，脉道为之不利”，即热深厥深。暑热夹痰浊内阻，蒙蔽心包，清阳失旷，故脉道伏匿不显。脉伏在此反映邪闭气塞、热深厥深之重危病机。", ["伏"]], "100": ["预后", "前诊脉伏，服清暑开窍、宣气涤痰之剂后“伏脉渐起”，是暑热闭郁渐开、气机得通之佳兆。原文谓“暑热有外达之机”，然身热头胀、口干不多饮、胸闷不能食、苔薄黄，又示暑必夹湿、湿热蕴蒸有转入阳明之象。伏脉渐起反映邪从内闭转为外达，故属预后转机之论。", ["伏"]], "101": ["病机", "脉濡数，濡主湿滞，数主热郁。原文谓秋凉引动伏暑，夹湿滞内阻，太阳阳明为病，症见寒热无汗、头胀且痛、胸痞泛恶、苔薄腻。脉濡数正合暑湿内郁、邪滞互阻之机，胃气不得下降故胸痞泛恶。脉象反映伏暑夹湿、邪滞互郁，治宜疏透伏邪、化湿滞。", ["濡", "数"]], "102": ["病机", "脉象濡数，为暑湿内蕴、湿热交蒸之征。原文述外受风凉、内蕴伏暑，暑必夹湿，湿与滞阻，阳明为病，故发热恶寒、胸痞泛恶、头胀且痛、遍体酸楚、苔腻布。脉濡数正应暑湿夹滞、邪阻阳明之病机，邪势鸱张，故非易速解，治以黄连香薷饮加减。", ["濡", "数"]], "103": ["病机", "脉濡数，濡主湿，数主热，为暑湿内蕴之象。原文谓暑温十天，身热汗出不彻、渴不多饮、胸脘烦闷、口有甜味、苔薄腻黄，皆暑必夹湿、伏于募原之征。脉濡数正合暑湿黏腻、缠绵难解之病机，势有欲发白㾦之象，故曰暑湿为黏腻之邪，最为缠绵。", ["濡", "数"]], "104": ["病机", "脉左弦数，右滑数。弦主热郁少阳，数主热盛，滑主痰热内蕴。伏暑化热，蕴蒸阳明，胃热上扰心神则烦躁谵语，热迫营分则鼻衄痰红。脉证合参，阴液暗伤，邪热猖獗，有传入厥阴致神昏痉厥之险。", ["弦", "数", "滑"]], "105": ["病机", "脉数依然，说明暑温之热仍踞阳明之里，未能达表。虽身热略减、鼻衄止，但口干胸闷、汗泄不多，乃阴液暗伤，无作汗之资，邪热欲蒸白㾦而不得透达。脉数不退，正示里热未清，仍须甘寒生津、解肌清温。", ["数"]], "106": ["预后", "脉数稍和，是热势渐退之征。服生津清温后，热势反增而汗畅、白㾦布于胸腹，天明热减胸闷舒，乃正胜邪却、邪从表解之机。脉由数而稍和，说明里热得以外达，故曰获效，仍守原法扩充。", ["数"]], "107": ["病机", "脉象濡数不静，濡主湿、主阴伤，数主余热未清。伏暑湿热虽得白㾦外达，但阴液已伤，木火易升，肺金化源受伤，不能下及州都，故小溲频数不爽、溺时管痛；阳明蕴热留恋，故脉数不静。", ["濡", "数"]], "108": ["病机", "脉象濡数无力，濡为湿留、数主余热，无力则示气阴两伤。身热已退、白㾦密布，伏暑之热有肃清之渐，但小溲未爽、咳痰色黄，乃肺胃余热留恋，气化不及州都。脉无力说明正气已伤，故仍拟甘寒生津、养胃清肺。", ["濡", "数"]], "109": ["病机", "脉象弦滑而数，弦主肝风，滑主痰热，数主里热炽盛。伏温由营及气，里热劫少阴之阴，津无上承，阳明腑热熏蒸心包，故谵语妄言、手指震动，肝风欲起，痉厥之变即在目前。脉弦滑数正示痰热内盛、肝风萌动之机。", ["弦", "滑", "数"]], "110": ["病机", "脉尚弦数，弦主木火升腾，数主余热未清。虽得汗、腑垢下行，灼热谵语减，但咳呛痰红、耳聋失聪、唇焦而裂，乃少阴阴液已伤，阳明伏暑化热灼津为痰，痰阻肺络，木火扰犯清窍。脉尚弦数，说明邪热未靖，尚未敢轻许无妨。", ["弦", "数"]], "111": ["预后", "脉左弦数，右濡滑而数。左弦数主木火升腾，右濡滑数主痰热胶阻肺络。虽灼热减半、神识清、舌焦黑退为红绛，津液有来复之渐，但睡则惊悸、耳聋口渴、咳痰夹血，余焰烁液为痰。合脉论证，已有出险入夷之佳象，再议生津泄热、清肺化痰。", ["弦", "数", "濡", "滑"]], "112": ["病机", "左脉弦小而数，弦为木火，小为阴伤，数为热，示肾阴胃液难复，木火易于上升；右濡滑而数，濡滑主痰湿未净，数主余热。结合咳呛咯痰不爽、口渴不多饮、耳鸣失聪、舌绛红，知肺金清肃不行，燥从火化，火克肺金，余波未尽。", ["弦", "小", "数", "濡"]], "113": ["病机", "左脉弦数，右脉濡数。弦数为温邪化热，肝经有火；濡数为湿滞太阴，湿遏热伏。前医早进白虎汤，致邪陷太阴，清气不升，故大便溏薄、日夜十余次；小溲短赤、心烦少寐、热势加剧，皆湿未化而热内炽之象，里重于表。", ["弦", "数", "濡"]], "114": ["病机", "脉象弦数，汗泄不通，发热依然，口干欲饮，舌转红绛。弦为肝火，数为热炽，示气分之温未罢，营分之热内炽；湿化为燥，燥亦伤阴，津乏上承。便溏渐止而热不退，是里湿减而营热未清，故拟清营透气兼顾中土。", ["弦", "数"]], "115": ["病机", "脉弦数不静，舌红绛，身热渐减而鼻红。弦数不静，示阴分已伤，肝火内炽，热遏营分，逼血上行而为红汗；湿从燥化，阳明之温尚未清彻。脉不静即邪未解，故虽有效机，仍须再进一筹清营透气。", ["弦", "数"]], "116": ["预后", "脉象虚滑而数，虚为气阴已伤，滑为湿热痰浊留恋，数为伏邪内蒸。结合潮热、白㾦、谵语郑声、小溲浑赤、唇燥舌红润，知湿热上蒙清窍，神明无以自主。脉证参合，正虚邪盛，已入危险一途，故亟宜扶正宣邪、苦化湿热以望转机。", ["虚", "滑", "数"]], "117": ["病机", "脉濡滑而数，濡主湿，滑主痰，数主热。湿温四天，身热有汗不解，胸痞泛恶，口干不多饮，舌苔薄腻而黄，正是伏邪湿热漫布三焦，气机不宣，痰浊交阻，胃失降和。脉与症合，故治宜宣气淡渗，使湿化热透。", ["濡", "滑", "数"]], "118": ["病机", "脉象濡迟，濡为太阴里湿弥漫，迟为太阳表邪郁遏、阳气不伸。身热有汗恶风、遍体骨楚，是表邪未解；胸闷泛恶、不能饮食、苔腻垢，是湿滞互阻中焦，清不升浊不降，胃乏展和之权。邪势鸱张，故拟五苓合平胃散加减，表里分消。", ["濡", "迟"]], "119": ["病机", "脉象滑数有力，滑主湿滞痰浊，数主暑热，有力为邪实正未虚。发热有汗不解，胸痞泛恶，腹痛痢下日夜四五十次，舌尖绛、中厚灰腻而黄，是暑湿蕴蒸阳明，湿滞郁于肠间，气机窒塞，胃失降和。湿温兼痢之重症，故宜表里双解、通因通用。", ["滑", "数", "有", "力"]], "120": ["病机", "脉数主热，此湿温身热两候，有汗不解，红疹白㾦布于胸膺，苔灰黄，显系伏邪湿热蕴蒸气分，漫布三焦。湿热黏腻难化，故身热久不退。脉数反映热邪内盛，与口干不多饮、苔灰黄相应，治宜宣化。", ["数"]], "121": ["病机", "脉濡滑带数，濡主湿，滑主痰湿，数主热，合为湿热蕴蒸之象。湿温七天，身热有汗不解，午后入夜尤甚，口苦而干，渴不多饮，苔薄腻，乃伏邪蕴湿逗留膜原，少阳阳明为病。前用达原宣化不应，今拟柴葛解肌加味。", ["濡", "滑", "数"]], "122": ["兼症", "二诊身热大减，胸脘不舒，纳减少寐，脉濡滑，苔薄腻微黄，为余邪湿热未楚，胃不和则卧不安。濡滑之脉主湿浊未净，与胸脘不舒、纳减相应。治拟芳香淡渗以靖余氛，并嘱避风节食防反复。", ["濡", "滑"]], "123": ["病机", "脉濡主湿，湿温三候，身热有汗不解，胸痞泛恶，脐腹作胀，两足痿软不能步履，苔腻，乃湿邪自下及上、自外入内，脚气重症。濡脉反映湿浊壅滞，与胸痞、腹胀、足痿相应。若加气喘则危殆，急拟逐湿下行。", ["濡"]], "124": ["病机", "脉象滑数，滑主痰，数主热，乃伏温夹湿夹滞，蕴蒸生痰，痰浊蒙蔽清窍，清阳失旷。故身热早轻暮重，热盛时神识昏糊、谵语妄言，胸痞泛恶，腑行不实，苔灰腻满布。与阳明内热不同，虑传经增变，拟清温化湿、涤痰消滞。", ["滑", "数"]], "125": ["误治", "脉象濡数，本为湿温之象，前医误认暑热，投芩、连、益元散等寒凉太过，致泄泻无度、渴喜热饮、身热依然，舌灰淡黄。此中气本虚，寒凉伤中，邪陷三阴，太阴清气不升，浊阴凝聚，虚气散逆，有似除中，阴盛格阳，真寒假热，势危。仿附子理中合小柴胡意。", ["濡", "数"]], "126": ["病机", "三诊温运太阴、和解枢机后，身热泄泻渐减，胀满亦松，脘饥不多食，均属佳境。脉濡数无力，濡主湿，数无力为虚热，乃中虚脾弱，饮水自救，故渴喜热饮，舌淡黄，神疲倦怠。效方出入，毋庸更张。", ["濡", "数"]], "127": ["病机", "原按指出泻而腹仍膨，非实胀；苔灰淡黄，脉象濡数，俱是假热之象。濡数脉在此非真热，乃阴寒内盛、虚阳外浮所致，故谓不从脉而从症。此案脉症不符，当舍脉从症，辨为真寒假热，与前述误治案相呼应。", ["濡", "数"]], "128": ["病机", "脉濡滑而数，濡主湿、滑主痰、数主热，合为湿热胶结之象。原文言寒凉太过致湿遏热伏、热处湿中，胃阳被遏、气机窒塞，故见呃逆、胸痞泛恶、口舌糜腐、小溲短赤。脉象正反映湿浊内阻、郁热不得透达之坏症病机。", ["濡", "滑", "数"]], "129": ["病机", "脉濡数，濡为湿象、数为热征，说明湿热黏腻胶阻于中焦未化。原文谓湿热胶阻则胸痞噫气，熏蒸于上则口有酸甜，三焦决渎无权则小溲短赤，白疹不现则邪无出路。脉象提示湿郁化热、三焦气机壅滞之病机仍在。", ["濡", "数"]], "130": ["病机", "脉濡数，仍主湿热未清。原文述白疹渐现为伏邪湿热有暗泄之机，然十余日未更衣、小溲短赤、身热临晚似剧，申酉阳明旺时腑垢不得下达。脉象说明三焦余湿未易清澈、阳明腑实与湿热互结之病机。", ["濡", "数"]], "131": ["病机", "脉沉细而数，沉主里、细主阴亏、数主热，合示伏温夹湿陷入厥阴、阴液亏耗而热邪内炽。原文见神识昏糊、牙关紧闭、四肢逆冷、唇燥而焦，兼素体阴亏、肝火内炽、怀孕虑殒胎，脉象正应邪陷营阴、热灼津伤之危笃病机。", ["沉", "细", "数"]], "132": ["病机", "脉仍沉细而数，说明阴液已伤、津无上承，陷入之温邪未能透达。原文见齿垢无津、里热口干、胸闷气粗，痰热胶阻肺络、肺失输布，兼怀孕七月胎气已伤。脉沉细数正合阴亏热伏、痰热内阻之病机。", ["沉", "细", "数"]], "133": ["病机", "脉由沉细转濡滑而数，濡主湿、滑主痰、数主热，示阴液已伤而痰热尚盛。原文谓陷入之邪有暗泄之机，然厥阳升腾、痰热胶阻肺络、肺失输布，怀麟七月胎热乘肺、肺气窒塞。脉象反映痰热恋肺、阴伤未复之病机。", ["濡", "滑", "数"]], "134": ["病机", "左脉弦数、右脉濡滑，弦数为肝经湿火上升，濡滑为痰浊未楚。原文见呕吐又起、不能饮食、口舌碎痛、腑气不行，说明肺胃之气不得下降、痰浊内阻。脉象合示湿火与痰浊交阻、胃失和降之病机。", ["弦", "数", "濡", "滑"]], "135": ["病机", "脉软滑无神，软为气阴不足、滑为痰浊内恋，无神则示正气已伤。原文谓怀麟七月阳明少阴阴液已伤、痰浊未楚、厥气乘势横逆，故见胸脘不舒、饮食少进、神疲、右颧赤色。脉象反映正虚痰恋、肝气横逆之病机。", ["软", "滑"]], "136": ["病机", "脉象濡滑而数，濡主湿邪未化，滑主浊痰内蕴，数主伏邪湿热未清。原文谓“伏邪湿热，已有外泄之佳象”，然“阴伤难复，浊痰未化，津少上承”，故脉见濡滑而数，提示湿热余邪未净、阴津已伤、痰浊内阻之病机，与口干不多饮、舌红苔薄腻、白㾦外透等症相应。", ["濡", "滑", "数"]], "137": ["病机", "脉象濡数，左关带弦，濡主湿邪黏腻，数主温邪内蕴，弦主热处湿中、蕴蒸膜原。原文谓“温与湿合，热处湿中，蕴蒸膜原，漫布三焦”，故脉见濡数而左关弦，说明湿温之邪留恋气分、三焦气机不畅之病机，与身热午后尤甚、胸闷不食、苔腻带黄等症相应。", ["濡", "数", "弦"]], "138": ["病机", "脉左濡数、右濡迟，趺阳亦弱，濡主湿困，数主余热，迟弱主脾阳不振。原文谓“太阴为湿所困，清气下陷”，又谓“少阴阴阳两伤，上有浮热，下有虚寒”，故脉见左濡数右濡迟而趺阳弱，说明湿温日久、脾阳下陷、少阴阴阳两伤之病机，与溏泻黑多黄少、唇焦齿垢、饮入肠鸣等症相应。", ["濡", "数", "迟", "弱"]], "139": ["病机", "脉象濡数，尺部细弱，濡数主伏温蕴湿未清，尺部细弱主少阴阴伤。原文谓“少阴之阴，太阴之阳，因泻而伤，清津无以上供”，又谓“泻不止，则正气不复”，故脉见濡数而尺部细弱，说明湿温日久、气阴两伤、余邪未透之病机，与泄泻、齿缝渗血、白㾦细小不密等症相应。", ["濡", "数", "细", "弱"]], "140": ["病机", "脉濡数而缓，濡主余湿未净，数主余热留恋，缓主胃气渐复、太阴健运之渐。原文谓“太阴已有健运之渐，白㾦布而甚多，色亦显明，正胜邪达之佳象”，然“余湿酿成痰浊，留恋中焦，胃气呆顿”，故脉见濡数而缓，说明气阴两伤、余湿痰浊留恋中焦之病机，与口干而腻、不思谷食、面红谵语等症相应。", ["濡", "数", "缓"]], "141": ["病机", "脉数主热盛，原文谓“秋温伏暑，蕴蒸阳阴，身热甚壮，有汗不解，口干欲饮，苔黄”，又谓“热在阳明，湿在太阴”，故脉数说明阳明热盛、太阴湿蕴之病机，与壮热有汗不解、两足逆冷等症相应，两足逆冷乃热深厥深之象，非中寒可比。", ["数"]], "142": ["病机", "脉象沉数，沉主病在里，数主热盛，原文谓“伏邪蕴湿化热，由气及营，由经入腑，腑中宿垢不得下达”，故脉见沉数，说明湿温伏邪化热入腑、宿垢内结之病机，与潮热、八九日未更衣、脐下按之疼痛、舌红绛中后腻黄等症相应。", ["沉", "数"]], "143": ["病机", "脉濡数无力，濡主余湿未清，数主余热留恋，无力主气阴两伤。原文谓“阴液暗伤，余热留恋气营之间，清津无以上供”，故脉见濡数无力，说明腑气虽通而阴液已伤、余热未净之病机，与潮热渐减、口干欲饮、舌中腻黄渐化等症相应。", ["濡", "数"]], "144": ["病机", "脉弦滑而数，弦主湿郁，滑主湿盛，数主热炽。湿温八天，壮热有汗不解，口干烦躁，谵语胸痞，溲赤苔黄，显系阳明热炽、太阴湿蕴，湿热蕴蒸气分，漫布三焦，有湿化燥、热化火之势，故脉象如此。", ["弦", "滑", "数"]], "145": ["病机", "脉洪数较缓，较前之洪数已减，示壮热之势大减，伏温渐解。然胸闷泛恶、苔腻黄渐化，蕴湿犹留中焦，故脉仍数而缓，为湿热未清、气分余邪未净之象，既见效机，仍守前法参入淡渗。", ["洪", "数"]], "146": ["病机", "左脉弦数，右濡滑。弦数主少阳伏邪，濡滑主湿蕴中焦。热退复寒热似疟，胸闷泛恶，溲短赤，苔黄口苦，乃伏匿之邪移于少阳，湿留恋中焦，胃失降和，枢机不利，故脉象应之。", ["弦", "数", "濡", "滑"]], "147": ["病机", "脉虚弦而数，虚为正气已虚，弦数主邪热未罢。湿温月余，形瘦骨立，纳衰，谵语郑声，白疹不显，乃病久正虚，太少之邪未罢，湿恋膜原，枢机不和，正不敌邪，故脉虚弦而数。", ["虚", "弦", "数"]], "148": ["病机", "脉濡数，濡主湿，数主热。进和解剂后寒热渐退，谵语止，白疹渐多，邪有外达之势。然口干不多饮，精神疲倦，谷食衰微，正气已夺，脾胃鼓舞无权，故脉濡数而无力，虚多邪少。", ["濡", "数"]], "149": ["病机", "脉来濡数，濡为湿，数为热，湿热合蕴蒸气分，漫布三焦。身热三候，朝轻暮重，白疹满布，形瘦神疲，乃湿热郁久不化，耗气伤阴所致，症势非轻，急宜存阴清宣。", ["濡", "数"]], "150": ["病机", "脉濡数无力，濡数主湿热余邪，无力为气阴已伤。湿温四候，身热早轻暮重，有汗不解，白㾦不显，口干唇燥，形瘦神疲，舌红苔黄，乃气阴两伤，余邪湿热留恋气营之间，虚多邪少，故脉无力。", ["濡", "数", "虚"]], "151": ["病机", "脉弦数，弦主热郁营分，数主热炽。湿温十六天，身灼热有汗不退，口渴烦躁，梦语如谵，目红溲赤，舌红糙无津，红疹布胸，此温化热、湿化燥，燥火入营，伤阴劫津，化源告竭，风动痉厥之变恐在目前。", ["弦", "数"]], "152": ["病机", "脉数不静，为营分热炽、木火升腾之象。原文谓“少阴之阴已伤，水不济火”，阴亏不能制火，故脉数而躁动不安。虽身灼热口渴减、寐略安，但红疹布多、目白红丝、小溲短赤，皆营热外达而木火未靖之征，故脉仍数不静，示热未全解。", ["数"]], "153": ["病机", "脉数不静，乃阴液难骤复、木火尚炽之余焰未净。原文谓“营分之热已得外达”，红疹满布，身灼热大减，梦语止，但舌转光红、小便黄、多日未更衣，阴伤肠燥，余热未清，故脉数不静，主津亏热恋、腑气不通之病机。", ["数"]], "154": ["病机", "脉象濡软而数，为邪退正虚、脾胃鼓舞无权之候。原文谓“身灼热已退，寐安神清”，红疹渐化，腑气亦通，但精神疲倦、谷食无味、小溲淡黄，显系湿温后期气阴两伤，余湿未净，脾胃运化乏力，故脉濡软而数，主正虚湿恋之病机。", ["濡", "软", "数"]], "155": ["预后", "脉左弦细促数，右部虚散，为阴液枯槁、正气亦匮之危候。原文谓温涩太过致“邪遏化热，湿遏化燥，伤阴劫津，化源告竭”，气逆而促、神糊谵语，舌苔黑糙而垢，腹无燥实坚满，不可下，脉象示厥脱之变即在目前，故主预后不良。", ["弦", "细", "促", "数"]], "156": ["病机", "脉洪数，为温邪化火、由气入营、热邪内炽之象。原文谓“扰犯包宫，伤津劫液，化源欲竭”，故见灼热不退、舌绛起刺、唇焦齿垢、谵语妄言，脉洪数正合气营两燔、热盛伤津之病机，属内陷重症。", ["洪", "数"]], "157": ["病机", "脉濡数，为湿温兼阴虚之候。原文谓“素有失红，阴虚体质”，湿邪蕴阻，故身热有汗不解、临晚畏寒、入夜热盛；湿困太阴，健运无权，水湿泛滥则肤肿足肿、脐腹饱满、面浮咳嗽。脉濡主湿，数主热，示湿郁化热、水湿内停之病机。", ["濡", "数"]], "158": ["病机", "脉寸部濡数，关尺迟弱，为真阳埋没、阴霾满布之危象。原文谓“太阳之阳不行，少阴之阴亦伤”，少火不能生土，水湿日积，泛滥横溢，浊阴凝聚，阴盛格阳。寸濡数示虚阳上浮，关尺迟弱示肾阳衰微，主水湿泛滥、真阳式微之病机。", ["濡", "数", "迟", "弱"]], "159": ["预后", "脉象关尺迟弱略起，为真阳有震动之渐、水湿有下行之势的佳象。原文谓服五苓真武后肤肿腹满轻减、小溲稍多，临晚寒热得汗而退，枢机有斡旋之意；但口干喜热饮、痰多咳嗽、谷食衰微，太阴湿困未复，脉略起示阳气渐回，主病势向愈之预后。", ["迟", "弱"]], "160": ["病机", "脉象缓滑，缓主脾虚，滑主湿痰。原文述肿退腹满渐消，但痰多咳嗽、纳谷衰少、小溲不清，苔薄腻微黄，显系脾不健运、胃不流通，湿痰积肺，肺失肃化。脉缓滑正合脾虚湿痰内蕴之机，故主病为脾运失健、痰湿恋肺。", ["缓", "滑"]], "161": ["病机", "脉象濡滑，濡主湿困，滑主痰聚。原文谓肿满已消、寒热亦退，惟纳谷衰少、口有甜味、痰多咳嗽、小溲不清，乃余湿留恋中焦，脾胃运化失司，津液不布为痰。濡滑之脉恰应湿痰未清、脾运不健之病机。", ["濡", "滑"]], "162": ["病机", "左脉弦迟而紧，右沉细无力。弦紧主寒主痛，迟主阴寒，沉细无力为阳衰。原文述湿温匝月，苦寒叠进，邪陷少阴厥阴，清阳窒塞，蓄瘀下焦，膀胱宣化失司，阴盛格阳。脉弦迟紧示寒湿瘀滞，右沉细无力示阳气虚衰，故主阴寒内盛、格阳于上之病机。", ["弦", "迟", "紧", "沉细"]], "163": ["病机", "脉仍弦迟，弦主寒滞，迟主阳虚。原文述呕吐烦躁减轻，少腹胀痛松，反大便溏泄七八次，为寒滞下行、中阳来复之佳象；身热、口干唇燥、渴喜热饮，苔腻稍化，脉仍弦迟，说明寒湿未净、阳未全复，故不可因燥热改弦易辙。", ["弦", "迟"]], "164": ["病机", "寸关濡滑，尺部涩迟。濡滑主湿痰蕴于中上，涩迟主瘀滞寒凝在下。原文述呕吐溏泄止，少腹胀痛减，惟小溲不利、溺时管痛、唇燥口干不多饮，是蓄瘀蕴湿留恋下焦，膀胱气化无权，脾不能为胃行津液。脉象上下分候，正合湿瘀阻下之病机。", ["濡", "滑", "涩", "迟"]], "165": ["病机", "脉现濡缓，濡主湿余，缓主脾虚。原文述诸恙十减七八，小溲亦利，惟纳谷衰少、神疲肢倦、唇干口干不多饮、苔转淡黄，是脾胃两伤、运化失常，余湿未净。濡缓之脉与脾虚湿困之病机相应，故拟醒脾和胃、宣余湿。", ["濡", "缓"]], "166": ["预后", "脉沉细无神，沉主里，细主虚，无神为阳气衰败。原文述湿温十八天，身热继则不热，两颧红赤，小溲自遗，时时欲寐，舌灰薄腻，口干不欲饮，此邪陷少阴，肾阳堙没，龙雷之火飞越于上，戴阳症也。脉沉细无神正合阳衰阴盛、浮阳上越之危候，故殊为可虑。", ["沉", "细"]], "167": ["预后", "脉象沉细，沉主里，细主虚。原文述湿温月余，身热汗多，神识昏糊，谵语郑声，唇燥口干不欲饮，谷食不进，舌苔干腻，湿邪久困太阴陷入少阴，伤阳致卫阳失护、浮阳外越、神不守舍，动则微喘肾气不纳，阴结便闭。脉证参合，正气涣散，阴阳脱离即在目前，故主危候。", ["沉", "细"]], "168": ["病机", "脉沉细为阳气不运、阴气凝结之象。沉主里主阴，细主虚主寒。原文述口干渴喜热饮、纳少神困、十余日未更衣、腹微胀不拒按、苔干腻，皆阳不运行、阴凝肠腑所致，犹严寒水冰地坼，故脉沉细主阳虚阴结、腑气不通之病机。", ["沉", "细"]], "169": ["病机", "脉象濡数，濡主湿主虚，数主热。原文湿温月余，身热不退、腹痛便泄、腹胀浮肿，纹色青紫逾气关，为三阳之邪传入三阴，水湿泛滥横溢。濡为湿盛，数为邪热未清，故脉濡数主湿温久延、三阴同病、水湿泛滥之病机。", ["濡", "数"]], "170": ["病机", "脉仍濡数无力，濡主湿，数主热，无力为虚。原文腹胀肢肿减轻、泄泻止，但身热晚作、口干欲饮，纹色回气关，断为阴盛格阳、真寒假热。脉濡数无力正是虚阳外浮、湿浊内蕴之征，故主阴盛格阳、真寒假热之病机。", ["濡", "数"]], "171": ["病机", "脉濡弱，濡主湿浊痰滞，弱主气阴不足。原文两目上窜、角弓反张、脐腹疼胀、舌强不利吮乳、哭声不扬，为气阴暗伤、虚风内动、痰热逗留、肺胃气机窒塞。脉濡弱正合虚风夹痰、气阴两伤之候，故主虚风内动、痰阻窍道之病机。", ["濡", "弱"]], "172": ["病机", "脉象弦细，弦主风主肝，细主阴血不足。原文角弓反张已和，但舌强不利吮乳、手足心热、哭泣声哑，为风阳挟痰热上阻廉泉、横窜络道，肺胃气机窒塞。弦为风阳未息，细为阴伤，故脉弦细主风阳痰热阻络、肺胃气窒之病机。", ["弦", "细"]], "173": ["主病", "脉紧急，紧主寒主痛，急主拘急。原文形寒畏冷、遍身骨楚、头项强痛、泛泛作恶、小溲短少、苔薄腻，为太阳阳明两经同病，寒邪外束。脉紧急正是寒邪收引、经气不利之征，故主太阳阳明合病、寒邪表实之病。", ["紧", "急"]], "174": ["病机", "脉象弦数，弦主少阳主风，数主热。原文得汗后头项痛骨楚均舒、泛恶止，但身热头眩、口干欲饮、苔薄腻黄、舌质红，为太阳之邪已解，阳明之热内炽。脉弦数正是热盛于里、风阳未靖之象，故主阳明热炽、太阳余邪未清之病机。", ["弦", "数"]], "175": ["病机", "脉象弦数，弦主风主肝，数主热。原文身热不退、头项强痛、角弓反张、神昏谵语、渴喜冷饮、舌红，前医叠投表散，汗多伤阴，阴虚不能敛阳，风动呃逆可虑。脉弦数正是阴虚阳亢、风热内动之征，故主阴虚阳浮、热盛风动之病机。", ["弦", "数"]], "176": ["病机", "脉细数，细为阴亏于下，数主阳浮于上，与头项强痛轻减、身热略退、渴喜多饮、苔腻舌红相应。阴液不足则脉细，阳热内浮则脉数，故曰阴亏于下、阳浮于上，前方见效仍守原意。", ["细", "数"]], "177": ["预后", "脉濡细，濡主湿滞未化，细主正气已伤，与神疲欲卧、纳谷不香、苔薄腻相应。神志清、头项强痛止，险岭已逾，然脾运未复，湿浊留恋，故脉见濡细，再与清养善后。", ["濡", "细"]], "178": ["病机", "脉伏因阳邪锢闭于内，中阳不伸，不能鼓击于脉道，与肢冷、两足转筋、汗多烦躁、口渴不欲饮相应。阴盛格阳，阴躁之象，形肉削瘦，脾土大伤，脉证参合，危在旦夕。", ["伏"]], "179": ["兼症", "复诊吐泻烦躁均减，而脉伏肢冷依然，说明中阳未复，阴寒仍锢，不能鼓击脉道、通达四肢。虽症减而脉未起，故加炒潞党参以扶正，兼顾阳气来复。", ["伏"]], "180": ["病机", "脉伏肢冷，因浊阴盘踞中州，阴气不能通达，与吐泻交作、目陷肉削、汗出如雨相应。脾主四肢，阳气外越则自汗，正气大虚则目陷肉削，虚中夹实，阴霍乱重症。", ["伏"]], "181": ["病机", "脉伏因湿遏热伏，气机闭塞，与腹中绞痛、烦躁懊𢙐、吐泻、四肢厥逆、口干欲饮、苔黄相应。热深厥深，阴阳乖戾，气乱于中，霍乱重症，亟宜辛开苦降、芳香化浊。", ["伏"]], "182": ["预后", "二诊脉息渐起，四肢微温，为佳兆，说明气机渐通，阳气来复。惟烦躁干恶、口渴喜冷饮、舌红绛、小溲短赤，是吐伤胃、泻伤脾，脾阳胃阴既伤，木火上冲，伏暑湿热留恋不化。", []], "183": ["病机", "三诊脉起肢温，吐泻已止，烦躁干恶亦减，惟身热口渴喜冷饮、小溲短少而赤、舌红苔黄，是阴液已伤，伏暑湿热蕴蒸膜原，三焦宣化失司，故拟生津清暑、苦寒泄热、淡渗化湿。", []], "184": ["病机", "脉沉似伏，乃寒暑湿滞互阻太阴阳明，阴阳逆乱、清浊混淆，气机壅塞，脉道不利，故脉沉而似伏。沉为在里，伏为邪闭，吐泻交作、腹中绞痛、烦闷懊𢙐皆由清浊相干、升降失司所致，属霍乱重症，故亟拟芳香化浊、分利阴阳。", ["沉", "伏"]], "185": ["预后", "前脉沉似伏，今转濡数，是里邪有外达之机。濡为湿滞未化，数为伏热外透，故反见身热、口干不多饮、苔灰腻而黄。吐泻渐止、腹痛亦减，说明太阴阳明气机渐通，里病有转表之象，属佳境，仍守原意加解表，俾伏邪从汗而散。", ["濡", "数"]], "186": ["病机", "吐泻虽止而里热口渴、烦躁不寐、舌糙黑，脉细数，细为阴液亏耗，数为热邪内炽。吐泻伤脾胃之阴，阴伤则脉细；心肝之火内炽，火盛则脉数。此脾胃阴伤、心肝火旺之病机，故当养阴救液而清伏热，不可再事分利。", ["细", "数"]], "187": ["病机", "脉沉主里，暑湿夹滞互阻中焦，湿遏热伏，气道闭塞，气闭不能通达经隧，故脉沉而四肢厥冷。吐泻交作、腹中绞痛、舌灰腻微黄，皆清浊混淆、升降失司之象。邪入胃则呕，入脾则泻，此感受疫疠之气由口鼻入中道，属霍乱重症，急拟芳香化浊、分利阴阳。", ["沉"]], "188": ["病机", "脉细欲伏，细为湿遏热伏、气机痞塞，伏为脉道不利。疫疠挟暑湿滞互阻太阴阳明，清浊相干，阴阳反戾，气乱于中，故腹中绞痛、吐泻交作、四肢逆冷、口干欲饮。肢冷脉伏由气机痞塞、脉道不利所致，非阳亡之比，故拟萸连解毒汤辛开苦降、芳香化浊。", ["细", "伏"]], "189": ["预后", "脉伏肢冷，目陷肉削，汗出如冰，乃浊阴盘踞中州，阴气不能通达，阳有散亡之象。伏脉非邪闭可比，合肢冷、汗出如冰，是阴无退散之期而阳将外脱，属阴霍乱危症，危在旦夕。故勉拟通脉四逆汤驱内胜之阴、复外散之阳，能否挽回未可知。", ["伏"]], "190": ["病机", "脉浮为时气之邪袭于表分，湿滞互阻肠胃，表里两病。浮脉主表，故见寒热无汗、遍体酸疼；湿滞内阻、清浊混淆，故胸闷泛恶、腹鸣泄泻、小溲不利、舌腻。此表邪未解而里湿滞并见，仿喻氏逆流挽舟之意，拟仓廪汤疏解表邪而化湿滞。", ["浮"]], "191": ["病机", "脉迟为受寒挟湿停滞，寒湿内阻，阳气不运，故脉行迟慢。脾胃两病，清不升而浊不降，故胸闷泛恶、腹痛泄泻、苔腻。迟脉在此主寒主湿，非虚寒之迟，乃寒湿困阻中焦、气机不利所致，故拟正气饮加减芳香化浊、分利阴阳。", ["迟"]], "192": ["病机", "脉濡数，濡主湿，数主热，为暑湿挟滞交阻肠胃之象。暑湿内蕴，肠胃气机壅滞，故腹痛泄泻黄水、日十余次；湿阻中焦则胸闷不能纳谷；湿热下注则小溲短赤；热伤津液则口干欲饮、舌红苔黄。脉证合参，病机为暑湿挟滞，肠胃失和。", ["濡", "数"]], "193": ["病机", "脉象弦细，弦为肝气横逆，细为血亏阴伤。患者形瘦色苍，木火体质，血亏不能养肝，肝气犯胃则呕，克脾则泻；泻久阴伤，津无上潮，故口干舌光、经闭四月。脉弦细正是肝郁血虚、阴津亏耗之征，延即成损，故拟敛肝柔肝、扶土和中。", ["弦", "细"]], "194": ["病机", "脉濡细，濡主湿、主虚，细主阴血不足。五更泄泻延经数月，泻后粪门坠胀，纳谷衰少，形瘦色萎，舌无苔，乃命火式微，不能生土，脾乏健运，清气下陷所致。脉濡细正合脾肾阳虚、湿浊内停之病机，故拟补中益气合四神加减，益气扶土而助少火。", ["濡", "细"]], "195": ["病机", "脉象弦细，弦为肝燥，细为营血虚。泄泻黄水日久，湿胜伤阴，浊阴上干则面浮，清阳下陷则足肿；脾湿入带脉则带下频频；脾津不蒸则内热口干；浮阳上升则头眩眼花；肾虚则腰酸。脉弦细反映脾失健运、胃乏坤顺、营血虚而肝燥、脾湿陷而肾寒之复杂病机。", ["弦", "细"]], "196": ["病机", "脉濡软，濡主湿滞，软主脾虚。脾土薄弱，湿滞易停，故泄泻青水；风邪淫肝，肝木乘脾，脾胃运化失常，则纳少神疲。脉濡软正是脾虚湿盛、肝木乘脾之象，故宜扶土和中、祛风胜湿。", ["濡", "软"]], "197": ["病机", "脉象浮紧而数，浮主表邪，紧主寒痛，数主热。感受时气之邪，袭于表分，故寒热呕恶；湿热挟滞互阻肠胃，故腹痛痢下日夜五六十次、赤白相杂、里急后重、苔腻布。脉浮紧数正是表邪未解、湿热挟滞内壅之噤口痢重症，先宜解表导滞。", ["浮", "紧", "数"]], "198": ["病机", "二诊得汗，寒热较轻，脉象紧数，紧主痛、主积滞，数主热。表邪虽渐解，而湿热挟滞胶阻曲肠，浊气上干，阳明通降失司，故痢下如故、腹痛加剧、胸闷泛恶、饮食不进、苔腻不化。脉紧数反映积滞内阻、湿热壅盛之病机，恙势尚在重途，再宜疏邪导滞、辛开苦降。", ["紧", "数"]], "199": ["病机", "脉转弦滑，弦主气机窒塞，滑主湿滞痰积。三诊寒热已退，呕恶亦减，而腹痛痢下依然，脘闷不思纳谷，苔腻稍化，脉转弦滑，说明湿热滞尚留曲肠，气机窒塞不通。脉象由紧数转弦滑，反映表邪已解而积滞未化，故仍宜寒热并用、通行积滞。", ["弦", "滑"]], "200": ["病机", "脉象濡数，濡主湿滞，数主热，提示湿热滞尚未清澈。原文谓“正气虽虚，湿热滞尚未清澈，脾胃运化无权”，故脉濡数反映湿浊内蕴、脾胃运化失职，与脘闷不思纳谷、苔厚腻渐化相应，病机为虚实夹杂，湿热未净。", ["濡", "数"]], "201": ["病机", "脉滑数，滑主湿滞痰浊，数主热，此脉象反映时疫伏温蕴蒸阳明，湿滞败浊互阻曲肠。原文谓“时疫伏温，蕴蒸阳明，欲达而不能达，湿滞败浊，互阻曲肠”，故脉滑数主里热炽盛、湿浊壅滞，与发热、下痢频繁、腹痛后重、苔腻黄相应。", ["滑", "数"]], "202": ["病机", "脉滑数不静，滑数主湿热内蕴，不静示邪未退。原文谓“湿热败浊，尚在曲肠之间，未得下行也”，虽得汗发热较轻、白疹外达，但脉仍滑数不静，说明湿热败浊未清，肠中气机未畅，故腹痛后重虽减而未除，纳谷无味、苔黄。", ["滑", "数"]], "203": ["病机", "脉濡滑而数，濡主湿，滑主痰湿，数主热，示湿热滞尚未清澈。原文谓“阴液暗伤，湿热滞尚未清澈，肠胃气机不和”，故脉象反映湿浊内蕴、热邪未净，与神疲色萎、口干不多饮、苔薄黄相应，病机为虚实夹杂，不可骤补。", ["濡", "滑", "数"]], "204": ["病机", "脉象弦数，弦主热郁营分，数主热盛。原文谓“阴液素亏，津乏上承，伏温在营，血渗大肠，肠中湿浊稽留，气机痞塞不通”，故脉弦数反映伏温化热、营热炽盛，与血痢、身热晚甚、口干、舌糙绛相应，病机为营热夹湿浊。", ["弦", "数"]], "205": ["病机", "脉弦数，弦主厥阴热盛，数主热炽。原文谓“伏温化热，由阳明而传于厥少二阴”，厥阴有热则血溢沸腾下迫大肠为血痢，少阴水亏火无所济则烦躁不寐。脉弦数反映热传厥少、阴伤火旺，与舌红绛、苔糙黑无津、烦躁不寐相应。", ["弦", "数"]], "206": ["病机", "脉弦数不静，弦数主热邪未清，不静示邪热仍炽。原文谓“阴液大伤，清津无以上供”，虽血痢减、有微汗，但脉弦数不静，说明营分邪热未净，阴液难复，与齿垢唇燥、舌焦糙、口渴不欲饮相应，病机为营热未退、阴伤未复。", ["弦", "数"]], "207": ["病机", "脉濡数，濡主湿滞，数主热，示邪热退而未净。原文谓“阴液伤而难复，邪热退而未净也”，血痢大减、身热减半，但脉仍濡数，说明余热夹湿未清，阴液未复，与唇燥口干、不思纳谷、舌光红相应，病机为阴伤邪恋。", ["濡", "数"]], "208": ["病机", "血痢虽止而潮热退，然唇燥齿干、睡醒口舌无津、谷食衰少、神疲萎顿，脉濡数不静。濡为阴液不足、津不上承，数为余热未清、虚阳内扰。脉不静者，示阴液未复、脾胃输化无权，生气受戕。此非实热，乃痢后胃阴耗伤、津无上承之候，故主甘寒生津、养胃清热。", ["濡", "数"]], "209": ["病机", "痢下赤白、日夜二十余次、腹痛后重、纳少面黄、苔薄腻，脉沉细而迟。沉主里，细主虚，迟主寒。脾脏受寒，不能统血，血渗大肠；肠中湿浊胶阻不化，故脉沉细迟而证见赤白夹杂。此为太阴虚寒夹湿浊，延久有胀满之虑，故急拟温运太阴、化湿浊，勿骤进兜涩。", ["沉", "细", "迟"]], "210": ["病机", "投温运太阴、化湿浊三帖后，下痢赤白减半，然纳谷衰少、神疲萎顿，脉象沉细。沉主里、细主虚，寒浊虽渐化，而脾胃输运无权未复。脉仍沉细，说明中阳未振、气血不足，故既已获效，更进一筹，继续温运脾胃以复其输化之权，非病退即止。", ["沉", "细"]], "211": ["病机", "经闭一载、营血早亏，下痢赤白三月，腹痛后重、纳少、形瘦骨立、舌光无苔，脉濡细。濡细为阴血亏虚、脾胃大伤之象。素嗜水果、病又不节食，脾土受伤，中焦变化之血渗入大肠，湿浊互阻积而为痢。脉濡细正合营血亏、脾土伤，故拟温运脾胃、寒热并调。", ["濡", "细"]], "212": ["病机", "暑湿挟滞郁于曲肠，煅炼成积，气机窒塞，故腹痛痢下、日夜数十次、赤白相杂、里急后重、纳少、苔腻，脉象沉紧。沉主里、主积滞内阻，紧主痛、主实邪搏结。脉沉紧说明积滞壅塞曲肠、气机不通，属实证，故先宜通因通用，导其积滞。", ["沉", "紧"]], "213": ["病机", "寒暑湿滞互阻肠胃，腹痛下痢次数甚多，胸闷泛恶、不能饮食、苔腻，脉迟。迟主寒、主滞，寒湿内阻、阳气不运，故脉来迟慢。苔腻、胸闷泛恶为湿浊中阻之征。脉迟与寒湿滞相符，非虚寒纯证，乃寒暑湿滞互结，故宜温下法，温通而导其滞。", ["迟"]], "214": ["病机", "痢下纯红、里急后重、腹痛纳少、苔黄，脉濡数。濡主湿、数主热，湿热入营，血渗大肠，肠中滞浊互阻，煅炼而为红积。脉濡数正合湿热蕴结营分之机，故见纯红痢、苔黄。治宜清热导滞、调气行血，气调则后重自除，血行则便红自愈。", ["濡", "数"]], "215": ["预后", "痢下匝月，次数虽少而谷食不进、里热口干、呃逆口糜，脉小数，舌红苔糜腐。小数为阴伤而木火内炽，痢久伤阴，木火冲胃，湿热败浊稽留曲肠，肠膜已腐。脉小数示正虚邪炽、阴液耗竭，危状叠见，恐难挽回，故列于预后不良，勉拟参连开噤聊尽人工。", ["小", "数"]], "216": ["病机", "脉虚弦，虚为中气不足，弦为风邪乘脾。患者年五十阴气自半，肠燥灌肠后风邪从肛门入，风气通肝，肝木乘脾，脾失健运，谷食不化精微而变败浊，风气鼓荡驱败浊下注大肠，故下痢色青如蓝、肛门坠胀。脉虚弦正合中虚风动之机，与舌中剥、谷食减少相应。", ["虚", "弦"]], "217": ["病机", "脉沉细，沉主里、细主虚，示脾阳不足而湿热内蕴。脾有寒则土虚，肠有湿热则痢下赤白；土虚木来侮之，气机窒塞不通，故腹痛绵绵。脉沉细与舌薄黄并见，说明寒热错杂、虚实夹杂，徒用攻剂恐伤脾阳，故宜温运脾阳、苦化湿热。", ["沉", "细"]], "218": ["病机", "脉象沉细，沉为在里，细为阳衰血少。脾寒肠湿，久痢不止，纳少神疲，显系中阳不振、湿热留恋，血痢色紫而腹无痛苦，是虚寒偏重。脉沉细与苔薄黄并见，说明寒湿为本、湿热为标，故拟黄土汤加味温运中阳、清化湿热，冀火土相生、阳升阴固。", ["沉", "细"]], "219": ["病机", "脉数主热，湿热滞郁肠胃，气机窒塞，故腹痛、里急后重、痢下鲜血；热灼肠络则血随便下，苔黄脉数皆热象。纳谷减少为湿热困脾。症势沉重，脉数示热邪鸱张，故拟白头翁汤加味苦寒清热、和中涤肠，以解热毒。", ["数"]], "220": ["病机", "脉弦滑，弦为少阳之脉，滑为痰湿之征。夏伤于暑、秋冒风凉，邪伏少阳，痰湿阻于募原，枢机不利，故先寒栗鼓颔而后壮热头痛，依时而作，汗出而解；胸闷纳少、苔腻布皆痰湿内阻。脉弦滑正合邪伏少阳、痰湿互结之病机。", ["弦", "滑"]], "221": ["病机", "脉象弦滑无力，弦滑为邪伏募原、痰湿内阻之象，无力则示正气已虚。寒热日作匝月，胸脘不舒、纳少神疲，舌苔薄白，皆正虚邪恋、少阳枢机不利之征。脉无力说明不可峻攻，故拟小柴胡汤加味扶正达邪、和胃化痰。", ["弦", "滑", "无", "力"]], "222": ["病机", "脉弦滑而数，弦主少阳，滑主痰湿，数则为热。伏邪痰湿互阻阳明，营卫循序失司，故间日疟先战寒而后壮热，热盛时烦躁胸闷谵语，自午后至夜半得汗而解；苔薄腻而黄、纳少神疲皆痰热内蕴之征。脉弦滑数正合伏邪痰湿化热、阳明热盛之机。", ["弦", "滑", "数"]], "223": ["病机", "脉弦滑不静，弦为少阳枢机不利，滑为痰湿未清，不静示邪势虽减而未靖。服桂枝白虎汤后寒热减大半、谵语止，惟胸闷纳少、神疲乏力、夜不安寐，苔薄腻，是伏邪痰湿未楚、胃不和则卧不安。脉象仍弦滑不静，说明前法既效，率由旧章再进。", ["弦", "滑"]], "224": ["病机", "脉沉弦，沉主里主水，弦主饮主痛。久疟伤脾，脾阳不运，浊湿凝聚募原，三焦输化无权，故脉见沉弦。大腹时满、纳少便溏、舌苔薄腻，皆脾阳不运、湿浊内停之症。此脉此症，说明病机为太阴脾阳不振，湿浊内蕴，枢机不利。", ["沉", "弦"]], "225": ["病机", "脉转弦滑，弦主少阳枢机不利，滑主痰湿。前诊脉沉弦，今转弦滑，是太阴之邪欲还出阳经之佳象。胸闷纳少、腑行不实、小溲短少，乃痰湿留恋中焦，脾胃运化失职所致。脉症合参，病机为痰湿中阻，枢机不利，脾胃运化失职。", ["弦", "滑"]], "226": ["病机", "脉沉弦无力，沉主里，弦主疟邪，无力为正气虚。三日疟延半载，纳少面黄，正气已虚，邪伏三阴，营卫循序失司，故脉沉弦无力。此脉说明正虚邪伏，缠绵之症，治宜扶正达邪，用阳和阴。", ["沉", "弦", "无", "力"]], "227": ["病机", "脉弦滑而数，弦主少阳，滑主痰，数主热。伏邪久蕴，消耗阴液，少阴之阴已伤，阳明之邪不解，故临晚身热、咳呛咯痰不爽、纳少形瘦、苔薄黄。脉症合参，病机为阴伤邪恋，痰热内蕴，久延成痨疟。", ["弦", "滑", "数"]], "228": ["病机", "脉沉细而弦，沉细为阳虚气弱，弦主疟邪。但寒不热，名曰牡疟，汗多淋漓，纳谷减少，舌中剥边薄白而腻，是阳虚失于外护，不能托邪外出，痰湿困于中宫，脾胃运化失职。高年患此，脉症示正虚邪伏，痰湿内困。", ["沉", "细", "弦"]], "229": ["病机", "脉沉细而弦，沉细为阳虚气弱，弦主邪伏募原。牡疟寒热已减而汗多淋漓、纳少胸闷，舌中剥边薄腻，是阳虚气弱，不能托邪外出，痰湿逗留募原，皮毛开而经隧闭。脉症相应，病机仍属正虚邪恋，痰湿内阻。", ["沉", "细", "弦"]], "230": ["病机", "脉弦滑，弦主少阳半表半里，滑主痰湿。伏邪痰湿逗留募原，营卫失其常度，邪与营争则热，与卫争则寒，寒热日作，胸闷泛恶，舌苔薄腻。脉症合参，病机为邪在少阳，湿在阳明，痰湿内蕴，营卫不和。", ["弦", "滑"]], "231": ["病机", "脉郁滑而数，滑主痰热，数主热盛，郁为邪遏不宣。风温疫疠之邪引动肝胆之火，蕴袭肺胃两经，发为喉痧，痧布隐隐，身热，咽喉肿红焮痛，内关白腐，舌苔薄黄。脉症示肺胃热毒壅盛，邪势鸱张，有增剧之虑。", ["滑", "数"]], "232": ["病机", "脉洪数，为伏温化热，蕴蒸阳明，由气入营之象。洪为热盛气分，数为热象，热邪销烁阴液，厥少之火乘势上亢，故见身灼热不退、咽喉肿痛白腐、舌绛。脉洪数反映气营两燔，热毒炽盛，症势沉重，急宜气血双清。", ["洪", "数"]], "233": ["病机", "脉沉数，沉主里，数主热，为温邪伏热稽留肺胃两经，血凝毒滞，肝胆火炽之征。痧回而身热不退，项颈漫肿疼痛，咽喉焮肿，内关白腐，舌薄黄，皆热毒蕴结于里之候。脉沉数说明邪热内伏，非在表也，故宜清肺胃伏热、解疫疠蕴毒。", ["沉", "数"]], "234": ["病机", "脉洪数，为温邪疫疠郁而化火，肺胃被熏蒸，心肝之火内炽之象。洪为热盛，数为热急，热毒上攻则白喉腐烂焮痛、妨于咽饮，壮热烦躁、舌红苔黄皆热盛之征。脉洪数主热淫于内，故治以咸寒解毒、清温泄热。", ["洪", "数"]], "235": ["病机", "脉浮滑而数，浮主邪在皮毛肌肉，滑主痰湿，数主热，为时气引动伏邪，蕴袭肺胃两经之征。痧点隐隐布而不透，形寒发热，胸闷泛恶，舌苔薄黄，皆邪郁阳明不得外达之候。脉浮滑数说明邪势鸱张，正在表分，故宜辛凉清解。", ["浮", "滑", "数"]], "236": ["病机", "脉濡滑，濡主湿，滑主痰，为痧后肺有伏邪、痰气壅塞，脾有湿热、不能健运之象。积湿生水，泛滥横溢，故面目虚浮、腹膨肢肿、咳嗽气逆、苔薄腻。脉濡滑反映湿痰内盛，水气太过，势成肿胀重症，宜肃运分消、顺气化痰。", ["濡", "滑"]], "237": ["病机", "脉数苔黄，数为热，黄为热象，为痧后余邪痰热未楚，肺胃两病之征。身热无汗、咳嗽气逆、口干欲饮，皆无形伏温蕴蒸阳明、有形痰热逗留肺络之候。脉数说明热邪内蕴，症势沉重，故拟清解伏温而化痰热。", ["数"]], "238": ["预后", "脉数，为痧火蕴蒸肺胃，肺津不布，凝滞成痰，痰热留恋肺胃之象。肺叶已损，气机不能接续，故气喘鼻煽、喉有痰声；咽喉为肺胃门户，热灼则内关白腐、音声不扬。脉数反映热毒炽盛，症势危笃，勉拟清温解毒化痰，聊尽人工。", ["数"]], "239": ["病机", "脉象滑数，滑主痰，数主热，为痧后肺胃阴伤，伏邪留恋，津液灼而为痰之征。身热不退、咳嗽咽痛、口渴欲饮、舌绛苔黄，皆伏热蕴蒸肺胃、肺失清肃、胃失降和之候。脉滑数说明痰热内蕴，故拟竹叶石膏汤加味清阳明、解蕴热。", ["滑", "数"]], "240": ["病机", "脉数主邪正交争、痰湿化热。原文谓痧后复感外邪，痰滞内阻，水湿不化，太阴阳明为病，遍体浮肿、寒热甚壮、便溏泛恶，苔腻脉数，正合氤氲外邪与黏腻痰滞交阻肺胃，肺失下降、脾弱不运，水湿聚而灌浸腠理、泛滥横溢，三焦决渎无权，故脉数示邪郁化热、病势危险。", ["数"]], "241": ["病机", "尺部沉细为阳气早亏、肾气不足之征；寸关弦紧而滑，乃贼风入中经腧、营卫痹塞，风性上升挟痰湿阻于廉泉、堵塞神明。原文以阴霾弥漫、阳不用事释之，舌强不语、神识似昧、右肢不用皆由阳气不运、痰湿蒙窍，幸小溲未遗，肾气尚固，未至脱象。", ["沉", "细", "弦", "紧"]], "242": ["病机", "二诊神识稍清而尺部沉细仍在，寸关弦紧稍和，说明阳气本虚、藩篱不固，贼风中经、经腧痹塞未解，痰湿稽留，宗气不得分布，故右手足不用；肾脉络舌本、脾脉络舌旁，痰阻心脾之络则舌强难言、灵机堵塞。脉象示正虚邪恋、痰浊未化。", ["沉", "细", "弦", "紧"]], "243": ["病机", "脉弦紧渐和而尺部沉细，示经腑邪风稍退、阳气有流行之机，然肾阳早亏未复，宗气不得分布，故右手足依然不用、腑气六七日不行。原文谓腑中浊垢须阳气通而后下达，经腑邪风必正气旺始托之外出，脉象正反映正虚邪滞、通降无力之病机。", ["弦", "紧", "沉", "细"]], "244": ["病机", "腑气已通、神识已清而脉弦紧转和、尺部沉细，说明邪风渐退而阳气衰弱之体未复。原文谓风为百病之长，阳气旺一分则邪风去一分，湿痰盘踞亦藉阳气充足始能克化，故舌强、右肢不用仍存；脉象示正虚为本、痰湿稽留为标，治当助阳祛风、化痰通络。", ["弦", "紧", "沉", "细"]], "245": ["病机", "尺部沉弱为高年气阴早衰、水亏不能涵木；寸关弦滑而数、按之而劲，乃内风上旋、挟素蕴痰热蒙蔽清窍、堵塞神明。原文引《金匮》风中于经、风中于腑之说，舌强不语、人事不省、左肢不用，正属中经兼中腑重症，脉象示阴虚阳亢、痰热内闭之机。", ["沉", "弱", "弦", "滑"]], "246": ["病机", "二诊人事渐知而尺部细弱、寸关弦滑而数，舌灰红，示高年营阴亏耗、风自内起未平。原文谓风扰于胃，胃为水谷之海，津液变为痰涎，上阻清窍、横窜经腧，故舌强不语、左肢不用；本症阴虚，风烛堪虑，脉象示阴亏为本、痰热风阳为标。", ["细", "弱", "弦", "滑"]], "247": ["病机", "脉弦数较静、尺部细弱，示内风渐平而阴血难复。原文谓津液被火炼而为痰，痰为火之标、火为痰之本，火不靖则痰不化，阴不充则火不靖，经腧枯涩如沟渠无水以贯通，故舌强语蹇、左肢不用；脉象示风火稍息、阴血亏虚未复之病机。", ["弦", "数", "细", "弱"]], "248": ["病机", "脉弦小而数，弦为肝风，小为阴血不足，数为痰热内扰。左手足不用，乃津液亏耗，筋无血养，如树木偏枯无滋液灌溉。此脉象反映下焦阴亏、上焦热蕴、中焦痰滞，本虚标实，故治以滋下焦之阴、清上焦之热、化中焦之痰、活经腧之血。", ["弦", "小", "数"]], "249": ["病机", "尺部沉细，寸关濡滑，沉细为气血两亏，濡滑为痰湿内蕴。年逾七旬，气血亏虚，邪风入中经腧，营卫痹塞，痰阻舌根，故舌强言蹇、手足不用。此脉示本虚标实，治宜益气养血、助阳化痰、兼通络道，冀阳生阴长、气旺血行。", ["沉", "细", "濡", "滑"]], "250": ["病机", "尺部细小，左寸关弦小而数，右寸关虚滑。细小为阴血大亏，弦数为内风上扰、痰热阻络，虚滑为气虚痰盛。舌光红、神识时昧、小溲不固，皆阴亏风动、痰热堵塞灵窍之中风重症。急拟滋液熄风、清神涤痰，以冀挽救。", ["细", "小", "弦", "数"]], "251": ["病机", "脉虚弦而滑，虚为气虚，弦为风动，滑为痰盛。体丰气虚，邪风入络，痰阻舌根，故舌强言蹇、右手足麻木无力。此中风初步之重症，本虚标实，急拟益气去风、涤痰通络，以遏病势。", ["虚", "弦", "滑"]], "252": ["预后", "脉伏，乃真阳飞越、气血涣散之象。陡然跌仆、不省人事、小溲自遗、喉中痰声漉漉、汗多身热肢冷，此本实先拨，枢纽不交，虽曰中脏，实暴脱也。脉伏示阳气不能外达，生机欲绝，故勉拟一方，聊尽人工，预后极差。", ["伏"]], "253": ["病机", "左脉细弱，右弦滑。细弱为气阴本亏，弦滑为虚风内动、痰浊上阻。舌强言蹇、手足麻木，乃风挟痰浊上阻廉泉、横窜络道，营卫痹塞。经云“邪之所凑，其气必虚”，虚处受邪，其病则实，故拟益气熄风、化痰通络。", ["细", "弱", "弦", "滑"]], "254": ["病机", "右脉细弱，左弦滑。细弱为心肾阴亏，弦滑为虚风内动、痰浊上阻。舌强言蹇、肢麻艰动、舌光绛中后干腻，乃阴亏风动，挟痰浊上阻廉泉，属喑痱重症。再仿地黄饮子意，滋肾阴、熄虚风、化痰浊。", ["细", "弱", "弦", "滑"]], "255": ["治法", "脉症依然，舌强言艰，麻属气虚，木属湿痰。肾阴不足为本，虚风痰热为标，标急于本。养阴助湿，化痰伤阴，顾此失彼。故再宜涤痰通络为主，养正育阴佐之，为急标缓本、寓守于攻之策。", []], "256": ["病机", "脉左细滑，右濡数，细滑为阴血不足而痰浊内蕴，濡数为气阴两虚兼有湿热。舌中剥、苔薄腻，剥处示胃阴伤，腻处示痰湿未化。诸恙平和乃药后痰湿渐化、气阴未复之象，故仍宗养正涤痰、通利节络之法，脉象反映正虚与痰浊并存之病机。", ["细", "滑", "濡", "数"]], "257": ["病机", "脉象细滑，细为阴血不足，滑为痰浊内盛。舌强言语蹇涩已减而左手足麻木依然，苔薄腻，说明痰浊仍阻络道、阴血未充。脉细滑与舌苔薄腻相应，示涤痰通络已获小效而痰湿未尽，故仍拟涤痰通络为法，病机重点在痰阻络脉兼阴血亏虚。", ["细", "滑"]], "258": ["病机", "脉弦小而滑，尺部无神。弦为肝风，小为气阴两耗，滑为湿痰壅盛，尺部无神示肾气已衰。体丰气本虚、湿胜痰必盛，虚风鼓动湿痰上阻廉泉，故舌强不语、神识时昧。脉象揭示气阴亏虚、肝风挟痰上扰之危重病机，症势颇殆。", ["弦", "小", "滑"]], "259": ["病机", "脉弦小而数，弦为肝风，小为阴分大伤，数为火热内炽。舌绛、咬牙嚼齿、牙缝渗血、呃逆频仍，皆阴伤火旺、肝风鼓火内煽之征。痰热阻于廉泉则舌强言蹇，肺胃肃降不行则呃逆。脉象示阴亏火旺、风火痰热交炽之险候，故云恙势正在险关。", ["弦", "小", "数"]], "260": ["病机", "脉弦小而滑，弦主肝风，小示正气不足，滑为湿痰内盛。外风引动内风，挟湿痰阻于廉泉则舌强不能言语，横窜络道则右半身不遂。苔薄腻与滑脉相应，证实痰湿为患。脉象反映风痰阻络、本虚标实之类中重症，故拟熄风涤痰、和营通络。", ["弦", "小", "滑"]], "261": ["病机", "脉虚弦而滑，虚为气阴本亏，弦为肝风内动，滑为湿痰壅盛。外风引动内风，挟湿痰上阻廉泉则舌强不语，横窜络道则右手足不用，蒙蔽清窍则神识时昧。舌红苔薄腻、口干欲饮，示阴亏而痰湿未化。脉象示正虚风动、痰浊阻络之类中重症。", ["虚", "弦", "滑"]], "262": ["病机", "左尺沉濡示少阴水亏，寸关弦滑而数示厥阳独亢、痰浊内蕴化热，右寸郁涩、右关软滑示肺气郁滞、脾运不健。水不涵木则肝阳上亢，引动中焦痰浊上蒙清窍，堵塞神明出入之路，故神机不灵、或类癫或类狂。脉象揭示肾亏肝亢、痰浊蒙窍之病机。", ["沉", "濡", "弦", "滑"]], "263": ["病机", "尺部沉濡示肾阴亏虚、水不涵木，脉数示火热内炽。心肝脾三脏阴伤，厥阴独亢，脾弱不能为胃行津液，水谷之湿生痰，阳升于上挟痰浊蒙蔽清窍，故神呆不语类癫、时或多言类狂。脉象反映阴亏火旺、顽痰积热阻于上中二焦之病机，痰火为患。", ["沉", "濡", "数"]], "264": ["病机", "脉寸略小提示心阳不足，右关流利为痰浊内郁之象。原文谓“顽痰郁闭心包，依然不化”，痰浊梗而不化，阻滞神明，故见神呆、语无次序。其病机为谋虑过度，气结津凝，脾不散精，悉变为痰，涎渍于肺则咳，沃于心包则神机堵塞。", ["小", "滑"]], "265": ["病机", "脉弦滑带数，弦主肝旺，滑主痰，数主热。原文谓“痰热蒙蔽清窍，神不守舍”，痰火上炎则彻夜不寐，痰蒙心则多疑妄闻。其病机为肾阴不足，心肝火旺，离坎不交，痰热踞舍空之处，扰乱神明。", ["弦", "滑", "数"]], "266": ["病机", "脉象软弱，右尺虚数，软弱为三阴虚损之征，虚数为君相火动之象。原文谓“心肾之阴不足，君相之火有余”，故见惊悸惕息、遗泄频频、盗汗甚多。汗为心液，虚阳迫津外泄，脉证合参，主阴虚火旺、封藏失职。", ["软", "弱", "虚", "数"]], "267": ["病机", "脉弦小而滑，原文自释“弦乃肝旺，小属肾虚，滑则有痰之明证”。心营肾水交亏，神机不灵，作强无权，故心悸、耳鸣、腰痛、健忘胆怯；痰热乘虚内生，蔽阻清窍。脉证参合，或成损，或为癫，主心肾亏虚、痰热内扰。", ["弦", "小", "滑"]], "268": ["病机", "脉濡滑无力，濡主虚，滑主痰湿，无力为气血不足。原文谓“卫虚失于外护，营虚失于内守，脾弱土不生金”，故寒热自汗盗汗、纳少便溏、咳嗽形瘦。此产后蓐劳，营卫俱虚，脾肺两弱，虚阳外泄之病机。", ["濡", "滑", "无", "力"]], "269": ["病机", "左脉细弱，右脉濡迟，细弱为阴血不足，濡迟为阳气式微。原文谓“阳陷入阴，命火式微”，前服滋阴太过，中土受戕，清气不升，故便溏纳少、腹痛隐隐。脉诀云“阳陷入阴精血弱”，主脾肾阳虚、中气下陷之机。", ["细", "弱", "濡", "迟"]], "270": ["病机", "脉来濡细，濡主脾虚湿困，细主阴血不足。原文谓“幸无数象”，说明虚火未炽。脾弱土不生金，肺虚灌溉无权，故咳嗽痰多、纳谷衰少、形瘦色萎、舌光无苔。此脾肺两虚、气阴不足之病机，仍当建立中气。", ["濡", "细"]], "271": ["病机", "脉象虚迟，虚主正气不足，迟主阳气衰微。原文谓“劳役太过，脾胃两伤，营卫循序失常”，故寒热似疟、形瘦色萎、食减神疲。舌光有津，势将入于虚损。此劳倦伤脾、营卫不和、阳气虚馁之病机，治以甘温补中。", ["虚", "迟"]], "272": ["病机", "尺部细弱，为肾阴亏于下；寸关虚弦，为阳升于上、心肝不宁。原文以诵读劳心、房帏劳肾立论，阴虚于下则阳不潜藏，故见头眩耳鸣、心悸少寐、遗泄频频；细弱主精血不足，虚弦主虚阳上扰，正合育阴潜阳、交通心肾之法。", ["细", "弱", "虚", "弦"]], "273": ["病机", "濡小而数，濡小为气阴两虚、脾胃生气受戕，数为阴亏生内热。原文入夜潮热两月、纳少形瘦、神疲乏力、舌光绛，正是三阴亏耗、虚热内扰之象。脉不洪大而反濡小，说明热由虚生而非实火，故虑成损怯。", ["濡", "小", "数"]], "274": ["病机", "濡细为脾胃虚弱、气血不足之脉。原文虚寒虚热、寒多热少、口唾白沫、纳减便溏、苔薄腻，皆脾弱胃虚、卫阳不入于阴所致。脉濡细而不数不弦，说明虚多而热少，故以黄耆建中合二加龙骨汤温建中气，而虑其成虚劳。", ["濡", "细"]], "275": ["病机", "左虚弦为抑郁气阻、肝木失和，右濡涩为土受木克、胃乏生化而血瘀。原文情志不适、经闭一载、纳少形瘦、临晚寒热、咳嗽痰沫，正是二阳之病发心脾、血不下注冲任之候。虚弦主肝郁而虚，濡涩主脾弱血滞，故复方图治。", ["虚", "弦", "濡", "涩"]], "276": ["病机", "左弦为木火偏亢，右涩为脾胃生化无权、血室干枯。原文经闭纳少、舌光无苔、咳嗽依然，说明阴血枯涸，木火刑金，土不生金。弦涩并见，非实邪壅滞，乃虚中夹郁、血少而滞，故须怡情适怀，培土生金、养血通经，非旦夕可图。", ["弦", "涩"]], "277": ["病机", "濡数为阴虚而燥邪化火之脉。原文仲秋燥邪咳嗽至冬不愈，咽痛干燥、蒂丁下坠、内热纳少、舌红苔黄，皆燥火刑肺耗肾、水不上潮、浮火炎炎所致。脉濡数而幸不洪大，说明火虽浮而未成实热，故虑其吐血入虚损，急拟清燥润肺降火。", ["濡", "数"]], "278": ["病机", "弦为劳、数为病进，大则阴不敛阳。原文吐血屡发、咳嗽有年、咽痛失音、形瘦骨立、潮热口燥，正是阴液枯涸、木火犯肺、肺叶已损之金破不鸣。弦大而数，说明虚火鸱张、病势日进，故断为肺痨显然，仅勉拟壮水柔肝、清养肺气。", ["弦", "大", "数"]], "279": ["病机", "脉细神疲，为心虚血少之征。原文以肺虚咳嗽寒热、脾虚纳少便溏、心虚脉细神疲、肾虚遗泄、肝虚头眩，五虚俱见立论。细脉主气血不足，与神疲并见，说明心脾两虚、五脏俱损，故非易图功，惟宜培土生金、益肾养肝，待泄泻止、谷食增方可言治。", ["细"]], "280": ["病机", "脉象尺部软弱、寸关虚小，为气分不足、肾阳亦亏之征。尺部候肾，软弱示肾阳亏虚，下失封藏之固；寸关虚小示中气不足，中无砥柱之权。故见小溲清长匝月，乃肾阳不固、气化无权所致。", ["弱", "虚", "小"]], "281": ["预后", "脉象细弦而数，细为阴血亏虚，弦为劳损之象，数则病势进展。原文谓“弦则为劳，数则病进”，劳已入损，故阴虚内热、阳虚外寒、肺虚咳嗽、脾虚形瘦诸症丛生。脉症合参，恐难完璧，预后堪忧。", ["细", "弦", "数"]], "282": ["病机", "脉弦小，弦主肝郁气滞，小主正气不足。心体亏而心阳亢，不能下交于肾，加之湿痰中阻，胃因不和，胃不和则卧不安。脉弦小正合心肾不交、湿痰内阻之病机，故不寐已久，时轻时剧。", ["弦", "小"]], "283": ["病机", "脉象虚弦而滑，虚为气阴两亏，弦为肝阳偏亢，滑为痰浊内蕴。高年气阴不足，肝阳挟痰浊上蒙清空，故健忘少寐、神疲肢倦。脉虚弦滑，苔薄腻，显系虚中夹实之候，故曰最难著手。", ["虚", "弦", "滑"]], "284": ["病机", "脉象软小而数，软小为阴虚难复、正气不足，数为肝火易升、虚热内扰。阴虚不能涵阳，肝火易升，宗气跳跃，夜梦纷纭。脉软小数，正合阴虚火旺、心肾不交之病机，故拟育阴潜阳、交通心肾。", ["软", "小", "数"]], "285": ["病机", "脉沉似伏，非寒厥之脉，乃痰气闭塞、脉道不利所致。操劳过度，肝阳化风上扰，痰热蒙蔽清窍，故神糊不语、牙关紧闭、四肢抽搐。肝风入筋，痰气闭塞，脉道为之不利，故脉沉伏。此为痉厥重症，当柔肝熄风、清神涤痰。", ["沉", "伏"]], "286": ["病机", "脉弦数，弦为肝风内动，数为阳热亢盛。阴亏于下，阳浮于上，风阳上扰巅顶，痰湿内阻，胃失降和，故耳鸣失聪、两目红赤、视物模糊、头眩泛恶。舌红苔黄，脉弦数，显系阴亏阳浮、风痰上扰之危象。", ["弦", "数"]], "287": ["病机", "脉沉伏，肢冷，非寒厥也，乃盛怒伤肝、气机窒塞所致。怒则气上，气郁化火扰于膻中，故心胸大痛、喜笑不休；气机窒塞，脉道不利，故脉伏肢冷。种种见证皆由肝病为患，木郁则达之，宜疏肝解郁理气，若误为寒厥则殆矣。", ["沉", "伏"]], "288": ["病机", "原文未识出脉名，仅述左胁痛、呼吸尤甚。左胁为肝之分野，肝气挟痰瘀入络，气机不得流通，故痛偏左而呼吸牵动更甚。病机在肝络气滞、痰瘀互结，主胁痛，与呼吸不利相应，治宜宣肺疏肝、化痰瘀通络。", []], "289": ["主病", "脉浮苔白，浮主表、主风邪外袭。风邪客于阳位，袭入太阳之经，故头脉胀痛、痛引后脑连及项背，恶风鼻流清涕、胸闷纳少。脉浮与表证相应，苔白示未化热，治以辛温解散，属太阳风邪主病。", ["浮"]], "290": ["主病", "脉浮苔黄，头痛且胀、痛引头额、畏风鼻塞。浮脉主风邪在表，风为阳邪客于阳明之经，故痛引额部；苔黄已见化热之象。脉浮与畏风鼻塞表症相应，主阳明风邪，治以辛散凉清。", ["浮"]], "291": ["病机", "脉浮数、苔黄，头额掣痛引左耳、夜半尤甚。浮为风邪在表，数为热，风邪化热引动肝胆之火上犯空窍，故掣痛夜甚。阴分本亏为其本，浮数之脉正合风热与肝胆火升，主头痛，治拟辛凉解散、清泄厥少。", ["浮", "数"]], "292": ["病机", "脉弦数，头痛如劈、筋脉掣起、痛连目珠、舌红绛。弦主肝、主筋，数主火，肝阳化火，上扰清空，故筋脉掣痛连目。脉弦数与舌红绛相应，说明火盛风动，治当壮水柔肝熄风火，并戒过用风药助火。", ["弦", "数"]], "293": ["病机", "脉弦细、舌光无苔，产后血虚，厥阳上扰，头脑空痛、目花眩晕。细为血虚，弦为肝阳不潜，血虚不能涵木则厥阳上扰。脉弦细与舌光无苔之阴血亏相应，主产后血虚头痛眩晕，治当养血柔肝潜阳。", ["弦", "细"]], "294": ["病机", "脉弦滑、苔薄腻，头眩眼花、泛泛呕吐、纳谷减少。弦主肝阳上僭，滑主湿痰内阻，肝阴不足而阳升，痰湿阻胃失降，故眩而呕吐纳少。脉弦滑与苔腻呕吐相应，正合无痰不作眩之说，治当柔肝潜阳、和胃化痰。", ["弦", "滑"]], "295": ["主病", "脉浮滑、苔白腻，形寒饮冷伤肺，畏寒咳嗽、头胀骨楚、纳少泛恶。浮主邪在表，滑主痰湿内蕴，寒饮伤肺则咳，表邪未解则畏寒头胀骨楚。脉浮滑与苔白腻相应，主外寒夹痰湿之咳，治以辛温散邪。", ["浮", "滑"]], "296": ["病机", "脉浮为邪在表，滑主痰湿内盛。原文“邪风犯肺，痰湿侵脾”，风邪外袭故脉浮，痰湿壅盛故脉滑；恶寒咳嗽、头痛且胀为风邪束表，胸闷泛恶、苔腻为痰湿中阻。浮滑并见，正合外风与内湿相合之病机，故宜辛散肺邪兼化痰湿。", ["浮", "滑"]], "297": ["病机", "脉浮缓而滑，浮为风邪在表，缓为营卫不和、卫阳不固，滑主痰湿。原文“劳力伤阳，卫失外护，风邪乘隙入于肺俞”，故恶风多汗、遍体酸楚；咳嗽痰多、纳少神疲、苔薄白，皆脾肺气虚痰湿内蕴之象。脉症合参，属劳风伤卫、痰湿恋肺之病机。", ["浮", "缓", "滑"]], "298": ["病机", "脉浮滑而数，浮主风温燥邪上袭，滑主痰，数主热。原文“营阴早亏，风温燥邪，上袭于肺”，故咳呛咯痰不利、咽痛干燥、畏风头胀；舌红苔粉白而腻，为燥邪初袭、痰热未甚。浮滑数并见，示风燥外袭、肺失清润而渐有化热之势，故治以辛散凉润清上焦。", ["浮", "滑", "数"]], "299": ["病机", "复诊脉仍浮滑而数，浮示余邪未尽，滑数为痰热内蕴。原文“风燥化热生痰，交阻肺络，阴液暗伤，津少上承”，故恶风头胀虽去而咳呛不止、咽痛口渴，苔转红绛为热伤阴液之征。脉数不退，说明燥热未清、痰热尚恋肺络，故拟甘凉生津、清燥润肺。", ["浮", "滑", "数"]], "300": ["病机", "脉濡滑而数，濡主阴伤湿恋，滑主痰，数主热。原文“初起风燥袭肺，继则燥热伤阴，肺金不能输化，津液被火炼而为稠痰”，故咳呛两月、音声不扬、咽喉燥痒、内热头眩，舌红苔薄黄。濡滑数并见，示燥热伤阴、痰热阻肺之病机，久延有成痨之虑。", ["濡", "滑", "数"]], "301": ["病机", "脉象滑数，滑主痰，数主热。原文“肺素有热，风寒外束，腠理闭塞”，邪郁化热，热蒸于肺，故恶寒发热无汗、咳呛气急、喉痛音哑、痰声漉漉、烦躁不安，舌边红苔薄腻黄。滑数之脉正示痰火内亢、肺炎叶举，清肃失降；前服降气通腑反增，邪不外达而内逼，症已入危。", ["滑", "数"]], "302": ["病机", "二诊脉滑数不静，滑主痰，数主火，不静示痰火尚炽未平。原文“外束之邪，已从外达，痰火尚炽，肺炎叶举，清肃之令，仍未下行”，故寒热退而咳呛咯痰不出、音哑咽痛、妨于咽饮，舌红苔黄。脉象不静，说明痰火仍壅肺络，故仍拟轻开上焦、清肺化痰。", ["滑", "数"]], "303": ["妇人", "脉象滑数，滑为胎孕之常脉，数主火。原文“怀麟七月，手太阴司胎，胎火迫肺，燥邪乘之”，胎火循经上迫于肺，复感燥邪，故咳呛气逆、口渴苔黄。滑数并见，示胎火与燥邪交炽于肺，咳甚则震动胎元，故虑其殒胎，属妊娠胎火迫肺之候。", ["滑", "数"]], "304": ["病机", "脉濡滑而数，濡主湿、滑主痰、数主热，合参嗜酒生湿、湿郁生热之因，知湿热熏蒸于肺，肺络损伤，故咳呛两月、痰内带红、膺肋牵痛；舌边红、苔薄黄亦为湿热之征。脉症相合，病机在肺经湿热伤络，故以清肺淡渗治之。", ["濡", "滑", "数"]], "305": ["病机", "左弦右滑，弦主气机不畅、滑主痰湿内蕴。平素嗜茶生湿，湿郁生痰逗留肺经，故咳呛痰多、气逆难卧；纳减、苔薄腻为脾湿不运之象。左弦右滑正示肝气偏旺而脾肺痰湿壅滞，清肺无益，当理脾和胃以化痰湿，治病求本。", ["弦", "滑"]], "306": ["病机", "脉滑主痰主积，此孩食积之火犯肺，乳滞生痰逗留肺胃，故趸咳匝月、嗽甚泛吐、苔薄腻。滑脉应痰滞内壅，非外感之象，故治法涤痰肃肺，使痰滞去则肺胃自安，与脉滑相符。", ["滑"]], "307": ["病机", "脉滑数，滑主痰滞、数主积热。食滞积热上迫于肺，故咳嗽匝月、五更尤甚、苔腻黄。五更阳气升发，积热随之上迫，咳乃加剧；滑数之脉正应痰热内蕴，故宜清肺化痰，使积滞积热下达而肺气自清。", ["滑", "数"]], "308": ["病机", "两寸脉数，寸候心肺，数主火。操烦过度、五志化火，火刑于肺，故咳呛痰不爽、喉中介介如梗、苔黄，内经谓之心咳。数脉见于两寸，正示心火烁金无疑，故拟滋少阴之阴以制炎上之火，火降水升则肺清。", ["数"]], "309": ["预后", "尺弱寸关濡数，尺候肾、寸关候肺肝。水亏不能涵木，木扣金鸡，故咳呛数月、痰内带红、形色不充；尺弱为肾水不足之本，寸关濡数为肺肝虚热之标。脉症合参，势虑入于肺痨一门，故壮水柔肝、清养肺气，属防其深入之预后判断。", ["弱", "濡", "数"]], "310": ["预后", "脉象细弱，细主阴血不足、弱主气虚。壮年劳心耗精，肾虚冲气上升，肺虚痰热留恋，气升咳嗽数月。脉细弱而不洪数、亦未吐血，示虚象虽著而火势未炽，尚非危候，故亟宜清上实下，兼节劳节欲，可望渐痊，属预后之论。", ["细", "弱"]], "311": ["病机", "脉象濡滑，濡主气虚湿滞、滑主痰。劳伤卫阳不固，风邪易触，肺先受之，故咳嗽数月、汗多怯冷、形瘦神疲；舌淡白无苔为阳气不足之征。濡滑之脉示虚而兼痰湿，势成肺痨，故宗劳者温之、虚者补之，用黄耆建中汤加减。", ["濡", "滑"]], "312": ["病机", "原文言“心虚则脉细”，并列“五虚俱见”，脉细为心虚之征，然五脏虚损皆可致脉细。此案阳虚外寒、阴虚内热、肺虚咳嗽、脾虚便溏、心虚脉细，五虚并见，已入损门，脉细反映气血不足、脏腑虚损之病机，尤以心脾为要，故治当调养中土。", ["细"]], "313": ["病机", "产后两月，百脉俱虚，脉象虚细，舌淡苔白，为气血阴阳俱虚之候。前医叠进养阴润肺，反致纳少便泄，阴损及阳，肺伤及脾。脉虚细正合“下损过胃，上损过脾”之难治例，说明虚损已深，脾阳亦伤，故以黄耆建中汤合二加龙骨汤温建中阳、潜镇浮阳。", ["虚", "细"]], "314": ["病机", "脉弦小而数，舌红苔黄，旧有肝气脘痛，痛止后咳嗽胁痛、难于左卧，显系气郁化火，肝升太过，上迫于肺，肺失清肃。弦为肝旺，小为阴伤，数为火炽，脉象反映木火刑金、痰热内蕴之病机，故虑其失血，治以柔肝清肺、化痰热。", ["弦", "小", "数"]], "315": ["病机", "失血后咳呛、手足心热、咽干舌燥，脉细数不静，为血去阴伤，木火刑金，津液被火炼而为痰。细主阴亏，数主火旺，不静者虚火内扰之象。脉症合参，病机为阴虚火旺、肺失清润，颇虑延入肺痨，故拟益肾柔肝、清养肺气。", ["细", "数"]], "316": ["预后", "去秋失血盈盏成盆，继则咳呛、内热口干、咽痛失音、形瘦骨立，脉象细数，为脏阴营液俱耗，木火犯肺，肺叶已损，金破不鸣。细数脉示阴亏火旺，损怯已著，故曰难许完璧，勉拟滋养金水而制浮火，佐培中土以延日。", ["细", "数"]], "317": ["病机", "孀居多年，情怀抑郁，五志化火，上刑肺金，致咳嗽气逆、子丑更甚。脉左弦细右濡数，左弦细为肝郁阴伤，右濡数为脾虚有热、痰湿内蕴。脉象反映木火炎威无制、中土尚有生化之机，故治以养阴血清肝火、培中土生肺金。", ["弦", "细", "濡", "数"]], "318": ["病机", "脉左弦细右虚数，舌光，夜卧气冲咳嗽，行走喘促更甚，为下元根本已拨，肾少摄纳，肝火挟冲气上逆于肺，肺失肃降。左弦细乃肝阴不足、肝阳偏亢，右虚数为肺脾虚而虚热上浮。脉症合参，病机为下虚上实、冲气上逆，势恐由喘而肿。", ["弦", "细", "虚", "数"]], "319": ["病机", "眩晕有年，盗汗，咳嗽气短，行走喘促，脉左弦细右虚数，此虚阳上冒，肝肾根蒂不固，冲脉震动则诸脉俱逆。左弦细为肝肾阴虚、阳不潜藏，右虚数为脾肺气虚而虚阳浮越。前医误用三子养亲等泄气伤阴之品，施于阴阳两损之质，徒增其害。", ["弦", "细", "虚", "数"]], "320": ["病机", "脉弦滑，弦主饮邪、滑主痰湿，新寒引动痰饮，渍之于肺，肺失肃降，故咳嗽气急又发；形寒怯冷为外寒束表，苔薄腻为痰湿内蕴。脉症合参，病机为寒饮射肺、痰湿内阻，治当温药和之。", ["弦", "滑"]], "321": ["病机", "脉浮弦而滑，浮主表寒外束，弦主饮邪内聚，滑主痰湿壅盛。暴寒外束，痰饮内聚，支塞于肺，肃降失司，故气喘咳嗽大发、日夜不能平卧；形寒怯冷、苔白腻皆寒饮之征。病机为外寒内饮、肺气上逆。", ["浮", "弦", "滑"]], "322": ["病机", "脉弦滑，弦为饮邪，滑为痰湿。服小青龙后日中大减，夜则依然，因夜为阴盛之时，饮邪窃踞阳位，阻塞气机，肺胃下降之令失司，故咳喘夜甚、纳少泛恶。脉象未变，说明饮邪仍盛，病机仍属寒饮内阻、肺胃气逆。", ["弦", "滑"]], "323": ["病机", "脉象沉细，沉主里、细主虚，为脾肾阳气式微之象。阳虚不能化水，水饮泛滥横溢，上激于肺则喘，灌溉肌腠则肿，凝聚膜原则胀；腑行溏薄、谷食衰少、舌苔淡白皆阳气不到、水湿盘踞之征。病机为脾肾阳衰、水饮泛滥，已入危险一途。", ["沉", "细"]], "324": ["病机", "脉象沉弦，沉主里、弦主饮，为水湿内停、阳气未复之象。服前方五剂后气喘较平、小溲渐多、肿亦见消，是阳气有来复之渐、水湿有下行之势；然大腹胀满、纳谷不香、咳嗽夜盛，说明水湿未尽、饮邪仍踞。病机为阳渐复而水湿未净。", ["沉", "弦"]], "325": ["病机", "脉左弦右濡，左弦为肾阳不足、水饮内停，右濡为脾虚湿困、运化无权。喘平肿减、腹胀松为转机，但纳谷不香、神疲肢倦、舌干不欲饮，乃肾少生生之气，脾胃运输无权，津液不能上潮，犹釜底无薪。病机为脾肾阳虚、水湿浊阴未尽。", ["弦", "濡"]], "326": ["病机", "脉左虚弦、右濡滑，左虚弦为脾肾亏虚、水饮未净，右濡滑为痰湿内蕴。喘平肿消、腹胀去六七，而咳嗽时轻时剧、纳少形瘦、神疲倦怠、口干欲饮、舌转淡红，说明脾肾亏而难复，水湿化而未尽。病机为脾肾两亏、痰湿留恋。", ["虚", "弦", "濡", "滑"]], "327": ["病机", "脉濡滑无力，濡为脾虚湿困，滑为痰湿内蕴，无力为正气亏虚。喘平肿退、腹满亦消，惟咳嗽清晨较甚、形瘦神疲、纳谷不香，说明脾肾亏虚难以骤复，痰饮根株亦不易除。病机为脾肾亏虚、痰饮残留，故以丸药缓图善后。", ["濡", "滑"]], "328": ["病机", "脉浮弦而滑，浮主风温外袭，弦主饮邪内动，滑主痰浊胶固。风温引动宿饮，饮得温蒸变为胶浊之痰，互阻上焦，肺失清肃，故气喘喉钩、咳痰不出、发热畏风。脉象反映外邪未达、痰浊壅闭之机，属肺实之喘。", ["浮", "弦", "滑"]], "329": ["病机", "脉滑数不靖，滑主痰浊留恋，数主温邪未净。药后气喘身热虽平，而咳嗽痰多、胸闷纳呆，苔薄黄，脉仍滑数，说明温邪已得外达，痰浊尚恋上焦，肺胃肃降失司；适值经临少腹隐痛，兼挟宿瘀，故佐和营祛瘀。", ["滑", "数"]], "330": ["病机", "脉弦滑，弦为饮邪内停，滑为痰食互阻。暴感寒凉，内停食滞，引动痰饮，阻于中上二焦，肺胃之气不得下降，故哮喘痰声、胸闷呕吐、不能纳谷；身热恶风有汗不解，苔腻，皆留饮兼表之征。", ["弦", "滑"]], "331": ["病机", "脉弦滑，弦主饮停，滑主食滞。复诊寒热哮喘呕吐虽减，而胸闷嗳气、不能纳谷、小溲短赤、腑气不行，苔薄腻，脉仍弦滑，说明宿食留饮难以骤化，胃气不和则卧不安。脉象示痰食饮浊仍阻中焦，故拟通胃消滞、和中涤饮。", ["弦", "滑"]], "332": ["病机", "脉寸浮关弦，寸浮主肺气上逆，关弦主饮邪内聚。素嗜酒湿生痰聚饮，渍肺则咳，肺病及肾，肾少摄纳则喘，故咳喘十余年、遇感则剧、胸闷纳减。脉象显示上实下虚，酒性本热，温药难投，故宜开上焦、肃肺气、斡旋中枢而纳肾元。", ["浮", "弦"]], "333": ["病机", "脉沉弦，沉主里、主下焦，弦为饮。饮邪泛溢，咳呛动则气喘，乃下虚无以制上、中虚易于化饮。脉沉弦正合饮停于里、下焦摄纳无权之机，故早服肾气丸摄纳下焦以治水泛之饮，午服外台茯苓饮斡旋中焦，使食不酿痰。", ["沉", "弦"]], "334": ["病机", "脉尺部细弱，寸关濡滑而数。尺细弱主肾虚，寸关濡滑数主痰饮挟热。咸为肾味，痰有黑花，肾虚水泛为痰，冲气逆肺，故咳呛有年、动则气喘。脉象示下虚上实、肾不摄纳，恙根已深，故宜滋补肾阴、摄纳冲气，勿拘见咳治肺。", ["细", "弱", "濡", "滑"]], "335": ["病机", "脉象沉弦，沉主里、主阳虚，弦为饮。年逾花甲，两天阴阳并亏，痰饮上泛，饮与气涌，故咳喘卧难著枕、上气不下。背寒足冷，阳气式微，藩篱疏撤。前医清肺滋阴降气，反助饮邪。脉沉弦正示阳虚饮泛，故以温药和之，温化痰饮、摄纳肾气。", ["沉", "弦"]], "336": ["病机", "脉滑数，滑主痰，数主热，合为痰热内蕴之象。原文谓“燥邪痰热，上恋于肺，销烁阴液”，咳嗽两月、音喑不扬、舌糙黄，皆痰热燥邪灼伤肺津、金钟损而声短之征，故脉滑数主痰热恋肺、阴液受烁之病机。", ["滑", "数"]], "337": ["病机", "脉象濡滑，濡为湿、为虚，滑为痰，合之示肺虚而痰湿内恋。原文“咳嗽数月不愈，舌苔薄腻”，正是痰湿留恋、清肃不行之候；久咳肺虚，故脉濡，痰湿未化，故脉滑，主肺虚痰湿之病机，治当培土生金。", ["濡", "滑"]], "338": ["病机", "脉沉细，沉主里、主水，细主虚，合之示肺脾肾三脏虚衰、痰饮内停。原文“痰饮随气上泛，咳嗽多年，气喘难于平卧，面浮肢肿”，皆水湿泛滥、气不降纳之征，脉沉细正合肺脾两虚、喘肿重症之病机。", ["沉", "细"]], "339": ["病机", "脉弦紧而滑，弦紧主饮、主寒，滑主痰，合之示痰饮内盛、寒饮盘踞。原文“咳嗽气急，难于平卧，舌白腻”，乃脾不散津、饮邪上逆之候；脉弦紧而滑，正合“痰饮之病，宜以温药和之”之病机，主脾肾阳虚、痰饮上泛。", ["弦", "紧", "滑"]], "340": ["病机", "脉滑数，滑主痰、主脓，数主热，合之示热毒壅盛、痰瘀互结。原文“外感风温，内蕴湿热，熏蒸于肺，肺脏生痈”，咳嗽胸膺牵痛、痰臭脓血、身热口干，皆热毒腐肺成痈之征，脉滑数正主肺痈热毒痰瘀之病机。", ["滑", "数"]], "341": ["病机", "脉数苔黄，数主热，苔黄主热，合之示火热内盛。原文“五志化火，酒湿生热，肝火湿热互蒸于肺，肺脏生痈”，咳呛胸痛、痰腥臭、潮热，皆火热腐肺之候，脉数正主肝火湿热蒸肺成痈之病机。", ["数"]], "342": ["预后", "脉象濡数，濡主阴亏、主湿，数主热，合之示阴亏火旺、湿热互蒸。原文“阴分素亏，木火刑金，湿热互蒸，肺痈早成，肺叶已伤”，形肉渐削、痰腥臭、胁痛，脉濡数正合此病机；而“惟虑由痈而痿，致入不治之条”，故本段重在言预后之险。", ["濡", "数"]], "343": ["预后", "脉数无力，数主热、主毒，无力主虚，合之示正虚毒恋。原文“肺痈已延两月，咳嗽脓多血少，稠浊腥臭，纳减形瘦神疲”，肺叶已腐而正气已衰，脉数无力正合蕴毒留恋、正不胜邪之机；症势入险，故本段主预后之危。", ["数", "虚"]], "344": ["病机", "脉浮紧为外感风寒束表，滑为痰浊内壅。原文言“外感风寒袭于肺胃，膏粱厚味酿成痰浊”，表邪与痰瘀互结，壅塞肺叶成痈。故脉浮紧应表寒，滑主痰浊瘀滞，与咳嗽气粗、痰秽如脓、胁痛、振寒发热相应，示邪实壅盛之肺痈急症。", ["浮", "紧", "滑"]], "345": ["病机", "脉滑数乃痰浊瘀湿蕴结化热之象。原文谓“胶黏之痰浊，蕴蓄之瘀湿，结于肺叶之间”，虽汗出寒热解，而痰稠腥秽、胸闷胁痛、溲短赤仍在，滑主痰湿，数主内热，说明余邪未清、痰热瘀阻肺络，故需小其剂以蠲化痰浊、清肃肺气。", ["滑", "数"]], "346": ["病机", "脉浮滑芤数并见，浮滑为新风袭肺胃，芤数示阴分大伤、肝火内炽、血不归经。原文“吐血盈盆，便血如注”与“复感新邪”并见，正虚邪实，血络损伤而邪不外达。芤主失血伤阴，数主火盛，浮滑主新邪痰热，故病机为阴伤火炽、蓄瘀感邪、血不归经之险候。", ["浮", "滑", "芤", "数"]], "347": ["病机", "脉弦芤而数，弦主肝火亢盛，芤主阴血亏耗，数主君相火炽。原文“阴分素亏，君相之火内炽，逼冲任之血妄行”，虽表热减而吐血不止、咳呛胁痛，火刑肺金、清肃不行。弦芤数并见，示阴虚火旺、血热妄行，有暴脱之险，故拟养阴凉荣、清肺降气。", ["弦", "芤", "数"]], "348": ["病机", "脉芤数不静，芤为阴血亏虚，数为火热未清，“不静”示火势仍动。原文“坎水早亏，离火上亢，肺金受制”，肺移热于大肠而便血。吐血虽减而咳呛、内热、便血仍在，说明阴虚火旺、肺热下迫之机未解，虽逾险岭而未涉坦途，故仍守养阴凉营清肺降气之法。", ["芤", "数"]], "349": ["病机", "脉仍芤数不静，芤主血去阴伤，数主木火内炽。原文“血去阴伤，木扣金鸣，肺炎络损，清肃无权”，吐血便血渐止而咳呛内热、胁痛气逆尚存，舌红苔黄。脉象未静说明阴未复、火未降，肺络损伤未复，故须凉肝清肺、养阴生津，以求水升火降。", ["芤", "数"]], "350": ["病机", "脉数较缓，较前芤数不静为缓，示火热渐退、阴液渐复之机。原文“阴液难复，木火易升，肺受其冲，不能输布津液，而反化为稠痰”，吐血便血均止而咳呛痰稠、动则气逆仍在。数脉虽缓而未静，说明余火未清、肺失输布，故以补肺阿胶合清燥救肺滋养化源。", ["数"]], "351": ["病机", "脉濡软而数，濡软主阴血亏虚、脉道不充，数主余火未靖。原文“咳呛已见轻减，肺获滋润之力”，“木火有下降之势”，胁痛亦止，说明滋养清燥见效，虚火渐降。濡软示正气未复，数示余热尚存，故仍守原法加培土生金，取虚则补母之意。", ["濡", "软", "数"]], "352": ["病机", "脉芤数无力，芤主失血，数而无力为虚阳外浮。吐血盈盏成盆而色不鲜红，舌苔淡白，前服凉血清营无效，说明阴分本亏，阳气亦虚，不能导血归经，血反上溢妄行。此非实热迫血，乃气不摄血、阴阳两虚之候，故脉象芤数无力，与舌淡白共示虚象。", ["芤", "数", "虚"]], "353": ["病机", "脉芤无力，芤为血虚失血之象，无力主阳气不足。原文谓阳虚气滞，不能导血归经，血因停蓄，蓄久络损，上为吐血，下为便血，色黑如墨，舌淡白。此上下交损，皆由中焦阳虚、气不统血所致，故脉芤无力，治宜理中汤温中摄血。", ["芤", "虚"]], "354": ["预后", "脉象微细，似有若无，为阳气衰微、阴血耗竭之危候。吐血七昼夜，狂溢数斗，神志恍惚，气短，四肢逆冷过于肘膝，舌红苔灰黄，乃阴不敛阳、阳不抱阴、气难摄血，虚脱之变即在目前。脉微细与肢冷气短并见，示气随血脱，故急予益气纳气以固脱。", ["微", "细"]], "355": ["预后", "二诊连服益气纳气后，气平血止肢温，脉渐起，汗收，阴平阳秘，大有生机。原文未识出具体脉名，仅言脉渐起，说明前之微细欲绝已渐复，阳气来复，气血得摄，故守原法毋须更张。此段重在判断预后转佳，脉象由危转安为关键佐证。", []], "356": ["病机", "脉象虚细，虚主气亏，细主阴血不足。吐血数月，时发时止，形神萎顿，面无华泽，血色淡红不鲜，显系烦劳太过，心脾并亏，络损血溢，气不摄纳。虚细之脉与萎顿少华相应，说明非实火迫血，徒恃养阴凉营无益，故拟归脾汤补益心脾以摄血。", ["虚", "细"]], "357": ["病机", "脉弦芤而数，弦主肝郁，芤主失血，数主火热。始由胁肋作痛、烦躁少寐，继则吐血不止、内热口干、舌红苔黄，良由郁怒伤肝，操烦劳心，气郁化火，火炽气焰，扰动阳络，血上溢也。弦数为气火内炽，芤为血溢络伤，故亟拟清气凉肝、祛瘀生新。", ["弦", "芤", "数"]], "358": ["病机", "二诊吐血渐减未能尽止，烦躁不寐，胁痛依然，脉弦数而芤，按之不静。弦数主气火，芤主失血，按之不静示火势未平。气火入络，络热则痛，水不制火，心肾不交，还虑血涌。脉象未缓，说明郁火仍炽、阴分未复，故拟壮水清肝、泄热和络。", ["弦", "数", "芤"]], "359": ["预后", "三诊胁痛减，夜寐稍安，但吐血不止反狂涌，幸脉转小数，神疲萎顿。小数为阴分大伤、虚火炎炎之象，缘已出络之血尽去，阴血耗损，虚火有吸尽西江之势。脉虽转小，然数而神萎，示正虚邪炽，颇为可虑，故仿血脱益气之例治之。", ["数", "小"]], "360": ["病机", "脉象濡中不洪，说明虽吐血衄血盈盏成盆，但热势未至洪盛，正气尚存。濡主气分大伤，不洪示邪热入营而未完全化火张扬。原文谓“气分大伤，邪热入营，逼血妄行”，脉与神识尚清相应，提示病虽危险，犹有挽回之机。", ["濡"]], "361": ["病机", "脉数苔黄，为肝胆之火升腾、风燥之邪外袭，燥化火而刑金。数脉主热，火性急迫，故虑其血涌狂吐。原文“肺炎叶举”“胁肋牵痛”皆火燥伤络之象，脉数正合邪热内盛、迫血妄行之机。", ["数"]], "362": ["病机", "脉象芤数，芤主血络损伤、血去阴伤，数主热或虚阳浮动。负重努力致血由上溢，吐血盈碗，胁肋牵痛，乃瘀血内阻兼阴血亏虚。芤数并见，说明失血之后阴分已伤而余热未清，故以去瘀生新主治。", ["芤", "数"]], "363": ["病机", "脉芤数，芤为失血之脉，数主木火升腾。原文“水亏不能涵木，木火升腾，阳络损伤，则血上溢”，咯血内热、舌质红，皆阴虚火旺迫血之征。芤数相合，示阴血亏于下而火热炎于上，还虑血涌，故壮水柔肝。", ["芤", "数"]], "364": ["预后", "脉微寡神，为气血大虚、阳气衰微之象。原文“血去阴伤，阴不抱阳，则阳益亢；阴不胜阳，故阴愈亏”，吐血屡发而脉微寡神、血不华色、舌苔淡白，说明阴损及阳，损症已著。脉症相参，预后堪忧，故仿壮水之主以制阳光。", ["微"]], "365": ["预后", "脉细如丝，为阴血枯竭、阳气欲脱之危候。原文“涌吐六七日，盈盏盈盆，汗多气喘”，阴不抱阳，阳不摄阴，气血有涣散之虞。细如丝示脉道空虚、生机微弱，故曰危在顷刻，宗血脱益气之法峻补其气以生其血。", ["细"]], "366": ["病机", "二诊脉细无力，较前细如丝略缓，但仍示血去阴伤、气亦不足。原文“龙雷之火上升，肺气不能下降”，气逆则血溢，故涌吐虽减而症情尚在险关。细而无力说明气血两伤、虚火未靖，再宜益气益阴、顺气降逆以望转机。", ["细"]], "367": ["病机", "脉濡滑而数，濡主阴伤，滑主痰湿内蕴，数主虚火。原文“温病后，阴液已伤，虚火烁金，肺热叶焦，则生痿躄”，两足不能任地、咳呛咯痰不爽、咽干舌红苔黄，皆肺热阴伤兼痰之象。濡滑数相合，示虚火与痰湿交阻，病根已深。", ["濡", "滑", "数"]], "368": ["病机", "脉濡数，舌质红绛，为热痿之征。濡主湿，数主热，湿热内蕴，久则伤阴，筋脉失养，故两足痿躄。原文言“热痿也”，又述“叠进清阳明滋肺阴以来，两足虽不能步履，已能自行举起之象”，说明热邪渐清，但阴血未复，故仍守原法加益精养血之品。", ["濡", "数"]], "369": ["病机", "脉濡缓，舌淡白，谷食衰少，为湿痿之象。濡缓主湿，湿性黏腻，由外入内，由肌肉而入筋络，络脉壅塞，气血凝滞，故痿软不能步履。原文引“湿热不攘，大筋软短，小筋弛长”，说明湿邪留滞，筋脉弛纵，治宜崇土逐湿、去瘀通络。", ["濡", "缓"]], "370": ["病机", "脉尺弱寸关弦数，尺弱为肾阴亏虚，寸关弦数为肺热络蕴。肺肾阴亏，络有蕴热，肺热叶焦，则生痿躄。原文言“阳明主润宗筋”，治痿独取阳明，症势缠绵，非易速痊，说明阴虚内热，筋脉失濡，故两足痿软不便步履。", ["弱", "弦", "数"]], "371": ["病机", "脉弦小而数，舌边红苔腻黄，为热痹之征。弦主痛，小主血瘀，数主热。体丰多湿多痰，性躁多郁多火，外风引动内风，挟湿痰入络，络热血瘀，不通则痛。原文言“阳气多，阴气少，则为热痹”，故专清络热为主。", ["弦", "小", "数"]], "372": ["病机", "脉数渐缓，为热邪渐退之象。前服清络热十剂，痹痛十去六七，肿势亦退，风静火平。惟舌质光红，口干欲饮，小溲短少，腑行燥结，乃血不养筋，津液不能上承下润。脉数渐缓说明热势已减，但阴津未复，故仍守原方加花粉生津。", ["数", "缓"]], "373": ["病机", "脉尺部沉细，寸关弦涩，苔薄腻。尺沉细为少阴血虚，寸关弦涩为寒湿痹阻、营卫不通。产后血虚，风寒湿乘隙入太阳、少阴、厥阴之络，厥气上逆，挟痰湿阻于中焦，故腰髀痹痛连及胯腹，痛甚泛恶清涎。原文谓“寒郁湿著”，治宜温经达邪、泄肝化饮。", ["沉", "细", "弦", "涩"]], "374": ["病机", "脉虚弦而浮，浮为风象，弦为肝旺，虚为气血不足。七秩之年，气血必虚，久坐电风入肾，气虚不能托邪外出，血虚无以流通脉络，故腰痛偏左如折，痛甚四肢震动，形瘦骨立。此虚人外感风邪，本虚标实之候，治拟大剂玉屏风改散为饮，益气托邪。", ["虚", "弦", "浮"]], "375": ["病机", "脉左弦滑，右濡滑。弦主风主痛，滑主痰湿，濡主湿。风寒湿三气杂至，合而为痹，痹者闭也，气血不能流通所致。原文辨“痿躄不痛，痛则为痹”，故髀部痹痛连及腿足，不能步履，有似痿躄之状，实为痹证。治拟蠲痹汤加减，温营去风、化湿通络。", ["弦", "滑", "濡"]], "376": ["病机", "脉弦细而涩，弦主风邪，细涩为阴血亏虚。原文谓“阴分素亏，邪风乘虚入络”，风性善走窜入经络，故肢节疼痛无定处而成行痹。营卫因阴亏而流通不畅，脉象反映正虚邪恋之病机，主行痹。", ["弦", "细", "涩"]], "377": ["病机", "脉沉细而涩，沉主里，细涩为阴血不足。原文谓“肝脾肾三阴不足，风寒湿三气入络，与宿瘀留恋”，故髀骨酸痛入夜尤甚。脉象示三阴虚损、邪瘀互结之病机，主痹证。", ["沉", "细", "涩"]], "378": ["病机", "左脉滑而有力，滑主痰浊，有力为实邪。原文谓“痰浊积于胸中，致成胸痹”，浊阴上僭蒙蔽清阳，膻中气窒，故胸痛彻背、夜寐不安。脉象反映痰浊壅盛之病机，主胸痹。", ["滑"]], "379": ["病机", "脉濡滑而数，濡主湿，滑主痰滞，数主热。原文谓“伏邪湿热挟滞，互阻募原”，枢机不和则寒热，脾失健运则䐜胀，风湿入络则痹痛。脉象示湿热挟滞阻遏之病机，主湿热痹痛。", ["濡", "滑", "数"]], "380": ["病机", "脉濡数，濡主湿，数主热。二诊腑气通而脐腹胀减，但右髀痹痛不便步履，苔薄腻黄。原文谓“阴液本亏，湿热气滞互阻募原”，肝失疏泄，脾失健运，络中风湿留恋。脉象示湿热未清、营卫不通之病机。", ["濡", "数"]], "381": ["病机", "脉虚弦而数，虚为阴分亏虚，弦主肝郁气滞，数主蕴热。原文谓“阴分本亏，肝脾气滞，蕴湿浊气，凝聚募原，络中痰瘀未楚”，故痹痛虽轻而不便步履。脉象示正虚邪恋、痰瘀阻络之病机。", ["虚", "弦", "数"]], "382": ["病机", "脉三部弦小而数，右寸涩、关濡、尺细数。弦小数为肝郁化热，涩濡为湿滞，细数为阴亏。原文谓“肾阴早亏，湿遏热伏，犯胃贯膈”，故胸痹痞闷、泛恶、便结。脉症合参示阴虚湿热壅遏之病机。", ["弦", "小", "数", "涩"]], "383": ["病机", "脉左三部细小带弦，右寸涩稍和、关濡尺细。细小弦为阴亏肝郁，涩濡为湿滞。原文谓“少阴之分本亏，湿热挟痰滞互阻中焦，肝气横逆”，故胸痞呕恶、便结。脉象示正虚湿热痰滞互结之病机。", ["细", "弦", "涩", "濡"]], "384": ["病机", "右脉濡滑主湿浊内蕴，左脉弦细带数示阴分本亏而肝木偏旺。原文谓\"阴分本亏，湿热留恋募原，三焦宣化失司\"，湿浊虽见下行而脾不健运、胃不通降，故纳少溲赤、苔薄黄、多日未更衣。脉象正合湿滞与阴亏并存之机，非纯实可下。", ["濡", "滑", "弦", "细"]], "385": ["病机", "右濡滑而数，为湿热黏腻熏蒸之象；左弦细带数，乃肾阴亏于未病之先、肝木失养。原文引叶氏\"湿热为黏腻熏蒸之邪，最难骤化\"，故虽胸痞减、腑气通，仍纳少溲赤、临晚潮热、苔薄腻微黄。脉症合参，主湿热逗留募原、三焦宣化失司、脾胃无权。", ["濡", "滑", "数", "弦"]], "386": ["病机", "右寸关颇和，示脾胃运化渐复；左关无力、两尺细软，则邪少正虚，肝肾不足。原文谓\"神疲乏力，目视作胀，且畏灯亮，此正虚浮阳上扰\"，口涎渐少为脾气能摄涎，苔黄已化、溲色转淡为湿热下行。脉象以尺部细软点出正虚本质，故治取标本兼顾。", ["细", "软"]], "387": ["预后", "脉象颇和而惟尺部细小，是病邪已去、脾胃资生有权之佳兆，然尺小提示下元尚弱。原文谓饮食日增、小溲渐清带淡黄，湿热从二便下达，正气日振；舌根腻未尽化，余湿尚存。脉以\"颇和\"言胃气渐复，以\"尺细小\"言根本未充，故主预后向愈而需扶脾化余湿。", ["细", "小"]], "388": ["预后", "脉象渐渐和缓，为脏腑气血日见充旺、胃气来复之征。原文引\"胃以纳谷为宝\"及\"无毒治病，十去其八，毋使过之，伤其正也\"，强调病邪尽去后当以饮食缓缓调理，余下微邪正足则自去。脉由病中之偏转为和缓，正是邪退正复、预后良好的直接反映。", ["缓"]], "389": ["平脉", "脉象和缓有神，为正气充旺、胃气有神之平脉表现。原文谓病邪尽去、饮食颇旺，惟小便色带黄、苔薄腻示余湿未尽；四日未更衣因饮食多流汁而非燥结。脉\"和缓有神\"与邪去正复相应，故不以病脉论，而属病后向愈之平调脉象，宜慎起居、节饮食以善后。", ["缓"]], "390": ["主病", "左弦紧为寒邪引动厥气上逆、肝脉拘急，右迟涩主寒凝气滞、食滞交阻中宫。原文谓新产半月而胸脘痛大发、拒按呕吐、形寒怯冷、苔灰腻，乃\"新寒外受，引动厥气上逆，食滞交阻\"，胃气不得下降。脉紧迟涩正合寒凝食滞之实，故急拟散寒理气、和胃消滞。", ["弦", "紧", "迟", "涩"]], "391": ["兼症", "左弦主肝气肝阳上升，右迟缓示湿滞未楚、脾胃运化无权。原文谓服药后胸脘痛减、呕吐止，而谷食无味、头眩心惊，苔薄腻，乃\"营血本虚，肝气肝阳上升\"兼湿滞未清。脉弦缓并见，说明痛势虽缓而肝旺脾弱、湿滞未化之兼症仍在，故拟柔肝泄肝、和胃畅中。", ["弦", "缓"]], "392": ["病机", "脉左弦右涩，左弦为肝气横逆，右涩为血虚不能养肝，肝气犯胃克脾，通降失司，故胸脘痛引胁肋、气升泛恶、夜不安寐；苔薄黄提示气郁化热。病机为血虚肝旺、胃失和降。", ["弦", "涩"]], "393": ["病机", "脉弦细而数，弦为肝气有余，细为阴伤，数为火炽；气郁化火，火内炽则阴伤，厥阳升腾无制，胃气逆而不降，故心悸不寐、头眩泛恶、内热口燥、腑行燥结；舌边红苔黄为火郁之征。", ["弦", "细", "数"]], "394": ["病机", "脉弦而数，弦主肝郁，数主火盛；气郁化火，销烁胃阴，胃气不降，肝升太过，故胸脘痛引胁肋、纳少泛恶；舌质红苔黄为热象。久痛属热，暴痛在经，久痛在络，此热郁络滞之机。", ["弦", "数"]], "395": ["病机", "脉象弦迟，弦为肝脾气滞，迟为受寒；脘痛喜按、得食则减、舌苔薄白，皆中虚受寒之征。虚寒气滞，肝脾不和，故以小建中汤温中补虚、缓急止痛。", ["弦", "迟"]], "396": ["病机", "脉左弦细、右虚迟，左弦细为肝木来侮，右虚迟为中气必虚；虚寒气滞为痛，虚气散逆为胀，故饱食则痛缓腹胀、微饥则痛剧心悸，舌淡白。体丰中虚，肝脾不和，虚寒内生。", ["弦", "细", "虚", "迟"]], "397": ["病机", "脉沉涩似伏，沉涩为气机郁滞，似伏为气闭不通；郁怒伤肝，肝气横逆，痰滞互阻，胃失降和，肝胀则痛，气闭为厥，故痛极而厥、牙关拘紧、四肢逆冷、不省人事；舌薄腻为痰湿之象。", ["沉", "涩", "伏"]], "398": ["病机", "脉左弦右涩，左弦为肝气未平，右涩为脾胃不和、运化失常；厥气渐平而胸脘饱闷嗳气、不思纳谷、腑行燥结，乃肝胃不和、气机不畅之余象，故拟柔肝泄肝、和胃畅中。", ["弦", "涩"]], "399": ["病机", "脉沉涩似伏，沉涩主气郁血滞，似伏为气闭；大怒伤肝，足厥阴逆气自下而上，累及手厥阴经，气闭则厥，不通则痛，故胸脘作痛、喜笑不能自禁、笑极则厥、牙关拘紧、四肢逆冷；苔薄腻为痰滞。", ["沉", "涩", "伏"]], "400": ["病机", "左弦右涩，左关候肝，弦为肝气偏旺；右关候脾，涩为脾运不健、气血滞涩。原文谓“厥气虽平，脾胃未和，中宫运化无权”，故脉象反映肝气虽减而脾胃气机未畅，运化无力，故见胸脘痞闷、嗳气不能饮食。", ["弦", "涩"]], "401": ["病机", "脉弦紧而数，弦主厥阴肝经为病，紧主寒束，数主内热。原文谓“新寒外束，厥气失于疏泄，宿滞互阻”，寒热夹杂，表里并病，故脉象弦紧而数，症见少腹拒按、胸闷泛恶、临晚寒热、溲短赤、苔腻黄。", ["弦", "紧", "数"]], "402": ["病机", "脉弦紧较和，较前之弦紧而数已见缓和，示厥阴疏泄渐复、寒热之势稍减。原文谓“肝失疏泄，胃失降和，气化不及州都，膀胱之湿热壅塞溺窍”，故仍见胸闷纳少、腑气不行、小溲短赤溺痛，脉象反映肝胃气滞、湿热未清。", ["弦", "紧"]], "403": ["病机", "脉弦涩，弦主肝郁气滞，涩主血行瘀阻。原文谓“蓄瘀积于下焦，肝脾气滞，不通则痛”，经行忽阻、少腹拒按、痛引腰胯、小溲不利，皆瘀血内停、气机不通之候，故脉见弦涩。", ["弦", "涩"]], "404": ["病机", "左脉弦涩，右脉濡缓。左弦涩主肝经气滞血瘀，右濡缓主湿浊困阻中焦。原文谓“湿浊阻于中宫，旧瘀积于下焦”，故少腹作痛、小溲淋沥、胸痞泛恶、苔灰腻，脉象反映湿瘀交阻、肝脾同病。", ["弦", "涩", "濡", "缓"]], "405": ["病机", "脉象弦紧，弦为肝脉，紧主寒痛。原文谓“风冷由脐而入，引动寒疝”，寒邪凝滞厥阴，阳气不运，浊阴凝聚，故脐腹攻痛、有形积块、形寒怯冷、肠鸣不食、苔白腻，脉弦紧正是寒凝气滞之征。", ["弦", "紧"]], "406": ["病机", "脉象虚弦，虚为脾土不足，弦为肝木偏旺、虫积气滞。原文谓“脾虚生湿，湿郁生虫，虫日积而脾愈伤”，面黄肌瘦、舌光无苔为脾虚之象，腹痛陡来截止为虫动之征，脉虚弦正合脾虚虫积之病机。", ["虚", "弦"]], "407": ["病机", "左三部弦数，右三部滑数，太谿细弱，趺阳濡数。弦数为肝阳偏亢，滑数为胃热，细弱为肾阴亏虚，濡数为胃气不足。原文谓“阴液亏耗，不能涵木，肝阳上僭”，故见虚里穴动、自汗盗汗、头眩眼花、消谷等症，脉数不减虑成消症。", ["弦", "数", "滑", "细"]], "408": ["病机", "左三部弦数，右三部滑数，太谿细弱，趺阳濡数。弦为肝旺，数为热盛，滑主胃热，细弱为阴亏。心肝阴伤阳亢，消灼胃阴，胃热炽盛，故脉弦数滑数；太谿细弱示肾阴亏耗，趺阳濡数乃胃热。症见多汗、眩晕、面烘、心悸、唇红舌光，一派阴液亏耗、虚火上炎之象。", ["弦", "数", "滑", "细"]], "409": ["预后", "脉弦数较和，细数依然。弦数为肝阳上僭、水不制火，细数为阴液亏耗。较和示肝阳稍平，细数依然说明阴亏未复。此段述药后脉象变化，仍守原意，因恙延日久，非克日奏功，预后需缓图。", ["弦", "数", "细"]], "410": ["病机", "脉弦滑，右甚于左。弦主肝郁气滞，滑主湿滞痰积。痧后谷食不谨，积滞生湿，湿郁化热，阻于募原，太阴失健运，阳明乏通降，故脘腹膨胀、小溲不利、咳嗽气喘、身热肢肿。右甚于左，病偏太阴阳明，湿滞中焦为甚。", ["弦", "滑"]], "411": ["病机", "脉浮滑。浮主风邪在表，滑主痰湿内壅。肺有伏风，痰气壅塞，脾有湿热，不能健运，故咳嗽气逆、面浮肢肿、食入腹胀、小溲不利。浮滑并见，示风邪与痰湿相合，病位在肺脾，势成肿胀。", ["浮", "滑"]], "412": ["病机", "脉虚弦而数，颈脉动时咳。虚为营阴大亏，弦为肝失涵养、木克中土，数为内热。营阴亏耗，肝阳上亢，脾不健运，水湿泛滥，上射于肺，故遍体浮肿、难以平卧、口干、腹胀、小溲短赤。脉症参合，刚剂尤忌。", ["虚", "弦", "数", "动"]], "413": ["病机", "脉虚弦带数。虚为血虚阴亏，弦为木火上升，数为内热。水气随木火上逆犯肺，肺失肃降，中土受侮，脾失健运，故咳嗽气逆、不能平卧、内热口干、食入脘腹饱胀益甚。仍宜养金制木，崇土利水。", ["虚", "弦", "数"]], "414": ["病机", "脉弦滑而数。弦主肝郁气滞，滑主湿浊内壅，数主热。暑气内逼，湿郁滞阻，三焦决渎无权，湿热壅盛，故脘腹胀满、泛泛呕恶、面浮肢肿、里热口干、二便不通、皮色晦黄、苔灰腻。此属热胀，治以苦辛通降。", ["弦", "滑", "数"]], "415": ["病机", "脉象浮紧。浮主风邪在表，紧主寒水内盛。春温愈后停滞，湿郁化水，复招外风，风激水而横溢泛滥，故遍体浮肿、气逆不能平卧、大腹胀满、囊肿腿肿、小溲涩少。浮紧为风水相搏之象，此为风水重症，急拟开鬼门、洁净府。", ["浮", "紧"]], "416": ["病机", "脉浮紧而弦，浮主表，紧主寒，弦主水饮。原文述遍体浮肿、咳嗽气急、小溲不利，乃脾阳不运、水湿泛滥，灌浸表里。脉浮紧为表寒未解，弦为水气内停，故主风水相搏、肺脾同病之候，与苔白腻、囊肿腿肿相应。", ["浮", "紧", "弦"]], "417": ["病机", "脉浮紧，浮为阳气外浮，紧为寒水内盛。原文谓中阳受伤、脾胃困顿，阳气不到之处即水湿灌浸之所，大有水浪滔天之势。脉浮紧说明寒水困阻、表里俱病，与遍体浮肿、咳嗽气逆、大腹胀满、苔白腻相应，病势尚在重险。", ["浮", "紧"]], "418": ["预后", "脉紧转和，紧为寒水凝聚之象，转为和缓则示水湿已得分消、阳气渐复。原文述遍体浮肿十去五六、气逆亦平，脉紧转和，说明病势向愈。惟脾不健运，食入难化、便溏口干，乃脾虚不能为胃行津液，非热象，预后转佳而余邪未清。", ["紧", "和"]], "419": ["病机", "脉浮滑而数，浮主风邪在表，滑主水湿壅盛，数主阳热。原文述关左暴肿气急、小溲短赤、口渴欲饮，为外邪壅肺、气道不通、风水为患。风为阳邪，水为阳水，脉浮滑数正合风水化热之机，与胃纳不减相应，故拟越婢汤加味。", ["浮", "滑", "数"]], "420": ["病机", "脉象沉细，沉主里主阴，细主虚主湿。原文述年近花甲、思虑伤脾、脾阳不运、湿浊凝聚，致大腹胀满、鼓之如鼓、小溲清白。脉沉细说明脾阳虚弱、湿浊内困，阴寒凝聚，与舌无苔、形瘦神疲相应，故当温运分消。", ["沉", "细"]], "421": ["病机", "脉沉细，沉为阳虚不能鼓动，细为气血不足。原文谓火衰不能生土、中阳不运、浊阴凝聚，鼓之如鼓、中空无物，即无形虚气散逆为胀。脉沉细与形瘦神疲、纳谷减少、小溲清长、腑行不实相应，说明脾肾阳衰、虚寒胀满，故拟益火消阴。", ["沉", "细"]], "422": ["预后", "脉沉未起，沉为阳气未复、阴寒尚存。原文述脐腹胀满大减、小溲微黄、腹内热气烘蒸，为阳气内返之佳象，但脉沉未起、形肉削瘦，说明阳虽渐回而根本未复，阴翳尚未尽消。脉象与症候合参，示病势向愈而正气犹虚，仍须益火之源。", ["沉"]], "423": ["病机", "脉沉细，沉主里主阳虚，细主虚主阴血不足。原文述大腹膨胀、鼓之如鼓、脐突青筋显露、形瘦色萎、舌无苔，为脾肾之阳大伤、虚气散逆、浊阴凝聚。前用理气消胀而胀势有增无减，病延一载，脉沉细正合虚胀无疑，故仿塞因塞用之法。", ["沉", "细"]], "424": ["病机", "脉细数，细为阴血亏虚、脉道不充，数为阴虚生内热。本案忧思伤脾，脾运无权而肝木来侮，浊气在上生䐜胀，大腹胀满、青筋显露、足肿、溲难，皆脾虚水湿不化、肝郁化热之象；口燥欲饮、舌红绛、脉数，正合阴虚内热。细数并见，示本虚标实、气阴两伤，故六君、五皮、肾气叠进而病势不减，已入危笃。", ["细", "数"]], "425": ["病机", "两关脉弦，关候肝脾，弦为肝气怫郁、木乘土位之象；寸部郁涩，涩主气机窒塞、湿浊凝聚。原文谓湿热浊气凝聚募原之间，三焦气机流行窒塞，故脘痛、腹满作胀、食入难化、面黄溺少。弦涩并见，说明肝郁气滞与湿浊内阻并存，气机不通为其关键，故拟疏肝解郁、运脾逐湿。", ["弦", "涩"]], "426": ["病机", "脉弦数为木火体质、肝郁化热之征。弦主气滞，数主热，气阻则血痹，与湿热凝聚募原，遂成血臌重症：大腹胀硬、脐突、红筋显露、便黑溲赤、舌灰黄，皆气滞血凝、湿热内蕴之候。原文强调气为血之先导，气滞则血凝，故脉弦数正示气滞血瘀兼湿热，治以行气去瘀、清热化湿。", ["弦", "数"]], "427": ["病机", "左弦右濡滑，左关候肝、右关候脾。弦为肝气不舒，濡滑为湿浊内盛、脾运失职。湿浊从下受，由经络入脏腑，太阴健运失常、阳明通降失司，故腿足浮肿、大腹胀满、胸闷气逆、不能平卧、面灰黄。濡滑主湿，弦示气机壅滞，合为脚气冲心重症，壅疾由湿浊上干所致，故急拟逐湿下行。", ["弦", "濡", "滑"]], "428": ["病机", "左弦细、右濡滑，与初诊相较，左脉由弦转细，示肝郁渐缓而正气不足；右濡滑依旧，说明湿浊未化、脾运仍困。故大腹胀满、腿足浮肿依然如旧，面乏华色、舌苔白腻，皆湿蕴由下而上、脾胃运化无权之象。脉细为虚，濡滑为湿，虚中夹湿，脚气重症还虑冲心之变，故仍守逐湿下行原意。", ["弦", "细", "濡", "滑"]], "429": ["病机", "脉象濡小而滑，濡滑主湿浊内蕴，小为脾弱正虚、脉道不充。三诊腿足肿略减而手背亦肿，腹胀虽松，胸闷气升难以平卧，身热不壮、口干且苦、苔薄腻微黄，皆脾弱水湿泛滥、浊气上干、肺胃之气失降之候。濡小示脾虚，滑示湿浊未清，故曰恙势尚在重途，仍以五苓合鸡鸣散逐湿下行。", ["濡", "小", "滑"]], "430": ["病机", "脉仍濡小而滑，与三诊同，说明脾虚湿盛之本质未变。虽肿势减、腹胀松、小溲渐多，水湿有下行之势，然身热时轻时剧、口苦且干、苔腻黄，示浊气留恋募原、脾胃运化无权。濡小为脾弱，滑为湿浊，脉象未转，故虽虚不补，仍宜五苓合鸡鸣散逐湿下行、运脾分消，冀不增他变而转危为安。", ["濡", "小", "滑"]], "431": ["病机", "脉由濡小转为弦小而滑，弦为肝气不舒、气机壅滞，小为脾虚，滑主湿浊。五诊肿势大减、腹胀渐松、小溲渐多，水湿有下行之渐，然纳少嗳气、咳嗽、苔薄白腻，示浊气聚于募原、水湿未能尽化，太阴健运失常、阳明通降失司。弦小滑并见，为虚中夹湿、气滞未畅，故前法颇合，毋庸更张。", ["弦", "小", "滑"]], "432": ["病机", "脉濡滑而数，濡主湿、滑主痰湿内蕴、数主热，合为湿热互阻中焦之象。原文言“湿热滞互阻中焦，太阴健运无权，阳明通降失司”，故脘腹胀闷、不思纳谷；湿热郁蒸外溢肌肤则一身尽黄、小溲短赤如酱油色。脉与苔薄腻黄相合，示黄疸已成而湿浊未化，故非易速痊。", ["濡", "滑", "数"]], "433": ["病机", "脉濡数，濡为湿象、数为温邪未清，合示湿温蕴阻募原。原文谓“滋阴太早，致伏温未发，蕴湿逗留募原”，湿著于内而现于外，故遍体发黄、目珠黄、溺短赤；身热晚甚、渴喜热饮、肢节酸疼，皆湿多温少、互阻不解之征。脉濡数正合“温少湿多”之机，故断为缠绵之症。", ["濡", "数"]], "434": ["病机", "左弦数、右濡数，弦主肝郁、数主热、濡主湿，合示湿热挟痰逗留募原。原文言“伏邪湿热逗留募原，如盦酱然”，湿热蒙蔽清窍则梦语如谵、神机不灵；清阳失旷、冲气上升则呃逆频频、手足蠕动，阴液暗耗而内风煽动。脉象与湿温黄疸互患相应，故虑痉厥之变。", ["弦", "数", "濡"]], "435": ["病机", "脉浮紧而数，浮主表、紧主寒湿外束、数主热郁于内，合示外湿内热、表里同病。原文谓“曝于烈日，复受淋雨，又夹食滞，湿著于外，热郁于内”，故遍体发黄、目黄溲赤、寒热骨楚、胸闷脘胀。浮紧应外湿束表，数应内热郁蒸，脉证相合，故仿麻黄连翘赤豆汤解表清里。", ["浮", "紧", "数"]], "436": ["病机", "脉濡主湿，原文谓“饥饱劳役，脾胃两伤，湿自内生，蕴于募原”，脾运不健则湿浊内蕴，故肌肤色黄、目黄溲赤；肢倦乏力、纳谷衰少，皆脾虚湿困之征。脉濡与舌苔黄相参，示湿郁化热而未甚。病延两载，属脱力黄病，虚中夹湿，故难速效，宜补力丸缓缓图之。", ["濡"]], "437": ["病机", "脉细涩，细主阴血亏少、涩主瘀血内停，合示寒客血室、宿瘀不行。原文言“经闭三月，膀胱急，少腹满，身尽黄，额上黑，足下热，大便色黑”，皆瘀积膀胱少腹、血行不畅之征；纳少神疲为血虚不荣。脉细涩与女劳疸重症相应，瘀血不去则黄不退，故非易速痊。", ["细", "涩"]], "438": ["病机", "脉沉细，沉主里、细主阳虚阴盛，合示脾肾两亏、寒湿内阻。原文谓“湿从寒化，阳不运行，胆液为湿所阻”，故一身尽黄、面目黧黑、小溲淡黄、大便灰黑；纳少泛恶、神疲乏力皆阳虚湿困之候。脉沉细正合阴疸阳虚之机，故拟茵陈术附汤助阳运脾，以离照当空散阴霾。", ["沉", "细"]], "439": ["病机", "左弦涩、右濡滑，弦主肝气上逆、涩主营血亏虚、濡滑主湿痰逗留。原文言“营血亏虚，肝气上逆，犯胃克脾，湿痰逗留中焦，肺胃肃降失司”，故胸闷气升、嗳气泛恶、食入作哽、痰多咳嗽；月事八旬未止为血虚不摄。脉象与舌边红、中薄腻相参，示肝胃同病、虚实夹杂。", ["弦", "涩", "濡", "滑"]], "440": ["预后", "左关弦小而促，弦为肝气，小为阴伤，促为阳郁，反映湿温伏邪内陷少阴，引动冲气上逆犯胃冲肺，故气喘呃逆、身热不扬；右濡细、趺阳虚弦数、太谿似有似无，示正虚邪陷、神不守舍，郑声神糊，厥脱之变指顾间事，脉象与危候相应。", ["弦", "小", "促", "濡"]], "441": ["病机", "脉弦小而滑，弦主肝气上逆，小为营液亏虚，滑为胃有痰滞。高年营液本亏，肝失柔养，气逆犯胃，胃失降和，故食后呃逆频频；舌光无苔亦示阴亏。脉症合参，病机在肝逆胃滞，治宜养阴柔肝为主，和胃顺气佐之。", ["弦", "小", "滑"]], "442": ["病机", "脉濡数，濡主湿，数主热，为湿热内蕴之象。厥阴肝脉循阴器络睪丸，肝失疏泄，湿热下注，膀胱宣化失司，故小溲夹浊、偏疝坠胀疼痛；苔腻亦湿征。经云“诸液浑浊，皆属于热”，无形厥气与有形湿热互相为患，脉象正合湿热下注之机。", ["濡", "数"]], "443": ["病机", "脉弦数，弦为肝气失疏，数为湿火内郁。湿火挟厥气下注，故偏疝坠胀疼痛、小溲浑浊；口干内热、苔腻而黄皆湿热之征。脾胃清气不升，小肠膀胱浊气不降，肝失疏泄，湿郁生痰，痰火瘀凝，脉弦数正是湿火与厥气交争之反映。", ["弦", "数"]], "444": ["主病", "脉弦细，弦主厥气失疏，细主中阳衰弱。中阳不足，厥气横逆，故疝气坠胀、腹痛筋急、泛泛作恶，甚则脘痛呕吐；苔薄腻亦示阳弱湿滞。脉症合参，病机为中阳衰弱、厥气失于疏泄，故拟大建中汤温建中阳以治。", ["弦", "细"]], "445": ["病机", "脉沉弦，沉主病在里，弦主肝气瘀凝。腹部结块按之略痛，或左或右，内热神疲，苔薄腻，乃中阳不足、脾胃素伤、血不养肝，肝气瘀凝而成瘕病。脉症参合，病非轻浅，若仅攻破恐伤中阳而致膨满，故拟香砂六君扶养脾胃以冀消散。", ["沉", "弦"]], "446": ["病机", "脉弦细而数，弦为肝气，细为阴血不足，数为虚热内扰。经停四月忽然崩漏，腹内作痛，泛泛呕吐，形瘦骨立，纳谷衰少，苔薄腻而灰，乃肝脾两虚、藏统失司，寒瘀停凝腹内，状如怀孕，即瘕病。脉症合参，症势沉重，急宜培补气阴、温通寒瘀。", ["弦", "细", "数"]], "447": ["病机", "脉郁数，数为热，郁示气机壅遏。身热六七日不退，大便脓血，苔黄，乃伏邪蕴蒸气分，湿郁化热入营，血渗大肠，肠有瘀浊所致。脉数应热，郁应湿遏，与便脓血、苔黄之症相应，故拟白头翁汤加味清解伏邪、苦化湿热。", ["数"]], "448": ["病机", "脉沉主里，苔腻主湿浊内蕴。脾阳不健，瘀浊留恋，血不循经而下溢，故大便脓血色紫；身热不扬乃阴盛格阳于外，非实热之象。脉沉与苔腻相合，正说明病本在脾、在里、在阳衰湿浊，而非表热，故治宜温运脾阳、化瘀浊。", ["沉"]], "449": ["病机", "溺血不痛属尿血，脉细小而数，细为阴血不足，数为君相之火内动。肾阴亏虚，相火下移小肠，逼血下行，故小溲带血而溺管不痛。脉细小而数正合阴虚火旺之机，故取壮水制阳、育真阴清相火之法。", ["细", "小", "数"]], "450": ["病机", "脉濡弦而数，濡主脾虚湿困，弦属肝旺，数示虚热。肝脾两亏，藏统失司，故溲血甚多、小便频数、大便溏薄；阴无阳化则膀胱宣泄无权，足肿面浮。舌中剥边黄腻亦应肝脾两伤、湿浊内蕴，故拟归脾合滋肾通关以引血归经、生阴化阳。", ["濡", "弦", "数"]], "451": ["病机", "左脉弦小而数，右脉濡弦，弦小数为肝虚有热、藏血失职，濡弦为脾虚湿困、统血无权。血随溲下而色紫黑、少腹满，是宿瘀未清之征；内热心悸、耳鸣头眩、面黄足肿，皆肝脾两虚、瘀血内停之候。故仍守归脾合滋肾法，复入通瘀之品。", ["弦", "小", "数", "濡"]], "452": ["病机", "溲血已止而尺部细小，寸关濡弦，尺小主肾虚精血不足，濡弦主脾弱肝旺。血虚则肝气肝阳易升，脾弱则水谷之湿不化，故足肿面浮、纳谷减少、小便不爽。此段重在辨血虚与脾弱并存之病机，故拟健运中土而化水湿，兼顾滋养。", ["细", "小", "濡", "弦"]], "453": ["病机", "尺部细小、寸关虚弦，虚弦为肝阳易升而中气不足，尺小为肾命火衰。血虚之体肝阳上扰，故头眩耳鸣、面无华色；脾弱则水谷之湿泛滥，故肿仍不退、便溏口干不欲饮。此火不生土、气不化血之机，故欲扶脾土须益命火，取少火生气之义。", ["细", "小", "虚", "弦"]], "454": ["病机", "尺部细小、寸关濡弦无力，细小主肝肾阳虚，濡弦无力主中气已虚、肝木来乘。肝肾阳虚则水谷之湿生痰聚饮，横溢募原，气化不及州都，膀胱宣化无权，故身半以下肿、便溏尿少、胸闷纳少。舌薄腻亦湿浊之征，故再拟崇土渗湿、滋肾通关。", ["细", "小", "濡", "弦"]], "455": ["病机", "脉弦数而促，弦属肝火，数主热盛，促为火急而气促之象。误服姜醋辛热，引动心肝之火上亢，阳络损伤则血上溢，故舌衄如涌、气粗喘促；舌干涸无液，是肺金化源告竭、龙雷之火飞越升腾。脉促正示火盛气逆、有喘脱之险，故急拟生脉救化源、犀角地黄清血热。", ["弦", "数", "促"]], "456": ["病机", "脉左弦右涩，弦为肝旺，涩为血少。肝郁化火，火性炎上，上冲则呕吐；肝胆同宫，挟胆火上升，故气升呕逆。口干内热、经事愆期、夜不安寐，皆由中怀抑塞，木郁不达，郁极化火，肝气横逆，顺乘中土，脾胃受制，营血化源不足所致。", ["弦", "涩"]], "457": ["病机", "脉弦细而涩，弦为肝失条达，细涩为营血亏耗。营血亏耗则肝失濡养，脾失健运，胃失降和，故气升呕吐虽未发而夜寐不安、经事行而不多。苔灰黄为郁热未清。此脉象反映木土不争、气血两亏之病机，治当养血柔肝、和胃降逆。", ["弦", "细", "涩"]], "458": ["病机", "脉象弦数，弦主肝郁，数主有热。客邪虽退而正气不复，冲任亏损，经事三月不行。纳减神疲为脾胃虚弱，弦数之脉提示肝郁化热未清，冲任亏虚而经事不通，故仍宗前法调治。", ["弦", "数"]], "459": ["预后", "脉细如丝，为阴伤津少、气血虚衰之象。少腹痛阵作、形寒纳少、咳嗽泛恶、口干引饮，乃肝热瘀阻、气滞不流，阴伤津少上承，肺虚痰热留恋。虚羸太极而脉细如丝，正气衰败，故曰恐难完壁，属预后不良之候。", ["细"]], "460": ["预后", "脉细依然，示阴伤津少未复。四肢逆冷、有汗甚多、形瘦骨立、口渴欲饮，乃肝郁化热，热深厥深，阴伤津少上承，肺虚痰热留恋。舌光脉细，阴不敛阳，阳不藏阴，颇虑厥脱之变，皆由虚羸太极，不任攻补使然。", ["细"]], "461": ["预后", "脉细如丝，阴血亏耗未复。形瘦骨立、舌红而绛、咳嗽泛恶，木郁化火，肝病传脾，阴伤津少上承，肺虚痰热留恋。虽厥复汗收、胃纳渐进为转机，但脉仍细如丝，正虚难复，故引《难经》贼邪之说，谓未足恃也。", ["细"]], "462": ["病机", "脉濡涩，濡主湿滞，涩主血瘀。适值经临而色紫黑、少腹胀痛拒按，乃新寒外束，宿瘀内阻。少腹为厥阴之界，肝失疏泄，气滞不通，不通则痛。气为血之帅，气行则血行，故行血以理气为先。", ["濡", "涩"]], "463": ["病机", "脉象濡小无力，濡小为营血亏耗，无力为气虚。年十六经犹未行，面色㿠白、心悸跳跃、神疲乏力，皆营血亏耗，无以下注冲任使然。舌苔薄腻，兼有湿滞。治当和营通经，以充经血之源。", ["濡", "小"]], "464": ["病机", "脉细为阴血亏少之象。患者崩漏日久，肝脾两亏，藏统失司，阴液已伤，冲任失固；又见面浮足肿、纳少便溏，乃脾胃薄弱、水谷之湿不化。脉细正应阴损及阳、中土败坏之险途，故以益气生阴、扶土运中为治，冀阳生阴长。", ["细"]], "465": ["病机", "脉细为血少，数为有热，合之崩漏不止、形瘦头眩，显系营血大亏、冲任不固。阴虚于下则阳浮于上，故脉细而数。归脾不效者，病在阴亏阳浮，非单纯气虚。治当滋养阴血以潜浮阳，调摄冲任而固奇经，胶艾四物合三甲饮正合此机。", ["细", "数"]], "466": ["病机", "脉细小为气血两亏之征。肝脾两亏，藏血统血失司，故经漏如崩、面色萎黄；腰为肾腑，肾虚则腰骨酸楚。脉细小与面黄、腰酸相应，示中气不足、血失统摄。治从心脾二经，归脾汤加味，俾中气充足而引血归经。", ["细", "小"]], "467": ["病机", "脉细涩主血少而兼瘀滞。经漏三月、甚则似崩，血去阴伤，故脉细；宿瘀留恋冲任、新血不得归经，故脉涩。舌淡黄、心悸头眩，皆血虚阳浮之象。暴崩宜补摄，久漏宜清通，故用胶艾四物调摄冲任、祛瘀生新，使瘀去而血自归经。", ["细", "涩"]], "468": ["病机", "脉虚弦者，气虚而肝阳偏亢之象。漏红带下、便后脱肛、肛门坠胀，皆中气下陷、气虚不能摄血；腰腿酸楚、腑行燥结，则血亏肝阳上升。虚为气馁，弦为肝旺，故治以补中益气、调摄奇经，冀气能摄血而血自归经。", ["虚", "弦"]], "469": ["病机", "原文未识脉名，从症推机：营虚肝旺，肝郁化火，脾虚生湿，湿郁生热，湿热郁火流入带脉，带脉失约束之权，故内热溲赤、腰酸带下；湿热下迫大肠则肛门坠胀。治以清火佐养营、渗湿兼扶土，标本兼顾，切中湿热郁火伤营之病机。", []], "470": ["病机", "原文未识脉名，据症析机：营血亏虚，肝火偏旺，火挟湿热下扰带脉，带脉失约，故带下赤白；头眩为肝阳上扰，腰酸为肾亏湿着。治以养肝化湿束带，养肝血以制火，化湿热以束带脉，使带脉约束有权而赤白带自减。", []], "471": ["病机", "脉细小而弦，细小为营血不足，弦为肝气偏旺、胎气不宁。妊娠四月，腰为肾府、胎系于肾，肾阴不足则冲任亦亏，故腹痛坠胀、腰酸流红。脉症合参，系胎气不固、营失维护，虑其胎堕，急拟胶艾四物养血保胎，以固冲任。", ["细", "小", "弦"]], "472": ["病机", "脉弦小而数，弦为肝火，小为营血不足，数为热象。怀麟七月，太阴司胎，燥邪引动肝火，由气入营，血得热妄行而流红甚多。脉数主热，弦主肝，小示阴血耗伤，故虑热伤胎元致小产，治以养营泄热、滋水清肝润肺。", ["弦", "小", "数"]], "473": ["病机", "脉濡滑而数，濡主湿、滑主痰、数主热，合为风温疫疠之邪蕴袭肺胃。疫喉痧布而不透、咽喉焮红，正邪热郁蒸之象。怀麟八月腰酸流红，脉数示热盛，滑濡示痰湿内蕴，故以清温解疫为要，疫解则胎自安。", ["濡", "滑", "数"]], "474": ["病机", "脉濡迟，濡主湿浊内蕴，迟主寒与阳气不运。受寒停滞，脾胃为病，清浊混淆，故腹痛泄泻、似痢不爽、胸闷不纳。舌光无苔示胃阴亦伤。怀娠四月，脉迟濡示中阳困顿、湿浊不化，虑困泻动胎，故和中化浊佐保胎元。", ["濡", "迟"]], "475": ["病机", "脉象滑数，滑主痰热内蕴，数主火盛。牙齿属胃，胃火循经上升，风热未楚，故左颧肿退而右颧漫肿又起，内热口干、心中𩠎杂。怀麟足月，滑数之脉正示胎火内炽，故拟辛凉清解以清胎热。", ["滑", "数"]], "476": ["病机", "脉弦小而滑，弦为肝火，小为冲任亏损、气血不足，滑为血热。漏红五六次、腹大乳不胀，脉小示血虚不能养胎，弦示肝火入营、血热妄行，故胎萎不长、不能依期而产。治当益气养血、清营保胎，使气摄血、血荫胎。", ["弦", "小", "滑"]], "477": ["病机", "脉象弦滑，弦主肝虚，滑主湿浊。妊娠九月便溏旬余、漏红色紫，乃肝虚不能藏血、脾虚不能统血，中焦变化之汁随湿浊下注。舌苔薄腻亦湿浊之征。脉弦滑示肝脾两虚兼湿浊内停，故宜培养中土、化湿浊，健运复常则胎元易充易熟。", ["弦", "滑"]], "478": ["病机", "脉弦滑，弦主风动，滑主痰瘀。新产五日气血亏耗，腠理不固，外风引动内风入于经络，风性上升，宿瘀随之蒙蔽清窍，故痉厥不语、神识时明时昧。弦滑之脉正示风痰瘀浊上扰，症势重险，故拟和营祛风、清神化痰。", ["弦", "滑"]], "479": ["病机", "脉细小，细主阴血亏少，小主气虚不振。血藏于肝、赖脾统之、冲任摄之，今肝肾两亏、气不固摄，故脉见细小。此脉示气血两虚、统摄无权，当培养肝脾、调摄冲任，以八珍汤加减益气养血。", ["细", "小"]], "480": ["病机", "脉细如丝，为血去阴伤、脉络不充之象。新产去血过多，阴血亏虚不能充盈脉道，故脉细如丝；阴不抱阳，阳不摄阴，浮阳上越则头眩眼花、神昏气喘，自汗肢冷乃阳失温煦。此脉示气血涣散、阴阳脱离之危候，属血脱重症。", ["细"]], "481": ["病机", "脉弦紧主宿瘀内阻、气机不畅，右濡细则营血亏虚兼挟湿下注。产后营血已亏，宿瘀未楚，瘀阻胞宫则腹痛；湿注膀胱，宣化失司，故小溲淋漓。弦紧为瘀滞之征，濡细为血亏湿困之象，合示营亏瘀湿互结之病机。", ["弦", "紧", "濡", "细"]], "482": ["病机", "脉濡软而滑，濡软主脾虚湿盛，滑主水湿痰饮内停。产后肺脾两亏，肃运无权，脾虚生湿，湿郁生水，水湿泛滥则遍体浮肿；肺为水之上源，不能通调水道，聚水为肿，肺病及肾，肾气不纳则喘不得卧。此脉示水湿内盛、肺脾肾同病之喘肿重症。", ["濡", "软", "滑"]], "483": ["病机", "脉濡数，濡主湿浊，数主热邪。新产后气血已亏，恶露未楚，感受时气氤氲之邪，引动先天蕴毒，由内达外，天痘已布尚未灌浆，身热骨楚，苔薄腻。濡数为湿毒蕴热之象，正虚不能托邪外出，故拟益气托浆、和营祛瘀，以扶正达邪。", ["濡", "数"]], "484": ["病机", "脉数主热，此产后发热不退，苔黄脉数，乃风温伏邪蕴蒸气分，肺胃两经受病。产后气血已亏，宿瘀留恋，伏邪不达，邪与虚热相搏，故身热更甚。前投解肌药不效，因正虚不能托邪外出。脉数示邪热内蕴，正虚邪恋之病机。", ["数"]], "485": ["病机", "脉细涩，细主阴血亏虚，涩主瘀血内阻。产后阴血已亏，不能营养经脉，邪风入络，络有宿瘀，不通则痛，以致手不能举、足不能履、肢节痹痛。细涩之脉正合血虚络瘀之病机，故治宜养血祛风、去瘀通络。", ["细", "涩"]], "486": ["病机", "脉弦细而紧，弦紧主痛、主瘀滞，细为营血已伤。产后五朝，营血亏虚，宿瘀交阻，上冲于胃则泛恶，凝滞于中则气机窒塞，不通则痛，故腹痛阵作拒按。此脉示营伤瘀阻、气机壅塞之病机，治当和营去瘀。", ["弦", "细", "紧"]], "487": ["病机", "脉象濡缓，濡主湿、主虚，缓主脾土薄弱。新产后营阴亏耗，恶露未楚，旧患便溏，脾土薄弱，胃呆纳少，舌苔薄腻。濡缓之脉示脾虚湿困、营阴不足之病机，新邪旧恙并存，故治宜和营生新、扶土和中兼顾。", ["濡", "缓"]], "488": ["病机", "新产三朝，营血亏而恶露未楚，氤氲之邪乘虚袭表，营卫循序失常。脉弦滑带数，弦主邪郁气滞，滑为痰瘀内蕴，数示邪正相争、营血不足而生内热。寒热头痛骨楚为外邪未解，胸闷不食、舌苔薄腻为痰滞中阻，故以疏邪外达、祛瘀生新并治。", ["弦", "滑", "数"]], "489": ["病机", "新产五朝，寒热轻而复重，恶露未止，脉仍弦滑带数。弦滑示宿瘀留恋、痰滞内阻，数主邪郁化热。氤氲之邪挟痰滞交阻阳明，故胸闷不食、舌苔腻布、头痛骨楚。脉象不缓而数，说明邪滞未化、正气尚能抗争，仍当疏散消滞兼祛瘀生新。", ["弦", "滑", "数"]], "490": ["病机", "新产八朝，形寒身热有汗不解，脉弦滑带数。弦为少阳枢机不利，滑为宿瘀痰滞未楚，数示邪郁化热。客邪移于少阳，营卫失常，故寒热往来、胸闷饥不思纳、渴不多饮、苔薄腻而黄，有转疟之机。脉数不退提示邪势鸱张，还虑缠绵增剧。", ["弦", "滑", "数"]], "491": ["病机", "产后两月营阴未复，重感新邪、内停宿滞，肺胃为病。脉左弦右濡，左弦主肝气郁滞、邪阻气机，右濡主肺胃气虚、湿滞内停。形寒身热有汗不解、脘痞作痛、纳少泛恶、咳嗽、经行色紫，皆标邪鸱张之象。脉濡非纯虚，故不可见虚投补，当疏邪消滞、和中祛瘀。", ["弦", "濡"]], "492": ["病机", "二诊寒热渐解而脘痞作痛、咳嗽痛剧、纳少泛恶、小溲短赤、经行色紫，脉左弦右濡。左弦为肝气横逆，右濡为肺胃肃降失司、营阴未复。外邪宿滞未净，挟肝气上逆犯肺，故咳则痛剧。脉象较前合度，仍宜宣肺化痰、理气畅中，使气机畅则瘀滞自化。", ["弦", "濡"]], "493": ["病机", "产后二十四天，营血已虚，恶露未楚。脉象濡细，濡主卫虚气弱、湿滞不化，细主营血不足、脉道不充。卫虚失外护故畏风怯冷、有汗不解；营虚失内守、肠中津液枯槁故旬日未更衣、腹痛隐隐、纳谷减少、舌无苔。此虚多实少，治当养营祛瘀、和胃润肠。", ["濡", "细"]], "494": ["预后", "产后八旬，寒热匝月，痰多纳减，脉象虚弦而数。虚为气虚营弱，弦为脾弱木乘、气机不舒，数为营虚生热、虚阳不敛。气虚则寒、营虚则热，胃虚纳减、脾弱痰多，正虚邪恋日久，势成蓐痨。脉虚弦而数示正气已亏而虚热未清，故拟八珍汤加减扶正，以望转机。", ["虚", "弦", "数"]], "495": ["病机", "新产十一天，恶露不止、少腹作痛，为宿瘀留恋下焦；咳嗽声音不扬，为风寒包热于肺。脉浮濡带滑，浮主邪在表、风寒外束，濡主产后营卫俱虚、湿滞，滑主瘀血痰浊内蕴。脉证相参，属虚实夹杂、瘀与邪并存，故拟祛瘀生新、开胃化痰，标本兼顾。", ["浮", "濡", "滑"]], "496": ["病机", "脉象濡缓，濡主湿、缓主虚，合之则示气虚血亏而痰湿内蕴。疮口深陷不起、根散漫不收，正因气血不足不能托毒外出；舌光红为阴血亏耗，痰湿蕴结致营卫不从，故脉见濡缓而非洪数，症势重险。", ["濡", "缓"]], "497": ["病机", "原文未识脉名，但言脑旁属太阳寒水之府，体冷质沉，花甲气血已亏，体丰多湿，湿郁生痰，风寒外侵、七情内动，痰湿互阻太阳之络，营卫不从，疽遂成。所喜红肿高活，尚属佳象，示正气尚能抗邪。", []], "498": ["预后", "脉细为气血两衰之象，合之色黑平塌、神糊、汗多气急，显系阴阳两损、肝肾俱败。疡症七恶已见，脉细无力正应正气溃败不能托毒，故断为虽华佗再世亦谢不敏，勉方冀幸而已。", ["细"]], "499": ["预后", "服药后神清思食似佳，然脉象弦硬，弦为肝旺，硬为胃气衰败、真脏脉见，乃孤阳反照之兆，非正气来复。故曰不足恃也，勉宗前法以冀万一，示预后不良。", ["弦", "硬"]], "500": ["病机", "原文言脉络空虚，非具体脉名，故脉象要素为空。骨槽风肿硬不痛、牙关拘紧缠绵二月，位在少阳少血多气之脏，脉络空虚则风寒乘隙而入，痰瘀凝结，属阴症，徒恃清凉无益，法当温化。", []], "501": ["病机", "脉濡小而数，濡小为气阴两伤，数为伏热内蒸。骨槽痈溃久，少阴伏热上升致喉痹燥痛、蒂丁下坠，咳嗽痰红，舌红绛，手足浮肿气喘，乃肺络损伤、子盗母气、脾土薄弱，治肺碍脾、治脾碍肺，棘手重症。", ["濡", "小", "数"]], "502": ["病机", "脉数主热，痘疹后热毒内蕴肾胃两经，牙龈属胃、齿为骨余，故牙疳腐烂、苔黄。热毒炽盛故脉数，听其漫延恐有穿腮落齿之险，治以芦荟消疳饮清阳明而解热毒。", ["数"]], "503": ["病机", "左弦数右濡数，弦数为伏温化热、肝胆火升，濡数为湿痰内蕴。重感氤氲之邪引动伏温，外发温毒，满面红肿、耳根结块，胸闷纳呆、苔薄腻微黄，正合弦数主热、濡数主湿痰，故虑其缠绵增剧，拟清解伏温而化痰瘀。", ["弦", "数", "濡", "数"]], "504": ["病机", "脉左弦数右濡数，弦主少阳，数主热，濡主湿。伏温时气客于少阳阳明之络，温从内发，故寒热日发、满面肿红焮痛；胸闷不思饮食、苔薄腻为湿阻中焦。右濡数示湿与热合，左弦数示少阳枢机不利。体质虽虚，脉未现虚象，故不可滋养，恐留邪。", ["弦", "数", "濡", "数"]], "505": ["病机", "左弦数右濡滑，弦数主少阳余温，濡滑主痰湿中阻。大头瘟后头面红色未退、睡醒烘热，为余温留恋少阳阳明，引动厥阳升腾；痰湿阻于中焦，阳明通降失司，故纳少溲赤、苔干白而腻。滋阴则留邪，燥湿则伤阴，故以清泄伏温为主，宣化痰湿佐之。", ["弦", "数", "濡", "滑"]], "506": ["病机", "左濡小右濡滑，濡小示阴分本亏、肝经气火易升，濡滑示湿痰中阻。面部红色渐退而烘热形寒时作时止，为络中蕴湿未楚、营卫失其常度；胸闷纳少、舌中微剥后薄腻，为胃失降和、阴伤湿恋。故拟清泄厥阳、和胃化痰，待伏温肃清后再滋阴潜阳。", ["濡", "小", "濡", "滑"]], "507": ["病机", "脉郁滑而数，滑主痰湿，数主热，郁示邪阻气机。风温疫疠客于上焦，化热蕴蒸阳明，故头面焮红肿痛、壮热口干、溲赤便结、苔薄腻。风属阳，温化热，如烟如雾弥漫清空，症非轻浅。脉滑数示疫邪化火与痰湿交阻，故拟普济消毒饮加味，清彻风邪而通腑气。", ["滑", "数"]], "508": ["病机", "脉洪数，洪为阳明热盛，数为邪火内炽。时气疫疠客于上焦，疫邪化火传入阳明之里，津液已伤，厥阳独亢，故头面肿红焮痛、壮热口渴、头痛如劈、入夜谵语、舌灰糙。洪数之脉示热势鸱张而津伤，颇虑昏厥，故亟拟生津清温以制其焰。", ["洪", "数"]], "509": ["病机", "脉弦主少阳胆火。瘰疬发于耳后，头痛，为少阳胆火上升，挟痰凝结于络。弦脉应肝胆，火升痰凝则结块成疬，故以清解化痰为法。此脉弦与瘰疬、头痛相应，示病在少阳，非虚寒之弦。", ["弦"]], "510": ["预后", "脉数主内热，疬疡自颈窜至胸膺，胛窝破深溃大，内热脉数，经闭食少，势入损门。数脉示阴亏火旺，溃深经闭食减为肝脾肾俱损之象，故曰难治，急拟养阴清热以遏其势。", ["数"]], "511": ["病机", "脉干涩，涩主血少精亏。瘰疬窜发，未溃肿硬、已溃脓少，经停半载，寒热食减，为肝脾肾三经精血大亏，血脉干涩，经水不通，气不行而瘰疬成。涩脉示精血枯涸，故当补益三阴，怡养性情。", ["涩"]], "512": ["病机", "原文未出脉名，仅言「阴血亏耗，营卫不能流通」。阴虚则脉络失濡，痰热乘虚结于颈项、结喉，故痰核破溃；营卫不通则胻骨肿痛、四肢酸楚。病机为阴亏为本、痰热阻络为标，属虚实夹杂之证，故拟养阴清络，养阴以固本，清络以祛痰热。", []], "513": ["病机", "脉象虚弦，虚为督阳已衰、气血不足，弦为痰湿蕴结、营血凝塞之象。原文谓「督阳已衰，太阳主寒水之化，痰湿蕴结，营血凝塞，此阴疽也」，正合虚弦之脉：正虚无力托毒故疮顶深陷、脓少，痰湿凝滞故肉坚肿。治当助督阳托毒、和营化湿。", ["虚", "弦"]], "514": ["病机", "脉象濡滑，濡主少阴阴阳本亏、气血不充，滑主痰湿蕴结。原文言「少阴阴阳本亏，痰湿蕴结太阳之络，营卫凝塞，肉腐为脓」，正虚故疮顶不起、脓不多，痰湿凝滞故四围肿硬色紫。前投助阳托毒和营化湿尚合度，仍守原意，脉证相符。", ["濡", "滑"]], "515": ["病机", "脉象虚弦而滑，虚弦应少阴阴阳本亏、正气不足，滑应痰湿凝结。原文谓「痰湿凝结太阳之络，营卫循序失常」，腐肉渐脱、脓渐多而脉仍虚弦滑，说明正虚未复、痰湿未尽。故仍拟助阳益气、化湿托毒，冀正气充足则脓易外泄，脉象示邪正消长之势。", ["虚", "弦", "滑"]], "516": ["病机", "脉虚滑，虚为少阴阴阳两亏、气血不足，滑为痰湿稽留太阳之络。原文言「痰湿稽留太阳之络，营卫循序失常」，腐肉渐脱、脓多、根脚肿硬收，而脉仍虚滑，示正虚未复、湿浊未清；饮食喜甜为中虚之征。故再拟助阳益气、化湿托毒，佐和胃之品。", ["虚", "滑"]], "517": ["病机", "左虚弦右濡滑，左脉候少阴阴阳两亏、虚而兼弦，右脉候脾胃，濡滑为蕴毒痰湿稽留、脾运失职。原文谓「蕴毒痰湿，稽留太阳之络，脾胃运化失其常度」，故胃纳不旺而脉见右濡滑。腐脱脓多、根脚松而脉象未和，示正虚湿恋，再拟益气托毒和胃化湿。", ["虚", "弦", "濡", "滑"]], "518": ["病机", "左虚弦右濡滑，与五诊同，示少阴阴阳两亏未复、蕴毒痰湿留恋。原文言「蕴毒痰湿留恋，一时未易清沏」，虽腐肉已去其半、脓多、根脚松，而胃纳不旺、脉仍虚弦濡滑，说明正气尚虚、湿毒未净，故再拟益气托毒、和胃化痰，守方缓图。", ["虚", "弦", "濡", "滑"]], "519": ["病机", "左濡弦右濡滑，濡主气血两亏，弦主余毒蕴结，滑主湿浊未楚。原文谓「气血两亏，脾胃不健，余毒蕴湿未楚」，故腐肉去半、根脚渐平而纳谷不旺、足跗浮肿、牙龈虚浮，皆脾虚湿泛之征。脉象示正虚湿恋，再拟益气托毒、崇土化湿，培土以制水湿。", ["濡", "弦", "滑"]], "520": ["病机", "脉左虚弦不柔，虚为气血两亏，弦不柔乃肝失濡养、浮火易升之象；右濡滑，濡主脾弱，滑主湿浊留恋。合之牙龈虚浮、足跗微肿，正是脾弱清气下陷、余毒留恋之征，故断为气血两亏、浮火易升、脾弱湿恋之病机。", ["虚", "弦", "濡", "滑"]], "521": ["病机", "左虚弦右濡滑，虚弦为气血两亏、津少上承，濡滑为脾胃不健、运化失常。纳谷不香、牙龈虚肿、面部虚浮，皆脾虚湿泛、清阳不升之候，脉证相合，故主气血两亏、脾胃不健之病机。", ["虚", "弦", "濡", "滑"]], "522": ["病机", "左虚弦右濡滑，虚弦示气阴两亏、无根之火易升，濡滑示脾胃不运、湿浊留恋。口舌糜点、牙龈肿痛为虚火上浮，便溏似痢、苔腻为湿浊内蕴，脉证互参，主气阴两亏、虚火上升、湿浊留恋之病机。", ["虚", "弦", "濡", "滑"]], "523": ["病机", "左脉弦象略缓，是肝阳渐平之兆；右部濡滑，仍主脾胃运化无权、湿浊未净。口舌糜点碎痛、牙龈虚浮，为虚火挟湿浊上浮；纳少苔腻，脾运未复。脉象示气阴两亏、虚火湿浊上浮之病机。", ["弦", "缓", "濡", "滑"]], "524": ["病机", "左寸关弦数不静，弦为肝阳旺而易升，数为阴液亏而难复；右寸关濡滑而数，濡滑主痰湿内蕴，数主虚热。乳岩肿硬、舌苔剥绛、睡醒遍体酸疼，皆阴亏血不养筋、营卫不得流通之候，脉证合参，主阴亏肝旺、血不养筋之病机。", ["弦", "数", "濡", "滑"]], "525": ["病机", "尺部细弱，为阴液亏耗、肾血不足；寸关弦细而数，弦主肝横，细数主血虚生热。舌红绛、遍体酸痛、腰膝尤甚，皆血不养筋、筋热络痛之征；腑行燥结、小溲淡黄，亦阴亏热郁之象。脉证相合，主阴血亏耗、肝横热郁之病机。", ["细", "弱", "弦", "数"]], "526": ["病机", "左弦数，弦为肝阳化风，数为热；右濡数，濡主痰湿，数主虚热。乳岩起病阴血亏虚，肝阳化风入络则肢节酸疼，心悸气逆、音声欠扬为痰热内扰，舌光红苔薄腻黄亦阴亏痰热之征，脉证合参，主阴亏肝风痰热夹杂之病机。", ["弦", "数", "濡", "数"]], "527": ["病机", "脉象濡软，濡主湿，软为气血不足之象。肝疽肿硬疼痛大减，是药已见效；然神疲肢倦、形肉削瘦，脉濡软，正合气血两亏、痰湿未能尽化之病机，故仍守益气消托原意。", ["濡", "软"]], "528": ["病机", "脉象濡细，濡主湿，细主虚。肺疽已成，漫肿疼痛，胸闷气结，汗多肢冷，乃风邪痰瘀蕴结肺俞，酿脓伤正，清肃失令。脉濡细反映正虚湿滞，气血不足，故虑虚脱之变。", ["濡", "细"]], "529": ["病机", "脉濡滑，濡主湿，滑主痰。外痔痛止而脱肛未收，苔薄腻，乃气虚不能收摄，阴虚湿热下注，大肠传导乏力。脉濡滑正合湿浊内蕴、气虚不运之机。", ["濡", "滑"]], "530": ["病机", "脉象濡滑，濡主湿，滑主痰。缩脚阴痰溃而未得脓，根脚肿硬疼痛，痛引少腹，小溲不利，腑行燥结，身热晚甚，口有甜味，苔薄腻，乃蕴湿缩瘀凝结厥阴之络，营卫不从。脉濡滑为湿瘀内阻之征。", ["濡", "滑"]], "531": ["病机", "脉弦小而迟，弦主痛主饮，小主虚，迟主寒。缩脚阴痰肿硬疼痛，上及少腹，下及腿侧，皮色不变，右足曲而不伸，寒热晚甚，苔薄腻，乃寒湿痰瘀凝结厥阴之络，营卫不从。脉弦小迟为寒湿痰瘀内结之象。", ["弦", "小", "迟"]], "532": ["病机", "原文仅言“脉之空虚”，未列具体脉象，故脉象要素为空。此段论精气神三宝，气阴两亏，坎离失济，心虚易动，肾虚不藏，神动精驰，致梦遗旧恙。久遗肾阴大伤，骨髓空虚，故脊痛腰酸在所必见。脉空虚正合精亏气弱之机。", []], "533": ["病机", "脉左关沉微而缓，右部虚浮。沉微缓主虚寒，浮主虚阳上浮。经漏百日，淋带不止，冲任督带不能固摄，病在下焦，阳升于上，阴亏于下。食减味少，胃气孱惫，故补中益气仅升脾营，滋阴又碍胃衰。脉象反映下元虚衰、虚阳上浮之机。", ["沉", "微", "缓", "浮"]], "534": ["预后", "脉百至，数促而芤，脉气震动。数促主热主虚，芤主失血伤阴。劳损数年，寒热大汗泄越，卧枕嗽甚，谷食大减，大便不实，乃下焦损伤冲脉之气震动，诸脉皆逆。胃气戕害，生阳不发，入冬可虑，故急固散越之阳。", ["数", "促", "芤"]], "535": ["病机", "原文未识别出脉名，故脉象要素为空。稚年纯阳体质，热症最多。病偏右胸高，呼气不利，肺气不能清肃，热郁内蒸，逆传膻中，状若痫症。肺主卫，心主营，营卫失和，越日触遇乃发。肺热壅塞，脏腑柔薄，苦寒沉降及腻滞阴药俱在禁例。", []], "536": ["病机", "脉小右弦，小为阳气衰少，弦主饮邪内停。原文述暴寒内入，阳气痹塞，水液化痰上泛，痰饮逆阻，故脉见小弦。症见呼吸不利、喉中有声、入夜神迷，皆痰饮上蒙、阳气不宣之象，与脉相应。", ["小", "弦"]], "537": ["病机", "原文未识脉名，然述尾闾尻骨先痛、溲溺淋闭兼瘀血，乃督脉与太阳脉络气坠不行，瘀血内阻，水道不利。病位在督与太阳，气化失司，故见淋闭疼痛，治以升任督之气、软剂温药，从脉症合参而知其病机在气陷血瘀。", []], "538": ["病机", "新产不满百日，天暑汗泄，澡浴汤蒸更助开发，阳浮左升，阴弱莫制，故喉痒咳逆、胁背皆痛。产后肝血未充，肾液未足，奇经怯弱，阴亏阳炽，血不荣筋，脉虽未识，病机为阴亏阳浮、奇经失养。", []], "539": ["病机", "肝阴少藏阳气，有升无降，暮夜咳甚如哕，戌亥肝阴旺时肝阳扰胃，阳明脉衰，故四肢倦怠、面青晦，阳化内风，掀越鼓动为肌浮偏肿。病机在肝阴不足、阳升无制、内风扰胃，非独咳嗽为患。", []], "540": ["病机", "久有胃痛，服资生丸消补相投，八味丸温润不合。今痛止不纳，口味酸浊，躁热头汗，口不渴饮，乃胃伤困乏，清阳不司旋运，清浊乱于中，上下不宣，状如关格而非阴枯阳结。病机在胃气伤困、清浊失序，故以大半夏汤图清气宣通。", []], "541": ["病机", "脉左数微弦，寸尺关虚数。数主热，弦主肝郁，虚为阴不足。原文述肝郁成热，热迫气逆血瘀，曾吐瘀血；肝阴不充，肝阳易动，升多降少，阴不和阳，胃津乏上供涵肺，故燥痒咳呛、吐涎沫。脉症合参，病机为肝阴不足、肝阳逆乘、木犯胃土。", ["数", "弦", "虚"]], "542": ["病机", "脉刚而数，刚为邪实内结，数为热盛。暑湿久伏，与时气秽邪凝合，酿成胶腻之痰，闭塞清明之府，故神呆目定、烦躁呓语；胃家浊液蒸遏不宣，舌苔黏腻。湿位之下燥气乘之，湿转燥，先滋液以洁烈焰之燔。病机为暑湿痰浊蒙蔽、化燥伤液。", ["刚", "数"]], "543": ["病机", "脉沉而微，沉为里寒，微为无阳。舌白似粉，泻起口渴，身体卧著痛甚，交夏阴气在内病加，少腹至阴部位浊阴凝聚，是为疝瘕。病机为阴寒内盛、阳气衰微、浊阴盘踞，故当以纯刚药直走浊阴凝结之处。", ["沉", "微"]], "544": ["治法", "原文未识脉名，但述阴寒盘踞少腹，非纯阳刚剂不能直入坚冰之地，阴凝不解。此阴寒内盛，非温阳刚剂不解，故仿通脉四逆汤法。前医易肾气汤阴多阳少，立见病加不食，药不对症，反证阴寒之重，需纯阳刚剂破阴回阳。", []], "545": ["病机", "脉脉络空乏，乃阳气日薄，阳明脉络空虚，不能束筋骨流利机关，故肩痛肢麻、头目如蒙、行动痿弱。此下虚上实，络热内风沸起。入夏阳升为甚，渗湿利痰不应，议清营热以泄内风。空脉主气血不足，络脉失养。", ["空"]], "546": ["病机", "原文未识脉名，述下体痿躄，先有遗泄湿疡，频进渗利，阴阳更伤。虽有参耆术养脾肺，未能救下。长冷阳微，饭后吐食，胃阳顿衰，卫外失职。下焦病属精血受伤，两投温通柔剂，以肾恶燥，久病宜通任督。通摄兼施，胃药另用，扶阳理胃，俾中下两固。", []], "547": ["病机", "脉已虚，长夏湿热，经脉流行气钝，兼下元络脉已虚，故痿弱不耐步趋，常似酸楚，大便或结或溏。都属肝肾为病，益下必佐宣通脉络，乃正治之法。恐夏季后湿热还扰，预为防理。虚脉主下元亏虚，络脉不充。", ["虚"]], "548": ["病机", "脉沉而缓，寝食如常，独两腿内外肉脱麻木，年逾五旬，阳脉渐衰，跷维不为用事，非三气杂感。沉缓主阳气渐衰，脉络不畅，故温通以佐脉络之流畅，仿四斤金刚之属。沉为在里，缓为阳衰，非外感三气。", ["沉", "缓"]], "549": ["病机", "原文未识脉名，述肾厥由腰脊而升，发时手足逆冷，口吐涎沫，喉如刀刺。盖足少阴经脉上循喉咙，挟舌本，阴浊自下犯上，必循经而至。仿许学士椒附汤，通阳以泄浊阴为主。此阴浊上逆，循少阴经犯喉，故见喉如刀刺。", []], "550": ["病机", "脉大便秘，疟得汗不解，近来竟夜汗出，胸痞不饥，形瘦。显然阴虚体质，疟邪烁液，致清阳痞结脘中。脉大主邪盛或阴虚阳浮，便秘为液耗。议以柔剂，存阴却邪。大脉在此示阴虚阳浮，邪热未清。", ["大"]], "551": ["病机", "脉微而迟，色衰萎黄。阳气不足，久利久泻，穷必伤肾。今浮肿渐起，目下是水失火而败。若非暖下，徒见泄泻有红，为脾胃湿热，必至中满败坏。微迟主阳气衰微，火不暖水，故浮肿。当暖下焦，不可误作湿热。", ["微", "迟"]], "552": ["病机", "左弦右浮涩，左弦为肝木拂郁，右浮涩为脾土自困、清浊混淆。始由脘痛贯胁，继则腹大高凸，纳食减少，二便艰涩，皆肝郁乘脾、胀势乃成之征。藏真日漓，府阳不运，故脉见弦涩，主虚症内伤胀满，非有形攻泻所宜。", ["弦", "浮", "涩"]], "553": ["病机", "脉缓弱，缓为脾土本脉，弱则阳气衰微。脘中痛胀、呕涌清涎，是脾胃阳微，得之积劳，午后病甚，阳不用事。脉缓弱正合脾阳宜通、温补极是之旨，而守中腻滞非通府，故勿佐用。", ["缓", "弱"]], "554": ["病机", "脉来小缓，按之不鼓，小为正气不足，缓为热邪内伏而非外感。身腴过劳，阳气受伤，呕吐食物，身热无头痛，间日烦躁渴饮，唇焦舌黑，是内伏热气由募原流布三焦。脉小缓不鼓，正征伏邪客病、两便颇通、略能纳谷，非停聚积滞。", ["小", "缓"]], "555": ["病机", "脉弦数右大，弦为肝病，数为热，大为阳化。舌绛面浮，咳呕上逆，心中热，腹中气撑，暮夜内外皆热，病因忧愁嗔怒，诸气交逆，少火化为壮火，玉液皆涸，内风煽动。见症肝病十之八九，病属郁劳，难以久延，故议咸苦清养厥阴之阴以和阳。", ["弦", "数", "大"]], "556": ["病机", "脉百至，右弦数，左细数，数为热，弦为厥阴，细为阴伤。寒热无汗，渴饮呕逆，病中咯血，经水反多，是邪热入阴，迫血妄行。平日奇经多病，内虚邪陷，厥阴热炽犯阳明，故呕闷不食、目胞紫暗、咽窒头痛。伏邪在至阴，必熬至枯涸，故咸味直走阴分，参苦寒清伏热。", ["数", "弦", "细"]], "557": ["病机", "右脉平和，左寸关弦动甚锐，弦动为木火之形，左寸关候心肝，木火内炽。面色带赤，体质清癯，禀多动之性，操持烦虑，五志之阳无有不炽，故寤多寐少，内风不熄，眩晕自生。谋虑不决则火动阴伤，肝阳独行，乏阴和协而魂不藏，寐不安，治以益阴和阳。", ["弦", "动"]], "558": ["病机", "脉弦数，弦为厥阴风木，数为热自内起。腹膨便泄，目自泪出，经来身体掣痛，今秋冬两月不至，缘情怀抑郁，热自内起，厥阴风木化火，阳明侵削，日迫气血内蒸，血海无贮，渐延干血劳症。久郁热胜，经阻有年，正气已亏，气血偏滞，非徒补可治，议厥阴阳明同治，酸苦泄热为先。", ["弦", "数"]], "559": ["病机", "脉小无神，小为中气不足，无神为正气虚馁。少年面色青黄，自幼频有呕吐，明是饮食寒暄不调，以致中气不足。咳嗽非外感，不宜疏泄，故以小建中汤主之，建中气以复脉之神。", ["小"]], "560": ["病机", "原文未出脉名，以“自觉热蒸，不梦自遗”言奇经虚。任督分行身之前后，奇经空虚则固摄无权，故热蒸、遗精不梦而作。辛湿药颇效，六味加五味子不应，因方药仅达下而未约束奇经，故议聚精固摄之法，此属奇经虚损、固摄失职之病机。", []], "561": ["病机", "脉弦促而芤，弦主肝郁，促为阳升气泄，芤示藏阴内虚。望色痿黄少膏泽、纳谷不旺，病已数年，春夏阳升偶加烦冗则血溢上窍，正是藏阴内虚、阳动乃溢之机。心主血、脾统血、肝藏血，三脏阴亏而阳扰，故血不循经上溢，非少壮阴火可比。", ["弦", "促", "芤"]], "562": ["预后", "服白通加人尿猪胆汁汤后“脉不微续，仍三五参差”，脉本微而欲续，今不能微续、三五参差，是阳气未复、脉气不续之象。原文断“尚非稳保”，说明浊阴蔽塞、通阳未效，病情尚险，故议用四逆通脉方再图温通，属预后判断。", ["微"]], "563": ["病机", "原文未出脉名，论疟久邪结必成疟母，邪深客于阴络，道路深远，故肌肤无汗、能食不运而便溺通调，病不在腑。从腹下升逆贯胁腰，推及八脉，是久疟入络、下焦痹阻之病机，故忆仲景转旋下焦痹阻、例以通阳为治。", []], "564": ["病机", "原文未出脉名，以“吐中有散”立论：多呕多吐则诸气升腾而散。厥阴风木久侵，中虚困穷，清空溃散，浊蒙蟠聚，故胸腹胀满、腰痹肌膜浮肿。因数日不食，阳明胃土伤疲已极，中无砥柱，木横浊攻，此非有余，乃虚症，故议通阳明兼泄厥阴。", []], "565": ["病机", "原文未出脉名，以眼胞上下为脾肾之脉循行之处，倦于开阖，断为“太阴脾脉已钝”。脾脉钝则运化无力，故甘补多用为宜。此从眼胞开阖推知脾脉虚钝，属脾虚病机，治以甘补健脾。", []], "566": ["病机", "脉弦右大，原文自释“弦则为饮，大则胃阳已虚”。操持萦思积劳阳伤，故不饥不食、勉纳不运、夜卧不安、腹鸣气震、四肢痿弱。阳虚为本，痰饮气逆因虚而聚，长夏湿土乘侮脾胃，虑肌肿腹胀，故议通补理胃阳为主、疏肝为辅。", ["弦", "大"]], "567": ["病机", "脉得右大，来去不整，左部小促。右大而来去不整，是阴气不复、阳气上冒之象；左小促示阴亏阳扰。结合小产之后耳聋、身热不寐、语言謇涩，非少阳伤寒，乃小产后阴气不复、惕气上冒，恐有牵搐暴厥之忧，故戒勿以轻浅视之。", ["大", "促"]], "568": ["病机", "脉右大能纳食，然《金匮》云“脉大为劳”，此大乃烦劳伤气，气浮于外，非实热也；又云“极虚亦为劳”，虚为情欲致损，精血内亏。秋暑失血，初春再发，阴损及阳，故脉见大虚。大与虚并见，示劳伤元气，形气不足，当安静调养，使气血渐复。", ["大", "虚"]], "569": ["病机", "内因之嗽由别经干连及肺，少阴脉循喉咙，阴乏上承，阳独自灼，故阴上阳下则寿，反则死。八味丸阴中之阳，然肉消形瘦，桂附刚燥，宜温和柔剂，取血肉有情之品，斑龙峻补玉堂关下，鹿角升督，青盐引下，此论肾虚冲阳上逆致嗽之病机。", []], "570": ["病机", "脉弱细不调，神采不振，呼吸带喘，素有寒疾气逆，宿饮蓄积。夏月脾胃主令，气泄于外，饥饱劳役伤中，减食胀满，气壅血瘀，胀势愈加。脉弱细为气血不足，不调为气机壅滞，此中焦虚而浊阴锢蔽，阳气不宣，故胀病淹淹，不可轻用攻劫。", ["弱", "细"]], "571": ["病机", "再诊脉神如昨，胸满胀更急，鼻尖冷甚，热汗出，吐瘀便垢，神衰吸短。此阳微浊僭，格拒不通，上下交征，当理其中。理中守剂不能治剧，故护阳通阳，参以苦寒，使浊阴泄一分，阳复一分，安谷之理在焉。", []], "572": ["病机", "经来渐迟色淡少，腹痛䐜胀，腰髀酸楚，脉数右小左大。数为血少生热，右小左大示冲任为他经之气所束，气机日钝，血少贮蓄。冲任隶属阳明肝肾，若暴怒则经漏沸溢，故用药择入奇经，两和气血宣通奇脉。", ["数", "小", "大"]], "573": ["病机", "寒入厥阴之脉，结为气疝，痛则胀升，气消绝无踪迹。老年下元已亏，不可破气攻疝。尿管痛或阻溺，乃下元虚寒，气化不利，温养下元，佐以通窍，使寒散气行，疝痛自缓。", []], "574": ["妇人", "寒少热多，先后厥之谓。热甚胎攻冲心痛，胎在冲，疟邪从四末渐归胃，冲脉属阳明胃脉管辖，上呕青黑涎沫，胎受邪迫上攻冲心。邪热无由发泄，内陷不已，势必坠胎。协热自利，外邪从里而出，故以酸苦辛泄两经热邪，井泥护胎。", []], "575": ["病机", "谋虑在肝，决断在胆，操持思虑，五志阳气有升无降，肝脉绕阴器，气逆拂乱，疏泄失权，似疝如淋。今形脉已衰当以虚论，肝病三法辛酸甘缓，食酸令人癃，小便不爽，大忌酸味，此肝虚气逆之病机。", ["衰", "虚"]], "576": ["病机", "原文述冲气上冲，肝脉必搏大无偏，面色赤亮，肌肉瘦削，乃肾精肝血内耗，阴不和阳，冲任不主把持。肝脉搏大无偏，为阴不制阳、冲气上逆之象，主内损精血、八脉失养，症见冲气上冲、面赤肌瘦，治当填实精隧、助阴抑阳。", ["大"]], "577": ["病机", "室女神志时惑、月事不来，原文引《内经》二阳之病发心脾，谓气逆血菀、经纬紊乱，日加郁痹。此非脉象所主，乃情志郁结致心脾受病、奇脉不通，故月事不来而神志惑乱，治当上清心窍、下调奇脉。", []], "578": ["治法", "原文仅载复脉汤去姜、桂，未述脉症。复脉汤本为气阴两伤、脉结代而设，去姜桂之辛温，意在减其温燥，偏于养阴复脉，属治法范畴，非直接论脉象所主病机。", []], "579": ["误治", "冒暑远行，热犯上中，分走营卫为寒热疟疾，当清疏胃气。奈何发散不效，复肆行滋补，致肺气壅闭、胃中凝滞，气机不通变成肿胀。此段述误治致变，非脉象主病，故脉象要素从缺。", []], "580": ["病机", "女科肝病为多，产后病及八脉，少腹瘕聚、冲气攻心、呕吐、经水不来、寒热，原文谓下焦多属血病，症属气聚，瘕为血痹，病在冲脉，阴阳维混混施治。此论奇经病机，非凭脉断症，故脉象要素为空。", []], "581": ["病机", "脉缓按之濡弱，谷少不食，厚味运化最迟，饮食不适即痛泻，肤腠麻木，骨软筋痛，遇暴风骤冷不安。缓而濡弱为气弱阳微、脾胃少于运化之象，湿郁生痰，气机不能灵动，故主脾阳不振、痰湿内阻诸症。", ["缓", "濡", "弱"]], "582": ["病机", "女子四十九天癸当止，阳明脉衰，冲脉力怯，不能招集诸络之血聚于血海。今带淋、肌麻血阻，脏阴内损及于八脉，有形之血去，无形之气掀旋，诸窍百骸攻迫肆症，乃阳气独行不得真阴眷恋，法当介用潜阳。", []], "583": ["病机", "三诊脉空虚，产后八脉空虚，固摄后精神向安，但寒在四肢背部、热在心前腹中，即阳虚外寒、阴虚内热之旨。脉空虚为产后气虚、阴分伤及阳位之征，故填补方中必佐收拾奇经散亡，补精以化气。", ["虚", "空"]], "584": ["病机", "右弦左濡，弦为肝木偏旺，濡为脾营先伤。久痔注血耗伤脾营，胃阳继困，府气不能宣畅，故纳食不易运化、大便不爽。东垣治土必先达木，不宜过投燥剂，正合此脉弦濡并见之肝郁脾困病机。", ["弦", "濡"]], "585": ["病机", "脉百至而左小涩结，右部弦大，小涩结为阴液枯槁、肠中气痹，弦大为浊阴渐阻。绿高年中焦清阳已微，致脘中窒塞、物不能纳、溺少便涩，正合虞花溪所谓噎膈反胃阴枯阳结、衰老难调之象。", ["小", "涩", "结", "弦"]], "586": ["病机", "右弦左濡，仲景论脉篇谓弦为饮，背寒为饮。秋凉宿饮上泛，乘暮夜窍发，故咳呛入夜、气冲胃脘、心悸震动必欲起坐。饮属阴邪，当治饮不当治咳，以通阳涤饮为法，用小青龙减麻辛，正合弦濡主饮之机。", ["弦", "濡"]], "587": ["病机", "频因小产，奇脉不固，经来甚多、经过带下，早震大便溏滑、纳谷日少、心悸震动。始养血滋腻即脘闷不思纳谷，此自下焦损伤渐及中焦，脾胃不能转运。脉象虽未明载，然病机在奇脉不固、中焦失运，故议宣通补中兼顾下焦。", []], "588": ["病机", "产育致虚，八脉皆空，损伤非在一脏一腑，故诸恙并起。脉空为虚损之征，稍涉情志不适药饵便少功效，沉痼宿恙骤难奏功。现腹胀洞泄、胁腹㽲痛，皆由内因虚损、八脉空虚所致，非一脏一腑之病。", ["空"]], "589": ["病机", "病久反复，精气损伤遂成虚怯。脐下闪闪升触、逆干咳嗽、痰多咽痹，明明元海无根、冲脉气震、无以把握，阴精内枯、阳乏眷恋。脉象虽未载，然病机在元海无根、冲脉不摄，非草木汤液所能久持，须静处山林屏绝世扰。", []], "590": ["病机", "脉来浮数，退而细涩。浮数为烦劳气损、血菀于上、气并于血，升降混淆为厥；细涩为阴精内枯、瘀聚胸膈。面黄唇白热势稍轻，神昏如故，目䆮舌缩为肾水竭绝，瘛疭不止乃肝虚风动，病名暴厥，即薄厥煎厥之类。", ["浮", "数", "细", "涩"]], "591": ["病机", "情志郁勃，气逆多升，络血上冒，连次小产则冲任已怯。心嘈震悸、目珠痛、头胀，皆肝胆厥阳动极所致。脉象虽未载，然病机在冲任怯弱、肝阳上冒，故用复脉汤去姜桂参加淮小麦、天冬、石决明，养肝阴兼通冲脉，防其倒经。", []], "592": ["病机", "脉弱为真气不足之象，交夏天暖，阳气外泄，真气随之外越，故脉弱。津液因热而伤，浮阳动搏，症见心热口渴、头痛胁疼、食下如噎、右耳气闭、语言过多、齿戛寒噤、巅胀面浮，皆津伤阳浮之候，故议甘凉生津和阳。", ["弱"]], "593": ["预后", "脉细小欲绝，乃阳气衰微、阴不内守之候。时令温邪内迫，经水不应期至而淋淋不断，二便不通，唇舌俱白，神呆恍惚，言语支离，值芒种夏至阳极泄越，阴未复而神魂不摄，故为亡阳昏谵，最属危脱之象，拟救逆法以扼其危。", ["细", "小"]], "594": ["病机", "原文未出脉象。经停两月，恰值嗔怒，阳气升降失和，血随气行冲任，脉络不固，遂为崩漏。血凝成大块，非血热宜凉；血脱必须益气，但冲任奇经在下焦，非升举诸法所宜，须固摄奇脉之药，乃能按经循络。", []], "595": ["病机", "脉右部向内极微而涩，右部主肺，微为阳虚，涩为血少，肺失濡养，故为水竭金枯之象。咳失音，乃肺金枯槁、津液不能上承所致，故姑变法治之。", ["微", "涩"]], "596": ["病机", "原文未出脉象。酒湿侵络，肩髃酸麻，留著不去，肺受其伤，痰中带血。络脉既伤，郁而成热，故清补不可废，示人于化湿通络中兼清郁热、补伤损。", []], "597": ["主病", "脉数久咳，气急内热盗汗，数脉主热，久咳肺伤，内热迫津外泄则盗汗，气急为肺失肃降。此虚损之候，故用虚损法，以补虚清热、敛肺止咳为治。", ["数"]], "598": ["病机", "脉左涩滞，右弦滑。左涩滞为肝郁不舒，右弦滑为饮邪内停。饮邪为患，肝郁不舒，燥药治水则伤阴，滋药养肝则滞饮，故用加减当归四逆，养肝利水、健脾运痰，以两顾其病机。", ["涩", "弦", "滑"]], "599": ["病机", "脉小微数，真阴不足。小为阴亏，微为阳弱，数为虚热。今既见血，旋覆咳嗽，久烁肺金，阴亏火旺，故温燥不可进，姑从金水二藏治之，以滋水清金为法。", ["小", "微", "数"]], "600": ["病机", "右部虚软无力，右脉主气主脾，虚软为正气不足、藏真亏损之象；左足内踝为足三阴经脉所行，肿胀渐大而脉不应实，说明非实邪壅滞，乃三阴虚损、气不运化所致。脉症合参，断为藏真亏损，故议峻补，以复三阴之虚。", ["虚", "软"]], "601": ["病机", "左脉弦，右关亦见弦象，弦为肝木之脉。左候肝血，右关候胃，两处皆弦，说明肝火偏旺、木乘胃土，胃脘之病由肝火引起；弦主疏泄太过，血随气下，故言「血之下也」。病机在肝胃同病，治当两调肝胃。", ["弦"]], "602": ["病机", "右尺举按少力，右尺主肾中真阳，少力为真阳不足、脉象不鼓；左关弦为肝火易动，疏泄太过则精泄不固。原文又言心火不降则不交，少阴之枢窒，说明真阳不足与心火不降并存，枢机不利，故从两经论治方合病机。", ["弦"]], "603": ["病机", "足冷肢麻、面有风块、恶风，而脉沉细。沉为病在里，细为血虚阳弱，阳气不能温达四末，故足冷肢麻；卫外不固则恶风、面起风块。前服方滞而少通，说明络脉痹阻、寒凝血脉，宜当归四逆汤温经通脉。", ["沉", "细"]], "604": ["病机", "原文仅言「冲脉为病，治宜镇逆」，未出脉象。冲脉起于下焦而上行，冲气上逆则为病，故治法取镇逆降冲。此段主旨在于申明冲脉病的病机与治则，脉象无从取，故脉象要素为空。", []], "605": ["病机", "木火旺令，肝木乘阳气之浮，直冲清道，血遂上溢。左部弦急，弦为肝脉，急为气火亢盛之象，说明肝火挟冲气上逆，迫血妄行。脉症相应，病本在肝，故宜从肝治，清降肝火以平上溢之血。", ["弦", "急"]], "606": ["病机", "脉数而肌肉消烁、痰咯不和，数主热，热灼肌肉则消瘦，灼津为痰则咯痰不爽。脉数而形损，正气已伤，故言有虚损之象。此非纯实，先进清补之剂，清其虚热、补其耗损，标本兼顾。", ["数"]], "607": ["病机", "左胁掣痛、筋脉不舒，原文未出脉象。左胁为肝之分野，筋脉不舒、掣痛，由络脉空虚、气攻所致，属络虚气滞之病机，非实邪结聚。故脉象要素为空，主旨在于说明胁痛筋急的络虚气攻病机。", []], "608": ["病机", "右脉虚软，虚为阳气不足，软为脉道弛缓，合而示真阳式微，不能温煦推动。阴寒凝聚成瘕，上攻为痛，正因阳衰寒凝，气血滞涩。脉症相参，此非辛温通阳不能破阴寒、复阳气，故曰“非辛温通阳弗效”。", ["虚", "软"]], "609": ["病机", "原文未及脉象，专论足筋不舒为湿邪所阻，络脉壅滞。湿性重浊黏滞，阻遏经气，故筋脉失舒；今发疮，是湿邪外泄之径，即“湿邪疏泄处”。此段重在湿阻络滞之病机，非凭脉断证。", []], "610": ["病机", "脉肝部不和，肝脉当弦而失和，示厥阴气机郁滞。食入窒塞且响、少腹微痛，皆肝气横逆、疏泄失常所致。肝郁则木不疏土，故食塞；气滞少腹，故微痛。治用温通厥阴，正合脉症。", ["弦"]], "611": ["病机", "左关候肝，脉左关弦，弦为肝脉，主气机劲急。此独见于左关，是肝火内郁、木气偏亢之征，故曰“全是肝火为患”。火灼肺金，故仿喻氏清燥救肺法，清肝润肺以平木火。", ["弦"]], "612": ["病机", "脉三五不调，短而微数，按之不鼓，短微为阳气衰少，数而无力为虚阳外浮，按之不鼓更示真阳式微、气不下潜。虚里振动，是宗气不敛、虚阳上扰之象。故宜温补中佐镇摄，以纳浮阳。", ["短", "微", "数"]], "613": ["治法", "脉挛急，指脉道拘紧不柔，为营血亏虚、筋脉失养之征。血虚不能濡脉，故脉急；筋脉挛急，亦因营亏。治宜养营，营血充则脉道柔、筋脉舒。此段以脉测营虚，主在治法。", ["急"]], "614": ["病机", "右脉细而急，细属木体之虚，即肝血不足、脉道不充；急则肝火之动，火性劲急。肝火犯肺，气逆上冲，故鼻衄气逆则嚏甚，是其明征。脉细急并见，示肝虚火动、气逆血溢之机。", ["细", "急"]], "615": ["主病", "久咳音嘶、痰中带红，脉右数。右脉候肺，数主热，肺热阴伤，灼津为痰，损络出血，故痰红；久咳肺损，金破不鸣，故音嘶。右数一脉，点明肺热阴伤之主病机。", ["数"]], "616": ["病机", "脉迟涩为阳虚之征：迟主阳不胜阴，涩主血少气滞。原文以目光应阳火，谓目病不尽属阴亏，亦有阳弱，寒水翳膜如云雾阴霾，正合阳虚水泛之机。迟涩示阳气不能温运，故断为阳虚，阴药不可用，须变法温阳。", ["迟", "涩"]], "617": ["病机", "脉弦数，弦为风木之象，数为阳动之征。原文谓风邪尚未寂静，闪烁无定，乃阳动而阴不能制，介类潜阳、参耆苓术建中后脉仍弦数，说明风阳未潜、阴不制阳，故仍用前方增损以消息病机。", ["弦", "数"]], "618": ["病机", "脉弦为肝木之象，月余不退，知肝木偏旺，未免侵克脾胃。胃腑以通为补，肝主疏泄，木旺则疏泄失常、胃气受制。故议两和肝胃，既平肝木之弦，又通降胃腑，使木不克土。", ["弦"]], "619": ["病机", "原文未识脉名，以三疟既久，项酸腰似折，断为督脉惫矣。疟久耗伤精气，督脉循项背腰脊，精亏则项酸腰折，故宜治少阴，补肾填精以充督脉。此段由症推机，非凭脉断。", []], "620": ["病机", "脉微涩，三五不调，微为阳衰，涩为精少，三五不调示脉气不续。原文谓先天禀赋不充，当壮盛之年而肾阳衰惫，水乘上泛，饮邪充斥。阳衰不能化水，水饮上泛，故宜崔氏八味加味以祛饮。", ["微", "涩"]], "621": ["病机", "脉数而细，数为阳热，细为阴血不足。原文谓喘急咽干，属金枯水亏之象：肺金枯槁则喘急，肾水亏乏则咽干，数细之脉正合阴虚火动、金水两伤之机。", ["数", "细"]], "622": ["病机", "脉数，咳嗽不止带血，湿热下注成漏，便溏泄。数主热，热灼肺金则咳血，湿热下注则漏，便溏泄示脾阳亦弱。原文谓所赖胃气尚强，故壮水清金不得有碍脾阳，以资生之本在胃。", ["数"]], "623": ["病机", "原文未识脉名，述炳类偏枯由梦泄太过，阴精既伤，筋脉失所养。梦泄耗精，精亏则筋脉失荣，故成偏枯。治宜填补固摄，以滋荣溉之源，即补精以养筋脉。此段由病因推病机。", []], "624": ["病机", "原文谓「脉按之不鼓」，按之无力鼓指，是阳气虚馁不能鼓动脉道；阳虚则湿聚不化，故见舌白、腹满、溲少、脐平。湿为阴邪，得阳则化，阳微则湿停，故急与通阳泄湿，通阳即所以化湿，湿化则胀满溲少自解。", ["虚"]], "625": ["病机", "原文以「短为气弱，涩为营虚」立论，短则气不充脉，涩则营血不濡，营虚不能恋阳，阳动升越而为心疼心痛。此非实火，乃阴不敛阳之虚痛，故先清火育阴以潜阳，徐议峻补，示人勿骤投温补。", ["短", "涩"]], "626": ["病机", "「肝脉弦搏，火有余也」，弦为肝脉，搏则火盛鼓指，肝火有余，灼伤血络，故痰中带红；又曾坠马跌伤，瘀血留络，火与瘀互结。治于育阴中佐行瘀之品，育阴以制火，行瘀以通络，标本兼顾。", ["弦"]], "627": ["妇人", "「诊脉小而弱」，小弱为气血不充之象，经阻四月而脉不见滑利，故未可遽断为妊。原文指出体质素虚之人，脉形有不见滑利者，以气血不充故也。治法取子莫执中之说，不偏于攻补，于本体有益无损，可无畸重畸轻之弊。", ["小", "弱"]], "628": ["病机", "「右关其来颇疾」，疾为肝邪扰中之象；「脉形不长」是肝木郁而不伸，左关弦长，幸其全局犹在左部。若肝邪并于右胃，木乘土位，必病矣。此段以脉之疾与不长，辨肝郁扰中、木不疏土之机。", ["疾", "弦", "长"]], "629": ["兼症", "「脉象已和」，言脉已复常，惟小便时茎中痛连及上，若小便长则不病。原文断为「阴中有火，病在小肠丙火」，火郁小肠则茎中痛，故以养营合导赤、用东垣法清利小肠之火，脉和而症未除，示人凭症续治。", []], "630": ["病机", "原文未及脉象，专论「痛止而经事犹行，应止不止」，此冲脉不摄之故。冲为血海，冲脉失摄则经行应止而不止，故宜兼调冲脉。虽无脉可凭，然由症推机，冲脉不摄是其病本，调之则经自止。", []], "631": ["病机", "「左关独弦」，春脉如弦，或交春令使然；然「弦而带急」，急则少柔和之气，是肝阴不足，不能濡养筋脉。凡心悸、腰痛悉由此肝阴亏虚、筋脉失养所致，弦急为肝阴不足之脉，非独春令之常弦。", ["弦", "急"]], "632": ["病机", "原文未明言脉象，但述“经行速而为日多，冲不摄也”，指出冲任不固、营气虚而寒热腹痛，病关督脉冲任诸奇经。脉象虽缺，病机为奇经失约、营血亏虚，故以调奇经、充河津为法，使经脉渐充而愈。", []], "633": ["病机", "脉左弦为肝阴素亏、木失柔养，伏邪内发则往来寒热；右涩数为营阴不足、邪热内郁。腹中绊痛、泛恶干咳皆肝胃不和、木火刑金之象。治以和阳益阴、少佐清热，正合弦涩数所主之阴亏邪伏病机。", ["弦", "涩", "数"]], "634": ["病机", "脉数右大，数主热，大主阳明邪盛。原文谓“暑去湿存，今又湿复招暑”，湿转化热，故见烦热、神烦寐少、舌红口干，显系阳明不和、湿热内蒸之候。脉数右大正是热盛于阳明之征。", ["数", "大"]], "635": ["病机", "脉弦带数，弦主肝郁，数主火升。偶吸暑浊致身热不解，宿病肝气随发，腹中块垒痛剧、呛咳心嘈，皆木火升扰之象。脉弦数正合肝郁化火、暑浊内侵之病机，故以宣降开达、轻苦和阳为治。", ["弦", "数"]], "636": ["预后", "脉数经停，数主虚热，经停为阴血亏耗。原文谓“骨小肉脆”“先天既弱而水亏，壮火复识而金燥”，已现虚劳之候。脉数正是水亏火旺、金燥液涸之征，预后堪忧，故药惟补北以救金水。", ["数"]], "637": ["误治", "原文未出脉象，但言“以脉症较之，其咳原属手太阴得之”，指出先补后泻之误，致“邪从补而升，元由泻而虚”，竟成庙兵出而岸兵入之弊。此段主旨在纠误治之害，非论脉象。", []], "638": ["病机", "脉左弦数，右搏而长。弦数为木火内扰，搏长为邪盛于右。原文谓“根本久拨之体，复蒸而上为胃病，是肾胃相关”，故目黄、遗精淋浊、膝胫肿痛、面沉紫呕，皆邪由下蒸上、肾胃同病之象。", ["弦", "数", "搏", "长"]], "639": ["病机", "右三部洪数弦急并现，左上数中紧。洪数为阳热亢盛，弦急为木火内动。原文谓“阳精不升”“阳络不固”，致失精吐红，先后天俱病。脉象洪数弦急正是阴亏阳亢、精血耗散之病机反映。", ["洪", "数", "弦", "急"]], "640": ["病机", "脉弦劲如循刀刃，全无冲和之气，是木气太过、金令不及之象。木旺则克土，金弱不能制木，形成贼克。此脉主肝气横逆，阴失潜藏，阳无所倚，久则阴阳离决。原文以“齿刚则折”喻其刚劲易折，强调需致太和之气以消乖戾，否则病深难治。", ["弦", "劲"]], "641": ["病机", "蜀地属坤，其民脉宜缓而流利。今脉洪搏太过，是土气不足而火气偏亢，面黄气重亦为脾虚湿蕴之征。洪搏为火热鼓动，阴血受灼，若处故乡湿热之地，恐致血溢。此脉主中土本虚而标热，治宜滋水以制火，早服丸药以安其本。", ["洪", "搏"]], "642": ["病机", "寸来空大是心不藏神，关脉滑数是木无水养，尺来浮大是水气不衡。滑数主肝经郁热，空大浮大主阴不敛阳。三焦脉象失和，心肾不交，水火不能既济，故见恍惚悸动、肢末不利。此脉主心肝肾三脏阴亏阳浮，治当滋营卫、交心肾。", ["空", "大", "滑", "数"]], "643": ["预后", "脉象较前稍和，两手平均，俱就六阳本体，是邪气已退、无外来之气之象。惟营卫少虚，故脉虽和而未充。此脉示病势向愈，预后良好，但需养心阴、藏肾阳以培补元气。原文“可卜无外来之气”即言其脉无实邪，当以培补善后。", ["和"]], "644": ["病机", "原文未识脉名，从脉色较之，知少阴与厥阴亦病。三阳结乃成膈，今郁火挟木邪横亢中州，得热为伍愈肆猖狂，致肺不生津、大肠不生液，津液亏耗。逆上者肝邪，不纳者胃病，肺气不降。此段论膈证病机为郁火木邪犯胃、津液枯竭，主病在肝胃肺。", []], "645": ["病机", "脉虚细无力，弦象俱退，是元气亏弱之征。前此投药无效，因元气不克载药行令。虚细主气血两虚，弦退则肝邪已减，而手足颤振为元气不能充养四肢。此脉主元气大虚，病机与元气此长彼消，治当以直走先天之品为膏丸，久服培元。", ["虚", "细"]], "646": ["主病", "脉空弦，腹中急痛，是肝病之脉。空为血虚，弦为气急，肝血不足则脉道不充而见空，肝气横逆则脉弦而腹中急痛。治肝不应，则治脾亦良法，因木旺克土，实脾以御肝。此脉主肝虚气滞之腹痛，病在肝脾。", ["空", "弦"]], "647": ["预后", "脉弦数而上承鱼际，是肝风与暑风相合，手足厥阴同病。弦为肝风，数为暑热，上承鱼际为风火循经上炎。真气久不周于四肢，又暴受暑邪类中，遗溺目瞑，喑不能言，是厥阴经气闭塞。此脉主暑风内中、肝风鸱张，预后不良，原文谓“不治”。", ["弦", "数"]], "648": ["病机", "原文未明言脉象，但述“沉寒伤筋之损”及“胸走手，腹走足”之脉道循行，提示寒邪深伤筋脉，气血阻滞，病及下焦。虽无脉名，从“八十丈周于一身”可知脉道通身，寒伤则脉行不畅，主沉寒痼冷之病机，故内服八味汤温补下元。", []], "649": ["主病", "脉来浮涩，浮为风邪在表，涩为气血滞涩。原文“须眉自落，皮毛淖泽”乃风邪外袭、营卫不和之象，非衰老所致。风为阳邪，其性轻扬，故脉浮；风挟湿滞，血行不畅，故脉涩。此脉主风病，与须眉落、皮毛淖泽相应，属“三十六种”风疾之一。", ["浮", "涩"]], "650": ["病机", "阳明脉实，实脉主邪热内盛。原文“气急而喘，壮火食气，消烁真阴”，乃阳明热炽，壮火耗气伤阴，故脉实。夏气开张而剧，因火热得天时之助。此脉主阳明实热病机，与喘急、真阴消烁相应，治以温胆汤少衰其热，保肺金之伤。", ["实"]], "651": ["病机", "脉左弦右弱，左弦为肝邪偏盛，右弱为脾气不足。体盛之人气反弱，寒热乍起，小便短数，头项𥆧动，舌干齿燥，气促，渴不欲饮，皆元不胜邪之象。弦弱并见，示正虚邪扰，恐津液衰而邪内陷，故宜谨慎斟酌，缘燥令当令。", ["弦", "弱"]], "652": ["病机", "脉数主热，五六日不更衣，舌黄唇焦，胃热炽盛之征。前服辛温耗阴之品，更助热邪深入阴中，阳气独亢，故脉数。此脉主胃热炽盛、阴伤阳亢之病机，与便秘、舌黄唇焦相应，治非寒凉不可，然须小心保护阴液。", ["数"]], "653": ["病机", "原文未出脉名，但言“脉象尚悍”，提示邪气深伏、脉势劲急。病由食柿过多得寒而起，邪入肺发为气哮，久则肾水无本，虚而上泛为痰，胃为贮痰之器。脉悍示病深邪实，非浅剂可除，故当深入病所，拟仲景方法。", []], "654": ["病机", "脉弦主肝病。嗽而失血逾三载，色黯，环口色黄，乃肝脾及肾，上藏失养。弦脉为肝木偏旺，木旺克土，脾失健运，饮邪内生，逐之不得，滋之无功。此脉主肝脾肾俱病、饮邪内停之病机，故宗建中法以涤饮，俟阳明升而大补太阴。", ["弦"]], "655": ["病机", "脉弦数，尺独大，弦为肝火，数为热盛，尺大乃阴亏火炎之象。咳而喉痛失音，数载失红之后，阴亏火炎不言可喻。此脉主阴虚火旺、虚火上炎之病机，与咳、喉痛、失音相应，治宜至静之品引阳潜入阴中，使阴秘阳密。", ["弦", "数", "大"]], "656": ["病机", "原文谓形忽渐瘦而脉虚极，气怯偶咳、目黑微眩、忽忽不乐，皆气血大虚之象。脉虚极者，正气衰微，气血不能充脉，故形瘦气怯；阴血亏虚不能上奉，则目黑眩冒、情志不乐。此非外邪，乃虚劳内损之机，故治法补气补血，更以阴兽引入阴中，取獭肝、鹿角胶填养阴分。", ["虚"]], "657": ["预后", "原文未明脉名，仅言诊得色脉而形骸俱惫。好食辛则耗散真阴，色脉俱败、形骸疲惫，是脏腑精气皆衰之征。虽未必暴卒，亦难望长生，故曰自宜持其病。此段重在据色脉形骸判断预后，非论某脉主某病，先服三生饮乃权宜之治。", []], "658": ["预后", "原文未识脉名，但言未过五旬而形脉色俱衰。形、脉、色三者俱衰，是精气神皆败之候；叩知连丧三子又伤其孙，情志重创，内伤五脏，非药饵所能挽回。此段以形脉色俱衰断其难疗，属预后判断，强调情志伤损非草木可疗。", []], "659": ["病机", "脉得数而且弦，数主虚火，弦主阴亏阳亢。原文明言此阴亏症，并非外感；虚火上升则头痛，阴亏及肺肾则渐成金水两伤之势。数而弦为阴不制阳、虚火上炎之象，故治当静摄为主，药饵其次，紧扣原文阴亏、虚火升、金水两伤之语。", ["数", "弦"]], "660": ["病机", "脉细数而微，细为阴伤，数为热，微为正气衰。原文舌干黄、下利、身焦燥不润，乃下多伤阴，热邪乘虚内陷。阴液耗于下，热邪陷于里，脉细数而微正合正虚邪陷之机，故曰大可虑，治法轻清其邪、苦泄其热，尚在拟议。", ["细", "数", "微"]], "661": ["病机", "原文未识脉名，谓诊得胃气不能脉中流布，断为元气中馁。中焦为气血津液朝会之所，胃气不布则脉中乏流利之象，元气内馁可知。酸摄、辛流、甘培本为治法，因增肿患而却甘，说明中虚不运、水湿易停，紧扣胃气不布、元气中馁之旨。", []], "662": ["病机", "仲景云疟脉自弦，今三部九候中并无一毫弦象。弦为邪正相争之象，疟邪与正气相战则脉弦；今不见弦，说明所感非春之风、夏之暑、南方之瘴等外邪，当另求病机。此段借疟脉自弦一句反推，强调据脉辨邪之有无，属病机辨析。", ["弦"]], "663": ["误治", "脉愈按愈大，按之不减反大，是阴气不足、虚阳外浮，疟邪得以深入。前医以漏芦、鳖甲补阴太过，非花甲劳心之体所宜；汗泄过多又伤阳气，胃间伏邪、水饮不入。种种皆所不胜，故戒不可再从汗解，此段主旨在于纠前医误治之失。", ["大"]], "664": ["病机", "原文谓「右尺脉碎乱搏指」，碎乱者脉体破碎、至数不匀，主气血乖乱、风阳扰动。右尺候肾，碎乱搏指说明肾水不足、肝风内动，故断为「乙癸同源，肾肝同病」。又言少阴之脉不至巅、惟厥阴能至，明示风阳上冒以肝为主、肾为次，病机重心在肝风上逆而非单纯肾虚。", ["碎", "乱"]], "665": ["主病", "「右脉如革」者，革脉中空外坚，主虚主寒主失血。原文见短气失音、喉中水鸡声、面浮色痿、心下痞硬，显系肺胃气虚、水饮上泛，革脉正应其虚寒本质。补泻纷更而无效，说明本虚标实、攻补两难，故拟苇茎越婢汤宣肺化饮，从肺胃论治。", ["革"]], "666": ["病机", "「弦动无情之脉」即脉来劲急少胃气，原文自注「即名胃少」，虽未至但弦无胃之死脉，然久病见此终非佳象。弦动无情说明肝木偏亢、胃气受戕，故告诫莫因失血久进纯阴之药，恐「阳气抑而阴无所恃」，主张甘温扶阳以护胃气，体现脉少胃气当顾中阳之旨。", ["弦"]], "667": ["治法", "本段未出具体脉象，主旨在论奇经病治法。原文言「病在奇经，治他经不应」，又谓鼻红昏晕皆出督脉，说明病位深在奇经而非十二正经，故常法不效。血行清道、清气不肃点明病机为督脉失摄、清气不降，主张「以古法之法治之」，即从奇经督脉论治，属治法范畴。", []], "668": ["预后", "「脉迟软」者，迟为阳衰、软为气弱，合暑邪内侵而见怠惰不语、神昏肢冷，显系暑热中挟阴邪、心阳受困。原文明言「渐有是机，四末渐冷，竟有内闭外脱之虞」，迟软脉正是阳气欲脱之兆，故急用通阳救逆、仿大顺散义，属辨脉测预后并出救逆之法。", ["迟", "软"]], "669": ["病机", "「右脉芤搏」者，芤脉浮大中空，主失血伤阴。原文见耳聋、血下溢、寒热不已，说明阴络受伤、厥阴肝不藏血，血溢于下而阴液亏耗，故脉芤。寒热不已为厥阴枢机不利之象，治当「从至阴中宣出热邪」，即于阴分中透热，以存阴为第一义，脉芤正示阴伤血溢之机。", ["芤"]], "670": ["病机", "「右脉一息七重弦，左脉一息六至紧」，至数偏数而兼弦紧，弦主饮主肝、紧主寒主痛，数则示虚阳或饮邪迫肺。原文咳而不得息，断为「阴气已弱，金水同受病」，即肺肾阴虚、水饮上逆，弦紧之脉正应水寒射肺、金水同病之机，故议六君煎培土生金以治本。", ["弦", "紧", "数"]], "671": ["病机", "本段未出脉象，主旨在论咳红伤阴之病机。原文谓禀质既薄、咳红极易伤阴，又言「不可理肺」，因肺为气母、水出高源，借以生津补液、周环百脉。说明咳红之由在阴液亏耗、百脉失养，治当滋养阴液而非单纯理肺，体现肺肾同源、以津液周环百脉为要的认识。", []], "672": ["病机", "两关脉弦，为肝木偏旺、克侮太阴之象，故用旋覆代赭镇降、四磨运化。今弦象已减而面浮少退，是药应；然暴渴欲饮如故，说明阳明腑中垢浊未去，煎熬津液，下流不通则上流上泛。更见虚脉虚象彰著，提示本虚标实，不可峻攻，故拟缓法推陈致新以存津液。", ["弦", "虚"]], "673": ["其他", "此段述诊断术源流，非论具体脉象。原文强调周秦医师诊病注重气色脉候、听声写形，仲景更参语声呼吸以合脉候症状，六朝至唐则重明症候、辨病脏虚实。全段旨在说明断病如断狱、能断而有法方称方案，脉候仅为四诊参合之一端，故无脉象要素可录。", []], "674": ["其他", "此段为作者自述家世与习医缘由，非脉学论述。文中家君热病神识昏瞀，伯父投三黄石膏汤而愈；家弟中暑壮热谵语，某老医手甫按脉即断危在夜半，后以西瓜汁取汗而解。全段借往事叹医药关系之重与专门名家之罕观，未载具体脉象，故脉象要素为空。", []], "675": ["病机", "脉弦滑而有胃气，弦主肝木乘脾、饮邪内停，滑主痰水壅盛；然有胃气则言语清晰、吐后能食，示胃气未败。肿胀呕吐、咳喘不得卧、吐痰水盈盆，皆痰饮上逆、气机壅塞之候。脉证合参，病机在痰饮内结、肝胃不和，故小半夏加姜味等方初服少效而呕吐大发。", ["弦", "滑"]], "676": ["病机", "脉息滑数、右部尤甚，滑主痰热内蕴，数主热邪亢盛，右部应肺胃，故知温邪蕴伏日久、蓄久暴发。壮热谵语、见人则笑、口渴溲赤、舌苔黄薄干燥无津，皆热炽津伤、痰热蒙扰之症。脉滑数与此相应，故治法以解热为主，佐豁痰润燥，用三黄石膏合小陷胸加减。", ["滑", "数"]], "677": ["病机", "初诊脉滑，为湿温伏邪、痰湿内蕴之象；服三仁汤后热愈甚、舌苔转燥、脉亦转数，说明湿渐化燥、邪从热化而内炽。发热身痛、溲热胸闷为伏邪外发，口渴心烦、苔燥脉数则热盛伤津。后战栗恶寒、震动床帐，乃欲作战汗之兆，脉静身凉则邪从汗解，可见脉滑转数正反映伏热化燥之机。", ["滑", "数"]], "678": ["病机", "两手脉数疾，数主热盛，疾则热极而躁，与壮热烁手、面垢目赤、鼻孔如烟煤、舌苔黑燥、手臂搐搦并见，显系阳明热极、胃家实之候。热邪内燔，津液被灼，故昏沉不语、大便三日不通。脉数疾正是热盛腑实之征，故非下不可，用调胃承气合三黄石膏以泻热存阴。", ["数", "疾"]], "679": ["病机", "初按脉滑数，滑主痰热，数主邪热，与恶寒发热、头痛身痛、谵语不识人、溲赤相应，为温邪夹痰热内扰。下午脉息滑而不数，身热自汗、面赤口渴、苔薄腻不黄燥，示热势稍敛而腑实已成，故用小承气下之。三日后复发热有汗口渴、脉滑数，是余热复炽，转用白虎清之。", ["滑", "数"]], "680": ["病机", "两脉俱数，数为热盛，结合发热谵语、口渴心烦、欲食冷物、胸闷溲热、舌苔黄腻，显系痰热内结、少阳阳明同病。数脉主热，热扰心神则谵语，热灼津伤则口渴心烦。初与小陷胸汤加柴芩不效，改用凉膈散通下，得战汗而解，证实热结在里，数脉为实热之征。", ["数"]], "681": ["病机", "脉数主暑热内蕴，与壮热头疼、胸闷咽燥、口渴舌绛焦燥、便闭溲赤相应，为暑热蕴伏肠胃热结之病。通下后热退，脉转缓不数，说明热结已解，邪势已衰。数脉为实热，缓为邪退胃和之象，故知饥欲食，继以清解余邪为治。", ["数", "缓"]], "682": ["病机", "两脉皆数，重按无神，为暑热内盛而正气已伤；吐泻交作、目陷形消、四肢逆冷、心烦口渴、舌红腻苔，乃暑湿霍乱、热深厥深之候。数而无力，非实热亢盛，而是暑热伤气、津液耗损。后脉转细小，为病去而气血两虚，故心悸腰酸、精神疲惫。", ["数", "细"]], "683": ["病机", "寸关俱数，舌苔黄燥无津，口渴欲冷饮，烦躁畏热，虽四肢冷而胸腹不热，此暑热内伏、热深厥深、内真热而外假寒之病。数脉主里热炽盛，热邪内闭，阳气不达四末故肢冷，非阳虚也。脉数与舌燥、渴饮相应，故用白虎合香薷清暑泄热而愈。", ["数"]], "684": ["病机", "脉息滑数，滑主痰湿宿滞，数主热，合腹痛吐利、发热口渴、烦躁、舌苔黄腻，为暑湿蕴伏中焦、肠胃有宿滞之病。滑数之脉反映湿热交蒸、痰滞内阻，故以黄连香薷饮合平胃散清暑化湿导滞。文中强调舌苔黄腻、小便红赤为用膏连之凭，滑数脉正与此相应。", ["滑", "数"]], "685": ["病机", "脉息小数，数为暑热未清，小为正气已伤，合霍乱吐泻、手足冷、目陷形消、口渴、舌苔黄腻，乃暑湿内蕴而脾胃已虚。数非实热亢盛，小示气血不足，故用姜汁炒川连清热，佐半夏、扁豆、苡仁、沙参健脾养胃，清补兼施，吐泻止而手足温。", ["小", "数"]], "686": ["病机", "脉沉迟而小，沉主里，迟主寒，小主阳虚，合腹痛上冲、呕吐清水、下利红白、手足俱冷、汗出神疲、面白唇淡，显系阳虚中寒之病，由乘凉饮冷所致。沉迟小为阴寒内盛、阳气衰微之象，非热证之数，故用附子理中汤加吴茱萸、桂枝温阳散寒而痛止利停。", ["沉", "迟", "小"]], "687": ["病机", "左脉细小，心脉尤弱，合血崩后不能寐、精神疲惫、饮食不多、脐左动气上冲、心悸多汗、筋掣，为血舍空虚、筋无血养、虚阳不能敛纳之病。细小弱脉主阴血亏虚，心脉弱则心血不足，虚阳上冲故动气心悸，治以阿胶鸡子黄汤合三甲复脉汤滋阴潜阳而安。", ["细", "小", "弱"]], "688": ["主病", "脉息小弱，为阳气大虚之征。小者脉体收敛，弱则搏动无力，皆阳气不能充脉之象。原文见冷汗、手冷额冷、面色萎黄、心悸头晕、精神不支，正合《伤寒论》‘亡阳’之候。阳气虚极，不能温煦四末，故手冷；不能固摄津液，故冷汗；不能上奉清窍，故头晕。此脉此症，主阳气欲脱之危候，故用四逆加人参汤急救回阳。", ["小", "弱"]], "689": ["病机", "脉息耎滑而小，耎为阳虚不鼓，滑为痰湿内蕴，小则气血不足。产后小产，阳气已伤，故手冷恶寒、自汗不止；痰湿阻滞中焦，故胸闷不欲食。舌苔薄白亦痰湿之征。此脉象示阳虚为本、痰湿为标，故用黄芪建中汤温阳建中，去饴糖之滋腻，加橘皮、半夏以化痰湿，标本兼顾。", ["耎", "滑", "小"]], "690": ["病机", "脉息沉弱，沉为病在里，弱为阳气虚。虽见烦躁谵语、欲食冷物、唇焦口渴，似属热证，然口虽渴而不能饮、舌则润泽、舌色不红、面色黄淡、身不发热、手冷，皆真寒之据。此因寒凉发散太过，损伤阳气，虚阳浮越，故现假热之象。脉沉弱正揭其底，主虚寒病机，非实热也。", ["沉", "弱"]], "691": ["主病", "脉息沉弱，沉主里、弱主阳虚。老妇感冒，医与发散，汗出伤阳，遂发狂奔走、欲脱衣卧冷地，似热而实寒。然面色黄淡、手足俱冷，脉沉弱，显系阳虚欲脱，虚阳外扰故发狂。此脉此症，主阳气虚脱之病机，故急以四逆汤加党参、熟地、肉桂回阳固脱，两剂而安。", ["沉", "弱"]], "692": ["病机", "初诊脉息小滑，小为阳虚，滑为痰饮；服发散后脉转沉弱，沉弱为阳气益虚。原文述‘阳虚受寒之病，得发散而阳气益虚’，故见喘息不能卧、热气上升、腹痛呕吐痰水、畏寒指冷。小滑示痰饮内停，沉弱示阳气虚衰，龙雷之火上越、肺肾不纳气，皆由此虚寒病机所生。", ["小", "滑", "沉", "弱"]], "693": ["主病", "脉息小弱，小为脉体不充，弱为搏动无力，皆脾胃气虚、阳气衰弱之象。两手俱冷、精神疲倦，泄泻不止，正合脾阳不振、运化失职。此脉主脾胃虚寒之病机，故用理中汤温中健脾，加山药、木香以止泻调气，后续加肉桂、枸杞温补真元，皆从脉小弱处着眼。", ["小", "弱"]], "694": ["病机", "脉沉而滑，沉为病在里，滑主痰饮。咳喘倚息不得卧、恶寒发热、头疼身痛、胸闷心痛彻背、舌苔白腻，显系风寒外束、痰饮内停，内外搏结，肺气不得下降而成肺胀。沉滑之脉正示痰饮内结、气机壅滞之病机，故用小青龙汤外解风寒、内化痰饮，合栝蒌薤白汤以通阳宣痹。", ["沉", "滑"]], "695": ["其他", "脉如平人，即脉象平和无病，然咳嗽音嗄、咳而无痰，自春徂秋不愈，饮食能进、不热不渴。此脉不显病机，说明非内伤虚损，乃风寒恋肺、肺气不宣所致。脉平而症在肺，故以三拗汤宣肺散寒，加干姜、五味子、半夏温肺化痰，后以六君子汤调补，从症不从脉。", []], "696": ["病机", "右脉滑数，滑主痰，数主热，痰热壅肺，故见咳嗽吐痰甚臭、身热口渴、手足心热、舌红无苔，此肺脏伏热势将成痈之候。脉滑数有力，为实热内蕴之征，与肺痈初期痰热壅盛病机相合。", ["滑", "数"]], "697": ["病机", "脉数主热，小儿发热数日，咳吐臭痰，额热烁手，舌干苔少，口渴，乃肺脏受热，热灼津伤。脉数而口渴舌干，为热盛伤津之象，与肺热咳痰相应，故用清肺泄热之剂而愈。", ["数"]], "698": ["病机", "脉息细弱，细主阴血亏少，弱主气衰，患者素有肺病，咳嗽痰中带血，头晕心悸，彻夜不寐，精神疲惫，心内觉热，乃劳神太过，血液衰耗，肺病日久将成肺痨。细弱脉为气血两虚之征，与虚劳病机相符。", ["细", "弱"]], "699": ["病机", "脉息缓滑，缓主湿，滑主痰，体胖舌有腻苔，咳嗽多日音嗄，起居如常，乃痰饮内停，湿浊蕴结。缓滑脉为痰湿之象，与痰饮病机相应，故用二陈汤加味化痰蠲饮而瘳。", ["缓", "滑"]], "700": ["病机", "两手脉滑有神，滑主痰，有神为胃气尚存，患者体胖神强，素患肺病，咳嗽哮喘，痰声如拽锯，呼吸几不能通，乃奉养太过，肥甘油腻蕴酿成痰，致肺气管枝发炎。滑脉为痰浊壅盛之征，与痰喘病机相合。", ["滑"]], "701": ["病机", "原文未直接描述脉象，仅言用生脉散加百合，从方测证，患儿精神疲惫，面色淡白，舌红无苔，满舌俱破，有汗不热，乃虚症也，属气阴两虚。生脉散益气养阴，加百合、元参等清润，与虚咳病机相应。", []], "702": ["病机", "脉息濡缓，濡主湿、主虚，缓主湿，患者咳嗽多日，时发寒热，舌光无苔，乃气阴不足兼湿浊内蕴。濡缓脉为气阴两虚、湿邪留恋之象，与咳嗽寒热病机相应，故用生脉散加青蒿、黄芩等清透湿热而愈。", ["濡", "缓"]], "703": ["病机", "左手脉伏不现，右脉弱小，伏为血为寒凝，营卫失常，弱小为气血虚寒之本相。患者怀孕三月，骤然腹痛下血，痛甚头出冷汗，手冷鼻冷，胸闷呕吐，前后阴阻胀，面色淡黄白无光采，舌淡无苔，皆中下焦阳气不足，腹部受寒，血脉流行阻滞之虚寒证。", ["伏", "弱", "小"]], "704": ["病机", "脉息耎数，耎为阴液亏虚、脉道不充，数为热邪燔灼。患儿体质素瘦，痧后泡疮、喉痧，身热咽痛溃烂，舌红无苔，口渴溲黄，显系阴液大亏，热邪燔灼上焦。脉耎示正虚，数示邪热，故断非实症，危险已极。", ["耎", "数"]], "705": ["病机", "脉息虚数，虚为气阴不足，数为余热未清。复诊身热轻，舌红艳而光无苔，溲黄浊，彻夜不寐，喉烂如故，言语多，乃阴液未复、虚热内扰。脉虚数正合气阴两虚而热邪未净之机，故去苦寒，加西洋参、枣仁、茯神等培补。", ["虚", "数"]], "706": ["病机", "脉息虚细无神，虚为气血不足，细为阴血亏少，无神示正气大伤。喉烂未全退，精神疲惫，舌红转淡，谵语减，乃邪退正虚、气血大虚之候。脉虚细无神，故急宜培补，用大补元煎合增液汤法。", ["虚", "细"]], "707": ["病机", "脉息仍细弱无神，细弱皆主气血亏虚，无神为正气未复。夜寐安，谵语止，喉烂减退大半，稍进粥汤，症情向愈，但脉仍细弱无神，示气血大虚尚未恢复，故仍用原方加熟地、莲子、女贞子培补。", ["细", "弱"]], "708": ["病机", "脉息较有神而现滑象，滑为气血渐充、胃气来复之征。喉烂全退，腐物易拭，现好肉，舌淡无苔，小便清，能进薄粥，皆邪退正复之象。脉由虚细无神转滑而有神，示气血渐旺，故仍用原方减熟地、去石斛，加扁豆健脾。", ["滑"]], "709": ["病机", "脉洪大不柔，左手寸部尤大硬，洪大为阳热亢盛，不柔、大硬示阴液枯竭、孤阳独炽。高年体胖，疽发背溃烂深，遍身小疖痛甚，手臂腿颤动，彻夜不寐，舌光赤无苔无津，皆阴液大亏、孤阳独炽、津血益伤之候。", ["洪", "大"]], "710": ["病机", "脉数身热，数主热邪；脉息耎小，耎小为阴液素亏、脉道不充。喉痧鲜红，咽喉破烂白腐，舌前半红赤无苔，颧红唇红，作恶，汤水难下，乃阴液素亏、感受温热，热毒上攻。脉数示邪热，耎小示正虚，故先宜养阴清热解毒。", ["数", "耎", "小"]], "711": ["病机", "脉息虚耎，虚为气血不足，耎为脉道软弱无力，主精血衰少。年六十三，悲哭太过，发白如霜，舌红如朱，咽喉白腐不溃烂，烦躁不宁，彻夜不寐，乃劳神太过、虚火上升、心肾不交、水火不济之病。脉虚耎正合精血衰、虚火浮越之机。", ["虚", "耎"]], "712": ["病机", "脉息滑数有力，滑主痰热，数主热盛，有力为实。温毒痰热蓄积上焦，污血壅阻而成喉痈，故脉见滑数有力。身热口渴、舌苔白腻、咽喉肿塞溃烂，皆痰热毒血壅盛之象，脉证相符。", ["滑", "数", "有", "力"]], "713": ["病机", "脉息小数，小为血虚，数为有热。血液亏耗，脑力素衰，复因劳役动火，火动生风，发为痉厥。症见昏倒口噤、手指痉挛、口眼歪斜，皆阴血亏虚、风火内动之候，脉小数正合虚火内扰之机。", ["小", "数"]], "714": ["病机", "脉息沉小，沉主里，小主气弱。屡经汗下，津枯气弱，胃气尚存故脉尚有胃气。舌质焦燥无津，呃逆不止，身不发热，皆津液耗伤、胃气上逆之象。脉沉小示病在里而正气已虚，非实热呃逆可比。", ["沉", "小"]], "715": ["病机", "两手脉皆细数，按之极虚。细为阴伤，数为热，虚为津气耗损。暑病误用辛温克削，耗损阴津而助邪热，热迫液泄，故汗出淋漓、心烦口渴、溲赤而热。脉细数极虚，正合暑热伤津、气阴两虚之病机。", ["细", "数", "虚"]], "716": ["病机", "脉沉缓而滑，沉主里，缓主湿，滑主痰滞。贪凉饮冷太过，风寒外袭，冷滞内停，故恶寒战栗、胸闷无汗、舌苔白腻。脉沉缓滑，正合寒湿内滞、营卫不和之病机，与但寒不热之疟相应。", ["沉", "缓", "滑"]], "717": ["病机", "脉与平人无大异，但略兼滑数之象。滑主痰热，数主热盛。暑气深伏为患，发则大热烦渴、欲饮冷水、溲赤而热，皆暑热内炽之候。脉虽近平而兼滑数，示暑热未清，正气未大伤，故以清热生津取效。", ["滑", "数"]], "718": ["病机", "脉息滑数，滑主痰热，数主热盛。疟病发数日，身热甚重，溲赤而热，舌苔干燥，皆暑热内盛、耗伤津液之象。脉滑数正合暑热痰滞之病机，故用竹叶石膏汤加减清热生津而愈。", ["滑", "数"]], "719": ["病机", "脉息缓滑，缓主湿，滑主痰。暑湿痰滞蕴伏于中，营卫不能和调，故疟症间二日一发，面黄头晕，胸闷作胀，舌苔白薄。脉缓滑正合暑湿痰滞内蕴之病机，服柴胡桂枝汤合平胃散后病气外泄而痊。", ["缓", "滑"]], "720": ["病机", "脉息小数，数主热，小主虚，合之见血液素亏之体复感暑湿，且兼拂郁。阴血不足则脉道不充而小，暑湿内郁则脉数。症见寒热往来、头晕心悸、彻夜不寐、舌光如镜，皆阴亏郁热之象，故以养血舒郁、清暑化湿为治。", ["小", "数"]], "721": ["病机", "左脉细数，右脉小滑兼数。细为血少，数为热，小滑为暑湿痰滞。生育多则血液素亏，复感时令暑气，故脉细数；暑湿内蕴，故右脉小滑。症见口渴自汗、手指蠕动、舌边破裂，皆阴亏热盛动风之兆，治以养阴清暑。", ["细", "数", "小", "滑"]], "722": ["病机", "脉沉弦滑，沉主里，弦主饮主痛，滑主痰。舌苔滞腻、胸闷身重、骨节酸疼、但恶寒微热，显系寒湿痰饮冰伏中焦，阳气不能健运。脉沉弦滑正是寒湿痰饮内阻之应，故用温阳化饮、运脾消痰之法，使阳气复而痰饮消。", ["沉", "弦", "滑"]], "723": ["病机", "脉息细数，左尺尤甚。细为阴液不足，数为有热，左尺候肾，尤甚则肾阴亏虚明显。平日用脑太过，阴液素衰，复受暑邪，故午后发虐，口渴心烦，溲赤苔少。脉细数正合阴虚暑热之机，治以养阴清暑。", ["细", "数"]], "724": ["病机", "脉滑溲赤，滑主痰湿，溲赤为湿热。发热胸闷、舌苔黄腻、腹胀不舒，显系湿热蕴伏，兼有痰滞。初用清利湿热痰滞而热退胸宽，后因关节痛加辛温通络之品，反致大喘、脉细弱无神，乃病退元气大虚欲脱之候，非初诊脉滑所主。", ["滑"]], "725": ["病机", "脉弦小不数，弦为肝旺，小为血少，不数则热不在气分。病者烦躁不寐、呕吐、脐左动气、白带频流、舌红赤光，产育十二胎，血液亏竭，阳热偏胜，加之辛散苦寒伤胃，胃液益竭，神不守舍。脉弦小不数正合阴亏阳浮、胃虚神扰之机。", ["弦", "小", "数"]], "726": ["病机", "脉数口渴，数为热，口渴亦热象。发热头疼、呕恶、溲热胸闷、舌苔薄腻，乃暑湿痰滞蕴伏中焦，胃脏不能运化。暑湿内郁则脉数，痰滞中阻则胸闷苔腻。服清暑化湿化痰之剂得战汗而解，脉数口渴随之而退。", ["数"]], "727": ["病机", "脉缓滑，缓为湿为常，滑为痰为食。陡患腹痛呕吐、恶寒发热、痛甚汗出、舌苔薄腻，乃寒湿痰滞内阻中焦，气机不通。脉缓滑正应痰湿内蕴，故用柴胡桂枝汤去人参，加蔻仁、木香以温运化湿、行气止痛，一剂而痛呕俱止。", ["缓", "滑"]], "728": ["病机", "脉滑主痰湿内蕴，弦主痛、主气滞，数主热。患者腹痛呕吐下利、胸闷发热、舌苔腻，显系饮食不慎，胃有痰湿积滞，兼犯房事致子宫病。初诊脉滑，示痰湿；后脉弦滑数，弦为痛甚，数为热增，滑为痰湿未化，故改用黄连汤加厚朴清湿热、行气止痛而愈。", ["滑", "弦", "数"]], "729": ["病机", "脉息滑大，滑主痰食内积，大主邪气盛实。啖糯米粽过多，致胸膈饱闷、恶寒发热、舌苔垢腻，乃食滞痰浊壅阻中焦，胃气不得下行。滑大之脉正合实滞之象，故先用平胃散合枳桔汤消导，不效，加滚痰丸攻逐痰积，得大便通而胸膈遂通。", ["滑", "大"]], "730": ["病机", "两脉弦小，弦主痛、主气逆，小主正气不足。患者年逾五旬，素有疝病，肾气素虚，复受客寒，寒气上冲，发为奔豚，自觉气从脐下直冲于心，心痛欲裂，手冷汗出。弦为冲气搏结，小为肾阳式微，故用桂枝加桂汤温肾降冲，加熟地、鹿角胶等补虚。", ["弦", "小"]], "731": ["妇人", "脉缓滑有神，缓为胃气调和，滑为气血充盛，此妊娠之常脉。患者天癸两月未行，呕吐不能食，恶寒发热，似病而实非病。诸医杂治无效，而脉仍缓滑有生气，故断为孕。虽痉厥可畏，然脉象有神，非死候也，嘱勿药，以粥汤调养。", ["缓", "滑"]], "732": ["兼症", "脉缓不数，缓为外邪未化热，不数为热势未炽。患儿发热恶寒、咳嗽体倦、食少，乃风温初起，邪在肺卫。服葱豉汤后痧点透发，脉仍缓不数，说明邪未深入。后热甚口渴、舌红起刺，脉象当有变化，但原文未载，此段脉象主要提示初期病机为邪郁肌表，尚未化热入里。", ["缓", "数"]], "733": ["病机", "脉数不大，数为热，不大为热势虽盛而脉形未洪，示暑热内伏肺胃，迫血妄行。患者吐血成碗、发热咳嗽、心烦口渴、欲饮冷水、胸部烧热，皆暑热炽盛之象。数脉主热，不大说明热郁于里而非外扬，故用玉女煎合清燥救肺汤清降肺胃之热，热降则血自止。", ["数", "大"]], "734": ["预后", "脉息亦尚平静，然咯血不已、精神疲惫、不能起于床，脉症不符。脉静而病重，乃气血虽未大脱，而肺络损伤已深，正气暗耗。次日血忽上涌，昏晕不能言，奄奄一息，可见脉静不可恃，须结合症情判断。此段主旨在于提示脉症合参，脉静而症危者，预后不良。", []], "735": ["病机", "寸关脉滑，滑主痰湿。患者素患肺病及头痛，每因劳怒啖黏腻肥甘而发，发则头痛目昏、咳嗽喉中如水鸡声、胸闷不饥、舌苔薄腻，显系痰滞阻塞，上扰清窍，壅遏肺气。产育多、吸阿片致脑筋衰弱，痰湿更易停聚。故用桑叶、杭菊、杏仁、贝母等化痰清上之品奏效。", ["滑"]], "736": ["病机", "脉滑数，滑主湿浊内蕴，数主热邪亢盛。患儿下痢里急后重、发热口渴、舌苔黄腻，显系湿热积滞肠腑，气血壅滞。脉滑数正合湿热壅盛之病机，故用香连丸加黄芩等清热化湿、行气导滞而愈。", ["滑", "数"]], "737": ["病机", "脉息滑数，滑为湿滞，数为热象。下利腹痛、里急后重，乃湿热积滞壅阻肠道。服小承气合香连丸后痛痢止而转发热胸闷，是里气通而余邪外达。脉滑数反映湿热内盛，故以通下清化取效。", ["滑", "数"]], "738": ["病机", "脉缓滑，缓主湿，滑主痰饮积滞。患儿下痢红白、腹胀、身不热、口不渴、舌淡无苔，乃过啖生冷，寒湿伤中，肠胃运化失职。脉缓滑提示寒湿内停，非热痢可比，故用平胃散加白术、木香等温运化湿而痊。", ["缓", "滑"]], "739": ["病机", "脉息小弱，小弱主气血虚衰、阳气不足。下痢多日，手足冷、冷汗出、神疲、口不渴、舌无苔，此非痢疾，乃阳虚欲脱之候。脉小弱正合阳气衰微、不能温煦固摄之机，故用理中汤温阳救逆，一服汗收手暖。", ["小", "弱"]], "740": ["病机", "脉息小弱，主气血两虚。年高病痢日久，脱肛、神疲、头晕心悸、不能起坐、舌光无苔，乃中气下陷、气血亏耗。脉小弱反映正气虚衰，故用补中益气汤升提中气，加麦冬、白芍养阴，三剂而痊。", ["小", "弱"]], "741": ["病机", "脉细，主阴血亏虚。泻利年余，面黄体瘦、食少作恶、舌光无苔、口干头晕心悸，乃久泻伤阴，肠胃脂液消亡，即“下多亡阴”。脉细正合阴液亏耗之机，故用大补丸煎加黄耆、赤石脂等补涩兼施，纯虚无滞故可纯补。", ["细"]], "742": ["病机", "脉息小弱，主阳气虚弱。病痢年余，日夜数次，手指清冷，脉小弱，虽饮食起居如常，然阳气已衰，不能温达四末。脉小弱反映中阳不足，故用理中汤加黄耆、木香等温中益气，两剂痢止。", ["小", "弱"]], "743": ["病机", "脉散，主气阴耗散、正气虚脱。病后泄泻汗多，体瘦神疲，咳嗽有痰，小便清，舌色淡，纯属虚象。脉散反映气阴两伤、卫外不固，故用四君子汤合生脉散加黄耆、花粉，补气敛阴，汗止泻减。", ["散"]], "744": ["病机", "脉数溲热，数主热，溲热为热邪下迫之征。暑湿蕴伏肠胃，兼有宿滞，火性急速，故暴注下迫、发热口渴、胸闷腹痛、舌苔黄腻。脉数与溲热并见，说明暑湿化火、热迫肠道之病机，主暑湿泄泻兼积滞。", ["数"]], "745": ["病机", "脉缓滑不数，缓为湿滞，滑为痰湿内蕴，不数则热不炽。身凉如平人而心中烧热、鼻衄如注，乃湿温之邪郁于血分，热迫血溢。脉滑不数又见咳嗽呕吐潮热胸闷胁痛，为湿温兼胃病，湿秽与恼怒郁闷相合，酿成湿热痰滞之候。", ["缓", "滑"]], "746": ["病机", "脉息耎数，耎为胃津耗竭、正气不足，数为湿热未清。前服克削过甚，胃津耗竭而脑力受损，故心烦不寐、精神疲倦、大便泄泻、咳则右胁作痛。脉耎数说明湿热未清而胃津已伤，主胃津亏耗、湿热留恋之病机。", ["耎", "数"]], "747": ["病机", "脉息耎滑，耎为胃气受伤、正气不足，滑为暑湿痰滞内蕴。手冷汗多、精神疲惫、时作嗳气、舌苔薄腻，乃暑湿痰滞之病治不得法，胃气受伤。脉耎滑说明正气已虚而痰湿未化，主暑湿痰滞兼胃气受损之病机。", ["耎", "滑"]], "748": ["病机", "脉息虚数，虚为气血两虚，数为阴虚发热。小产后去血过多，气血两虚，阳虚则恶寒，阴虚则发热，阴阳俱虚则恶寒发热。心慌不寐、头晕汗多、口干舌苔少、舌尖破皮，皆气血两虚、心神失养之象。脉虚数主气血两虚、阴阳俱损之病机。", ["虚", "数"]], "749": ["病机", "脉虚小无力，虚为血虚，小为脉道不充，无力为正气衰弱。失血后小便下血块、大便带血、阴户酸坠、精神疲弱，乃血虚而脑筋衰弱之病，殆由房劳过度。脉虚小无力说明血虚不能充脉，主血虚脑弱、正气亏虚之病机。", ["虚", "小"]], "750": ["病机", "两脉细小，细为血虚，小为脉道不充。产后大笑不止、面色黄淡无华、自汗气促，乃临盆下血过多，脑无血养，致脑之作用失其常度。脉细小说明血液亏虚不能充脉养脑，主气血两虚、脑失所养之病机。", ["细", "小"]], "751": ["病机", "脉息沉缓，沉为病在里，缓为寒湿；脉沉小缓，小为阳气受抑。贪食西瓜过度，冷滞伤胃，感冒风寒，寒湿与痰水阻遏中焦，胃中阳气受压抑，不能运化，故手足麻、胸闷作痛、舌苔白腻、口不渴。脉沉缓小说明寒湿内阻、中阳受困之病机。", ["沉", "缓", "小"]], "752": ["病机", "脉滑兼数，滑主痰湿，数主热，合而示暑湿蕴伏肺胃、痰热内盛之病机。原文谓“暑湿蕴伏肺胃，病在上焦”，故见午后发热、胸闷、口燥溲热、胸膈热甚、舌苔黄薄有裂痕，皆上焦痰热之症。前医误用攻下，只通肠胃，与肺无涉，故病不退。脉滑数正是痰热壅于上焦之征，治宜轻清开化。", ["滑", "数"]], "753": ["病机", "脉息沉滑，沉主里，滑主痰，示痰热结于胃腑之病机。原文谓“胃热有痰”，故见妄言骂詈、终日不休、不能寐、舌尖红苔腻、大便三日未行、饮食如常，皆实象而非虚症。胃热上扰神明则狂言骂詈，痰浊内蕴则脉滑，病位在里故脉沉。此脉证实为胃热痰结之狂证，尚可治。", ["沉", "滑"]], "754": ["病机", "脉息滑数，滑主痰湿，数主热，示湿温兼肺病、痰热内蕴之病机。原文谓“湿温而兼肺病”，故见头疼身重、肢节酸疼、发热谵语、咳嗽痰中夹血、面色晦黯。湿温之邪蕴于气分，痰热阻肺则咳血，热扰心神则谵语。脉滑数正是湿热痰浊交蒸之象，治以小陷胸汤加清化之品而瘥。", ["滑", "数"]], "755": ["病机", "脉滑数不调，滑主痰，数主热，不调示痰热阻滞气机，原文谓“暑湿痰滞蕴结于中焦之病”。故见恶寒发热、谵语不识人、手舞吃吃笑不休、口渴烦躁、舌尖红中苔白腻、身热有汗。痰热蒙蔽心包则谵语笑不休，蕴结中焦则苔腻。脉滑数不调正是痰热壅盛、气机不利之征，治以清化痰热而愈。", ["滑", "数"]], "756": ["病机", "脉滑舌燥、脉滑唇红、脉息滑数，滑主痰热，数主热盛，示痰热内结、阳明腑实之病机。原文见发热恶寒、头疼身痛、胸闷、热烁手、心烦不寐、数日不大便，继则谵语烦躁、舌苔黄、口内破裂、大便溏，皆痰热胶结、邪传阳明之象。脉滑数正是痰热壅盛之征，故以大柴胡、小陷胸等方下之而斑疹透发。", ["滑", "数"]], "757": ["病机", "脉息小滑，小示正气已伤，滑主痰热，原文谓“病退而津液大伤，痰热阻滞为患”。故见彻夜不寐、谵语笑不休、不饥不食、舌尖红而苔少。津伤则脉小，痰热内扰则脉滑、笑不休、不寐。此脉小滑正是津亏痰热未净之候，治以养阴清化痰热，一剂而笑止神安。", ["小", "滑"]], "758": ["病机", "右脉小弱、左脉虚数、两脉虚细，小弱虚细皆主正气亏虚，数示虚热，原文谓“克削过甚，津液元气俱伤之候”。故见面色黯淡、舌燥无津、手指蠕动、心悸不寐，继则汗出不止、舌现黑色、头重异常、手冷神疲。脉虚细数正是津液元气大伤、阴阳欲脱之征，前药嫌轻，终至两脉皆虚。", ["小", "弱", "虚", "数"]], "759": ["病机", "两脉皆虚耎无力、脉散，虚耎主气血大虚，散主阴阳欲脱，原文谓“高年气血已亏，外症出脓血既多，饮食又多日不进，气血大虚阴阳欲脱之候”。故见汗多头晕、大便溏泻、精神疲弱、胸闷作恶、咳嗽心悸、舌苔少。脉虚耎无力为气血亏极，脉散为阳气浮越欲脱，危险实甚，治以大补气血、敛阴固脱。", ["虚", "耎", "散"]], "760": ["病机", "脉息弦缓无力，弦为劳神太过、肝脾失调之象，缓而无力则示气血大亏。原文谓“阴络伤则血内溢”，便血三月、每日二十余次，血色鲜紫淡不一，头晕心悸、精神疲惫、面色黄淡，皆失血过多、气血两亏之候。脉虚无力正合气血大亏，故急宜补养气血、止血敛血，否则暴脱。", ["弦", "缓", "虚"]], "761": ["病机", "脉息虚小，左脉较小，虚小为阴血不足、脉道不充之象。原文谓“劳神太过，阴虚血热妄行”，经水淋漓不止而致血虚，心无血养则头晕心悸，热上升则咽痛，舌红无苔亦阴虚之征。左脉较小尤显血虚于内，故先宜养血调经以止血，继加鳖甲、珍珠母育阴潜阳。", ["虚", "小", "细"]], "762": ["病机", "两脉虚弱，为气血大亏、势将虚脱之候。患者素患血崩，遇劳、思虑恼怒即发，此次下血成斗，心悸头晕、奄奄一息、面色无华，皆失血过多、气随血脱之象。脉虚弱无力正合“势将脱矣”之危，故师魏柳洲法，重用熟地、枸杞、阿胶、枣仁、党参峻补气血以固脱。", ["虚", "弱"]], "763": ["病机", "脉息细弱，细为阴血亏少、脉道不充，弱为阳气衰微、鼓动无力，合之乃阴阳两脱之候。产后下血不止，头晕心慌、汗多手冷，正是血脱于下、阳浮于外、阴阳不相维系之危象。原文谓“危亡在即”，故非童便力薄所能及，急以党参、黄耆、熟地、阿胶、枣仁气血双补以固脱。", ["细", "弱"]], "764": ["病机", "脉息缓滑，缓为湿邪困阻、气血运行不畅，滑为痰湿内蕴之象。患者沿途感冒风寒，左肩作痛不能举动、痛处畏冷，乃风寒湿邪痹阻经络；饮食如常则里无大热。脉缓滑正合风寒湿夹痰之痹，故以羌活、桂枝、秦艽祛风散寒，半夏、苍术、白芥子化痰除湿通络。", ["缓", "滑"]], "765": ["病机", "脉弦小滑，弦为气机郁滞，小为正气不足，滑为痰湿内蕴。患者胸次闷塞、饮食不进、溲热口干、舌苔薄腻，乃暑湿痰滞郁结上焦、气机不通之候。脉弦小滑正合痰湿郁阻而正气已虚，故先以石菖蒲、枳壳、桔梗、佩兰宣开上焦，待胸闷松后再议调补气血。", ["弦", "小", "滑"]], "766": ["病机", "脉细小，细为阴液亏少、脉道不充，小为气血不足。患者年六十一，身体素瘦，阴液素亏，兼有郁抑，复受暑邪，故头晕心悸、胸闷嘈杂、时发寒热、口干溲热。脉细小正合阴亏体弱之质，暑邪乘虚而入，故以轻剂清暑养阴、调畅气机，二剂而愈。", ["细", "小"]], "767": ["病机", "右脉弦数，弦为湿郁气滞，数为热邪内蕴；舌苔白腻、小便热、午后发热、胸闷作恶、泄泻，乃湿温病湿遏热伏之候。前医误用元参、麦冬滋腻，致热愈甚。药后脉转缓小，缓小为邪退正虚、湿滞渐化之象，故胸次作痛、怔忡手麻、咳嗽舌尖红，示余邪未清而气阴已伤。", ["弦", "数", "缓", "小"]], "768": ["病机", "脉滑主痰湿，右脉滑数说明痰热壅滞上焦。初起咽喉红肿白点、寒热头疼、舌苔淡黄腻，为湿热痰滞酝酿；次日右脉滑数、咽喉破烂、汤水难下，乃痰伏上焦化热。脉滑数与此痰热内蕴之喉症相应，故治以清化痰热。", ["滑", "数"]], "769": ["病机", "脉息弦细，细为阴血亏虚，弦主气机郁滞。患者羸瘦、经闭、咳嗽发热、胁痛不寐、舌光赤无苔，显系阴液耗竭、肝郁化热。脉细如蛛丝提示阴血大伤，弦为木郁不达，故见肌肉瘦削、饮食不进，治以养阴退热兼消积滞。", ["弦", "细"]], "770": ["病机", "脉左缓大，左脉候肝肾，缓大为气虚不敛、络脉弛张之象。偏枯在左，因血虚不荣筋骨，内风袭络。脉缓大反映肝肾亏虚、内风扰动，与半身不遂相应，故病机为血虚络空、风动为患。", ["缓", "大"]], "771": ["病机", "脉细而数，细为脏阴亏虚，数为营液耗损。患者右肢偏痿、舌本络强、言謇，因冬暖失藏、肝木风动，真阴被劫。脉细数正是液虚风动之征，与神愦如寐等症相应，故议复脉法以滋阴熄风。", ["细", "数"]], "772": ["病机", "原文仅言“脉络之虚”，未列具体脉象。嗔怒动阳，厥阴内风乘阳明脉络之虚上凌，致指节麻木，为痱中根萌。病机属阳升热蒸液亏、下虚上实，故治宜柔润调肝，忌苦降辛散。", []], "773": ["病机", "原文仅述“脉络空虚”，未载具体脉象。阳明脉络空虚，内风暗动，故右肩胛及指麻木。病机为胃虚表疏、络脉失养，风邪乘虚入络，治以玉屏风散固表加当归、天麻、桑枝养血熄风通络。", []], "774": ["病机", "脉小弱，小为气虚，弱为阳衰。寡居独阴无阳，操劳伤气，当夏阳气外泄，忽然右肢麻木不举、汗出麻冷、心中卒痛，显系卫阳虚弱、络脉痹阻。脉小弱非外感，故治以固卫阳为主，佐宣通脉络。", ["小", "弱"]], "775": ["病机", "原文仅言“脉络已空”，未出具体脉象。阳明脉络空虚，厥阴阳气易逆，风胜为肿，热久为燥，面热、喉舌干涸、心中填塞，皆阳化内风、胃受冲侮之象。病机属风阳燥热、下虚上实，久延虑痱中。", []], "776": ["病机", "脉虚为阳明脉气不足之象。高年思虑忧愁，神意俱伤，肉脱肢废而成痿。脉虚说明中土衰薄，土虚则木横，厥阴风动。治当培中，若穷治风痰则劫烁正气，反致谬误。此脉虚正是土衰木横、痿象已成之根由。", ["虚"]], "777": ["病机", "脉左大右濡，左大主厥阴内风掀越，右濡主中阳已虚。老年隆冬暴中，阴阳失交，内风动而中阳衰，故神惫欲寐。左大右濡并见，正是肝风内动、阳明中虚之候，故宗阳明厥阴主治，肝胃同治。", ["大", "濡"]], "778": ["病机", "脉濡无热，濡主湿，无热则非热邪。厥后右肢偏痿、口㖞舌歪、声音不出，乃阴风湿晦中于脾络，寒滞汤药蔽其清阳，清气不展。脉濡正合湿中脾络之机，法当益气攻风祛痰，与风中廉泉之任脉病有别。", ["濡"]], "779": ["病机", "脉虚数为肾虚液少、肝风内动之象。虚为精血不足，数为虚热内扰。病在左躯而成偏枯，非外来之邪。肾阴虚则肝木失养，虚风内动，故脉虚数而症见偏枯，属内伤虚风而非外感。", ["虚", "数"]], "780": ["病机", "脉弦动主肝阳炽盛、虚风内动。眩晕耳聋、行走气促无力、肛痔下垂，乃肾阴弱收纳无权、肝阳虚风蒙窍，上实下虚之象。弦动为肝风鼓动之脉，故质厚填阴、甘味熄风，可免仆中。", ["弦", "动"]], "781": ["病机", "脉细小带弦，细小为肾阴亏虚，弦为肝风内动。冬季藏纳少固，遂至痱中。语言謇涩、多言少续，乃肾脉不营舌络、机窍少宣，属虚象。脉细小带弦正合下虚风动之机，故用地黄饮子治下、星附六君子益虚宣窍。", ["细", "小", "弦"]], "782": ["病机", "原文未出脉名，以五志气火交并于上立论。怒劳忧思致肝胆内风鼓动盘旋，上盛下虚，故足膝无力；肝木壮火乘袭胃土，故唇舌麻木、肢节如痿，为中厥之萌。此段重在阐发内火召风、上盛下虚之病机，非以脉断。", []], "783": ["病机", "左关尺独得动数，动数为厥阴阳挟内风纠扰；阳明脉中空乏，则真气不主藏聚，下无力行动。多语舌音不清、右肢麻木、心中热炽、喉燥多咳，皆下虚上实、虚假之热上泛之象。脉中空乏正示阳明空虚、虚风内动之机。", ["动", "数", "空"]], "784": ["病机", "左脉小弦动数，右手和平略虚，示肝肾阴亏、内风旋动。小为阴血不足，弦动为风阳上扰，数为热象。原文谓“热则真气泄越，虚则内风再旋”，故见头晕、目泪、足痿、舌刺微咳，皆风阳升于上、下焦无气之候，治当补肝肾摄纳、清上安下。", ["小", "弦", "动", "数"]], "785": ["病机", "原文未出脉名，然述“液燥下亏，阳挟内风上引，阴不上承”，致舌络强而言謇、气不注脉而肢痿乏力。此肝肾阴液本虚，阳失所附而化风上扰，筋脉失濡。镇补之中微逗通阳，因脏液虚不受纯温，故以柔润通补为法。", []], "786": ["兼症", "“脉左颇和”指左脉渐趋平和，为苦味和阳后阳亢得降之象。然心悸少寐，乃营气衰微、心失所养。左脉虽和而营虚未复，故仿酸枣仁汤养营安神，兼和阳益心气以通肝络，属调理善后之候。", ["和"]], "787": ["主病", "左脉数、右弦缓，年高形盛气衰，冬春之交真炁不相维续，内风日炽。数主热，弦主风，缓为气衰湿滞。风火痰阻络，故左肢麻木不仁、舌歪言謇，属中络之轻证。原文注“痰火阻络”，治当清火化痰通络，戒酒肉可望向愈。", ["数", "弦", "缓"]], "788": ["病机", "左脉濡涩，濡为气虚湿滞，涩为血少脉道不利。有年偏枯，原文引丹溪“麻为气虚，木是湿痰败血”，又谓“气血皆虚”。濡涩并见，正合气虚湿痰与血虚并存之机，故驳方书左属血虚、右属气虚之偏，示偏枯当责气血两虚。", ["濡", "涩"]], "789": ["其他", "此段论中风分类与类中三因，未出具体脉象。原文列真中、类中及中经络血脉脏腑之分，又引河间主火、东垣主气虚、丹溪主湿痰热生风，三者皆辨类中之由。虽无脉可据，然示类中风病机多端，当合脉症辨其虚实。", []], "790": ["病机", "“阳明脉空”指右脉空虚，主气血不足。肝阳虚风上巅则头目不清，阳明脉空则腰膝酸耎。空脉为虚，阳虚不能温养，风动于上而虚于下，故议养血熄风，使血充风息，阳有所附。", ["空"]], "791": ["治法", "此段仅出方治，未载脉象。复脉汤去参姜麻仁，加生鳖甲汤煎药，乃炙甘草汤加减。去温燥之参姜麻仁，加鳖甲滋阴潜阳，示阴亏阳浮、脉现虚数或结代者，当以复脉滋阴、潜镇浮阳为法，属治法条文。", []], "792": ["病机", "脉空旷、脉络交空显然，乃素禀阴亏，冲任奇脉失养，络血空虚之象。春交阳气升举，虚人随升，气动横逆，致痛从腿肢筋骨上及腰腹心胸，面赤如赭，饥不欲食，耳失聪，寤不成寐，阳浮于上。脉空应络血失养，故先和阳治络。", ["空"]], "793": ["病机", "脉弦小数，弦为阳升内风旋动，小数为阴液耗损、血分有热。操持积劳，阳气化火，壮火食气，烁筋损液，故形体日瘦，口舌糜碎，肩背掣痛，肢节麻木，肤腠瘙痒，目眩晕耳鸣。脉弦小数正合阳升血热、内风震动之机。", ["弦", "小", "数"]], "794": ["病机", "脉右虚左数，右虚主营液内耗，左数主肝阳内风震动。营液亏虚，肝阳失潜，化风上扰，故心悸眩晕少寐。此心营热而肝风动，脉虚数并见，虚为液耗，数为热扰，病机在营液内耗、肝阳化风。", ["虚", "数"]], "795": ["预后", "脉象模糊，肝风阻窍，正气外脱之危候。牙关紧，咽痹不纳汤水，机窍闭塞，虽有方药难以通关。脉模糊示正气涣散，故有外脱之危，预后凶险。当刮指甲末温汤调灌，苏合香擦牙，倘关开再议他法。", []], "796": ["病机", "脉右弦，右主气，弦为肝阳郁勃之象。肝阳上郁，清窍失司，故头胀耳鸣火升。脉弦应肝，右弦示气分郁滞，阳升于上，清窍被扰，病机在肝阳上郁、清窍不利。", ["弦"]], "797": ["病机", "脉数，夏季阳气暴升，烦劳扰动，内风上阻清窍，故口㖞舌强，呵欠，机窍阻痹不灵。数脉主热，乃络热窍痹，司气所致，非表邪为病，故忌投温散。脉数应内热风动，非外感之数。", ["数"]], "798": ["病机", "脉数面赤，数主热，面赤为阳升之征。肝风尚动，阳热上浮，故宜和阳熄风。脉数应内热，面赤应阳升，二者合参，知肝风内动、阳热偏亢，非表邪所致。", ["数"]], "799": ["病机", "脉来弦动而虚，弦动为厥阴内风暗旋不熄，虚为阳明脉衰、气伤阳动。望六年岁，阳明脉衰，胃脉不主束筋骨利机关，肝阳直上巅顶，汗从阳气泄越，春月病发，劳力病甚。脉弦动而虚正合胃虚表疏、气愈伤阳愈动之机。", ["弦", "动", "虚"]], "800": ["病机", "左脉弦，为肝脉之象。原文谓“气撑至咽，心中愦愦”，乃肝气上逆、冲心犯咽所致。此脉弦主阴耗阳亢，肝体失养而肝用独亢，故见气逆、心悸不安。治以养肝之体、清肝之用，正合弦脉所主之肝阴不足、阳亢气逆病机。", ["弦"]], "801": ["病机", "原文未明言脉象，但述“脉中气逆混扰”，可知脉气紊乱。病由操持怒劳内损乎肝，致少阳上聚为瘕、厥阴下结为疝，冲脉不静，气燥热化，风阳交动。诸症如气冲至心、头眩目花、耳内风雷、四肢麻痹，皆肝风内扰、营液日耗之象，总属肝风为害。", []], "802": ["病机", "原文未出脉象，然述“胃脉不复，气愈不振”，可知脉当弱而不振。病由情志菀结，冬温阳气不潜，春令阳勃化风，阴虚阳亢，内风扰络，清窍蒙塞，舌喑不言。肝风内扰，阳明受冲，胃脉不振，不束筋骨，致鼻准光亮、肌肉浮肿，总属虚风内动之候。", []], "803": ["病机", "此段未及具体脉象，而论“阳冒不潜”之病机。情志内因致病，阴阳脏腑不和，肝为风木之脏，体阴用阳，相火内寄，其性刚主动主升。阳冒不潜即肝阳上亢、阴不敛阳之机，故治当和阳就阴，药用牡蛎、白芍、地黄、菊等，以水生木、木生火、火生土，崇生气以复阴阳之平。", []], "804": ["主病", "脉左浮弦数，浮主阳浮，弦主肝风，数主火盛。原文谓“痰多，脘中不爽，烦则火升眩晕”，乃少阳相火挟痰上扰，阳明失降。左脉候肝胆，浮弦数并见，为肝阳化火、痰火升腾之象，故议少阳阳明同治，清火化痰以平眩晕。", ["浮", "弦", "数"]], "805": ["主病", "脉弦动，弦为肝风，动为阳升。原文谓“眩晕痰多，胸痹窒塞”，乃清阳少旋，内风日沸，挟痰上扰。当春地气上升，肝阳易动，最虑风痱。弦动之脉正合肝风内动、痰浊阻络之病机，故以熄风化痰为治。", ["弦", "动"]], "806": ["主病", "脉芤弱，芤主阴血不足，弱主阳气虚馁。原文谓“痰多眩晕，心神过劳，阳升风动”，乃劳心耗阴，阴不制阳，虚风上扰。芤弱之脉示气血两虚，不可过饮助升，治当健中化痰、缓晕熄风，以复中焦升降之机。", ["芤", "弱"]], "807": ["病机", "两寸脉浮大，寸候上焦，浮大为阳亢气火上升之象。原文谓“气火上升，头眩，甚则欲呕吐”，乃厥阴上干，久则阳明失降，土被木克，脾胃俱伤。浮大之脉主肝阳化火上冲，胃气不降，故先当镇肝阳以平冲逆。", ["浮", "大"]], "808": ["病机", "左脉弦劲为肝风相火内动之象，右脉小平示中焦尚和。操持惊恐伤神，相火肝风上窜，故目跳头晕；阴弱欲遗乃下元不固。弦劲为肝木刚强之征，风阳升动无制，与上窜诸症相应，属上实下虚之候。", ["弦", "小"]], "809": ["病机", "原文未出脉名，以“络脉中热、阳气变现、内风上冒”立论。眩晕已缓而络热未清，热化内风在上，根本虚在下，故曰上实下虚。此非外风，乃阳气变现之内风，先清标恙即清络中郁热，使上冒之风阳得平。", []], "810": ["病机", "阳明脉弦大而坚，厥阴脉小弦数促，弦为肝风，大坚为阳亢，数促为火郁。操持怫郁，肝阳挟内风直上巅顶，故面赤头痛绕脑后、惊惕肉𥆧、汗出；木火戕胃则呕逆。春深司候，阳升愈甚，虑暴厥瘈痉，故议柔缓熄风和阳。", ["弦", "大", "坚", "数"]], "811": ["病机", "原文未出脉名，论头风偏正之分。偏者主少阳，风淫火郁为多；阴虚火浮、气升吸短者，升散太过反萌厥脱。故另出轻清凉泄以解少阳郁遏，久则伤肝阴，参咸凉柔镇。肝阴久耗、内风日旋、厥阳无宁，非汤散可解，当复脉纯甘壮水、胶黄柔婉熄风。", []], "812": ["病机", "原文未出脉名，以“少壮精气未旺、奇脉纲维失护”言病机。形不足温气、精不足补味，今纳谷如昔而精亏，故以血肉充养。奇脉失护即阴维、阳维、冲任失其维系，精血不充则纲维不固，属阴虚之损，非谷食所能补。", []], "813": ["预后", "原文未出脉名，以“形脉生气内夺”断预后。疬劳发于出幼之年，真阴日消烁，冬月可延、入夏难挨，因夏火耗阴更甚。救阴无速功，故难治，用两仪煎培补真阴。形脉生气内夺即形神与脉气俱衰，为损怯难复之象。", []], "814": ["预后", "脉左数甚，左属肝肾，数甚为阴亏火动、真气不守。春病至夏，天地大气发泄，形色消夺，为损怯之症；交节病加尤属虚象。肛有漏疡，下夺精血，与上损相应，故最难全好。数脉在此非实热，乃虚阳浮越、真阴耗损之征。", ["数"]], "815": ["病机", "原文未出脉名，言长夏久热伤损真阴，深秋收肃而身中泄越已甚，故吸短精浊、消渴眩晕，症属肝肾。脉由阴渐损及阳明胃络，纳谷减、肢无力，即越人“阴伤及阳”之旨。真阴亏则阳无所附，胃络失养，故治损难于治病。", []], "816": ["治法", "原文未载具体脉象，仅言“脉神形色”以察老年衰惫。年高血气有情之属渐亏，故无攻病成法，主以人乳牛乳炖暖入姜汁栽培生气，属治法范畴。", []], "817": ["病机", "脉数虚为稚年阴亏阳亢之象。春阳化风地升，暮热晨汗，肌柔白，非客邪清解，乃阴虚不能制阳，虚热外浮，故仿仲景复脉法去姜桂加甘蔗汁以养阴和阳。", ["数", "虚"]], "818": ["病机", "脉小数疾，童真阴未充长而阳独升降，囊下肛前已有漏卮，巅窍如蒙，皆阴亏火旺、虚阳上扰之机，故与壮水制火，生六味去萸肉加生白芍黄柏知母人中白。", ["小", "数", "疾"]], "819": ["病机", "原文未出脉名，仅言“脉尺垂少藏”，尺脉垂而少藏，唾痰灰黑，乃阴水内亏、阳火来乘，为损怯之萌，年过三旬静养可充旺，主病机在肾阴亏虚。", []], "820": ["病机", "原文未载脉象，述遗浊日久，喉中哽噎，肾阴消烁，龙雷不肯潜伏，浮阳蒸灼，柔嫩肺伤，为痹为宣，不外阴虚阳亢，故养育阴气贵乎宁静，药以六味加减介以潜阳。", []], "821": ["病机", "脉细涩入尺泽，下元精亏，龙旺火炽，口齿龈肿，皆下焦虚阳上越，引火归窟；形瘦液少虑其劫阴致疡痈，故虎潜去广归锁阳加山药苁蓉青盐羊肉胶丸。", ["细", "涩"]], "822": ["病机", "脉坚，咽阻心热，得嗳气略爽，腰膝耎弱，精滑自遗，必因惊恐伤及肝肾，下虚则厥阳冲逆而上，法宜镇逆和阳，继当填下，主病机为下虚阳逆。", ["坚"]], "823": ["病机", "脉数垂入尺泽穴中，阴精未充早泄，阳失潜藏，汗出吸短，龙相内灼，升腾面目，肺受熏蒸，嚏涕交作，胃弱少谷，精浊下注溺管疼痛，肝阳吸其肾阴，显然肾虚如绘，议有情之属填精。", ["数"]], "824": ["病机", "左脉细为精血亏少，右脉空为气不摄固，合之色夺神夭、声嘶，显系下焦精伤、上焦气耗。精伤则咳，气不固则汗，劳怯重病由此而成。脉细主阴亏，空主气散，故曰药难奏功，用大造丸填精固气。", ["细", "空"]], "825": ["病机", "左脉弦搏，弦为肝旺，搏为阳动不潜。著枕眠卧则冷痰上升，交子后干咳，乃肾虚阳不潜伏，虚阳挟痰上逆。弦搏非实热，是阴不敛阳之象，故从摄固引导，勿骤进温热燥药，以免助阳耗阴。", ["弦", "搏"]], "826": ["预后", "脉细促而三五欲歇止，细为阴精竭，促为阳气欲绝，歇止则脏气无根。头垂欲俯、著枕即气冲不续，皆肾不纳气、督脉不用之征。虚损至此，脉症俱败，故断必无挽法，属死候。", ["细", "促"]], "827": ["治法", "原文未出脉名，但言脉症仍然，知肝厥虚症未复。用咸味入阴、介类潜阳、酸味收敛，皆从阴引阳之法。夏令大气主泄，烦劳则病发，故须静养经年，使阴阳自交，病可全去，是虚症缓图之治。", []], "828": ["病机", "脉细数，左垂尺泽，细为真阴不足，数为龙相刻燃。先天素薄，精通年岁阴气早泄，津液暗消，虚怯根萌。故药宜至静纯阴，知柏六味加龟甲天冬猪脊髓，滋填下焦以制相火。", ["细", "数"]], "829": ["病机", "原文未出脉名，然阴精下损、虚火上炎、脊腰髀酸痛、髓空，显系督带诸脉失养。精亏则髓空，虚火浮越则见热象，法当填髓充液，莫以见热投凉，点明此热为虚火，不可苦寒直折。", []], "830": ["病机", "原文未出脉名，述破伤失血后神气无护，冬令阳微畏寒，奇脉少津，行步欹斜、健忘若愦，皆精气内夺之征。将交大雪纯阴无阳，见此离散之态，是精衰气竭，虽平素不受暖补，今则不拘此例，当以藏阳为要。", []], "831": ["病机", "原文未出脉名，言阴精走泄于下，阳气郁冒于上，太冲脉衰，厥气上冲，陡然痫厥。阴阳失交，阳随汗泄，故治从阴引阳、从阳引阴，大封大固，以蛰藏为要，远房帏、独居静室，百日可效。", []], "832": ["病机", "形躯丰溢而脉来微小，形盛脉弱，是阳气不足于内，不能充达脉道。原文谓“阳气不足体质”，又言理烦治剧、曲运神机皆“伤阳之助”，说明此脉微小非外邪实滞，乃劳神耗阳、体质本虚之征，故治以温养有情、栽培生气，不与逐邪攻病同例。", ["微", "小"]], "833": ["病机", "原文未出脉名，以“少壮形神憔悴”与“身体前后牵掣不舒”立论，断为“奇经脉海乏气，少阴肾病”。少壮当盛而形神反悴，前后牵掣属督任跷维失养，故知非外邪，乃少阴肾气不充、奇经脉海乏气，筋骨失于温煦所致。", []], "834": ["病机", "原文未出脉名，述经迟、晨泄、心若摇漾、得食姑缓、肛疡久漏，断为“病在至阴之脏，延及奇经八脉”“都属下损”。经迟晨泄属肾阳不足，心摇得食缓属中虚，久漏更耗精血，故知至阴脏损累及奇经，冲任不充而艰于孕育。", []], "835": ["病机", "诊脉数、左略大，数主虚热，左大属肝肾阴亏不敛。症见足痿、盗汗、梦遗、脊椎骨凸，原文推为“先天禀赋原怯，未经充旺，肝血肾精受戕”，致奇经八脉乏运用之力。脉数大非实火，乃精血损伤、筋骨间病之内应。", ["数", "大"]], "836": ["病机", "原文未出脉名，专论精血有形，草木无情难补，桂附刚愎愈劫脂膏，知柏苦寒沉著未通奇脉。主张“柔剂阳药，通奇脉不滞，且血肉有情，栽培身内之精血”。此段阐发虚损病机在精血亏而奇脉不通，故治法取柔通血肉，王道缓图。", []], "837": ["病机", "原文未出脉名，述辛温咸润柔剂通药服有小效，断为“劳伤肾真，而八脉皆以废弛失职”。肾恶燥，故用柔润；劳伤肾真则八脉失其统摄，故议进升阳法。此段明奇脉兼阳虚之病机，非单纯补益可复。", []], "838": ["病机", "原文未出脉名，述父母弱症早丧、禀质不充、年二十未娶而见损怯，寒热遇劳而发。引《内经》“阳维脉衰，不司维续，护卫包举”，下部无力，有形精血不得充涵筋骨。下元之损必累八脉，故医药徒补无用，明禀赋虚损之病机。", []], "839": ["病机", "原文未出脉名，直断“肝肾损伤，八脉无气，未老衰惫大著”。肝肾精血亏则奇经八脉失养，故未老而衰惫显著。议通阳守阴一法，即于阴中求阳、通补兼施，以复八脉之气。此段明肝肾损伤累及奇经之病机。", []], "840": ["病机", "原文言「摇精惊恐，肝肾脏阴大泄，阳不附和」，虽未出脉名，然所述病机为惊恐伤及肝肾，阴精下泄而阳气失于依附，致阴中百脉之气自足至巅、起自涌泉而逆乱。此非外邪，乃内伤阴阳翕阖失司，故以招集溃散卒伍喻用药调燮阴阳，使阴阳复归翕阖。", []], "841": ["病机", "脉虚细，虚为气夺、细为阴亏，合之「夜热晨寒、烦倦口渴、汗出」，显系脏液已亏、元气有伤。春气外泄则阴不内守，虚阳外浮故夜热汗出；晨寒烦倦乃阳失所附。叶氏宗《内经》甘药养元、复脉汤滋阴，正为此虚细之脉所主之脏液亏虚、元气损伤而设。", ["虚", "细"]], "842": ["病机", "原文未出脉名，而言「脏阴久亏，八脉无力，是久损不复」，兼「中脘微痛，脐中动气」。八脉无力即奇经失养、元真虚惫之象；脐中动气乃下焦虚寒、冲气上逆。久损不复非滋腻凉药可解，故仿大建中温养元真、壮其奇脉，为通纳方法，主病在奇脉虚损、元真不固。", []], "843": ["预后", "虚劳三年，形神大衰，食减便溏，寒热交作，每咳必百脉动掣，胁肋攻触，是病深传遍、损伤已极之候。脉动掣者，百脉失养而躁动不宁，非草木可振。前服四君子加桑丹不应，今益气少灵，理从营议，暂用理阴煎镇逆固摄，若胃苏知味方有转机，否则难拟法，故归预后。", ["动", "掣"]], "844": ["病机", "脉细属脏阴之损，平素畏寒怯冷，少年阳气未充，夏令暴泻本为时令湿热，未必遽然虚损，而今谷减形瘦、步履喘息，劳怯显然。细脉主阴血亏少、脾肾失养，故下损及中，当理脾肾。此脉此症示脏阴内损、阳气不充，非一时湿热暴泻可比。", ["细"]], "845": ["预后", "脉如数而垂入尺泽，数为阴亏阳扰，垂入尺泽则脉势下坠，主肝肾下损。病起下焦，延及脾胃，正合秦越人「自下焦损伤，过中焦则难治」之说。数脉非实热，乃虚阳不敛、真阴亏耗之象，故预后堪虑，示下损及中之难治。", ["数"]], "846": ["病机", "脉空虚，为气血俱亏、八脉失充之象。病损不复，八脉空虚，不时寒热，间或便溏，虽步履饮食如常，而周身气机尚未雍和，乃虚损未复、脾肾两亏之候。空虚之脉正应八脉空虚、元气未复，故前丸药仍进，煎方宗脾肾双补，虑其调摄失慎而反复。", ["虚", "空"]], "847": ["病机", "寸口动数，动为阳浮不宁，数为热扰，合之冲年久坐诵读、五志之阳多升、咽干内热，显系真阴不能自旺于本宫，阴虚阳浮。阳升无制则动数见于寸口，怕有见红之虑，故以甘寒缓热为稳，不致胃枯。此脉主阴虚阳浮兼胃阴虚，非实火可比。", ["动", "数"]], "848": ["病机", "脉左坚而上下直行，坚为阴凝不柔、直行为气机失于柔和之象。左脉属肝肾，精血亏虚则脉失濡养而现坚劲，虚热随气机升降起伏，故言精损、热自升降。此非实邪壅滞，乃精亏不能涵养、虚热内扰之病机。", ["坚"]], "849": ["病机", "脉弦主肝木偏旺、气机郁滞。胁痛引及背部，是肝络失和、气郁不达；食减则木旺乘土、脾胃受困。合而观之，弦脉在此示营血亏损、肝郁化劳之机，故断为营损传劳，非单纯外邪为患。", ["弦"]], "850": ["病机", "脉耎即软，为气血不足、脉道失充之象。不嗜食、腰酸无力，见脾胃与肾气俱虚；咳烦劳则营阴亏耗、虚火上扰。软脉不任按，正合营虚不能充脉、脏腑失养之病机，故以营虚所致总括之。", ["软"]], "851": ["病机", "左小右虚，左主营血、右主中气，小为不足、虚为无力，合示胃阳已弱、营卫失护。背寒肢冷、痰多微呕、食减不甘，皆中阳不振之症；小便短赤、大便微溏属虚象而非实邪。故立建中气以维营卫之法，明辨偏寒偏热皆非正治。", ["小", "虚"]], "852": ["治法", "右脉濡而来去涩，濡为阳气不充、涩为血行不畅，右部主脾胃中焦。中阳式微则脉道濡软无力，营血痹阻则往来艰涩。前案已立建中，此以辛甘化阳、用大建中汤，正针对中焦虚寒、营卫不和之病机而设。", ["濡", "涩"]], "853": ["病机", "脉来小弱，小为脉道不充、弱为鼓动无力，是阳气虚损、营血不足之征。劳倦伤阳则形寒，阳损及阴则骨热，然脉无实滞之象，说明非有形邪积。故以和营为治，着眼于虚损而非攻邪。", ["小", "弱"]], "854": ["病机", "脉左甚倍右，左属心肝、右属肺脾，左倍于右示君相之火上亢莫制。原文归因于操持劳思所伤，劳心耗神则阴不制阳、火失潜降。故非单纯药力所能尽，须山林静养以复心神，属劳伤心神、虚阳上浮之病机。", []], "855": ["病机", "脉形虚小，虚为营气不足、小为脉道不充，右部带弦则木气偏旺。操持思虑伤心营，劳力泄气更耗中气，气不摄血故痰带血出。虚小为本、弦为标，示心脾两虚而肝木乘之，故用归脾汤加减养心健脾、柔肝和营。", ["虚", "小", "弦"]], "856": ["病机", "原文未出脉名，以“神困食减、五心热、汗出”断为元气虚而阴火盛。劳倦耗气，中焦不运则食减神困；元气不足则阴火浮越，故五心热而汗出。此非实火，乃虚火上炎，故宜补中生脉四君子汤，培土以敛浮火。", []], "857": ["病机", "未录脉象，以“既暮身热、汗出早凉、食减半、色脉形肉不足”定内损劳怯。暮热早凉为阴分不足、阳无所附；劳而食减、形肉不足，是脾胃营卫俱损。故用人参小建中汤建中气、和营卫，非逐邪之法。", []], "858": ["预后", "“右脉空大”而色痿黄，右脉主气，空大为气分泄越、中气不守之象；色痿黄为脾土衰败。久劳内损，汗出食减，身不耐大气泄越，故曰衰极难复、无却病方法，仅议封固一法，属劳损重候之预后判断。", ["空", "大"]], "859": ["病机", "“脉小右弦”，小为正气不足，右弦主中焦气偏、木邪犯土。久嗽晡热、著左眠稍适，是阴亏而肝肺之气偏著。二气已偏即为损怯，故戒逐邪清泄，当与甘缓，黄耆建中去姜以培中缓肝。", ["小", "弦"]], "860": ["病机", "“脉大而空”为阴血亏虚、气无所附之象，故主亡血失精。午食不运、入暮反胀，是阴伤及阳，脾阳亦不能运化。脉大非实，空则中虚，缠绵反复，归芍异功散养血健脾以调之。", ["大", "空"]], "861": ["病机", "“脉细无神”为精气内衰、下元不纳之征。中年身动喘嗽、食减过半，是肾不纳气，五液蒸变黏涎，未老先衰。细而无神，非邪实，乃根本虚竭，故断为劳病，主在肾气不纳。", ["细"]], "862": ["病机", "未出脉象，以“奔走之劳最伤阳气、能食不充肌肤、四肢常冷”立论。劳则阳气耗散，经脉之气不得贯串四末，故四肢寒冷而肌肉不充。此劳伤经脉、阳气不布之童损，非外邪所致。", []], "863": ["病机", "引《金匮》“脉大为劳，极虚亦为劳”分两层：脉大为气分泄越，思虑郁结使心脾营损于上中，营分萎顿，宜归脾、建中、养营之属；脉极虚为精血内夺、肝肾阴不自立，宜六味、八味、天真、大造、复脉及平补足三阴固摄诸法。同曰劳而虚实异治。", ["大", "虚"]], "864": ["治法", "本段未出具体脉象，以“分其体质之阴阳为要领”立论，论虚劳调治大法。原文强调“柔剂养心脾之营液”“甘温气味建立中宫”，使“二炁日偏”得复、“营卫循行”；纵欲伤精者“治下而兼治八脉”，并辨“填补精血精气之分，益火滋阴之异”。所论以体质阴阳、上中下见症为据，属治法范畴，非凭脉断病。", []], "865": ["病机", "徐评辨虚劳两途：仲景所论虚劳属“虚寒之症”，故脉“浮大芤迟”，浮大芤为精血虚而阳浮，迟为虚寒，故用建中；今之虚劳乃“阴竭而浮火上炎”，脉“皆细数”，细为阴亏、数为火升，与建中汤“正相反”。原文以脉之浮大芤迟与细数对举，明虚寒与阴虚火升病机迥异，误投建中可变喉痹血冒。", ["浮", "大", "芤", "迟"]], "866": ["主病", "脉沉细而“形寒咳”，沉主里、细主虚，脉沉细与形寒相应，示阳气不足、寒饮内伏，肺失温宣而咳。此段以脉沉细定病位在里、病性属虚寒，主虚寒咳嗽之证，形寒为外候，咳为肺气上逆，脉症合参，非表邪实热之咳。", ["沉", "细"]], "867": ["病机", "“咳嗽，声音渐窒”，诊得“右寸独坚”。右寸候肺，独坚示邪气壅聚肺俞，原文谓“寒热客气，包裹肺俞，郁则热”，即寒邪外束、郁而化热，肺气壅遏故声窒。坚脉主邪实气壅，非虚细之象，故先以麻杏石甘汤散寒清热，属寒包热之病机。", ["坚"]], "868": ["主病", "风温而“脉虚”，虚为正气不足，风温之邪乘虚犯肺，故见嗽。脉虚与风温并见，示正虚邪袭、肺失清肃，主风温咳嗽而体气偏虚之证。此段以脉虚点明虚实夹杂，非单纯实热风温，故列于风温门中，提示察脉虚以顾护正气。", ["虚"]], "869": ["主病", "“脉右搏数”，右脉候肺，搏数示邪热鼓动于肺。风温之邪犯肺，热盛则脉数而搏指，肺气上逆则为呛咳。原文以右搏数定病位在肺、病性属温热火盛，主风温呛咳之证，数脉为热，搏为邪实，与风温化热之机相应。", ["数"]], "870": ["病机", "“脉右浮数”，右候肺，浮为邪在表、数为热，示风温之邪干肺。原文谓“风温干肺化燥”，热灼肺津则喉间痒、咳不爽，故用“辛甘凉润剂”以润燥清热。浮数脉与风温化燥之机相应，主肺燥咳嗽，病位在肺卫，性属温燥。", ["浮", "数"]], "871": ["病机", "本段未出具体脉象，仅言“形脉不充”。积劳伤正，更受风温，咽干热咳，形脉不充示气血不足、正虚邪扰。风温犯肺则热咳咽干，劳伤日久则形脉失充，故与“甘缓柔方”扶正柔润。所论以形脉不充点明虚实夹杂之病机，属风温兼虚之候。", []], "872": ["病机", "脉细数为阴分不足而温邪内郁之象。细主阴伤，数主热盛，温邪犯肺，灼津为痰，故咳嗽痰黄；热壅咽喉则咽痛。脉症合参，知非单纯外感，乃温邪内蕴、阴分受灼，故治当清温邪，透热保津。", ["细", "数"]], "873": ["病机", "右脉弦大，右寸候肺，弦主郁、大主热。温邪上伏于肺，郁而化热，灼液成痰，故咳嗽痰多而黄。弦大之脉示邪郁于上焦气分，非虚象，乃温邪伏肺、肺气壅遏之病机，故曰属温邪上伏之故。", ["弦", "大"]], "874": ["病机", "脉小数，小为阴亏，数为虚热。冬藏失纳，水亏于下，温邪伏于内，故干咳暮甚；能食者胃火犹旺。阴亏火旺，灼伤肺络，防其失血。脉小数为水亏温伏、阴不制阳之征，故用复脉法滋阴复脉，去参姜桂避其温燥。", ["小", "数"]], "875": ["病机", "脉左弱，右寸独搏，左弱主营血不足，右寸独搏为肺有郁热。久咳音嘶，肺津受灼；寐则噎阻咽，胃热上逆。平昔嗜饮，酒热酿痰，胃热遗肺。脉症合参，乃酒客胃热遗肺、肺失清肃之病机，故忌甜腻，取微苦微辛开上痹。", ["弱"]], "876": ["病机", "脉浮数，浮主邪在表，数主热。宿病营卫两虚，燥气上犯，暴凉外侮，气馁卫怯，肺先受邪，故咳喘欲呕；上热下冷者，虚寒于下而热郁于上。浮数示外邪犯肺、卫表不和之病机，治先清化上气，微辛微苦以宣降。", ["浮", "数"]], "877": ["病机", "右脉数大，右寸主肺，数主热，大主邪盛。嗽已百日，从夏季伏暑内郁，暑热蕴于气分，至秋而发，故脉右数大。数大为暑热内郁、肺气壅热之征，病在气分，故治在气分，清透暑热。", ["数", "大"]], "878": ["病机", "脉右大，右寸候肺，大为热盛。瘅热无寒，暑郁在肺，暑热内燔，肺气受灼，故但热不寒。脉右大示暑热壅肺、气分热盛之病机，故当清气热，佐宣通营卫，用桂枝白虎汤加麦冬，清肺胃而透暑热。", ["大"]], "879": ["病机", "热止而脉右数，咳不已，右寸候肺，数主热。热势虽退，肺中余热未清，故脉仍数而咳不止。此段示热退后肺热未尽、余邪恋肺之病机，脉数为余热未净之征，当续清肺热以竟全功。", ["数"]], "880": ["病机", "两寸脉皆大，寸主上焦，大则邪气盛于上。原文谓“冷热上受”“清邪中上”，说明暑风清邪侵袭上焦，肺失清肃，故咳嗽无痰。脉大在此非虚，乃邪实于上之象，与冷热上受、咳嗽无痰相应，故从暑风法以散上焦清邪。", ["大"]], "881": ["病机", "右脉弦数，弦主气机郁滞，数主热。原文谓久咳不已则三焦受之，冲脉受伤犯胃扰肺，气蒸熏灼，又加秋暑风、客气加临，营卫不和。弦数示暑风之邪郁于上焦气分，微寒热、渴饮为佐，故拟桂枝白虎汤温治上焦气分以表暑风。", ["弦", "数"]], "882": ["病机", "形瘦脉数，数主热，形瘦示阴分不足。原文谓骤凉暮热、肺失和为咳，小暑后得之，由时令暑湿之气所致。脉数反映暑湿郁蒸、肺失清肃之病机，热在气分而未成实，故轻则治上，大忌发散，以免耗伤肺气。", ["数"]], "883": ["病机", "右脉弦大而缓，弦主气郁，大示邪壅，缓为湿象。原文谓水谷气蕴之湿再加时序湿热，壅阻气分，故久嗽声嘶而浊、形瘦目黄。弦大而缓正合湿热痰火壅阻气分之机，久成老年痰火咳嗽，无性命之忧而有终年之累。", ["弦", "大", "缓"]], "884": ["病机", "脉沉弦为饮，沉主里、主水，弦主饮邪停聚。原文谓近加秋燥，上咳气逆，中焦似痞，是饮邪内伏于里，复感秋燥上扰，肺气不降故咳逆，中焦气机不利故似痞。沉弦示饮停于里，故以辛泄凉剂暂解上燥，标本兼顾。", ["沉", "弦"]], "885": ["病机", "脉右劲，劲主气火偏亢。原文谓疥疮频以热汤沐浴，卫疏易伤冷热，皮毛内应乎肺，故咳嗽气塞痰多；久则胃津日耗，不司供肺，加秋冬天降燥气，渐成老年痰火之象。右劲正示气分热燥、肺胃津伤之机，故宜清气热以润燥，忌投滞补。", ["劲"]], "886": ["病机", "脉弦，弦主气机郁滞。原文谓胸膈痹痛、咳嗽头胀，此燥气上侵，肺气不宣使然。燥邪犯上，肺失宣降，气机痹阻，故脉见弦、胸膈痹痛而咳。弦为燥气郁遏肺气之象，病位在上焦，故当用轻药以清上焦，宣肺润燥。", ["弦"]], "887": ["病机", "右寸独大，寸候上焦肺，右寸独大示肺之气分邪壅。原文谓气分咳已一月，说明邪郁肺之气分，肺失清肃而咳久不已。脉独大而非浮数，是气分壅滞、邪未透解之象，与气分咳相应，主病在肺之气分。", ["大"]], "888": ["病机", "脉右大，右主气，大则气分邪盛或气机弛张。原文以「寤咳寐安」辨病位：醒时咳而寐安，说明病在气分而非阴分。气分受邪，肺失宣降则咳，昼日气行于外故寤咳，夜卧气归于内故寐安。右脉大正是气分受病、气机不降之象，与咳嗽症候相应。", ["大"]], "889": ["病机", "脉右坚，右候肺与气，坚为邪实内结、气机壅滞。原文见咽阻、咳呛、声音渐低两月，是冷热之邪伤肺，肺气不利则咳呛，金实不鸣则声低。右坚说明肺中邪气胶结不散，非单纯表证，故断为冷热伤肺，与咽阻咳呛声低相应。", ["坚"]], "890": ["病机", "脉独气口空搏，气口候胃与元气，空搏为元气已伤、阴液亏虚之象；左大则属外感邪实。原文久疟伤阴、冬春温邪、入暮寒热晨汗，阴液损伤而阳愈炽，色消肉烁，故气口空搏主内伤虚多，与左大之外感实脉相别。此脉说明邪少虚多，忌发散，当以甘药理阳顾阴。", ["空", "大"]], "891": ["病机", "脉见细小，细为阴血不足，小为脉道不充，主脏阴亏虚。原文秋燥从天而降，肾液无以上承，故咳嗽吸不肯通、大便三四日一更衣，皆津液枯涸、脏阴失润之候。细小之脉正合阴液内亏、无以上承，故议治在脏阴，与咳、便艰相应。", ["细", "小"]], "892": ["病机", "脉右大而长，右候肺气，大为气分邪盛，长为邪气有余、壅滞不散。原文喉痹咳呛，是肺气不降、邪热上壅咽喉。右脉大而长说明肺中邪实气壅，非虚象，与喉痹咳呛之实症相应，主气分壅热之病机。", ["大", "长"]], "893": ["病机", "原文未识脉名，以「阳脉不用」言病机。形寒畏风冷、食减久嗽，是卫外阳气已怯，内应于胃，胃阳不振则食减，卫阳不固则畏风冷，久嗽由中气不足、肺失所养。阳脉不用即阳气虚而脉不鼓，故用药莫偏治寒热，以甘药调中，宗麦门冬汤法养胃阴以复阳气。", []], "894": ["病机", "脉左坚数促，左候肝肾，坚为阴亏阳亢，数为热，促为热盛而气机急促。原文冬温咳嗽，是水亏热升，龙相之火上炎，胃阴受伤，秽浊气味直上咽喉。坚数促正示水不制火、虚热内迫之机，故先议甘凉益胃阴以制龙相，与咳、咽中秽浊相应。", ["坚", "数", "促"]], "895": ["病机", "脉右数，右候肺胃，数为热。原文咳两月、咽中干、鼻气热、早暮甚，是右降不及，胃津虚而厥阳来扰。胃津不足则肺失润降，虚热上扰则咽干鼻热，早暮阳气升降之时故症甚。右数说明胃津虚而阳扰于上，与咳、咽干、鼻热相应，主胃津虚、厥阳上扰之病机。", ["数"]], "896": ["病机", "两寸促数，促为阳脉，数主热，寸部候心肺。患者形体日损、咳嗽吐痰，乃烦劳动阳、虚火上炎，不得天地收藏之令，故脉促数而大便通而不爽。此非实火，乃胃阴亏虚、虚阳浮越之象，故少纳胃衰，不可重进滋腻，议用甘味养胃阴，取麦门冬汤润养肺胃。", ["促", "数"]], "897": ["病机", "左搏数、右小数，数主火，小为虚。久咳三年、痰多食少、息鸣如喘，自觉内火燔燎，乃五液内耗、阳少制伏，非实火也。左脉搏数示肝阳偏亢，右小示脾肺气虚，故以琼玉膏滋水益气，勿损胃气为上，清肺治嗽之药无益于体病。", ["数", "小"]], "898": ["病机", "两寸脉大，寸候肺与上焦。咳甚、脘闷头胀、耳鼻窍闭，乃少阳郁热上逆犯肺，肺燥喉痒。脉大示郁热壅盛于上，木火刑金，故先拟解木火之郁，清胆火以复肺之清肃。", ["大"]], "899": ["病机", "脉小久咳，小为虚为弱。背寒骨热、知饥不食、厌恶食物气味，乃忧思悒郁、内损之候。前医以清寒治肺不应，因郁火伤胃、土虚不能生金。脉小示正气内损，故议益土泄木，培中焦以制肝木。", ["小"]], "900": ["病机", "右搏左涩，右候气、左候血。寡居烦劳，思郁致五志烦煎，气燥在上故右脉搏，血液暗亏故左脉涩。晨咳吐涎，病从胃治，以血海亦隶阳明，养胃阴以滋血源，非温热补涩所宜。", ["搏", "涩"]], "901": ["病机", "脉数主热，冲气咳逆乃阴虚阳浮、虚火上冲。劳嗽日久，肾阴亏耗，金水不能相生，故当摄纳肾阴、滋养柔金，为金水同治之法。脉数在此非实热，乃阴亏不能制阳之虚数。", ["数"]], "902": ["病机", "左尺坚，尺候肾，坚为牢实之象。久嗽失音、入夏见红、天明咳甚、纳谷减损，乃劳损之症。左尺坚示肾阴亏而虚火内灼，金水两伤，故急宜静养，不可妄攻。", ["坚"]], "903": ["病机", "脉耎即软，为虚为弱。久嗽咽痛、入暮形寒，虽属阴亏，然形痿脉耎，示正气衰惫、脾胃虚弱，故未宜夯补。耎脉提示虚不受峻补，当以缓图，先顾中焦化源。", ["耎"]], "904": ["病机", "左弱右搏，左候肝肾精血，弱为下元根蒂已薄、冬藏不固；右搏为春升之气失于潜藏而浮越。久虚损交春不复，夜卧气冲咳甚、行走气短喘促，皆肾不纳气、冲气上逆之征。故急当固纳摄下，非辛凉理嗽所宜。", ["弱", "搏"]], "905": ["病机", "热病反复，真阴必伤，脉震动乃冲脉失于镇摄之象。戌亥时厥昏汗出，为虚阳上冒、肝肾根蒂不牢，冲脉震动而气逆。脉动主阴阳相搏、虚阳浮动，故见昏厥汗出，非实热可攻。", ["动"]], "906": ["病机", "原文未出脉名，然言诸脉俱逆、阳泄为汗，是下焦阴不上承、阴阳两损之候。咳嗽非肺病，乃肾不纳气、冲气上逆。苏子钩藤皆泄气锋芒之药，施于阴阳两损最宜斟酌，故用都气加青铅收摄固纳。", []], "907": ["病机", "形瘦而脉垂尺泽，是肾虚不能摄纳、厥气上干之象。久嗽呕逆半年不愈，非肺脏本病，乃下焦虚气上逆。医者清寒治肺，反伤中下，故曰误人匪浅。脉垂尺泽正示肾气不守、虚阳上浮。", []], "908": ["病机", "右弦左沉，右候肺、左候肾，弦为气逆，沉为肾不纳。冬季咳痰，卧则气冲喘急起坐三载，是肺主出气、肾主纳气，老年肾气不收，气不归元。故以肾气丸去牛膝肉桂加沉香纳气归肾，不必因痔畏辛热。", ["弦", "沉"]], "909": ["病机", "两手脉弦细数，细为精气内损，数为虚热，弦为气逆。久咳损及中州，脾失输化，食减神倦，肺无所资而咳不已。此非泛常消痰治咳可投，乃精气内损、脾肺两虚之候。", ["弦", "细", "数"]], "910": ["病机", "脉搏大，大为阳不下伏、虚阳上浮之象。咳频喉痹，暮夜为甚，暮夜阴盛而阳愈不藏，故知阴虚火炎、阳不潜降。先从上治，是急则治标、清上焦浮火之意。", ["大"]], "911": ["病机", "脉来虚芤，虚为阳气再伤，芤为阴不固摄、血失所守。形色衰夺，久患漏疡，经营劳动更伤阳气，冬月客邪致咳，皆本体先虚。春深入夏天地气泄，身中无藏而日加委顿，故议补三阴脏阴方法。", ["虚", "芤"]], "912": ["病机", "脉细数，细为阴血亏少、脉道不充，数为虚热内扰。原文见干咳咽燥、脊酸痿弱，乃肺肾阴亏、虚火上炎之象：肺失濡润则干咳咽燥，肾精不足、骨失所养则脊酸痿弱。此脉此症提示本病欲损，属虚损之渐，非实热外感。", ["细", "数"]], "913": ["病机", "左脉弦数，弦主肝郁或木火偏亢，数主热。遗泄为相火扰动、精关不固；久嗽痰黄乃木火刑金、灼津为痰。脉弦数反映肝肾相火内炽、上灼肺金，下扰精室，故当用填补以滋水涵木、固摄下元，非清散所能治。", ["弦", "数"]], "914": ["治法", "脉濡为气虚湿滞、脉道软弱之象，合色萎、心悸、呛痰咳逆，乃劳心经营、气馁阳虚所致。中年向衰，中阳不运则湿痰内生，下元不固则肾真失守。故治法以中宫理胃、下固肾真为主，用大半夏汤通补胃阳，早服附都气丸温纳肾气，务以加谷为安。", ["濡"]], "915": ["病机", "脉细促，细为精血内亏，促为阳气不相接续、脉行急迫而时一止。久嗽寒热、身痛汗出，非外邪束表，乃精伤及胃、中气馁弱，营卫失和所致。精亏则脉细，气虚则脉促，故用黄耆建中汤去姜，甘温建中以复营卫。", ["细", "促"]], "916": ["病机", "脉得虚数，虚为气馁弱无以自立，数为虚阳浮越、气机不相接续。久嗽气急、短气少气，非外寒束肺、内热迫肺之实喘，乃三焦受病、中气亏虚所致。既曰虚症，虚则补其母，故用黄耆建中汤甘温补中以培土生金。", ["虚", "数"]], "917": ["预后", "左脉细、右空搏，细为阴营亏少，空搏为胃气不充、脉道失实。久咳吸短如喘、肌热日瘦，为内损怯症；食纳已少、大便亦溏，则脾损及胃。原文引越人谓上损过脾、下损及胃皆难治，故寒凉滋润未能治嗽，徒伤脾妨胃，预后堪忧，惟以甘药调之、议建中法。", ["细", "空"]], "918": ["病机", "虚损而脉弦，弦为肝木偏旺、土受木克之象。久嗽食减，乃中气已馁，木火刑金则嗽久不愈，木乘土位则食纳减少。虚损本宜脉弱，今反见弦，说明肝木横逆、脾胃受困，故用小建中去姜，甘温建中以柔肝缓中。", ["弦"]], "919": ["病机", "脉来虚弱，虚为气不足，弱为阳衰微，合久嗽、形瘦食减、汗出吸短，皆中气亏虚、形气不足之候。久虚不复谓之损，宗内经形不足者温养其气，故用黄耆建中汤去姜加人参五味，甘温补中、酸收耗散之气。", ["虚", "弱"]], "920": ["病机", "脉弦右大，弦为木旺，右大为脾胃受克。久嗽而背寒盗汗，乃中阳不足、营卫不和，木气乘土，肺金失养。用小建中去姜加茯神，意在温建中气、安神敛汗，说明此脉主土虚木乘、营卫失调之病机，非单纯肺咳。", ["弦", "大"]], "921": ["病机", "原文未出脉名，以劳力神疲、遇风则咳立论。劳则气耗，卫阳受伤，腠理不固，风邪易袭，故咳。治宜和经脉之气，用当归桂枝汤合玉屏风散，益气固卫、调和营血。此段主旨在说明卫阳受伤、营卫不和之病机，非瘀血内阻，故戒逐瘀攻伤。", []], "922": ["病机", "脾胃脉部独大，大而无力为土衰之象。饮食少进、不喜饮水、痰多咳频，是脾虚不能运化水湿，湿聚成痰，土不生金，肺失肃降。建中去饴加茯神，接服四君子，皆培土生金之法。此脉主脾胃虚弱、痰湿内生、母病及子之病机。", ["大"]], "923": ["病机", "脉虚为正气不足之象。久嗽伤肺，子盗母气，脾土亦弱，故减食。四君子加南枣，健脾益气以培土生金。此脉虚主肺脾两虚、中气不足之病机，久嗽减食正是虚证相应之症，治当补益而非攻邪。", ["虚"]], "924": ["病机", "脉沉主里、主寒湿。短气、咳甚、呕吐饮食、便溏泄，乃寒湿郁痹渍于阳明胃，营卫不和，阳不旋运，夜阴用事则浊泛呕吐。原文明言\"胃咳之状，咳逆而呕\"，斥庸医治痰顺气、治肺论咳之误。此脉沉主寒湿内郁、胃阳不运之病机。", ["沉"]], "925": ["病机", "脉弦右甚，弦为木旺，右甚则木乘土位。嗽而午潮热、便溏畏风，是土虚木贼、营卫不和，故以大肠嗽治之。右脉主肺与大肠，弦甚说明气机郁滞、木火刑金，下迫大肠则便溏。此脉主肝木犯肺、土虚不运之病机。", ["弦"]], "926": ["病机", "脉数主热，右长左弦，右长则气分有热，左弦则木旺乘土。上咳下溏，是肺热而脾虚，木火刑金则咳，木乘土则溏。数而长为邪热内蕴、气机不降之象。此脉主上焦有热、肝木犯脾、肺脾同病之病机。", ["数", "长", "弦"]], "927": ["病机", "寸口独大，为寒邪束表、上焦郁热之象。形寒暮热、咳嗽震动、头脘胁骨皆痛、先经嗽红，是体气先虚，时序冷热不匀，夹寒邪致病，邪郁上焦，肺失清肃。原文戒温散之剂，当清解上焦。此脉主寒邪外束、上焦郁热之病机。", ["大"]], "928": ["病机", "寸口脉搏指而劲，为风温之邪内郁、痰血互结之象。搏指属阳邪亢盛，劲则络脉拘急，故初因风温咳嗽，震动络血而致痰血；能食者胃气未败，病在上焦营肺。脉劲示热邪灼络、血不循经，故治以清心营肺卫之热，使络宁血止。", ["劲"]], "929": ["病机", "右脉大，主冬温内侵、阳气不伏。冬应藏而反温，阳失潜藏，热郁于内，故脉大而见于右；热蒸上焦则咽喉痒呛、头中微胀，络热血溢则血得外溢。脉大为邪热亢盛之征，非虚大，故当调其复邪，清解冬温，使阳得藏而络血自安。", ["大"]], "930": ["病机", "脉小而劲，少年体丰而真气易泄，非外感实邪。小为正气不足，劲为内热郁络，冬温失藏则热伏于里，咳频震络故痰带血出。脉小劲示本虚标热、络伤血溢，治当薄味和上焦，清气热以保真阴，使咳平血止而病可却。", ["小", "劲"]], "931": ["病机", "脉右大，为温邪犯肺、热震络脉之象。右主气分，大则邪热亢盛，温邪上受，先犯肺卫，热灼肺络则咳痰带血。脉大非虚，乃温热内逼、气分热盛之征，故以清温宁络为治，使热清则络安血止。", ["大"]], "932": ["病机", "血后喉燥痒欲呛，脉左搏坚。左脉候肝，搏坚为肝阳亢逆、阴血亏虚之象；血去阴伤，肝失濡养则阳亢搏指，上灼肺金故喉燥欲呛。脉坚示邪郁络急，非纯虚，治当柔肝润燥、清络宁血，使肝阳平而呛痒止。", ["搏", "坚"]], "933": ["病机", "脉小涩，小为阴血不足，涩为热阻气机、血行不畅。欲凉饮者内有郁热，热阻则气升，气升则血冒，故见上焦血溢之候。脉小涩示热郁络滞而非大实，仍议治上，清透上焦郁热，使气降血宁，涩脉自和。", ["小", "涩"]], "934": ["病机", "热伤元气，血后咳逆，舌赤而脉寸大。寸大主上焦热盛，热伤元气则气逆不降，血后阴伤而热未清，故咳逆不止；舌赤为热灼营分之征。脉寸大示热壅上焦、气阴两伤，治当清上焦热、益气阴，使热退咳平。", ["大"]], "935": ["病机", "脉涩，为邪阻肺卫、气血郁滞之象。咳嗽痰血、不时寒热，乃寒热之邪郁伤肺卫，卫气失宣则寒热交作，肺络被郁则咳而痰血。涩脉主气机不利、血行不畅，非虚涩，故以苇茎汤加杏仁通草宣肺通络，使邪去则涩脉自畅。", ["涩"]], "936": ["病机", "脉数促为阳热亢盛而兼气机急促之象。原文谓肛疡溃脓虽愈，然阴气已走泄，阳气弛张发泄，故脉数促；加嗽血痰多、胃纳减，是阳热上灼肺金、内扰胃气，阴不制阳，虚火与实热交炽，主阴虚阳亢、热迫血溢之病机。", ["数", "促"]], "937": ["病机", "脉搏数主热盛，舌心灰、咳痰有血、频呕络伤，显系热邪内迫，灼伤肺胃络脉，血随热气上出。数脉为热，热伤阳络则血外溢，故见咳血频呕；仍理气分者，示热在气分而波及血络，主热伤络脉、气火上逆之病机。", ["数"]], "938": ["病机", "脉小数主阴虚内热，舌绛、喉痒、咳呛血，因暑热旬日，热入营络，震动而溢。小数为阴分不足而热伏营中，热迫血络则咳呛出血；肺病逆传膻中，故以手厥阴治，主暑热入营、阴络受损之病机。", ["小", "数"]], "939": ["病机", "脉数主热，汗出身热、吐血五日、胸脘不舒，舌白，为阴虚本质而暑热内侵营络。数脉示热邪内盛，热迫血溢则吐血；暑热渐有时疟之状，小溲茎中微痛，是热郁营络而波及腑经，主阴虚暑热、营络受灼之病机。", ["数"]], "940": ["病机", "脉尺浮为下焦阴气不藏，虚阳上浮之象。因毒药熏疮，火气逼射肺金，致咳呛痰血、咽干胸闷；尺浮示肾阴失守，火气上逆，最虑病延及下而成虚损。此脉主火气逼肺、下焦不藏之病机，故姑以轻药暂清上焦。", ["浮"]], "941": ["病机", "脉数涩小结，数主火动，涩小为血少络阻，结为气机郁滞。痰血经年屡发而能纳食应酬，非精血损怯，乃五志过动，相火寄于肝胆，操持郁勃动灼，致络血上渗混痰火。此脉主木火劫烁、络伤血溢之病机，必静养方安。", ["数", "涩", "小", "结"]], "942": ["病机", "脉左坚上透，左关候肝肾，坚为阴亏阳亢、木火内动之象。血色紫乃离络之色，非久瘀；劳役暑蒸，内阴不生，阴虚阳扰，故脉坚而上透。此脉主肝肾阴虚、木火亢盛之病机，治仿琼玉意，仍用阴柔通剂。", ["坚"]], "943": ["病机", "血止而脉左大，左脉候肝肾，大为阴不敛阳、虚阳外张之象。失血之后阴血亏虚，阳无所附，故左脉大而不静；虽血止，脉未和缓，示阴虚阳亢未复，主阴亏阳浮、血后未复之病机，当防虚火再动。", ["大"]], "944": ["病机", "脉左坚，左脉候肝肾，坚为阴血亏虚、脉道失濡而拘急之象。阴伤失血，血去则阴益虚，虚火内扰，肺失清润，故致咳。治以复脉汤去参桂姜之温补，加白芍以柔肝敛阴，正合养阴补血、柔肝止咳之法。", ["坚"]], "945": ["病机", "右坚者胃络震动，气分受病；左坚者肝肾阴伤，虚火迫血；脉弦胁痛者，肝气郁滞、络脉不和。原文以脉之左右坚与弦，分别提示咳血之病位在气在血、在胃在肝，并各出方药，示人凭脉辨治咳血之轨则。", ["坚", "弦"]], "946": ["病机", "脉左细右劲数，左细为肝肾精血亏虚，右劲数为气分虚火偏亢。精血伤则纳食不充肌肤、卧眠不能著左，遇节令痰必带血，是阴损及气、虚火动血之候。损症五六年，无攻病之理，故议平补足三阴法。", ["细", "劲", "数"]], "947": ["病机", "失血五六年而脉虚，虚为气血俱亏之象；气喘不运不饥，是脾肾两虚、纳运无力、气不归元。治在中下二焦，望其安谷精生，勿许攻病，正因脉虚示本元已损，攻伐更伤正气，当以培补为要。", ["虚"]], "948": ["兼症", "脉弦主肝郁气滞、络脉不和。胁痛已缓而血仍来，说明肝郁虽减，络脉未和、血不循经之机仍在。弦脉与胁痛、出血并见，提示病本在肝，气滞血瘀，虽症减而脉未和，故血仍不止。", ["弦"]], "949": ["兼症", "脉虚数为阴血亏虚、虚热内生之象。失血后阴血不足，心失所养则心悸；虚阳上扰清窍则头眩。虚数之脉与失血、心悸、头眩并见，正说明阴亏于下、虚热浮于上之病机。", ["虚", "数"]], "950": ["病机", "脉象细涩，细为阴血不足，涩为血行不畅、阴伤脉道失濡。患者血来稍缓、能纳谷、步履撑持，是阳明未败、禀赋强健之征；然脉细涩，则阴伤之本质已显，故曰阴伤奚疑。", ["细", "涩"]], "951": ["病机", "原文言诊脉已非实热，是脉不现实热之象，知呛血数发乃阳气过动、虚火上炎所致，非实热迫血。故预宜静养迎夏至一阴来复之生气，秋分后再议，方用生脉六味去丹泽加阿胶秋石，以滋阴潜阳、静摄浮阳。", []], "952": ["病机", "右脉弦数，弦主肝木有余，数主火动，左细涩为阴血亏少、脉道不利。失血后久咳，阴损及阳，食减便溏，是木火刑金而脾胃亦弱。弦数见于右关，示肝火犯中，故知阴损失血为本，咳与食减便溏为标。", ["弦", "数", "细", "涩"]], "953": ["预后", "脉来涩数，涩为血少精伤、脉道不利，数为阴虚火动。失音咽痛继而嗽血，阴液已涸，虚火灼金，故成劳怯。然能食胃强，中气尚存，故曰带病延年。涩数并见，示精血亏而虚火内炽，非实热可比。", ["涩", "数"]], "954": ["病机", "左脉坚，木火偏旺、肝阳不潜；右脉弱，中气不足、营液久耗。情志郁勃致伤，春季失血嗽痰，是木火升腾、迫血上溢。少食尩羸，形瘦阴亏，古语瘦人虑虚其阴，正合左坚右弱之象，示阴虚火旺而中土亦弱。", ["坚", "弱"]], "955": ["病机", "脉左数，左属肝肾阴分，数为火动。侧眠嗽血，是阴虚火升、络血上溢，卧则气壅于一侧故侧眠。数脉主热，见于左部，知为阴亏内热而非外感，热迫血络故嗽血，病机在肝肾阴虚、虚火上炎。", ["数"]], "956": ["病机", "脉细为阴血不足，左小促为营阴亏而脉道拘急、时有歇止。干咳有血、寒热身痛，经水先期色淡且少，是脏阴伤及腑阳，奇脉无气，内损成劳。细促示精血耗竭、气血不续，故药难骤效，属虚劳重候。", ["细", "小", "促"]], "957": ["病机", "脉细弦数，细为阴分不足，弦为肝木偏旺，数为虚火内动。痰中带红、肠风下血，春温之后再劫津液，上下失血，是风淫于内、虚火迫血。细弦数并见，示阴亏火旺而风动，故宜咸寒育阴潜阳。", ["细", "弦", "数"]], "958": ["病机", "诊脉左数，左属阴分，数为阳升火动。烦劳则阳升，咳呛震动络血上沸，五心热，知饥纳谷，是阴亏于下、阳浮于上，胃气尚和故能纳。数脉见于左，主阴虚内热、阳不潜藏，故议育阴和阳，使阳得下交。", ["数"]], "959": ["预后", "形瘦脉促数，促为数中一止、脉道急促不续，数为虚火。吸气如喘、痰气自下上升，是肾虚气不收摄，冲气上逆。失血后见此，乃劳怯难愈大症。促数示真元不续、肾不纳气，故用贞元饮以摄纳固本。", ["促", "数"]], "960": ["病机", "左脉弦数，弦为肝阳不潜，数为阴亏生热。失血后咳嗽音嘶少寐，乃阴液亏耗、阳升不潜之候。弦数并见，说明肝阳上扰、阴不制阳，故以滋养为主，使阴复则阳潜。", ["弦", "数"]], "961": ["病机", "形瘦脉数，寸口搏指，数为阳动，搏指为浮阳上冒。阴精不旺则阳易动，络血不宁。胃纳尚佳故数发不致困顿，然须戒酒淡欲、怡情静养，水足火不妄动，络血自宁，方用六味加龟甲秋石。", ["数"]], "962": ["病机", "诊脉细促无神，细为阴亏，促为阳动不宁。触胁气闪则络血复上，左目珠痛、喉息有音、足胫冰冷，皆血冒不已、孤阳上升之征。戌亥时自缓者，阳得暂潜。故从肝肾引阳下纳，镇摄浮阳。", ["细", "促"]], "963": ["病机", "脉左垂右弦，左垂为阴精不足，右弦为胃纳亦少。初冬痰中见红、冬春寐有盗汗，乃难藏易泄之象。阴精亏则阳不藏，故入夏当防病，以夏气升发易动浮阳，须预为调摄。", ["弦"]], "964": ["病机", "脉左细数，细为肝肾内损，数为阴亏阳动。肉消肌烁、气冲咳嗽呕吐失血，乃下元不主纳气、厥阳上冒所致，非肺咳。交夏气升血溢，故姑以镇纳，用青铅六味加牛膝白芍，望其血止。", ["细", "数"]], "965": ["预后", "脉两手已和，说明前此脉象已趋平和，病有转机。惟烦动恍惚欲晕，乃阳未全潜、阴未全复之余象。议静药益阴和阳，三才汤加金箔，以镇摄浮阳、安神定志，巩固向愈之势。", []], "966": ["病机", "脉小数，入尺泽，小为阴亏，数为阳动，尺泽候下焦。夏季时令发泄，阳浮于外，失血形倦，乃下焦不摄、阴不固阳之候。治宜摄固下焦，使阴守阳潜，血得归经。", ["小", "数"]], "967": ["病机", "脉左坚，坚为肾阴不固、阳不潜藏；肾脉虚馁，虚为五液不承。冬令失血、能食而咳、脊痛腰酸，乃肾脏不固少纳。寐则口干喉燥，五液不承之征。宜固阴益气，固本丸加阿胶芡实莲肉丸。", ["坚", "虚"]], "968": ["病机", "脉长关搏，长主阳盛，关搏为肝胃气逆，结合形色充伟，乃禀阳体而性情喜动，阳不潜伏。冬月藏阳失职，阳升则血溢而衄血痰血，降则遗精，故脉长关搏反映阳亢不潜、血随气逆之病机。", ["长", "动"]], "969": ["病机", "脉数主热，咳血因木火体质，烦劳则阳升逼肺，肺热不能生水，阴亏阳炽，血由阳而出。数脉为阳热亢盛之象，与咳血、咯腥痰相应，说明火逆迫血妄行之病机。", ["数"]], "970": ["病机", "原文未明脉象，但述失血、冲气上逆、血涌如泉、腰痛足冷，皆肾精肝血不主内守，阳翔为血溢，阳坠为阴遗。病机为精夺下损，冲阳上冲莫制，任脉失担任之职，属虚阳上浮、精血亏耗之证。", []], "971": ["治法", "血脱益气，用人参熟地两仪煎，取人参同阴药补阴，茯苓引阴药入至阴，河车温养，石英镇冲，五味酸收。此段论治法，针对气散越、冲脉不固之血脱，脉象虽未言，但病机为大气散越、阴不内守。", []], "972": ["病机", "脉左数入尺，左尺属肾，数主热，为真阴下亏，阳不潜藏。先有血症，毕姻后血复来，下午火升呛咳，乃阴中阳浮，虚火上炎，保扶胃口以填阴，说明肾阴亏虚、虚阳上浮之病机。", ["数"]], "973": ["病机", "脉动极无序，动主惊、主痛、主阳浮，无序为元气散乱。血涌如泉，汗出畏冷，少焉热躁，此无根之阳上冒，血凝成块，非凉药可止，反映虚阳上越、气不摄血之危重病机。", ["动", "数"]], "974": ["预后", "脉数，血后咳甚痰腥肢肿，阳升内风鼓动。数脉主热，阳升风动，灼肺烁阴，痰腥肢肿为肺脾同病，阴损及阳，故断为最属难治，说明阳升风动、阴亏液涸之病机，预后不良。", ["数"]], "975": ["病机", "脉得左关前动跃如浮，左关前属肝心部位，动跃如浮为阳气化风之象。血去络伤，阳气上蒸，胸胁微痛非有形滞浊，头中微晕，乃阳气化风上扰，说明血虚阳浮、肝风内动之病机。", ["动", "浮"]], "976": ["病机", "左脉形略敛仍坚，是厥阴阳风内动、胃气欲逆之象。原文谓“阳明津衰，厥阴阳风自动，而胃气欲逆”，脉坚示风阳不柔，敛而仍坚说明阴津不足、阳未潜降；喉燥脘痛、热蒸、大便不爽皆津衰气逆之征，故治法取熄风和阳、柔缓宣畅。", ["坚"]], "977": ["治法", "此段仅载复脉汤去参姜桂加白芍，属治法调整而非脉象描述。去参姜桂避温燥刚烈，加白芍柔肝敛阴，反映前段脉坚、风阳自动之病机下，取柔缓熄风、护阴和阳之意，与“必用柔缓”之旨相承。", []], "978": ["治法", "午服生脉散，脉散为气阴耗散、肺气不敛之象。生脉散用人参、麦冬、五味子，益气养阴、敛肺生脉，正对脉散所主的气阴两伤、脉气不聚，属因脉施治的记载，非单纯主病。", ["散"]], "979": ["预后", "原文未识脉名，仅言“形色与脉，日现衰惫”，属脉象模糊之描述。操持怫郁、五志阳动、失血呛咳有年，形色脉俱衰，系生气克削、里真少聚；虑春半地气升、阳气泄，久病伤损难聚，故以摄补三阴、带病延年为法，主预后判断。", []], "980": ["病机", "此段未出脉名，论足少阴真气不摄：唾中有血、吸气少入、腰脊酸楚、寐泄魄汗，皆真气内损之征。若加嗔怒再动肝阳，木火劫烁脂液，春木日旺则调之非易，全段重在阐发真气内损、肝阳再动的病机与调治难点。", []], "981": ["病机", "脉数涩，数主虚热，涩主阴血不足、脉道不利。原文断为“阴损及阳，而非六气客邪”，故咳血气逆、晨起必嗽、得食渐缓，皆内损之象，非可通可泄；法当养胃之阴、多纳谷食，以治此损，脉数涩正是阴损及阳之据。", ["数", "涩"]], "982": ["病机", "脉坚、形瘦久咳、失血有年、食物厌恶、夜寝不适，为液亏阴伤、虚阳不潜之象。前服七味八味从阴引阳不效，因“液亏不受桂附之刚”，脉坚示刚燥不受、下元失摄；故当温养摄纳其下，兼益胃津以供肺。", ["坚"]], "983": ["病机", "脉左坚右涩，左坚为阴虚阳不潜降，右涩为脾虚血少、中焦气滞。冲年形瘦、腹胀食减便溏、失血后日加孱弱，虽起于阴虚，而中焦为急，故原文断为劳伤中气虚，脉左坚右涩正示阴虚而中气先困之机。", ["坚", "涩"]], "984": ["病机", "右脉长大透寸部，长主气火有余，大主邪热亢盛。情志动而厥阳上燔，震动络中致咳失血，虽血止而脉仍长大透寸，是厥阳未敛、气火上升之象。食物不欲纳、寐中呻吟呓语，由至阴损及阳明，精气神不相交合，故议敛摄神气法，使浮越之阳得收。", ["长", "大"]], "985": ["病机", "脉缓大长，缓为胃气本象，大长则气衰血亏不能内守。前服敛手少阴之剂，药力直下少腹而微痛，逾时自安，是阳明胃虚不能载药上奉。肌肤甲错为血亏外候，脉缓大长与气衰血亏如绘相应，故姑建其中，用参耆建中汤去姜以温养中宫。", ["缓", "大", "长"]], "986": ["病机", "脾胃脉独大为病，大主气分泄越，思虑郁结则心脾营损于上中，阳分萎顿，故《金匮》谓男子脉大为劳。极虚亦为劳，为精血下夺、肝肾阴不自立。若脉细欲寐，则少阴见症。今饮食少进、痰多嗽频，土衰不生金气，当春木火司权、脾胃受戕，故先建中理阳，继进四君子大固气分。", ["大", "细"]], "987": ["病机", "原文未识脉名，仅言色脉胃减。积劳思虑内损，久病秋季再发，夏暑气泄，劳则气愈泄不收，络空动沸，此与阴虚有别。色脉俱减、胃纳不旺，说明气泄不收、中气受损，凉降之法更伤胃气，故非所宜，改用人参建中汤建中益气以摄浮越。", []], "988": ["病机", "血大去则络脉皆空，伤损非一腑一脏。脉弱濡涩，弱为气衰，濡为阴血不足，涩为血少络空、脉道不利。肢节微冷、气伤上逆如烟雾迷离、熏灼喉底作呛逆，是上焦不降、下焦不固之象。故大旨上焦宜降宜通，下焦宜封宜固，先得安谷崇土再商后法。", ["弱", "濡", "涩"]], "989": ["病机", "脉右濡，濡主气虚湿滞、胃气不充；左未敛，则左脉尚欠收敛之象。右濡示中焦脾胃之气未复，左未敛示阴血尚未宁谧。此段承前诊而言，重点在右脉濡软，说明中宫气弱、运化无力，故当以培补中宫为要，使胃气渐充而脉转收敛。", ["濡"]], "990": ["病机", "左脉静而虚，静为阴分尚安，虚为精血不足；右如数，数主阳气偏动、胃气未和。初进谷食，胃气初复而右脉尚数，说明中宫未充、阳气易动。霜降后五日天气降，以丸剂摄下，是顺时令敛藏之意，使虚者得补、数者得静，培中宫以固下焦。", ["虚", "数"]], "991": ["病机", "脉如数，数主气火内动。痰嗽失血百日反复，每咳呕而汗出，是气伤失统、络血上泛，气不摄血而随咳上溢。数脉示虚阳浮动、气火不宁，故寒凉止血理嗽不但败胃妨食，决无一效。当从仲景元气受损之例进甘药，冀胃土日旺、柔金自宁，气复统血而脉数自平。", ["数"]], "992": ["病机", "脉细形瘦，为阴血亏虚、内损不复之象。血后久咳，复加喘促，乃肺肾两亏，根蒂力怯，摄纳无权。阴乏恋阳，气多升少降，故静坐勉支，身动则气泛。所纳食物亦难化，总由内损不肯充复，药饵偏理肺嗽，未培根本。", ["细"]], "993": ["病机", "此内损症，久嗽便溏，夏月大气主泄，血吐后肌肉麻木、骨痿酸疼，显系阳明脉络不用，气血难荣。治当益气，大忌肺药清润寒凉，以免更伤中阳。脉象虽未明言，然症候已示中虚络阻之机。", []], "994": ["治法", "脉耎形劳失血，耎为虚软之象，主气血不足。形劳伤气，失血耗阴，中焦营卫俱损。故用小建中汤加玉竹，甘温建中以复气血，玉竹润养以济阴分，乃虚劳失血之正治。", ["耎"]], "995": ["病机", "形瘦脉左数，左脉候阴分，数为虚热，是阴分精夺。谈笑多或胃中饥虚，冲气上逆则咳逆。前年失血盈碗，下损精血，有形难复。急以甘药益胃，中流砥柱，病至中焦不可缓图。", ["数"]], "996": ["病机", "诊脉右大，右候肺胃。秋暑失血，初春再发，颇能纳食。引《金匮》男子脉大为劳，极虚亦为劳。大者之劳，烦劳伤气；虚者之劳，情欲致损。大旨驱尽病根，安静一年可愈。", ["大"]], "997": ["病机", "脉弦劲按之空豁，弦劲为肝旺，空豁为阴血内亏。久嗽先泻血，便不实，近又嗽血，积劳久损，阴阳两亏。食不欲餐，中气亦馁。先宜甘温益气，然贫窘难继参苓，故为难调。", ["弦", "空"]], "998": ["病机", "脉右空大可证。频频伤风，卫阳已疏；劳怒伤阳，亦令失血。当独理阳明，胃壮则肝犯自少。右脉空大，主胃阳虚而卫外不固。若三阴热蒸，脉必参于左部，今左部不显，故知病在阳明。", ["大", "空"]], "999": ["病机", "脉空动若谷，按之微涩。甘温益胃血止，食腥嗔怒复咳血，不独卫阳疏豁，络脉亦空动若谷。微涩为气血俱虚，心营肺卫皆损。议治心营肺卫，以图根本，非沉寒堵塞可冀片效。", ["微", "涩"]], "1000": ["病机", "脉细促为营阴亏虚、脉道不充而兼急促，右空大乃中气亏乏、虚阳外浮之象。爪甲灰枯、久嗽见红、食减身痛、形容日瘁，皆营虚失养、内损难复之候。细促与空大并见，说明营虚为本、气浮为标，故断为内损难复，主以养营法。", ["细", "促", "空", "大"]], "1001": ["预后", "脉大无神，大而无力、神气不充，是劳怯日久、元气损伤、虚阳浮越之征。面少膏泽、痰嗽失血、微寒热不来，皆二气已损、营卫不调之候。脉大无神与形容日瘁相应，说明劳怯不复元大著，故温养甘补使寝食两安，若饵滋阴润肺则胃伤变症。", ["大"]], "1002": ["病机", "脉濡为营血亏虚、脉道不充而兼湿滞之象。形瘦色枯、失血心悸，皆营伤失养之候；寒热乃营卫不和所致。濡脉主虚主湿，与营伤相应，故用归耆建中汤去姜，甘温养营以复其虚。", ["濡"]], "1003": ["病机", "脉芤为失血之后、血去脉空之象，中空如按葱管。汗出、失血、背痛并见，说明络脉空虚、营血亏损，背痛乃络虚失养所致。芤脉主血虚失血，与络虚相应，故断为络虚，治当养血和络。", ["芤"]], "1004": ["病机", "脉空隙即脉道空虚不充，为营液损伤、络脉失养之象。失血半年、心悸忡、胁下动，皆营液亏虚、络脉空隙之候。空隙之脉与络虚相应，说明营液损伤为本，故议甘缓辛补，以养营和络。", ["空"]], "1005": ["治法", "脉弱为气血不足、胃气虚弱之象。遇节血症反复、废食、胁痛胃耎，皆胃气衰败、受纳无权之候。脉弱与废食相应，说明胃气已虚，故无治咳止血之理，当先扶胃气受纳，方可商调理，此即治病求本之意。", ["弱"]], "1006": ["病机", "原文未识脉名，以思郁伤于心脾立论。二脏主营血，营出中焦，脏阴受损则阴虚生热，熏蒸络脉致血不宁静；食少痰多、色泽少华皆虚象。此段说明病机在阴虚络热、心脾两伤，故不宜久进凉润嗽药，当以异功散、归脾汤甘温调补。", []], "1007": ["病机", "左手平和而尺中微动，右关前动数、尺脉带数，动数乃阳升气火之象。烦心劳神、五志皆动，阳不潜伏，冲脉升动，络血不宁，随咳呛溢于上窍；行走喘促亦助其动搏。脉升动与咳呛失血同是一原，说明阳升气火、冲脉上逆为病机，故当静以制动、益水生金。", ["数", "动"]], "1008": ["病机", "原文未识出脉名，仅言“诊脉同前述”，故脉象要素从缺。所述心中怯冷、交四更咽干、咳呛连声、血已盈口，皆心营肺卫同病之象：心液耗则怯冷，肺津亏则咽干咳呛，虚火上炎则血溢。论治从“敛心液滋肺津”立法，正说明此段重在阐发上焦心营肺卫失养、阴液不敛而血随咳溢的病机，非单主一脉。", []], "1009": ["病机", "原文仅言“脉两寸未和”，属脉象模糊描述，未成具体脉名，故脉象要素从缺。“陈血止”而两寸未和，说明上焦心营肺卫之气尚未调畅：寸候心肺，血止而脉未和，是络中余滞未清、营卫未复。仍议心营肺卫方，紧扣前案，示病机重心仍在心肺上焦，不可因血止即谓痊愈。", []], "1010": ["病机", "脉右大，右候肺胃，大为阳盛有余之象。失血而知饥，是胃中尚能纳谷；然咽干喉痒、血随阳升，说明胃阳上逆、胃阴不足，阳无所附而升腾。原文自注“胃阴虚”，正点出脉右大非实热壅盛，乃胃阴亏而阳浮偏大，故主胃阳上逆、阴不制阳之失血咽干喉痒。", ["大"]], "1011": ["病机", "脉右涩，右主阳明，涩为血少气滞、络脉不充之象。初气冲失血、咳逆、血来潮涌，而能食无味，说明阳明胃络空虚，血随阳升上溢。原文明言“乃阳明胃络空虚，血随阳升而然”，并戒“莫见血治咳而用肺药”，正以右涩为据，主中焦络虚、气逆血升之病机。", ["涩"]], "1012": ["病机", "脉小数而右空大，数小为阴亏有热，空大为中气不足、脉道不充。色黄、咳呕血溢、饮食渐减，皆胃阴胃气两伤之征；建中旬日颇安，而沐浴气动血咳复至，说明胃阴未复、气易浮动。故主胃阴亏虚、虚阳上扰、血不循经之病机，治取麦门冬汤养胃阴。", ["小", "数", "大", "空"]], "1013": ["病机", "右部不鼓击应指，是阳明脉气不充；左寸数疾，左寸候心，数疾为阳动火升之象。因伛偻拾物致阳明脉络血升，面色微黄为血去之征。右脉不鼓说明中气已弱，左寸数疾说明心阳偏亢，合而示阳明络虚、血随气升、心火偏动之病机，故不宜凉解妨胃，宜益气理胃远肝。", ["数", "疾"]], "1014": ["病机", "原文仅言“阳明脉络已虚”，属脉象模糊描述，未出具体脉名，故脉象要素从缺。吐血数发、肢震、面热汗出、寐中惊惕，是阳明络虚不能统血，厥阴风阳上炽而扰及心神；饮食不为肌肤，则中焦化源不足、消烁之征。全段主阳明虚而厥阴风阳上亢、血失所统之病机。", []], "1015": ["病机", "脉左小数、右弦：左小数示阴分不足而虚热内生，右弦示胃阳偏亢、木气犯土。食减不肌、易伤风、便结，皆胃阳外应卫气而九窍不和之象；冬春见血，是冬失藏聚、春生气少，遇长夏热蒸真气渐困。故主胃病及卫气不固、阴亏阳浮、血随气逆之病机。", ["小", "数", "弦"]], "1016": ["病机", "两寸脉大，寸主心肺，大则阳热有余。原文谓“心烦脊热，汗出”，乃营分热盛、阳气外泄之征，故曰“营热气泄”。痰少血止是阴液渐亏而热未清，竹叶地黄汤甘凉养胃阴、清营热，正合此脉此证。", ["大"]], "1017": ["病机", "原文未出脉名，然述“春尽入夏，气机升泄，阳气弛张极矣”，阳动则阴乏内守，络血外溢，故吐血咳嗽。今交土旺发泄之时，病气随时令而动，急养阳明胃阴以固络，佐生脉之属敛阳，避炎熇烈日，皆防阳气再泄、阴血复伤。", []], "1018": ["病机", "脉小坚者，小为阴血不足，坚为胃阴亏而虚火内结。见红两年、冬月加嗽、声音渐嘶、喉舌干燥，皆阴津不能上承；厚味不纳、胃口日减，是胃阴亏而受纳失职。故以甘缓益胃阴主治，使胃津复则金得所养。", ["小", "坚"]], "1019": ["病机", "脉大色苍，大则阳升少制，苍为形瘦阴亏之象。冬月嗽血、春夏吐血，缘冬少藏聚，阳无所制而升动，络血上溢；干咳无痰、纳谷减半，是胃土之津亏。故安闲静养以平五志气火，养胃土之津以生金。", ["大"]], "1020": ["病机", "脉右大左虚，右大主阳明阳气升动，左虚主阴血不足。夏四月阳气正升，烦劳过动其阳，络中血溢上窍；血去则阴伤生热。故宜养胃阴以滋化源，大忌苦寒清火，恐更伤胃气而阴愈亏。", ["大", "虚"]], "1021": ["病机", "原文未出脉名，仅言“脉搏”，指脉动应指急疾。血涌而饥易纳食，是风阳过动、消烁胃津，阳动迫血上溢，胃热则消谷善饥。若不自保摄，药力难敌情志劳扰，故曰饵药无益，重在静养以制风阳。", []], "1022": ["病机", "阳明脉弦空，弦为阳动，空为血去阴伤、脉道不充。失血后咽痹即呛，是胃阴亏而津不上承，纳食虽强却未得水谷精华游溢。故当益胃阴，使津液复则咽润呛止，脉空可渐充。", ["弦", "空"]], "1023": ["病机", "失血能食而脉数，数为阳热内动，能食是胃火消谷。痰嗽、色苍，乃阴伤而热灼津液。故与甘凉养胃中之阴，胃和金生则热自平；痔血便躁，亦阴亏肠燥所致，柔药最宜，忌刚燥再伤其阴。", ["数"]], "1024": ["病机", "脉小弦，小为血少，弦为肝郁。血去食减，服地黄柔腻反觉呆滞，且不喜肥甘，显系肝胃不和，木郁克土，胃气不醒。弦主肝病，小示阴血不足，故议两和肝胃，以调其偏。", ["小", "弦"]], "1025": ["病机", "脉数左坚，数主热，坚主实，左关候肝。当夏阳气方张，嗔怒引动肝阳勃升，络血上涌，咳逆欲呕，眠卧不得欹左，皆肝阳左升太过、木失水涵、阴亏生热之象，非客邪实火可清可降，故宜甘缓制急。", ["数", "坚"]], "1026": ["病机", "左脉细坚搏指，细为阴血不足，坚搏为肝阳逆亢。肝阳上逆，迫血妄行则失血；阳亢于外，腠理不固则汗出。脉象示阴亏阳亢、血随气逆之机，与失血、汗出症候相应。", ["细", "坚"]], "1027": ["病机", "脉细小如无，细为血少，小为气虚，如无则真炁衰微。素多郁怒，肝阳化风，络血沸起，故咯血不止、寒战面赤、惊惕头摇、四肢逆冷。此肝病暴变，阳逆于上而真炁不支，势非轻渺，故用镇阴煎制阳就下。", ["细", "小"]], "1028": ["病机", "脉涩，涩主血行不畅，有瘀滞。能食而咳血，知胃气尚强，然血已离经，涩脉示络脉瘀阻，血不循经而咳出。此瘀血内停、新血不得归经之机，与咳血症候相应。", ["涩"]], "1029": ["病机", "原文未识脉名，然述左乳傍胁中常似针刺、汗出、心嘈能食，此少阳络脉阳气燔灼，因谋虑致伤，气火内郁，将有络血上涌之事。虽无脉象，症已示络热瘀滞，故议清络宣通，勿令瘀著。", []], "1030": ["病机", "左脉坚搏，坚为实，搏为有力，左关候肝。因投柔剂和阳益阴而血未止，反见右胸似痞、左胁刺痛，知阴柔滋养未能宣通络中，少阳络脉气机壅滞，痛咳未罢，故议辛润宣通。", ["坚", "搏"]], "1031": ["病机", "脉左弦右小濡，弦主肝郁，濡主湿滞。病原起于忧郁，郁久化热，蒸迫络脉，血为上溢，凝结成块者乃离络留瘀。血后纳食如昔，腑络贮富，气火旋动漉漉有声，非有形质，故当清阳明之络为要。", ["弦", "濡"]], "1032": ["病机", "冬令过温，人身之气不得潜藏，阴弱之质血随气逆，诊得阳明脉动，动主阳扰气逆，血随气上而吐瘀黑，络中离位之血尚有，故未可止涩，当降气行血。", ["动"]], "1033": ["兼症", "胃脘当心，肝经交络所过，上布于肺，咳嗽胃旁作酸、腹䐜胀，络气逆也；脉数能食，数主热，胃热络逆，当虑失血，宜和络气，勿使热迫血溢。", ["数"]], "1034": ["病机", "诵读静坐，痰血夏发入冬不已，胸胁痛引背部，脉小微涩，非欲伤阴火；小微软涩主络脉失和，气血涩滞，络中气逆血上，痛为络脉失和，宗气为血帅，当调气和络。", ["小", "微", "涩"]], "1035": ["病机", "脉数，涕有血、嗽痰，冷热外因动肺，缘素患肝痹，左胁不耐卧著，数主热，热动肝肺，恐阳升血溢，微用苦辛泄降，不宜通剂，以折阳升之势。", ["数"]], "1036": ["治法", "脉右长，呛血，长主气逆有余，右脉长知气机上逆，呛血由气逆血上，仍宜降气，使气降则血宁，此脉症相应，降气为要。", ["长"]], "1037": ["主病", "脉弦，失血，胁痛气逆；弦为肝脉，主气逆，肝络不和，气逆血上则失血，胁痛为肝经所过，弦脉主肝病气逆，故见失血胁痛。", ["弦"]], "1038": ["病机", "忧思怫郁，五志气火内燔，烟辛泄肺、酒热戕胃，阳络伤则血外溢，胃络受伤，阳明脉络日衰，背冷右胁酸疼咳吐不已，胃土惫肝木横，厥阳逆，秽浊自下泛上，左升右降失司，病情全在血络，清热滋阴不能入络，定清养胃阴为主，另进通络。", []], "1039": ["病机", "有年冬藏失司，似乎外感热炽，辛散苦寒误治，自春入夏大气开泄，日见恹恹衰倦，呼吸喉息有声，胁肋窒板欲痛，咯呛紫血，脉不和，络脉不和，议辛补通调，不致寒凝燥结，冀免关格上下交阻。", ["不", "和"]], "1040": ["病机", "脉弦为肝旺之象，结合目眦黄、咳痰黏浊、呕血，可知胃有湿热胶痰，因怒劳动肝，肝气横逆，血随气上逆而呕血，左胁中痛为肝络不和之征。此非虚损，乃实证，故当薄味静调、戒嗔怒以平肝气。", ["弦"]], "1041": ["病机", "脉数上出，数为热，上出为气火上逆。右胁上疼、痰血上溢，因嗔怒努力劳烦致络中气阻，气阻则血瘀，郁而化热，热迫血上溢。宜安闲静摄、戒怒慎劳，使气机调畅则病可去。", ["数"]], "1042": ["病机", "本段论失血三因，外因多阳邪，因阴分先虚易受风热燥火；内因责之嗔怒伤肝、劳形耗心脾、纵欲贼肾；不内外因由饮食偏好、努力坠堕。治外因重手三阴，内因重足三阴，再审乘侮制化，强调三因根蒂用药不可混乱。", []], "1043": ["误治", "徐评批评治血症用麦冬、五味、玉竹、沙参等峻补收敛之误。吐血咳嗽乃肺家痰火盘踞，火邪入肺，痰凝血涌，宜散宜降，反用酸收腻补，致痰火收住肺中，无出路，贻误后人。", []], "1044": ["病机", "右寸脉浮大，右寸候肺，浮为气分燥，大为津液亏。喉干失音一月未复，因津液不上供，肺失清肃，气分燥而津液亏，故脉浮大。治当润燥生津，清肃肺气。", ["浮", "大"]], "1045": ["病机", "脉细心热，细为阴伤，热为阳浮。呼吸有音、夜寤不寐，过服发散致气泄阳伤，肺痿之疴。仲景法以胃药补母救子，祟生气也，金匮麦门冬汤主之。", ["细"]], "1046": ["病机", "脉数而虚，偏大于右寸。数为热，虚为气分不足。沉积劳忧思内伤，冬温触入为咳嗽，气分先虚，邪得外凑。辛散则气分愈泄，滋阴不能安上，咽痛音哑，虚中邪伏。春暖阳和，气机流行，小效旬日；谷雨暴冷，卫阳久弱，不能拥护，病复。", ["数", "虚"]], "1047": ["预后", "脉细色夺，细为阴血不足，色夺为精血外衰。溃疡流脓经年，漏损脂液，阴失内守，阳失外卫，声嘶食减、咳嗽、喉中梗痛，皆液伤卫虚之候，肺痿之疴，谅难全好。", ["细"]], "1048": ["病机", "脉左弦右濡，左弦为肝木偏亢，右濡为肺脾不足。木火扰动，相火不藏，故梦遗；木火刑金，肺失清肃，则咳逆气急。此脉示肝旺脾弱、木叩金鸣之病机，主梦遗咳逆，与气急症相应。", ["弦", "濡"]], "1049": ["病机", "脉垂入尺，指脉象沉坠至尺部，为肾阴亏虚、精关不固之征。阴虚则相火妄动，扰动精室，故有梦遗精。议填阴摄固其下，即针对此阴亏不摄、精走下泄之病机，主梦遗，与精滑症相应。", ["垂"]], "1050": ["病机", "脉虚色白，形神皆劳，阳虚于外，故陡然大瘦。冬至阳动而精摇下泄，暴寒折阳，身不发热，时时惊惕烦躁，乃亡阳之象。脉虚主阳气浮越，与仲景亡阳肉𥆧例相应，故用救逆汤法，防昏痓瘛疭之变。", ["虚"]], "1051": ["病机", "色苍脉数，为阴虚火旺之征。烦心则遗，因阳火下降，扰动精室；阴虚不摄，兼湿热下注，故固涩无功。脉数主热，此热由阴虚而生，与烦心、遗精、湿热下注症相应，病机为阴虚湿热。", ["数"]], "1052": ["病机", "脉右弦左垂，右弦为肝木乘脾，左垂为肾阴不足。阴虚则相火不藏，湿热下注，故遗精；湿热浸淫，则疮蚀。此脉示阴虚湿热、木旺土虚之病机，主遗精疮蚀，与阴虚湿热症相应。", ["弦", "垂"]], "1053": ["病机", "梦遗病乃阴气走泄，湿热二气乘虚下陷，坠自腰中至囊，环跳膝盖诸处可见。久遗八脉皆伤，故议用通药兼理阴气。此段未出脉象，主述阴伤湿热下陷、八脉受损之病机，主梦遗，与腰囊坠胀、环跳膝盖症相应。", []], "1054": ["病机", "左脉百至余，颇有敛聚之意；右关及尺芤动若革，按脐下过寸动气似穿梭。芤革为阴精内枯、冲脉失养之征，动气震跃不息，乃关元内空。阴精内枯，阳不交阴，故五心热炽、骨节热痿、烦惊惕汗。主内损精血，与遗滑经月不来症相应。", ["芤", "动", "革"]], "1055": ["预后", "参脉症形色，生阳颇有根蒂，为预后向善之象。近食蚕豆滞气，腹中微膨，食后口味酸浊，乃脾阳运动之机尚少；火升心烦、动气汗出遗精虽减未平，总属内损已深。调治合宜，精气复一分则病减一分，长夏培土助纳为要，兼摄固散越之气。", []], "1056": ["病机", "右脉弦大而少冲和，是脾胃中焦阳气不振、运化无力，故谷进运迟、吞酸䐜胀；左脉细促未静，为下焦阴不内守、相火不宁，故寐中仍欲遗精。形色渐复而脉未和，说明病去三四而中阳未复、阴守未固，治当动运中阳、固摄下阴。", ["弦", "大", "细", "促"]], "1057": ["病机", "长夏暑温热郁伤脾胃，色黄神倦、纳食不旺、气分自馁，遗泄因劳烦而发。原文谓「脉象非数搏」，排除阴虚火旺之数搏，说明遗泄由脾虚气陷、中气不固所致，故议养脾立法，归脾汤加减以益气摄精。", []], "1058": ["病机", "左弱右弦，左弱为阴分不足、肾关不固，右弦为脾胃气机不畅；色黄食少、腹胀便溏是脾阳不运，梦遗泄为阴不内守。原文明言「非阴柔涩腻可服」，说明此属阳不煦阴、脾肾气弱，当用煦阳以涵阴，而非滋腻补阴。", ["弱", "弦"]], "1059": ["病机", "遗精数年，不但肾关不固，原文更言「阳明脉络亦已空乏」，说明久遗耗损，由肾及脾，阳明气血亦虚，络脉失养。故治法不独固肾，须戒欲宁心、待阴阳渐交，用桑螵蛸散固精兼理阳明，体现脾肾同病之机。", []], "1060": ["病机", "壮年形质伟然而脉来芤虚，芤为阴血不充、虚为阳气不足，脉与形不相称。述心悸怔、多畏惧、夜寐不宁，是劳心过度、阳不易交于阴，心神失养。脉芤虚正合阴血亏而神不宁之机，故用妙香散养心安神。", ["芤", "虚"]], "1061": ["病机", "形壮而脉小，形脉相反，小为气血不足之象。自述心力劳瘁、食减遗精，是劳心耗气、脾运不健，气夺则精亦不固。原文引景岳「精因气而夺，当养气以充精」，说明此遗精根在气虚，故理无形以固有形，用妙香散益气养心。", ["小"]], "1062": ["病机", "左脉刚坚，为肝肾相火亢盛、阴不制阳之象；火升则神气欲昏，片刻平复宛若无病，是劳心五志之阳动、龙相无制，故常有遗泄。脉刚坚正示火旺于内，先用滋肾丸淡盐汤送，以泻相火而保阴。", ["坚"]], "1063": ["病机", "脉细涩，细为阴血不足，涩为脉道不利、精血亏少。寐则遗精、心热口渴、不时寒热，是肾阴内损、心阳暗炽，水火不交。细涩之脉正合阴亏精损之机，故用补心丹滋阴养血、清心安神。", ["细", "涩"]], "1064": ["病机", "脉上动尺芤，上动者心阳浮动、神驰不宁，尺芤者精血亏虚、下元不固。冲年知识太早，真阴未充而久遗滑漏，精损难复，故心动神驰、神驰精散。此脉主心肾不交、精关不固之遗精，治当理心脾以交肾、固肾气以宁心，非草木偏性可独任。", ["动", "芤"]], "1065": ["病机", "脉虚芤，虚为气馁，芤为血脱，应乎失血遗精。先天既薄，更易泄少藏，精血两伤而封藏失职。此脉主精血亏虚、下元不固，故见遗精失血屡作。治须潜心静处，冀水火自交而精固，非徒药饵可恃，正合褚氏难状之疾之论。", ["虚", "芤"]], "1066": ["病机", "脉小色白，小为气血不足，白为色脱无华，合之失血遗精屡发，显系精血亏耗、封藏不固。犹喜纳谷胃安，中土尚能化生气血，故可封藏固补使其藏聚。若再苦寒泻火，必伤胃废食，坐以待困，此脉此症忌寒凉、宜温固之意昭然。", ["小"]], "1067": ["病机", "脉左部数有锋芒，左关候肝，数为热，锋芒为阳亢不驯，是肝阳上冒之象。久遗滑则肾弱不摄，入夜痰升肋痛、初夏见红，皆肝阳升动、血随气涌之征。此脉主肝阳上冒兼肾弱不摄，故固摄助纳必佐凉肝，标本兼顾。", ["数"]], "1068": ["病机", "脉数虚，数为阳动，虚为阴亏，气冲心热、呛咳失血，屡因嗔怒则肝阳升而血涌，坠则精遗，是阴阳枢纽失固、阳不潜藏。暮热晨汗，值春夏发泄之令而愈显。此脉主阴虚阳浮、肝升血涌兼精遗，故议摄真，而清寒肺药须忌，恐更伤其阳。", ["数", "虚"]], "1069": ["病机", "脉小如数，小为阴精不足，数而无力为阳浮不敛。梦遗阴精不固，冬温腠疏，阳动不藏，诸气皆升，络血上溢，故头面热、目下𥆧、心悸怔忡、四末汗出、足跗肿冷、动即吸短欲喘，皆少阴肾气失纳、阳浮不肯潜伏之征。法当味厚填精、质重镇神，佐酸收甘缓。", ["小", "数"]], "1070": ["病机", "此段总论遗精，以有梦、无梦、湿热三者范围之。有梦为心病，无梦为肾病，湿热为小肠膀胱病。精藏制在肾而主宰在心，故治法不外宁心益肾、填精固摄、清热利湿。肾精亏乏、相火易动者用厚味填精、介类潜阳；无梦滑脱者用桑螵蛸散填阴固摄，滑涩互施。", []], "1071": ["病机", "脉数垂，数为热蕴，垂为下坠之象，淋浊愈后再发、肛胀便不爽、余滴更盛，是湿热下注、气机坠滞未清。数脉主热，垂示湿浊趋下，故症见前阴余沥、后阴胀滞。此脉主湿热蕴结下焦、小肠膀胱气化不利，当清热利湿、升清降浊，防其反复。", ["数"]], "1072": ["病机", "脉左劲右濡，左劲为肝阳化风之象，右濡乃胃土虚弱之征。水弱木失滋涵，肝阳上亢化风，过膈绕咽达巅，故头晕肢麻、咽喉似有物黏著；木乘胃土，阳明脉衰，不司束筋骨利机关，故胃脘腹中饥则欲痛，得食则缓。壮年见此，已属痱中根萌，病机为肝肾阴虚、肝风内动兼胃虚。", ["劲", "濡"]], "1073": ["病机", "脉左坚入尺，坚脉主邪实内结，入尺部提示病位在下焦。湿热下坠，蕴结膀胱，故淋浊而痛。左尺坚为阴虚湿热互结之象，阴液亏虚则脉失柔润而坚，湿热下注则淋浊。治以滋肾丸，滋阴清热利湿，标本兼顾。", ["坚"]], "1074": ["病机", "脉数形瘦，数脉主热，形瘦为阴血不足之体。素有失血，阴弱少制，阳气鼓动，故自觉气从左升，痰嗽随之。此积劳伤阴，阳无所制而上逆。近日便浊，虽宜清热，亦必顾其阴体，六味壮水以制阳光，使阴复阳潜。", ["数"]], "1075": ["病机", "脉沉主里，淋浊而脉沉，为心火下陷于下焦，与湿相合，蕴结膀胱。心火本应下降，今陷于下，故见淋浊。治以分清饮加山栀、丹皮、茯苓、猪苓，清心火、利湿浊，使火归其位，湿有出路。", ["沉"]], "1076": ["病机", "脉沉实，沉主里，实主邪盛。血淋尿管溺出而痛，形色苍黑，为腑热内结，热伤血络，故尿血而痛。沉实之脉示热邪壅盛于内，治从腑热，清泻腑中实热，热去则血自宁。", ["沉", "实"]], "1077": ["病机", "脉左细劲，细为阴血不足，劲为肝阳不柔。腰酸、溺有遗沥，为肾气不摄；减谷难化，为下焦脏阴虚馁，渐及中焦腑阳。此下焦阴虚，肝阳偏亢，肾失封藏，脾胃纳运亦弱。治当收纳肝肾，勿损胃气。", ["细", "劲"]], "1078": ["病机", "脉沉涩无力，沉主里，涩主滞，无力为虚。淋閟属肝胆居多，前医以桂附劫阴，与刚脏不合，致阴伤气滞。沉涩无力非实热壅闭，故五苓八正不可投。议用朱南阳法，从厥阴论治，疏达肝木，通利下焦。", ["沉", "涩"]], "1079": ["病机", "原文未识脉名，以症测机。败精宿于精关，宿腐因溺强出，新者又瘀在里，经年累月，精血枯槁，势必竭绝成劳。此奇经任督冲带为病，如女人崩漏带下，非八正分清、地黄益阴泻阳所能治，当从奇经调理。", []], "1080": ["病机", "本案无脉名，从“案牍神耗，过动天君”立论，言思虑劳神致心阳过动，阳燧直升直降而水火不交，阴精不守，变为腐浊下趋。精浊与便浊异路，故宣利清解无功，久延则伤及任督八脉。其病机在奇经失固、阴精下漏，非湿热实邪，故治法意在升固八脉之气以涵阴精。", []], "1081": ["病机", "脉缓涩，缓为气虚不运，涩为血少滞涩，合见则气血两亏、奇脉失养。溺后成块之血、晨溺胶浊黏腻，是精血下泄而络脉不固；四肢寒凛为阳气不达四末；纳食如昔说明中焦尚可，病不在脾胃而在奇经。故原文断为“病伤奇脉”，主下元亏虚、奇脉不摄之精浊血淋。", ["缓", "涩"]], "1082": ["病机", "原文言“冲脉动，而诸脉皆动”，是冲任不宁、下元失固之象；诊得脉微小涩，微为阳衰，小涩为阴血滞少，正合悲忧惊恐内伤情志、阳气外泄、络中不宁而血从漏出。任脉失担任之司，故小便欲出有酸楚如淋之状。脉动主冲脉上逆，微小涩主阴阳两伤，故宜理阳通补。", ["动", "微", "小", "涩"]], "1083": ["病机", "此段无脉名，专论淋浊辨证。提出五淋、精浊便浊当分气血、精道水道；秘结宜通，滑脱当补；心阳亢则利火腑，湿热甚则彻泉源，气陷升阳，血瘀化结。又特举厥阴内患，少腹绕前阴如刺、小水点滴难通，为环阴脉络痹阻、气化机关已息，主病在厥阴络痹，法用滑利通阳、辛咸泄急。", []], "1084": ["病机", "脉小数涩，数为热，小涩为阴血不足而气机郁滞。原文言“上热火升”，喜食辛酸爽口，是郁火内扰；上年精滑阳痿用通填未效，说明非纯虚可补。此乃焦劳思虑郁伤，气郁化火，气血不畅，故当从少阳条畅气血。脉小数涩正主郁热伤阴、气机不舒之病机。", ["小", "数", "涩"]], "1085": ["病机", "脉细为阳气不足、脉道不充，自汗为卫阳不固、腠理失密；下体怯冷是阳气不能温达下元。原文断为“卫阳式微使然”，即卫外之阳衰微，既不能固表而汗出，又不能温煦下体。脉细与自汗、足冷相应，主阳虚卫弱之病机，非阴虚盗汗可比。", ["细"]], "1086": ["病机", "脉微为阳气大虚，汗淋为卫外不固、阳随汗泄。右胁高突而耎、色痿足冷，是阳气不能温运；不食易饥、食入即饱，为胃阳衰而纳运失职。原文断“阳气大伤，卫不拥护”，脉微与汗淋、足冷并见，正主阳衰卫弱、封藏失固之病机，故法当封固。", ["微"]], "1087": ["病机", "脉弦大为营卫虚而气机不柔，身热时作汗出，是劳伤营卫、卫外不固、营阴外泄之象。原文引“劳者温之”，明言由劳伤营卫所致。弦为虚风内动，大为劳气外张，非实热壅盛，故身热而汗出，主营卫两虚、卫不护营之病机，治当温养。", ["弦", "大"]], "1088": ["病机", "脉细弱为营卫气血两虚之象。细者阴血不足，脉道不充；弱者阳气衰微，鼓动无力。症见自汗体冷、形神疲瘁，乃卫阳不固、营阴外泄；知饥少纳、肢节酸楚，为脾胃气弱、营卫不和。叶氏断为病在营卫，以甘温补益，正合虚则补之之旨。", ["细", "弱"]], "1089": ["病机", "本案未录脉象，以症测机。案牍积劳致神困食减、五心汗出，叶氏明言非因实热，乃火与元气势不两立，气泄为热为汗。劳伤心神，虚热内扰，故以生脉四君子汤补气敛阴。此属虚热，与实火宜清者迥别，治在无形，即补元气以制浮火。", []], "1090": ["病机", "此段论汗症病机，未出脉象。原文以阳加于阴谓之汗立论，谓心主阳脏，火扰所在则津泄为汗。心阳虚不能卫外则自汗，肾阴虚不能退藏则盗汗，总由心肾虚而得。汗为心液，肾主五液，故汗症未有不由心肾虚者，紧扣心肾阴阳立说。", []], "1091": ["预后", "脉革无根、左尺如无，为亡阳危候。革脉中空外坚，按之如鼓皮，主精血虚极而阳气浮越；左尺候肾，如无则肾阳败绝。大汗后寒痉、头巅痛、躁渴不寐，皆阳亡于上、阴竭于下之象。干呕格拒，胃气亦败，故断为真危如朝露，勉以救逆汤收摄溃散之阳。", ["革"]], "1092": ["预后", "脉微细而促，微细为阴阳俱虚、脉道不充，促为急促不匀、二气不相接续之征。症见鼾声呵欠、目瞑烦躁，乃阴阳并虚、衰脱之候。叶氏谓清神熄风难以进商，急固根蒂，仿河间地黄饮子阴阳并补，正合微细促脉所主之虚脱病机。", ["微", "细", "促"]], "1093": ["预后", "本案未录脉象，以症测机。肾脉不得上萦，则下元空虚；肝风突起掀旋，呵欠鼾声、口噤汗出，皆阴阳不相接续之危候。肾虚于下，风动于上，阴阳离决，故危期至速。地黄饮子补肾填精、引火归元，正对此阴阳不续之机。", []], "1094": ["预后", "脉大不敛，为大而无力、浮散不收之象，主阳气浮越于外、阴不内守。症见神迷呓语，乃阴阳不相交合，神失所依。叶氏断为欲脱之象，谓救阴无速功，急急镇固阴阳以冀苏息。脉大而不敛，正是阴阳离决、真气外泄之危候。", ["大"]], "1095": ["病机", "本案未录脉象，以症测机。阴液枯槁则阳气独升，心热惊惕、倏热汗泄，皆阴虚阳浮、五液亏耗之象。叶氏议用复脉汤甘以缓热、充养五液，去姜桂之辛温，加牡蛎之咸寒潜阳，正合阴枯阳升之病机，与脉细数虚热之候相应。", []], "1096": ["死脉", "脉如雀啄，乃气血大虚、胃气将绝之死脉。色枯气促、身重如山、不思纳谷，皆脾肾衰败、精气不能上荣外达之象。雀啄脉来数而一止，止而复作，如雀啄食，为真元耗散、虚风内动之候，故虑其暴脱。", ["雀啄"]], "1097": ["病机", "脉愈弱，色脉俱衰，食减寝少，神不自持，皆虚脱之象。寒热两日后脉弱，乃正气不支、脾胃虚惫，气血生化无源，故议固涩之法以挽虚脱，不及理病，示急则治标之意。", ["弱"]], "1098": ["治法", "原文仅言脉神稍安，未及具体脉象，故脉象要素为空。脉神稍安示正气渐复，议足三阴补方，乃从肝脾肾三阴入手培补，以固其本，属治法范畴。", []], "1099": ["病机", "脉涩为阴亏血少、脉道不利之象。体质阴亏偏热，近日不饥口苦，乃胃阴有伤、邪热内炽，热灼津伤则脉涩，胃阴不足则不思食，古称邪火不杀谷，正合此机。", ["涩"]], "1100": ["病机", "脉数主热，口渴有痰，乃胃阴未旺、虚热内扰之候。数脉为热，热灼津液故口渴，津凝为痰，胃阴不足则虚火内生，此数脉非实热，乃阴亏阳亢之象。", ["数"]], "1101": ["病机", "脉耎小带弦，耎小为胃阳不足、气血虚弱，弦为土虚木乘。知饥不欲食、晨起吐痰，乃胃阳不振、痰饮内停，故宜外台茯苓饮健脾化饮，此脉示胃阳不足兼肝木偏亢。", ["耎", "小", "弦"]], "1102": ["病机", "脉右濡，右主气分，濡为湿滞、阳气不运。脐上聚气横束、食难用饱、数日更衣，乃胃病清阳失司、气分痹阻，九窍失和皆属胃病，故仿仲景微通阳气为法。", ["濡"]], "1103": ["病机", "脉濡自汗，口淡无味，乃胃阳惫矣。濡为阳气虚馁、湿浊内滞，阳虚不能固表则自汗，胃阳衰则口淡无味，此濡脉主胃阳不振、气不摄津之病机。", ["濡"]], "1104": ["误治", "脉小为胃阳不足，右弦主中焦气滞。劳倦伤脾、饮食不和，本属内伤，医反投柴葛升表、消导攻里，致汗泄三日，胃阳大伤，脘中不饥。脉小弦正是胃阳虚而气不和之象，故防哕呃厥逆之变，此段重在误治伤阳。", ["小", "弦"]], "1105": ["病机", "长夏湿热伤脾胃，疟痢之后老年气衰，清阳不转，脘中不容纳、痰吐不清。脉弦为土虚木乘，右濡涩主脾阳不运、湿滞血少。下焦便不通调、九窍不和，皆胃病及肠。刚补不安者，阳土不耐辛热，故议宣通补，大半夏汤加川连姜汁。", ["弦", "濡", "涩"]], "1106": ["病机", "壮年肌柔色黯，脉小濡涩，小为阳气不足，濡涩主湿滞血少。每食过不肯运化、食冷物脐上即痛，正是胃阳不旺、浊阴易聚之征。色脉参合，病在腑阳不通，故医知腑阳宜通，自有效验，此段以脉证合参定胃阳虚浊阴聚之病机。", ["小", "濡", "涩"]], "1107": ["病机", "脉象窒塞，未成具体脉名，然窒塞即脉气不畅之象。能食少运、便溏，是脾阳不运、水谷不化。脾阳宜动则运，故当温通脾阳。脉窒塞与能食少运便溏相应，说明中阳不振、气机壅滞，非食积实滞，故以温通为治。", []], "1108": ["其他", "温通脾阳颇适，而脉象仍然窒塞，说明药已中病、阳气渐复而脉气未畅，脾阳久困未全振。照前方再服二剂，是守温通之法；如作丸方，当脾肾同治，因脾阳根于肾阳，脉窒塞未解提示病本在脾肾，非独脾也。", []], "1109": ["病机", "脉缓弱为脾胃阳气衰微之象，缓属湿、弱属虚。脘中痛胀、呕涌清涎，正是脾胃阳微、阴浊上逆；得之积劳，午后病甚，阳不用事。脾阳宜动则运，故温补极是，而守中腻滞皆非，宜通腑阳间佐之，此段以脉缓弱定脾阳虚病机。", ["缓", "弱"]], "1110": ["病机", "脉弦主木旺乘土、气机郁滞。食下䐜胀、大便不爽，是水谷之湿内著，脾阳不主默运，胃腑不能宣达，升降失司。弦脉与胀满不爽相应，说明湿伤脾胃、升降不利，故治以疏脾降胃，令其升降为要。", ["弦"]], "1111": ["病机", "脉虚涩弱，虚弱为阳气大衰，涩为血少气滞。面乏淖泽、鼻冷肢冷、肌腠麻木、时如寒凛微热，皆阳衰不能温煦；欲溺大便有不化之形、谷食不纳，是脾肾阳虚、火不暖土。脉证合参，故理进温补，用附子理中汤。", ["虚", "涩", "弱"]], "1112": ["病机", "左脉数、右濡，数主气火内扰，濡主胃气不充。气塞心痛者，肝气上逆、胃气不和，气机壅塞于胸脘，故痛。数见于左，示肝经有热；濡见于右，示胃气柔弱。治以养胃平肝，正合左数右濡之机，使肝平胃和则气塞自通。", ["数", "濡"]], "1113": ["病机", "脉弦为肝木之象，弦主痛、主气逆。胃脘痹痛而子后清水泛溢、由少腹涌起，显系肝厥犯胃，肝气挟水饮上逆，胃失和降。弦脉应肝，故知痛自肝厥而来，非单纯胃腑本病，乃肝胃同病之候。", ["弦"]], "1114": ["病机", "左弦右涩，弦为肝气偏旺，涩为胃络不畅、气血滞涩。中脘痛及少腹，是肝气横逆、由胃及腹，气机郁滞不通。左弦示病本在肝，右涩示胃受其累，故原文断为病在肝胃，弦涩并见正合肝郁胃滞之机。", ["弦", "涩"]], "1115": ["病机", "左脉弦，弦应肝胆，主气逆。少寐而气从左升，是肝升太过、肝阳不潜，气火上扰心神则少寐，气从左胁上冲故自觉气升。此非胃病为主，乃肝气偏亢、胃受其制，故治以泄肝和胃，使肝降胃和则气升自平。", ["弦"]], "1116": ["病机", "脉缓为脾胃本象，左弦则肝木偏旺。晨倦食减，值土旺之候而脾运不健，是肝木乘土、脾胃受困。缓中见弦，示土虚木亢，故不急伐肝而急调脾胃，用戊己汤去甘草加谷芽，培土以御木，正合缓弦并见之病机。", ["缓", "弦"]], "1117": ["病机", "原文未识脉名，仅言诊脉时手指微震。曲运神机、心多扰动则君相火动，火动消烁，故梦寐不宁、食纳痰多、形骸不充。手指微震是心肝风火内动之征，非脉象本身。首宜理阳明以制厥阴，即培土以平木火，使君相不妄动。", []], "1118": ["病机", "脉虚为正氣不足之象。操家烦动嗔怒，肝气易逆，木犯胃土则干呕味酸；风木动而晨泄食少，形瘦脉虚，是肝旺乘脾、脾胃日衰。虚脉示正气已损，故不专伐肝，先议安胃和肝，使土安则木有所制，正合虚脉主虚之旨。", ["虚"]], "1119": ["病机", "病久正气已衰，喜热恶寒为虚寒之征，而左脉尚弦，弦主肝病，示病根在肝。高年体虚，虽有肝弦之象，却非伐肝平肝所宜，当通补胃阳，以温养中土、缓肝之亢。左脉尚弦说明肝气未平，但正虚为主，故治从通补。", ["弦"]], "1120": ["病机", "脉虚为胃阴不足、阳气熏蒸之象。原文谓“胃阴不升，但有阳气熏蒸”，致咽燥不成寐、冲逆心悸，厥阴内风乘胃虚上僭，故胃脉日虚，肢肌麻木。脉虚主胃气亏虚，不能升津濡咽，亦不能御肝风，与咽燥、不寐、心悸、麻木诸症相应。", ["虚"]], "1121": ["病机", "脉弦为厥阴肝阳偏亢之象。原文谓“厥阴肝阳顺乘胃口，阳明脉络不宣”，故心中热、欲呕、不思食、大便不爽、身体掣痛。弦脉主肝，肝阳犯胃则胃气不降，脉络失宣，诸症由生。治当两和其阳，酸苦泄热，少佐微辛。", ["弦"]], "1122": ["病机", "原文未出脉象，然论病机谓“初病在气，久必入血”，肝气之逆久则诸气均逆，三焦皆受，木犯胃土，胃受克为虚。惊则气逆为初因，久则气逆入络，故陈缓急先后进药方法，议用安胃一法，制木必先安土，防久克难复。", []], "1123": ["病机", "右脉虚弦带涩，左脉小弦劲而数，为肝病既久、脾胃必虚、风木郁于土宫之象。虚弦带涩主脾虚肝郁、营卫不畅；小弦劲数主肝阳偏亢、内风扰动。故胃痛虽缓，而畏寒鼓栗、俄顷发热，乃肝病先厥后热，营卫失于流畅所致。", ["虚", "弦", "涩", "数"]], "1124": ["病机", "脉小弦为木火犯土之象。小主不足，弦主肝木，因悒郁强饮，肝郁化火，横逆犯胃，胃气不得下行，故纳谷脘中哽噎。脉小弦正合肝郁土虚、木火内扰之机，治以苦辛泄降，使胃气得降，肝火得清。", ["小", "弦"]], "1125": ["病机", "右脉虚、左脉弦，为脾胃困顿、肝木偏旺之象。右虚主脾胃气虚，左弦主肝木乘土。晨起腹痛、食谷微满、不思饮食，皆清浊阻滞、脾胃虚弱而肝木克之所致。古人培土必先制木，正合此脉此证。", ["虚", "弦"]], "1126": ["病机", "原文未出脉象，然述经行后冲脉血下，跷维脉怯不用，因惊肝病，木乘土位，胃衰气逆。初则气升至咽，久则懒食脘痞，厥气上加，势必呕胀吞酸。此冲隶阳明、厥阴对峙，肝病及胃，阳明不阖，故治取阳明，通补为宜，刚药畏劫阴，少济以柔。", []], "1127": ["病机", "原文未出脉象，述季胁虚里穴跳跃如梭，乃阳明络空，冲脉亦属阳明所管。经行后病变，冲气欲胀，冷汗跗寒，食入恶心，鼻准明，环口色青，肝胃相对，一胜一负。此络虚阳微、冲气上逆之机，故议理阳明之阳，佐以宣通奇脉，仿仲景动气阳微之法。", []], "1128": ["病机", "脉寸强尺弱，寸强主阳浮于上，尺弱主下元不足。厥阴之阳化风，乘阳明上犯，蒙昧清空，故见麻痹干呕耳聋、昏迷如厥；食减少、口味淡、微汗为阳明胃弱之征。此上盛下虚、风阳上扰之病机。", ["强", "弱"]], "1129": ["病机", "原文言“阳明脉络空虚”，非具体脉象，故脉象要素为空。阳明脉络空虚，冲任无贮，故经水不至、腹中微痛、右胁蠕蠕而动。此冲任亏虚、络脉失养之病机，主经闭、腹痛。", []], "1130": ["主病", "未识别出脉名，脉象要素为空。原文述“阳明脉衰”，形寒、痞、饥不食、心痛、洞泄兼呕，皆阳明虚衰、中阳不运、升降失常之候。主病在阳明，属虚寒。", []], "1131": ["病机", "脉微小弱，是阳气已衰。长夏热泄气分，脾胃先受困，故不食不运、味变酸苦；稍涉嗔怒，木乘土中，益加不安。此脾阳衰微、木乘土位之病机，主纳运失常。", ["微", "小", "弱"]], "1132": ["病机", "脉小弱，是阳虚体质。郁勃内动少阳木火，木犯太阴脾土，遂致寝食不适。此木火犯土、阳虚郁勃之病机，主寝食不安，法当补土泄木。", ["小", "弱"]], "1133": ["病机", "肝为风木之脏，性急而动，病则脉必弦。弦为肝脉，主肝气亢逆。肝病犯土，侮其所胜，故见胁胀疼、偏寒偏热、先厥后热；犯胃则恶心干呕、脘痞不食、吐酸水涎沫；克脾则腹胀、便溏或爽、肢冷肌麻。此肝木乘土之病机。", ["弦"]], "1134": ["病机", "脉弦色黄，弦主肝木，色黄主脾土。食谷不运、䐜胀呕恶、大便不爽，乃胃阳式微、升降失司使然。弦脉在此示木郁克土，胃阳虚而肝乘之，故法当温通阳气。", ["弦"]], "1135": ["预后", "右大而缓，左小数促，大缓为劳倦伤脾、中气不足之象，数促为虚阳内扰。面浮足肿、呼吸皆喘、食纳不运，皆脾胃衰而营卫失度。仲景谓“男子脉大为劳”，此劳倦致损，交夏脾胃主候，中满胀病日来，预后堪虑。", ["大", "缓", "数", "促"]], "1136": ["病机", "左脉弦，弦为肝木之象，主气机郁滞。胀满不运、便泄不爽，乃肝失疏泄，木不疏土，脾运失健，气滞于中则胀满，传导失常则便泄不爽。治当温通脾阳，以复中焦运化。", ["弦"]], "1137": ["病机", "脉沉小弦，沉主里，小为阳微，弦乃饮象。中年后阳气不足，痰饮水寒乘虚逆趋，致运纳失和，渐成胀满浮肿。此本在脾胃阳虚，水寒不化，法以辛温宣通，正合病机。", ["沉", "小", "弦"]], "1138": ["病机", "脉沉小缓，沉小为阳气式微，缓则示腑阳久伤、流行失司。早食难化、晚食夜胀、大便不爽，皆脾阳不运、传导无力之征。故必以温药疏通，忌闭气黏荤，以护中阳。", ["沉", "小", "缓"]], "1139": ["病机", "脉细软，细为阴血不足，软为阳气衰微。肿胀由足入腹，乃水湿泛滥，脾肾阳虚不能运化水谷，故不能运谷。治当少阴太阴，温补脾肾以化气行水。", ["细", "软"]], "1140": ["病机", "脉微而迟，微为阳衰，迟为阴盛。色衰萎黄、久利久泄，皆阳气不足之候。食蟹咸寒损阳，致水失火而败，浮肿自下而起。此肾阳虚衰，火不暖土，水湿泛滥，非暖下不可。", ["微", "迟"]], "1141": ["病机", "原文未识脉名，然述脉络气血不为流行，腹满重坠、脐左动气、吐冷沫、身麻语塞，显系肝风日炽、疏泄失职，木侮土位。丹溪云自觉冷者非真冷，乃气郁阳不达。溃疡后刚燥难进，议宣通肝胃，平淡为治。", []], "1142": ["病机", "脉百至而右缓涩、左弦劲，缓涩为湿滞血少，弦劲乃肝郁化火。情怀少旷，清气不转，肝木侵胃，腑阳窒塞，故肠鸣泄气、腹满䐜胀、纳废便难溺少。此肝郁犯胃兼湿，非旦晚可图，议分消法。", ["缓", "涩", "弦", "劲"]], "1143": ["病机", "脉小而涩，小为气虚，涩为血滞。悒郁经年，肝气不舒，木郁克土，胃病则食入不运、脘中䐜胀；色黄形瘦、喜凉恶热、便未通调，皆胃失和降、九窍不和之征。此郁久伤胃，气血滞涩。", ["小", "涩"]], "1144": ["病机", "脉右弦，面黄腹满，按之漉漉有声，便前腹痛而不干爽，显系肝木横逆，疏泄失司，胃气不降，阳气自滞。弦为肝脉，右关候胃，弦见于右，知肝气犯胃，浊阴内聚，故腹胀漉漉；嗔怒不息，肝木愈横，疏泄愈失，胀满由生。", ["弦"]], "1145": ["病机", "脉左弦，不饥不运，少腹胃脘悉满，乃肝木犯胃，二腑不主流行，浊阴弥漫。左关候肝，弦为肝旺，肝气横逆则胃受克，传化失职，浊阴渐次弥漫，他日单胀难免。原文诫“速速戒恼怒”，正以情志动肝，肝病及胃，为胀满之根。", ["弦"]], "1146": ["病机", "胀势已缓而脉来弦实，弦主肝郁，实主邪滞，知湿热犹未尽去。前胀虽减，脉未和缓，是余邪胶结，故必淡泊食物以清肃胃口，续用清渗利水之剂，使湿热分消。脉实为邪气实，非虚胀可比，再议攻邪，当以脉症为凭。", ["弦", "实"]], "1147": ["病机", "诊脉浮中沉，来去不为流利，是气阻湿郁，胶痰内著，脉道不利。浮中沉皆不流利，非独一部，知痰湿弥漫三焦，气机壅滞。原文以“气阻湿郁，胶痰内著”释之，故用控涎丹缓攻，逐其痰涎，使气机流通，胀满可减。", []], "1148": ["病机", "服控涎丹后大便通而不爽，右脉弦实，目黄舌燥，是中焦湿热不行，肝木乘胃，弦实之脉主邪滞。久病神倦，不敢过攻，故用丹溪小温中丸泄肝通胃，缓治其胀。右脉候脾胃，弦实知湿热与肝气交阻，非纯虚可补。", ["弦", "实"]], "1149": ["病机", "脉形小弱，吐涎沫甚多，不纳谷，周身寒凛，四肢微冷，皆胃中无阳，浊阴上僭。小弱为阳气衰微之脉，胃阳不振则不能纳谷，浊阴上踞而为䐜胀。原文引“食不得入，是无火也”，正指胃阳虚衰，火不生土，故脉小弱而见寒凛肢冷。", ["小", "弱"]], "1150": ["病机", "脉实，久病瘀热在血，胸不爽，小腹坠，能食不渴，二便涩少。实脉主邪结，瘀热在血分，故能食不渴而二便涩少；两进苦辛宣腑未却，知病不在气而在血。原文断为“血病”，用通幽法，以脉实为瘀热内结之征，非虚胀可攻。", ["实"]], "1151": ["病机", "脉左弦右浮涩，脘痛贯胁，腹大高凸，纳减便涩，乃肝木拂郁，脾土自困，清浊混淆。左弦为肝郁，右浮涩为脾虚湿滞，脏真日漓，腑阳不运，胀势乃成。原文强调“通阳为务”，以弦涩知阴凝浊聚，非滋阴柔药所宜，故用禹粮丸暖水脏、攻秽浊。", ["弦", "浮", "涩"]], "1152": ["病机", "脉数主热，暑邪内侵，与肝脾不和相合，气机壅滞，故见恶心、脘胀。数脉为暑热内郁之征，非独虚数，结合症候，病机为肝脾不和夹暑邪，热郁气滞，胃失和降。", ["数"]], "1153": ["病机", "脉小而涩，小主气虚，涩主血滞，郁勃久坐致中焦不运，腑阳失司，气机痹阻，故寒热、小溲不通、腹膨胀满。涩脉示气血不畅，小脉示阳气不充，全属腑阳失司，泄木通腑分消为治。", ["小", "涩"]], "1154": ["病机", "右脉小促，左小弦劲，小促为阳气痹结，弦劲为肝郁气滞，病起脘痛梗突，渐至食减胀满，四肢不暖，便血，爪紫，皆肝脾气血不通，久则阳微痹结，上下不行，有否卦之义，总属清阳痹结。", ["小", "促", "弦", "劲"]], "1155": ["病机", "脉沉弦，沉主里，弦主饮主痛，湿痰阻气为喘，过食停滞，阴脏之阳不运，阳腑之气不通，二便不爽，跗肿腹满，皆水寒痰滞阻遏气分，上下不通调，当从三焦分治。", ["沉", "弦"]], "1156": ["病机", "脉浮小带促，浮主表，小主气弱，促主气结，闻声呼息不利，是气分在上结阻，以致中下不通，喘胀由肺气不降，水湿不行，治当开鬼门洁净腑，宣通表里，急急开上为法。", ["浮", "小", "促"]], "1157": ["病机", "原文未识脉名，然述中满用余粮丸获效，腹胀去而髀尻足跗肿浮，乃脏寒生满病，暖水脏之阳，培火生土，阳未全复，四末流行未布，故肿减后仍议通下焦经脉，加味活络丹。", []], "1158": ["病机", "原文未识脉名，述进神芎导水丸下黏腻黄浊，前议腑气窒塞，水湿黏滞，浊攻犯肺为痰嗽，水渍脉隧为浮肿，经脉六腑之病总以宣通为是，六腑以通为补，肢节足跗之湿必针刺决流。", []], "1159": ["病机", "原文未识脉名，述腹满下至少腹，三阴受伤，周身疥疮数年不断，脉络中必有湿热，腹痛泄泻，腑阳不通，不独偏热偏寒之治，常用四苓散，病机为湿热阻络，腑阳失运。", []], "1160": ["病机", "脉右涩左弱，涩主气血滞涩，弱主阳气不足。面黄瘦露筋，乃积劳忧思伤阳，浊阴自少腹盘踞中宫，妨食呕吐，为单鼓胀之象。阳虚不运，阴浊凝滞，故脉见涩弱，治当急急通阳以驱阴浊。", ["涩", "弱"]], "1161": ["病机", "脉左小弱，右缓大。小弱为气血不足，缓大为脾胃气钝。腹形坚大，二便通闭，纳食腹胀，四肢恶冷，热自里升，衄血牙宣，全是气血交结，非积聚停水。太阴不运，阳明愈钝，故以脾胃为病薮，议缓攻一法。", ["小", "弱", "缓", "大"]], "1162": ["病机", "脉细小右微促，细小为阳气衰微，微促为虚寒内结。畏寒甚，右胁中气触入小腹，著卧即有形坠著，乃水脏虚寒，阳气不通，阴寒之气下坠。故用禹余粮丸暖水脏以通阳气。", ["细", "小", "微", "促"]], "1163": ["病机", "脉入尺，弦胜于数。弦主肝郁，数主热，尺部弦甚为元海阳虚，肝失疏泄。阳虚则水寒，肝郁则气滞，以致䐜胀。病本在元海阳虚，病标在肝失疏泄，故朝用玉壶丹温阳，午用疏肝实脾利水，分消太阳太阴之邪。", ["弦", "数"]], "1164": ["病机", "脉弦数，弦主肝郁，数主热，然手足畏冷、心中兀兀，为中气已虚，虚寒内生。脉数非实热，乃虚阳外浮。中虚不运，故先用小针砂丸消积，后以药压之，兼顾中气。", ["弦", "数"]], "1165": ["病机", "脉如涩，涩主湿滞血瘀。阳气动则遗，右胁汨汨有声，坠入少腹，可知肿胀非阳道不利，是阴道实，水谷之湿热不化。涩脉为湿热壅滞、气血不畅之象，故用牡蛎泽泻散化湿逐水。", ["涩"]], "1166": ["病机", "脉数实，数主热，实主邪盛。恶水，午后手足畏冷，乃阳明中虚，水气聚而为饮。数实为饮热内结，然中虚畏冷，故以苓桂术甘汤劫饮，牡蛎泽泻散止遗逐水，加生于术健脾。", ["数", "实"]], "1167": ["病机", "脉虽数而右大左弦。数主热，右大主阳明中虚，左弦主肝郁。手足畏冷，不喜饮水，右胁汨汨有声下坠少腹，信是阳明中虚，水饮内停。故用人参熟附生姜温经补虚，调治太阳太阴。", ["数", "大", "弦"]], "1168": ["病机", "原文论肿胀之因，分阳水阴水：外来风、湿、气、热为有余，即阳水；大病后脾肺虚弱、心火克金、肾阴亏虚火烁肺，致水道不通、小便不利，为不足，即阴水。胀则因湿、郁、寒、热、气、血、痰、积、虫，位有脏腑脉络皮肤上下表里之别，且寒郁化热、热中传寒。全段以病因分类阐发肿胀病机，未及具体脉象。", []], "1169": ["病机", "疟邪久留，结聚血分成疟母，本属少阳厥阴。今脉弦大，面色黄滞，腹大青筋皆露，颈脉震动，是脾胃受伤、积聚内起、气分受病、痞满势成，与疟母邪结血分两途。弦主木旺土衰，大主病进，故断为脾胃伤气分结痞，经年正怯，宜疏补两施、缓攻为治。", ["弦", "大"]], "1170": ["病机", "右胁有形高突，按之无痛，断为瘕痞，非气聚凝痰可比。原文谓病久仅阻在脉，须佐针刺宣通，正在伏天宜商。此段以形症定病位在脉络，属痰凝脉络之瘕痞，未载脉象，故脉象要素为空。", []], "1171": ["病机", "著而不移，是为阴邪聚络。诊脉弦缓，弦主阴邪结聚、络脉凝滞，缓则示病势缠绵而非急攻可下，故难以五积肥气攻治。大旨以辛温入血络治之，取辛能通络、温能散阴之意，紧扣脉络凝痹之病机。", ["弦", "缓"]], "1172": ["预后", "伏梁病在络，日久有血凝之虑。脉数左大是其征也：数主热、主病进，左大应肝木血络，示邪郁化热、血络壅滞，故预断日后当血凝。此段以脉数左大作为伏梁血凝之兆，属预后判断。", ["数", "大"]], "1173": ["治法", "脉数坚，数主热郁，坚主积结牢固，与伏梁病在络相合，示气血壅结、络脉不通。故治宜气血分消，既行其气，又通其血，使络中积结渐消。此段由脉数坚推出伏梁在络之病机，并立气血分消之法。", ["数", "坚"]], "1174": ["病机", "以不动者为症、动者为瘕，即难经积聚之意。属脏者阴，阴主静，静则坚而不移；属腑者阳，阳主动，动则移而不定。案中由此悟出著而不移为阴邪聚络，大旨以辛温入血络治之。全段辨症瘕动静阴阳之病机，未出具体脉象。", []], "1175": ["病机", "脉不清，神烦倦，中痞恶心，乃热邪里结。脉不清示邪热内壅、脉道不利，热结中焦则痞满恶心，扰及心神则烦倦。故进泻心法，以苦寒泄热、辛开散结。此段由脉症合参定热邪里结之病机，未明写脉象要素。", []], "1176": ["病机", "原文未出脉名，述烦劳之人卫气少固，雾露雨湿伤其流行清肃，致疮痍外涸、脘胁反痹。此明经脉为病，无关腑脏，病机在卫外不固、湿邪痹阻经脉，非脏腑内伤，故脉象无从指认。", []], "1177": ["病机", "脉形濡涩，濡主湿、涩主滞，为暑湿热气内伏、正气泄越之象。原文明言“岂是表症”，故不可发散取汗；面垢油亮、目眦黄、头胀如束、胸脘痞闷皆暑湿郁蒸之症，壮年已非有余，当从劳倦伏邪例诊治。", ["濡", "涩"]], "1178": ["病机", "脉濡而缓，濡为湿象、缓为气机弛缓，主时令之湿与水谷相并、气阻不行，欲作痞结。不饥不食即气阻之症；体质阳微，故开泄宜轻，不可过用苦寒攻下，免伤中阳。", ["濡", "缓"]], "1179": ["主病", "脉沉主里、主气机内郁，中脘不爽为气阻于中，肢冷为阳气不达四末。沉脉与脘闷肢冷相应，说明病在里而不在表，属阳气郁遏、中焦气滞之候。", ["沉"]], "1180": ["预后", "脉微有歇，微为阳气衰微、歇为脉气不续，故见无神倦欲寐。服大半夏汤而脘痛不安，不耐辛通，知营液大虚、胃气已惫。春节在迩，恐防衰脱，是脉症相参而虑其正气难支。", ["微", "歇"]], "1181": ["病机", "脉涩主气滞血少、脉络不畅，与脘痞不饥、口干有痰相应，说明气机郁滞、津不上承而痰阻上焦。原文谓“当清理上焦”，是涩脉在此主气分郁滞而非单纯血瘀。", ["涩"]], "1182": ["治法", "此段未出脉象，专论治痞之法：六淫外侵用泻心汤，脾胃内伤用苓姜桂甘法，以苦为泄、辛甘为散；邪伤津液者辛苦开泄兼酸味以助，上焦不舒者枳桔杏蒌开降、栀豉除热化腐。总在临症视阴阳虚实，灵机应变。", []], "1183": ["病机", "脉小涩，小为阳气不足、涩为阴液不充，主阳气结于上、阴液衰于下。脘中隐痛、呕恶吞酸、舌绛不多饮，皆上下不通之象，故为关格之渐，治当开痞通阳。", ["小", "涩"]], "1184": ["病机", "脉弦大而搏，弦主气结，大主邪盛，搏为邪正相争。老人食入涎涌、二便艰少，是阳不转旋而上结，阴枯于下而便难。脉象反映阴阳俱损、气结于上，故难调治，用妙香丸以通阳开结。", ["弦", "大"]], "1185": ["预后", "原文未识脉名，但言“两脉生气日索”，即脉象渐失胃气。积劳伤阳，阴枯阳结，五液告涸，咽燥溺少，故脉无生机。病属噎膈反胃，非医药能愈，预后不良。", []], "1186": ["病机", "脉寸口搏大，按之则涩。搏大主阳结于上，涩主阴枯血少。形瘦气逆，上不纳食，下不通便，是阳结不行、阴枯腑乏津营，致二便交阻，病名关格，故为难治。", ["大", "涩"]], "1187": ["病机", "脉涩左大，涩主液亏血少，左大主肝气偏亢。食入为噎，是液亏气滞，胃失濡润。先理气后润剂，针对液亏气滞之噎膈。", ["涩", "大"]], "1188": ["病机", "脉弦而小涩，弦主郁怒气滞，小涩主阴血不足。郁怒化火，气滞痰聚，清阳不展，脘管窄隘，食入脘痛格拒、吐清涎，噎膈渐至。法当苦降辛通，佐利痰清膈。", ["弦", "涩"]], "1189": ["病机", "脉濡缓无力，濡缓主湿，无力为阳虚。胃中无阳，浊阴腐壅，故早食晚吐，属反胃。仿仲景阳明辛热宣通例，以温阳化浊。", ["濡", "缓"]], "1190": ["病机", "脉缓，右关弦。缓为胃气不足，右关弦主胃阳衰微、开合之机已废。知饥恶食、食入即吐、肢浮便溏溺少，皆胃阳衰微之噎膈反胃大症。", ["缓", "弦"]], "1191": ["病机", "脉左小弦，右濡涩。左小弦主肝郁，右濡涩主脾虚湿滞血少。阴阳日衰，劳烦伤阳，清气欲结，食入脘痛、痰涎涌逆，皆噎膈反胃见症。饮酒愈甚由正气先馁。", ["弦", "濡", "涩"]], "1192": ["病机", "脉沉微，沉为阴位，微为阳衰，故曰“阳气大伤”。阳虚不能温运，阴浊僭踞中焦，升降失司，故旦食不能暮食；阴浊凝滞经脉，周身掣痛、背胀。脉症相合，示阳虚阴浊凝滞之重证，故云“病状著难愈之症”。", ["沉", "微"]], "1193": ["病机", "两关脉缓涩，缓主阳气不运，涩主积滞血瘀。食入气阻、吐涎稍通，前吐瘀浊胶黏，皆久积劳倦、阳气不主旋运所致。脉缓涩与噎膈反胃之症相应，示中阳不振、瘀浊内阻，故病多反复，须身心安逸方可却病。", ["缓", "涩"]], "1194": ["病机", "原文未出脉名，以“血枯气衰”立论。香燥消涩久禁，因阴血已亏；阳微浊踞者偶用辛热，余则苦辛泄滞兼润养、酸甘化液直滋清，总以调化机关、和润血脉为主。末言“阳气结于上，阴液衰于下”，点明上结下衰、气血枯涩之病机。", []], "1195": ["病机", "脉细为阴血不足，右坚大为厥阳上冒之象。向有气冲，长夏土旺，呕吐不纳食、头胀脘痹，皆厥阳挟冲气上逆，胃失和降。脉细坚大与症相应，故议苦辛降逆、酸苦泄热，使胃和则愈，戒嗔怒以平肝阳。", ["细", "坚", "大"]], "1196": ["病机", "脉细小而弦，细为阴血不足，弦为风木亢盛。当春木气张，风木乘土，故食入不变、呕吐；小便通少缓，示气化得行则逆稍平。脉弦细小与风木乘土之机相应，治以通阳，使中阳复则木不犯土。", ["细", "小", "弦"]], "1197": ["病机", "脉右弦涩，弦主阳微阴凝，涩主浊滞不通。食入则吐、胃痛胀甚，半月前药效后反大便欲解不通，乃腑阳不利、浊乃上攻。脉弦涩与阳微阴凝、浊气上逆之症相应，故先用玉壶丹通腑泄浊，使浊下则呕胀可减。", ["弦", "涩"]], "1198": ["主病", "脉沉主里、主阴寒。食入呕吐，沉脉示胃阳不振、阴寒内踞，受纳腐熟失职，故食入即吐。忌冷滞食物，正因沉脉主里寒，冷滞更伤中阳。此段以脉沉定病位在里、病性属寒，主胃寒呕吐之病。", ["沉"]], "1199": ["病机", "脉濡弱，濡主湿滞，弱主阳微。左胁下久有聚气，纳食酿积胃脘，呕噫吞酸，皆怫怒动肝、肝木犯胃，胃中阳伤，不能传及小肠，变化失司，故七八日始一更衣。脉濡弱与胃阳伤、肝逆犯胃之机相应，法当温胃阳、制肝逆。", ["濡", "弱"]], "1200": ["病机", "脉濡涩，濡主胃虚湿滞，涩主血少气滞。原文述食后漾漾涌涎欲吐，乃胃虚肝乘，胃气上逆。濡涩相合，示胃虚不运、肝气犯胃之病机，故用旋覆代赭汤降逆和胃。", ["濡", "涩"]], "1201": ["病机", "右脉弱主中阳不足，左脉弦主肝气偏亢。因惊肝气上犯，冲逆呕吐涎，阳升头痛。右弱左弦，正是厥阴肝木乘阳明胃土之象，故从厥阴阳明治。", ["弱", "弦"]], "1202": ["病机", "脉弦虚，弦为肝气横逆，虚为胃气不足。食已漾漾欲吐、咽阻中痞有痰，乃肝气犯胃、胃虚痰阻，气机上逆所致。弦虚并见，主肝乘胃虚之病机。", ["弦", "虚"]], "1203": ["病机", "右脉小欲歇，小为气血不足，欲歇为胃气衰败之兆。汤水下咽呕吐，明是劳伤中气，肝乘胃反。脉小欲歇示胃虚已甚，故用小半夏汤加檀香、粳米和胃降逆。", ["小"]], "1204": ["病机", "脉虚不食，虚主胃气亏虚，不食为胃不受纳。干呕胁痛因恼怒而病，是厥阴肝气侵侮阳明胃土。脉虚示中虚，故当通补，用大半夏汤加姜汁、桂枝、南枣。", ["虚"]], "1205": ["病机", "脉弱汗出，弱主阳气虚衰，汗出为阳虚不固。积劳伤阳，脘痛引背，频吐微眩，胃中已虚，肝木来乘。脉弱示中阳不足，防有呃忒吐蛔，故用吴茱萸汤温胃降逆。", ["弱"]], "1206": ["病机", "原文未识脉名，然述攻胎伤气血、寒热身痛，奇经冲任受病，阳维不用。更见汤饮哕出、便闭半月、吐青绿涎沫，显系肝风大动，将胃口翻空，肠中污水荡漾。此乃误治致肝风内动、胃气败逆之危候。", []], "1207": ["病机", "右手涩弱，虚象昭然；左脉空大，按之不实。涩弱主气血亏虚，空大主阴不敛阳。产后血去液亏，真阴日损，阳气不交于阴，变化内风，上巅犯窍，冲逆肆横，胃掀吐食。此非肝气有余，乃虚风内动之病机。", ["涩", "弱", "空", "大"]], "1208": ["病机", "原文未出脉名，仅言\"肢冷\"。肢冷为阳气不达四末，呕逆、下痢白积乃阴寒内盛、浊邪犯胃所致。\"生冷水寒郁生阳\"说明寒邪郁遏阳气，气机不得宣通，故\"气上塞心大痛\"。此为厥阴浊邪上攻，寒浊循经上逆，阳郁不伸，故见肢冷而痛。脉虽未明，当为沉紧或弦迟之属，主寒实内结、浊阴上逆之病机。", []], "1209": ["病机", "原文未出脉名，以\"阳微不运\"立论。阳气式微，不能运化水谷，悍气不散而聚为湿浊，湿阻中焦则\"食入即呕\"，阳气不布则\"周身牵掣不和\"。此为阳明胃阳不用事，纳运失职。久延湿浊泛溢，恐致肿胀。脉当见濡缓或沉弱，主阳虚湿聚、胃气不运之病机，治以苓姜术桂汤温阳化湿。", []], "1210": ["病机", "右濡为胃气虚弱、湿浊内滞，左弦为肝木偏旺。舌白不饥示胃阳不振、湿阻不化。瘀血上吐下泻，胃阳大伤，药入即涌，所吐皆酸水痰沫，乃胃中虚寒、痰饮上逆。右濡左弦正合胃虚肝乘之象，主胃阳大伤、痰饮内阻、肝木犯胃之病机，故以理阳为法。", ["濡", "弦"]], "1211": ["病机", "脉虚无神，为胃阳大虚、气血生化无源之象。闻谷干呕，乃胃虚不能纳谷、气逆于上；汗出振寒，为阳虚卫外不固、腠理失密。原文明言\"此胃阳大虚\"，指出不可因寒热表象而攻邪，当以扶阳为要。脉虚无神紧扣胃阳衰败，主虚寒内生、卫阳不固之病机。", ["虚", "无"]], "1212": ["病机", "脉微细小，为阳气衰微、气血不足之象。微者阳微，细者阴弱，小者气少，三象并见，示胃阳大衰、中焦虚寒。原文承前案而言\"以理中兼摄其下\"，说明中阳衰而下元亦不固。此脉主胃阳大衰、中气虚弱之病机，治当温理中阳兼固下元，非攻邪所宜。", ["微", "细", "小"]], "1213": ["病机", "脉弦主饮邪内阻、气机不畅，迟主阳结寒凝。汤水不下膈、呕吐涎沫，乃饮邪阻遏胸膈、阳气不得宣通，故称\"阳结\"。弦迟并见，正合寒饮内结、气机壅塞之象。原文议\"辛热通阳、反佐苦寒利膈\"，用泻心法，主饮邪阻气、阳郁不伸之病机，与脉弦迟相应。", ["弦", "迟"]], "1214": ["病机", "左弦为肝木偏亢，右弱为胃气不足。食粥脘中有声、气冲涌吐，乃肝木乘胃、胃虚气逆所致。原文明言\"此肝木乘胃，生阳已薄\"，又谓\"皆情怀不适所致\"，说明情志不遂、肝郁化火犯胃，胃阳日衰。左弦右弱正合肝旺胃弱之象，主肝木乘胃、生阳衰薄之病机。", ["弦", "弱"]], "1215": ["病机", "脉微为阳气衰微之象，肢冷、呕吐清水、食不下化，皆阳虚不能温运之征。带下脊髀酸耎，乃产后奇脉不固、下元虚惫。原文谓\"阳气素虚，产后奇脉不固\"，指出病本在阳虚。脉微与肢冷并见，主阳气素虚、奇经失固之病机，故急扶其阳，用附子理中汤。", ["微"]], "1216": ["预后", "原文“脉象稍和”指脉象由病态渐趋调和，是邪退正复之象。前用理中汤温中健脾，已得效验，故脉象转和，说明脾胃阳气渐复，气机趋于调畅。脉和则胃气未绝，可议养营法以滋营血，巩固疗效。此脉象主病机向愈，预后良好。", ["和"]], "1217": ["病机", "原文“脉之短涩无神论之，阳衰邪伏显然”。短脉主气病，涩脉主血少或邪滞，无神为阳气衰微之征。患者肌肉柔白、阳虚多湿多痰，邪踞中焦，正衰邪炽，故脉短涩无神，主胃阳虚而邪伏不食，与干呕胸痞、杳不纳谷相应。", ["短", "涩"]], "1218": ["病机", "原文“脉小濡”主阳气微弱。小脉为阳气不足，濡脉主湿、主虚。壮年形伟而脉小濡，形盛脉弱，说明阳气式微，浊阴类聚。口鼻受污浊异气，先入募原，上逆呕吐，故脉小濡主阳虚吸受秽浊，与恶闻秽气、食入呕哕相应。", ["小", "濡"]], "1219": ["病机", "原文“诊脉右大，并不搏指”。右大主胃中气分偏盛或津伤气浮，不搏指则非实热坚结。两番探吐后脘痛止而胃津受损，风木来乘，外冷里热，故脉右大不搏指，主胃津未复、肝木乘土，当少少进谷以养胃，调和中焦。", ["大"]], "1220": ["病机", "原文“冲脉动，而诸脉交动也”。动脉主惊、主痛、主气机逆乱。少腹属肝，肝厥犯阳明，痛呕二年，久则奇经诸脉交伤，冲脉气上逆，故脉动。此脉主肝肾虚损、冲脉气逆，与少腹痛呕、奇经交伤相应，治从下焦虚损温通柔润。", ["动"]], "1221": ["病机", "本段未言脉，专论呕吐病机。原文强调“胃司纳食，主乎通降”，其不降上逆“皆由于肝气冲逆，阻胃之降”。五行木动必犯土，故胃病治肝，以泄肝安胃为纲领，用药苦辛为主、酸佐之。此论呕吐责在肝气冲逆犯胃，非独胃火胃寒痰食气滞。", []], "1222": ["主病", "原文“脉右歇”指右脉歇止，为结代类脉，主气分邪阻、脉道不利。舌白渴饮、脘痞热、呕逆稠痰、吐蛔，乃伏暑湿伤气分，邪自里发，湿邪不运。脉歇主邪阻气机，与伏暑湿浊内蕴、胃气上逆相应，故议半夏泻心汤苦辛通降。", ["歇"]], "1223": ["病机", "原文“冲脉动，则诸脉皆逆”。动脉主气逆上冲。蛔虫上下、呕吐痰涎浊沫，乃厥阴乘犯阳明，内风入胃；老年冲脉既衰，冲脉动则诸脉皆逆，周身牵引直至足心，阴阳跷维不得自固。此脉动主冲脉气逆、厥阴伏邪未达，与呕吐浊痰、牵引相应。", ["动"]], "1224": ["病机", "原文未出脉名，以“食入欲呕、心中温温液液、痰沫味咸、脊背上下引痛”立论。味咸属肾，涎沫上泛为肾虚水液不化、水寒上逆；督脉循脊，约束失司则脊背引痛。故病机为肾阳虚衰、水寒上泛，主真武汤证，与痰沫、呕逆、背痛相应。", []], "1225": ["病机", "脉沉弦，沉主里、弦主肝木。原文言误表禁食伤胃，肝木上干胃土，蛔虫上出，故腹痛呕吐、鼻煤舌绛、面青晦。沉弦正示里虚而肝横，木乘土位、胃气上逆之机，有厥逆之虑，治拟泄肝和胃。", ["沉", "弦"]], "1226": ["预后", "痛再发而诊脉微细，微细为阳气衰微、正气不相接续之象。恰值立夏交节，阳气当升而脉不能应，故原文断“有复厥之虑”。此段以脉微细测正气虚脱、厥逆将作，属预后判断，非泛言主病。", ["微", "细"]], "1227": ["主病", "脉虚缓，虚为阳气不足，缓为胃气薄弱。原文自注“胃阳虚”，症见不食不饥、形寒浮肿。胃阳不振则纳运无权而不饥，阳虚不能温煦则形寒，水湿不化则浮肿，脉虚缓正合胃阳虚之病机。", ["虚", "缓"]], "1228": ["病机", "时病后脉弦而劲，弦劲为肝木偏旺、胃气未和之象。原文谓“知饥不纳”，知饥属胃气尚存，不纳因胃气未和、木气扰动。弦劲非平和之脉，故当静处调养，使胃气和降、脉转柔和，此段重在示病后胃未和之机。", ["弦", "劲"]], "1229": ["病机", "脉濡无力，濡为湿滞、无力为阳气不振。原文言天暖气泄、烦劳再伤阳气，卫外之阳内应乎胃，胃逆则不纳不饥。唇赤舌干微眩，是阳泄于上、胃气不降之候，脉濡无力正示阳气虚而湿滞，主胃阳受伤之机。", ["濡", "无", "力"]], "1230": ["病机", "原文未出脉名，以舌白、不渴不饥、旬日不便、皮肤麻痒、腹中鸣动立论。风湿化热阻遏气分，诸经脉络皆闭，故肠痹不通、鸣动麻痒。此段引丹溪开肺气以宣通之法，病机在气分痹阻、湿热内闭，属病机分析。", []], "1231": ["病机", "脉右部弦搏，右候肺与大肠，弦搏为气机郁阻、浊邪内攻之象。高年疟后内伤食物，腑气阻痹，浊攻腹痛、二便不通、渴思冷饮。原文引肺主一身气化，主张开提肺窍以通下，脉弦搏正示气闭于下、浊壅不通之病机。", ["弦", "搏"]], "1232": ["病机", "原文未识脉名，但述“沉锢之疾”“病著深远”，提示病邪深伏。平素饮酒厚味，酿湿聚热，渍筋烁骨，故大便仍秘涩，针刺无增减。湿火胶结，非汤液能通逐，故议大苦寒坚阴燥湿，参酒醴引导，同气相求。病机为湿火深锢，主大便秘涩、筋骨受蚀。", []], "1233": ["病机", "原文未识脉名，述“脉右如昨，左略小动”，左关小动应肝风震动，里气大燥，火腑不通。肝风内动，燥热结于肠腑，故更衣丸通火腑，便通浊行。病机为肝风震动、火腑不通，主大便不通、里燥。", []], "1234": ["病机", "脉见弦大，非脏阴病象。脾宜升健，胃宜降和，今能食不运，大便窒塞，嗳气频频，痔疮肠红，全是胃气不降，肠中不通，腑失传导。弦大主胃腑阳病，独大独小为病脉，故六腑以通为补，病机在胃气不降。", ["弦", "大"]], "1235": ["病机", "脉左微弱右弦，左微弱为阳气衰微，右弦为浊阴上攻。口甜夜胀，食粥不化，早食晚吐，火土不生，不司腐熟。浊阴凝痞，成氏称阴结，肠间屈曲隐处旋转机关不利，风动则鸣。病机为阳微浊阴上逆，主反胃脘痛、胀满。", ["微", "弱", "弦"]], "1236": ["病机", "阳明脉大，环跳尻骨筋掣痛，痛甚足筋皆缩，大便燥艰常秘。老年血枯，内燥风生，春升上僭，下失滋养。肝风木横，胃土必衰，阳明诸脉不主束筋骨、流利机关。脉大主阳明燥热，病机为血枯内燥生风。", ["大"]], "1237": ["病机", "面白脉小，高年下焦阴弱，六腑之气不利，多痛不得大便，乃幽门之病。脉小为阴血不足，不可峻攻，故拟五仁润燥以代通幽。病机为下焦阴弱、肠燥便闭，主大便不得、腹痛。", ["小"]], "1238": ["病机", "脉小弱，形瘦，肠风已久，食少便难，得嗳噫泄气自觉爽释。小弱为气血不足，肠风日久伤阴，六腑通即为补，仿东垣通幽意。病机为气血两虚、肠燥便难，主形瘦食少、便难。", ["小", "弱"]], "1239": ["病机", "脉得左部弦实，汤饮下咽嗳噫不已，不饥不食，大便干坚若弹丸。胃逆为病，加嗔怒肝木贯膈犯胃，左弦实为血郁血结之象，平昔常似有形骨梗。病机为肝木犯胃、血结郁滞，主嗳噫、便坚。", ["弦", "实"]], "1240": ["主病", "左脉弦数，弦主肝郁气滞，数主热，合之则肝经郁热。溺短而痛，为热结小肠、膀胱，气化不利。导赤散加丹皮赤苓，清心利水，凉血导热，正合脉症。", ["弦", "数"]], "1241": ["病机", "脉动数，动主痛、主惊，数主热，示火腑壅结，气机不通。舌干白不欲饮，脐下攻痛，便闭溲少，皆火结小肠、传导失职。更衣丸通火腑之壅结，通则不痛。", ["动", "数"]], "1242": ["病机", "脉左弦如刃，弦劲太过，主真阴衰、五液涸，肝失柔养，气火内亢。小溲血水点滴不爽，少腹右胁聚瘕，属癃闭，非少壮实火可比，不可泻火通利，当滋水涵木。", ["弦"]], "1243": ["病机", "脉实，主邪实内结。病久瘀热在血，胸不爽、小腹坠、二便涩少，能食不渴，为血分瘀热痹阻。苦辛宣腑未效，故用通幽法，通血络、润肠腑，以除瘀热。", ["实"]], "1244": ["病机", "脉搏劲，劲主气逆、主郁，舌干赤，嗳气不展如呃忒，缘频吐胃伤，诸经之气上逆，填胸聚脘，周行脉痹，肌肉著席痛转加。先议治肺，以肺主一身之气化，降气通痹。", ["劲"]], "1245": ["病机", "脉小涩，小主气虚，涩主血滞。失血呕逆后，脘痞纳胀，便闭溲赤，此怒劳致气分逆乱，肺痹不降。从肺痹主治，宣降肺气，气行则血行，腑气自通。", ["小", "涩"]], "1246": ["治法", "此段论肺痹治法，未出脉象。肺为娇脏，主清肃下降，六淫著之则痹塞不通。因风、寒、湿、燥、温热分别用药，总取轻浮微辛，开气宣痹，不用重浊，以复肺之降令。", []], "1247": ["病机", "脉弦，主肝气郁滞、清阳失旷。胸脘痹痛欲呕，便结，为气机不降，胃失和降。久延怕成噎格，当理气降逆、通阳开痹，防其膈塞。", ["弦"]], "1248": ["病机", "脉沉如伏，是气机郁闭于里、壅塞不通之象。原文言\"痞胀格拒，在脘膈上部\"，病人自觉气壅、左侧觉热，说明木郁化火、郁结于上焦脘膈。脉沉伏正反映邪郁深伏、气不宣达，故治以\"木郁达之，火郁发之\"，因势利导，病位在上者宜吐，使郁开气畅则脉自起。", ["沉", "伏"]], "1249": ["病机", "脉弦主饮、主气机不利。原文述\"色鲜明，吞酸胸痹，大便不爽\"，断为\"痰饮凝冱，清阳失旷，气机不利\"。饮邪凝滞，阻遏胸阳，脉道拘急故弦；清阳不布则胸痹，饮停犯胃则吞酸，气滞于肠则便不爽。法当温通阳气，阳运则饮化弦缓。", ["弦"]], "1250": ["病机", "脉沉主里、主寒湿内郁。原文见\"短气咳甚，呕吐饮食，便溏泻\"，断为\"寒湿郁痹，胸痹如閟，清阳少旋\"。寒湿之邪郁闭于里，阳气不运，故脉沉；上则胸阳不展而咳逆短气，中则胃气上逆而呕吐，下则脾失健运而便溏。用小半夏汤加姜汁温化寒湿，湿去阳通则脉起。", ["沉"]], "1251": ["病机", "原文引《金匮》\"寸口脉沉而迟，阳微阴弦\"，以明胸痹病机。脉沉迟为胸中阳虚、阳气不运，阴弦为阴寒内盛、上乘阳位。故断言胸痹\"但有寒症，而无热症\"，与胸痞之寒热错杂、燥涩虚痞迥异。治惟辛滑温通，流运上焦清阳，不可与痞结痰食混治。", ["沉", "迟", "弦"]], "1252": ["病机", "脉左大右平，左候肝、主饮邪，右候肺脾。左脉独大，是肝气偏亢、伏饮内动之象；右平说明新感外邪尚未深陷。原文\"当暴凉而发\"，乃新邪引动宿饮，内外相引故哮喘发作。以小青龙法逐伏邪饮气，外解寒邪、内蠲水饮，饮去则左脉之大气自平。", ["大"]], "1253": ["病机", "本段未出脉名，纯以症候推病机。原文述\"先寒后热，不饥不食，继浮肿喘呛，俯不能仰\"，断为\"气分郁结，水道阻塞，肺气不降，二肠交阻\"。水谷蒸腐之湿横趋脉络，故肿渐加。先喘后胀治肺、先胀后喘治脾，此属肺郁水气不降，病在气分，非乱医可效。", []], "1254": ["病机", "脉弦坚，是肝气刚劲太过之象。原文\"动怒气冲，喘急不得卧息\"，断为\"肝升太过，肺降失职\"。怒动肝阳，升发无制，挟饮上逆，肺金不能肃降，故喘急难卧；阳郁不达四末则两足逆冷，入暮阳衰阴盛故剧。用越婢法宣肺泄热、降逆平冲，使肝升有制、肺降复职。", ["弦", "坚"]], "1255": ["病机", "本段未出脉名，以\"细诊色脉\"言上实下虚。原文述色痿腠疏、阳虚体质，厚味蒸痰致频年咳嗽；医用皂荚搜攒，反伤肺气致喷涕不已，胶浊仍踞胸背。喘病因在肺为实、在肾为虚，此上实下虚，耳聋鸣响。治下壮水源以熄内风，卧时兼清上焦浊痰，通补阳明以阖太阳之开。", []], "1256": ["病机", "脉沉主里，此案年高下元已虚，肾气失于收摄，故脉沉；痰饮随地气上升，致短气、身动即喘。沉脉在此反映肾虚不纳、痰饮内动之病机，非表证之沉。有年而见陡然中厥之虑，正因下元虚衰、气机升降失司。", ["沉"]], "1257": ["病机", "脉细尺垂，细为阴弱，尺垂主下元不固；形瘦食少、动则气促喘急，乃阴弱失纳、吸气入而为喘。原文明言“肾病何辞”，指出病机在肾不纳气，非肺病客感。治法收摄固真、上病实下，宗肾气方法，正合尺垂所主下虚之机。", ["细", "垂"]], "1258": ["病机", "脉大而动搏，大非实热，乃元气浮越之象；动搏为阳不潜藏。形枯汗泄、吸音颇促、神衰呓语，皆元海根微、不司藏纳所致。阳从汗出，最虑昏脱。原文谓“阳根于阴”，虽温邪扰攘，仍须摄固下真以治根本，脉大动搏正是虚阳外越之征。", ["大", "动", "搏"]], "1259": ["预后", "脉微弱为阳气衰微之象，面亮戴阳、呃逆胁痛、自利，乃阳虚浊阴上逆、欲脱之候。高年劳烦伤阳，三焦俱病，脉微弱正应阳气欲尽。原文断为“欲脱之象”，议从中治，以温阳驱阴为急，脉症合参示预后险重。", ["微", "弱"]], "1260": ["病机", "两脉微涩，微为阳气衰微，涩为阴血滞涩；呕吐发呃下利，乃阳气欲尽、浊阴冲逆。前医杂入耆归呆钝、代赭重坠及表药，反致牵掣不解。脉微涩紧扣“阳气欲尽”之机，故舍理阳驱阴无别法，示病机危笃。", ["微", "涩"]], "1261": ["病机", "脉歇止为结代之类，主胃中虚冷、阴浊上干；汗出呃逆、大便溏，乃劳倦积伤、阳气不运。歇止脉反映中焦虚寒、气血运行不畅，阴浊乘虚上逆而为呃。原文以“胃中虚冷”点明病机，脉症相应，非单纯气滞。", ["歇止"]], "1262": ["病机", "脉小舌白，小为阳气不足，白为寒象；气逆呃忒、畏寒微战，乃胃阳虚而肝木上犯。脉小应胃阳式微，不能镇纳肝木，故气逆为呃。原文议镇肝安胃理阳，正合脉小所主阳虚肝逆之病机，非实热呃逆。", ["小"]], "1263": ["其他", "此段专论呃逆症治，未出具体脉象，故脉象要素为空。原文溯内经“哕”名，列胃中虚冷、胃虚虚阳上逆、中焦虚寒、下焦虚寒阳竭、食滞等因，分用橘皮汤、橘皮竹茹汤、理中加丁香、归气饮等，属呃逆辨证治法总论，非单论脉。", []], "1264": ["病机", "脉虚涩，虚为阳气不足，涩为血少气滞。饮酒发黄本属湿热，然病后形瘦、行动不耐，显系阳气渐薄，兼思虑劳烦致损，脾胃两伤。湿热未清而正气已虚，故脉不任按而涩滞不畅，腹鸣不和亦中阳不振之象，治当两和脾胃，不可纯清湿热。", ["虚", "涩"]], "1265": ["病机", "脉沉主里，湿热郁蒸于里故发黄。中痞恶心、便结溺赤，皆三焦气机壅滞、湿热内结之征。沉脉说明病不在表而在里，湿热胶结，非苦辛寒不能开泄。三焦病者，上中下气化皆阻，故以苦辛寒主之，清里热、化湿浊、通三焦。", ["沉"]], "1266": ["病机", "原文未识脉名，然心下痛年余屡发、痛缓能食，渐目黄溺赤，乃络脉凝瘀蕴热，与水谷之气交蒸所致。瘀热在络，非攻下可急，攻之过急必变胀满，温燥亦须忌。此示络瘀湿热之病机，治用金铃子散合金铃子、谷芽、枳实、小柴胡法，行络中瘀热。", []], "1267": ["病机", "脉弦胁痛，弦主肝胆，胁痛为肝胆气郁之征。此段论黄疸湿得之，分阴阳在腑在脏：阳黄湿从火化，瘀热在里，胆热液泄，与胃浊并，身目溺俱黄如橘子色，治在胃；阴黄湿从寒水，脾阳不化，胆液受阻，色如熏黄，治在脾。脉弦正应肝胆郁热、气机不畅之机。", ["弦"]], "1268": ["病机", "脉紧主寒。此段虽论风为百病之长、能兼五气，然举隆冬裸卧犯寒、本无风气侵入为例，说明寒邪独伤而不兼风。紧脉应寒邪束表、卫阳被遏之机。风性本寒，巽卦初爻属阴，故风能兼寒而寒不兼风，辨脉紧可知寒邪为病之因。", ["紧"]], "1269": ["病机", "原文未识脉名。太阳脉行由背抵腰，外来风寒先伤阳经，经气上逆则呕痰涎、头痛，小溲数行则病解，是膀胱气通、逆者转顺之象。此段明寒客太阳、经气上逆之病机，治当通太阳之里，用五苓散化气利水，使经气顺降。", []], "1270": ["病机", "寸口脉独大，大主热盛。风温上受，肺受热灼，故寸口独大而声出不扬。肺位最高，温邪先犯，热灼肺金则音哑，脉独大者邪聚上焦、肺热壅盛之征。治以辛凉清上，薄味调养，使肺热得清，声自扬矣。", ["大"]], "1271": ["病机", "脉左实大，实主邪盛，大主热。左脉候肝胆，风温仍在上焦，清窍被蒙，故头目如蒙、不爽。实大之脉说明温邪壅盛于上，肝胆之火上扰清窍，气机升降失司。拟升降法，使上焦风温得清，清窍自利。", ["实", "大"]], "1272": ["病机", "原文未出脉名，仅述风温热灼之后津液未复、阳明脉络不旺，故骨酸背楚。此非脉象所主，乃温热耗津、阳明失养之病机，治以和补，示津亏络虚当缓调，与脉诊无直接对应。", []], "1273": ["病机", "此段未出脉象，专论风温两阳熏灼先伤上焦，手三阴为病薮，头胀汗出身热咳嗽并见。主旨阐明温邪化热伤津、太阴失肃之病机，忌辛温劫津、苦寒损胃，救逆用甘药，骤变痉厥、缓变虚劳，皆由津伤络损而来。", []], "1274": ["主病", "脉数主热，暮热示邪入阴分或热盛于里；头痛腰疼、口燥并见，为温邪入肺、热灼津伤之候。数脉应温邪化热，热盛则脉行急迫，故以脉数暮热定其属温邪，非虚寒可比。", ["数"]], "1275": ["兼症", "原文仅言右脉未和，未出具体脉名，故脉象要素为空。右脉未和提示气分热邪未清、肺胃痰热互结，故热多口渴；若再劫胃汁则脘痞不饥。主旨以脉不和参合症候，辨清热生津佐理痰之兼症处理。", []], "1276": ["病机", "脉数主气分热邪未去，舌紫渴饮示热渐入血分。引仲景阴气先伤、阳气独发之论，说明瘅热消灼肌肉由热盛津伤所致。数脉为热邪鸱张之征，故甘寒清气中必佐存阴，防热入血分。", ["数"]], "1277": ["治法", "原文未出脉象，仅言营络热、心震动，用复脉汤去姜桂参加白芍。此属营热扰心、络脉失和之病机，故以复脉汤养营通络、去温药加白芍以柔肝敛阴，主旨落在治法而非脉诊。", []], "1278": ["病机", "脉数主热，舌赤耳聋胸闷示痰火素盛、冬温引动宿病，加以劳复，热邪弥漫上焦、小溲不利。数脉应痰火与温邪相合，热扰胞络，故议治胞络之热，清化痰火以解弥漫之邪。", ["数"]], "1279": ["病机", "引平脉篇清邪中上之旨，说明温邪从鼻入肺、逆传心胞，气血交阻、清窍蒙蔽，故神明欲迷。平脉非言今病之脉，乃借古训明邪从上受、逐秽利窍当用芳香，非豁痰降火所能解。", ["平"]], "1280": ["病机", "左脉弦且坚，弦为风木之象，坚则阴血内亏、络脉失柔。饮酒纳谷而见偏中于右，是内风消烁、阳气弛张，春升之令引动伏温，故肌腠隐约斑点、面赤舌灰黄。弦坚非外风，乃肝阳化风夹伏温内闭，故怕神昏，治当清络宣窍，不可攻风劫痰。", ["弦", "坚"]], "1281": ["病机", "脉数左盛，数主热，左盛属阴分血分受热。夜热早凉、热退无汗，是热从阴分而来，伏于血分而不能外透；能食形瘦，邪热内耗营阴。两月不解，热陷血分已深，故治在血分，非表散所能解。", ["数"]], "1282": ["病机", "原文未出脉名，以舌绛裂纹、面色枯槁、心中热焚辨之。邪深竟入厥阴，正气虚极，热灼阴液而舌裂无泽；形象畏冷是阳衰于外，热焚是邪陷于内，属邪少虚多。故勉拟复脉汤扶正，去人参生姜加甘蔗汁，取甘润救阴之意。", []], "1283": ["误治", "原文未出脉名，述热病误投表散消导，正气受伤而神昏舌强，势如燎原。前用复脉法略见转机，知邪少虚多，当遵前方去桂加参，以扶正气为主。此段重在纠误治伤正之弊，非以脉断病。", []], "1284": ["病机", "脉数右大，数主温邪化热，右大属气分热盛。烦渴舌绛，是热灼气营，气血两伤。温邪入里，气分热炽而营阴亦耗，故用玉女煎两清气营、救阴泄热，非单纯气分或血分证。", ["数", "大"]], "1285": ["病机", "原文未出脉名，言关阴虚挟温邪，寒热不止。阴虚则正气不足，温邪留恋则寒热不解；既不宜发散消食以伤正，徒补又碍邪，故拟复脉汤法，寓扶阴托邪之意，属邪少虚多之候。", []], "1286": ["病机", "原文未出脉名，以色脉参视立论。体虚而温邪内伏，头汗淋漓、上热下冷、舌白烦渴、心腹窒塞，是春阳升举引动冬令少藏之邪，阳气浮越于上、阴寒凝滞于下。色脉合参，虚实夹杂，故当谨慎，不可径投表散。", []], "1287": ["病机", "原文未出脉名，述劳倦内伤复受温邪，两月不愈。心中温温液液、夜卧喉干，是津液无以上供，阴液亏耗而邪热未清。劳倦伤中、温邪耗阴，故用复脉汤去姜桂参，先滋液和阳，三服后再加参以扶正。", []], "1288": ["病机", "原文未识脉名，但述劳倦更感温邪，阳升头痛、寒热战栗、冷汗，邪虽外达而阳气亦泄，致神倦欲眠、舌赤黄胎、口不知味。此乃劳倦伤阳，温邪内侵，阳气外泄，阴液被灼，故以育阴除热为主，辛散苦降非宜，用复脉汤加减。", []], "1289": ["病机", "脉促数，舌白不饥，寒热汗出，初起腹痛脐右有形，乃久伤劳倦复感温邪。病两旬又六，微咳有痰，不渴饮，寒来微微齿痉，此营卫二气大衰，恐延虚脱。促数脉示邪热未清而正气已衰，故议固卫阳以平寒热。", ["促", "数"]], "1290": ["病机", "脉右搏数左小，腹满已久，面颔肿胀，牙关紧闭，先寒热随现是象。乃温邪触自口鼻，上焦先受，气血与热胶固，致清窍不利，倏有痹塞之变。右搏数主热毒壅结上焦，左小示邪未深入，故先治新邪，辛凉轻剂宣通。", ["数"]], "1291": ["病机", "脉左数右缓弱，阳根未固，阴液渐涸，舌赤微渴，喘促自利溲数，晡刻自热，神烦呓语。温邪久伏少阴，阴分有伏邪而真阳不肯收纳。左数主阴虚热伏，右缓弱示阳根不固，故仿河间浊药轻投，育阴祛热，使下焦根蒂自立。", ["数", "缓", "弱"]], "1292": ["病机", "脉左数右软，舌干苔白，小溲淋沥，吸气喘促，烦汗。肾阴不承，心神热灼蒙闭。左数主肾阴亏而热扰，右软示气分不足。故以三才汤滋水制热，加茯神黄柏金箔，晚进牛黄清心丸以清心开闭。", ["数", "软"]], "1293": ["病机", "昨诊左手数疾顿减，尺中垂而仍动，呓语妄见，肾热乘心，膻中微闭，神明为蒙。服牛黄丸后辰刻脉濡小，形质大衰，舌边色淡，下利稀水。濡小示阴伤气衰，数疾减而虚邪未净，关闸欲撒，故用桃花汤堵塞阳明以救阴。", ["濡", "小", "数", "疾"]], "1294": ["病机", "脉左沉数右小数，暮热微汗时烦，辰刻神清。沉数主虚邪仍留阴分，小示阴分不足。暮热微汗乃阴虚内热之象，神清则邪未入营。故议用清补，清其余热，补其阴分，使虚邪渐解。", ["沉", "数", "小"]], "1295": ["病机", "原文未识脉名，述温热病已伤少阴之阴，少壮阴未易复，夏令发泄，百益酒辛热劫阴泄气，致形体颓然。又论冬伤于寒春必病温，重在冬不藏精，阴精久耗，木火内燃，强阳无制，燔燎之势从里发，故主治以存津液为第一，黄芩汤坚阴却邪。", []], "1296": ["病机", "左脉劲主暑邪内郁，肝阳偏亢；右濡主太阴湿滞。暑湿蒙闭清空，故头痛脘闷、麻痹欲厥、舌白。脉劲为邪实，濡为湿阻，合示暑湿内中、清阳不展，将成疟象。平昔阴虚，故勿犯中下二焦，防劫阴也。", ["劲", "濡"]], "1297": ["病机", "脉寸大，寸候上焦，大主热盛。暑热气从上受，故头晕、脘中食不多下。寸大示上焦气分热壅，非虚大也。治以苦辛寒，清上焦暑热，使气机得降，食自下矣。", ["大"]], "1298": ["病机", "脉神颇安，非无脉也，乃脉象渐和。病起湿热，无汗则肌腠气窒，疹发而邪未尽泄。肌无膏泽、瘦削枯槁，示阴液不充。脉神安而症见枯槁，知邪退正伤，当淡薄调理，防痰热复聚，不可腥膻浊味助热。", []], "1299": ["病机", "右脉小数主热在里，左脉涩弱主阴血亏耗。暑湿热内郁，新凉引动伏邪，医误发散消食寒凉，致胃汁消亡、真阴尽烁。舌赤齿燥血，邪留营中，有内闭瘛疭厥逆之变。脉数涩弱，示热固在里而阴伤日久，下之再犯亡阴，故宜轻清清解。", ["数", "涩", "弱"]], "1300": ["病机", "右脉缓大，左弱，面垢减而痰嗽不爽。缓大非实，乃辛散温燥伤胃津，热焰蒸迫心营肺卫，致神呆喘急耳聋、清阳阻痹。脉缓大示胃阴伤而气机弛纵，左弱示营血不足。今获效，当清养胃阴肺气，兼参体质。", ["缓", "大", "弱"]], "1301": ["病机", "脉虚而右大左小，右大主气分暑热壅闭，左小主营血不足。身热自汗、腹痛、大小便不利，暑热内闭，表里气机不通。脉虚示正气已伤，不可峻攻，拟和表里法，调其气机。", ["虚", "大", "小"]], "1302": ["病机", "脉虚而舌赤消渴，伏暑热气过卫入营。虚脉示暑热伤气，营阴受灼，故舌赤消渴。邪已入营，治在手厥阴，清营透热，不可再汗。", ["虚"]], "1303": ["病机", "右脉小弱，暑伤气分，脉必芤虚。小弱示气分不足，芤虚示暑热伤津。烦渴喜冷饮，里热炽盛，非结胸实症。脉虚芤，故宜辛寒彻里邪，不可攻下。", ["小", "弱", "芤", "虚"]], "1304": ["病机", "脉小色白，示气分不足，胃弱少食。气弱则脉道不充，故小；色白为气馁之征。胃弱受纳无权，故少食。阴柔之药妨胃助浊，故以猪肚丸养胃，生脉四君子汤补气，杜夏季客暑之侵。", ["小"]], "1305": ["病机", "烦劳伤阳，长夏发泄令加，症见气弱、烦渴有痰，皆热伤气也。阳明经脉主束筋骨流利机关，胃虚则机关不利。治先其胃，用金匮麦门冬汤养胃生津。", []], "1306": ["病机", "脉肝胆独大，尺中动数，先天素弱水亏，木少滋荣。春深长夏气机泄越，热伤元气，故烦倦食减。进甘酸充养胃阴，俟秋肃培植下焦固纳。", ["大", "动", "数"]], "1307": ["预后", "热止汗出，伏暑已解，但病魔日久，平素积劳，形色脉象虚衰，深虑变病。饮食未进，寤寐未宁，议敛液补虚，防其虚脱。", ["虚"]], "1308": ["病机", "右脉空大左脉小芤，寒热麻痹，腰痛冷汗，平素积劳内虚，秋暑客邪干脏阴，致神迷心热烦躁。空大芤小示阴分亏虚，热深劫阴，虑痉厥。议清阴分之邪，养正辅之。", ["空", "大", "小", "芤"]], "1309": ["主病", "诊脉弦，午后恶寒似热，不饥，溺涩短赤。暑热炎蒸外袭肺卫，游行三焦，气分窒痹，故脉弦。当用和法，薄滋味杜疟患。", ["弦"]], "1310": ["病机", "下午进药后诊脉较大于早晨，神识如前，舌赤中心干燥，身热甚于早间，此阴分亦被热气蒸伤。瘦人虑液涸，痰咯不清，养阴腻滞，议清膈及紫雪丹芳香宣窍逐秽。", ["大"]], "1311": ["预后", "脉形小数，小为病退，数为余热，故皮腠麸蜕，思食欲餐，皆佳兆。但舌赤中心黄苔，热蒸既久，胃津阴液俱伤，咽物若阻，溺溲尿管犹痛，咯痰浓厚，宿垢未下。存阴为主，清腑兼之，忌食复劳复。", ["小", "数"]], "1312": ["治法", "原文未载脉象，仅言“脉症如昨”，示病机未变。前诊当为阴分余热未清、上脘热痰内蕴，故仍议滋清阴分余热、佐清上脘热痰。脉症同前，说明热痰未化、阴伤未复，治从原法增损，非另立新方。", []], "1313": ["主病", "脉虚为正气不足之象。伤暑而见头重脘闷、跗酸，乃暑湿伤气，清阳不升则头重，湿阻中焦则脘闷，湿流下焦则跗酸。脉虚正合暑伤气分之病机，虚中夹湿，故见症如此。", ["虚"]], "1314": ["病机", "原文未出脉象，专论暑湿相合之病机。谓“暑病必挟湿”，因天暑动而地湿腾，人处蒸淫之中，正气有隙则邪从口鼻吸受，先阻气分，上焦清肃不行，水谷精微蕴结为湿。此段阐发暑湿成因及传变，非以脉断病。", []], "1315": ["病机", "脉来小弱而缓，小弱为阳气不足，缓为湿邪凝滞。体壮有湿，长夏阴雨，湿著经络则身痛，湿困中焦则自利发热。湿邪凝遏阳气，故脉小弱而缓；湿中热气横冲心胞，致神昏肢冷，病名湿温，非伤寒同法。", ["小", "弱", "缓"]], "1316": ["病机", "原文未载脉象，但言“色脉非是有余”，可知脉不洪数实大，而现不足之象。身体稍稍转动、语謇神呆，是气机未为灵转；湿为阴邪，不徒偏寒偏热，故色脉无有余之征，病机重在湿阻气机、神机不运。", []], "1317": ["主病", "脉小涩，小为气虚，涩为湿滞血少。痰多上涌、食入脘阻、大便不爽，皆湿伤气痹、痰湿内阻之象。曾病黄疸，饥饱失和，湿伤气分，气机痹阻，故脉小涩，主以湿伤气痹。", ["小", "涩"]], "1318": ["病机", "脉象呆钝，非指具体脉形，而言脉来不灵利，为湿郁气机之征。舌白目黄、口渴溺赤，湿热郁蒸，故脉呆钝。湿郁则气机不畅，脉道不利，此属湿郁为病，非虚非寒。", []], "1319": ["误治", "原文未出脉象，述酒客中虚、粤地潮湿、长夏涉水，外湿下起，内湿中聚。治法不先宣通经腑，致湿阻气分，郁而为热，水湿横渍脉腠，二便不爽，湿热浊气交扭。又乱药多进，脾胃受伤于药，腿肢肿痛，清阳先伤，汤药难进，故议小温中丸疏利肠中。", []], "1320": ["病机", "脉右缓，右脉候气，缓主湿邪。湿性黏滞，易阻气机，故曰“湿著阻气”。此脉缓非平和之缓，乃湿邪困阻、气机不畅之象，主湿阻气分，症见身重、脘闷等。", ["缓"]], "1321": ["病机", "脉濡为湿邪伤表、阳气被遏之象。湿阻气分，清阳不升则头胀，湿性重着则胸身重著而痛，营卫不和则寒热，湿浊犯胃则微呕。脉濡与诸症合参，主湿阻气分。", ["濡"]], "1322": ["病机", "脉缓主湿，身痛汗出热解而复热，乃水谷之气不运，湿复阻气，郁而成病。湿性黏滞，故热自湿中来，徒进清热不应。脉缓紧扣湿阻气分、气机不宣之病机。", ["缓"]], "1323": ["病机", "脉迟小涩，迟为阳伤，小涩为气血不足。形质颓然、不食不寐、腹痛便窒，皆少谷中虚、湿结阳伤，寒湿浊阴鸠聚为痛之征。脉象与嗜酒中虚、湿浊内结病机相应。", ["迟", "小", "涩"]], "1324": ["病机", "脉缓主湿，脐上痛、腹微膨、便稀、溺短不爽，乃湿郁脾胃之阳，致气滞里急。脉缓与湿郁气滞之症相符，故宗古人导湿分消，用桂苓散方。", ["缓"]], "1325": ["病机", "脉象模糊，湿邪弥漫、气机壅滞之象。脘闷、便溏、身痛，皆湿蕴三焦、气化不利所致。脉模糊与湿浊弥漫之病机相合，主湿蕴三焦。", []], "1326": ["预后", "诊脉微，阳气已败，湿壅生热至胃痈脓。脉微为阳气衰微之候，清热则阳亡即死，故以术苓运中祛湿、佐附迅走气分。此段重在凭脉判断阳气败绝之预后。", ["微"]], "1327": ["病机", "脉长而数，长为有余，数为热，显系厥阴阳明湿热内蕴。疟痢后肝虚，左胁痞块、腹中礧坚、汨汨有声、寒热嘈杂吞酸，皆肝胃湿热错杂之症。脉长数主湿热下渗前阴，阳缩为湿热症。", ["长", "数"]], "1328": ["病机", "脉弦沉，弦主气机郁滞、痛证，沉主里主湿。原文述胸膈迷漫、胃痛呕食、肢节屈曲处冷痛、经落后、痛即便溏，皆湿郁阻闭、气血不行之象。湿性黏滞沉伏，阻遏气机则脉沉；气血被郁、经脉拘急则脉弦。弦沉并见，正合湿郁内阻、气血不得宣通之病机，故先须断酒以除湿源。", ["弦", "沉"]], "1329": ["病机", "原文未出脉名，然明言「湿郁在脉为痛」「湿家本有汗不解」。汗多身痛、自利、小溲全无、胸腹白疹，皆风湿伤于气分、湿郁经脉之候。医误用血分凉药，反使湿邪凝滞不解。湿郁于脉则气血痹阻而痛，湿困气分则三焦不利、小便不通，故以气分湿郁立论。", []], "1330": ["病机", "脉右数大，右脉候气，数主热，大主邪盛。原文径言「议清气分中燥热」，可知数大为气分燥热炽盛之象。热盛于气分则脉数，邪热鼓动气血则脉大，且见于右部，正合气分受病。故本段以脉象定病位在气分、病性属燥热，主清气分燥热之治法。", ["数", "大"]], "1331": ["病机", "脉数虚，数主热，虚主不足。原文见舌红口渴、上腭干涸、腹热不饥、心下温温液液，明言「津液被劫，阴不上承」。热劫阴液则脉数，阴津亏虚则脉虚，数而虚正是热盛伤阴、阴液不能上承之征。故用炙甘草汤滋阴复脉，以救被劫之津液。", ["数", "虚"]], "1332": ["病机", "原文未出脉名，述心中烦热、正值经来而热渴不已，并斥「清肺气大谬」，主张用复脉法。经行之际阴血下泄，热扰心神则烦热，阴液耗伤则热渴不已。病机在阴血亏虚、虚热内扰，非肺气实热，故清肺气为误，当以复脉滋养阴血、和营清热为治。", []], "1333": ["病机", "原文言「形脉俱虚，难投白虎」，又谓「左关尺空数不藏」。虚为阴阳津液重伤，数为余热淹留，空为阴不藏守。临晚潮热、舌色若赭、频饮不解渴，皆邪少虚多、少阴厥阴之阴亏耗之象。脉虚数而空，故不可用白虎峻清，议复脉法使二脏之阴少苏、胃关复振。", ["虚", "数", "空"]], "1334": ["病机", "两脉数搏，数主热盛，搏指脉来有力急迫，主邪热鸱张。原文述伏气热蕴三焦、心凛热发、烦渴、遍体赤癍、夜躁不寐，皆伏热内蕴三焦、热毒外发营分之候。热蕴于里鼓动血脉则数而搏指，热扰心神则夜躁不寐，热毒外溢肌肤则发赤癍，故脉数搏主三焦伏热之病机。", ["数", "搏"]], "1335": ["预后", "原文未出脉名，专论癍之形色以决预后：鲜红起发者为吉，紫成片为重，黑为凶，青为不治，明言「有诸内而形诸外，可决其脏腑之安危，邪正之胜负」。癍由伤寒瘟疫失于宣解、邪蕴胃腑走入营中所致，故察癍色之荣枯可判邪正胜负，本段主旨正在预后吉凶之判断。", []], "1336": ["病机", "两关脉弦长，关候肝胃，弦为肝旺，长为阳热有余，故断为“五火燔燎”，肝阳胃阳尤甚。动怒抽掣属肝病，食辛香厚味即病至属胃病，皆由痰火根深使然。脉象反映肝胃火盛、痰火内蕴之病机，故治法主张静养薄味，渐加药力。", ["弦", "长"]], "1337": ["病机", "右关脉弦滑，关主中焦，弦为肝旺，滑主痰涎。痰火上蒙，津液不得上承，故舌干微强、语言似謇。高年虑风痱，正是痰火内扰、窍络不利之象。脉象揭示痰火为患，故宜清上宣通，忌刚燥腻滞。", ["弦", "滑"]], "1338": ["病机", "左脉弦坚搏，弦为肝郁，坚搏示郁结之甚。郁虑已甚，肝木横逆，侮克脾胃，故痰多、食不易运。脉象反映肝郁气结、木侮中土之病机，有年之人最宜开怀，以防延及噎膈。", ["弦", "坚"]], "1339": ["其他", "原文未识出脉名，仅言“脉如前”，承前案脉象而未另立脉形。所述“痰气未降”，指前证痰气仍壅滞不降，故于前方去杏仁加白芥子，以增豁痰降气之力。此段重在据脉症调整治法，非专论脉象主病。", []], "1340": ["病机", "脉沉弦，沉主里、主湿，弦主气机不畅。久寓南土，水谷之湿蒸热聚痰，湿热盛则目黄、肢末易疮，气隧不得流畅。脉象反映湿热内蕴、痰阻气滞之病机，故法当苦辛寒清里通肌，以清热为要。", ["沉", "弦"]], "1341": ["病机", "原文未识出具体脉名，仅言“脉胀”，当指脉象反映胀满之候。湿阻热痰，壅遏气机，故见胀。此段点明湿、热、痰三者交阻为病机核心，脉胀正是气机壅滞之外候，主病在湿热痰浊内阻。", []], "1342": ["病机", "原文未识出脉名，以“阳明脉衰”言病机。阳动内风，木火犯中，中土受侮，故痰多、经脉不利。夏季脾胃主司，肝胆火风易贯膈犯中。此段论木火犯胃、胃虚生痰之病机，主张清少阳郁热，使中宫自安，忌畏虚滋腻。", []], "1343": ["病机", "左脉浮弦数，浮为阳浮，弦为少阳木旺，数为火升。痰多、脘中不爽，烦则火升眩晕，静坐神识安舒，皆少阳阳明郁火挟痰上扰之象。脉象反映少阳阳明同病、痰火内扰之病机，故议少阳阳明同治。", ["浮", "弦", "数"]], "1344": ["病机", "原文“脉两手已和”指脉象已恢复平和，但“烦动恍惚欲晕”说明阴血不足、虚阳上扰，神失所养。脉和而症未平，故议用静药益阴和阳，以潜镇浮阳、滋养阴血，使阴阳重归和谐。", []], "1345": ["病机", "脉左小不静，右部弦滑。左小为肝肾精血不足，不静为虚阳扰动；右弦滑主肺胃痰热。色鲜明属上有痰饮，上实下虚。故法当清肺胃热痰、益肾肝精血，标本兼顾。", ["小", "弦", "滑"]], "1346": ["病机", "脉浮主表，亦主阳气浮越。患者下元虚衰，冲阳升而痰饮泛，咳聋痰音、胁痛气冲。骤冷恐外寒引动内饮，脉浮提示饮邪有外达之势，故议开太阳以肃上，外解寒邪、内化饮浊。", ["浮"]], "1347": ["病机", "脉右大弦，右主肺卫，大弦为饮邪壅盛、气机逆乱。气喘咳唾浊沫、不能著枕、喜饮汤水、遇寒病发，皆饮邪留于肺卫、肺气不降之征。若误投清润，则饮愈壅而病剧。", ["大", "弦"]], "1348": ["病机", "脉沉属饮，沉主里、主水。冬温阳不潜伏，伏饮上泛乘肺，肺气不降，故咳甚不得卧、卧则喘甚。面色鲜明为饮。高年下焦根蒂已虚，饮邪上扰，络血上沸。治当开太阳使饮浊下趋，用小青龙越婢合法。", ["沉"]], "1349": ["病机", "脉沉而微，微则阳气不足，沉乃寒水阴凝。阳衰不主运行，痰饮聚气欲阻，故心痛怔忡、渐及两胁下坠。痛来如心震、波撼岳阳，皆阳微饮逆之象。议用外台茯苓饮合桂苓方，温阳化饮。", ["沉", "微"]], "1350": ["病机", "脉沉小弦，沉主里、小主虚、弦主饮。阴浊饮邪内结，禀质阳不充旺，胸中清气不得舒展，偶触寒冷或误进寒物则饮邪暴冷凝结胸痞。故忌酒肉腥浊，常服苓桂术甘汤温阳化饮，病来因冷即服大顺散。", ["沉", "小", "弦"]], "1351": ["病机", "病去神爽，但本脉带弦，弦为饮邪未净、阳气不足之象。平素有饮，阳不充旺，年纪渐多，防有风痹。故宜少酒肉、戒劳怒，议外台茯苓饮方健脾化饮，以杜饮邪复聚。", ["弦"]], "1352": ["病机", "脉空为阳伤之象。烦劳太过耗伤阳气，卫阳失护则毛发自坠，阳跷脉空则寤不成寐；阳虚不能运化，痰饮日聚。此脉空非血虚，乃阳气日就其衰之征，故主阳伤痰饮、卫外不固之病机。", ["空"]], "1353": ["病机", "脉弦主饮邪内结、阳气不通。背中冷、左偏微痛、食少欲呕、四肢牵强，皆饮邪阻遏阳气、经脉失于温煦所致。弦为阴脉，饮为阴邪，脉弦与饮结阳郁相应，故议通阳气以化饮。", ["弦"]], "1354": ["病机", "右弦左弱，弦主痰饮上泛，弱主中气不足。眩晕恶心、胸脘不爽为痰饮上逆；面色红亮乃虚阳上浮之象。右弦左弱示痰饮内盛而正气已虚，有厥中之事，故主痰饮上泛、本虚标实之病机。", ["弦", "弱"]], "1355": ["病机", "脉沉为痰饮内停之征，沉主里、主水。原文直言「脉沉为痰饮」，因阳气不足，浊阴欲蔽，饮邪留著于里故脉沉。治当理脾为先，俾中阳默运，即仲景外饮治脾之意，故本段主阳气不足、浊阴蔽阻之病机。", ["沉"]], "1356": ["病机", "脉沉主里、主阳虚水停。背寒、心悸如坠为阳气式微、饮浊内聚之候；形盛气衰示外强中干。沉脉与痰饮内聚、脾肾阳虚相应，故当温通补阳，阳复则饮浊自解。本段主脾肾阳虚、痰饮内聚之病机。", ["沉"]], "1357": ["病机", "左脉沉静、右脉微弦。沉静示清阳日薄、脾运渐迟；微弦主水谷悍气蕴蒸痰饮。四旬清阳渐衰，加以烦心萦思伤脾，运化失职，饮浊内生，故脉右微弦。本段主脾阳不足、痰饮蕴蒸之病机。", ["沉", "弦"]], "1358": ["治法", "原文按脉非龙相之动搏，即脉不显相火妄动之象，故非纯用清泻。中年遗泄之患，当固下益肾、转旋运脾，分早晚服。本段以脉象排除龙相动搏，确立固下益肾、运脾化饮之治法，属治法范畴。", []], "1359": ["病机", "脉沉弦，沉主下虚，弦主饮泛。饮泛呛咳乃下虚无以制上，肾气不摄，水泛为饮。故早服肾气丸摄纳下焦，午服茯苓饮转旋中焦。沉弦与下虚饮泛相应，本段主下虚不能制上、水泛为饮之病机。", ["沉", "弦"]], "1360": ["病机", "脉弦大为阳气微漓、浊饮上泛之象。高年久嗽，阳气式微，不能运化水饮，浊阴上逆，故脉弦主饮、大主虚阳外浮。寤不成寐乃阳不入阴，饮邪上干所致。仲景‘病痰饮者，当以温药和之’，正合此虚寒饮逆之机。", ["弦", "大"]], "1361": ["病机", "脉涩小为寒热攻胃、逆气痰饮互结之候。涩主气血滞涩，小主正气不足。舌白不渴、身动呕痰、身如在舟车中，皆痰饮内停、清阳不升之象。通补阳明以复中运，白术甘草守中而湿未去，故宜缓商。", ["涩", "小"]], "1362": ["病机", "脉来沉缓，沉主里、缓主湿，合之肌肉丰溢，显系脾胃阳微、寒湿滞聚。右季胁痛、汤饮下咽汨汨有声、吐痰涎头痛，皆寒湿饮邪内阻、气机不畅之症。年壮不必介怀，治宜温中佐条达以运通阳气。", ["沉", "缓"]], "1363": ["病机", "脉沉而弦，仲景明言‘是为饮家’。沉主里、弦主饮，昔肥今瘦乃饮邪内耗。男子向老下元先亏，气不收摄，痰饮上泛，饮与气涌为咳。医者误以清肺滋阴，反助浊滞气。饮伏至阴，肾脏络病，当以温药和之，外饮治脾、内饮治肾。", ["沉", "弦"]], "1364": ["病机", "脉虚微为阳气大虚之候。春阳地升而浊阴上干，喘不得卧，乃少阴肾阳式微，不能镇纳浊阴，阴寒上逆迫肺所致。虚微之脉正合‘治在少阴’之旨，当温少阴之阳以逐阴浊。", ["虚", "微"]], "1365": ["病机", "脉弦主饮、主痛，暮夜浊阴冲逆，乃阳微不能制阴，饮邪乘阴时而动。前通阳得效，今议真武法以撤其饮，温肾阳以镇水，使阴浊不得上干，弦脉可望转和。", ["弦"]], "1366": ["病机", "脉弦右濡，弦主饮逆，右濡主阳气微弱。阳微恶寒、饮浊上干、咳吐涎沫、食减胃衰、寒疝窃踞，皆阴浊见症。喻嘉言谓浊阴上加于天，非离照当空不能退避。误用阴药则阴霾肆虐，故以熟附配生姜扫群阴、驱饮邪、维阳气。", ["弦", "濡"]], "1367": ["病机", "脉来濡弱无神，濡主湿、弱主虚，无神为阳气衰微之征。痰饮咳逆未已，前用小青龙虽暂效，交惊蛰阳气发泄病势再炽，显系肾阳不足、饮邪泛滥。谅非前法可效，宗真武汤法，熟附配生姜通阳逐饮，去白术加人参以顾护元气。", ["濡", "弱"]], "1368": ["病机", "脉沉弦，沉主里、弦主饮，合形盛面亮、喘不得卧、胸满腹胀、小水不利，知痰饮内聚、饮逆上泛。暮夜属阴，饮为阴邪，故喘甚不得卧。仲景谓饮家而咳当治其饮，故以开太阳导饮逆为法，小青龙去麻辛合越婢，正是从脉沉弦定饮邪内聚之病机。", ["沉", "弦"]], "1369": ["病机", "脉弦右涩，弦为饮、涩为气滞血少，右涩主中焦痰饮聚蓄。面亮舌白、口干不喜饮、头重岑岑、胸脘痹塞而痛、得嗳气稍舒，皆饮邪挟气上阻清空之象。引《金匮》脉弦为饮、色鲜明者为留饮，口干不欲饮水为饮邪未去，故断为痰饮聚蓄、清阳被阻，非风寒温邪。", ["弦", "涩"]], "1370": ["病机", "原文未出脉名，以风寒外受、热气内蒸立论。痰饮日聚于脏之外、络脉之中，遇风冷、曝日、劳碌、心事不宁则扰动络中宿饮，饮泛气逆，故咳嗽、气塞喉底胸膈、不思食、著枕呛吐稠痰。气降则自愈，病名哮喘伏饮，明言宿饮伏络、气逆上泛之病机，非单纯外感。", []], "1371": ["病机", "脉右弦、结饮，弦主饮、结主气机阻结。舌黄不渴、当心似阻、昔壮今瘦、咳久不已、卧著则咳、痰出稍安，知清阳少旋、支脉结饮。饮结支脉则气不流通，卧则饮逆故咳，痰出饮减故稍安。形瘦为饮久伤正，故议通上焦之阳以旋清阳、散结饮。", ["弦", "结"]], "1372": ["病机", "原文未出脉名，以头中冷痛、食入不消、筋脉掣痛、四末时冷立论。阳微不主流行，则痰饮日多、气隧日结，阳气不能达于四末故冷，不能温养筋脉故掣痛，不能运化故食入不消。总属阳微饮聚、气隧结滞之病机，故先以微通胸中之阳为治。", []], "1373": ["病机", "脉结饮，结主气机阻结、饮邪聚于支脉。寒月喘甚，因寒为阴邪、饮亦阴类，外寒引动宿饮故喘加；初因寒湿而得，食辛稍安，辛能温通散饮。可见支脉聚饮、寒饮相引为病机，喘甚随寒月而作，非新感风寒可比。", ["结"]], "1374": ["病机", "脉结饮，结主饮结气阻。支脉结饮则气机不利，故阻气喘胀；饮入胁络则痛；饮阻清阳、气逆不降则厥逆为眩。喘、胀、胁痛、眩四症皆由支脉饮结、气逆上泛所致，故以结饮为病机之枢，非泛言痰眩。", ["结"]], "1375": ["病机", "脉结饮，结主饮邪结聚、气机阻结。支脉结饮，饮伏络中，遇触发则气逆上壅，故发必喘急。原文仅言病发用，未详方药，然以结饮为脉、喘急为症，可知病机在支脉饮结、气逆而喘，属宿饮伏络、随触而发之候。", ["结"]], "1376": ["病机", "脉右虚主中气不足，左小弦主肝络不和，面色黄少华采为脾虚血少之征。左胁肋痛五六年未愈，久恙入络，络主血，故脉见小弦，示肝血瘀滞络脉。药不宜刚、勿事腻补，正因虚中夹瘀，刚燥伤阴、腻补碍络，故取旋覆花汤通络化瘀，加柏子仁、归须、桃仁养血润络，属内伤络病之脉证。", ["虚", "弦", "小"]], "1377": ["病机", "夏季阳气大升，痰多呛咳夜不得卧，谷味皆变，大便或溏或秘，脉右大而弦。右大主饮邪壅盛于中，弦主饮停气逆，悬饮流入胃络，胃气不得下行，故呛咳夜卧不安、谷味变、便溏秘不调。脉大弦与痰饮上逆相应，故议开阖导饮法，通降胃络以撤饮邪。", ["大", "弦"]], "1378": ["病机", "早诊两手皆弦，右偏大，弦主饮邪内停，大主饮气壅盛。痰气上涌咳逆愈甚，小溲少、下焦微肿，示饮邪上逆而太阳气化不利，水饮不得下输。脉弦大与痰饮上涌、下焦水停相应，故议通太阳以撤饮邪，开膀胱气化则饮从下解，咳逆可平。", ["弦", "大"]], "1379": ["病机", "脉弦略数，不渴不思饮，为饮浊未去、清阳不主运行之象。弦主饮停，略数示阳郁化热而非真热，故不渴。心下胃口若物阻呆滞，浊锢阳微，饮浊阻遏胃阳。前用甘温开阖令胃喜，次法开太阳撤饮。若治咳滋阴，则阴浊横帜，适助饮邪。脉弦数与饮浊锢阳相应，故用大半夏汤通阳降浊。", ["弦", "数"]], "1380": ["病机", "脉虚涩，虚主气血不足，涩主郁滞不畅。情怀失畅，肝脾气血多郁，半载不愈，郁久伤及气血，故脉见虚涩。虚涩并见，示正虚而郁滞并存，难任峻剂攻伐，故以逍遥散疏肝健脾、补中益气升举清阳，缓图气血郁滞之解，属肝脾郁结兼气血虚之脉证。", ["虚", "涩"]], "1381": ["病机", "恼怒肝郁，思虑脾伤，面黄脉涩。涩主气机郁滞、血行不畅，肝郁则气结，脾伤则生化不足，面黄为脾虚血少之征。寤不成寐，乃肝郁化火扰心、脾虚心神失养所致。脉涩与肝脾郁结相应，故宗薛氏法调肝健脾、解郁安神，从郁结论治。", ["涩"]], "1382": ["病机", "脉弦涩，弦主肝郁气结，涩主血行郁滞。外寒内热，齿痛舌干无寐，乃肝脾郁结不舒，气郁化热于内，外寒束表，郁热上扰则齿痛舌干，扰心则无寐。脉弦涩正合肝脾郁结、气血不畅之机，故从郁结论治，解郁清热，使气机条达则诸症自减。", ["弦", "涩"]], "1383": ["病机", "操持过动，肝胆阳升，胃气日减，脉应左搏。左搏指左脉搏指有力，主肝胆阳升气逆。操劳过度耗伤肝阴，肝阳上亢，木旺克土，胃气日减。脉左搏与肝胆郁热、阳升气逆相应，故从郁热论治，清肝胆郁热、降逆和胃，使阳升得平则胃气自复。", ["搏"]], "1384": ["病机", "脉弦为肝胆气郁，右大主气分郁滞。乳房刺痛、经阻半年，乃肝气郁结、气血不循；遇劳怒则腹痛逆气上冲，是郁久化火、少火变为壮火，气钝不循致胞脉痹阻。弦大之脉正应邪郁既久、气血壅滞之机，故治以泄少阳补太阴，使气血流利而郁热解。", ["弦", "大"]], "1385": ["病机", "脉弦主肝胆气郁，涩为血滞，数则化热。颈项结瘿、咽喉痛肿阻痹、水谷难下，皆情志郁勃致肝胆相火内风上循清窍。弦涩数并见，说明气郁血滞而火动风升，虽清热直降难制情怀之阳，故频药勿效，病根在情志郁勃。", ["弦", "涩", "数"]], "1386": ["病机", "脉左大弦数，左主肝胆，大弦为气郁化火之象，数则热盛。头目如蒙、背俞䐜胀，都是郁勃热气上升所致。原文谓“气有余便是火”，弦大数正应气郁化火、火热上扰清窍之机，故治宜清上，使郁热得清则诸症自减。", ["大", "弦", "数"]], "1387": ["病机", "原文未出脉名，以“气血郁痹，久乃化热”立论。女科八脉失调，渐有经阻瘕带诸疾，是气血郁滞日久化热、冲任受损之机。虽未言脉，然郁热内蕴当见弦数涩之类。治先清上、勿滋腻气机，正针对郁热上焦、气机壅滞之病机。", []], "1388": ["病机", "脉数为热，得之郁怒，是情志不遂、气郁化火之象。舌白神呆，白苔主气分郁滞，神呆为郁热扰及心神。数脉在此不主外感，而主郁怒化热、气机不畅，热郁于内尚未炽盛，故见数而舌白，治当解郁清热。", ["数"]], "1389": ["病机", "原文未出脉名，以“病起忧虑上损”立论。心胸右胁常有不舒，是气血内郁少展、支脉中痰饮气阻所致。忧虑伤气，气郁则血滞，痰饮乘虚阻于脉络，故宣通流畅脉络为治。此段重在郁损脉络、痰饮阻气之病机，非以脉断。", []], "1390": ["病机", "脉左涩主血络郁滞，右弦主气分郁结。口鼻中气触腥秽，是郁热蒸腐；右胁板痛、呼吸不利、卧著不安，乃气血郁痹、血络不通。有年郁伤，气滞血瘀日久，故左涩右弦并见，治当宣通脉络以行气血。", ["涩", "弦"]], "1391": ["治法", "原文未出脉名，紧接上段“血络郁痹右胁痛”而言，提出“治当宣通脉络”。此段主旨为治法，针对气血郁痹、血络不通之右胁板痛，以宣通脉络为法，使郁滞得行、血络通畅，则胁痛呼吸不利诸症可解。", []], "1392": ["病机", "原文未出脉名，专论五郁之发与六气著人皆能郁而致病，如伤寒邪郁营卫、暑湿蕴结三焦、瘟疫客于募原、风寒湿杂感成痹，总由邪不解散即谓之郁；又述七情之郁原由于心，情志不遂则郁而成病，症多心脾肝胆。此段重在阐发郁病之因机，非凭脉断病。", []], "1393": ["病机", "脉右涩大，右主胃，涩为营血内耗、脉道不充，大为木火升腾、胃逆不降。原文谓劳怒触动情志，少阳木火盛于寅，犯逆阳明上凭诸窍，致呕逆、耳鸣咽痹、食纳久留脘中、寤不肯寐；涩大合见，正示胃逆不降而营血内耗、无以养心之机。", ["涩", "大"]], "1394": ["主病", "原文未出脉象，述巅胀神迷、经脉抽痛、胀闷不欲纳食、一月经期四至，断为郁伤气血成病。经期四至属气血郁滞、冲任失守，巅胀神迷、经脉抽痛为郁火上扰、血不荣筋，故以龙荟丸清降郁火。此段以症测机，非凭脉立论。", []], "1395": ["病机", "脉左涩右弦，左候肝血，涩为血少气滞；右候气，弦为气火不降。原文直断气火不降，症见胸胁隐痛、脘不爽，胸胁为肝络所布，气火郁于脘胁则隐痛痞闷；气火升逆最虑灼伤血络而失血，故特标最虑失血，示气火郁脘痛之机。", ["涩", "弦"]], "1396": ["病机", "脉右虚左数，左候肝，数为营热；右候气，虚为气分不足。原文谓君相多动、营热气偏，故鼻左窍有血、左肩胛臂痛，皆木火循经上扰、络热所致。左数应营热，右虚示气不内守，合为君相火动、营热偏亢而络脉受灼之机，故先以清肝通络。", ["虚", "数"]], "1397": ["病机", "脉虚，原文标阳跷脉虚。操心烦劳则阳上升动，气越外泄，阳不入阴，故痰饮上溢而不得寐；中年后下元先损，阳不交阴，脉虚正应下元不足、阳气浮越。勉饮酒醴求神昏假寐非调病之法，故早用八味丸、晚用半夏秫米汤以引阳入阴。", ["虚"]], "1398": ["病机", "脉涩，涩为营血不充、脉道不利。原文谓不能充长肌肉、夜寐不适，断为脾营消索、无以灌溉，脾主肌肉，营虚则肌肉失养而不充，营不养心则寐不安。涩脉正应营血虚少，故用归脾汤意温养脾营，以复生化之源。", ["涩"]], "1399": ["预后", "脉细数涩，细为阴液内耗，数为化火，涩为营血不充。原文谓寤不成寐、食不甘味、尫羸，断为阴液内耗、厥阳外越、化火化风、燔燥煽动，属阴损，最不易治。细数涩合见，示阴亏火旺、营血枯涩，故预后不良，姑与酸枣仁汤养阴安神。", ["细", "数", "涩"]], "1400": ["病机", "原文述肌肉瘦减、善饥渴饮，为烦劳伤及心营肺卫，渐损中下。脉偏于左搏，左主血，搏为营络虚热之象，虚热内灼故苦寒莫制其烈，甘补无济其虚，终成中上消之病。", []], "1401": ["病机", "脉左数，左候肾，数主热。能食为胃火旺，肾阴虚不能制火，火旺消谷故能食。此肾阴虚胃火旺之消证，故用六味加二冬、龟版、女贞、旱莲、川斛滋肾阴清胃火。", ["数"]], "1402": ["病机", "形瘦脉搏，搏为火亢之象。渴饮善食，三消症也。肾阴虚则水不制火，心火亢盛，肠胃激烈之燥，津液枯竭。故河间以益肾水制心火为真治法，玉女煎主之。", ["搏"]], "1403": ["病机", "脉右数左小弱，右候肺，数主热；左小弱为营血不足。面明、微寒多热、呕逆身痛，乃暑湿挟痰火自肺经而起，气不宣化，热在气分。故与温疟同例，用桂枝白虎汤加半夏，忌葛柴足六经药。", ["数", "小", "弱"]], "1404": ["主病", "脉如平人，但热无寒，骨节烦疼，微呕而渴，此温疟之证。脉虽如平，而症候已显热邪内蕴，故仲景以桂枝白虎汤主之，清热生津，兼解表邪。", ["平"]], "1405": ["病机", "脉数，舌红口渴，数主热，舌红为血分有热之征。热邪已入血分，故脉数而口渴，当从血分论治，清营凉血。", ["数"]], "1406": ["病机", "舌黄烦渴，身痛，心腹中热躁，暑热不解为疟。经言暑脉自虚，此虚乃暑热耗气伤津所致，又受从前疲药之累瘁，故脉虚。当清暑益气，不可再行攻伐。", ["虚"]], "1407": ["病机", "脉数，目眦黄，舌心干白黄胎，口中黏腻，脘中痞闷，不思纳谷。此暑风客邪内侵募原，营卫不和，暑必兼湿，湿热搏结，清浊交混，升降自阻，故发疟疾。治当苦降辛通，开热气痞结。", ["数"]], "1408": ["病机", "脉右弦左弱，右弦主邪留气滞，左弱为营血不足。原文谓“留邪未尽”，邪阻肠道则大便黏稀，脉弦应之；左弱示正虚。弦弱并见，正虚邪恋，故“最防转痢”。治当苦辛寒逐蕴伏，通利小便，务尽去疾。", ["弦", "弱"]], "1409": ["病机", "脉濡小，濡主湿，小主虚。原文谓“暑湿从口鼻入，湿甚生热”，湿阻中焦则脘痞胀痹、呕恶便不爽；濡小为湿盛伤阳、正气不足之象。治以苦辛寒清上彻邪，不可温补助邪。", ["濡", "小"]], "1410": ["病机", "脉濡，为湿邪未化之象。原文谓“口渴，余热尚炽”，是暑湿余邪未尽，热炽伤津则渴，湿阻脉道则濡。濡脉主湿，亦主气虚，此段以脉濡提示湿热余邪尚存，不可纯补。", ["濡"]], "1411": ["病机", "原文未出具体脉名，仅言“阳脉衰也”。寒甚于背，背为阳位，阳脉衰则阳气不能温煦背部，故寒甚。此以脉释病机，阳衰不能抗邪，寒从背起，属阳虚寒盛之候。", []], "1412": ["妇人", "原文未出具体脉象，仅言“八脉以和补”。患者天癸始通，面黄汗泄，内热外冷，先天既薄，疟伤不复，阳维为病苦寒热。八脉失和，纲维不振，故四肢骨节疼痛。治当和补八脉，调经却病。", []], "1413": ["病机", "原文未出具体脉象，仅言“脉络未充”。久病阳虚，寒热未止，诸症虽减而脉络未充，是阳气未复、营卫未和。治宜通补为法，通以祛余邪，补以充脉络，不可纯补纯攻。", []], "1414": ["病机", "原文未出具体脉名，仅言“脉络中空乏”。疟久营卫气伤，脉络空虚，屡进补法仅填空隙，不能驱蕴伏之邪，故寒热未止。此营卫两伤、正虚邪恋之机，拟养营法，养正邪自却。", []], "1415": ["病机", "脉弦缓，弦主寒主痛，缓主湿主虚。原文谓“寒战甚则呕吐噫气，腹鸣溏泄”，是足太阴脾寒，寒凝气逆则呕噫，脾虚湿盛则腹鸣溏泄。弦缓并见，脾寒湿滞之象。苦辛寒屡用不效，反伤脾胃。", ["弦", "缓"]], "1416": ["病机", "原文未出脉名，以“劳伤阳气”“内损邪陷”“天癸既绝之后阴经空乏”立论，说明病机为营卫造偏、中宫营虚，故畏寒不知热而成牝疟，身体重亦属阴象。治以辛甘理阳，鹿茸自督脉煦提，与姜附走气分者不同，驱邪益虚却在营分，可见本段重在阐发虚损邪陷、营分受病之理。", []], "1417": ["病机", "原文引奇经之说“阳维脉为病发寒热也”，未及具体脉象。阳维维系诸阳，病则阴阳不能自相维，故发寒热。此段以奇经立论，说明寒热之由不在表邪，而在阳维为病、维脉失职，属病机层面之阐发，非据脉断症。", []], "1418": ["病机", "脉沉主里，合舌白、呃忒、时时烦躁，知向系阳虚痰饮。疟发三次即止，非邪去病解，乃邪窒不能宣越。今阴冱痰浊阻塞于中，上下气机不相维续，症势险笃。脉沉正应阴寒内冱、痰浊阻中之机，故舍通阳一法无方可拟，必得中阳流运、疟症复作方有愈机。", ["沉"]], "1419": ["病机", "左弱右促，目微黄，嗜酒必中虚谷少，易于聚湿蕴热。左弱示中气不足，右促为湿热内蕴、阳伤而躁。原文戒“勿谓阳伤骤补”，仿内经辛散太过当食甘以缓之，可见病机在胃阳虚而湿聚、湿热蕴阻，非纯虚可骤补，故以甘缓调中为法。", ["弱", "促"]], "1420": ["病机", "脉右大，间日寒热，目眦微黄身痛，此平素酒湿挟时邪流行经脉使然。右大主邪盛于气分，酒湿蕴中，时邪乘之，故寒热间作、身痛目黄。前因辛温大汗暂养胃口，今脉症既定，仍从疟门调治，说明病机为酒湿挟邪、流于经脉，非单纯虚损。", ["大"]], "1421": ["病机", "原文未出脉象，而言“形脉俱衰”，项疟已过月，形脉皆衰，平素阳虚，虚则邪难解散。腹胀是太阴见症，治从脾胃。可见病机为脾胃阳虚、正气不足，邪因虚而难解，故形脉俱衰、腹胀由生，当从脾胃温运以扶正祛邪。", []], "1422": ["病机", "脉数主热，疟来日迟，舌干渴饮，积劳悒郁，内伤居多，致邪气乘虚渐劫阴气。热邪坠于阴，热来小溲频数，故汗多不解。脉数正应阴分伏热、津液受劫之机，故议清阴分之热以救津液，说明病机在阴伤热伏，非表邪未解。", ["数"]], "1423": ["病机", "脉左弦，暮热早凉，汗解渴饮，治在少阳。左弦主少阳枢机不利，邪踞半表半里，故暮热早凉、汗出而渴。弦为少阳本脉，邪正交争于枢，故以和解少阳为治，说明病机在少阳枢机失运、邪留不解。", ["弦"]], "1424": ["病机", "热多昏谵、舌边赤舌心黄、烦渴，显系心经热疟，热盛伤津之候，而脉反弱，是热邪内陷、正气已馁之象。脉弱主虚，与壮热烦渴并见，说明邪热虽盛而心气已伤，非单纯实热。原文警告医投发散消导则津劫液涸、痉厥至矣，正因脉弱揭示津气两伤，再攻则虚虚之祸立至。", ["弱"]], "1425": ["病机", "脉寸大，寸候上焦肺卫，大则邪郁于手太阴，气分热盛。汗出口渴，是伏邪因新凉引动、由里出表之征，间日疟来亦邪踞肺卫、正邪交争之象。寸大而不言他部，说明病位偏上焦，故议治手太阴，从肺卫透解伏邪，与一般疟邪客少阳者不同。", ["大"]], "1426": ["病机", "脉濡主湿、主阳气不振，濡而兼不渴、呕痰不饥，正是湿痰困阻太阴脾土之象。脾阳不运则湿聚为痰，痰湿中阻则不渴不饥而呕，故断为太阴脾疟。脉濡非热盛之征，乃湿胜阳微之候，故治当辛温以理中焦之阳，温运脾阳、化湿祛痰，不可清解。", ["濡"]], "1427": ["病机", "疟邪大犯脾胃，呕吐痰涎、不饥不食，脾胃受困已明。脉仍虚、舌白，虚字点出正气不足、脾阳不振，邪虽在脾胃而正已虚，故治在太阴、不必攻表。脉虚与不食并见，说明中焦运化无力，若再攻表则更伤正气，当以温运太阴为要。", ["虚"]], "1428": ["病机", "脉濡为湿胜阳微之象，寒热、疟日迟、腹微满、四肢不暖，皆太阴脾阳不运、湿浊内困之征。疟发日迟说明邪陷较深、正气不足；四肢不暖是脾阳不能温煦四末。故断为太阴脾疟，用露姜饮升阳，正针对脉濡所主的湿困阳微病机。", ["濡"]], "1429": ["病机", "舌白脉小，暑邪成疟本应脉数，今脉小是麻黄劫汗伤阳、正气受戕之象。痰咸有血、右胁痛引背、不知饥饱，为胃津亏耗、腑气不降之候。脉小主虚，与劫汗伤阳相应，故变痉症。原文谓当先理胃津，正因脉小示津气已伤，不可再事攻散。", ["小"]], "1430": ["病机", "脉数主热，左寸大、关弦，寸大关弦并见，是胃气受伤、痰热内扰之象。疟后食大荤太早，胃气壅滞不得下降，故痞闷恶心、痰多唇燥、大便不利。脉数大弦说明腑气不宣、痰热郁阻，非虚寒之候，故拟温胆汤和胃气以宣腑气。", ["数", "大", "弦"]], "1431": ["病机", "体丰色白本阳气素虚，伏暑挟痰饮为疟，寒热夜作、邪已入阴，冷汗频出更伤阳气。脉小无力、舌白，虚象已著，小为阳气衰微，无力为正气不支，与冷汗频出相应，故恐延厥脱之虑。拟救逆汤法，正针对脉小无力所主的阳衰欲脱病机。", ["小", "无力"]], "1432": ["病机", "脉左手似数而坚，数非热炽，乃天暴冷阳伤，阴液亏虚，饮水自救之象。坚脉主寒凝气滞，阳伤泄泻，口微渴舌仍白，说明阴液既亏而寒邪未化热，故议通塞两用，冀寒热再缓。", ["数", "坚"]], "1433": ["病机", "左脉较右脉弦长，右脉弦长，弦为肝木之象，长为气机有余。平昔肝木易动，味变酸是木侮土之征，脉弦长反映肝气偏亢，乘克脾土，故秋前宜慎，防其加剧。", ["弦", "长"]], "1434": ["病机", "脉不和，疟母乃疟邪入络与血气扭结，凝然不动。遇冷劳怒则冲气至脘，痛必呕逆，三日气降痛缓，水饮得入。此厥逆之气由肝入胃，冲脉不和则经水不调，脉不和正示气血络脉阻滞。", []], "1435": ["病机", "诊脉右濡，濡为气虚湿滞之象。寒热已止而右脉濡，明是气衰，脾胃气弱，余邪未清。故宜和胃生津，使余邪不攻自解，濡脉在此主气衰而非邪盛。", ["濡"]], "1436": ["病机", "脉左数，舌绛暮渴，数脉主热，左脉候肝，舌绛为热入营血，暮渴乃阴分热灼。此脉数示热邪内扰营阴，阴液受灼，故见舌绛暮渴之症。", ["数"]], "1437": ["病机", "诊脉小右濡，小为气虚，濡为脾弱湿滞。不饥、入夜昏谵语但如寐不加狂躁，论脾为柔脏体阴用阳，脉小濡反映脾气虚衰、湿浊内困，故遵冷香缩脾遗意治之。", ["小", "濡"]], "1438": ["病机", "脉右弦来去不齐，左小耎弱，弦为疟邪内伏，小耎弱为阳气微弱。舌边红舌心白黄微绉，鼻冷四肢冷，热时微渴不饥，形肉消烁，说明脾胃受病、阳气微弱，阴伏邪无发散清热之理，宜宣通脾胃之阳。", ["弦", "小", "耎", "弱"]], "1439": ["病机", "脉右涩，涩主气血滞涩。疟伤脾胃，腹中不和，食入胀甚，服通调气血佐泄木之剂后积滞下、痛随利减，说明脉涩为木郁克土、气血壅滞，仍宜制木安土，不可作阳虚温补。", ["涩"]], "1440": ["病机", "脉左弦主肝胆气机不畅，木旺克土。呕吐、发热后脘中痞闷不爽，乃邪留少阳阳明，胃气上逆，湿浊中阻。弦为肝脉，左关候肝，故知肝气犯胃，宜慎口腹，清肃上中二焦，防其延成疟疾。", ["弦"]], "1441": ["主病", "脉沉涩主里，涩为气滞血瘀。疟而中脘痞结，邪结于里，气机壅塞，故脉沉涩。此属里症，非表邪，当用泻心法以开结泄热，调畅中焦。", ["沉", "涩"]], "1442": ["兼症", "脉沉主里，右关大主脾胃热盛。疟未止，寒热子后作，烦渴中闷不欲食，乃邪伏膜原，热伤胃津，气机壅滞。右关大提示中焦热结，故见烦渴不食。", ["沉", "大"]], "1443": ["预后", "脉细涩主气血两亏，涩为气结血瘀。湿热与水谷交蒸，误补致邪弥漫，神昏喘急，谵妄痉搐，邪无出路，内闭外脱。洞利后腹满，诸气皆结，脉细涩示正气已败，故难望挽救。", ["细", "涩"]], "1444": ["病机", "脉右大主气分热盛，右关候脾胃。寒热微呕，脘痞不纳，疟邪交于中宫，脾胃气滞热郁。右大示邪在中焦，当苦辛泄降，酸苦泄热，使邪势减而中焦得和。", ["大"]], "1445": ["病机", "脉两手俱数主热盛，数则为热。寒热未已，渴饮仍然，周身皆痛，汗泄不解，舌灰白边赤，乃里热炽盛，邪留气分。数脉示热邪未清，故拟酸苦泄里热，务以疟止。", ["数"]], "1446": ["病机", "脉小涩主气血不足，涩为血瘀气滞。疟后食物不和，烦劳伤气，肝邪助木势张扬，中土受侮，清阳不展，浊阴日踞，渐为痞满。小涩示气血久阻为郁，故用通络法，病根在疟久邪留络中。", ["小", "涩"]], "1447": ["其他", "本条未识脉名，述夏秋湿热疟痢，正虚邪留，混入血络，结成症瘕疟母。湿气热气本无形，医治非法致血脉蕴邪，寒热间发。仲景立法务在缓攻，急则变为中满，故兼服鳖甲煎丸缓消疟母。", []], "1448": ["病机", "原文未出脉名，然言「邪已入络，与气血胶结成形」，左胁结疟母，是久疟邪深、络脉凝瘀之病机。表里解散之药不能入络通血脉、攻坚垒，故佐辛香以走窜通络，点明络病大旨在于气血胶结、非攻逐可解，与一般疟邪在表里者不同。", []], "1449": ["病机", "脉微弱不鼓，为阳气衰微、鼓动无力之象。阴疟一年方止而羸瘦妨食、食入不运、四肢无力，皆脾阳不振、火不生土所致。屡进六君益气无效，正因虚在阳分而非气虚，故当温里通阳，从火生土，脉微弱不鼓正是阳虚内寒之据。", ["微", "弱"]], "1450": ["病机", "脉沉细，沉主里、细主虚，为脾阳困顿、阳气不能外达之象。三疟不饥不纳、恶心、渴喜热饮，皆中阳不振、阴寒内踞之症。脾阳虚则不能送邪外出，故脉沉细而症见纳呆恶心，治以四兽饮温运脾阳，使邪有外出之路。", ["沉", "细"]], "1451": ["病机", "脉濡为湿象，面黄舌白、脘中格拒、汤水皆呕，是足太阴阳微而饮邪结聚。濡脉主湿主虚，湿饮内结则气机阻遏，故格拒呕吐；三日疟一至，邪伏较深。据色脉合参，断为太阴阳微饮结，当以温药和之，温阳化饮则濡脉可去。", ["濡"]], "1452": ["病机", "原文未出脉名，重在析病机转变。初病劳倦晡热误投甘温，反剧而闻谷气秽、渴思凉饮，是暑邪内伏、胃热灼燥。邪由经气入络血，由阳入阴，间日延为三疟，奇脉跷维皆伤，故四末寒凛。指出参耆术附不能固阳、归桂地芍不能养营，邪与气血混成一所，非汗吐下可解。", []], "1453": ["病机", "脉细微为气血两虚、神衰之候。三疟久延，邪入阴络，症瘕疟母聚于季胁，本宜攻逐瘀聚以通阴阳，然诊得脉细微、食减神衰，攻法再施恐扰中满。故前与温补通阳颇安，守中之补姑缓为宜，示正虚邪结者攻补须权衡，脉细微正是不可峻攻之凭。", ["细", "微"]], "1454": ["病机", "原文未出具体脉名，仅言「其脉色自有阳胜之候」。诸疟由伏邪而成，暑必挟湿、专伤气分，须辨上中焦及暑湿孰重。暑热重者热重寒微、唇舌绛赤、烦渴喜凉饮，脉色现阳胜之象，故宗桂枝白虎法。此段论疟之六气分类与辨证眼目，脉象从属于阳胜之候。", []], "1455": ["治法", "夏至后热胜湿蒸、气伤神倦，用东垣益气汤；若汗出口渴，则兼生脉散以敛液。脉散指气液耗散不收，暑热伤气、汗多耗津，故脉见散而口渴，治当益气与敛液并行，使耗散之气液得以收敛，体现暑湿伤气分而设的治法。", ["散"]], "1456": ["病机", "原文未识脉名，仅言「脉垂」，指脉气下坠不能升举。阴疟久伤成损，督脉失用，故俯不能卧、脊强、足跗浮肿，渐至伛偻废疾，皆督脉不主一身之阳所致。近日暑湿内侵泄泻，是虚损基础上复感外邪，先宜分利和中，属标本兼顾之治。", []], "1457": ["病机", "左脉缓涩为久病阴阳之损，涩主血少、缓主气虚，是劳倦内伤之合理脉象；右脉弦大非有余形质之滞，乃湿热内淫、脾胃日伤、气机壅滞之象。足跗肿、大便黏腻黄赤紫滞、小便不利，皆脾肾日伤、肾关枢机已废、水谷酿湿坠下所致，弦大正是邪滞之征。", ["缓", "涩", "弦", "大"]], "1458": ["病机", "脉缓大主水谷内因之湿。缓为湿滞、大为邪盛，湿郁蒸于肠胃，致清浊不分，故腹痛泄泻、小溲不利。此非虚损之缓大，乃湿浊壅盛之候，若不清理分消，湿浊久聚可延为积聚黏腻滞下，故议芩芍汤清利湿热。", ["缓", "大"]], "1459": ["病机", "脉缓涩主气郁湿凝。缓为湿滞，涩为气机不畅、血行不利，湿凝在肠、气郁滞久，故腹满、痛泻不爽。此非纯虚之涩，乃湿阻气滞、肠道传导失司之象，用丹溪小温中丸以温中化湿、行气散结。", ["缓", "涩"]], "1460": ["病机", "肝部独大而脾胃缓弱，是肝木偏旺、脾土受制之象。纳谷甚少而精神颇好，先天虽充，后天脾胃已弱。水泻、少腹满胀，少腹为厥阴肝位，由阴阳不分、浊踞于下，致肝失疏泄，故以五苓散导水利湿，仿开支河之法分利浊邪。", ["大"]], "1461": ["病机", "脉沉缓主水湿内停、阳气少于运行。沉为病在里，缓为湿滞，肌肉丰盛是水土禀质，水谷聚湿布及经络，故下焦重著筋痛、食稍不运便易泄泻、经水色淡。总属太阴脾脏运化失职、水湿交混，调理当以健脾化湿为主，否则恐防胀病。", ["沉", "缓"]], "1462": ["病机", "脉紧主阳微湿聚、气不流畅。紧为寒湿内盛、阳气受困之象，阳虚不能化湿，湿聚气滞，故足肿便溏。此非表寒之紧，乃里阳不足、寒湿凝滞之候，久则气机壅塞，怕成单胀，故照前方加茵陈以增利湿退肿之力。", ["紧"]], "1463": ["病机", "脉虚主阳明脉虚、内风闪烁。霍乱后痛泻已缓而心中空洞、肢节痿弱，是吐泻伤中、阳明气血不足，筋脉失养而虚风内动。此属虚象，非实邪为患，故用异功散去参术，避其壅补，专以调和脾胃、缓理虚风为要。", ["虚"]], "1464": ["病机", "脉小弦，小为阳明胃土虚衰、气血不足，弦为厥阴肝风内动。原文谓“非二神四神温固之症”，点明非单纯脾肾虚寒，而是“阳明胃土已虚，厥阴肝风振动内起”，肝风乘虚扰脾，久病致飧泄、腹鸣晨泄、巅眩脘痹。故治以甘理胃、酸制肝，脉象揭示土虚木贼之病机。", ["小", "弦"]], "1465": ["病机", "原文未识脉名，以“左胁气胀，在皮膜之里”定位络脉中病。前医泄肝破气久服，致“脾胃受困，而为泄泻”，说明破气伤中之弊。虽得养中小愈，然“以药治药，脉络之病仍在”，揭示病本在络脉气滞，误治后脾胃受累，病机由络脉气病转兼中焦受困，非单纯攻伐可解。", []], "1466": ["病机", "脉右弦，右关候脾胃，弦主木旺。原文谓“少阳木火郁伤脾土”，胆木郁火横逆犯脾，脾失健运则腹膨鸣响痛泻，半年不痊。久则土虚水湿不化，可致浮肿胀满。脉弦示木郁未伸，故法当疏通泄郁，非辛温燥热所宜，紧扣胆郁伤脾之病机。", ["弦"]], "1467": ["病机", "脉沉主里、主阳虚。原文见形寒、腰髀牵强、腹鸣、有形上下攻触、每晨必泻，经水百日一至，显系肾阳不足、冲任虚寒，阴寒内盛故脉沉。晨泻属肾阳虚衰，腰髀牵强为督脉失温，经水迟至为冲任虚损。仿仲景意，即温补下焦、固摄奇经，脉沉揭示里虚寒之本质。", ["沉"]], "1468": ["病机", "脉耎即软，主阳气不足。原文“色白，脉耎，体质阳薄”，入春汗泄、神力疲倦、大便溏泄不爽，皆脾阳困顿、不能鼓动生生阳气之象。汗泄为卫阳不固，便溏不爽为脾运无力。脉耎正合阳虚气弱，故以和中为先，温运脾阳，非峻补可骤效。", ["耎"]], "1469": ["病机", "两关缓弱，关候脾胃，缓弱为脾阳式微、中焦聚湿少运，故心下懊𢙐、纳谷不易化。尺动下垂，尺候肾，动为肾阴衰、固摄失司，发为瘕泄。原文明言“脾阳微”“肾阴衰”，上中下同病，故议早进治中法旋运中焦，夕用四神丸封藏下焦，脉象分示脾肾两虚之机。", ["缓", "弱", "动"]], "1470": ["病机", "久泻脉虚，虚为正气不足。久泻伤脾，脾阳日损，气血生化乏源，故脉见虚象。原文仅“久泻。脉虚”四字，脉虚与久泻相应，揭示泻久中气亏虚、脾阳不振之病机，虚脉主正衰，非实邪内滞，治当温补固涩，不可再行攻消。", ["虚"]], "1471": ["病机", "原文未识脉名，以“劳损，自三阴及于奇经”立论。腹中气升胃痛、有形动触，为冲任脉乏、下焦不摄，气逆上冲。守补则滞、凉润则滑，说明纯补纯清皆碍，兼漏疡久泻寒热，正虚邪恋。故先固摄下焦为治，病机属三阴及奇经虚损、冲任不固、虚气上逆。", []], "1472": ["病机", "脉细下垂，细为阴血不足，下垂示气虚下陷。高年久咳，肺气已亏；腹痛泄泻，脾阳亦弱；形神憔悴，乃气血双虚、病伤难复之象。此非实邪攻伐可解，故拟甘缓法以培中气，与中虚腹痛相应。", ["细", "沉"]], "1473": ["病机", "泄泻总因湿胜。脉微气脱，洞下不禁，为湿胜气脱之滑泄，急投四柱六柱饮；脉弦治风，飧泄完谷不化，湿兼风也，用胃风汤；脉濡渗湿，濡泄身重软弱，湿自胜也，虚则胃苓、实则术附。三脉分主风、湿、气脱之机。", ["微", "弦", "濡"]], "1474": ["病机", "脉来右弦左弱，右弦主痰饮内停、气机郁滞，左弱为营血不足。痰哮宿病，又值寒热下痢血积，腹痛吐逆，目黄羞明，显系暑湿凝滞著里，虚实夹杂。故以补虚之中佐清邪，乃通剂法，与痰哮、痢积症候相应。", ["弦", "弱"]], "1475": ["病机", "脉左小右大，左小为营阴亏虚，右大为邪热壅盛。内虚邪陷，协热自利，病九日不减，正虚不能托邪，邪热下迫肠道，故为重症。议白头翁汤加黄芩白芍，清热止利兼和营阴，与协热痢相应。", ["小", "大"]], "1476": ["预后", "右脉搏大，右关主脾胃，搏大乃邪热亢盛、正气反伤之象。血积痛痢起于夏令，秋半不减，湿热久滞肠胃，面色消夺，正虚邪实。痢症见搏大脉，为胃气受戕、邪势鸱张，故曰大忌，稍通积聚兼和血，乃不得已之法。", ["搏", "大"]], "1477": ["病机", "脉缓为湿邪内蕴、阳气不运之象。脐上痛、便稀溺短，乃湿郁脾胃之阳，致气滞里急。湿阻中焦，脾失健运，故宗古人导湿分消之意，使湿去则阳自通，与阳虚气滞之机相应。", ["缓"]], "1478": ["病机", "脉沉伏，沉主里、伏主邪闭，乃阳气郁遏不能外达。久痢腹痛、畏寒少食、气弱肠滞，显系脾肾阳虚、寒湿内凝，气血滞而不行。故以温通方法，温阳以散寒，通滞以止痢，与阳虚寒凝之痢相应。", ["沉", "伏"]], "1479": ["预后", "脉见弦劲，弦为肝木乘脾，劲则失柔和之胃气。痢伤浊壅，脾肾复惫，纳食变痰沫，水液上泛阻咽，已成胀病末传。弦劲无胃气，乃真脏脉现，阳渐溃散而阴液枯槁，小愈变病，入冬藏阳之令而阳不藏，故最属不宜。", ["弦", "劲"]], "1480": ["病机", "下痢泄泻后脉右弦大，右脉候脾胃，弦大乃胃虚少纳、阳弱不司运化之象。弦为木旺乘土，大为虚阳外浮，非实热壅盛。原文谓“胃虚少纳，阳弱不司运化”，故法当通腑之阳，以复中阳运化之职。", ["弦", "大"]], "1481": ["病机", "腹满自痢而脉来濡小，濡小为太阴脾虚湿盛之脉，非腑病湿热之实。原文更以“小便清长”佐证，明非湿热内蕴。濡小示中阳不振、湿浊内停，故法当温之，以温运太阴脾阳。", ["濡", "小"]], "1482": ["病机", "痢疾一年，浮肿溺涩，食粥吞酸，色瘁脉濡。濡脉主湿、主虚，久痢伤肾，中焦之阳日惫，水谷之湿不运，故脉濡。原文谓“中焦之阳日惫，水谷之湿不运”，仍辛温以苏脾阳，佐分利，用胃苓汤加减。", ["濡"]], "1483": ["预后", "脉微细、肢厥、下痢无度，微细为阳气衰微、阴寒内盛之脉。吴茱萸汤仅能止痛而不进食，原文断为“阳败阴浊，腑气欲绝”，故用桃花汤温涩固脱。此脉示阳气败绝、阴浊弥漫，预后凶险。", ["微", "细"]], "1484": ["病机", "痢后大便不实、食不健运，色脉俱是虚象。原文谓“清阳失旷于中，阴气先走泄于下”，脉虚象示中阳不振、清阳不升，阴泄于下。先理中焦以复清阳，再当摄阴，此脉虚为脾阳不足、阴走于下之机。", []], "1485": ["病机", "脉沉微，下痢红紫黑，舌胎粉白，并不渴饮。沉微为阳气虚衰、阴寒内盛之脉，红紫黑痢非热迫，乃太阴脾营虚寒、血失统摄。原文断为“太阴脾营虚寒”，故仿理阴煎温补脾营。", ["沉", "微"]], "1486": ["预后", "高年下痢，痰多舌干，脉右空大，神困音低。右脉空大为脾胃虚败、脉失充养之象，非实热。原文谓“脾肾两亏，二气交虚”，高年致此，恐非所宜，示脾肾气衰、预后不良。", ["空", "大"]], "1487": ["病机", "脉左数，下利腹不甚痛，暮夜微热。左脉数示阴虚内热，所伏暑热乘阴虚下陷。原文谓“清热理脾不效，当摄阴升阳”，数脉为暑热内伏、阴伤阳陷之机，非单纯实热。", ["数"]], "1488": ["病机", "脉右数、左细数，右数主里热炽盛，左细数主阴液亏耗。面垢舌燥、白苔点点为暑热熏蒸、津伤之象；肌肤甲错、左胁动气示阴血瘀滞、肝络不和。伏暑秋凉而发，初如疟，里邪炽烈变下痢，胃津被劫、阴液大耗，故以救阴为务，用复脉汤去姜桂麻存阴。", ["数", "细"]], "1489": ["病机", "原文未出脉名，以证测机。泻痢起于长夏，医作湿热治而病经两旬不减，缘高年肾阳肝阴先亏，客气内扰、中流乏砥柱，致狂澜滔天。神识尚清知外邪少、内损多，八脉无权、下无收摄、漏卮不已，必生阳泄下焦冷，皆阴阳二气微绝，故治本为宜。", []], "1490": ["病机", "原文未出脉象。治痢古法不越通涩，然经停有瘕、腹浮肿，显系八脉之病，非脾胃症。医惑于见痢而认作脾胃，议用济生肾气丸，正是从下焦八脉、肾气不化水立论，以瘕聚浮肿属奇经虚滞、水气不行，故不专治痢。", []], "1491": ["病机", "原文未出脉象。痢久必伤肾阴，八脉不固，肠腻自滑而下，故但执健脾无用，病不在中焦。纳谷运迟，下焦坎阳亦衰，是肾阴肾阳俱损、奇经失约。用三神丸温涩下焦，正针对八脉不固、滑脱不禁之机。", []], "1492": ["病机", "脉数劲，数主热、劲主阴伤阳亢，为下损至中之象。下痢腹鸣痛、后坠，卧则气冲、咳嗽吐黏涎，产后过月而纳谷日少、形神日衰，势成蓐劳。数劲之脉示虚劳内热、阴不恋阳，冲气上逆，故难期速功。", ["数", "劲"]], "1493": ["病机", "脉促细坚，促为阳结、细为阴亏、坚为邪伏深入。神气索然、腹中动气、舌红嗌干、寒热日迟，平素积劳致虚，邪伏厥阴。促细坚示正虚邪结、阴阳不相顺接，温清难用，故勉议复脉汤存阴勿涸，希图援救。", ["促", "细", "坚"]], "1494": ["病机", "原文未出脉象，言两投复脉后色脉略转。平素积虚，疟邪内陷，阳结于上则胸痞，阴走于下则频利，非徒开泄攻邪可治。救逆汤去姜，意在救逆护阴、交通阴阳，针对虚而邪陷、上下格拒之机。", []], "1495": ["病机", "脉动气，动主阴阳相搏、阳虚不潜。奔脉动气皆阳虚浊泛，浊阴上逆则气动不安。当和营理阳，使阳复归位、浊阴下降，则动气自平。此段以脉动点出阳虚浊泛之病机，非单纯气滞。", ["动"]], "1496": ["病机", "脉左细数右弦，细为阴伤，数为热，弦主痛。暑湿深入著腑，酿成积滞，故干呕不能纳谷、腹痛里急后重、痢积不爽。此噤口痢疾，湿热壅阻肠胃，气机不通，势属重危，故议苦寒清解热毒。", ["细", "数", "弦"]], "1497": ["病机", "脉弦形衰，舌白不渴，日泻数行，食不下咽，不知饥饱。此久痢后胃倒气夺，中宫损极，下关不摄。弦为气机郁滞，胃气衰败，故谷不能咽，药难承受。久痢久泻务在能食，当醒脾胃或安肾摄纳。", ["弦"]], "1498": ["病机", "脉坚劲不和，高年暑湿热邪内著，脾胃气困。坚劲示邪实气滞，湿热壅阻，故舌心黄边白、渴饮、水浆停胃脘、干呕冷呃、自痢稀水、小便不利。年高不敢过清过消，用清暑益气以醒脾胃。", ["坚", "劲"]], "1499": ["病机", "原文未识脉名。口中干燥、小水全无，泉源已竭，阴液无以上承；痢症噤口，湿热壅于胃口，下元衰惫，冲脉气震高突。此攻病保真两难，阴液枯竭而湿热未清，故理难捉摸。", []], "1500": ["病机", "脉结涩而痛，结涩主气滞血瘀、积阻不通。痢症古名滞下，夏秋暑湿挟积居多，邪著脏腑，气血壅滞，故痛。在气在血、伤脏伤腑各异，治有苦辛调气、辛甘益气等法，须细辨邪之所在。", ["结", "涩"]], "1501": ["病机", "脉右数，形色苍黑，体质多热。长夏湿热内蒸，水谷气壅，血从便下。右数主热壅气分，湿热伤及肠络，故下血。法以苦寒清解，佐辛温通滞，薄味调养可愈。", ["数"]], "1502": ["病机", "脉沉，粪后下血。沉主里，少年淳朴，食物不和，肠络空隙渗血。此非外邪，乃内伤饮食，气机升降失司，血不循经而下。故与升降法调其气机，使肠络自安。", ["沉"]], "1503": ["病机", "脉缓濡弱，阳气不足，过饮湿胜，大便溏滑似乎不禁，便后血色红紫成块。濡弱主气虚湿盛，少阴肾脏失司固摄，阳明胃脉但开无合。治腑以通为补，与治脏补法迥异，当温阳化湿、固摄下元。", ["缓", "濡", "弱"]], "1504": ["病机", "脉数主热，便红为大肠血热之征。热迫血行，血溢肠腑，故见便红。数脉为热盛之象，与大肠血热病机相应，非虚寒所致。", ["数"]], "1505": ["病机", "脉数能食，肠红下泄，乃肠腑热炽，阴液自下泄。数脉主热，热灼肠络则血溢，非温补所宜。此脉数说明热邪内炽，阴伤血泄之病机。", ["数"]], "1506": ["病机", "脉濡小，食少气衰，春季便血，大便时结时溏。濡小为气衰阴弱之象，春夏阳升而阴弱少摄，故便血。阳明不阖，甘酸固涩以阖阳明，非升阳所宜。", ["濡", "小"]], "1507": ["病机", "脉细色痿，能食肠血，肛痔下坠。细脉主阴血不足，色痿为血虚不荣。肠血下坠乃阴亏风动，酸苦熄风坚阴，以复阴血。", ["细"]], "1508": ["病机", "便血如注，面黄脉小，已三载。小脉主虚，面黄为脾胃阳虚，气不摄血。久病便血，脾胃虚衰，当益胃以复中阳。", ["小"]], "1509": ["误治", "脉小左数，便实下血，肝络热腾。医投参耆归桂辛温，助火升阳，致鼻塞头晕呛咳。左数主肝热，小为阴伤，误治则虚阳上冒，下虚上实。", ["小", "数"]], "1510": ["病机", "下血阴伤，虚阳上升，参耆术桂助上致鼻塞耳聋。清上后右脉已小，左仍细数，乃阴亏本象。细数主阴亏火旺，下愈虚则上愈实，滋水制火为法。", ["细", "数"]], "1511": ["病机", "脉左数，耳聋胁痛，木失水涵，上泛为患。左数主肝火，水不涵木则风火上扰，耳聋胁痛。补阴丸滋水涵木，以制上泛之阳。", ["数"]], "1512": ["病机", "脉右空大、左小促，乃劳伤下血后络脉空乏、营卫失序之象。右空大主阳明络虚不固，左小促示营阴耗伤而脉道不利。营卫不主循序流行，故为偏寒偏热；络脉空乏则痛。治以归耆建中汤通补阳明，使开合有序，正合脉证。", ["空", "大", "小", "促"]], "1513": ["病机", "原文未识脉名，然述“阳明脉乏，不主用事，营卫失度，津液不升”。湿去气泄后，阳明脉气匮乏，不能主营运化，营卫循行失度，故见筋骨痿耎寒热、夜卧口干。此非外邪，乃内伤气泄、津液不升之机，天真丸主之，去人参避其壅补。", []], "1514": ["病机", "脉左虚涩、右缓大，左虚涩主精血亏少、脉道不利，右缓大示中气浮缓不敛。尾闾痛连脊骨、便后血、欲晕、纳少，明是中下交损、八脉全亏。虚涩为损脉之征，缓大为虚阳外浮，故用斑龙丸峻补、归脾膏涵养，守之经年。", ["虚", "涩", "缓", "大"]], "1515": ["治法", "此段无脉象描述，专述用药法度。鹿茸壮督脉之阳，鹿霜通督脉之气，鹿胶补肾脉之血，骨脂独入命门以收散越阳气。针对督脉阳虚、阳气散越之病机，取血肉有情之品通补奇经，使阳气得收、督脉得壮，非泛泛补肾。", []], "1516": ["治法", "此段无脉象，论制方之意。柏子凉心益肾，熟地味厚填肾，韭子菟丝就少阴升气固精，重用茯苓淡渗引诸药入至阴。不用萸味之酸，因酸能柔阴且不能入脉。全方着眼于少阴肾与阳明之界，升气固精、通补兼施，以复脉道之虚。", []], "1517": ["主病", "左脉小数坚，小为阴血不足，数为有热，坚则脉道拘急。肛坠胀者，热郁气陷、络脉不和之象。小数坚并见，示阴亏而热结于下，非纯虚之候。此脉主下焦郁热、气机坠滞，与肛坠胀症相应，当于升固中兼清络热。", ["小", "数", "坚"]], "1518": ["病机", "脉小为阴液损伤、奇经不充之征。泻血二十年，阴络伤而血内溢，冲任失养故不得孕育；心中痛坠、血下不论粪前粪后、腰尻酸楚、跗膝冷而骨髓热灼，皆阴损及阳、阳不固密之象。脉小正合奇脉亏虚，议从奇经升固一法。", ["小"]], "1519": ["病机", "原文以“脉络牵掣不和”描述，非典型脉名，故脉象要素从缺。劳力见血，胸背胁肋诸脉络牵掣不和，乃劳力伤络、营络瘀滞之病机。络脉受损则气血不通，不通则牵掣而痛；血溢脉外则见血。治在营络，即和营通络以复其常。", []], "1520": ["病机", "此段论便血，分肠风脏毒脉痔，归于风淫肠胃、湿热伤脾，更取《内经》阴络受伤、结阴之旨。阴络即脏腑隶下之络，结阴为阴不随阳之征，故血不归经。以先便后血、先血后便分远近，决脏腑性情，防气失统摄、血无所归。肺病燥涩宜润降，心病火燃血沸宜清化，脾病湿滑宜燥升，肝病风阳痛迫宜柔泄，皆从络病与脏腑相关立论。", []], "1521": ["病机", "脉濡弱主气虚湿滞。湿热伤气，气下陷则坠肛而痛，溲后阴囊筋牵于肛，痛甚。厥阴肝脉绕阴，虽病涉肝，然脉濡弱非疏泄实邪，乃中气不足、清阳不升。故议“陷者举之”，用东垣补中益气汤升举阳气，兼化湿热。濡弱为虚象，提示不可峻攻，当以补气升提为治。", ["濡", "弱"]], "1522": ["病机", "脱肛漏血遇劳即发，病经十六载，色萎黄，背脊痛，诊脉尺中下垂。尺脉下垂主下元虚衰、阳气不升，故升阳摄阴兼理奇脉。劳则气耗，气虚下陷则脱肛，阴络不固则漏血；色萎黄为脾虚，背脊痛属督脉失养。用斑龙丸加五味子蜜丸，补奇脉、摄阴血，从下焦根本论治。", []], "1523": ["病机", "有年偏痿，日瘦，色苍脉数。脉数主热，色苍为阴伤，年高阴亏，肺热叶焦则津液不布，筋脉失养而成痿躄。此本《金匮》“肺热叶焦，则生痿躄”之论，热灼肺津，不能输精于皮毛筋骨，故偏痿日瘦。脉数正是内热之征，治当清肺润燥，不可妄补。", ["数"]], "1524": ["病机", "色苍脉实体壮，年逾四旬气元充旺，平日善啖酒醴甘肥，酿成湿火蕴结下焦。少腹微肿硬、二便滞涩、气胀上冲、两足沉重、腿股皮热，即《内经》湿热不攘、大筋緛短、小筋弛长之痿。脉实为邪气壅盛，非虚候。又吸受秽浊毒气与湿热纠蓄，故以苦辛寒燥佐搜逐络隧，并戒饮茹素以拔病根。", ["实"]], "1525": ["病机", "雨湿外来、水谷聚湿内起，两因相凑，经脉为痹。始病继以疮痍，渐致痿緛筋弛、气隧不用。湿虽阻气，而热蒸烁及筋骨，久延可致废弃。此论湿热相合，外湿引动内湿，痹阻经脉，热蒸伤筋，故见痿软筋弛。病机重在湿热蒸烁筋骨，非单纯寒湿，治当清渗湿热、通利经脉。", []], "1526": ["病机", "诊脉论体，遗精漏疡后环跳穴痛，不堪行走，脏阴伤及腑阳，阳气窒塞，经脉不司舒展。食入壅脘欲吐，大便旬日不通，痞阻日甚而成痿。此胃气窒塞、筋骨不利之痿。《内经》论治痿独取阳明，以胃脉束筋骨利机关，故用加味温胆汤流通胃气，使阳气舒展，机关通利。", []], "1527": ["病机", "五旬又四，阳气日薄，阳明脉络空乏，不司束筋骨以流利机关，故肩痛肢麻、头目如蒙、行动痿弱无力。此下虚上实，络热内风沸起，入夏阳升为甚。脉脉络空乏示阳明虚，虚则筋骨失束；络热生风，故头目蒙、肢麻。燥湿利痰必不应病，议清营热以熄内风，从虚实夹杂论治。", ["空"]], "1528": ["病机", "原文谓“陈阳明脉空，厥阴风动”，脉空示阳明气血亏虚，不能充脉，故右肩臂渐及足跗痿躄；长夏气泄、秋不主收肃，皆因虚而气不固。阳明虚则筋骨失束，厥阴风动则痿躄由虚而生，显属虚症，故用通摄方法，以肝胃虚内风动为主。", ["空"]], "1529": ["病机", "原文未出脉名，然述“稚壮失血遗精，两交夏月四肢痿𤻊”，因冬主收藏、夏主发泄，内损多年不复元，阳明脉衰所致。失血遗精伤精耗气，至夏气泄则阳明脉衰，四肢失养而痿，指节不能屈曲，病机在肝胃虚、阳明脉衰。", []], "1530": ["病机", "原文未出脉名，述下焦痿躄先有遗泄湿疡，频进渗利致阴阳更伤；畏冷阳微、饭后吐食乃胃阳顿衰，外卫失职。下焦多属精血受伤，肾脏恶燥，久病宜通任督；又谓“阳明之脉束筋骨以利机关”，故病机为胃阳督肾皆虚，通摄兼施。", []], "1531": ["病机", "原文谓“下元络脉已虚”，脉虚应之；长夏湿热，经脉流行气钝，兼下元络虚，故痿弱不耐、步趋酸楚，大便或结或溏。湿热阻络与肝肾下虚并见，益下必佐宣通脉络，徒补恐湿热还扰，病机属湿热肝肾虚。", ["虚"]], "1532": ["病机", "脉沉而缓，寝食如常，独两腿内外肌肉麻木。五旬又三，阳脉渐衰，跷维不为用事，非三气杂感。沉缓示阳气不充、脉络不畅，跷维失用则肌肉麻木，故以温通佐脉络流畅，病机在阳脉渐衰、脉络不畅。", ["沉", "缓"]], "1533": ["病机", "原文未出脉名，述寝食如常而仪容日瘦，语言出声、舌络牵强，手足痿弱不堪动作。此肝肾内损，渐及奇经诸脉，乃痿痹之症。肝肾精血亏虚，奇经失养，故舌络牵强、手足痿弱，未能骤期速功。", []], "1534": ["病机", "右脉颇和，左关尺大而坚搏不附骨。春阳初萌，里真漏泄，左关尺大坚示肝肾阴亏、阳不潜藏，有风动枯痿之虑。坚搏不附骨为里真不固、虚阳外露之象，故议乙癸同涵，滋水涵木以潜阳。", ["大", "坚"]], "1535": ["病机", "原文谓“冲脉虚寒，浮火上升”，脉虚寒应之。右肢跗足无力如痿，子夜痰多呛嗽，带下且频，因冲为血海隶于阳明，天癸将绝，脉络少气，冲脉虚寒则浮火上升。非治嗽清热，宜通阳摄阴以实奇脉。", ["虚"]], "1536": ["病机", "原文言金疮去血伤营络，又嗔怒动肝、苦辛泄气致阳泄，形丰而收藏固摄失职，少腹约束、阳道不举、背脊喜靠、步履无力，皆痿弱症端。脉兼虚正示下元肾阳与奇脉之气虚衰，固摄无权，故以通纳涵养生真为法，非客邪实候。", ["虚"]], "1537": ["病机", "脉左沉小、右弦，两足腰膝酸耎无力、舌本肿胀、颈轰热、痰涎味咸，原文断为肾虚收纳少权、督脉不司约束、阴火上泛、内风齐煽。左沉小主下元虚衰，右弦主内风与阴火逆动，病根在下，久延痿厥，故通奇脉以收拾散越之阴阳。", ["沉", "小", "弦"]], "1538": ["病机", "脉濡弱而右大，心热烦渴，两足膝腰髀伸缩不得自如，原文定为下焦阴虚、热烁筋骨而为痿躄。濡弱示阴精不足、脉道失充，右大示虚热偏盛；下焦阴虚不能濡养筋骨，虚热内灼，故成痿躄，治以虎潜加减滋阴清热。", ["濡", "弱"]], "1539": ["病机", "原文未出脉名，述冬藏精气既少，春夏发泄则失血、遗精，筋弛骨痿不堪行走，精血内怯、奇脉中少气，三年久损。此以精血亏虚、奇脉失养为骨痿病机，若不绝欲安闲，将有偻废难状之疾，重在久损不复、筋骨失荣。", []], "1540": ["病机", "原文未出脉名，症如历节而汗出筋纵、痛以冬月为甚，腰脊伛偻形俯，且未病前梦遗已久，断为精血内损、无以营养筋骨，难与攻迫。此示督阳虚而精血亏，筋骨失温养，故以香茸丸温通太阳督脉，非风寒湿实邪可攻。", []], "1541": ["病机", "此段引经论痿，述肺热叶焦则生痿躄、治痿独取阳明，及脉痿筋痿肉痿骨痿之论，归旨于肝肾肺胃四经。原文未出具体脉象，而以肝伤筋拘、精虚血虚不养筋骨、肺虚高源化绝水涸、阳明虚宗筋纵不能束骨为病机，属痿症总论。", []], "1542": ["病机", "原文言经脉通而痛痹减，络中虚则痿弱无力、周身汗出、阳泄已多，不可再用苦辛伤阳泄气。脉虚正合络虚阳泄之机；引内经筋缓为阳明脉虚，示阳明气虚不能束筋骨，故当宗此旨以扶阳养络，而非攻痹。", ["虚"]], "1543": ["病机", "原文未出脉名，辨邪中于经为痹、中于络为痿；今痹痛全止而行走痿弱无力，是经脉受伤、阳气不为护持。此以络虚阳衰、筋骨失护为病机，法当温养通补，取春夏养阳、扶培生气之意，示痿由经伤阳弱而非邪实。", []], "1544": ["病机", "原文未载脉象，然述‘濒海飓风潮湿，著于经脉之中’成周痹，痹则气血不通，阳明不主司事，食腥腻不化而溏泻。此湿邪久着，正虚邪实，故不可急攻，宜缓图。病机为湿阻经脉、脾胃气弱，主周痹兼便溏。", []], "1545": ["主病", "原文未出脉，而言‘风湿发热，萃于经脉，肿痛游走’，病名行痹，即历节风。风性善行数变，湿性黏滞，风湿合邪客于经脉，气血痹阻，故肿痛游走。主行痹，症见发热、关节游走性肿痛。", []], "1546": ["病机", "脉小弱，小为阳虚，弱为气衰。长夏湿盛，卫阳单薄，三气（湿暑寒）易袭，故四肢痹痛、筋骨不舒。此卫阳不足、湿阻经脉之痹，主四肢痹痛，治先流畅阳明气血。", ["小", "弱"]], "1547": ["病机", "左脉如刃，阴亏阳亢；右脉缓涩，缓主湿，涩主气血滞。暑热为疟，水谷湿气下坠，肢末挛痹，便泻减食畏冷，阳明气衰极。此阴亏本质，湿滞经脉，阳明虚衰，主挛痹兼疟泻。", ["缓", "涩"]], "1548": ["病机", "原文未载脉，述湿痹脉络不通，苦温渗湿小效，但汗出形寒泄泻，阳气大伤。此湿邪久痹，阳气虚损，不可拘‘湿甚生热’常例，当通阳宣行以通脉络，使生气周流。主湿痹阳伤，症见汗出形寒泄泻。", []], "1549": ["病机", "脉小涩，小主阳虚，涩主湿滞血瘀。长夏湿胜气阻，不饥不食，四肢痹痛，痛甚于午后子前，色痿黄。此阳气被阴湿遏阻，经脉不通，主湿痹，症见纳呆、肢痛、面黄，治宜微通其阳，忌劫汗。", ["小", "涩"]], "1550": ["病机", "脉沉主里，湿邪久伏，阳气伤损，故目黄舌肿、周身疹发、胃痛、肢末肿强，遇冷饮凉即病。沉脉示病在里，阳伤不能运化水湿，湿郁化热外发疹黄。主久伏湿邪、阳伤络痹，症见肿强疹黄胃痛。", ["沉"]], "1551": ["病机", "原文未出脉，述右后胁痛连腰胯，发必恶寒逆冷，暖护良久乃温。此脉络中气血不行，凝塞为痛，乃脉络之痹，从阳维阴维论病。阳维主表，阴维主里，气血凝滞则恶寒逆冷，得温则减，主络痹寒痛。", []], "1552": ["病机", "左脉弦大为肝阳偏亢之象。原文言「劳怒动肝」，肝阳化风，阳气不交于阴，阳维阳跷失养，内风烁筋，故跗廉痹痛、暮夜为甚。弦主肝病、主痛，大示阳亢，脉症相合，病在脉络，属内风致痹之病机。", ["弦", "大"]], "1553": ["病机", "脉数右大，数为热，大为邪盛。原文谓「温渐化热，灼及经络」，气血交阻而为痹痛；阳邪主动故游走，阳动化风故肉腠浮肿。右大主阳明热盛，数示热灼，脉象反映温邪化热、灼络成痹之病机。", ["数", "大"]], "1554": ["病机", "脉大已减而右数未平，示邪势渐退而阳明余热未清。原文言「阳明之气未化，热未尽去，阴已先虚」，故痛缓什七而肌肤甲错发痒、腹满便不通。大减为邪衰，数存为热留，脉象提示热未尽而阴已伤，不可过剂。", ["大", "数"]], "1555": ["病机", "原文未载脉象，以「久痹酿成历节、舌黄痰多」立论。舌黄痰多示湿热内蕴，湿邪阻著经脉，久痹不愈而化为历节。此段从症测机，说明湿邪留着经脉、痰热互结为痹之病机，非凭脉断证。", []], "1556": ["病机", "右脉缓、左脉实，缓为湿滞，实为邪结。原文谓「湿热混处血络之中」，湿伤下先受之，内踝重著、阴维受邪，久则化热烁血、风动舍于肝胆。左实示血络邪阻，右缓示湿滞，脉象反映湿热入络、延为痿废之病机。", ["缓", "实"]], "1557": ["病机", "原文未出脉象，以「暑暍外加湿热、水谷内蕴湿热」论痹。外邪著经络，内邪著腑络，故辛解汗出而热痛不减。此段从病因推病机，说明暑湿与内湿相合、痹痿之根在阳明，非据脉立论。", []], "1558": ["病机", "原文未载脉象，以「冬月温舒、阳气疏豁」立论。风邪由风池风府流及四末，忽上忽下，以风为阳主动。诊视鼻明而知阳明中虚，卫阳疏而风邪入络。此段从时令症象推病机，说明卫外不固、风邪入络成痹。", []], "1559": ["病机", "原文未出脉象，以「症已渐安、脉络有流通意」言转机。引仲景「经热则痹，络热则痿」，知风淫于内，治以甘寒，寒去热而甘不伤胃。此段从症势与治法推病机，说明络热致痿、风淫于内当以甘寒清之。", []], "1560": ["病机", "原文未出脉名，以\"右指仍麻、行走屈伸不舒、戌亥心热烦蒸\"述症。前用杞归辛温养肝血熄风而右指仍麻，说明阳动风亦动，辛温反助阳化风；戌亥阴分心热烦蒸，为肝阴虚内热之征。故去辛用咸，取咸寒入血、柔肝熄风，兼虑疟邪留滞血络，佐通逐缓攻，病机在肝阴虚、风阳内动兼络滞。", []], "1561": ["病机", "原文\"脉中筋急\"，指脉道拘急不柔，为热入阴分血中之象。仲景谓经热则痹、络热则痿，今痹痛多日而脉中筋急，说明热邪已由气分深入下焦血分，血热则脉络拘急，故下焦为甚。上焦属气、下焦属血，脉急正是血分热灼、络脉失濡之征，主痹痛之因于热入血络者。", ["急"]], "1562": ["病机", "脉弦劲为风寒湿三气混入经隧、气血被阻之象。弦主痛主饮，劲则邪实拘急，故右足踝臁肿痛，得暖得摩稍适，正合寒湿得温则散之性。三气痹阻经隧，气血不通，脉道拘急而劲，主痹证之属实者，治当辛温宣通经气，使邪从隧络而出。", ["弦", "劲"]], "1563": ["病机", "原文未出脉名，述烦劳郁勃之阳化为热气内风，引《内经》热淫风消必用甘寒。酒客痰多食少忌甘腻，故先清少阳胆热，因酒气先入肝胆。今气热当午上冒，经络痹痛减于平日，说明肝胆风热渐清而胃气未和，主以和阳甘寒、宣通经脉，病机在肝胆风热上冒兼肠胃湿滞。", []], "1564": ["病机", "痹痛在下重著不移，似属寒湿，然左脉搏数、经月遗泄三四、痛处无形，则非六淫邪聚。数脉主热，遗泄日久则精血虚，阴虚生内热，故脉数而痛处无形，是精血亏虚、络脉失养之痹，非实邪。隧道深远药饵难达，佐艾灸以温通，病机重在精血虚而夹热。", ["数"]], "1565": ["病机", "脉右大而阳明空，右主气属阳明，大而中空为气不充脉之象。气短闪烁欲痛，正是气虚不能充脉、络脉失煦所致。阳明为多气多血之经，脉大而空说明气分虚馁，故见短气而痛，病机属气虚，非实热之大脉可比。", ["大"]], "1566": ["病机", "原文未出脉名，述筋纵痛甚、邪留正痹。筋纵则弛纵无力而痛甚，为邪气留滞、正气已痹之候。当此天暖，间用针刺宣脉络，初补气血之中必佐宣行通络，说明病机为气血不足而邪留筋络，正虚邪痹并存，故补中兼通，不可纯补纯攻。", []], "1567": ["病机", "脉沉小数，沉主里、小主虚、数主热，合为营中留热之象。热伏营分故脉沉而数，营阴受损故脉小；骱骨尚有微疼，是营热留滞经络骨节未清。治宜通经络佐清营热，使营分伏热得清、络脉通畅，则骨节微疼可除，病机属营中留热、络脉不和。", ["沉", "小", "数"]], "1568": ["病机", "原文未出脉名，但论痹病病机为“正气为邪所阻，脏腑经络不能畅达”，强调“气血亏损，腠理疏豁”致风寒湿三气乘虚外袭，留滞而成湿痰浊血凝涩。此非单一脉象可主，乃痹证总病机，与“重著沉痛”及行、痛、著痹等症相应。", []], "1569": ["病机", "原文未出脉象，述肾厥由“阴浊自下上犯，必循经而至”，足少阴经脉上循喉咙，故发时手足逆冷、口吐涎沫、喉如刀刺。病机为阴浊上逆、通阳被阻，主肾厥急症，与椒附通阳泄浊法相应。", []], "1570": ["主病", "脉左坚，经阻半载，戌亥阴时厥逆肢掣，逾时方苏，渴饮，便闭两旬。左坚主热结在血、阴分壅实，经阻与厥逆由热结血分、火郁上冲所致，故仿厥应下之义，用玉烛散咸苦清火通下。", ["坚"]], "1571": ["病机", "原文未出脉名，但诊脉时“两手牵掣震动”，乃津液受劫、肝风内鼓之象，为发痉之原。温热病神呆舌赤，瘦人阴亏，液劫风动，故议养胃汁、熄肝风，用复脉汤去参姜桂以存阴。", []], "1572": ["预后", "脉细促，神迷舌缩言謇耳聋，四肢牵引，病已月余。细为阴液亏耗，促为阳浮独行、内风大震，温邪劫液致痉厥危疴。脉细促示正虚邪陷、阴阳不相接续，故曰危，必得痉止神清方有转机。", ["细", "促"]], "1573": ["预后", "原文未出脉名，但言“脉来敛静”，神气稍苏，为邪退正复之兆；然五液交涸、风阳尚动，故用甘寒清补和阳去热，滋液救焚。脉敛静与津复风熄相应，可望向安，属预后转佳之象。", []], "1574": ["病机", "原文未出脉象，述少阴不藏，温邪深入，喘促汗出，渴不多饮，舌辛似缩。病机为邪少虚多、少阴根气不固，温邪内陷迫肺，故喘汗；液亏不能上承，故渴不多饮、舌缩。用复脉汤去姜，主虚多邪少之候。", []], "1575": ["病机", "原文未出脉象，舌绛汗泄、齿燥痰腻，为热劫津液、阴伤风动之征。舌绛主热入营血，汗泄为阴不内守，齿燥痰腻示液涸痰聚，最防痉厥。故用复脉汤去姜桂，以甘润存阴、潜阳熄风，属病机与防治之论。", []], "1576": ["病机", "脉细劲为真阴枯槁、风木大震之象。患者肠红日久，阴络久伤，左胁下宿瘕，肝家风气易结，形瘦面青，阴虚阳冒，冲气犯胃为呃，症似蓄血为狂。细为阴亏，劲为风动，阴液无有，风木鸱张，故刚剂强镇不能熄其厥冒。", ["细", "劲"]], "1577": ["病机", "脉芤弱主肾真内怯、精血亏虚。患者肝风痫厥迅发莫制，平素多遗，肾精不固，下元虚惫，故脉芤而弱。芤为血虚，弱为气衰，肾真内怯则肝风易动，痫厥由生。议用固本丸加味，固摄下元，填精益肾，以制肝风。", ["芤", "弱"]], "1578": ["病机", "原文未识脉名，然述少腹气攻有形、呕吐头胀、四肢逆冷，显系厥阴寒厥之象。厥阴脉上至巅顶，环绕阴器，寒浊循经上逆则头胀呕吐，阳气不达四末则肢冷，肝脉失约则为遗泄。非疟母宿冷，乃厥阴寒厥为患。", []], "1579": ["病机", "右脉已伏，左小紧，四肢冰冷，干呕烦渴，此厥阴浊泛、胃阳欲绝之痛厥。伏为阳气闭阻，小紧为寒浊内结，阳衰不能布达则肢冷，浊阴上逆则干呕烦渴。故以辛热泄浊通阳，救胃阳之欲绝。", ["伏", "小", "紧"]], "1580": ["病机", "脉微为无阳，下利冷汗，呕逆不食，肢厥不回，一团浊阴阻蔽，有闭脘之危。微为阳气衰微，阴寒内盛，阳衰不能温煦则肢厥，浊阴上逆则呕逆不食，阳气外脱则冷汗。议四逆之属护阳驱浊，急温回阳。", ["微"]], "1581": ["病机", "脉小弦，舌白无胎，先寒战后发热，心中极热，干呕烦躁，渴饮冷不解，曾肢冷如冰，此热邪入厥阴肝经，热深厥深。小为阴伤，弦为肝热，热邪深伏，阳郁不达则肢冷，热结于里则烦躁渴饮。议紫雪丹开深伏之热结。", ["小", "弦"]], "1582": ["预后", "脉两手俱细，是阳极似阴，热邪深走厥阴，发厥，鼻煤舌干，目眦黄，多属邪闭坏败。细为阴伤，热邪内闭，阳不外达故脉细，非真阴寒。热深厥深，邪闭心包，故昏烦头痛，谅难挽回，用凉膈散以冀万一。", ["细"]], "1583": ["病机", "室女经来，冲脉自动，动则阳升，内风绕旋不息，为薄厥煎厥。阳明虚胃失降，厥阴热肝愈横，风阳上冒，清空神迷，诸窍似阻。脉自动乃冲脉不宁、阳升风动之征，本虚表实，先理其实，用龙荟丸纯苦直降。", ["动"]], "1584": ["病机", "脉虚小为气血不足之象，结合望色㿠白，知肝病犯胃致呕逆腹痛，然怀妊而病不发，乃中气尚能砥柱。虚小脉提示胃土虚弱，肝木乘之，故治以六君子培植胃土，佐芍药木瓜抑肝。", ["虚", "小"]], "1585": ["病机", "脉空乏因经水适来，血海骤虚，冲脉失养，风阳乘虚交动而厥。冲脉隶阳明，阳明虚则失阖，厥气上犯莫遏。脉空乏正是冲任空虚、下焦独冷之征，故取小半夏汤通补阳明以制肝侮。", ["空", "乏"]], "1586": ["病机", "脉右大主热升风动，郁冒为厥。右脉候气，大则阳亢化风，风热上扰清窍。奇脉虚而风阳动，故宗陈无择羚羊角散凉肝息风。脉大在此非实热壅盛，乃虚风内动之象。", ["大"]], "1587": ["病机", "原文未识脉名，然述经水两至、痛自下焦冲突而厥，病由阴维冲任失司。八脉不固，营血亏虚，冲气上逆致厥。前治养营仅到中宫，未及奇经，故无效。此段重在明冲任虚损之病机。", []], "1588": ["病机", "脉数而厥止，知热不在肝胃而在营中。数脉主热，营热内扰则厥虽止而热未清。心主营，营热故脉数，治当清心营之热，非徒治厥也。", ["数"]], "1589": ["病机", "脉左动如数，右小濡弱，左候肝，动数乃阳动化风；右候气，小濡弱为气阴不足。病起嗔怒，诸阳皆动，内风为厥。肝藏魂，阳动则魂不守舍，故神魂散越。脉象示下焦肝肾虚而风阳扰，治当镇固收摄。", ["动", "数", "小", "濡弱"]], "1590": ["病机", "原文未识脉名，述冷自足上贯心、口鼻冷气，病起惊恐，内伤肝肾。冲脉隶肝肾，二脏失藏则冲气沸乱，脉气由至阴上逆，故多冷。此肝肾虚而冲气上逆之厥，脉虽未载，病机昭然。", []], "1591": ["病机", "原文未识脉名，论厥痉由气血日偏、阴阳一并而发，如风雷郁极。发而渐复可安，转逆则危，存亡在命脏盈亏。列举吐、清、开降诸法，示厥证病机复杂，当辨痰食、壮火、气厥等因。", []], "1592": ["病机", "原文以「脉络滞涩」言惊则伤胆、恐则伤肾，惊急恐缓，小儿神志未坚、胆气未充，猝然受惊则心猝及胆、胆即及肝，君火与肝胆相火风木骤起，故见搐搦瘈疭、神昏谵妄、肢冷厥逆等。脉络滞涩正示惊动内风、木火沸起而气血运行不畅，非外感风邪，故以惊字立病名，加风字明内风之动。", ["滞", "涩"]], "1593": ["病机", "原文「神呆脉沉，因惊恐以致痫疾，语言不甚明了」，脉沉主里、主痰火内阻。惊恐动火生痰，痰火阻其灵窍，故神呆而语言不明。沉脉不浮，说明病不在表，乃痰火郁闭于里、灵窍不利之痫疾，故戒酒肉厚味、静室善调，经年可愈。", ["沉"]], "1594": ["病机", "原文「惊恐，阳升风动，宿痫遂发，吐痰呕逆不言，络脉失利也」。虽未识脉名，但所述阳升风动、痰随气逆而吐呕、机窍不利而不言，皆因惊恐引动阳气上逆、风痰阻络，旧痫复发。病机在阳气郁而上升、窍络被阻，故见吐痰呕逆与言语不利。", []], "1595": ["病机", "原文「惊狂，乃木火扰动，虽得平静，仍心悸怔忡，夜卧不寐，诊脉虚细如丝，已非痰火有余」。脉虚细如丝，示木火扰动之后心神已虚、气血不足，故心悸怔忡、夜卧不寐。虚细非痰火实脉，故议补心丹以理心之用，属由实转虚之病机。", ["虚", "细"]], "1596": ["病机", "原文「癫疾，脉不鼓指，议交心肾，益神志」。脉不鼓指说明火郁于内而脉气不能鼓动于外，非实火亢盛之象。火郁则心肾不交、神志不宁，故以交心肾、益神志为治。此段主旨在于从脉不鼓指辨火郁心肾不交之病机。", []], "1597": ["病机", "原文以天地阴阳偏胜喻人身，引《内经》「重阳者狂，重阴者癫」，说明痫与癫原则相同，皆阴阳偏胜所致。狂多躁而常醒、妄言妄笑，癫多静而常昏、如醉如痴，痫则卒然昏仆、筋瘛疭、口中作声。此段重在辨癫痫狂之阴阳病机，非专论脉候。", []], "1598": ["病机", "原文「常有衄血，今夏忽起神识如呆，诊脉直上鱼际，大忌惊恐恼怒，天癸得通可愈」。脉直上鱼际示胆火上升、心营有热，火升则神识如呆；素有衄血亦为火升迫血之征。故忌惊恐恼怒以防火动，待天癸得通、阴血下行则火降可愈，病机在胆火上升、心营热。", []], "1599": ["病机", "原文「脉左数，衄血火升」，左脉候肝胆，数主热。左数说明肝胆火升、阴虚阳冒，火升迫血妄行故衄血。数而见于左，示阳热偏亢于阴分，阴不制阳而阳气上冒，故以阴虚阳冒概其病机，与衄血火升之症相应。", ["数"]], "1600": ["病机", "脉数为阳热亢盛之象，此案阴亏于下，阳无所附而升越，故脉数。阴亏阳升，上扰清窍则头晕，扰及心神则心中烦杂，阳热迫血妄行、从清道而出则鼻衄。数脉在此标示阴虚阳浮、虚火上炎之病机，与头晕、心烦、鼻衄三症相应。", ["数"]], "1601": ["病机", "原文未出脉名，专论衄血病机。指出衄血总由乎火，外因六淫变化、内因五志掀腾，致气血错乱、阴阳相乘。清道指山根以上睛明之次，为手足太阳、足阳明、阴阳跷五脉之会及冲脉交会处，故诸经皆能为衄，不独肺胃。强调天人交感处须分虚实，为辨证之要。", []], "1602": ["病机", "原文未出脉名，论七疝治法及病机。疝病根在奇经，任脉为病，男子内结七疝。辛香泄肝仅治气实，参术升补仅治中虚下陷，与元海奇经中病无补。壮岁至老病根不辍，下焦日衰，升阳一法体症颇合，衰年仅可撑持。末注督任阳虚，点明病本在奇经阳虚。", []], "1603": ["病机", "脉之凝涩，主气血凝滞、经脉不通。脐下少腹形象横梗，发必痛绕胁腰及阴囊，乃厥阴肝气不宣、气滞血凝所致。凝涩之脉正合经脉凝涩之病机，故议苦辛加左金，佐通经脉之凝涩，以辛开苦降、行气通络为治。", ["涩"]], "1604": ["病机", "脉右弦左涩，弦主肝气郁滞，涩主凝聚有形。当脐痛连少腹，已属凝聚有形；呕吐黄浊、大便欲解不通，为肝气犯胃、气机壅滞。患处漉漉有声、卧著体不转移而痛更加，皆气结血凝之征。此属肝气疝瘕，故以辛香流气，通则不痛。", ["弦", "涩"]], "1605": ["病机", "原文未出脉名，注奇脉阳虚。动气疝瘕绕脐汨汨有声，男子精气不充，是下焦损伤、奇经阳虚，气不归元而筑动。治当温补，然勿过刚燥，须察八脉以推病情，点明病本在奇脉阳虚而非单纯气滞，故温补须柔润，兼顾奇经。", []], "1606": ["病机", "原文未出脉名，论疝瘕成因。久久劳怒则肝木内震，胁中少腹皆肝脉游行之所，气凝聚为胀，聚久结形为瘕疝。情怀忧郁，情志内起，非草木微功可愈。指出病机在肝气郁结、气聚成形，与情志密切相关，故治疗须重情志调摄。", []], "1607": ["病机", "原文未出脉名，论七疝在肝。冲脉为病，冲隶阳明，肝木必乘克胃土，胃翻涌逆，致吐蛔呕涎、汤饮不入、呃忒不止，皆逆乱无已，为脏厥危疴。肝体本刚，相火内寄，一派热燥药饵以刚济刚，有缺折之虞。欲泄其浊，拟用朱南阳法，示人慎用刚燥。", []], "1608": ["病机", "原文未识脉名，仅言「形体参脉」，从形体与脉合参而知「湿热内蕴阻塞」，故二便不通爽。疝多属肝病，宜辛泄，然此例非单纯气结，乃湿热壅阻下焦、太阳腑气不利，故先以通太阳为治，脉象虽缺，病机重在湿热内蕴、阻塞不通。", []], "1609": ["病机", "脉沉主里，沉而兼痰多、手骱赤疮、宿疝在下、右胁气坠少腹，显系湿热久聚沉痼，非皮膜经脉之壅。前用控涎丹逐痹未应，说明病位深在腑聚，故用浚川丸通腑。脉沉正合「久聚湿热沉痼」之里实病机。", ["沉"]], "1610": ["病机", "原文未出脉，以症测机：痛自肾囊渐踞少腹之左，厥阴之脉绕阴器，操持谋虑伤肝，一气结聚变幻为痛，病名曰疝。暴疝多寒、久疝多热，此例泄气痛缓，知为气热湿郁下焦，故用川连、山栀清湿热，小茴、橘核、川楝理气散结。", []], "1611": ["主病", "脉沉弦，沉主里、弦主痛主肝，舌灰边白、腰跨气痛、肾囊睪丸肿大，显系湿热下坠为疝。前医乱用发散消导，反使湿热下坠，故治当分消，使湿热从上下分利。脉沉弦正合湿热壅阻下焦、肝经气滞之疝病。", ["沉", "弦"]], "1612": ["病机", "原文未出脉，以症言机：厥阴三疟久延，邪攻肝经络脉，少腹痛渐硬、气串绕阴器筋痛，乃结疝瘕之象。病久虽少壮不可专于泄气，因疟邪久羁、气血两凝，故以温肾宣肝为急，脉象虽缺，病机重在久病入络、虚实夹杂。", []], "1613": ["病机", "原文未出脉，以病史言机：疟母十年，沉痼宿疴，药不能效，因疟邪久与气血两凝、结聚络脉，药难入络。疟不离肝胆，疝不外乎肝病，虚质不可专以辛香，下坠为甚，故议有情温通以培生气。病机为久病络瘀、气血两凝而兼虚。", []], "1614": ["病机", "脉弦而紧，弦主肝主痛，紧主寒主收引。原文历引《素问》《灵枢》诸经之疝，说明疝之成与任督、肝、脾、肾、阳明、太阴、厥阴诸经皆相关，而仲景独以寒疝为名，出方以温散为主。脉弦紧正合寒邪收引、肝经气结之疝病病机。", ["弦", "紧"]], "1615": ["主病", "脉左弦数，左主肝胆，弦主肝经气火，数主热。右偏头痛、左齿痛，显系肝胆风火上扰，循经上攻头齿。脉弦数正合肝火偏亢、风阳上扰之病机，与偏头痛、齿痛症候相应，治当清泄肝胆风火。", ["弦", "数"]], "1616": ["病机", "原文言“某高年气血皆虚。新凉上受。经脉不和”，虽脉象写法为“脉不和”，但未具体描述脉形，故脉象要素为空。病机为高年气血两虚，新感凉邪，致经脉气血运行不和，筋脉失养，故脑后筋掣牵痛，倏起倏静，属阳风之邪为患。", []], "1617": ["误治", "原文未识出脉名，但言“既知去血过多。为阴虚阳实之头痛。再加发散。与前意相反矣”，指出血虚阳浮之头痛，误用发散则更伤阴血，使阳气愈浮。故脉象要素缺如，主旨为误治之戒。", []], "1618": ["病机", "原文“脉数虚而动。足征阴气大伤。阳气浮越。头痛筋惕”，数脉主热，虚脉主不足，动脉主惊动，合而观之，乃阴气大伤，阳气浮越，虚风内动之象，故见头痛筋惕，治以镇摄之法。", ["数", "虚", "动"]], "1619": ["病机", "原文未识出脉名，通论头痛病机，谓“头为诸阳之会……故头痛一症。皆由清阳不升。火风乘虚上入所致”，并分述阳虚浊邪阻塞、火风变动、阴虚阳越、厥阳风木上触等证治，脉象要素缺如，主旨为病机。", []], "1620": ["兼症", "原文“脉细数。闻雷被惊。心下漾漾作痛”，细脉主阴血不足，数脉主热，惊则气乱，肝阳上逆，故心下漾漾作痛，治以逍遥散去柴胡加钩藤丹皮，养血平调。", ["细", "数"]], "1621": ["预后", "原文“脉左涩伏。心下痛甚。舌白不能食谷。下咽阻膈。痛极昏厥。此皆积劳损阳。前者曾下瘀血。延绵经月不止。此为难治”，涩脉主血滞，伏脉主邪闭，左脉候血，积劳损阳，瘀血内阻，故痛甚昏厥，下血不止，预后难治。", ["涩", "伏"]], "1622": ["主病", "原文未识出脉名，述“心痛引背。口涌清涎。肢冷。气塞脘中。此为脾厥心痛。病在络脉。例用辛香”，乃脾寒厥逆，病在络脉，故心痛引背、肢冷、口涌清涎，治以辛香开通。", []], "1623": ["其他", "原文未识出脉名，辨析厥心痛与胃脘痛之异同，并列举闻雷被惊、积劳损阳、脾厥心痛等证治，强调“厥心痛。为五脏之气。厥而入心胞络”，脉象要素缺如，主旨为学术辨析，故归其他。", []], "1624": ["病机", "原文未出具体脉象，仅言“阳明经脉失和”。病由肝脏厥气乘胃入膈，气逆填胸阻咽、脘痹而痛，周身掣痛夜甚昼缓，因戌亥为肝旺之时。此属肝厥气逆、阳明经气不和之病机，多从惊恐嗔郁而发，失治可变为昏厥，故以病机为主。", []], "1625": ["病机", "脉左数，左主血分，数主热，痛缓而夜深复炽、前后心胸板掣，说明热郁血络、络气不通。病在血络中，故痛处板掣而夜甚，非单纯气分之痛。数脉在此示络中郁热，与心胸板掣、痛势反复相应，属血络病机。", ["数"]], "1626": ["病机", "脉细弦右涩，细为阴血不足，弦为肝木偏旺，涩示胃络不畅。产后三年经水不转、胃痛得食必呕、汗出形寒、腰左动气，是厥阴肝木顺乘阳明，胃土久伤而肝木愈横。弦细涩并见，正合肝横胃弱、络脉不和之病机，故主辛酸两和厥阴、通补阳明。", ["细", "弦", "涩"]], "1627": ["病机", "原文未出具体脉象，仅言“久病络脉空隙”。天癸当绝仍来、昔年头晕、今春悲哀后麻木头眩、膝胫冷、痛引背胁，是情志郁勃、厥阳热气乘络，内风旋动袭阳明，致呕逆不能进食。络脉空隙而肝风犯胃液虚，故以病机为主。", []], "1628": ["病机", "脉得左大右小，左大示肝木偏亢，右小示胃土不足。胃痛屡发、纳物呕吐酸苦、完谷而出、呃逆热汤不减、不嗜汤饮，是肝木侮胃土、胃阳虚而气掀腾如沸，兼凝痰聚瘀留于脘底。左大右小正合肝犯胃兼痰饮之病机，故用药远柔用刚。", ["大"]], "1629": ["病机", "脉濡小无力，濡小为阳气不足、脾胃虚弱之象。壮年面色痿黄、胃脘常痛、情志不适即发、饮暖酒暂解、食物不易消化，是脾胃之土受克，肝木来乘。濡小无力说明中阳不振，故属郁伤脾胃阳虚之病机，怡情放怀可愈。", ["濡", "小"]], "1630": ["病机", "脉弦涩，弦主肝郁气滞，涩主血行不畅。胃痛绕背、谷食渐减、病经数载，说明气滞日久入于胃络，络脉瘀阻。弦涩并见，正合久痛入络、气血痹阻之病机，故与辛通法以通络行滞，属病机分析。", ["弦", "涩"]], "1631": ["病机", "原文未出具体脉象，仅言“脉络牵掣不和”。阳微不司外卫，胃痛夏秋不发而冬寒骤加，说明阳气不足、卫外不固，寒邪外袭致脉络牵掣。病机在阳微寒凝、络脉不和，故宜急护其阳，用桂枝附子汤温阳通络，属病机为主。", []], "1632": ["主病", "脉耎即软，主胃气虚弱。背寒为阳气不布，食入脘痛乃胃虚受纳无力、气机壅滞。脉软示中阳不足，不能温煦背俞，亦无力运化水谷，故食入即痛。此非实邪，乃虚寒之象，与背寒、食入脘痛症候相应。", ["耎"]], "1633": ["病机", "脉弦硬为肝木乘土、气机郁滞之象。努力伤气，饥饱失时损胃，冷酒凝滞，致中焦气阻血涩。弦主痛、主肝，硬示郁结不柔，故中脘痛。此脉说明胃络痹阻、肝胃不和，与努力、饥饱失时、好饮冷酒之病因相应。", ["弦", "硬"]], "1634": ["病机", "脉右弦，右关候脾胃，弦主饮邪内阻、气机不宣。不饥、纳谷不运、吞酸，皆浊饮停聚中焦，胃阳被遏之征。弦脉示饮浊尚阻，阳气仍不宣通，故纳运失职。此段以脉弦点明饮阻气滞之病机，与不饥、吞酸症候相应。", ["弦"]], "1635": ["病机", "脉虚涩，虚为气弱，涩为血少行滞。胃痛日久，气血两伤，血络瘀痹，故治在血分。虚涩并见，示正气已亏而瘀阻络脉，非单纯气分病。此脉说明久痛入络、血瘀气馁之病机，与胃痛久、血络瘀痹相应。", ["虚", "涩"]], "1636": ["病机", "诸脉逆乱，非阳微欲脱之虚脱脉，乃痰因气滞、气阻血瘀，络脉痹窒所致。频吐污浊而便反秘，是瘀浊内聚、气机逆乱之征。脉乱示病在络、气血不通，非阳气无形之衰。此段辨明肝病络瘀之机，与呕吐肢冷、便秘症候相应。", ["逆", "乱"]], "1637": ["病机", "原文未识脉名，然述久有胃痛更加劳力，致络中血瘀、经气逆，患在络脉痹窒。形瘦清减示瘀久伤正，攻里攻表皆置病不理，故无效。此段主旨在明病位在络、瘀阻气逆之病机，与胃痛、形瘦清减症候相应。", []], "1638": ["病机", "脉弦涩，弦主痛、主气滞，涩主血瘀。经事不至、寒热、胃痛拒格、呕恶不纳，乃久病胃痛，瘀血积于胃络，冲任受阻。弦涩示瘀滞不通，故议辛通瘀滞法。此脉说明胃络瘀积之病机，与经闭、胃痛拒格症候相应。", ["弦", "涩"]], "1639": ["病机", "脉小涩，小为气弱，涩为气滞不行。豆食闭气，浆凝为腐，食已脘痞痛胀，乃清气之阻。小涩示气机壅塞、清阳不展，非大实大虚。舌白黏腻佐证湿浊内停。此脉说明气阻脘痞之病机，与食已痛胀、舌白黏腻相应。", ["小", "涩"]], "1640": ["病机", "原文述阳明为十二经之长，痛因多端。脉长示经气尚充，脉络枯涩为营血虚少、络脉失濡，脉滑则示痰食内滞。三者并见，说明胃痛有虚有实：素虚劳伤者营虚络涩，饱食痛甚者滑主谷滞。故治有宜补不宜补之分，辛香理气与辛柔和血为对待之法。", ["长", "涩", "滑"]], "1641": ["病机", "劳怒引动阳气，左胁闪闪、腹中微满，诊脉弦搏且左甚。弦为肝脉，搏则气逆阳亢，左部应肝，故知肝阳化风、气火内郁，络脉壅急。当先用苦辛以泄降，正合「劳怒阳动」之因，非虚寒胁痛可比。", ["弦", "搏"]], "1642": ["病机", "痛从中起绕及右胁，得食自缓，是胃络受伤；每于下午黄昏阳气渐衰时发，说明络中阳虚寒滞，得食则谷气暂充而痛缓。原文未出脉，以时症推病机为络虚寒凝，故取辛温通络，使阳气复而络脉通。", []], "1643": ["病机", "右胁有形攻心、呕吐清涎、周身寒凛，痛止寂然无踪，是寒邪入络、气乘填塞阻逆之象。清涎与寒凛皆阴寒之征，痛止无踪说明气行则通、气滞则塞。原文未出脉，以症测机为寒凝络气，故用辛香温通以散寒行气。", []], "1644": ["病机", "嗔怒动肝，寒热旬日，左季胁痛难外舒转，是肝郁日久、血络瘀痹。瘀阻络脉则痛处固定、转侧不利；防有见红，乃瘀久伤络、血不循经之兆。原文未出脉，以病因症候推为血络瘀痹，故宜静调勿劳，使气平瘀行。", []], "1645": ["病机", "胁痛游走、渐至痰多、手足少力，初病两年寝食如常，入夏病甚，说明病由经脉继及络脉。经主气、络主血，久病血瘀从便下，是瘀血内结之征。诸家忽寒忽热治之无效，因未分经络；服新绛小效，乃络方通络之验。", []], "1646": ["病机", "诊脉动而虚、左部小弱，左胁疼痛上引、得食稍安，是操持太甚损及营络。动为阳扰，虚小弱为营血不足，左部应肝，故知五志之阳动扰不息，久痛津伤而嗌干舌燥心悸。症固属虚，然参术归芪未能治络，当以辛甘润温柔肝济刚。", ["动", "虚", "小", "弱"]], "1647": ["病机", "右弦左小弱涩，病起积劳伤阳、操持索思，五志皆逆。弦为肝旺，小弱涩为营气不足，左部应肝，故先胁痛；晡暮阳不用事则剧。日饵辛燥致气泄血耗，六味滋腻非止痛之方。病久及阳明胃络，肝胃同病，议甘药少佐摄镇。", ["弦", "小", "弱", "涩"]], "1648": ["病机", "原文未出脉名，专论胁痛归属。胁居少阳之部，故伤寒胁痛在胆经；肝脉布于胁肋，故杂症胁痛属厥阴肝经。所列旋覆花汤、金铃子散及辛温通络、甘缓理虚、温柔通补、辛泄宣瘀诸法，皆治肝著胁痛之剂。然症有虚实寒热，不可概论，须详审而扩充之，方临症有据。", []], "1649": ["病机", "脉数按之涩，数主热主急，涩主气机阻滞。腹痛呕吐而见数涩，非单纯虚寒，乃痧秽之邪格拒于中，气分壅塞不通。上中二焦气阻，故宜宣通气分，使秽浊得泄、气机得畅，则痛呕可平。涩为气阻之征，数因邪郁而急，二者合参，明非虚证。", ["数", "涩"]], "1650": ["病机", "脉沉微，沉主里主阴，微为阳气衰微之象。腹痛欲大便，乃阴浊内凝、腑阳不通所致。阳气积衰，不能温运，故阴寒浊邪盘踞中焦。治必以辛热通阳，使阳气复振、阴浊得散，则腑气通而腹痛止。沉微并见，正示阳衰阴盛之机。", ["沉", "微"]], "1651": ["病机", "脉来沉而结涩，沉主里，结涩主血行瘀滞不畅。小便自利而大便黑色，当脐腹痛十五年渐甚，显系郁勃伤及肝脾之络，血败瘀留。劳役动怒则宿疴复发。冬深闭藏，忌用攻下，故议辛通润血，取通则不痛之义。结涩正瘀血内凝之脉征。", ["沉", "结", "涩"]], "1652": ["病机", "原文未出具体脉象，然言辨色脉之衰旺以究痛因。腹痛分无形有形：寒凝火郁、气阻营虚、暑湿痧秽为无形；蓄血食滞、症瘕蛔蛲内疝为有形。在脏以肝脾肾为主，在腑以肠胃为先。通字非专指攻下，建中、理中、厚朴温中及吴茱萸汤、四逆、左金等，皆示通阳泄浊、清火泄郁之法。", []], "1653": ["病机", "左脉忽现芤涩，芤主营血虚而脉道不充，涩主脉络滞涩，虚脉亦示不足。痛时筋挛绕掣耳后，乃营虚脉络失养、风动筋急之候。前用清络凉剂不应，因营虚不受辛寒。故仿东垣舒筋汤意，以温养营血、舒筋缓急为治，脉象正示营虚为本。", ["芤", "涩", "虚"]], "1654": ["病机", "原文未出脉象，述五旬又四阳明脉衰，肩胛筋缓不举而痛。阳明主润宗筋，脉衰则气血不充，筋脉失养，故缓纵不举而痛。治当通补脉络，补其不足、通其痹滞，莫进攻风之品，以免耗伤已衰之气血。此以年岁脉衰立论，明虚痛不可妄攻。", []], "1655": ["病机", "原文未出具体脉象，仅言形脉不足。左指胀痛引肩，男子血虚风动，病在肝。形脉不足示气血亏虚，肝血不足则筋脉失养，虚风内动而胀痛牵引。故以柔药温养，柔肝养血、温通脉络，使血充风息则痛止，不可作实风攻散。", []], "1656": ["病机", "原文未载脉象，以“肾气攻背项强、溺频且多”点明督脉不摄、肾气上逆。督脉贯脊属肾，肾气不固则溺频，督脉失摄则项强腰重、难以转侧。病本在少阴肾与督脉，先与通阳宗许学士法，是温通督阳以散攻冲，非外邪项强。", []], "1657": ["病机", "原文无脉，专论冲气攻痛之病机归属：从背而上者系督脉主病，治在少阴；从腹而上者系冲任主病，治在厥阴，或填补阳明。以攻痛起处辨奇经所属，背属督脉、腹属冲任，故分少阴、厥阴论治，示人治病宗旨。", []], "1658": ["病机", "脉芤主血虚，汗出失血则阴血外夺，络脉空虚，故背痛。芤为浮大中空，如按葱管，正合失血后络虚之象。原文“此为络虚”直指病机：血去络空，失于濡养，不通而痛，非实邪阻滞。", ["芤"]], "1659": ["病机", "原文以“虚脉”统言肩背臂痛之因：肺病不能管摄一身则肺俞痛，阳明亏则肩垂背曲，臂痛责之阳明。痛分内外两因、虚实迥异，营虚脉络失养、劳倦伤阳脉络凝塞皆属虚，故脉虚主气血亏虚、络脉失养之病机。", ["虚"]], "1660": ["病机", "脉虚身热，似外感而实非。腰髀皆痛、少腹有形攻触，是脏阴亏虚、奇脉交伤，虚阳外浮故身热。原文明言“不可作外感治”，点出脉虚为正虚本质，身热乃虚热，攻触为奇经气逆，病在肝肾阴分。", ["虚"]], "1661": ["病机", "脉涩主血少气滞、脉络不宣。腰髀环跳悉痛，烦劳即发，因下焦空虚，络脉失充，涩脉正应络虚血滞之机。原文“络虚则痛”一语破的：虚而兼滞，劳则气耗血涩，故痛随烦劳而作。", ["涩"]], "1662": ["病机", "脉细色夺，细为阴血不足，色夺为精血外衰，合参则肝肾虚损明矣。腰为肾府，肝肾亏虚，络脉失养，故腰痛。原文点明“是络病治法”，示虚在络脉，当以柔养通络为治，非峻补肝肾之脏。", ["细"]], "1663": ["病机", "老年腰膝久痛，牵引少腹两足，不堪步履，原文归为“奇经之脉，隶于肝肾为多”。未载脉象，以症测机：年高肝肾精血亏虚，奇经失养，冲任督带不能约束，故痛引少腹两足，病本在奇经而根于肝肾。", []], "1664": ["病机", "脉迟缓为阳气不足、湿浊内凝之象。饮酒便溏、遗精数年，腰髀足膝坠痛麻木，皆脾肾之阳受伤，湿邪凝滞下焦所致。迟主阳微，缓主湿滞，湿凝则阳气不运，故滋填固涩无效，当先以苓姜术桂汤驱湿暖土，使湿去阳复。", ["迟", "缓"]], "1665": ["病机", "脉弦而数，弦属厥阴肝木，数主热。两足皮膜抚之则痛，由厥阴肝气犯阳明胃土，胃厥气逆所致。弦为肝旺，数为郁热，肝木横逆则胃气不降，故治当疏泄，使厥阴之气条达，阳明胃气自和。", ["弦", "数"]], "1666": ["病机", "原文未出脉名，以症测机。饱食则哕为胃病，两足骨骱皆痛，乃阳明胃脉不司束筋骨。胃主受纳，饱食则气逆而哕；阳明主润宗筋，胃脉不司则筋骨失束而攻痛。故议转旋阳气法，使胃气通降，阳气流转。", []], "1667": ["病机", "脉小弱为气血不足之象。老人右足患处麻木筋强微肿，冬病至长夏，食不加餐，皆气血不得宣通、脾胃虚弱所致。小弱主正气衰少，无力推动宣通，故络脉痹阻而麻木筋强，治以温养，使气血渐复。", ["小", "弱"]], "1668": ["病机", "此段论腰痛以肾为主病，分内因、外因、不内外因。肾阳亏则益火消阴翳，肾阴夺则壮水制阳光；寒湿伤阳用苦辛温通阳泄浊，湿郁生热用苦辛胜湿通气；劳役伤肾则先后天同治。虽未出脉，然脉象当随虚实寒热而辨。", []], "1669": ["病机", "原文未出脉名，而言有年色脉衰夺。络虚则痛，因络脉空虚失养而痛，非香蔻劫散可效。年高色脉衰夺，正气已亏，医不明治络之法，妄用劫散则愈治愈穷。此示络虚当以补养通络为治，不可峻攻。", []], "1670": ["病机", "脉不浮，非外感也。痛则气乱发热，头不痛、不渴饮，皆里证气机紊乱之象。浮脉主表，脉不浮则邪不在表，故非外感。气乱发热由内伤气滞所致，暂用金铃散一剂以行气止痛，非解表之法。", ["浮"]], "1671": ["病机", "脉小涩，小主气血不足，涩主血行不畅。久因悒郁，脘痛引及背胁，病入血络，经年延绵；更兼茹素数载，阳明虚馁，肩臂不举。郁久入络，血涩不行，阳明虚则筋脉失养，故缓调为宜，议通血络润补，勿投燥热劫液。", ["小", "涩"]], "1672": ["病机", "脉数而细，数主热，细主阴伤。原文谓“高年脂液久耗”，根蒂先亏，内乏藏纳，相火寄于肝，龙火起于肾，并从阴发越，故脉数细。此脉主阴亏伏热，症见忽痛必热肿且痛来迅速，治以滋肾丸泻阴中伏热。", ["数", "细"]], "1673": ["病机", "原文未出脉象，而言“痛为脉络中气血不和”，医当分经别络。肝肾下病，必留连及奇经八脉，故脉络不和。此段主病机在气血失和、奇经受累，症见痛，治当分经别络，非独治肝肾。", []], "1674": ["病机", "脉来小促数，小主虚，促数主热。壮年风温咳嗽，继以耳聋，苦降滋阴不效，是明虚实经络之误。膏粱厚味助上痰火，火郁上焦，故脉促数。此脉主上焦痰火，症见耳失聪，治以茶调散。", ["小", "促", "数"]], "1675": ["病机", "脉数主热，舌白为暑湿，左耳聤痛为暑风上攻。体质阴虚，挟受暑风，上焦气热，故脉数。此脉主暑风客热，症见耳痛舌白，治宜辛凉轻药，清上焦气热。", ["数"]], "1676": ["病机", "原文未出脉象，而言大声喊叫致右耳失聪，外触惊气，内应肝胆，胆脉络耳，震动火风之威，郁而阻窍。此段主病机在惊气动火、胆络郁阻，症见耳聋，治在少阳，忌食腥浊。", []], "1677": ["病机", "原文未出脉象，而言耳聋咳嗽、形体日瘦，男子真阴未充，虚阳易升乘窍。胆络脉附耳，故先议清少阳郁热。此段主病机在阴虚阳升、少阳郁热，症见耳聋咳嗽消瘦，治当清胆。", []], "1678": ["病机", "脉形细数，细主阴亏，数主内热。年六旬，肾阴久亏，肝阳内风上旋蒙窍，故耳失聪。五行有声多动真气火风，非苦寒直降可效。此脉主肾虚肝阳上亢，治以填阴重镇、滋水制木。", ["细", "数"]], "1679": ["病机", "原文未出脉象，而论耳为清空之窍，风热火郁、水衰火实、肾虚气厥皆能失聪。治法通阳镇阴、益肾补心清胆，使清阳上走空窍。此段主病机在清窍被蒙，症见耳聋，治分轻重。", []], "1680": ["病机", "风温上郁，目赤而脉左弦。左脉候肝胆，弦为肝木之象，风热郁于上，循经攻目，故目赤。风性轻扬，郁则宜散，故用辛以散之，使风热从表解。脉弦在此示风热郁于肝胆之经，非虚寒之弦。", ["弦"]], "1681": ["兼症", "脉左弦，左目赤痛泪多。左脉属肝胆，弦为肝气偏旺、风热上攻之象。肝开窍于目，风热循经上扰，故目赤而痛、泪多。此段以脉左弦点出病在肝胆，症与脉相应，属风热上郁之目疾。", ["弦"]], "1682": ["病机", "目痛偏左，翳膜红丝，脉左弦涩。弦主肝胆气热，涩示热郁血滞、络脉不畅。肝胆气热上攻于目，气血壅滞，故生翳膜红丝而偏左作痛。原文明言由肝胆气热所致，弦涩正合气热而兼郁滞之机。", ["弦", "涩"]], "1683": ["病机", "脉数右大，郁久热生，目障心痛。数为热，大为邪盛，右脉候肺胃，郁久化热，热循经上攻则目生障，热扰心胸则心痛。数大示郁热炽盛、邪实于内，非虚损之候，故以清热解郁为治。", ["数", "大"]], "1684": ["病机", "高年目暗已久，血络空虚，气热乘隙攻触脉络，液尽而痛，夜甚。原文未出脉名，以血络空虚为本、气热上乘为标，热由阴分而上，故夜甚。又虑外科酒调末药温散攻坚，反伤其虚，故断为虚症，示不可妄攻。", []], "1685": ["病机", "脉涩细，左目痛，泪热翳膜。细为阴血不足，涩为脉道不利，合示肝阴内亏、血少不荣。阴亏则厥阳上越，虚热攻目，故泪热生翳。原文明言肝阴内亏、厥阳上越，涩细正应阴血亏虚之机，治当养阴潜阳。", ["涩", "细"]], "1686": ["病机", "脉涩，眦痛，右目当风泪多。涩主血少、络脉不畅，肝开窍于目，肝肾精血不足则目失濡养，风邪易乘，故眦痛、当风泪多。原文断为当治肝肾，涩脉正示精血亏虚、络脉不充之病机，非实邪壅滞。", ["涩"]], "1687": ["病机", "论眼科外感内症皆关肝胆，外感六淫风火燥居多。脉见紧数或浮洪，紧主寒束、数主热，浮洪主邪在表。紧数并见，示外邪束表而内有郁热，与头痛寒热鼻塞、筋骨酸疼相应，属外感邪实之脉，治当分辨阴阳虚实寒热标本。", ["紧", "数"]], "1688": ["病机", "脉细数上出，细为阴血不足，数为内热，合之则体属阴虚、内热内生。牙痈后颊车穴闭、口不能张，是热毒虽退而络脉痹阻，病在络而不在脏，故药饵难效，当以宣通络痹为法，非徒清热可解。", ["细", "数"]], "1689": ["病机", "左脉弦数，弦主肝郁气滞，数主热，左脉候肝，故为肝经郁热上扰。咽痛脘闷并见，是阴亏体质不耐辛温，热郁上焦而气机不宣。治当轻药暂清上焦，避辛温燥烈以护阴液，与肺燥热之机相应。", ["弦", "数"]], "1690": ["病机", "原文未出脉名，以阴阳交虚、营卫欹斜立论。忽冷忽热、周身骸骨皆痛、百脉皆损，是阴阳不相维系；秋降而身中气反泄越、汗出喉痹，为阳不入阴、自为动搏。从少阴咽痛例用猪肤汤，正取滋阴润燥以缓喉痹。", []], "1691": ["治法", "此段仅载\"复脉汤去桂\"一方，未及脉象。复脉汤去桂，是去辛温通阳之品，专取滋阴复脉之意，承接前段阴阳交虚、百脉皆损之证，以甘润填补阴血、使脉道得复，属对症转方之治法记录。", []], "1692": ["病机", "引《内经》一阴一阳结谓之喉痹，脉数而为咽痛，数主热。手少阴君火与手少阳相火并络于喉，气热内结则肿胀，胀甚则痹，痹甚不通。故喉痹之机在君相二火独胜，热且痛，治标宜辛散咸软、去风痰解热毒。", ["数"]], "1693": ["病机", "脉不浮大，非关外风，排除表邪。右掌二指不屈伸、头面身半以上疮泡，是阳明脉络内留湿热，循经外发。若非疠气吸入，定然食物中毒，故与宣解缓攻，使湿热从脉络透解，而不作外风表散。", ["浮", "大"]], "1694": ["病机", "原文未出脉名，以能食、二便通调言脏腑无病。初因脓疮，疮愈有泡，自面及肢体至右指掌屈伸皆痛，是脉络留邪、隧道壅塞。前用辛凉入血先开后降得小效，今制清脉络壅热、藉酒力引导以通复营卫。", []], "1695": ["病机", "原文未出脉名，而言阳脉亦衰。血舍空隙则内风蠕动，外以热汤先洗，湿热蒸袭肌窍，遂裂脓流水；周身渐加麻痹，是阳脉衰而隧道不利。治当清营熄内风、疏利湿热以肃隧道，忌辛辣腥鲜，缓以计功。", []], "1696": ["病机", "原文未提脉象，从“营卫行动于脉中脉外”可知营卫尚能循行，故疮痍虽发而腹满可免；但“谷食尚未安适”“胃阳未复”说明胃气未振，湿浊内滞，故仍以通调利湿主治，病机重点在胃阳未复、湿邪未净。", []], "1697": ["平脉", "原文直言“脉象非有病”，即脉无病象，与“身瘦久疮、血分有热”之体相参，说明虽久患疮疡，脉尚未显病机，故属平脉；但“精通之年，最宜安养”提示需防血热耗损，非真无病。", []], "1698": ["病机", "脉来濡浮，濡主湿、浮主表，合之久疮不愈，说明卫阳疏豁、不耐寒暄，客邪未解而混处气血，浸淫阳分肌腠；故以升举一法，气壮则风湿尽驱，病机在卫阳不固、风湿客于肌表。", ["濡", "浮"]], "1699": ["兼症", "脉左数右长，左数主血分有热，右长主气分有余，热郁颈项少阳阳明之络，故结瘿而时衄；瘿为气结痰凝，衄因热迫血溢，脉象与颈项结瘿、时衄之症相应，病机为肝胆郁热、气血壅结。", ["数", "长"]], "1700": ["病机", "原文以“脉不浮数，无寒热”辨非痈脓，说明乳房有形而痛乃情怀失畅、气血郁痹于少阳络脉所致；脉不浮数则无表热壅盛之象，故当治在络，病机为气郁血痹、络脉不通。", []], "1701": ["病机", "原文未言脉，因嗔忿失血致颈项筋肿痛连背部，百日不痊，说明郁怒伤肝、气血流行失司，郁滞少阳阳明之络，久则流注溃脓；病机在郁伤气血、经脉失司，非单纯外疡。", []], "1702": ["病机", "脉左数实，数主热、实主壅，左脉候血，故血络有热；暑风湿气外加，与内热相搏，壅于肌腠则发疹块、壅肿瘙痒，是属暑疡；脉象说明热壅血络、外邪郁表之病机。", ["数", "实"]], "1703": ["预后", "脉微小，溃疡半月而余肿未消、脓水清稀、浮肿汗出、呕恶恶食，说明胃阳垂败、痈毒内攻欲脱；阳失煦则阴液不承，元气撒则毒愈弥漫，脉微为阳衰之兆，故预后险恶，议甘温培本以冀陷者复振。", ["微", "小"]], "1704": ["病机", "疡溃脓血去多，元真大耗，脉无力不嗜食、恶心，乃中州不振、胃气衰败之象；寐则惊惕，神不守舍。脉无力提示气血大虚，故以养营法补益，非攻邪所宜。", []], "1705": ["病机", "因疡漏过进寒凉，损伤阳气，遂患腰痛牵引脊膂，晨起周身不得自如。此经脉络脉之中气血流行失畅，久病非攻逐可解，议两和方法调畅气血。", []], "1706": ["病机", "痛久屈伸不得自如，经脉络脉呆钝，气痹血瘀，郁蒸上热；旬日频频大便必有血下，复喘促烦躁、不饥不食，无寒热汗出，全是锢结在里，欲作内痈。部位脐左之上内应乎肝，吐痰口气皆臭，内痈已见一班。", []], "1707": ["主病", "壮热旬日，周身筋脉牵掣，少腹坚硬，小便淋滴，忽冷忽热，欲酿脓血，乃肠痈为病。此热毒壅结肠腑，气血壅滞，酿脓成痈，故仿孙真人牡丹皮大黄汤主之。", []], "1708": ["病机", "经先期色变，肤腠刺痛无定所，晨泄不爽利，从来不生育。由情怀少欢悦、多愁闷，郁则周行之气血不通，而脉络间亦致间断蒙痹，例以通剂调畅气血。", []], "1709": ["病机", "久嗽背寒晨汗，右卧咳甚，经事日迟，脉如数而虚，谷减不欲食。此情志郁伤，延成损怯，肺气虚损，非清寒肺药所宜。脉数而虚为虚火内扰，中气已馁。", ["数", "虚"]], "1710": ["病机", "肺为气出入之道，内有所伤，五脏之邪上逆于肺则咳嗽。久嗽背寒晨汗，全是肺气受伤；经事日迟，血枯肝闭可知。脉数虚火也，虚则不可清寒，况谷减不欲食，中气之馁已甚，故与黄耆建中益气温中。", ["数", "虚"]], "1711": ["病机", "气冲心痛呕涎，气坠少腹为泻，经来后期色或淡或紫，病在冲脉。冲脉隶于阳明，肝气犯胃，故从厥阴阳明两治，以调冲降逆。", []], "1712": ["主病", "脉涩为血少气滞，血行不畅。脘闷减食，脾胃气滞；经水来迟、腹痛坠，冲任血海不充，气血涩滞，故脉涩主血虚气滞、经行不畅之病机。", ["涩"]], "1713": ["病机", "奇脉下损，脉虚寒滞，乃奇经虚寒、气血滞涩。经迟腹痛，因下焦虚寒，冲任失温，血行迟滞。用当归建中汤温养，续商八脉治法，脉象示虚寒滞之病机。", ["虚", "寒", "滞"]], "1714": ["病机", "原文未识脉名，述能食不运、瘕泄、经事愆期、少腹干涸而痛、下焦麻痹、冲心呕逆、腹鸣心辣，显系八脉奇经交病，下焦虚涸，冲任不调，气血痹阻之病机。", []], "1715": ["病机", "脉右缓左涩，右缓主脾胃气弱，左涩主肝血郁滞。经水色淡后期、呕吐痰水食物、不孕，乃久郁凝痰滞气，阳明厥阴同病，脉象示痰气郁滞、血行不畅之病机。", ["缓", "涩"]], "1716": ["病机", "原文未识脉名，述经水一月两至或几月不来、五年不孕、下焦肢体常冷，是冲任脉损，无有贮蓄，肝肾虚寒，胞宫失温，故脉当见虚寒之象，主冲任虚损病机。", []], "1717": ["病机", "脉肝阴虚，冲脉肝阴虚。经期迟至、筋骨牵掣酸楚，因血海不充，冲脉失养；阴虚生热，阳虚生寒，产后虚损不复。脉示肝血阴虚、木火内寄，冲脉病之不孕。", ["虚"]], "1718": ["病机", "脉阴虚，八脉隶乎肝肾，肝肾血液久亏，八脉乏束固之司。阴弱内热，阳微外寒，膂脊常痛，经事愆期，血海渐涸。脉示至阴损伤，八脉不为约束之病机。", ["虚"]], "1719": ["病机", "原文未识脉名，述寒热无汗、经先腹痛、喉中燥痒咳逆、食物不思，此郁伤气血，八脉主病，气血郁滞，冲任不调，故脉当见郁滞之象，主八脉气血郁伤病机。", []], "1720": ["病机", "原文未识脉名，但言「究脉察色」而知「脉不循序流行」，点出冲任跷维诸脉皆隶肝胃，肝气偏横则胃受戕、气血阻痹。经水先后不定、来期腹痛、下焦常冷、腹鸣忽泻忽结，皆肝胃失和、奇经不循常度之象，久则结瘕聚痃痞，属气郁血痹之病机。", []], "1721": ["病机", "原文仅言「郁伤络脉。痛经」，未载脉象。郁怒伤肝，肝气失疏则络脉瘀滞，冲任气血运行受阻，经行不畅而作痛。此段以病因「郁」立论，指明痛经由络脉受伤、气血痹阻所致，属气滞血瘀之病机，非单纯虚损可比。", []], "1722": ["病机", "脉来右大左弱，右大主上部火升，左弱主下焦虚冷，故见经水紫黑、嘈杂、脉络收引而痛、带下不断、形瘦日减、下焦冷彻骨中。此阴阳乖违、阳不交阴之候，前医补血涩剂反滞其阳，故议通阳摄阴，使上下交通而孕育可望。", ["大", "弱"]], "1723": ["病机", "脉数主热，合性躁、经来气攻触、右肩痛痿、经不调，知气分有热，热扰冲任则经行不顺，气攻则痛。数脉为热象之征，非虚寒可比，故原文直断「气分有热」，热郁气分而血随气动，经候因之不调。", ["数"]], "1724": ["病机", "脉数而形疲、咳、经闭半年，更见食减、便溏、浮肿，是脾胃阳虚、中气衰馁，数脉非实热乃虚阳外浮之象。土虚不能生金则咳，不能运化则食减便溏浮肿，冲任乏血故经闭。原文戒「无清嗽通经之理」，主扶持中土，正合虚损病机。", ["数"]], "1725": ["病机", "脉数而经闭、腹胀足肿，数脉在此非热盛，乃气滞湿凝、郁而化热之象。气机壅滞则腹胀，湿浊下注则足肿，冲任受阻故经闭。原文标「气滞湿凝肿胀」，明示病机在气分湿滞，非血枯经闭，故数脉当从气郁湿阻解。", ["数"]], "1726": ["病机", "原文未载脉名，但言「无妊脉发现」，即脉不显滑数妊娠之象。居经三月而痞闷膨胀，询知劳碌致病，断为脾胃阳伤、中气愈馁，冲脉乏血贮注。劳倦伤中，阳虚气馁则血海不充，经候因停，属气血虚滞兼湿之病机，非胎孕可比。", []], "1727": ["病机", "脉右弦左涩，弦主气滞、涩主血瘀，合面无华色、经阻三月、冲气攻左胁而痛、腹时胀、两足跗肿，是血瘀气滞、水湿内停之候。冲脉隶于肝，气攻左胁为肝经之象，血蛊已成，故原文戒「勿得小视」，示瘀阻日深之病机。", ["弦", "涩"]], "1728": ["病机", "右脉虚主中阳不足，左脉虚弦数示营阴亏虚而肝木偏亢。腹痛两月、胸痹咽阻为气机痹阻，冷汗、寒栗属卫阳不固，周身刺痛乃营虚络涩之征。总由郁损营阴、内损成劳，经闭将作，故以桂枝汤加茯苓通阳和营。", ["虚", "弦", "数"]], "1729": ["病机", "原文未出脉名，仅言「阳脉不流」，指阳气郁遏不能流畅。病起经阻、形容日瘦、嘈杂刻饥、心腹常热，皆悲惋离愁内损营阴、阴脏受伤之象。阳脉不流则气血失于温运，故断为难治之症，必怡悦情怀方望经来，通经败血断不可用。", []], "1730": ["病机", "脉数而色夺，数非实热，乃阴阳并损、虚阳浮越之象。久嗽经闭示肺损及营，寒从背起、热过无汗说明营卫循行失其常度，非疟邪往来。脉数与色夺并见，正合阴阳两伤、营卫失调之机，故以并损立论。", ["数"]], "1731": ["病机", "脉来细促，细为营血亏少，促为脏真受损、脉行急促不匀。面色㿠白、久嗽减食、腹痛便溏、经闭半载，示三焦脏真皆损，营虚血枯而成干血劳怯。俗医见热投寒凉，更戕生气，故原文叹「生气断尽，何以挽回」。", ["细", "促"]], "1732": ["病机", "脉弱无力主中气大虚、营卫不足。发热汗出为虚阳外浮，久咳形冷、减食过半乃脾肺俱损、阳气不充。显然内损成劳，故大忌寒凉清热治嗽，姑与建中法温建中阳，冀加谷经行，犹可调摄。", ["弱"]], "1733": ["预后", "原文未出脉象，仅言「百脉枯槁」，指血脉失荣、枯涩无生机。干血劳病日久，营血耗竭，百脉失养，故渐至危笃。三月诊脉一次、当面告辞，示其脉证已无挽回之机，非因循误事，乃预后凶险之断。", []], "1734": ["病机", "脉来弦数，弦为肝郁血滞，数为热蒸。潮热经阻，营血被寒热交蒸，流行之机断阻，血滞不行遂成干血劳瘵。弦数并见，正示寒热交争、营血受灼而瘀阻之病机，故断非小恙。", ["弦", "数"]], "1735": ["病机", "脉细数，细主营血亏少，数主营分有热。腹痛、营热、经不通，乃营阴不足、虚热内灼，血行涩滞而经隧不通。细数之脉与营热经闭相应，示阴亏热扰、血枯不行之病机。", ["细", "数"]], "1736": ["病机", "原文未出脉象，专论月经之本在冲脉、胃气、心脾生化之源。以“太冲脉盛，月事以时下”为据，强调冲为血海、阳明水谷化血，故经水不愆其期。此段从生化之源阐发女科调经首重冲脉与胃气，非以脉断病，而归病机之论。", []], "1737": ["病机", "温邪劫阴，阴伤则阳不潜而火升，故见带下、胸痞；脉小数者，数主热，小主阴液亏耗，是温邪内灼、阴分受损之象。脉数与火升相应，小与阴伤相应，故主温邪伤阴、虚火上炎之病机。", ["数", "小"]], "1738": ["病机", "阳明脉虚，胃气不充，则水谷精微不布，故手麻、足冷、身动；带下如注者，中虚不摄、湿浊下渗也。脉虚为胃气不足之征，与通摄方之治法相合，主胃虚不摄、带脉失约之病机。", ["虚"]], "1739": ["病机", "色苍脉数，阴不足而阳偏亢，肝阳内扰，风木乘土，故心中泛泛、头晕腹痛，经水仍来兼带下。数脉主热，阴不足则阳无所附，化风上扰，乘克中土。法当酸以和阳、咸苦坚阴，正对肝阳化风、木乘土之病机。", ["数"]], "1740": ["病机", "带下不止，少腹内踝连痛至不能伸缩，是血虚络脉失养、滞而不宣。脉虚为血虚之据，络虚则痛，久则结痈绵缠。原文辨“医云肝气”为非，强调血虚脉络滞痛之病机，不可作肝气实治。", ["虚"]], "1741": ["病机", "带淋日久，脂液垂涸，奇脉俱伤，营卫亦偏，内风自动，中焦气夺，浮肿腹膨，寒热交作。原文未出脉象，以“液涸风动”为纲，述奇经虚损、营卫失和、内风扰动之病机，暂以咸缓和阴为治。", []], "1742": ["病机", "脉左细，按之空虚昭然，痛起得按痛缓，是八脉空虚、阴血不足之征。细为血少，虚、空为脉道不充，得按痛缓属虚痛。原文断为“八脉空虚昭然”，舍补养则反增剧，主奇脉虚损之病机。", ["细", "虚", "空"]], "1743": ["病机", "女科淋带瘕泄，奇脉虚空，腰背脊膂牵掣似坠，而热气反升于上从左而起。脉虚空为八脉亏虚、精血不充之象，虚则气不摄而热浮。原文强调女人以肝为先天，医不晓八脉之理，妄用桂附地味皆非，主奇经虚损、虚阳上浮之病机。", ["虚", "空"]], "1744": ["病机", "原文谓“脉隧气散不摄”，指脉道中气耗散不能固摄阴液，故见淋带瘕泄、诸液耗伤。阴伤而气不摄，用参附姜桂劫阴无效，胶地阴柔亦不效，因阴药沉降反扰其滑脱。治当引之收之固之，以震灵丹意通涩兼施，说明病机为气散不摄、阴液滑脱。", []], "1745": ["病机", "原文“脉络空豁”指脉道空虚豁然，因自乳血耗、阴血亏虚，脉络失充。症见脊膂椎髀酸耎、带下不已、下部已冷，乃阴虚及阳，奇经失养。脉空豁正应阴血耗损、脉络不充之机，故速断乳以杜耗血，免延成劳。", ["空"]], "1746": ["病机", "原文“脉空乏”言脉道空虚乏气，因经漏成带、下焦畏冷，阴血下夺，八脉失充。肝脏阳升致眩晕，乃阴亏于下、阳浮于上。脉空乏正是下焦精血亏虚、奇经空乏之征，故主经漏带下、眩晕之候。", ["空"]], "1747": ["病机", "原文未出脉名，而言“八脉无气”，指奇经八脉气虚不能摄纳。寡居独阴，愁烦思郁，目注凝神，阳升巅顶为眩晕；八脉无气则带下、下冷；内风日动则痱疹麻木隐现。病机为阴亏阳浮、八脉气虚、内风扰动，故以暖下柔剂和其阴阳。", []], "1748": ["主病", "原文举“脉必滑数”“脉微涩”以辨带下。滑数主湿痰流注带脉、下浊液，赤者属热兼火；微涩主虚，白者属湿兼痰，年久不止则脾肾虚。又分白带、白浊、白淫，白带下元虚损，白浊胃中浊气渗膀胱，白淫精不摄。淋症肾虚膀胱积热，故脉数而涩。", ["滑", "数", "微", "涩"]], "1749": ["病机", "原文“脉数”而寒热汗出、腹胁痛，病起经漏崩淋之后，乃阴血骤伤，阳无所附而乘之，故脉数。消渴喜凉饮，是阴伤脏燥热之象，不可纯作外邪论。治以和营卫、调中、甘缓，正针对阴伤阳乘、脏燥热之病机。", ["数"]], "1750": ["病机", "原文“冲任脉虚”“奇脉虚血滞”，指产育频多耗伤冲任，脉道空虚，血行滞涩。天癸当止之年，紫黑血如豚肝暴下，继黄水绵绵，乃积贮之血久而瘀浊，不得不下。脉虚主冲任亏虚，血滞则瘀浊内积，故属奇经络病，宜清宜通。", ["虚"]], "1751": ["预后", "原文“阳明胃脉衰微少气”，指右肢渐不能举，因五旬天癸当止而经淋牵掣，冲任督带损伤，阳明胃脉衰微少气。脉衰微少气说明中焦气血生化乏源，奇经失养，故肢体不举。此为冲任胃皆虚，最难向安之病，预后不佳。", ["微", "衰"]], "1752": ["病机", "原文述崩漏两年，先有带下，每交申酉漏必至，谓“冲脉任脉皆动，下无提防约束”。冲任皆动则血海不宁，下无约束故漏下不止；阳明久虚，脉不固摄，有开无阖，故崩漏缠绵。此非单纯涩剂可止，须按经论治，调补冲任阳明。", []], "1753": ["病机", "原文谓“冲任二脉损伤，经漏经年不痊，形瘦肤干畏冷”，由阴气走乎阳位，冲任阳虚不能固摄，故经漏不止；阳虚失温则形瘦畏冷，阴液外泄则肤干。治当益气培阳、温摄固下，以复冲任之职。", []], "1754": ["病机", "原文谓“阳明脉空，阳越卫疏，阴火升举”，脉空示阳明气血不足，冲脉隶于阳明，阳明虚则冲脉失养；阳越卫疏故汗泄、夜寐少，阴火升举故经来淋漓。此阴衰阳动之候，治宗补阴丸或虎潜丸，久病慎汤药妨胃。", ["空"]], "1755": ["病机", "原文述停经三月，下漏成块，少腹膨痛，议通和奇脉。奇脉不和，气血瘀滞，冲任失和，故经停而漏下成块；少腹膨痛为瘀阻之征。治当通和奇脉，调畅气血，使冲任复其常度。", []], "1756": ["病机", "原文谓“肝肾内损，延及冲任奇脉，遂至经漏淋漓，腰脊痿弱，脉络交空”，脉空示精血亏虚，脉络失充。肝肾虚则冲任不固，故经漏淋漓；腰脊失养则痿弱。此虚寒之候，有终身不得孕育之虞。", ["空"]], "1757": ["病机", "原文谓“阳明脉衰，厥阴风木由乎血去液伤，冲任交损，内风旋转而为风消之象，病在乎络”。阳明衰则化源不足，血去液伤则冲任损，内风旋转故经漏如崩、白带绵绵，形瘦、夜热多汗、肢冷、腹鸣等皆液伤络热风消之征。", []], "1758": ["病机", "原文谓“冲脉之动而血下，诸脉皆失其司”，经漏三年，色脉俱夺，面浮跗肿，纳减便坚，腰髀酸楚。冲脉动则血下，任带督跷失司，故漏下不止；症虚而补阳不应，未达奇经之理。治当通以济涩，咸味就下，入奇脉以调之。", []], "1759": ["治法", "原文述治八脉之大意：鹿性阳入督脉，龟体阴走任脉，阿胶熄肝风养肾水，柏子养血理燥，牡蛎咸固下，锁阳固下焦阳气。此以血肉有情之品通补奇经，咸味就下，同气相需，针对奇脉虚损、冲任不固之病机。", []], "1760": ["病机", "原文未出脉名，然述“奇脉内乏”，指冲任奇经亏虚。病由悲哀烦劳伤阴，又因目病服苦辛寒散太过，耗伤阴液，致经漏淋带、两旬方止。阴血亏虚，内不营守，虚风外扰，故周身瘾疹㾦累。此段以病史推病机，属阴亏奇脉不固、虚风动络之候。", []], "1761": ["治法", "脉实下，指脉象沉实，主里实热。原文谓“六淫客邪，无有不从热化”，疮痍属火，阴不内营则阳气浮越、卫怯少固，客气外乘化热。经至之期阴血下注，故议“固脉实下”，佐东垣泻阴火法，先固下焦、清内热，非徒治肌腠瘙痒。", ["实"]], "1762": ["病机", "右大而涩、左小数，中有坚疾如刃之象。大涩为液亏，小数主阴虚阳动，坚疾如刃乃内风沸起、肝阳化风之征。经来阴血下注，阳气鼓动，风非外来，乃阳化之气。液枯风动，故腹坠腰酸、疹痒及鼻耳窍。治当熄风润燥，忌辛温动阳耗液。", ["大", "涩", "小", "数"]], "1763": ["病机", "连次候脉必小弱为少安，小弱示阳动暂息、内风未旋。原文引“暴崩当温涩，久漏宜宣通”，指出耆术呆守则气壅，归艾辛温则阳动，皆失变化之旨。冲脉隶于阳明，血海亏虚，阳动不息则内风旋扰。故以理阴熄风、通摄冲任为法，非骤期速愈。", ["小", "弱"]], "1764": ["治法", "此段述丸药制法与服法，未出脉象。药末胶膏加熟蜜捣丸，早上服，小暑至处暑以生脉散送下。生脉散益气养阴，送服通摄冲任之丸，取补气阴以固奇脉、清暑热以护液之意，属长夏调理之服法安排，非论病机脉象。", []], "1765": ["病机", "原文未出脉名，述“久漏奇脉少固”，指漏下日久，冲任奇经失于固摄，故经后带下仍有。前案已申通摄冲任之法。此段重在说明外寒易御而内因劳嗔难调，情志劳伤扰动气血，使奇脉难固，故丸剂须恪守久服方效。", []], "1766": ["其他", "此段仅记十二日午诊脉后仍用初十日早服方法，去穞豆皮加生牡蛎，未出具体脉象。属临证随诊调整方药之记录，以生牡蛎增强潜阳固涩之力，配合前法续进，非专论脉象病机。", []], "1767": ["治法", "脉散微，散为气阴耗散、固摄无力，微主阳气式微。交小暑后骤热，暑热耗气伤阴，故午后另煎生脉散微温服一次，益气敛阴、清暑生津，以救脉散微之耗散。属因时令变化而设的调治服法，非主病之脉。", ["散", "微"]], "1768": ["病机", "原文未出脉名，以暴崩后黄白淋漓、寒热拘束烦躁、晡时汗出、寐则身麻如虫行、骨节皆痛为据。指出血去过多，冲任损伤，阴损及阳，故为寒为热；脂液荡尽则形骸枯槁，延为瘵疾。此段重在说明崩漏日久耗损冲任阴血、由阴及阳的病机转归，非凭脉断病。", []], "1769": ["病机", "原文无脉象，专论崩漏病机。以“崩如山冢崒崩”喻血横决莫制，“漏如漏卮难塞”喻血漫无关防。阴在内为阳之守，去血过多则诸病丛生。列举冲任不摄、肝不藏血、脾不统血、热迫妄行、元气大虚不敛、瘀阻新血不归等因，示人依此类推治法。", []], "1770": ["主病", "经停三月而无寒热，诊得脉大，系恶阻减食。妊娠恶阻常见脉大，因胎气初结、气血壅盛于中，故脉形宽大；无寒热则非外感，减食为胃气受胎气上逆所致。此以脉大合停经、减食，主恶阻之病，属妊娠早期常见脉症。", ["大"]], "1771": ["主病", "上年夏产后过月经转，今停经四月，左脉弦滑流动，乃为妊象。弦滑流动为妊娠气血充盛、胎气搏结之脉；然气急脘痞咳嗽，是热气上乘迫肺，形瘦热烁阴耗气。脉主妊，症示热伤肺阴，故议清金平气而勿碍胎下。", ["弦", "滑"]], "1772": ["病机", "原文未出脉象，述怀妊五月得热病，久伤阴液，阳气有升无降，故耳窍失聪、便难艰涩。热邪久羁耗伤阴液，阴不制阳则升而不降，上扰清窍、下涸肠道。议用仲景复脉法以生津液，是养阴复脉以制亢阳，属热邪伤阴之病机。", []], "1773": ["病机", "脉右虚左弦，身麻肢冷，胎冲胀闷，五六月脾胃司胎。右虚主中气不足，左弦主厥阴内风暗动；中虚则不饥吞酸，肝风犯脾胃则身麻肢冷、胎冲胀闷。脉症合参，全属中虚而肝风内动、犯及脾胃之病机，非单纯胎病。", ["虚", "弦"]], "1774": ["其他", "原文无脉象，述怀妊六月，阳明司胎之时，闪动络脉，致环跳痛连腰膂。因妊娠闪挫，络脉受损，气血运行不畅而痛引腰膂。所重在“最防胎气”，提示须防闪动络脉波及胎元，属妊娠外伤络脉、需护胎之候，非脉诊主病。", []], "1775": ["误治", "原文无脉象，述先寒后热、咳呛，春月风温肺病，怀妊九月热伤肺阴，喘急消渴胸满便溺不爽。前医误用芎归辛温、参术守补、肉桂沉香辛热，致大热烦闷、势属危殆。此段主旨为胎前忌用辛温守补辛热之误治，议清肺润燥、胎凉则安，去病即安胎。", []], "1776": ["治法", "原文未出脉名，以“喘热减半、四肢微冷、腹中不和、胎气有上冲之虑”述病势。前用清润得漐漐汗，知辛燥耗血助热；今烦渴止而病由悲哀惊恐伤及肝肾，故以养肝阴、滋肾液为治，复脉去桂麻姜枣加天冬知母子芩，旨在稳保胎元，属胎前病之调治。", []], "1777": ["病机", "右脉涩小数、左弦促，涩小数主气郁化热、津不畅，弦促为肝胆火郁搏击。症见纳食脘胀、甘酸浊味、呕吐清涎、旬朝一更衣而不爽，询知情怀抑郁，五志过极皆从火化。怀妊恶阻按逐月安养在足少阳，肝胆相火内寄，非凉剂无以和平，故主郁热。", ["涩", "数", "弦", "促"]], "1778": ["主病", "脉虚唇白，虚为阳气不足、唇白为血不华，交节上吐下泻更伤中阳，胎动不安由吐泻耗伤阳气、中州失守、胎失所养所致。急用理中法者，温复中阳以止吐泻、安胎元，原文自注“吐泻伤热阳”，正说明虚寒吐泻累及胎气之病机。", ["虚"]], "1779": ["病机", "原文未出脉名，以“喜暖恶寒、升则厥痛、坠微便痛绕腹”述寒邪厥逆之象。怀妊阳气不足，寒邪内侵，络脉拘急则厥痛绕腹；暖胎须避络伤及奇脉，畏胎坠难挽，故用辛香温柔之补，冀其止厥，属寒邪伤胎、络脉失温之病机。", []], "1780": ["主病", "形瘦而脉数尺动，数为热、尺动为胎动不安之象。不食恶心证象恶阻，腰痛见红则为胎漏欲坠。数动之脉见于尺部，示热扰冲任、胎元不固，故既见恶阻又见漏红，主胎漏欲坠之病，须急安胎。", ["数", "动"]], "1781": ["病机", "原文以“奇脉之结实者”立论，冲脉为病，男子内结七疝、女子带下瘕聚，结实即脉气结聚不通。古人用苦辛和芳香通脉络，虚者辛甘温补佐流行脉络。今产后体虚兼瘀而痛，法当益体攻病，日期已多缓治为宜，示虚实夹杂、络脉结滞之病机。", ["结", "实"]], "1782": ["病机", "原文未出脉名，述“下元虚损无疑，八脉无气把握，带下淋漓不止，梦魂跌仆”。下虚则梦坠，八脉失于统摄则带下淋漓，奇脉无气把握故梦魂不安。议镇固奇脉方，旨在固摄下元、安镇奇脉，属虚损不固、奇脉失约之病机。", []], "1783": ["病机", "脉濡主虚，恶露紫黑、痛处紧按稍缓，按之缓为络虚不荣之征。此属络虚，治在冲任，以辛甘理阳。濡脉示营络虚寒、冲任失温，故恶露未清而色紫黑，痛喜按，主营络虚寒之病机。", ["濡"]], "1784": ["病机", "脉濡空大，濡为湿滞而虚，空大则营血亏虚、脉道不充。营络虚冷，故脉象虽大而按之空软无力，主产后营血虚寒、络脉失养之病机，症见畏寒、肢冷、面色无华等。", ["濡", "空", "大"]], "1785": ["病机", "原文未出脉名，述产后下焦阴亏、奇脉不固，阳浮乃升，风动则飧泄嘈杂，液损必消渴骨热。此属肝肾阴亏、虚阳上浮、内风扰动之病机，主产后下焦阴伤、奇经失固，症见飧泄、嘈杂、消渴、骨热等。", []], "1786": ["预后", "脉缓热止，缓为胃气渐和之象，热止则邪热已退，故为病减之象。但舌色未净、大便未通，产后大虚不敢推荡，示余邪未清、腑气未通，当以蔬粥养胃、清润待便通再补，属预后顺中之虑。", ["缓"]], "1787": ["预后", "原文未出脉名，但言脉无神，神倦欲昏、汗出，乃阳气走泄；泻利系阴气不守。产后见症属重虚，深恐节间暴脱。此脉无神为阳气阴液俱脱之兆，主产后重虚危候，预后凶险，寒热胸痞腹痛皆标末不足论。", []], "1788": ["病机", "冲脉逆则诸脉皆动，动为冲气上逆、阴阳失守之象。天朗晴和少安，由阴分虚及阳分可征。前法包举大气、温养佐通，日来春升略有衄血，加咸味入阴，减鹿霜归身恐升阳，加枸杞桂圆养肝，皆围绕产后下焦先伤、冲逆动脉之病机。", ["动"]], "1789": ["病机", "脉空乏，空为脉道不充，乏为无力，乃产后下焦百脉空乏之象，谓之蓐损。前法酸甘益阴和阳，诸病皆减，然谷食未加，沉腻恐妨胃口，加餐可用丸药，填隙固髓为正治，紧扣下焦虚损、百脉空乏之病机。", ["空", "乏"]], "1790": ["病机", "脉空隙，空为血虚不充，隙为脉道不密，乃产后下焦先损、百脉空隙之象。时序夏秋，天暖发泄加病，扶阳益阴得效，诸症向愈，独经水未至，冲任奇脉不振，须脏阴充旺、脉中游溢，主下焦虚损、奇脉失振之病机。", ["空", "隙"]], "1791": ["病机", "脉虚，为产后下元阴分先伤，奇经八脉皆丽于下，肝肾怯不固，八脉咸失职司。阳维脉痛苦寒热，阴维脉病苦心痛，下损及胃食物日减。产伤先伤真阴，忌用桂附之刚，温煦阴中之阳，能入奇经者宜之，主下损及胃、奇脉虚之病机。", ["虚"]], "1792": ["病机", "原文未出脉名，以“邪深入阴，气血胶结”立论。产后正虚，外邪乘虚内陷阴分，气血凝滞互结，日久遂成瘕疝有形之块；奇经纲维失于约束，故身体伛偻。此非单纯攻邪可解，须充形通络、温养奇脉，仿当归羊肉汤意，从血分通补兼施。", []], "1793": ["病机", "原文未载脉象，主旨在“产后胞损溺淋，筋脉牵掣”。产后胞宫受损，下元不固，故小便淋沥；精血亏耗，筋脉失养，故牵掣不舒。病本在下焦虚损，治当摄下固脬，非清利淋浊之法，体现产后以固补下元为要。", []], "1794": ["病机", "“阳明脉空”点明胃脉空虚，由产后下焦虚损日久延及中焦，阴损及阳，胃气不充则不饥不食；厥阴风木失养而内动掀旋，故头痛面浮、肢冷指麻，皆亡血家阴血亏虚、虚风上扰之象。脉空正应气血两虚、阳明乏养之机。", ["空"]], "1795": ["病机", "“脉右大是阳明空”，右脉大而中空，为阳明胃气虚泄不固之象。患者自幼劳伤，产后体虚，清阳不升则头眩耳鸣，神色衰夺、唇黄舌白、手冷脚肿，皆中阳不足、下焦虚寒。脉大非实热，乃气虚外浮，故以暖下温中主治。", ["大"]], "1796": ["病机", "“脉虚淋滞”示脉虚而淋涩不畅，为冲任奇脉内怯、固摄无权之候。产后淋带不止，精血暗耗，奇经空虚，故脉虚；虚而兼滞，是气血不足、运行无力。久延恐成崩漏劳损，治宜固补实下，兼通奇经，补中有通。", ["虚"]], "1797": ["病机", "“百脉空隙”言产后血脉空虚，营血骤亏，百脉失充。腰脊痛者，奇经失养、督带不固；漏淋者，下元不摄。脉空与症相符，皆亡血后精血亏虚、脉络不实之象，治当补养奇经、固摄下焦，不可见淋而利。", ["空"]], "1798": ["病机", "原文未出脉名，以“蓐损八脉”立论。产后下焦先虚，渐及中宫，血液脂膏涸竭，故经水不来、带下频频。桂附燥热反助劫烁，故用温药取温养之义而非温热，示奇经虚损当柔润温养，不可峻补燥烈。", []], "1799": ["病机", "“脉濡”为虚软无力之象，应产后血去过多、冲任空虚。血虚不能充脉则濡，下焦失养则跗肿腹膨，阳虚不温则形寒面黄。脉濡与亡血、虚寒诸症相合，故当温养下元，补血固冲，不可误作水湿实肿而攻利。", ["濡"]], "1800": ["病机", "脉沉濡，沉主里、濡主虚，为产后下焦虚寒、寒湿内侵之象。寒凝气机则痛胀，水湿下注则腹鸣晨泄；浊阴上逆则心痛呕逆。原文谓“其实治下为是”，点明病本在下焦虚寒，上症乃标，故脉沉濡主下焦虚寒、寒湿内盛。", ["沉", "濡"]], "1801": ["病机", "脉微弱为气血大虚之候。产后下焦不复，中焦又伤，故食减吐泻；脾肾虚衰，水湿不化，渐加浮肿胀满，倏甚忽平，乃下焦厥逆上冲所致。形无华色亦由虚损。原文强调“下虚于产后，刚剂难以专任”，脉微弱正示虚损难复之机。", ["微", "弱"]], "1802": ["病机", "右迟左弦，右迟主中阳不足，左弦主肝木偏亢。产后未满百日，气血未复，阳虚失温则畏寒便溏、食减；肝失疏泄、筋脉不利则胸胁骨节收引、四肢麻木；阳虚水湿不化则浮肿腹胀。早轻夜重属阳衰。原文“先与理中，健阳驱浊”即针对此阳虚肝郁、浊阴内停之机。", ["迟", "弦"]], "1803": ["治法", "本段未出脉象，以症测机。原文“便利仍痛，非是实症”，明言非实邪积滞，乃“肝失调畅”，下焦阳虚，肝络失于温通。故治法“理用以益水母”，去芍药之酸寒，加当归、小茴香拌炒焦黑，辛温通阳、散益肾肝，以通肝脏脉络之阳。此属产后下虚、肝络不和之病机与治法。", []], "1804": ["病机", "脉细肉消，细主阴血不足，肉消为形骸失养。产后肿胀不愈，显系下虚，肝肾气不收摄，水湿泛溢则肿；形寒痞闷、食少痰多，乃脾肾阳虚、痰湿内停。原文“治从阴分，非分和攻消者”，强调病本在阴分虚损，脉细正合阴血亏虚、肝肾不摄之机。", ["细"]], "1805": ["病机", "本段未出脉象，以症论机。原文“风胜为肿，湿甚生热，乃经脉为病”，指出风邪胜则肿，湿郁化热，病在经脉。但产后百日，精神未复，气血尚虚，故“不可过劫”，提示虽风湿为患，亦须顾护正气，不可峻攻。此属产后经脉风湿化热、正虚未复之病机。", []], "1806": ["病机", "脉虚为气血不足之象。产后腹大半年不愈，近日有形冲突、肠如刀搅，据述坐蓐艰产、血去盈斗，腹形即已胀满。原文断为“八脉不用，肾气散越不收，非瘀血积气为病”，脉虚正合奇脉亏虚、肾气不摄、冲任不固之肿胀病机。", ["虚"]], "1807": ["病机", "本段未出脉象，以症推机。原文“冲任伤，督带损，皆由产时劳怖”，明言奇经八脉受损，下元不固。腹满膨痛，若徒固补而不通调，恐滋胀肿，故立“阳宜通，阴宜固”之法。此属产后奇脉虚损、阴阳失和、虚实夹杂之病机，治当通固兼施。", []], "1808": ["病机", "原文未载脉象，以症测机。产后冬月右腿浮肿、按之自冷，非败血壅滞，乃冲任先虚、跷维脉不为用，下焦脉络寒滞。败血半年当成痈疡，针刺反加痛，说明病本在虚寒而非实滞。温养下元、通络取效迟，正因虚寒凝结，需恪守缓图。", []], "1809": ["病机", "脉沉主里，合喘咳浮肿、鼻窍黑、唇舌赤、渴饮胀急、大便不爽，是秋风燥化上伤肺气，气壅不降，水谷汤饮之湿痹阻经隧。沉为水气内痹、气不宣通之象，故有坐不得卧之虑。法宜开通太阳之里，若畏产后久虚而温补，则客气散漫、三焦皆累。", ["沉"]], "1810": ["病机", "脉小左弦，小为气虚，弦主肝木气逆。咳逆脘闷、小便不利、便溏纳呆、嗳气臭秽，皆胎前气上逆冲，浊踞膈间，肺失清肃降令，上窍痹致下窍不利。弦为气逆湿阻之应，恐延浮肿腹满、喘急不卧，故不可独以产后通瘀为事。", ["小", "弦"]], "1811": ["病机", "原文未载脉象，以色脉合参。产后未满百日，多惊怕、五味皆变，陡然狂乱入井，暴病属痰火风。厥阴肝木顺乘阳明，一阴一阳变乱为痫。先清心胞解营热，待食进便通再调，说明木火盛、心营热为当前病机重点。", []], "1812": ["治法", "此段仅载方药，无脉象可录。复脉汤去参姜桂，是于炙甘草汤中去温补之品，取滋阴养血、复脉通营之意，用于阴亏脉失所养之证。去参姜桂者，避其温燥助热，专事濡润，属治法范畴，非主病或病机直述。", []], "1813": ["病机", "原文未载脉象。时热属上焦，逾时自解，缘体质素薄，长夏坐蓐，肝肾阴伤，诸气发泄，阴不恋阳，冲脉上冲而心热骨痿。总由阴亏不复元，久延成损。法宜填补下焦、摄固迎养，与清润治肺之咳无预，点明病本在下焦阴亏。", []], "1814": ["预后", "脉似数而按之芤涩，芤为血虚，涩为精亏，数非实热乃虚阳浮动。产后三年经未行、腹中有形升逆痛、咳吐涎沫、气冲欲坐、食减便溏，是蓐劳损极不复，下焦元海少振，冲脉动则诸脉交动。原文叹非草木可图，主预后不良，佐重镇护持体质而已。", ["数", "芤", "涩", "动"]], "1815": ["病机", "原文未载脉象。产后成劳损，先伤下焦血分，寒热数发不止，奇经八脉俱伤，欲呕不饥，肝肾及胃，有形凝瘕。病机为下焦血分虚损、奇经失养、肝胃不和而凝瘕成形，故议柔剂温通补下，非峻攻可比。", []], "1816": ["病机", "产后下虚，厥气上冲犯胃，食入呕胀，脉络日空，营卫两怯，寒热汗泄，淹淹为蓐劳之病。脉空乃营卫两怯、脉络空虚之象，主产后下虚、厥气上逆之蓐劳，症见呕胀、寒热、汗泄，最难调治。", ["空"]], "1817": ["病机", "产后陡然惊恐，阴亏，厥阳上逆，血涌吐痰，胸背胁俞大痛，乃八脉空乏之征。脉空乏主阴亏阳逆、八脉空虚，故见血涌吐痰、胸背胁痛，为蓐劳重症延绵，最难全好，议镇固一法。", ["空"]], "1818": ["预后", "原文未识脉名，仅言“脉少敛，痛止血缓”，此乃前案镇固治疗后脉象收敛、痛止血缓之象，示病势渐退，故仍用镇纳以巩固，属预后转佳之征。", []], "1819": ["主病", "小产三日，脉数，头痛，脘痞，小腹坠痛，欲厥，此属郁冒。脉数主郁冒化热、气血上逆，故见头痛脘痞、小腹坠痛、欲厥，为小产后郁冒之病机。", ["数"]], "1820": ["病机", "半产一日，脉小，舌白，频频呕吐青绿水汁涎沫，左肢浮肿，神迷如寐，此胃阳大虚，肝风内泛，欲脱之象。脉小主胃阳大虚、正气欲脱，故见呕吐青绿、浮肿神迷，急急护阳安胃。", ["小"]], "1821": ["病机", "原文脉象写作“脉阳虚不升固”，非具体脉名，故脉象要素为空。其病机为半产下焦之损，致八脉失其拥护，少腹不和，形畏寒凛凛、忽然轰热、腰膝坠胀、带下汗出，治以通摄脉络。", []], "1822": ["病机", "怀妊三月小产半年不复，寒从背起，热起心胸，经水后期不爽，带下脉脉不断，脊膂腰髀痿坠酸疼，膝骨跗胫易冷无力，由冲任督带伤损，致阴阳维跷不用。脉虚淋滞主奇脉虚损，调治非法有终身不孕之累。", ["虚"]], "1823": ["误治", "小产后气冲结瘕，奇经八脉损伤，医谓病尚有形，佥从瘀血施治，半年来肌肉大消，内热，咯痰带血，食过脘下辄腹痛。此产后下焦真阴大亏，攻瘀清热重虚其虚，药先戕胃口，致饮食废，延成蓐劳，议肝胃两和方法。", []], "1824": ["病机", "脉数右大，数主热、大主虚，右脉候气分脾胃。胎漏两月而腹痛恶露未尽，是厥阴肝血失养、血滞不行，郁而化热，故脉数大。肝虚不能藏血则漏下，血滞胞络则腹痛恶露不净，脉症相合，示虚中夹滞、血分有热之机。", ["数", "大"]], "1825": ["病机", "原文列新产三病：痉、郁冒、大便难，总因亡血伤津。脉紧数洪大有力者，紧为寒郁、数为热、洪大为邪盛，乃血虚汗出、风入筋脉失养而劲急之象；洪滑弦滑则示津亡胃燥、阳气上厥。三病虽异，皆亡血伤津所致，脉象反映虚中夹风、津亏阳浮之病机。", ["紧", "数", "洪", "大"]], "1826": ["病机", "本段未出具体脉名，强调产后气血大亏，七情六气稍有感触即病，治当辨脉候以明内外之因、审阴阳以别虚实。朱丹溪主大补气血，然症多端须尽变，不可一味逐瘀或守温补。脉候在此为辨虚实、定攻补之依据，示产后病机以气血亏虚为本、虚实夹杂为变。", []], "1827": ["病机", "原文未载脉象。瘕聚结于左，肢节寒冷，断为病在奇脉（冲任督带），以辛香治络。左属肝，瘕聚为气滞血凝有形之积，肢冷示阳气不达四末、络脉痹阻，故用辛香走窜入络以通阳散结，病机为奇经络脉凝滞、阳气不通。", []], "1828": ["病机", "原文未出脉象，仅言脉症向安。痛时少腹满胀，有形疝瘕略小，是营虚而气滞未净。前用辛甘化风法已效，今于益营之中佐通泄其气，取通则不痛之义。病机为营血不足、气机壅滞，瘕聚渐消而未尽，治当补中寓通。", []], "1829": ["病机", "原文未载脉象。右胁攻痛作胀、应时而发，断为浊阴气聚成瘕、络脉病。右胁属肝肺之分，浊阴之气聚而不散，阻于络脉，故攻痛胀满、发作有时。治以温通营络，使阴浊得温而行、络脉得通而痛止，病机为阴寒浊气凝聚肝络。", []], "1830": ["病机", "原文未出脉象。瘕聚有形高突，痛在胃脘心下或连腰少腹，经水后期色黄白，断为冲脉为病。络虚则胀、气阻则痛，冲脉隶于阳明，气血凝络则经阻，故以辛香入络、苦温通降。病机为冲脉气血凝滞、络虚气阻，扰及胃脘。", []], "1831": ["病机", "原文未载脉象。瘕聚痼结，痛胀妨食、得食不下，月经阻不至而带淋甚多，断由冲任脉络扰及肝胃逆乱。冲任失调则经阻，肝胃气逆则痛胀妨食，久延恐成蛊疾。病机为冲任脉络瘀结、肝胃气机逆乱，属虚实夹杂之痼疾。", []], "1832": ["病机", "原文未载脉象，从症析机：络血不注冲脉则经阻，气攻入络聚为瘕而痛，冲脉隶阳明，痛升于右、胀及中脘、呕清涎浊沫，操家烦怒致肝犯胃。病机为肝气横逆、络瘀成瘕、胃失和降，故泄肝救胃。", []], "1833": ["病机", "原文未出脉，据症言机：脐下瘕渐大，气塞心胸咽喉，经水百余日不来，溲利便不爽，情志郁则肝胆相火内灼，冲脉血涸，气滞血瘀。口甜食后痞为木火郁气犯胃，故用苦辛清降。", []], "1834": ["病机", "原文未载脉，凭形色脉象断非通经丸所宜：经阻半年腹渐大，痛不拒按，溲短便通，下气还攻于络，有形若症瘕。病机属肾气不摄、冲任虚滞、气攻络脉，故用炒枯肾气丸温摄下元。", []], "1835": ["病机", "脉弦左搏，弦主肝木，左搏为肝气偏亢。惊忧嗔怒动肝，乘中土，胃伤失降，脉络逆并，故胃痛拒按、胁拘、少腹瘕聚、气冲为胀呕。久发中衰，辛香燥烈更伐脾胃，议疏肝安土。", ["弦"]], "1836": ["病机", "原文未出脉，述少腹疝瘕多年，冲起散漫，胃脘两胁痛甚欲呕，足跗瘰裂水，乃下焦至阴湿热瘀留，经脉络中交病。前安胃泄肝效而未尽，故须宣通气血壅遏，使络脉畅达。", []], "1837": ["病机", "脉小身不发热，非时气，小为虚候。经水由冲脉下，冲脉隶胃，消导寒凉伤胃，冲脉上冲犯胃为呕、攻胸痞塞、升巅昏厥。小腹有形兼动气，即《经》言冲脉为病，女子瘕聚，奇络虚滞不司流通。", ["小"]], "1838": ["病机", "脉左弦涩，弦主肝郁气逆，涩主血滞络瘀。少腹攻逆，痛即大便，乃肝气不疏、厥阴滞积，气攻下迫则便。左脉候肝，弦涩并见，正合气滞血瘀、络道不利之病机。", ["弦", "涩"]], "1839": ["病机", "原文未出脉，专论症瘕：症者征也，血食凝阻有形不移；瘕者假也，脏气结聚无形可动。病在肝脾，胃与八脉亦与有责。治从诸经，辨气血偏胜：气虚补中行气，气滞开郁宣通，血衰养营通络，血瘀入络攻痹。", []], "1840": ["病机", "原文见咳嗽脉数舌白，前医误作温邪在肺用辛凉轻剂，而烦渴愈甚。脉数主热，热邪已深十三日不解，不独气分受病，且体质素虚、面色黯惨，热入血室，五液暗耗，内风掀旋，故三日前已发痉。数脉在此示热深而阴伤，非轻浅肺卫之热，故议玉女煎两清气血以救阴。", ["数"]], "1841": ["病机", "又脉数、色黯、舌上转红，寒热消渴俱缓，说明前用两清气血后伏邪已得效验，数脉尚存示余热未尽。原文强调体质素虚，驱邪及半必兼护养元气，仍佐清邪；又见腹痛便溏，故以和阴为急。此数脉主余热未清而正气已虚，非纯实热之象。", ["数"]], "1842": ["病机", "脉右数左虚，临晚微寒热。右数主气分余热未清，左虚主阴血不足，正合热入血室后阴分受损之机。临晚微寒热乃阴亏不能敛阳、营卫不和之候。故用复脉汤去姜桂，去辛温以避助热，专事滋阴复脉，以左虚为用药着眼处。", ["数", "虚"]], "1843": ["病机", "脉右长左沉，舌痿饮冷，心烦热，神气忽清忽乱，经来三日患病，血舍内热气乘空内陷。右长主热盛于气分，左沉主热瘀于血分，故以瘀热在里论病。神气忽清忽乱正是蓄血如狂之候，病已至危，从蓄血例治。此脉示热邪由气入血、瘀热互结之机。", ["长", "沉"]], "1844": ["病机", "此段述金匮热入血室五法，第三条中风寒热、经水适来七八日，脉迟身凉，胸胁满如结胸状，谵语者，显无表症，全露热入血室之候。脉迟身凉非虚寒，乃热邪内陷血室、阳气不能外达所致，故急刺期门以泄血室之热，示针力比药力尤捷。", ["迟"]], "1845": ["病机", "两脉俱细，右涩欲歇，脉形细耎，按之不鼓。细耎不鼓主阳气衰微，涩而欲歇主血少气滞。症见肢冷、下血液七八日、痛不饮水、面色枯白气黯，明是冷湿中于太阴，非积滞实热。前医误用大黄攻荡，故令勿进，急煎人参炙草炮姜归芍以温中复阳。", ["细", "涩", "耎"]], "1846": ["小儿", "此段论小儿三岁以内看虎口三关脉纹，以纹色辨病：紫热、红伤寒、青惊风、白疳病，黄淡红为平常小恙。筋纹宜藏不宜暴露，见黑色则危险。又分部位轻重，下截风关轻、中截气关重、上截命关尤重，直透三关为大危。纯以纹色部位言小儿病之浅深吉凶，未及具体脉名。", []], "1847": ["小儿", "此段辨伤寒与痘疹两途，伤寒邪由外入，痘子热从内起。周岁小儿初热即现惊搐昏迷最多，世俗谓惊痘最好未必皆然。原文述痘毒由肾至肝至心脾及肺，自里至外、自深及浅，全藉身中元气领载充长，化毒为浆，浆厚苍老始结痂，毒外泄元气内返则无变症。周岁元弱，故有热一日即出之顺候。", []], "1848": ["病机", "原文论痘疹收痂之际，真气归里，肺合皮毛为末传，灌胀蒸迫致气泄为咳，非毒气未尽。此时上焦转燥，阴气告匮，故夜暮属阴时烦热。脉象未识，然病机为痘后肺燥阴亏、气泄咳嗽，与苦寒误治伤胃相关。", []], "1849": ["主病", "春温伏邪暴感，见头痛恶寒发热、喘促鼻塞身重、脉浮无汗，为邪在表，原可表散。春令温舒，辛温宜少用，阳经表药忌混乱。脉浮主表，无汗为寒邪束表，故宜辛解表邪，兼顾里证。", ["浮"]], "1850": ["病机", "痘中复感温邪，口鼻触入，由中道布及络脉，致目泛失明、左肢不举、少腹肿满、两足皆痿，小便淋滴，大便渐塞。此厥阴肝热，疝瘕失疏泄，内风旋转，腑阳不通。经言暴肿暴胀皆风火变动，故议咸苦通在下结热。", []], "1851": ["病机", "陈官人自汗短气咳嗽，风温见症，肌腠痤痱，色脉是虚。补脾辛甘不应，腹满按之自耎，二便通利，腹痛时发时止。考幼科五疳与大方五劳相类，疳因郁热为积为虫，此饮食不充肌肤，病来非暴，攻之由渐，宜甘凉清养胃阴。", ["虚"]], "1852": ["主病", "虞面色痿黄，脉形弦迟，汤水食物入咽吐出，神气恹恹欲寐。此胃阳大乏，风木来乘，渐延厥逆，俗称慢脾险症。脉弦为风木乘土，迟为胃阳不足，故主胃阳虚而肝木犯胃，治宗仲景食谷欲呕者。", ["弦", "迟"]], "1853": ["病机", "世俗所称慢惊风，症见吐泻兼作、气怯神倦、虚烦搐搦、痰喘不食、脉虚无神、睡则露睛。此由外感未清、误治、饮食失调或病后而成，吐伤胃泻伤脾，土衰不生金，中虚木乘克，皆肝脾肺胃之病。脉虚无神为元气亏虚，治宜急顾本原，扶土生金，安胃和肝，温养肾阳。", ["虚"]], "1854": ["病机", "唐面青脉濡，神呆，舌缩不伸，语寂寂然，痫症四肢皆震，口吐涎沫。此阴风已入脾络。脉濡主湿、主虚，面青为肝色，神呆舌缩为脾络受阴风所扰，四肢震与吐涎沫为风动痰涌之象，故主阴风入脾络之痫症。", ["濡"]], "1855": ["误治", "小儿痫痉厥本属险症，今死者多因医者不察病情，概以芩连钩藤菖蒲橘红夹金石之药清火降痰，此不善治也。病家父母失于调治，当元气与病邪交战之际，如战汗将止、吐泻之后、痉厥渐苏、适然大便等时，宜养元气，若误治则遗祸。", []], "1856": ["治法", "炙甘草汤又名复脉汤，原文未出脉名，其方以炙甘草为君，配生地、麦冬、阿胶、麻仁、桂枝、姜枣，意在益气滋阴、通阳复脉。所谓复脉，针对的是气血阴阳俱虚、脉道不充而现结代或细弱之证，故本条主旨属治法，示人虚劳脉结代者以此方复其脉气。", []], "1857": ["治法", "通脉四逆汤即四逆汤加葱白，原文未标脉名，然方名通脉，所对乃阴寒内盛、阳气衰微、脉微欲绝之证。加葱白取其辛通阳气、宣通上下，使欲绝之脉得通。随症加法更见因人施治之意，本条主旨为治法，示回阳通脉之方。", []], "1858": ["治法", "通脉四逆加猪胆汁汤，于通脉四逆汤中加猪胆汁，原文未出脉名。此方针对阴寒极盛而拒药、或阳亡液竭之候，胆汁苦寒反佐，引阳药入阴，防格拒。脉当微细欲绝，本条主旨属治法，示回阳救逆兼反佐之法。", []], "1859": ["治法", "生脉散以人参、麦冬、五味子组成，原文标脉散。脉散者，气阴两伤、肺气耗散、脉道不敛之象，故用参补气、麦冬养阴、五味收敛，使散越之气复聚、耗散之脉复敛。本条主旨为治法，示脉散者当益气敛阴生脉。", ["散"]], "1860": ["治法", "生脉四君子汤即生脉散合四君子汤，原文脉散。脉散主气阴耗散，然合四君子，则重在补益中气，示脉散而兼脾胃气虚者，当于生脉敛阴之外培补中州，使气充则脉自敛。本条主旨属治法，明合方之用意。", ["散"]], "1861": ["治法", "生脉六味汤即生脉散合六味汤，原文脉散。脉散为气阴耗散之象，合六味则兼滋肝肾之阴，示脉散而兼肾阴不足者，当敛肺生脉与滋填下焦并行，阴充气聚则散脉可收。本条主旨为治法，见合方随证之妙。", ["散"]], "1862": ["治法", "生脉六味丸即六味丸合生脉散，原文脉散。脉散主气阴两伤，丸剂合生脉，缓补肝肾兼敛肺气，示脉散属虚损日久者，宜丸药常服、肺肾同调。本条主旨属治法，与汤剂条相呼应而剂型有别。", ["散"]], "1863": ["其他", "本条论先生用古方取法而不胶柱，如复脉、建中、泻心等皆随证加减，用牡蛎泽泻散只取二味，案中但书方名而不列药味者，决非尽用板方。原文未出脉名，主旨在于说明读案当以意会其加减之法，属其他类，非专论脉。", []], "1864": ["病机", "脉形滑数，滑主痰食内壅，数主邪热未解。冬温感邪月余，身热未退，舌灰燥腻、中脘未宽，显系挟食中焦蒙阻、膜原未化；痰多喘咳、神昏谵语，为痰热蒙蔽心包、营卫未清之象。滑数相合，正示邪热与痰食交结，故拟泄风通里，导邪外出。", ["滑", "数"]], "1865": ["病机", "脉形浮滑，浮主邪在表分，滑主痰湿内盛。久患哮喘，肺胃感寒而发，咳嗽痰多气逆，舌滑带腻，皆痰湿壅肺、寒邪束表之征。浮为肺胃受寒、病位偏上偏表，滑为痰浊内蕴，故断为肺胃受寒即发，拟泄风清肺，使表寒解而痰湿化。", ["浮", "滑"]], "1866": ["病机", "脉形滑数，滑主痰浊壅盛，数主热毒内炽。疡疮未愈，毒入内攻，齿浮头胀、骨节举动即痛，喉肿腐烂、黏痰甚多，舌肿厚带腻而疼，皆余毒内传、上攻咽喉、痰热胶结之候。滑数正合毒热痰浊交蒸，症属险患，故拟清凉化毒，另用紫雪丹搽舌以泄热毒。", ["滑", "数"]], "1867": ["病机", "脉形迟涩，迟主阳气不运，涩主气血滞涩。婴孩肺风痰喘、气逆上壅，面浮肢肿、腹胀如箕、阴囊水肿光亮，舌苔滑腻，显系脾胃受邪、运行失职，土不制水，水气泛溢，木不能荣、金无取主。迟涩正示阳微气滞、水湿内停，故拟葶苈汤加减以泻肺行水。", ["迟", "涩"]], "1868": ["病机", "脉形滑数，滑主痰食内伏，数主温邪化热。冬温感寒两候，身热神昏多语，舌色带灰，气食感寒内伏，痰热互结，蒙蔽清窍。滑数相兼，示邪热与痰食胶结于里，热势鸱张而正气渐耗，故症属沉重，恐防邪陷，宜辛凉通滞，透热化痰导滞。", ["滑", "数"]], "1869": ["病机", "脉形细数，细主阴液亏耗，数主邪热未清。前投辛凉通滞后，冬温邪热内伏，神识昏蒙，舌燥而红、目赤、寤寐少安、二便未行，显系热灼津伤、燥热内结、心神被扰。细数为热盛阴伤之征，故症属棘手，防其昏陷变端，仍宜清燥化热通滞，兼顾护阴。", ["细", "数"]], "1870": ["病机", "原文未识脉名，故脉象要素从缺。所述喉闭肿胀、饮食不下，为风火相传，脾胃之火蒸于肾脉、循于喉咙；内气一弱则水火不济，虚火循经上灼咽喉。病机重在风火壅盛、水火失济，故以清火散肿为主，使火降肿消而咽喉通利。", []], "1871": ["病机", "六脉浮洪，浮主气逆于上，洪主火盛阳亢。气逆喘哮、言语不续，肺气受邪，舌燥津亏，标本失运，水不制火，肝经独旺，火炎上喘。浮洪并见，正示肝火挟肺气上逆、火热灼金之机，故拟抑火清金、定喘降气，使火降气平而喘自定。", ["浮", "洪"]], "1872": ["病机", "脉虚为气血大亏之象，舌滑示津液未竭而筋脉失养。久痿虽愈，然遍体身疼骨楚、四肢酸软，正是肝血不足、血少筋枯所致。脉虚主正气亏虚，血不荣筋，故见骨节酸痛；舌滑则阴血虽亏而痰湿未盛。治宜养血荣筋，从肝血亏虚立论。", ["虚", "滑"]], "1873": ["病机", "六脉细软为久病元虚、脾土不足之征，细主阴血亏少，软主阳气不振。舌红燥、津液大亏、干呛无痰，乃土衰火旺、虚火上灼肺金；纳谷少思则脾运失职。脉细软与舌红燥并见，示气阴两伤而虚火内扰，久延有成怯患之虞，故宜扶脾滋阴抑火。", ["细", "软"]], "1874": ["病机", "失血后脉来细软，细为阴血亏耗，软为脾气虚弱。咳呛音哑乃肺金失润，舌色虚滑、纳谷少思、得饮即吐，皆木旺土衰、脾阳失运之候。脉细软正合气血两虚、肝木乘脾之机，故拟泄肝养脾清肺，以脉证相参而知脾阳不运为关键。", ["细", "软"]], "1875": ["病机", "脉洪为湿热疫邪亢盛之象，洪主邪热鼓动气血。身热未解、头疼骨痛、神识昏蒙，舌腻，皆湿热疫毒蕴蒸、蒙蔽清窍所致。脉洪与舌腻并见，示热势虽盛而湿浊未化，防其发疹斑，故宜疏肌透解，使邪从表解。此脉主邪实热盛，非虚候可比。", ["洪"]], "1876": ["病机", "脉来浮数，浮主邪在肌表，数主热邪亢盛。疫邪一候身热未退，舌色黄腻、神烦头晕、遍体骨楚，皆温热未化、邪郁肌腠之征。前已疏肌透解而脉仍浮数，说明表邪未尽、热势未衰，故仍守疏肌透解之法，使温热从表而解。", ["浮", "数"]], "1877": ["病机", "脉形弦滑，弦主肝胆气郁，滑主痰湿内蕴。疫邪旬日，畏寒身热未解，舌白腻、中脘未宽、呕恶黏痰，正是湿热内蕴未清、痰浊中阻之候。脉弦滑与舌白腻相应，示湿痰郁于中焦、肝胆失和，故拟温胆解和，化痰清热以宽中脘。", ["弦", "滑"]], "1878": ["病机", "脉象形弦，弦主气机郁滞、肝胆不和。进温胆后身热未退，舌苔黄腻、胸脘稍宽而呕恶未减，说明疫邪未楚、痰湿郁热尚恋中焦。脉弦与苔黄腻并见，示湿热未清而气郁仍在，症属较重，故仍宜加减温胆以和解枢机、清化湿热。", ["弦"]], "1879": ["病机", "脉象虚软，虚主气血亏耗，软主脾阳不振。久漏血有块、腹痛，乃漏下日久、气血两伤，冲任不固而瘀滞未净；舌苔微白无色，示气血不能上荣。脉虚软正合久漏正虚之机，故拟止痛止血，标本兼顾，以固冲任而止漏下。", ["虚", "软"]], "1880": ["病机", "脉来迟涩，迟主寒，涩主湿滞血少。本案感冒受寒，腹疼上吐下泻，湿热未清，舌苔带白，显系寒湿困阻中焦，脾胃升降失司，气血运行不畅，故脉迟涩。迟涩并见，提示寒湿内盛，阳气不宣，与吐泻交作、腹痛相应，治宜和中分利、温中。", ["迟", "涩"]], "1881": ["病机", "脉象六阴兼之带浮滑，浮主表主风，滑主痰主湿。患者感冒受风，气逆不舒，痰多咳嗽，气喘胸脘不宽，舌白腻，此寒客肺胃，湿痰阻滞中焦。浮滑之脉反映风邪外袭、痰湿内壅，肺失宣降，故见咳喘胸闷，治宜开泄化痰定喘。", ["浮", "滑"]], "1882": ["病机", "脉象形浮，浮脉主表，风邪袭肺。风火挟寒，喉疼咳嗽，舌色微白，此寒入肺胃，邪在卫表。浮脉为风邪外束、肺气不宣之征，与喉疼咳嗽相应，故拟辛凉疏解，使邪从表解。", ["浮"]], "1883": ["病机", "脉象细软，细主血虚，软主气虚。胃气不宣，饮食无味，两筋乏力，舌色光滑，显系脾胃虚弱，气血不足，筋脉失养。细软之脉反映营血亏虚、中气不振，故治以开胃养血、和络安荣为主。", ["细", "软"]], "1884": ["病机", "脉来细软少神，细软主气血内亏，少神为胃气不振。恙经月余，身热已解，湿热未清，咳嗽气逆，干呛无痰，痞闷纳呆，寤寐欠安，舌微白带垢。此湿热蒙阻未清，气血内亏，胃气不宣，故脉细软少神，治拟开泄化痰。", ["细", "软"]], "1885": ["病机", "六脉细软少神，细软为营虚气弱，少神乃精力大亏。前服宣胃补中养营和血剂后自汗甚多，神不守舍，神志不宁，纳谷不运，舌色虚滑，精液干枯少泽。此营卫不固，毛窍空疏，汗流时出，气血亏虚，故脉细软少神，治宜养营敛汗、扶原补气养血。", ["细", "软"]], "1886": ["病机", "脉象浮滑，浮主风邪上浮，滑主痰涎壅盛。因失火受惊，奔走劳伤气，哮喘气逆，言语不能接续，风邪传入肺经，舌白腻苔。浮滑之脉示风邪乘虚上浮，痰壅气逆，症属棘手，防其痰壅，故暂宜疏肺化痰降气。", ["浮", "滑"]], "1887": ["病机", "脉象迟涩，迟主寒，涩主邪滞血行不畅。冬温春发，寒邪入于肺胃，初起咽喉肿痛，复加大便泄泻，身热未凉，不语，神色模糊，多语昏蒙，舌不出关。迟涩之脉反映寒邪传内，阳气被遏，气血凝滞，症属险危，恐防邪陷内闭，故宜疏肌透解、祛痰开泄、清心。", ["迟", "涩"]], "1888": ["病机", "脉来浮滑，浮主表邪未解，滑主痰湿食滞内蕴。原文“冬寒春发，两肋吸痛插胁，伤寒兼之咳嗽，身热未解”，说明寒邪外束肌表，内有痰湿阻滞，故脉浮滑。舌白腻亦为寒湿之象。此脉主伤寒兼咳、邪在表里之间，症见身热、胁痛、咳嗽，治宜疏肌通里。", ["浮", "滑"]], "1889": ["病机", "六脉迟涩，迟主寒凝气滞，涩主血行不畅、食积内阻。原文“伏邪身热未解，舌色黄腻，脘闷未宽，挟食停滞中焦，拒按作痛”，说明冬温伏邪内蕴，兼食滞中焦，气机壅塞，故脉迟涩。此脉主邪伏食滞、中焦不通，症见脘闷拒按、身热不解，属棘手险重，防邪陷转脱。", ["迟", "涩"]], "1890": ["病机", "六脉迟涩，迟涩主寒凝食滞、气机不畅。原文“年高花甲有余，冬温春发，身热一候未解，中脘未宽，拒按作痛，呕逆气冲，挟食停留，胸中迷闷，神色有时模糊”，说明伏邪挟食滞中焦，胃气上逆，故脉迟涩。此脉主邪入膜原、食滞中州，症见呕逆迷闷，证属重险，防厥逆气脱。", ["迟", "涩"]], "1891": ["病机", "脉来浮滑，浮主表邪未尽，滑主痰食内停。原文“身热转汗身凉，胸脘拒按仍痛，大便虽解未畅，伏寒停食未清”，说明表邪虽得汗减，但伏寒停食仍滞中州，故脉浮滑。舌白腻亦为寒湿未化之征。此脉主表里同病、伏邪未清，症见胸脘痛、便解不畅，防其转变。", ["浮", "滑"]], "1892": ["病机", "六脉浮洪，浮主邪未全退，洪主热盛气分。原文“身热已退，舌色根腻，中脘略宽，大便解而薄溏，色黑，小便短赤”，说明湿热伏邪尚阻中宫，虽身热退而脉仍浮洪，为余热未清、湿滞未化。此脉主湿热内伏、邪阻中焦，症见便溏色黑、溲赤，症属险重，防其增剧。", ["浮", "洪"]], "1893": ["病机", "六脉浮洪，浮主邪在表，洪主热盛。原文“冬寒温发，身热未解，便溏泄泻，现发痧斑未透，胸闷未宽，挟食滞”，说明寒温外袭，热邪内盛，兼食滞中焦，痧斑欲透未透，故脉浮洪。此脉主表里俱热、邪欲外透，症见身热、痧斑、胸闷，恐邪陷转变，宜疏肌透解。", ["浮", "洪"]], "1894": ["病机", "六脉迟涩，迟主寒凝，涩主气滞血瘀。原文“寒邪入肺，非近时感受所得，因冒雨当风所致，平日积受肺胃两经，每遇西北风高土燥，哮喘气逆难舒，中州迷闷，咳呛黏痰”，说明寒邪久伏肺胃，气机壅滞，故脉迟涩。此脉主寒邪恋肺、气逆痰阻，症见哮喘咳呛、坐卧难安，下虚上实。", ["迟", "涩"]], "1895": ["病机", "六脉细小，细主血虚，小主气弱。原文“妊娠三月，小产八天，遍体骨痛腰酸，瘀血停留作痛，舌苔虚滑，津液干燥，面白无神”，说明小产后瘀血内停，气血两伤，故脉细小。此脉主瘀血凝滞兼气血虚损，症见骨痛腰酸、面白无神，治宜祛瘀通理生新。", ["细", "小"]], "1896": ["病机", "六脉细软，细主气血不足，软主虚与湿滞。本案感受痧气后胸闷不宽，舌色光滑，说明痧毒未清，气血凝滞，脉道不充故细软。脉象反映正气已虚而邪滞未化，故治以和气血、通滞宽中，非单纯攻邪。", ["细", "软"]], "1897": ["病机", "浮滑脉主痰湿壅盛。浮为邪在表或阳气浮越，滑为痰湿内阻。本案挟郁胸中，痰流包络，神色模糊昏迷，天癸数月未行，正是湿痰阻滞中州、蒙蔽清窍之象。脉浮滑与痰湿尚阻中州相应，故拟化痰宽气、安神镇心。", ["浮", "滑"]], "1898": ["病机", "洪数脉主热盛。洪为热邪亢盛、气血涌沸，数为热象。本案冬寒春发，身热未解，咳呛无汗，遍体骨楚，头疼干恶，舌白腻，脉洪数，说明温邪蕴热未解，热势鸱张。脉洪数与身热、将发斑疹相应，故拟疏肌解表，防其增剧。", ["洪", "数"]], "1899": ["病机", "滑数脉主湿热痰浊内蕴。滑为痰湿未化，数为热邪未清。本案进清凉化热剂后胸脘已宽，但湿热内伏未清，寒痰尚阻中州未化，脉来滑数，舌苔略薄，说明余邪未净、痰热互结。脉滑数与湿热痰阻相应，故拟养阴清化法。", ["滑", "数"]], "1900": ["病机", "迟涩脉主寒凝气滞、血行不畅。迟为寒邪凝滞，涩为气血瘀阻。本案年逾古稀，感冒受风，入于肺胃，遍体骨楚，头疼咳呛，肋胁作痛，舌苔白腻，脉来迟涩，说明伏邪寒入膜原，阳气被遏，气血涩滞。脉迟涩与寒湿困阻相应，故宜疏风通络。", ["迟", "涩"]], "1901": ["病机", "虚软脉主正气不足、脾胃虚弱。本案前进和脾宣胃化痰剂后肝阳犯胃稍减，脾胃已和，但六脉仍带虚软，舌色微黄，说明邪气虽减而正气未复，脾胃气虚未充。脉虚软与脾胃已和但未健相应，故拟和脾开胃生津，以培补后天。", ["虚", "软"]], "1902": ["病机", "浮滑脉主风邪夹痰。浮为风邪在肺卫，滑为痰湿内蕴。本案肺经受风，寒邪内伏，咳呛干嗽，痰黏胸脘未舒，胀闷，舌色微白，脉来浮滑，说明寒邪郁于肺胃未泄，痰气交阻。脉浮滑与咳呛痰黏相应，故宜疏风辛凉法。", ["浮", "滑"]], "1903": ["病机", "浮滑脉主风邪夹痰湿。浮为风邪袭表，滑为痰湿内停。本案伏暑感风，脉来浮滑，说明暑湿内伏而风邪外袭，表里同病，痰湿未化。脉浮滑与伏暑感风之病机相应，故拟疏风泄肺，以解表化湿。", ["浮", "滑"]], "1904": ["病机", "脉来浮数，浮主邪在表，数主热，风火受寒，邪入阳明，牙疼腮肿、口燥唇干，皆阳明热盛之象。浮数相合，说明风热之邪客于肌表，尚未完全入里，故宜辛凉散解，使邪从表解。", ["浮", "数"]], "1905": ["病机", "脉滑主痰湿内蕴，患儿感受寒邪客于肺胃，哮喘咳呛、气逆不舒、痰黏难吐，风邪内伏未清，舌腻，脉滑为痰湿壅盛之征，说明寒邪与痰湿互结，肺胃气机不利，故宜泄风定喘降气。", ["滑"]], "1906": ["病机", "脉形浮滑，浮主风邪在表，滑主湿痰内盛，湿痰蒙闭中州，脾阳失运，痰阻脾胃二经，咳嗽痰黏、哮喘气逆，舌白腻，说明湿困脾阳未化，风邪与痰湿相合为患，故拟泄风化痰、利湿降气。", ["浮", "滑"]], "1907": ["病机", "脉象六阴，指六部脉皆沉细而弱，主原气虚弱，神劳不息，中虚下陷，湿痰蒙阻中州，胸脘不舒、得食饱闷、大便欲解不解，耳鸣头胀为湿痰挟肝火上升，舌苔腻垢，说明正虚湿阻、肝火挟痰上扰之病机。", []], "1908": ["病机", "脉来浮数，浮主表邪未解，数主热，复感受寒，身热未解，饮食太多停滞中州，胸脘不宽，舌苔微白，说明外邪未清而兼食滞内停，邪阻未化，故宜疏风通滞和中，表里兼顾。", ["浮", "数"]], "1909": ["病机", "前进疏风通滞宽中剂后，身热虽解未清，胸脘略宽，但脉仍浮数，舌带微白，早暮潮热未退，说明表邪未尽，余热未清，邪阻未化，故仍宜小柴胡汤加减和解退热，透达余邪。", ["浮", "数"]], "1910": ["病机", "脉来迟涩，迟主寒，涩主气血滞涩，久患胃脘寒痛，呕恶吐食，木旺乘脾，胃经无火，舌色滑腻，说明肝阳犯胃、木旺土衰，寒凝气滞，胃失温煦，故宜平肝温胃，散寒降逆。", ["迟", "涩"]], "1911": ["病机", "脉来浮洪，浮主邪在表，洪主热盛，冬温春发，身热经余，舌苔遍尖绛色，热甚则鼻衄上冲，胸脘不舒，说明寒邪内伏化热，热势鸱张，有伏邪内陷、转变之虞，故宜疏肌通里清热，表里双解。", ["浮", "洪"]], "1912": ["病机", "脉来洪数，洪为热盛气分，数为邪热内炽，与舌色干燥、神昏模糊并见，说明邪入膜原未解，热势鸱张，有内陷转剧之势。洪数之脉主热邪亢盛，故原文断为证属非轻，宜疏肌通利清热以透达膜原。", ["洪", "数"]], "1913": ["病机", "身热已退而脉来浮洪，浮为热邪未全内伏，洪为三焦热盛，与舌色尖绛、口渴神烦、小便黄赤相应，说明热入三焦脏腑，虽表证稍平而里热仍炽，故仍宜清凉化热，使浮洪之脉得平。", ["浮", "洪"]], "1914": ["病机", "六脉沉细少神，沉为气血内困，细为阴血不足，少神乃元神大耗之征，与舌带虚滑、咳呛痰黏、纳谷少思、胸脘饱闷相应，说明高年气血两亏、脾阳失运，故宜培元养血、和胃生精，防其增剧。", ["沉", "细"]], "1915": ["病机", "脉形弦滑，弦主气逆痰阻，滑主痰湿内蕴，与舌色白腻、胸脘满闷、挟食停滞相应，说明伏邪感寒、痰阻中州、肺脾两经受病，气不纳运，故拟疏肌化痰定喘、清金通里，使弦滑之脉得解。", ["弦", "滑"]], "1916": ["病机", "六脉沉迟，沉为伏寒在里，迟为阳气不振，与四肢极冷、得饮即吐、少腹作痛、肠鸣气滞相应，说明伏寒未泄、肝阳犯胃、木土未平，故见霍乱转筋、上吐下泻，拟温中下气以散寒回阳。", ["沉", "迟"]], "1917": ["病机", "脉来迟涩，迟为气血运行无力，涩为血少精亏、脉道不利，与舌色滑腻、咳呛痰多、神思恍惚、夜卧欠安相应，说明恙久气血大亏、思虑太过耗伤心脾，故宜止嗽养神，培补气血。", ["迟", "涩"]], "1918": ["病机", "六脉细软，细为气血不足，软为脾阳未复，与舌滑、呕恶虽除而脾胃未和相应，说明霍乱吐泻后邪气已退、脾胃未和、脾阳未化，故仍拟开胃和阳健脾，以复中州运化。", ["细", "软"]], "1919": ["病机", "脉来洪数，洪为温邪蕴热炽盛，数为热邪内迫，与身热未解、干恶无汗、遍体骨楚、舌色白腻相应，说明冬寒春发、温邪蕴热未解，热势有外透发斑疹之势，故拟疏肌解表，防其增剧。", ["洪", "数"]], "1920": ["病机", "六脉洪数，洪为热盛气分，数为邪热内炽，结合冬温春发、身热脘闷、谵语，显系温邪内传，热扰心神。舌尖绛根腻提示热入营分兼湿滞，故断为邪陷内传之险候，主病在气营之间，与热渴烦躁、神昏谵语相应。", ["洪", "数"]], "1921": ["病机", "脉滑数细软，滑主湿浊内蕴，数示余热未清，细软为正气已伤。前案辛凉解表后身热未解、神糊谵语，舌仍少绛，胸脘略舒，说明湿邪未化、热势渐退而正虚显露，故曰湿邪内蕴未清，恐邪陷转变，与神志模糊、舌绛相应。", ["滑", "数", "细", "软"]], "1922": ["病机", "脉形细软，细为阴血亏少，软为气弱不充。素体柔弱、恙久咳呛无痰、失音纳呆，乃木旺水亏、金失清肃之象。脉细软正合虚劳损怯之机，故断恐成怯患，与干嗽无痰、气逆失音相应，主肺肾两亏、金水不济。", ["细", "软"]], "1923": ["病机", "脉形浮滑，浮主邪在表分，滑主湿浊痰滞。春温时邪身热经余未解，舌腻垢遍绛、红点隐隐未透，说明邪郁气分，湿浊内阻，欲透未透。浮滑之脉与邪恋表分、湿遏热伏相应，故症属棘手，恐邪内陷，宜疏解清透。", ["浮", "滑"]], "1924": ["病机", "脉象濡弦，濡主湿困，弦主木郁克土。素食大烟、病经半载，脾阳未运，木土未和，故纳谷少思、舌滑腻。濡弦并见，正合脾阳湿困、肝木乘脾之机，与纳呆、舌腻相应，主病在脾胃，治宜和脾建胃。", ["濡", "弦"]], "1925": ["病机", "脉形原带濡弦，濡为湿滞未化，弦为木土不和。进和脾建胃剂后中脘稍宽而纳谷仍少思，自汗甚多，说明胃强脾弱、气血两亏，湿困未全解。濡弦脉与脾运不健、肝木偏旺相应，故主化脾益胃和中。", ["濡", "弦"]], "1926": ["病机", "脉形弦浮，浮主邪在肌表，弦主风动气郁。疏肌透解后喉肿不退、风痧隐隐，舌腻，说明肺胃疏邪未泄，风邪郁于表分，欲透不能。弦浮之脉与风痧隐现、喉肿相应，故仍拟疏肌表里，使邪从表解。", ["弦", "浮"]], "1927": ["病机", "脉来浮滑，浮为寒邪在表，滑为痰湿壅盛。三阴疟后复感寒邪，入于肺胃，身热痰喘气逆，舌黄腻，说明外寒引动内痰，肺胃失降。浮滑脉与痰喘气逆相应，症属棘手，恐防转变，主病在肺胃痰热壅阻。", ["浮", "滑"]], "1928": ["病机", "脉形濡弦，濡主湿邪，弦主风动，合而提示风温时邪挟湿，太阳肌表邪伏未解。身热不解、头痛骨楚为邪郁太阳；呕恶、舌黄腻、胸闷未舒为湿浊内阻。脉症相参，病机在表邪未透、湿滞中焦，故拟疏肌主治。", ["濡", "弦"]], "1929": ["病机", "六脉弦濡，弦为气逆，濡为湿滞，年逾六旬、恙久喘逆气不纳，心劳过度则心血内亏、气弱不运，湿痰上逆故咳呛气冲、夜卧少安。脉弦濡反映本虚标实：气血内亏为本，痰湿气逆为标，故拟泄降化痰佐治。", ["弦", "濡"]], "1930": ["病机", "六脉濡弦带软，濡软主湿、弦主气逆，前用泄降后喘逆之气冲不足，然心劳过多血衰，气血内亏未复。脉软为虚象，弦为气机不降，濡为湿痰未化。病机属气血两亏、痰湿内恋，故仍拟化痰润降，兼顾本虚。", ["濡", "弦", "软"]], "1931": ["病机", "脉形洪滑，洪为阳明热盛，滑为邪实痰滞，春温身热未解、斑疹隐隐、头痛呕恶、舌白腻，显系阳明邪伏未泄、热郁肌腠。洪滑之脉主里热壅盛，与斑疹欲透相应，故拟透肌疏解，使邪从表解。", ["洪", "滑"]], "1932": ["病机", "脉形弦滑，弦主邪郁气滞，滑主痰热内蕴，前投疏肌透解而身热未解、头痛呕恶、斑疹隐隐未透足，舌黄腻。脉弦滑示邪热仍郁肌腠、痰湿未化，故症非浅视，恐防转变，仍拟解肌透法以促斑透。", ["弦", "滑"]], "1933": ["病机", "脉形细弱，细为阴血不足，弱为脾气虚衰，恙久阴虚内亏、火旺土衰，故呕恶气逆上冲、咳呛无痰、纳谷少思。脉细弱正合脾土未运、木来乘土之机，本虚为主，故拟化脾醒胃一法。", ["细", "弱"]], "1934": ["病机", "脉形弦滑，弦主风邪郁表，滑主痰热内壅，时邪一候而身热未解、呕恶胸闷、挟滞下泻、入暮神昏多语、热甚鼻衄，舌白腻。脉弦滑示风热挟滞内郁、邪有入里化斑之势，故防发斑疹，拟疏风辛凉法。", ["弦", "滑"]], "1935": ["病机", "脉形弦数，弦主邪郁未解，数主热盛，身热经余未解、鼻衄已止而舌滑腻遍绛、红点隐隐，显系邪热未清、郁于肌腠血分。脉弦数正合热郁未透之机，症非轻视，宜疏风解肌以透余邪。", ["弦", "数"]], "1936": ["病机", "六脉芤虚，芤主失血，虚主神气不足。瘀流失血后，血去脉空，故脉芤；心劳神虚，气血不充，故脉虚。遍体潮热乃水亏火旺、络虚所致，阴不制阳则潮热，络脉空虚则失血。此脉象直接反映阴血亏虚、虚火内扰之病机，主失血后阴亏火旺证。", ["芤", "虚"]], "1937": ["病机", "失血已止而六脉仍芤虚，说明血去络空未复，气血未充。右胁作痛、遍体烦热，乃肝旺水亏，阴不潜阳，虚火内炽。芤为血虚，虚为气弱，脉象未因血止而改善，提示阴血亏虚为本，肝阳偏亢为标，故以益阴降火培元为法。", ["芤", "虚"]], "1938": ["病机", "六脉弦芤，弦主肝旺，芤主失血。前进降火剂后咳呛失血，胸闷脘胀少力，肾亏耳鸣，乃肝肾二亏、阴不制阳。弦为肝阳偏亢，芤为阴血亏虚，脉象弦芤并见，说明水亏木旺、虚火上炎，灼伤肺络则咳呛失血，肾亏则耳鸣少力。", ["弦", "芤"]], "1939": ["病机", "脉形濡芤，濡主湿滞，芤主血虚。恙久脘痛呕酸，积饮多年，气血大亏，中焦腹胀气满，舌黄腻，乃水亏肝旺、脾湿不化。濡为湿困，芤为血伤，脉象提示气血亏虚而湿浊内蕴，肝旺乘脾，故症属棘手，恐防失血增剧之变。", ["濡", "芤"]], "1940": ["病机", "脉形弦软，弦主风动，软主虚。久虚三阴未愈，四肢麻木，真元不足，血虚风燥，舌滑。弦为血虚生风、肝木失养，软为气弱不充，脉象弦软并见，说明阴血亏虚、虚风内动，筋脉失濡则麻木，真元不足则脉软无力。", ["弦", "软"]], "1941": ["病机", "脉形细软，细主阴血不足，软主气虚湿困。劳心太过，气血两亏，气不纳运，肢节酸疼，舌带虚滑。细为水亏木旺、阴血不充，软为脾湿蒙阻、气弱不运，脉象提示气血双亏而湿浊内阻，肝阴不足则木旺，脾虚则湿蒙。", ["细", "软"]], "1942": ["病机", "脉形濡弦，濡主湿滞，弦主肝旺。恙久肠红下血，怫郁阻滞，右胁作痛，内伤气血，舌津枯，纳胀饮呕。濡为湿浊内蕴、气血阻滞，弦为肝郁气滞、木旺克土，脉象提示肝郁湿阻、气血内伤，久延恐成隔患。", ["濡", "弦"]], "1943": ["病机", "脉形浮滑，浮主表主风，滑主痰主实。风热感寒于肺胃，咳呛喘逆呕恶，畏寒身热，舌白腻，胸闷不舒。浮为邪在肺卫，滑为痰湿内壅，脉象提示外感风寒、内有痰湿，肺胃失降，阳明感寒未泄，症非轻视，恐防转变。", ["浮", "滑"]], "1944": ["病机", "六脉细软，细为阴血不足、脉道不充，软为气弱无力鼓动，合之正应原文“素体内亏，精力不足，四肢软，神虚气弱”。脉不任按而柔和无力，非实邪壅滞，乃脾肾两亏、气血不充之象，故断为脾肾不足，治宜扶阴化脾。", ["细", "软"]], "1945": ["病机", "脉形弦滑，弦主邪郁少阳、气机不畅，滑主痰湿食积内蕴，与“时邪内伏身热”“舌色滑腻，头疼呕恶”相应。邪伏于里而脉见弦滑，说明表里同病、邪势方张，故原文称“症属重甚，恐防转变”，主以表里解肌。", ["弦", "滑"]], "1946": ["病机", "脉形迟涩，迟为邪阻气机、阳运不畅，涩为痰湿胶结、血行不利，正合“湿热挟痰，迷闷心络不清”“舌色滑腻”。邪伏心肝两经，蒙阻清窍，故脉不流利而迟涩，原文断为“症非浅视，恐防转厥之变”，主清心熄肝化痰。", ["迟", "涩"]], "1947": ["病机", "脉形浮滑，浮主风热在表，滑主热毒挟痰湿壅盛，与“风热唇疔，行走不定，畏寒身热，舌色滑腻”相合。热毒成疔而脉浮滑，示毒势向外游走，故原文虑其“走黄内攻”，拟清凉化毒以解表里之热毒。", ["浮", "滑"]], "1948": ["病机", "脉形迟涩，迟主寒凝气滞、邪伏于里，涩主食积痰湿阻滞脉道，正应“感寒挟食，停滞中脘，拒按作痛”“舌色根腻”。寒食互结阳明，气机不通，故脉迟而涩，原文断为“阳明伏邪挟食未化”，主表里双解。", ["迟", "涩"]], "1949": ["病机", "脉形濡弦带滑，濡主湿困、阳气不运，弦主气机郁滞，滑主痰湿内蕴，合于“湿热挟痰入于肢络，酸软”“胃不纳运，中虚气弱”。湿困膜原、脾阳不展，故脉濡而兼弦滑，主和脾化痰利湿。", ["濡", "弦", "滑"]], "1950": ["病机", "脉形弦滑，弦主风热郁阻、气机不利，滑主热邪挟痰湿内盛，与“风温时邪，身热五天未解”“舌色黄腻，喉疼咽燥，头痛骨楚”相应。风热内阻而脉弦滑，示邪未外透，故主疏风解肌，使邪从表解。", ["弦", "滑"]], "1951": ["病机", "脉形浮滑，浮示风热仍在表分，滑示痰食内滞、热邪未清，与“身热六天未解”“舌色腻燥，头胀干恶，烦闷胸脘未舒，挟食拒按作痛”相合。表邪未解而里滞已成，故防传变，仍宜疏解通滞。", ["浮", "滑"]], "1952": ["病机", "脉形弦滑，弦主风邪未解、气机郁滞，滑主痰湿食滞内蕴。原文见“身热一候未解”“头痛挟滞拒按”“中脘未舒”“干恶”，正是风邪外束、食滞内停之象；舌黄腻亦助湿滞。脉弦滑与症相符，故断为疏风通滞未彻、邪滞交阻，症属沉重，防其转汗生变。", ["弦", "滑"]], "1953": ["病机", "脉形弦数，数主热盛，弦主邪郁气滞。原文“温邪经余身热未凉”“舌色腻垢，中心带灰”“干恶挟滞蒙闭”“神昏谵语”，显系温邪湿热内伏、郁而化热，热扰心神。脉弦数正应邪热内郁、湿热胶结之势，故症属危险，恐邪陷内传。", ["弦", "数"]], "1954": ["病机", "脉形濡数，濡主湿滞，数主热郁。原文“温邪病涉九天，身热未凉”“舌色黄腻遍绛”“少腹胀满不舒”“热内阻神昏谵语”，乃湿热内阻、热势鸱张之候。濡数脉反映湿遏热伏、邪未透解，故症属险甚，防其内陷生变。", ["濡", "数"]], "1955": ["病机", "脉形濡弦，濡主湿浊，弦主郁滞。原文“温邪病涉旬日，身热未解”“舌色黄腻带灰”“少腹未舒，下焦挟热未化”“神昏烦躁谵语，口渴多饮”，为湿热挟阻下焦、邪郁未清之象。濡弦脉应湿阻气郁，故症属险重，防邪陷不测。", ["濡", "弦"]], "1956": ["病机", "脉形滑数，滑主痰热内壅，数主热邪炽盛。原文“温邪十二天身热未退”“舌色黄腻灰燥”“温热挟阻未化”“口渴神昏多语”“热甚则鼻衄上冲”，显系温热邪势内伏、痰热交阻。滑数脉正合热盛痰壅之机，故症属重险，防交节转重。", ["滑", "数"]], "1957": ["病机", "脉形滑数，滑主湿热痰浊壅滞，数主热邪内盛。原文“经今两候”“湿热邪势未清”“舌色黄灰”“口渴神烦，有时不清，谵语”，为湿热邪伏未化、热扰心神之候。滑数脉应湿热交蒸，故症属险甚，防两经传变。", ["滑", "数"]], "1958": ["病机", "脉形虚数，虚主正气已伤，数主余热未清。原文“病涉半月，湿热邪势已减，身凉”“热阻神蒙疲倦”“舌带微黄略薄”，示邪势虽减而正虚未复，余热内蕴。虚数脉正是正虚邪恋之征，故症虽浅而恐反复传变，治拟扶阴泻火。", ["虚", "数"]], "1959": ["病机", "脉形虚数带软，虚软主正气亏虚，数主蕴热内阻。原文“湿热邪伏已清，蕴热内阻”“自汗甚多，正虚邪盛”“头晕心神少安”，显系正虚邪恋、气阴两伤。虚数软脉应正虚热扰之机，故症虽减而恐增剧，治拟扶原泻火。", ["虚", "数", "软"]], "1960": ["病机", "脉形弦滑，弦主邪郁少阳阳明，滑主痰湿内蕴。风温时邪未解，身热头痛骨楚，呕恶胸闷，舌黄腻，显系邪伏阳明，痰湿阻滞，气机不畅。脉症合参，病机为邪郁痰阻，非轻浅之候，故拟疏肌透解。", ["弦", "滑"]], "1961": ["病机", "脉形洪滑，洪为阳明热盛，滑为痰热内壅。温邪未解，至夜热甚，神昏谵语，舌黄腻，腰痛骨楚，乃邪热炽盛于阳明，痰热蒙蔽心包。脉洪滑与热甚神昏相应，示邪势鸱张，恐防转重。", ["洪", "滑"]], "1962": ["病机", "脉形濡数，濡主湿邪黏滞，数主热，为湿热交蒸之象。温邪未减，胸闷不纳，午后热甚，神昏肝风震动，舌腻燥，系邪伏三焦，湿热内阻，风火相煽。脉濡数正合湿遏热伏之机，恐邪陷生变。", ["濡", "数"]], "1963": ["病机", "脉形滑数，滑主痰热壅盛，数主邪热亢盛。温邪九天，邪热未减，胸闷气不能舒，昏蒙谵语，鼻衄上升，舌黄腻，系邪阻膜原，热甚迫血。脉滑数与痰热内炽相应，示邪伏三焦未清，症属重险。", ["滑", "数"]], "1964": ["病机", "脉数滑，数与滑并见，主邪热内盛而痰湿未化。温邪旬日，身热未凉，胸膈未宽，气闷昏蒙，舌黄腻尖燥，乃邪热内阻，痰热蒙窍。脉数滑与热甚痰阻相应，病属重甚，恐防邪陷。", ["数", "滑"]], "1965": ["病机", "脉形滑数，滑主痰热，数主热盛。温邪旬余，身热未凉，胸膈未舒，神昏谵语，舌黄燥，系邪伏未清，痰热内闭心包。脉滑数与邪热痰浊壅盛相应，症属险重，恐防邪陷内传。", ["滑", "数"]], "1966": ["病机", "脉左部空浮，右部洪滑而数。左空浮为阴血亏虚、邪热外浮，右洪滑数为阳明痰热炽盛。温邪十二天，神昏谵语，口渴烦闷，舌黄燥，系邪伏三焦，痰热内闭而阴分已伤。脉象虚实夹杂，症属危险，恐邪陷内传。", ["空", "浮", "洪", "滑"]], "1967": ["病机", "六脉洪滑而数，洪为阳明热盛，滑为痰热，数为邪热亢盛。温邪十三天，邪势未减，舌根腻带灰、尖绛津枯而燥，神识稍清，口渴烦躁，系邪伏内阻，痰热炽盛而津液已伤。脉洪滑数与热盛痰壅相应，症属危险，恐防内陷。", ["洪", "滑", "数"]], "1968": ["病机", "脉象弦滑，弦主风邪为患，滑主痰湿内蕴。本案感冒风温，身热头疼未解，舌色滑腻，遍体骨楚，热甚则鼻衄上冲，显系风热之邪外袭，痰湿内阻，热迫血络。脉弦滑与风温挟痰湿之病机相应，故宜辛凉疏风散解。", ["弦", "滑"]], "1969": ["病机", "脉仍弦滑，舌色白腻，身热已解未清，胸闷已宽。弦为风邪未尽，滑为湿浊未化，风热虽减而痰湿内滞，故脉象未转。此系风热未清，湿浊留恋，症非轻浅，恐防转传，仍拟散肌一法以疏解余邪。", ["弦", "滑"]], "1970": ["病机", "原文未识脉名，仅言六脉稍尽，舌色微黄，头疼未减。六脉稍尽提示邪势稍减而未尽，舌微黄为阳明邪阻未化之征。头疼未减，乃阳明经气不利，邪热上扰。此系阳明邪阻未化，症属虽浅，仍拟疏风散解主治。", []], "1971": ["病机", "六脉细软，细为湿邪内阻、脉道不利，软为正气不足。病涉二十多天，行路途劳，风湿内阻，膜原不清，舌色滑腻，神蒙疲倦，自汗甚多，口渴呕恶。此系阳明湿邪未清，湿困气机，正虚邪恋，症非轻视，宜泄邪化湿治之。", ["细", "软"]], "1972": ["病机", "六脉细数，细主湿邪内伏、阴液不足，数主邪热内郁。舌色根腻尖燥，神蒙疲倦，呕恶，病涉恙久，路途受寒，风湿内阻。此系阳明湿邪内伏，湿郁化热，热伤津液，故脉细数而舌尖燥。症非轻视，恐防传变，仍拟化湿主治。", ["细", "数"]], "1973": ["病机", "脉形迟涩，迟主寒凝气滞，涩主积食血瘀。挟寒积食停滞，中满作胀，舌色滑腻，胃不纳思。寒邪与积滞互结阳明，气机壅塞，脉道不利，故脉迟涩。此系阳明感寒，积滞未化，症非轻视，宜祛寒消滞一法。", ["迟", "涩"]], "1974": ["病机", "脉形弦浮，浮主表邪未解，弦主风邪内郁。风温感邪，身热未解，舌色黄腻，挟食停滞膜原，中脘不舒，呕恶作胀。此系阳明邪伏不解，表里同病，风温挟食滞交阻，症非浅视，恐转温邪时患，宜疏解表里主治。", ["弦", "浮"]], "1975": ["病机", "脉形弦浮，浮为风温时邪在表，弦为痰火内郁。恙久哮喘，痰火感伏，风温时邪身热未解，舌色白，胸闷未舒，咳呛。此系邪伏阳明未泄，外风引动内痰，肺气不利。症非轻视，宜疏风散解，兼化痰火。", ["弦", "浮"]], "1976": ["病机", "脉形细软，细为阴血不足，软为津力亏虚，合之高年头眩、水亏肝旺，知是肝肾阴虚、津不上承。脉细软不任按，正合‘身体内虚’‘津力不足’之象，故主阴虚不足，治拟扶原益阴。", ["细", "软"]], "1977": ["病机", "脉形洪滑，洪为阳明热盛，滑主痰食内壅。风温外束而食滞内停，身热未解、苔垢腻、呕恶胸闷，皆阳明伏邪未解、里热与食滞相搏之征。脉洪滑应此邪实，故防交节转重，治拟疏风化热。", ["洪", "滑"]], "1978": ["病机", "脉形弦涩，弦主邪郁气滞，涩为湿阻血行不畅。风温挟湿，身热畏寒、舌滑胸闷头晕，是阳明伏邪未泄、湿遏气机。脉弦涩正合湿邪蕴结、营卫不利之机，故症非浅视，拟疏风解肌。", ["弦", "涩"]], "1979": ["病机", "脉形弦滑，弦为阳明遏阻、气机不畅，滑主湿蕴热蒸。前药后风温湿邪未清，胸膈未舒、往来潮热，脉弦滑应此湿热内遏、表里不和之机。恐转温疟，故仍宜祛寒表里主治。", ["弦", "滑"]], "1980": ["病机", "脉形芤虚，芤主失血伤阴，虚为真元不足。失血后恙久喉痒咳呛、舌燥腻，素体柔弱，阳阴两亏，气不纳化。脉芤虚正合阴血亏耗、气失摄纳之机，故拟扶阴养肺。", ["芤", "虚"]], "1981": ["病机", "脉形细弦，细为阴血不足，弦主风热内阻、毒郁经络。唇口疔疮、疔毒行走不定、畏寒身热呕恶，是风热内阻、毒邪走窜。脉细弦应此正虚邪郁之机，恐走黄之变，故拟泄风化热。", ["细", "弦"]], "1982": ["病机", "六脉细，细主气血两亏、真元不调。病涉三月，素好酒，湿阻入络，肢节不舒、遍体骨楚腰酸，水亏木旺。脉细应此久病正虚、湿滞络脉之机，恐成痿痹，故拟祛寒和血通络。", ["细"]], "1983": ["病机", "脉形迟涩，迟主湿遏阳郁，涩为湿滞血行不畅。湿热蒙阻，中脘未舒、舌滑腻，是太阴阳明合病、湿滞未清。脉迟涩正合湿浊内阻、气机不利之机，故拟清州都一法。", ["迟", "涩"]], "1984": ["病机", "脉形弦数，弦主怫郁内阻、气机不畅，数主时邪内伏化热。风温身热已解未凉，红点未透，舌滑，中脘未舒，正合邪郁气滞、热欲外透而不得之机。脉弦数反映邪伏未解、郁热内蒸，故症见发红点未透、胸闷脘痞，恐防转传。", ["弦", "数"]], "1985": ["病机", "脉形弦滑，弦为邪郁气机、疏泄不畅，滑为痰湿内蕴、邪势鸱张。身热未凉，斑疹隐隐未透，舌白腻，胸闷干恶，皆邪势未泄、湿浊中阻之象。脉弦滑说明邪郁而湿滞，气机不利，故透疹不畅，仍拟解肌透疹。", ["弦", "滑"]], "1986": ["病机", "脉形弦浮，浮主邪在表分、欲从外解，弦主邪伏内阻、气机郁滞。温热时邪身热未凉，斑疹略透，舌苔白腻遍绛，胸闷干恶，神志时昏，乃邪伏膜原、表里同病之候。脉弦浮示邪有外达之势而内阻未彻，故仍拟透达疏解。", ["弦", "浮"]], "1987": ["病机", "脉形弦滑，弦主邪伏少阳阳明、气机郁滞，滑主痰热内蕴。温邪交一候，身热未凉，斑疹略透，舌微黄遍绛，胸脘稍宽，神志较清，乍有烦躁，干恶，便秘溺短，皆邪伏阳明未清、热结气滞之征。脉弦滑说明邪热与痰滞互结，故仍拟辛凉透达。", ["弦", "滑"]], "1988": ["病机", "脉形濡滑，濡主湿邪黏滞、正气受困，滑主痰湿内盛。温邪经余，身热未退，斑疹已透，舌滑腻遍红，神蒙不清，干恶烦闷，乃邪在募原、湿浊蒙蔽清窍之候。脉濡滑反映湿浊内蕴、气机不畅，故神蒙烦闷，仍拟辛凉化热透托。", ["濡", "滑"]], "1989": ["病机", "脉形濡滑，濡为湿困、正气不足，滑为痰热内蕴。温邪病涉九天，身热稍减，斑疹已透未化，舌遍红而燥，齿干，脘闷气促，神蒙烦躁，皆邪伏未清、湿浊与热互结、津液受灼之象。脉濡滑说明湿浊未化、邪热内郁，故仍拟辛凉化热清解。", ["濡", "滑"]], "1990": ["病机", "脉形濡滑而数，濡主湿浊内蕴，滑主痰热，数主邪热亢盛。病涉旬日，身热未凉，斑疹未化，舌中心黄燥边滑白腻，神昏谵语，唇燥齿干，烦闷气冲，乃邪伏三焦、湿热化燥、内陷心包之候。脉濡滑数示湿浊未化而热势鸱张，恐防邪陷。", ["濡", "滑", "数"]], "1991": ["病机", "脉形滑数，滑主痰热内盛，数主邪热炽烈。病涉旬日余，温热邪势未减，斑疹未化，舌灰黑边绛，唇干齿燥，面红目赤，耳聋，神昏谵语，皆邪热深入营血、痰热蒙蔽心包之重险候。脉滑数说明邪热与痰浊交结，内陷之势已显，故仍拟清邪化热。", ["滑", "数"]], "1992": ["病机", "脉弦滑带数，弦主肝风，滑主痰浊，数主邪热。原文见斑疹透而未化、神识模糊、呓语，正是痰热内闭心胞、肝风震动之象。热势未减而舌灰燥、唇干齿燥，说明邪热炽盛，痰随风动，蒙蔽神明，故症属重甚，恐邪陷内传。", ["弦", "滑", "数"]], "1993": ["病机", "脉滑数，滑为痰盛，数为热炽。原文载温邪势未减、斑疹未化、神志模糊、谵语挟痰迷闭、肝风震动，显系痰热互结，内闭心包，引动肝风。舌灰黑燥、唇干齿焦，热灼津伤已甚，故症属危险，防邪陷内传。", ["滑", "数"]], "1994": ["病机", "脉滑数，主痰热内伏。原文谓邪热内伏、肝风震动、神迷气冲，舌燥绛、液枯唇干，斑疹未化，神志昏蒙，是邪伏三焦未清，痰热上蒙，肝风内动。滑数之脉正应痰热壅盛，故症属危险，恐邪陷内传不测。", ["滑", "数"]], "1995": ["病机", "六脉濡数，濡主湿滞津伤，数主邪热未清。原文见温邪半月热势未减、肝风仍震气冲、舌红滑边腻津枯、斑疹已化未尽、神识有时昏语，乃湿热余邪未净，津液已伤，肝风未平。濡数相合，正示湿阻热蕴而津枯，故症重险，防陷厥之变。", ["濡", "数"]], "1996": ["病机", "六脉洪滑而数，洪为热盛，滑为痰壅，数为邪炽。原文载温邪余势未清、斑疹已化未尽、神志有时不清、肝风震动未平，舌燥绛，是痰热余邪内扰，正虚邪盛，肝风未靖。洪滑数脉示邪热痰浊尚盛，故症险重，恐邪陷痉厥。", ["洪", "滑", "数"]], "1997": ["病机", "左部濡数，右部洪滑而数，濡数示阴伤湿滞，洪滑数主痰热壅盛。原文谓肝阳火旺、余热未楚、窜入心经、神蒙、肝风仍震，舌绛斑疹未尽，是厥阴未平，痰热内扰心肝。左右脉象合参，正见肝阳化火、痰热内窜，故症非浅渺。", ["濡", "数", "洪", "滑"]], "1998": ["病机", "六脉洪滑而数，洪滑主痰热壅盛，数主火旺。原文见舌燥、斑疹已化、肝阳火旺、余热未清、肝风略平，是水亏木旺，痰热虽减而未清，肝阳仍亢。洪滑数脉示邪热痰火未靖，故症非浅视，仍宜清心泄肝化热。", ["洪", "滑", "数"]], "1999": ["病机", "六脉细弦带滑，细主血亏，弦主肝旺，滑主湿痰。原文谓肝阳震动、神志已清、心神少安，舌仍燥，是血亏肝旺、湿痰未泄。细弦滑相合，正示阴血不足而肝阳偏亢，痰湿内滞，故症非浅视，恐其转变，仍宜泄肝化热。", ["细", "弦", "滑"]], "2000": ["病机", "六脉稍平示余邪大势已减，然舌色略清而余邪未化，湿热挟阻膜原，中脘未舒，风疹遍体忽现忽收，乃湿热余势未尽、郁于肌腠之象。脉平非病愈，正虚邪恋故恐反复，宜泄风化热以清透余邪。", ["平"]], "2001": ["病机", "六脉已静、舌色已清而尖燥，示邪势渐退，然余邪湿热内阻气分，风疹未退，症势虽减。脉静而舌尖燥，为湿热未尽、胃津略伤之征，恐夏至节令转变而反复，故仍拟化湿清胃，兼顾气分湿热。", []], "2002": ["病机", "六脉稍静、舌色略腻，风疹已化未平，胃不纳运、中焦痞闷，此湿痰内阻中焦之候。脉静非邪尽，乃湿痰黏滞、气机不运使然，故仍宜化湿醒胃佐治，以复中焦运化。", ["静"]], "2003": ["病机", "脉形浮滑，浮主邪在肌表，滑主痰湿食滞，合舌色滑腻、头疼呕恶、胸闷，为阳明邪伏未泄、湿热内蕴之象。邪郁阳明，防发斑疹，故拟疏肌散解，透邪外出。", ["浮", "滑"]], "2004": ["病机", "脉形弦浮，浮为邪在表，弦主气机郁滞、湿热内阻，合舌白腻带滑、身热不退、胸闷呕恶头疼，示阳明邪热未清而湿热郁蒸。恐防转传，故仍拟疏肌透解，使邪从表解。", ["弦", "浮"]], "2005": ["病机", "脉形弦浮，浮示风温时邪在表，弦示湿热郁滞、气机不畅，舌白腻、胸闷呕恶，邪郁阳明。兼热入血室，症非浅视，防发斑疹与转传，故仍拟疏肌透解，透邪达表。", ["弦", "浮"]], "2006": ["病机", "脉形弦浮，浮主风温时邪在表，弦主中焦湿热挟滞、气机郁阻，舌满布白腻、头晕干呕，示湿热滞未清。症非轻渺，恐防发疹，故仍拟解肌疏透，使湿热从肌表而解。", ["弦", "浮"]], "2007": ["病机", "脉来洪数，洪为热盛气分，数为热炽，合舌绛、身热暮甚、躁烦口渴、斑疹未透、手撮鼻扇、热结旁流，示风温热毒炽盛、内陷营血、肺火壅盛。症属棘手，防内陷不测，故勉宣风清解疏托。", ["洪", "数"]], "2008": ["病机", "脉来洪数，洪为阳明热盛，数为邪热内迫。风温十二天，身热未减，斑疹显而不多，热结旁流，便泄色赤，此邪入太阴兼传阳明，热盛于内而外泄不畅，故脉洪数。洪数主里热炽盛，与胸闷神蒙、烦躁口渴、唇干口燥相应，示热邪有内陷昏陷之虞。", ["洪", "数"]], "2009": ["病机", "脉形濡数，濡为湿滞内阻，数为邪热未清。风温十三天，身热未解，斑疹较多，白㾦发现，便痢色白，此挟滞内阻，气滞不畅，湿热交蒸。濡数脉主湿阻热蕴，与胸闷泛恶、咳呛肋痛、舌绛少液相应，示邪滞内阻而津液已伤，症属重险。", ["濡", "数"]], "2010": ["病机", "脉数，数为邪热内盛。风温挟滞，身热两候未解，脘闷神疲，烦躁口渴引饮，斑疹未化，便痢白色，此邪滞内阻，热郁于里。数脉主热，与舌色光液、卧寐不安相应，示热邪伤津而滞未化，症属重险，防昏陷不测。", ["数"]], "2011": ["病机", "脉数，数为余热未清。风温半月，热退未清，挟滞内阻，神烦口渴，白㾦肌密，便痢不畅，此热邪虽减而滞未化，余热内扰。数脉主热，与舌光少液相应，示热伤津液而滞阻气机，症尚在险途，防其变端。", ["数"]], "2012": ["病机", "左关弦促，右部细数，尺按无神。弦促为肝木强横、气机郁迫，细数为阴亏火旺。经居三月，咳呛半载，木火刑金，肺痿将成，痰随气升降，津液化痰涎。弦促主肝郁气逆，细数主阴虚火动，与脘痞拒按、嗳气不舒、自汗甚多相应，示痨瘵重症，金不伐木，木乘土亏。", ["弦", "促", "细", "数"]], "2013": ["病机", "左脉仍弦，促势较优，右滑不利而虚数，两尺细软无神。弦为肝木强横，滑为痰涎内壅，虚数细软为气阴两亏。久咳肺痿将成，肝木强横侮及脾土，痰沫甚多。弦滑主肝旺痰壅，虚细数主正虚，与咳呛、自汗、舌薄根底花剥相应，防血溢失音之变。", ["弦", "滑", "虚", "细"]], "2014": ["病机", "脉左手滑涩，尺细。滑为痰涎内郁，涩为气机不畅，细为阴血不足。咳呛自汗均减，金不伐木，木动胃逆，呕吐痰沫，脘痞手按隐痛。滑涩主痰郁气滞，细主阴亏，与神枯形削、舌薄相应，示内郁不化，肝木强盛，元气大亏，虚不受补，防复感交节增变。", ["滑", "涩", "细"]], "2015": ["病机", "左脉较平，右寸滑细，两尺濡涩。滑细为痰热内蕴而阴伤，濡涩为湿滞血少。病起半载，木火克金，久咳伤阴，肺痿内损，肝气结紧。右寸滑细主肺有痰热，两尺濡涩主下元亏虚，与舌腻淡红根花相应，势恐增变，拟清金伐木。", ["滑", "细", "濡", "涩"]], "2016": ["病机", "脉滑细涩，滑主痰湿，细主阴血不足，涩主气滞血瘀。原文述肝气扰及中宫，木旺土虚，金受火克，咳呛痰沫不止，喉痒，脘痞嗳气，乃肝郁化火刑金，脾虚生湿酿痰，脉象反映痰湿内阻兼气血不畅，故主劳胜之候，慎防反复。", ["滑", "细", "涩"]], "2017": ["病机", "左关弦数不和，右细濡涩。弦为饮邪、肝邪，数主郁热，细濡为脾虚湿胜。原文谓金郁失清肃，木郁失疏泄，土郁失升降，咳呕嗳气便溏，脉象揭示肝郁化火、脾虚湿困、肺失宣降之病机，属肺咳兼胃咳、饮咳兼汗咳。", ["弦", "数", "细", "濡"]], "2018": ["病机", "两尺沉细，左关弦数，右寸弦大而滑。沉细主肾阴亏虚，弦数主肝火亢盛，右寸弦大滑为肺受火刑、痰热内蕴。原文谓血不养肝，木火疏泄太过，上克肺金，咳呛气急，居经不行，脉象示肝肾阴亏、肝火犯肺、冲任失司，损症已成。", ["沉", "细", "弦", "数"]], "2019": ["病机", "左脉弦数而浮，右细濡软数。弦为肝邪饮，浮为风热，细为正虚。原文谓咳久腠理不固，风温时感侵袭，肺失降肃，饮邪挟肝邪，眩晕嗳气，形寒身热如疟。脉象示正虚感邪，肝饮内动，风热外袭，肺胃同病，虚症感邪调治非易。", ["弦", "数", "浮", "细"]], "2020": ["病机", "脉细数无神，轻取则弦，重按则涩。细数主阴亏内热，弦为肝阳上亢，涩为邪阻血滞。原文谓素体阴亏，风邪伏于肺胃，咳呛内热，气欲上浮如喘，邪由虚入，深入于里，太少二阴皆病，脉象示正虚邪陷、阴亏火旺之损症。", ["细", "数", "弦", "涩"]], "2021": ["主病", "脉数舌腻，数主热盛，舌腻主湿浊食滞。原文述童年风温挟食，身热头疼腰痛，斑屑未透，左肋乍痛。脉数反映温邪化热内盛，食滞蕴阻，热势鸱张，症属重险，防其热陷变端，故主病为风温挟食、热郁阳明。", ["数"]], "2022": ["病机", "脉来濡数少力，濡主湿困，数主热，少力为正气不足。原文谓风温时邪挟食，斑疹较显，烦躁口渴，骨疼肋痛，邪食蕴阻阳明，化热未彻。脉象示湿温挟食、正气已伤，热邪未得透达，症属重险，防昏喘不测。", ["濡", "数"]], "2023": ["病机", "脉来濡数，舌苔根腻。濡为湿邪内蕴，数主热，腻苔示食滞湿浊。原文谓温邪挟食，内伏阳明，化热达而未彻，斑疹未透足，头疼烦躁，左肋吸痛。脉象反映湿温挟食、气络失司、热郁未清之病机，证属重险。", ["濡", "数"]], "2024": ["病机", "脉数寸浮，数主热盛，浮主邪在表分。原文谓“童年风温宿食，身热七天”，邪食互阻未泄，故脉见数浮；寸浮尤应上焦风温，与头痛胸闷、脘痛拒按、斑㾦未足相应，示邪势方张，防其内传。", ["数", "浮"]], "2025": ["病机", "脉数主热，指汗微而身热，斑疹未透，胸闷恶心，错语嗜寐，乃湿温内伏，由阳明欲入少阴。数脉为邪热内蒸之征，热为湿遏，故汗微而疹不透；神昏错语，正合“由阳明而入少阴之象”，故曰弗泛视。", ["数"]], "2026": ["预后", "脉小数，数主邪热未清，小主正气已伤。原文谓“邪未达而正已伤”，故身热不扬、耳聋嗜寐、谵语神迷，舌绛苔黄，便溏胸闷额汗，间有呃逆。小数并见，示正虚邪陷，深虑肝风内动、内闭外脱，故曰殊可危也。", ["小", "数"]], "2027": ["病机", "脉数舌煤，数主邪热，煤为津伤。原文谓“邪热伤阴，心火内炽”，故身热起伏、四肢躁动、耳聋蒙睡、不时作呃；白㾦现而热不退，是邪热未透而阴液已耗，肝风有昏厥之虞，故拟存阴透热、熄风化痰。", ["数"]], "2028": ["预后", "脉数舌煤，数主热炽，煤主阴伤。身热如灼、手指风动、呃逆时作，皆邪热伤阴、心肝火旺、虚风内动之象。原文谓“症属非轻，甚防蒙厥”，数脉不退而舌煤，示热灼津涸，有内闭昏厥之危，故再清心肝以冀转机。", ["数"]], "2029": ["病机", "脉形弦数少神，弦主肝风，数主邪热，少神为正气已衰。原文谓湿热蕴郁三焦，相火相煽，内窜心胞，故神志时清时浑、呓语如梦、手痉捻撮、斑疹隐约、咳呛痰稠、气促呃逆。弦数少神，示邪热由卫入营，扰及厥阴，震动君主，防额汗外脱。", ["弦", "数"]], "2030": ["病机", "脉形濡而数，濡主湿，数主热，为湿温挟热之象。原文谓“温邪挟湿，春感夏发，热邪渐入心营”，故神志稍清而呓语如梦，斑疹较多未透，咳呛痰黏色黑，唇燥齿黑，口渴不引饮。濡数并见，示湿遏热伏，燔灼心营，肝风震动，防痉厥额汗。", ["濡", "数"]], "2031": ["预后", "脉濡数而少神，濡为湿浊，数为邪热，少神乃阴液下耗、正气衰败。原文谓“湿温化燥劫津，邪热由气分渐入营中”，故口糜咽干、神昏谵语、耳聋、疹癍未尽、舌焦、腑闭溲赤痛。濡数少神，示液涸邪张，扰动神明，故虞额汗痉厥之变。", ["濡", "数"]], "2032": ["病机", "脉浮主新凉外束，滑主伏邪内蕴，数主温邪化热。原文谓“伏邪内蕴，新凉外束，气机闭塞”，浮滑数正合外寒束表、内热郁蒸之象，故见身热无汗、口干微恶、咳嗽胸闷、少寐烦躁，邪势鸱张。", ["浮", "滑", "数"]], "2033": ["病机", "脉滑浮而数，滑主湿滞痰浊，浮主邪在表分，数主热邪内炽。原文“温邪挟湿挟滞，上中二焦受病，气机窒塞”，故身热无汗、胸闷呕恶、胁痛、渴不欲饮，脉象反映湿滞热郁、邪势鸱张。", ["滑", "浮", "数"]], "2034": ["病机", "脉滑数，滑主湿蕴痰聚，数主热邪内郁。原文“伏邪湿蕴于气分，漫布三焦，肺金输化失司”，虽汗泄热减、胁痛止，但胸闷、口干不欲饮、痰中微红，脉仍滑数，示湿热未清、肺失宣化。", ["滑", "数"]], "2035": ["病机", "脉弦滑而数，弦主热郁气逆，滑主湿痰内蕴，数主热邪炽盛。原文“湿郁化热，热邪漫布三焦，肺失清肃，阴液渐渐损伤”，故身热暮重、口干欲饮、咳嗽气逆、便溏溲赤，脉象示湿热壅盛而阴伤。", ["弦", "滑", "数"]], "2036": ["病机", "脉弦滑而数，弦主热郁气结，滑主湿蕴痰滞，数主热邪内盛。原文“湿郁化热，热邪蕴于气分，漫布三焦，肺失清肃”，故身热不退、咳喘、便溏溲短，白㾦隐隐未透，脉象示热邪锢结、阴液暗耗。", ["弦", "滑", "数"]], "2037": ["病机", "脉弦数，右寸关濡滑尺细。弦数主热郁气结，濡滑主湿痰壅肺，尺细主阴液已伤。原文“气分𪱥郁，热灼阴液，内窜心胞络”，故神昏呓语、红疹未显、便泄溲不利，脉象示湿热内陷、阴液耗损，势属危笃。", ["弦", "数", "濡", "滑"]], "2038": ["病机", "脉濡滑而数，寸弦。濡滑主湿邪黏滞，数主热邪内蒸，寸弦主热郁上焦。原文“温邪挟湿，先由气分而传营中，清窍被蒙”，故神志时浑、耳鸣、红疹未显、白㾦晶莹，脉象示湿热郁遏、邪渐入营。", ["濡", "滑", "数", "弦"]], "2039": ["病机", "脉左弦滑，右濡数，尺不耐重按。弦滑主热郁痰滞，濡数主湿蕴热蒸，尺弱主阴液亏虚。原文“气分之热，渐渐延入营中，薰蒸于胞络”，故神志略清、呓语减、红疹微见，脉象示湿热入营、阴液耗伤。", ["弦", "滑", "濡", "数"]], "2040": ["病机", "脉弦滑数，重按少神，尺濡细，为邪热化燥内陷，劫灼津液，扰及手厥阴心包，清窍被蒙；弦主热郁，滑主痰热，数主邪热，濡细则津亏。症见神志略清、呓语、唇燥齿干、耳聋、胸闷气促，皆热陷津伤、气机不宣之象，故防风动痉厥。", ["弦", "滑", "数", "濡"]], "2041": ["病机", "左脉弦滑，右寸关濡数，沉候少神，为春温挟湿，湿与温合，蒸郁蒙蔽清窍，浊热害清。弦滑主痰热内郁，濡数主湿郁化热，寸关候肺脾，故见咳喘痰黏、耳聋唇燥、津液未回，舌尖绛根灰，属危险之候，防痉厥。", ["弦", "滑", "濡", "数"]], "2042": ["病机", "脉弦濡数，重按无力，为燥火未降，津液未回，炉烟虽熄，灰火未消。弦主余热未清，濡数而无力主气阴两伤、虚热内扰。症见疹㾦化而未清、气粗喘促、耳聋唇燥、舌尖剥，皆虚人善变、防生糜喘急之机。", ["弦", "濡", "数"]], "2043": ["病机", "脉弦小数，小为邪退，数为余热，说明阴液略回而邪火尚未清彻。弦主余邪郁滞，小示正虚，数主余热。症见寤寐不安、头眩烦仍、咳甚胁痛、痰黏兼涎、两足时肿，为病后元气未复、湿痰未化、脾失健运、肺失清肃之候。", ["弦", "小", "数"]], "2044": ["病机", "左右脉弦数而滑，为暑湿、食积交阻中州。弦主气滞，数主热，滑主食积痰湿。症见腹痛后重、红白痢不爽、小溲短赤、身热形凛、头胀、舌苔黄腻，皆湿热食积壅滞肠胃、气机不畅之象，故防淹缠，先以通因通用。", ["弦", "数", "滑"]], "2045": ["病机", "脉数，舌腻，为攻下后红白痢稍爽，头胀松而表退，但中焦尚属固结，小溲短赤。数主热邪未清，湿滞未化，故仍以苦寒攻下之中参以疏化，防其淹缠。", ["数"]], "2046": ["病机", "脉象较昨滑大减，而数尚不驯，为苦寒攻下之后，红白痢爽，但用力太猛，气伤而液涸。滑大减示积滞渐去，数尚不驯示余热未清；口渴唇燥、舌上脱液，皆攻下伤津之象，故以攻下之中参养胃生津法。", ["滑", "数"]], "2047": ["病机", "脉滑数右盛，舌垢腻尖绛，为素体湿痰，寒暑挟食，交阻肠胃，而成便痢赤白后重。滑主湿痰食积，数主热，右盛候肺脾，故腹痛气滞、肌热暮甚，症属重候，防虑增变，拟调气疏化。", ["滑", "数"]], "2048": ["病机", "脉弦数，弦主气滞、数主热，与原文“暑湿夹食，蕴阻肠胃”相合。胃阳受寒而湿食内蕴，气机不畅故后重腹痛、胸欲泛；畏寒肌热为表里不和之象。右部稍缓说明脾胃湿滞尚存，弦数示郁热未清，症势非轻，防其增变。", ["弦", "数"]], "2049": ["病机", "脉形濡数，濡主湿、数主热，与“积滞渐化而脾肾大亏”相应。痛痢稍缓而腰间冷气、气撑腹痛，是脾肾阳虚、气不运化；神疲自汗、胃呆为气虚湿困。濡数示湿滞未净而虚象已露，故宗前法更入培土之品。", ["濡", "数"]], "2050": ["病机", "脉象濡细而数、重按少神，濡细主湿虚、数主郁热，重按少神示正气大伤。原文“痛痢伤脾，肝阳亦为扰动，湿滞气分”，故满腹不舒、痛势如旧、肢冷自汗；胃钝少纳、夜难安寐为脾虚肝扰。症情颇重，防其增变。", ["濡", "细", "数"]], "2051": ["病机", "脉濡数，濡主湿、数主热，与“痢旬余，伤及脾土，运行失宣”相合。脾伤则运化无权，湿注下焦故仍重便痢、积少粪多；肝阳不潜则时欲呕逆。濡数示湿滞未化而脾虚已著，故当防增变。", ["濡", "数"]], "2052": ["病机", "脉濡数，濡主湿、数主热，与“脾虚少运，湿注下焦”相应。痢疾腹痛减而未止、后重气滞仍然，是湿滞未尽；时欲气撑嗳逆为肝阳未潜、气机上逆；胃呆钝示脾运未复。濡数示湿郁化热未清，防虑变迁。", ["濡", "数"]], "2053": ["病机", "脉濡滑，濡主湿、滑主痰湿内蕴，与“脾阳大伤，运行无权”相合。便痢虽减未止、腹痛时缓时甚，是湿滞未净；神情颇乏、自汗津津为脾阳虚弱、卫外不固；纳少宣化示运化无力。濡滑示湿浊尚存而正虚，防反复。", ["濡", "滑"]], "2054": ["病机", "脉尚弦滑，弦主肝木横逆、滑主湿滞，与“肝木横逆，脾虚气滞”相应。当脐腹痛、自汗畏寒、神疲乏力，是肝气犯脾、脾虚不运；舌苔渐润示湿滞稍化。弦滑示肝脾不和、气滞湿阻仍在，故仍宗前法。", ["弦", "滑"]], "2055": ["病机", "脉濡缓，濡主湿、缓主脾虚，与“脾阳运行失宣，气滞腹痛”相合。种种见端属佳兆，示邪渐退；惟神疲无力、气滞腹痛，是脾阳未复、湿滞未尽。濡缓为湿困脾虚之象，故仍宗前法以运脾化湿。", ["濡", "缓"]], "2056": ["病机", "脉濡滑，濡主湿、主脾虚，滑主痰湿内蕴。原文言「运行无权，枢机钝迟」，致腹痛便溏、积未能止、胃纳少化，正合脾土不运、湿热内滞之机。濡为湿困气分，滑为湿聚成痰，故治以培土调气兼理湿热，脉症相参，病在中焦脾运。", ["濡", "滑"]], "2057": ["病机", "脉滑软左弦，滑主湿痰未清，软主正气不足，左弦应肝、主气机郁滞。痛痢后邪未尽而脾运未复，故纳后少运、腰间时冷。弦见于左，示肝木乘土、气机不调；滑软并见，为湿滞中焦而脾土虚弱，仍当培土调气以复枢机。", ["滑", "软", "弦"]], "2058": ["病机", "脉滑而数，滑主湿痰食滞，数主有火。原文谓「有火有湿痰，下虚上实」，湿痰气滞阻于中，清不升浊不降，故腹痛攻至中脘、牵引腰部。滑数相合，示痰湿郁而化热、中焦壅滞，恐延休息痢，病机在脾胃输化失职、湿热痰滞交阻。", ["滑", "数"]], "2059": ["病机", "脉细数，细主气阴亏虚，数主邪热内扰。原文言「气阴既亏，寒入卫分」，肌热微微、胸闷拒纳、咳呛痰黏，正合阴虚内热、外邪恋卫之象。细为阴血不足，数为热象，故防其变，治当兼顾气阴与透邪。", ["细", "数"]], "2060": ["病机", "脉濡微数，濡主湿、微主气虚阳弱，数主邪热。高年气阴既亏，寒袭胃分，身热暮甚、咳呛频频。濡微示正气虚馁、湿滞不化，数示余邪化热，正虚邪恋，故防变迁，病机属气阴不足而外邪未解。", ["濡", "微", "数"]], "2061": ["病机", "脉滑，滑主痰湿内盛。高年气阴两亏，外感而起，身热暮甚、咳呛、胃呆烦躁，舌腻遍绛。滑脉示痰湿壅于肺胃，与舌腻相合；烦躁、舌绛又见郁热之象。正虚而痰湿恋邪，势属淹流，故防虚生变。", ["滑"]], "2062": ["病机", "脉滑而数，滑主痰湿，数主邪热。高年气阴两亏，邪恋肺胃，身热未解、暮则咳呛神疲，舌绛。滑数并见，示痰湿郁热留恋肺胃、阴分受灼，正虚邪实，故防增变，病机为痰热恋肺、气阴耗伤。", ["滑", "数"]], "2063": ["病机", "脉促数，促主阳盛而阴不能配、气机急促，数主热。原文谓「阴液内耗」，木少涵金不伐木，咳嗽气促、喉干口燥、舌干少津而绛，正合阴虚火动、肺失清润之机。促数示阴亏热扰、正气欲竭，故症为沉重，防虚中生变。", ["促", "数"]], "2064": ["病机", "脉数少神，数主火，少神为心血亏虚之征。高年操劳，心血早亏，木火刑金，故咳嗽痰稠；火克金则神疲纳呆。脉数而少神，示虚火内扰，非实热，防虚中生变。", ["数"]], "2065": ["病机", "脉细弱，细为阴血不足，弱为气衰。高年营卫两亏，水枯木贼，金受火克，故顿嗽痰黏、神疲气不下续。脉细弱正合气血双亏、气火上逼于肺之机，防喘急增变。", ["细", "弱"]], "2066": ["病机", "脉弦细数，弦为木火亢盛，细为阴血亏少，数为火旺。高年气血两亏，木火凌金，故咳嗽顿作、口渴痰黏、纳谷不宣。脉象示阴虚火旺、木火刑金之病机，症属棘手。", ["弦", "细", "数"]], "2067": ["病机", "脉濡细无力，濡为湿，细为阴亏，无力为气虚。高年久咳肺阴不足，痰多神疲，胃纳不宣，口干，脉象示气阴两虚兼湿，肺失清润，防喘厥，宜存液清肺。", ["濡", "细", "无", "力"]], "2068": ["病机", "脉弦滑数，尺细。弦为木火，滑为痰，数为热，尺细为肾阴不足。高年久咳，肺阴火耗，痰多气促，日轻夜重，脉象示痰火内盛、肺肾阴虚，宜清肺滋阴。", ["弦", "滑", "数", "细"]], "2069": ["病机", "脉滑弦虚，滑为痰，弦为木横，虚为脾弱。高年久咳肺虚，金不伐木，木横土虚，脾弱，顿食著寒，腹痛便薄，里结气滞。脉象示肺虚木横、脾弱痰滞之病机。", ["滑", "弦", "虚"]], "2070": ["病机", "脉滑细软，滑为痰，细为阴亏，软为气虚。高年气血两亏，咳呛虽减，痰吐不畅，神疲乏力，脉象示气阴未复、痰湿未净，宜养阴利肺。", ["滑", "细", "软"]], "2071": ["病机", "脉形濡数尺软，濡为湿，数为热，尺软为下虚。冬令阳失潜藏，外感袭于肺胃，身热八天，咳呛气升，痰鸣烦躁，脉象示下虚外感、痰气上逆，症险重，防喘急变端。", ["濡", "数", "软"]], "2072": ["病机", "脉濡数，濡主湿、数主热，合之外感入肺胃、冬不藏阳、痰火上逆，显系痰热内蕴而兼湿滞。咳呛气急、卧不著枕、喉间痰鸣、舌黄腻，皆痰火壅肺之征；便行带薄则脾湿下流。脉症相参，病机为痰火尚盛、肺胃同病，故防喘急变端。", ["濡", "数"]], "2073": ["病机", "脉形濡细而数，濡为湿，细为营亏，数为热盛。原文谓营分素亏、阳明有余、热盛生痰，又感外邪，肺气不顺，故身热起伏旬日不退、咳呛痰稠、夜不能著枕。细数示阴亏热扰，濡示痰湿未化，病机属营亏痰热、肺失清肃，恙非轻浅。", ["濡", "细", "数"]], "2074": ["病机", "脉仍濡数，濡主湿痰，数主热。前用顺气疏化后痰吐略爽、气机稍和，是肺降渐有权衡；然外感未清彻，身热退而未和，舌腻，脉数未减，说明痰热湿浊尚恋肺胃，气机虽稍畅而邪未尽解，故仍防变端。", ["濡", "数"]], "2075": ["病机", "脉弦细滑，弦主肝旺，细为阴伤，滑为痰盛。原文谓左升太过、右降不及，伤风引动肺逆，故咳痰稠黏、气促、卧不著枕、胃呆灼热心烦。弦细示肝木偏亢、阴分不足，滑示痰浊内壅，病机为肝升太过、肺降不及、痰热内扰，殊非浅视。", ["弦", "细", "滑"]], "2076": ["病机", "脉滑数，滑主痰，数主热。伤风半月，肺气不降，咳嗽痰吐不畅、气急神疲、胃呆妨卧、舌黄，皆痰热壅肺、肺失肃降之象。脉滑数正合痰热内盛，故症非泛视，防其变迁。", ["滑", "数"]], "2077": ["病机", "脉左弦细、右滑数，左弦细示肝阴不足、木火偏亢，右滑数示脾湿生痰、痰热内蕴。原文引脾为生痰之源、肺为贮痰之器，浊火不降、津液化为痰涎，故咳嗽、肌热起伏、心嘈妨纳、寤寐不安、喘促。病机为脾湿痰热、阳不交阴，时届严冬宜调气存液。", ["弦", "细", "滑", "数"]], "2078": ["病机", "脉滑弦细，滑主痰浊，弦主气逆，细示阴分不足。肺不清肃，咳呛半月、痰多气促、胃不和则卧不安、舌中黄、呕恶，皆痰热阻肺、胃气上逆之征。弦细并见，说明气逆之中兼有阴伤，故宜清肺降气，防虑增变。", ["滑", "弦", "细"]], "2079": ["病机", "脉滑数少神，滑主痰，数主热，少神示正气渐伤。咳已半月余，肺气不降而灼热、气急痰多黏、夜卧不安、纳谷不思，皆痰热壅肺、胃气受困之象。脉数而少神，说明邪热未清而正已受损，故殊非轻视，防喘急之变。", ["滑", "数"]], "2080": ["病机", "脉虚为正气不足之象，肝气虽略平而中气已虚，故咳痰气促、夜卧不安。舌黄提示内有郁热，虚脉与舌黄并见，说明正虚而兼痰热内扰，气逆不降。脉虚主气弱，气弱则运化无力，痰湿内生，上逆犯肺则咳痰气促，扰动心神则夜卧不安，治宜平气逆兼顾正气。", ["虚"]], "2081": ["病机", "脉滑主痰，细主阴血不足。肝阳未平，化火灼津，炼液成痰，痰热上扰则咳呛不止、吐痰呕恶；胃呆口苦为肝火犯胃、胆热上溢；神疲乏力、目圈觉酸乃阴血亏虚、筋脉失养。滑细并见，说明痰热未清而正气已伤，本虚标实，故宜清阳止咳兼顾养阴。", ["滑", "细"]], "2082": ["病机", "脉滑主痰浊内盛，弦主肝气偏亢，细为阴分不足。肺失清肃，痰多咳呛，入暮则甚，乃痰随气逆、肺降无权；纳谷不宣、卫气不和，为肝木犯土、营卫失调。滑弦细三脉并见，示痰浊、肝郁、阴伤夹杂，本虚标实，故治宜清肃上元，使肺气降而痰浊化。", ["滑", "弦", "细"]], "2083": ["病机", "脉濡细数而弦，濡细为暑湿伤阴、正气不足，数为热盛，弦主邪郁少阳、肝风内动。秋温伏暑十二日，身热午后甚、神迷如醉，疹㾦未透，胸闷泛恶，乃邪伏不达、热传血室；舌尖绛根腻、骨楚、少腹乍痛、经行即止，皆热入血室之征。脉数弦示热盛风动，故防痉厥。", ["濡", "细", "数", "弦"]], "2084": ["病机", "脉乱为气血逆乱、阴阳不相维系之象。邪传血室，少腹阵痛，痛甚症块上升，气塞肢麻发厥，神志时清时浑，乃热陷厥阴、肝风内动、气血逆乱；疹㾦色暗、肤紫唇青，为热毒内闭、血行瘀滞。脉乱与舌尖绛并见，说明邪热深陷、正气溃散，故势属危笃，防汗脱。", ["乱"]], "2085": ["病机", "脉迟濡数，迟为邪阻气机、脉道不利，濡主湿浊，数为热郁。病涉两候，邪伏不达，热传血室，小腹痞块升痛，甚则肢楚痉厥，乃邪袭厥少两阴；肤乏华光、脘腹膨胀、小溲不利、气粗吸短，为阳明热郁、气机壅塞。迟濡数并见，示热郁湿阻、正虚邪陷，故防厥脱。", ["迟", "濡", "数"]], "2086": ["病机", "脉形濡细而数，濡细为阴伤湿滞、正气亏虚，数为热邪内盛。恙延半月，身热未解，病中经行，情怀抑郁，邪不外达，热乘血室，故少腹阵痛、痞升厥逆、四肢麻冷、唇青、面出油汗；白㾦密布色暗、齿焦口臭，为热灼阴伤、邪毒内郁。濡细数示正虚热陷，防厥脱。", ["濡", "细", "数"]], "2087": ["病机", "脉象缓大，缓为胃气尚存而肝风内动之象，大为阴不敛阳、虚阳外浮。肝肾久衰，内风袭络，故肢体麻木、舌强言謇，此属痱中之象。缓大非实热之洪大，乃下元亏虚、阴气不主上承，风阳上扰清窍。脉大而缓，示本虚标实，治当重培其下，兼佐熄风。", ["缓", "大"]], "2088": ["病机", "脉形浮散，浮为虚阳外越，散为阴液耗散不收。患者眩晕仆中、口㖞眼斜、舌强言謇，乃晚年肝肾气衰、内风袭络、阴液无以上供所致。浮散之脉正应阴不敛阳、虚风内动之机，非外感表证，故拟滋阴熄风以固本。", ["浮", "散"]], "2089": ["病机", "脉形短数，短主气郁血涩，数主热盛阳亢。夏令阳升，复遭嗔怒，肝气大作，黎明跌仆神昏，舌苔黄厚，是肝阳化火、痰热内壅之象。短数之脉反映气机壅塞、火热内迫，故姑议滋清以平肝清热。", ["短", "数"]], "2090": ["病机", "脉来寸急尺缓，寸急为阳气上逆，尺缓为下元不足。烦劳则阳气张大，厥阳变化，内风鼓动上凭诸窍，致呕逆眩晕。此即经云「上实下虚，为厥巅疾」，脉象上下悬殊正合上实下虚之病机，病不在中上而在下元亏虚。", ["急", "缓"]], "2091": ["病机", "原文未识脉名，然头风痛、呕吐便秘，显系肝阳化风上冒，风阳扰胃则呕，腑气不降则便秘。柔缓和阳、复脉去参姜桂加牡蛎，意在潜阳熄风、柔肝缓急，从治法反推其病机为肝阳上亢、风动于上，非单纯外风头痛。", []], "2092": ["病机", "脉大而风温上受，咳嗽恶心鼻塞，是温邪犯肺、肺气不宣之候。脉大主邪气盛，风温初袭上焦，正气尚能抗邪，故脉应之大。此脉大非虚大，乃邪实于表之象，与咳嗽鼻塞等肺卫症候相应。", ["大"]], "2093": ["病机", "脉虚细，虚为气不足，细为营血亏。晨咳、咳动身热、拘束自汗、腹中微痛、色㿠白，病几一月，辛寒不应，显非邪著于里，而是营卫二气交怯。虚细之脉正应气血两虚、营卫失和，故宗虚则补母之义，用建中汤补益中气。", ["虚", "细"]], "2094": ["病机", "吐血已止而脉象弦数，弦为肝旺，数为火动。胃纳不减，咳嗽气冲，是少阴久虚、虚火上炎、肝阳偏亢之象。血止而脉仍弦数，说明阴亏未复、火未全平，故防血复来，脉象揭示病本在少阴亏虚而标热未清。", ["弦", "数"]], "2095": ["病机", "脉左坚，左脉候肝肾，坚为阴血亏而脉失柔润、肝气偏强之象。肝肾阴伤，阴不制阳，虚火内扰，灼伤血络而失血。左坚之脉正反映肝肾阴亏、肝阳偏亢之病机，与失血症候相应，治当滋养肝肾之阴。", ["坚"]], "2096": ["病机", "左关脉渐平，知肝血随气升之势已减；右关濡软略旺，濡软为脾虚湿滞之象，略旺示胃有虚热。结合咯血、咳逆，病机为肝肾阴亏、阳不潜藏，冲胃犯肺，络脉震动而血溢，瘀行未尽故脉未全平。", ["濡", "软"]], "2097": ["平脉", "左关弦退，肝阳潜伏；右关鼓指，胃气渐振；右寸软弱、左尺虚细、右尺微小，示肺肾不足。六脉虽未调和，然无病脉之象，故曰“未见病脉，即平脉也”，主脏阴渐复、肝阳宁静之机。", ["弦", "虚", "细", "小"]], "2098": ["病机", "原文未载脉象，以“填纳下焦”后肝肾肺胃络脉渐宁、痰咯未净而脏阴离络之瘀已尽为据，说明下焦得填、络脉完固，病机由瘀阻络伤转为虚损渐复，故仍拟肝肾定例少佐清化。", []], "2099": ["平脉", "右寸软、尺小弱，余部中和，为肺气不足、肾气偏弱之象；然瘀尽络固、痰少神安，值少阴用事之时，脉虽偏弱而无病脉，属平脉范畴，只宜静养待一阳来复，益气佐之。", ["软", "小", "弱"]], "2100": ["病机", "原文未出具体脉名，仅言“左脉已静，右脉未和”。左静知肝血渐宁，右未和示肺胃络虚留滞，呛逆凝瘀。病机为络虚不固、瘀滞未净，故议益阴和阳佐宣络。", []], "2101": ["病机", "左脉虚数，虚为阴血不足，数为有热。面色痿黄、无梦遗泄，乃湿热下注扰动精室，非虚滑不固之证，故脉虚数而非细弱，治当清利湿热，与固涩异政。", ["虚", "数"]], "2102": ["病机", "脉细面白，小溲不通，细为气血不足，面白为阳气不充。此非实邪闭肺，乃中气不足、膀胱气化无力所致，故投泄肺展气化决不效验，当补中益气以助气化。", ["细"]], "2103": ["病机", "脉细形寒自汗，细为阳气衰微、卫外不固，形寒自汗为卫阳式微、腠理不密之征。此属阳虚不能温分肉、充皮肤，故脉细而症见寒汗，治当温卫固表。", ["细"]], "2104": ["病机", "汗泄而见脉大，大脉主邪盛或正虚。此案汗出过多，营卫耗伤，气不内守，故脉体宽大而无力，属劳伤营卫、气浮于外之象。汗泄伤阴耗气，脉大为劳，正合虚劳脉法，主营卫两伤、气不敛固之病机。", ["大"]], "2105": ["预后", "三岁小儿喘急而脉细，细为气血衰少、阳气不振。喘急本属气逆，脉当浮滑有力，今反细弱，是正气已衰、不能胜邪。更见戴眼，乃阳气上脱、目系失养之脱象，故原文断为「已现脱象」，属危候，预后不良。", ["细"]], "2106": ["病机", "阴寒内盛，格阳于外，故脉独疾而散。疾为阳浮躁动，散为阳气涣散不收，非实热之数。心胸热炽、面赤尤甚于两颧、烦渴干呕，皆虚阳上越之假热。脉疾散而症见热象，正是阴盛格阳、导火归原之危候，故云危期至速。", ["疾", "散"]], "2107": ["预后", "雀啄脉来三五不调、止而复作，为脾气已绝、真元将败之死脉。患者先有癃闭，前阴利水属厥阴，二便属少阴，今脉如雀啄，是肝肾气逆、阴精欲脱。原文断「已萌阴脱之象」，三日内恐见手足厥阴、目盲等症，属不治之候。", ["雀啄"]], "2108": ["病机", "脉按之细而兼沉，细为阴血不足，沉为邪陷于里。邪陷日久，脘痹不纳谷、心胸热炽、两眼怕亮喜暗，皆邪锢蔽日深、清疏无效之象。脉细沉说明正气内馁、邪伏深沉，故勉拟热因热用、补里托邪，导火归原。", ["细", "沉"]], "2109": ["病机", "新产十朝，右尺不起，脉形独疾而散而非数。疾散乃阴血骤亏、阳气浮越不收，如灯火焚膏殆尽。两颧赤甚、干呕不除、竟夜少寐，皆虚阳上扰之征。原文以灯火将灭为喻，明此非实热之数，乃阴竭阳浮、导火归原之危候。", ["疾", "散"]], "2110": ["病机", "身无寒热而脉缓，缓为胃气渐和之象，非病脉。便溏、纳谷而少，是脾弱不司运化，胃气方苏而脾运未复。病后见此脉症，属脾胃虚弱、运化无力之病机，与寒热无关，故原文谓「病后颇有是症」。", ["缓"]], "2111": ["治法", "右寸脉数已退，是肺中余热渐清之征；大便已解，腑气亦通。然气分尚怯，说明邪退而正气未复。原文拟养肺胃、以理余邪，属病后调治之法。脉数退而气怯，主肺胃气阴不足、余邪未尽之病机，故以养为正治。", []], "2112": ["病机", "脉弦为肝木偏旺之象，本案阳明胃衰而见呕逆吞酸、少寐，是木邪乘土、肝气犯胃。弦脉主痛主肝，胃土本虚则肝木易侮，故以制肝木、勿犯胃土为治，脉弦在此标示肝强胃弱之病机。", ["弦"]], "2113": ["病机", "左脉涩弱示肝肾精血不足，脉动为冲脉失摄、气逆上冲之征。原文言冲脉隶于肝肾，肝肾衰则冲脉动，心下漾漾、涎沫上溢，皆肾气少纳、中无砥柱所致。涩弱非实邪，故与肝胃症似是而非，主下焦虚损、冲气上逆。", ["涩", "弱", "动"]], "2114": ["病机", "脉象弦数为肝木化火、乘犯阳明之象。弦主肝旺，数主热，肝火犯胃则呕酸食少；经分不至亦因肝木乘土、气血生化受阻。此脉说明木邪侮土而兼内热，故拟制肝和胃，弦数正是肝胃同病之凭。", ["弦", "数"]], "2115": ["病机", "脉象沉伏为邪郁深闭、气血不能外达之征。跗肿腹满、噫嗳胀势不消、二便皆秘，是血分聚水、厥阴气结而阳明不通。沉伏非虚，乃实邪内闭，故前用苦辛宣腑、酸涩泄肝而病未减，此脉示血分水聚、气机壅塞之病机。", ["沉", "伏"]], "2116": ["病机", "原文仅言脉象稍清，未识具体脉名，故脉象要素从缺。呕逆已止而脉稍清，说明苦辛开痞后邪势略退；但胸次按之而痛，是热邪阻遏中焦、无形清气壅滞，与食滞有形之痛不同。此段重在辨热邪阻遏中焦之病机，非以脉定病。", []], "2117": ["病机", "脉象短数，短主气机不畅，数主热。脘闷、舌白黏腻、得大便胸次稍舒，是热结在上、上焦不行而下脘不通。肺与大肠相表里，热邪陈腐郁于上焦，故脉短数。此脉示热结气壅之病机，拟栀豉汤解陈腐之邪。", ["短", "数"]], "2118": ["病机", "脉缓而便溏，缓为胃气不足、阳虚失运之象，非平和之缓。嗳气不舒是浊阴上干，便溏是胃阳不能腐熟运化。此脉说明胃阳虚衰、浊阴上逆之病机，故以温阳降浊为治，缓脉在此主虚主湿。", ["缓"]], "2119": ["病机", "脉涩主血少气滞、运行不畅。原文言下焦气钝血燥、便难，正与涩脉相应：血燥则肠道失润，气钝则传导无力。进通幽方以润燥通便，涩脉在此标示下焦阴血亏虚、气机不利之病机，非外邪实滞。", ["涩"]], "2120": ["病机", "年高脉伏，非阳虚即邪闭。原文点明“瘀热在营，血燥便难”，伏脉主邪郁深沉、气血壅滞不通，瘀热内结营分，血燥津亏则便难，脉气不得外达故伏。此非虚寒之伏，乃实邪内闭之象，故进通幽法以通下瘀热。", ["伏"]], "2121": ["病机", "温邪内郁，舌白脘闷、频渴，脉大。大脉主邪盛气分，温邪郁于肺卫，手太阴气化失宰，故脘闷不饥、二便不利。脉大示邪势方张而未入营，宜苦辛泄降以开肺痹，使气化得行。", ["大"]], "2122": ["病机", "身热脘闷、不饥不食、不大便而脉数，数主热盛。原文断为“气分窒塞”，热郁气分，腑气不通，故脉数而症见痞满便秘。苦辛泄降正合气分郁热之治，非虚数之候。", ["数"]], "2123": ["病机", "胸脘阻蔽，脉微而痛，肢厥得嗳稍舒。微脉主阳气衰微，胸阳失其旷达，阴寒阻蔽胸脘，阳气不布故肢厥，嗳气得通则稍舒。此胸阳不振、阴浊上干之机，脉微正是阳微之征。", ["微"]], "2124": ["病机", "右寸滑软、左脉细涩，右寸候肺，滑软为痰气壅实；左脉候肾，细涩为肾虚少液。原文谓“喘症在肺为实，在肾为虚”，肺肾并衰、出纳无权，痰色瘀紫亦气馁少液之征，脉象正合虚实夹杂之机。", ["滑", "软", "细", "涩"]], "2125": ["病机", "脉小舌白、两脉微涩，呃逆气冲、大便滑溏。小涩主阳气不足、血少气滞，胃阳虚则浊阴上干，呃逆气冲；阳虚不摄则便溏。原文断为“胃阳虚，浊阴上干”，脉小涩正是阳衰阴浊内阻之应。", ["小", "涩"]], "2126": ["病机", "服凉解后身热止、渴减，邪解之象，然脉微汗泄、呃逆便溏，是胃阳衰惫。微脉主阳气虚衰，阳虚不能固表则汗泄，胃阳败则呃逆便溏。原文称“火为重候”，脉微正示阳衰欲脱之危，故勉拟理中温阳。", ["微"]], "2127": ["病机", "脉伏口噤、神昏鼾睡，原文断为“寒热直中阴经，阳气逆乱”。伏脉主邪闭阳气、脉道不通，寒邪直中阴经，阳气不能外达故脉伏，神昏口噤乃邪闭清窍。症属棘手，勉拟辛温达邪以通阳开闭。", ["伏"]], "2128": ["病机", "风温外袭肺卫，寸口脉大，为邪在表、正气抗邪之象。身热恶寒、头晕且痛，皆风温上扰清窍、肺卫失宣所致。脉大而不数，说明邪未深入，故拟轻剂宣通，从表解之。", ["大"]], "2129": ["病机", "头旋脉大，身热恶寒，风温外袭肺卫。脉大主邪气盛于表，肺卫受邪，清阳不升则头旋。治拟轻扬上焦，使邪从表解，方中牛蒡、连翘、桑叶等皆轻清宣透之品。", ["大"]], "2130": ["病机", "温邪自里而出，两脉洪大，为里热炽盛、正气抗邪之象。烦渴、便溏、脘闷食少、舌苔中绛边白，示肺大肠表里同病，热邪有外达之势。洪大脉主热盛，故拟清里少佐泄邪。", ["洪", "大"]], "2131": ["病机", "温邪逆传膻中，心阳受蒙不宣，呕逆、神昏、烦渴，脉数舌绛，为热入营分、内陷心包之征。高年五液皆涸，脉数示热盛阴伤，最防窍闭厥脱，故拟清营络热邪。", ["数"]], "2132": ["病机", "寒热交作、头痛口渴、腹痛膝痛，脉浮自汗，为冬令感冒时邪，伏邪内动。浮脉主表，自汗示卫表不固，邪踞表里之间。寒伤营、风伤卫，治与疟病两岐，当从伏邪透解。", ["浮"]], "2133": ["病机", "暑湿未清，舌白脘闷，脉象濡弱，口渴便溏。濡弱主湿邪困阻、气机郁滞，非虚象。始由奔走气乱，肺气膹郁，继则漫布三焦，身热不为汗衰。苦寒辛寒无益，当展清阳、化湿邪。", ["濡", "弱"]], "2134": ["病机", "壮热微寒，舌绛渴饮，脉右寸关空大、左细小。空大示气分热盛而津伤，细小为阴血不足。右寸关主肺胃，热炽于上；左细小示肝肾阴亏。议玉女煎加减，清胃热、滋肾阴。", ["空", "大", "细", "小"]], "2135": ["病机", "右脉短数、左脉细数，寤而少寐，身凉而有寒热，时作气喘，脘闷舌白。短数主热邪内陷、气机不畅；细数示阴分受伤。热陷少阴、少阳，故拟清泄少阴之里、解少阳之表。", ["短", "数", "细", "数"]], "2136": ["预后", "原文“脉数已缓”指数脉已趋缓和，反映邪热渐退；“气急已退，得汗安寐”为邪解之象。脉数转缓说明表里气机渐和，内陷之势已无，故预后可渐愈。", ["数", "缓"]], "2137": ["病机", "脉小主正气不足，湿邪内阻。原文“头重若裹，胸闷不食，并不渴饮，便溏”为湿邪阻蔽气分之征。湿性重浊黏滞，困遏清阳则头重，阻滞气机则胸闷不食，脉小正合湿阻气分、正气受困之机。", ["小"]], "2138": ["病机", "右寸候肺，脉偏大于右寸，主肺胃燥热。原文“咽干唇裂，上腭干痛，频渴不多饮”为秋燥伤津之象。燥邪犯肺胃，津液受损，气分有热，故右寸脉大，治以甘寒生津。", ["大"]], "2139": ["病机", "右脉数搏，数主热，搏为有力，示肺胃热盛。原文“鼻头胀，咽干，咯血，频渴不多饮”为温邪化燥、阴分不足之征。热灼肺胃，迫血妄行则咯血，阴伤津亏则渴不多饮，脉数搏正合温燥化热之机。", ["数", "搏"]], "2140": ["病机", "左关弦大主肝郁化火，右寸搏大主肺热。原文“唇裂频呕，口干头痛，不寐足冷，左胁瘕聚，便秘，胸腹热炽”为温燥内郁、肝火上炎之象。弦大搏指示燥热内郁，肝肺同病，故议清燥救肺汤合肺肝之治。", ["弦", "大", "搏"]], "2141": ["病机", "肝脉仍弦，示肝郁未解。原文“呕减，潮热，咳乃胀痛，大便秘，肺胃衰，肝阴亏，肝火上越”为肝阴亏虚、肝火上炎之候。弦脉主肝病，阴亏火旺则脉弦不减，呕虽减而潮热咳痛仍在，病机未变。", ["弦"]], "2142": ["病机", "左脉洪大主热盛于里。原文“温疫自口鼻吸入，神识不清，烦渴，鼾声，胸背赤疹隐约”为温邪郁遏、化火化燥之象。洪大示热邪炽盛，三焦交炽，势防内陷，故拟滋清营分兼佐泄邪。", ["洪", "大"]], "2143": ["病机", "两脉洪数，洪主热盛，数主热急。原文“夜躁不寐，热盛烦渴，癍疹未透”为胃腑热邪炽盛、癍疹欲透未透之征。洪数脉示热邪内盛，气分热炽，故拟清胃腑热邪兼以疏癍。", ["洪", "数"]], "2144": ["主病", "脉数主热，身热脉数，为外感时邪化热之象。已见癍，说明热邪深入营血，外发肌表。数脉与身热、见癍相应，提示邪热炽盛，病势进展。", ["数"]], "2145": ["病机", "两脉洪数，洪为阳明热盛，数为邪热亢盛。时疫未经宣透，邪已蕴结阳明，见烦渴、昏谵不寐，脉洪数正是阳明热盛、邪欲外发发癍之征。发散伤阳、苦寒损胃，故拟凉膈疏癍。", ["洪", "数"]], "2146": ["病机", "两脉独大，大脉主邪热亢盛。温邪发疹，烦渴少寐，脉大提示热邪内盛，正气抗邪有力，邪热有外透之势。脉症合参，为温邪在气分，热势鸱张。", ["大"]], "2147": ["兼症", "脉右软短，软为气虚，短主气郁。疹邪已透胸背，而右脉软短，提示气机不畅，营络郁滞。烦渴热频、少寐、舌白、蛔厥、大便不解，皆因气郁营热，故仍议清疏营络透疹。", ["软", "短"]], "2148": ["预后", "身热脉大，大脉主邪热炽盛。惊邪内炽，痰壅神昏，两眼蒙闭，寤不转侧，症属棘手。所喜舌苔津液未涸，脉大而津未竭，尚有一线生机，预后虽险犹可挽回。", ["大"]], "2149": ["病机", "脉象沉弦，沉主里主水，弦主饮主痛。背寒肢冷、咳嗽暮剧、并不饮渴，此饮邪内伏，阳气不布，故脉沉弦。议温药和之，以温阳化饮。", ["沉", "弦"]], "2150": ["病机", "脉象沉弦，沉为在里，弦为肝郁。潮热腹痛、经事愆期、气冲欲呕，此肝郁木不条达，气机郁滞。宜泄少阳、补太阴，进逍遥方以疏肝解郁。", ["沉", "弦"]], "2151": ["病机", "脉数脘痹，数主热，脘痹为气机不畅。中怀郁勃，气不展舒，郁而化火，故脉数；头目如蒙、胸胁隐痛、寤而少寐，皆郁火扰神之象。此属郁火，宜当清散。", ["数"]], "2152": ["病机", "脉弦为肝阳亢盛之象，肝阳犯胃，胃气上逆则呕吐妨食；厥心痛由肝阳上逆、气血不通所致；肢冷为阳气不达四末。弦脉主痛、主肝病，此处脉弦与呕吐、肢冷并见，说明肝阳犯胃、胃失和降，阳郁不达。", ["弦"]], "2153": ["主病", "脉细面白，为气血两虚之征。心脾两虚，血不养心，则寤不成寐；面白为血虚不荣。归脾汤主之，健脾养心、益气补血。脉细主虚，与面白、失眠相应，说明心脾两虚、气血不足。", ["细"]], "2154": ["预后", "痢久伤阴，痢止泻减而脉象右微，右脉候脾肺，微为阳气衰微。泻血多、汗泄不寐，心脾肝肾皆亏，阳气不肯下交于阴，脏病散漫，故难奏效，深虑反复。脉微主阳气虚衰，与泻血、汗泄、不寐并见，说明阴阳两伤、脏气耗散，预后不良。", ["微"]], "2155": ["病机", "脉右微已振，左脉稍濡，微为阳虚，濡为阴血不足。两颧赤、口干汗泄、少寐为阴火上升；下纯血止，经阻三月，三阴大亏，瘀阻内结。腹痛冷热、酸水涌溢为木邪犯胃。脉微濡与气血交亏相应，说明阴阳两虚、木邪内扰，当导火归原。", ["微", "濡"]], "2156": ["病机", "右脉数搏，右候肺胃，数为热盛，搏为邪气搏结。肺胃交炽，热灼津液，故消渴善饥，属中上消症。脉数与消渴善饥并见，说明肺胃热盛、津液耗伤，拟甘寒方清热生津。", ["数"]], "2157": ["误治", "暑湿内郁成疟，前投凉解牙宣血溢已止，脉象稍平，寒减热未退，脘闷舌白痰多溲赤。医者误用升、柴、苏、菖过于升泄，复缪于鹿角霜温理奇阳，致血溢之恙。脉稍平而里湿未尽，说明误治后邪未透解，当以栀豉汤引邪出表。", []], "2158": ["病机", "脉弦滑，弦主少阳，滑主痰湿。寒热头痛为少阳枢机不利；脘闷频渴为痰湿中阻、津不上承。脉弦滑与寒热、脘闷并见，说明少阳痰湿内郁，枢机不和，故从少阳开泄，和解枢机、化痰湿。", ["弦", "滑"]], "2159": ["病机", "脉数，数为热盛。疟邪未止，寒少热多，渴饮无度，呕吐神烦汗泄面赤，大便四日未解，为阳明热盛、津伤气逆。深秋燥邪，辛寒佐甘缓，符仲景阴气先伤、阳气独发之旨。脉数与热多烦渴相应，说明燥热内盛、阳气独发。", ["数"]], "2160": ["病机", "脉大而并不渴饮，说明热不在气分津伤，而是心经热疟，热邪迫于肺胃。面赤、恶心呕吐、神烦汗泄、衄血皆热邪上扰、迫血妄行之象；脉大为热盛鼓动血脉，然不渴饮则热未伤津，故主清心热、凉肺胃，使热退而脉自平。", ["大"]], "2161": ["病机", "原文未直接言脉，以“络脉空隙”言病机。妊去液伤，产后恶露已净而液亏，络脉空虚失养，故少腹微痛、腰酸、寤而少寐、督虚背寒；瘕泻大减示瘀滞渐去。治当温而不燥、润而不清，以入至阴之地，补络脉之空隙，非温下所能尽。", []], "2162": ["病机", "脉濡弱为脾胃气馁、气血不足之征。肠风便血、腹痛，乃风邪入肠、血络受伤，然脉不弦数而濡弱，说明中气已虚，不能统血摄血。故治法疏风凉血之外，须和阴扶脾，使脾胃气复则血有所统，濡弱之脉可渐充。", ["濡", "弱"]], "2163": ["病机", "两脉涩弱，涩主血少滞涩，弱主气虚，合之见肾虚失于收纳、藏聚少司。痿躄、左足偏枯、步履皆废，为下元虚衰、精血不能充养筋骨；背脊喜捶，亦肾督空虚之象。病根在下，故用虎潜意补肾填精、强健筋骨。", ["涩", "弱"]], "2164": ["病机", "鼻衄已止而面白无神、脉细音嘶，细脉主阴血亏少，音嘶为气阴不能上承。血脱之后，气无所归，阳气亦随之耗散，故面白无神。此血脱气弱之候，治当以阳气为首务，益气摄血、引气归元，使气有所归则脉渐起。", ["细"]], "2165": ["病机", "右寸关搏而疾大，右寸关属肺胃，搏疾大为阳明燥热鼓舞之征。瘀咯初净而肺胃阴液未充，值天时燥气加临，阳易旋动，清窍失肃，故衄血复发。脉之搏疾大正是燥热内迫、阳动不潜之象，治以滋清益阴肃上，使燥热平而血止。", ["搏", "疾", "大"]], "2166": ["病机", "左脉和静而右动搏已减，说明前之阳明燥热渐平。右脉动搏为火象，凡动皆火，易就燥；今搏减、衄血渐止、紫滞退，是阴渐复而阳渐潜。口干乃余热未清、阴液未充，故议益阴潜阳，佐清阳明燥热，使动搏尽平。", ["动", "搏"]], "2167": ["病机", "脉右搏大今现于左部，右属肺脾，左属肝肾，搏大之脉由右移左，说明痰积下坠、浮火已熄，病位渐深。拘束减、夜寤稍寐、跗肿消，皆痰气下降之征；肚坠便积为湿郁蕴痰酿积。脉搏大示痰积内阻，故治以通积消瘀痰、扶脾佐之。", ["搏", "大"]], "2168": ["病机", "脉小为内伤虚损之象，非外感清散可治。原文言'谋虑伤肝，肝阳挟内风上冒'，阳浮头痛、暮热早凉、面赤肉𥆧皆肝阳上冒、阴血不足之候。脉小示正气已弱、阴不制阳，故属内伤巅顶之疾，治以复脉去参姜桂加鸡子黄、白芍，育阴潜阳。", ["小"]], "2169": ["病机", "脉沉微为阳气不振、木不条达之象。原文言'嗔怒动肝木，犯胃'，致痛、呕、消渴、肢冷。沉主里，微主阳虚，肝木横逆犯胃则胃气不和而呕痛；阳气不达四末故肢冷。脉沉微正合'木不条达'、制肝木理能取胜之旨。", ["沉", "微"]], "2170": ["主病", "脉弦为肝病主脉，弦主气机郁滞、水湿不化。原文'肝水肆横，腹痛脉弦'，六岁小儿肝常有余，水气横逆犯脾，气机壅滞则腹痛。脉弦紧扣肝水肆横之病机，故宜当疏泄，以疏肝行水、条达气机为治。", ["弦"]], "2171": ["病机", "关脉迟缓主脾胃虚寒、中阳不振。原文言跌仆惊恐致气乱气下，又误投下蛔、五味扰动厥阴肝络，胃伤废食。关候脾胃，迟缓为戊土残惫、运化无力之象；按之痛止、抚摩稍适亦虚痛之征。色现黑滞、饮食不思皆胃气衰败之候。", ["缓", "迟"]], "2172": ["主病", "脉弦主痛、主气滞。原文'寒客于胃，腑阳不宣，腹痛脉弦，少食'，寒邪客胃则腑阳不宣、气机不通，不通则痛，故脉见弦。弦为寒凝气滞、胃阳受困之应，治当通阳散寒，合'六腑以通为用'、痛则不通之旨。", ["弦"]], "2173": ["病机", "本段未识别出脉名，仅言'阳明脉衰，肩胛痛'。阳明经气衰少，气血不能充养肩胛经络，故肩胛作痛。此属经络失养、气血不足之病机，非外邪实痛，与脉象无直接对应，故脉象要素从缺，主旨归于病机。", []], "2174": ["病机", "脉虚为气血不足、督脉空虚之象。原文'背痛脊痛，此属督脉虚'，督脉行于脊背，总督一身之阳，督脉虚则脊背失养而痛。脉虚正应督脉空虚、阳气不充之病机，故属虚证背脊痛，治宜温养补虚。", ["虚"]], "2175": ["病机", "两尺脉独小，尺候肾与命门，独小为少阴久虚之象。原文'腰溶溶而痛，形寒，面乏华泽'，腰为肾之府，肾虚则腰失所养而痛；阳虚不能温煦故形寒，精血不足故面乏华泽。脉小紧扣少阴久虚，理宜温养。", ["小"]], "2176": ["主病", "脉微弱为气血不足之象，足跗软乃下焦虚弱、筋骨失养所致。微弱脉主虚证，说明正气亏虚，不能充养肢体，故见足跗软弱无力。此段以脉微弱点明病机属虚，与足跗软症候相应。", ["微", "弱"]], "2177": ["病机", "原文未载脉象，仅述风温上受、耳聤胀痛，胆脉络于耳，议清少阳气分之热。此段主旨为病机分析，风温之邪侵袭少阳，胆经郁热上扰耳窍，故耳胀痛。脉象缺失，从症测机，属少阳风热为患。", []], "2178": ["病机", "原文未述脉象，言暑风袭于少阳，胆脉络于耳，木火上炎，清窍失聪。此段阐明暑风外袭少阳，引动胆木之火上炎，蒙蔽清窍，故耳失聪。病机为少阳风火，与耳聋症候相应。", []], "2179": ["预后", "两尺脉独大，尺候少阴，疟邪陷入少阴，热逼血升，气散血随散，有骤脱之虞。脉独大示邪热亢盛于阴分，迫血妄行，故当血上溢。此脉主热盛动血，预后险恶，须防气随血脱。", ["大"]], "2180": ["主病", "左关脉洪大，左关候肝胆，洪大为阳热亢盛之象。齿痛连太阳，乃肝胆之火上炎，循经上扰所致。脉洪大主实热，与齿痛连及太阳症候相应，故议景岳方法清泄肝火。", ["洪", "大"]], "2181": ["病机", "原文未载脉象，述怀妊五六月，病上牙齿痛偏右，属肝阴不足，肝风内动，虚乘袭入阳明脉络。此段论病机，肝阴亏虚则风动，风邪乘虚入阳明经，故齿痛。治宜熄风，与妊妇阴血养胎相关。", []], "2182": ["病机", "原文未述脉象，言咳嗽腰痛、咽喉如梗，引少阴之脉循咽、厥阴之脉循喉咙，断为肝肾内衰之征。此段以经络循行阐明病机，肝肾阴精亏衰，虚火上逆，故见咽梗咳嗽腰痛，治当酸咸入阴。", []], "2183": ["病机", "脉微涩为气血涩滞，两寸脉独大示上焦热盛。经闭数月，胸满腹胀，寒热消渴，便结，乃胃大肠腑热渐侵心脾，即“二阳之病发心脾”。脉微涩与独大并见，反映本虚标实、热郁血涩之病机。", ["微", "涩", "大"]], "2184": ["病机", "原文谓淋带起于产后，腰腹绞痛，归咎冲任交伤而带脉空隙。产后气血骤虚，带脉失约，故见淋带不止；腰腹绞痛乃冲任受损、气血不畅之征。脉空隙正示带脉约束无力、下元不固，故治法宜固其下，以固摄冲任带脉为要。", ["空"]], "2185": ["病机", "崩漏暴下不止而脉动，动脉主阴阳相搏、气血失守。冲任交损，血去过多，阴不潜阳，阳气浮越而动，故脉见动摇不宁。方议潜阳，正是针对阴亏阳浮、冲任不固之机，以潜镇浮阳、固摄冲任为治。", ["动"]], "2186": ["病机", "脉左迟右濡，左迟示肝阴久亏、阳气不振，右濡主气虚湿滞。寒热腰痛、脊酸楚、足缓腹痛、漏淋不止，皆肝肾内衰、八脉无气之象。疏泄逐瘀不可进，故取血脱益气、阳生阴长之法，拟乌贼丸固摄奇经。", ["迟", "濡"]], "2187": ["病机", "经漏半月一至、大便两日始通，属肝肾内衰、八脉无气拥护。原文引胞络移热于膀胱之论，说明下焦虚而热移，冲任失摄则经漏，肠腑失润则便难。议三才汤参入益肝阴、养心液，从滋养肝肾、濡润奇经立法。", []], "2188": ["妇人", "寸脉搏指，为妊娠脉象之特征。经水三月未来，寒热头痛、渴饮不化、胸闷呕恶，皆孕早期冲气上逆、胃失和降之候。寸脉搏指乃血聚养胎、脉道充盈所致，故断为妊象，非病脉也。", ["浮"]], "2189": ["病机", "新产四朝，腹痛背痛、腰溶溶而痛、恶露淋漓，属督带交伤。产后瘀血未净，奇经受损，督脉失养则背腰疼痛，带脉不约则恶露淋漓。治宜理奇脉以逐瘀佐之，但不可骤用温补，恐留瘀为患。", []], "2190": ["病机", "产后下虚，冲任脉震而动，动脉主虚阳浮动、气血失守。心痛形寒，乃下元虚寒、阳失温煦之征。最怕淹缠蓐损，示产后虚损难复。宜议温养，以温补下元、固摄冲任，使震动脉象得安。", ["动"]], "2191": ["病机", "脉象左部细涩，细主液亏，涩主血少不畅。阴气下泄、阳从上冒，头痛巅顶尤甚，恶露已净而脉细涩，明是液亏不司留恋其阳，成上实下虚之症。左部候肝，肝阴不足则阳无所附而上冒，故见巅顶头痛。", ["细", "涩"]], "2192": ["病机", "左脉数主热，右脉大主热盛，合咽痛、舌灰、便闭、头痛脘闷欲呕口干鼻干少寐，显系热邪炽盛，已由少阳内陷血室。数大之脉与热邪内陷相应，故议玉女煎加竹叶清泄阴分血室之热。", ["数", "大"]], "2193": ["病机", "风温袭肺卫，身热发痧、痰咳气喘、烦躁频渴，脉大乃热邪亢盛、肺卫气分热炽之象。脉大与频渴烦躁相合，说明热势鸱张，故议清泄肺卫。", ["大"]], "2194": ["预后", "惊热内闭，躁烦不食，两脉洪大，为热邪炽盛、内扰心神之征。洪大之脉示邪热方张，故原文虑其邪陷心包，痉厥将至，属防变之预后判断。", ["洪", "大"]], "2195": ["病机", "风温内郁，身热咳嗽，脉大主热盛于气分。脉大与身热咳嗽相应，说明风温热邪郁于肺卫，正气抗邪有力，故以脉大辨其热郁之机。", ["大"]], "2196": ["病机", "两关脉数，关候脾胃，数主热。吐乳洞泄、烦躁、睡喜覆卧、腹痛按之痛止，述跌仆后泻呕格拒，惊则气乱，故断为蛔厥，脾胃气馁、四肢厥冷。数脉与吐泻烦躁相参，示惊气乱而蛔动之机。", ["数"]], "2197": ["病机", "痫厥来速，醒后两脉皆洪，四肢搐搦身热，洪脉主阳气拂逆、热盛于内。脉洪与搐搦身热相应，说明阳气拂逆、热扰络脉，故防络闭，属病机与防变之论。", ["洪"]], "2198": ["病机", "头晕体丰，心悸脉动。动脉主惊主痛，亦主阴阳相搏、气血失和。体丰多痰，痰扰心神则悸，阳扰于上则晕，脉动正示阴阳不交、痰火内动，故为类中之渐，须安养调治。", ["动"]], "2199": ["病机", "少寐头晕，阳不交阴；六脉紧数，紧主痰结、数主火盛，合之显系肝火挟痰为患。脉紧数与头晕少寐相参，说明火痰上扰、阴阳失交，故防其类中。", ["紧", "数"]], "2200": ["病机", "六脉弦数为肝火亢盛、木火刑金之象。弦主肝郁气逆，数主火热内炽，火热挟痰上冲，故卒然厥晕；肝气横逆犯胃，膈次胀楚。佐金法即清金制木，使肺金肃降以平肝火，正合弦数之脉所主肝火犯肺、气逆痰升之病机。", ["弦", "数"]], "2201": ["病机", "脉来弦滑，弦为厥阴气郁、肝阳不潜，滑为痰湿内蕴。阳本亏而厥阴气郁，劳动则阳气升动，痰随气逆，故头晕肢麻。弦滑并见，示肝风挟痰、类中欲动之机，原文明言「类中之机，预为调治」，故当早图，勿待风痰骤升。", ["弦", "滑"]], "2202": ["病机", "脉软为营阴内伤、气血不足之征。血不养肝，肝失柔养则膈胀作痛；营阴亏虚，卫外不固故恶寒；舌本不利、语言不清，乃阴血不能上荣舌本。脉软无力正合虚象，原文谓「须宽心安养」，示此属内伤虚损，非实邪为患。", ["软"]], "2203": ["病机", "原文未出脉名，纯以症候立论。上手足肿痛不仁，为风邪入络、气血痹阻；艰于言语，乃痰浊蒙蔽清窍。风与痰合，络脉不通、清窍失灵，故原文断为「风入络脉，痰蒙清窍」，治宜祛风豁痰，脉象虽缺而病机自明。", []], "2204": ["预后", "六脉沉弱少力，沉主里、弱主虚，为积劳内亏、气血津液俱竭之象。腰为肾府，腰痛肢痿示肾精亏耗；津液内竭则脉道不充。原文谓「必须温补，否则防类中」，以沉弱之脉见虚损根基，正虚则风痰易动，故列预后警戒。", ["沉", "弱"]], "2205": ["病机", "六脉弦滑不柔，弦为肝火亢逆，滑为痰浊内盛，不柔示肝失柔和之性。肝火挟痰上扰清空，故耳鸣头晕。原文直断「肝火挟痰为患」，弦滑不柔正是火痰交炽之脉征，治先清后补，清其火痰、补其本虚。", ["弦", "滑"]], "2206": ["治法", "六脉弦数，弦主肝郁、数主火盛，肝火挟痰上逆，故卒然厥晕；肝气犯胃，膈次胀楚。原文出「当用左金法」，左金丸辛开苦降，清肝泻火、降逆和胃，正对弦数之脉所主肝火犯胃、气逆痰升之证，属因脉立法之例。", ["弦", "数"]], "2207": ["预后", "六脉弦数，为肝风内动、痰火交炽之象。四肢麻时昏沉，乃风痰欲作痫厥之先兆。原文谓「防其痫厥」，以弦数之脉示肝风痰火鸱张，暂用疏肝涤饮以折其势，脉数不退则风痰愈炽，故列预后警戒。", ["弦", "数"]], "2208": ["兼症", "右脉滑大，滑主痰湿内蕴，大主邪气有余。时疾后惊恐伤肝，肝风上冲则呕恶膈胀，下迫则精滑，风痰湿邪壅盛，故右脉滑大。此脉象提示肝胃不和、痰湿内阻，与膈胀浮肿、呕恶相应，故先理胃疏肝。", ["滑", "大"]], "2209": ["病机", "原文述脉象并不细软，细软为虚象，今不细软且脾胃无咎，说明阳未本亏。肝失所养，内风煽烁，痰壅气逆而喘，血少肝亢。脉不细软反映邪实为主，非纯虚之候，故以甘露饮加减清肝化痰。", []], "2210": ["病机", "脉数无力，数主热，无力为虚，乃营液交虚、心阳飞越之象。阴不敛阳，虚热上扰，故易饥胆怯、神思倦怠。上实下虚，火动于上而根虚于下，脉数无力正合此病机，拟甘温潜纳以引火归元。", ["数", "无", "力"]], "2211": ["病机", "左脉紧大，紧主风邪劲急，大主邪盛。肝胆热郁生风，风邪窜扰则统体作痛；阳明湿邪下注，湿浊不化则口渴不清。紧大之脉反映风热湿邪交争，肝胆郁热化风，故先用疏风分理以祛邪。", ["紧", "大"]], "2212": ["病机", "右脉滑数，滑主痰，数主热。厥阴化风，痰气壅于上焦，风痰热邪搏结，故脉见滑数。痰热壅阻，营卫不和，则瘭疖不消。此脉象提示肝风痰热为患，治以和肝化痰，使痰热清而风自息。", ["滑", "数"]], "2213": ["病机", "右脉弦数，弦主肝风，数主内热。久患休息及咳血虽愈，而内风扇动，耗伤营阴，虚热上扰，故心悸头晕。弦数之脉反映肝风内动、营阴不足，治宜黑归脾通补，养营熄风以安痊。", ["弦", "数"]], "2214": ["病机", "原文未识脉名，然述厥阴气郁久而化风，营阴暗耗，不寐，火动及上焦，脉络痿痛。此乃气郁化风、营阴亏耗、虚火上炎之病机，虽无脉象可凭，症候已明，故宜疏风静养，以缓肝急、滋营阴。", []], "2215": ["病机", "脉数肢痿，数主热，肢痿为精血不足。阳明有余则热盛，少阴不足则水亏，水不涵木，肝火内动，故脉数而肢痿。此脉象反映阴虚火旺、肝风内动，治宜祛风培水，滋水涵木以调治。", ["数"]], "2216": ["病机", "六脉滑大不柔，滑主痰湿，大主邪盛，不柔示肝风内动。原文谓“脾虚挟湿，血少肝风”，脾虚运化失职则湿聚为痰，血少肝失濡养则风动，痰湿上扰则头晕，风痰阻络则四肢麻木。脉象滑大不柔正是痰湿挟风之征，故以平肝燥土调治。", ["滑", "大"]], "2217": ["病机", "脉不柔软，即脉弦劲失和。原文谓“厥阴气郁，络伤经败，肝失所养，木风愈甚”，肝郁日久则络脉损伤，肝血不足则木风愈甚，脉失柔润而现弦劲。此脉主肝郁风动、络伤经败之病机，故以通为补，用黑逍遥佐苦泄法。", ["弦"]], "2218": ["病机", "脉动为心悸之征，动脉主惊主痛，亦主气血失和。原文谓“头晕体丰，心悸脉动，类中之渐”，体丰多痰湿，痰湿上扰则头晕，痰扰心神则心悸，脉动反映气血逆乱、阴阳失和，为类中风之渐，故须安养调治。", ["动"]], "2219": ["病机", "六脉弦滑不柔，弦主肝郁，滑主痰湿，不柔示肝火亢盛。原文谓“肝火挟痰为患”，肝火偏亢则脉弦，痰湿内蕴则脉滑，火痰交阻，上扰清窍则耳鸣头晕。脉象弦滑不柔正是肝火挟痰之征，故先清后补。", ["弦", "滑"]], "2220": ["病机", "六脉软弱少力，软主虚，弱主气血不足。原文谓“咳呛脾泄，饮食日减，六脉软弱少力，土不生金之验”，脾土虚弱则运化失职，饮食日减，土不生金则肺气亦虚，咳呛由生。脉软弱少力正是脾肺气虚之征，症非轻渺。", ["软", "弱"]], "2221": ["病机", "右脉弦数，弦主肝郁，数主热。原文谓“久咳膈痛，右脉弦数，肺痿之渐”，久咳伤肺，肝火犯肺，灼伤肺络则膈痛，脉弦数为肝火内郁之征，肺阴受灼，渐成肺痿，故莫作轻视。", ["弦", "数"]], "2222": ["病机", "脉弱主气虚，非实火之象。原文谓“喘咳稠痰转剧，咽痛脉弱，此非有余之火克金，乃气虚肝液亏也”，气虚则喘咳，肝液亏则咽痛，脉弱正是气虚之征。若再投凉剂则脾胃困败，须重剂滋补。", ["弱"]], "2223": ["病机", "脉软中虚，软主虚，中虚示脾胃气虚。原文谓“咳呛、秽痰、气喘，脉软中虚，肺络受伤也”，脾虚生痰则咳呛秽痰，肺气不足则气喘，脉软中虚反映肺脾两虚、肺络受损，殊非轻恙。", ["软"]], "2224": ["病机", "脉数主热，烦渴为热灼津伤；然早寒暮热、呛咳不减，且服凉剂未效，知非单纯表热，乃下虚上实、火不潜根。数脉在此示虚火上浮，非实火，故生津止渴佐降气，引火归元。", ["数"]], "2225": ["病机", "六脉并不弦数，排除肝火亢盛；咽碎痛、咳唾涎、便燥结，乃肝阴亏虚不能濡润，脾不输津下布。脉不弦数正是阴亏而非火旺之据，故主肝脾阴亏、津液不布。", []], "2226": ["病机", "脉软主虚，咳吐白沫、恶寒，乃肺金虚寒，不能约束津液，水津不布而化为白沫。软脉示阳气不足，故治以和脾保肺佐降气，温运中焦以复肺金宣降。", ["软"]], "2227": ["病机", "色脉少神，指面色与脉象皆乏神气，为气分亏虚之征。咳呛不止乃气亏不能肃降，故从脾肺调治，补土生金以复气分。脉象虽未明言，然少神即虚象之概括。", []], "2228": ["病机", "咳逆音哑似阴亏火动，然脉象未见虚数，则非虚火，乃蕴邪未得清彻，邪郁肺系致声哑。脉不虚数正是辨证关键，排除阴亏，主邪蕴肺络，宜轻剂和理以清透余邪。", []], "2229": ["病机", "六脉虚数无力，虚为气液不足，数为虚热，无力示中气大伤。咳沫、气喘、咽痛并见，乃中虚肝液竭，虚火上浮。脉虚数无力正是中虚液竭之象，故填补保肝。", ["虚", "数", "无", "力"]], "2230": ["病机", "六脉弦紧，弦主气郁、紧主寒凝，中气不舒则脉道拘急。近兼咳呛，恐气郁化火、灼伤肺络而咯血。弦紧为郁结之象，故惟恐咯血，示病机向热化伤络发展。", ["弦", "紧"]], "2231": ["预后", "元气素虚，疟后腠疏，喘咳转剧，脉数无力。数而无力为虚热，示元气亏耗、虚阳外浮。劳怯之渐，愈期未许，乃预后不良之判断，脉数无力正是劳怯将成之征。", ["数", "无", "力"]], "2232": ["病机", "久嗽不止致中虚表弱，盗汗、膈胀气喘皆中气不固、表虚不摄之象。脉软为正气不足、脾胃虚弱之征，非实邪壅滞。软脉主虚，故以健胃固表为治，使中气复则表自固，盗汗气喘可减。", ["软"]], "2233": ["病机", "咳喘多痰、咽间梗塞而六脉无力，无力即虚象，非痰热实邪。原文断为“中虚肝液亏”，中虚则运化失职生痰，肝液亏则气逆不降，故咳喘梗塞并见。脉无力正合虚损，殊非轻恙，提示本虚为主。", []], "2234": ["预后", "水亏火动、干呛咯血而六脉无力，无力示元气虚衰，不能制火。水亏则火无所制，火动灼肺故干呛咯血；脉无力说明非实火，乃虚火挟元气不足。原文“恐交春病剧”，因春木升发助火，故列预后警示。", []], "2235": ["预后", "再诊冲呛减少，脉象数势缓和，数减而缓和为邪热渐退、正气渐复之象，故原文称“斯属佳境”。然脉虽缓和而病根未拔，故又言“速愈不能”，示向愈而需缓图，非死脉亦非平脉。", ["数", "缓"]], "2236": ["主病", "温邪伤肺，咳呛失血，六脉弦数。弦为肝旺、数为热盛，温邪化热灼肺，木火刑金故咳呛失血。弦数并见示邪热未清而肝火偏亢，恐延入怯门，即虑其耗阴成劳，故以主病兼预后言之。", ["弦", "数"]], "2237": ["病机", "内伤失血、咽干膈痛、咳呛，而六脉并不弦数，说明非实热肝火为患。原文归为“虚阳不潜”，即阴不敛阳、虚阳上浮，故见咽干膈痛而脉不弦数。脉不弦数正是辨虚之关键，须省力调治，不可妄攻。", []], "2238": ["病机", "素有痰喘，近兼失血频发，两手脉虚软。虚软为气分不足、中气受伤之象，非实痰实火。中虚则气不摄血，故失血；气不化津则痰喘。原文断为“中虚气分受伤”，治须培阴保肺兼顾，标本同调。", ["虚", "软"]], "2239": ["预后", "阳络受伤而咳血膈痛，病久脉虚。虚脉示气血耗伤、正气不复，络伤失血日久则阴血亏虚，脉道不充故虚。原文“愈期难决”，正因脉虚示本元已损，恢复需时，非旦夕可效，属预后审慎之论。", ["虚"]], "2240": ["病机", "原文未载具体脉象，仅言“覆诊脉症，俱见平安”，而“内烧不止”为阴分虚损之征。脉症虽平，然阴亏内热未除，说明病本在阴分不足，虚火内生，故主病机为阴虚发热，与潮热、盗汗、舌红少苔等症相应。", []], "2241": ["病机", "狂失血后脉软，软为气怯之象。失血后脉不洪大反软，说明胃气薄弱、气血两伤，气不充脉。此脉主虚，与神疲乏力、纳差等症相应，故曰“非补无策”，治当补益胃气。", ["软"]], "2242": ["病机", "蓄血妄行后左脉弦大，弦主气滞，大主邪盛。血去而络脉不和，气机疏泄失常，故脉弦大。原文“并不咳呛，气逆”说明病在血络而非肺气上逆，治以疏滞通络，继用黑归脾调理。", ["弦", "大"]], "2243": ["病机", "原文言“脉络空虚”，非具体脉象，指阳明络伤、狂吐衄血后血去络空。血虚不能养心充脉，故气喘心悸。此属血脱络虚之病机，与面色苍白、心悸气短等症相应。", []], "2244": ["预后", "骤然失血半斗，神困脉微，微为阳气衰微之象。去血过多，气随血脱，阳气无依，故脉微神困，颇有脱势。此脉主阳气虚脱，预后险恶，急宜补气养心以固脱。", ["微"]], "2245": ["病机", "咳血反复，咽关不利，左脉弦数。弦为肝旺，数为火盛，木火刑金，灼伤肺络，故咳血咽不利。此脉主肝火犯肺之病机，与咳嗽、咯血、咽干等症相应。", ["弦", "数"]], "2246": ["病机", "素体不足，前曾失血，现脉弦数不静。弦数为水亏火旺之象，火不潜根，虚阳上浮，故脉躁动不静。此主阴虚火旺病机，久则灼肺，故“久防咳呛”，与潮热、盗汗、咳呛等症相应。", ["弦", "数"]], "2247": ["病机", "咳血气秽，六脉弦数模糊。弦数为温邪化热，模糊为邪入络脉、气血壅滞之象。温邪入络，肺胃受伤，故咳血气秽。此脉主温邪入络、肺胃热伤之病机，治以清理救肺。", ["弦", "数"]], "2248": ["病机", "失血过多则阴血亏虚，肝木失养而亢逆，木邪乘虚侮土，故脉不柔软，提示肝脾不和、土受木克。治以通为补，旨在疏达肝木、调畅气血，使木不伐土，血自归经。", ["不柔软"]], "2249": ["治法", "血症复萌而右脉弦数，右脉候肺，弦数主肝火偏旺、木火刑金，肺失清肃，阳络受损而血上溢。当升令之时，肝木升发太过，故宜泻白法清泻肺热、平肝降逆，以折其火。", ["弦", "数"]], "2250": ["预后", "咳血复萌兼遗泄，若脉数气喘则阴火大亏，今幸不脉数气喘，知阴分未至大亏，病在阳络受伤，血溢于上。先理后补，先调其络、清其阳热，再议滋补阴分。", ["数"]], "2251": ["病机", "狂失血后，络伤气怯，脉细无力为气血两虚之象。虽见咳呛，非阴火上冲，乃气不足使然，故以归脾法补气摄血、健脾养心，使气旺血生，络脉自复。", ["细", "无力"]], "2252": ["预后", "阳络受伤，血症频发，虽不咳呛，而六脉甚是弦数，弦主肝旺，数主火炎，木火内炽，阴血暗耗，非佳境也。立春在迩，肝木当令，恐升发太过而血复上溢，故预为调治。", ["弦", "数"]], "2253": ["病机", "呕泻蓄血，阳络阴络俱伤，气滞脾困，不克输津生新，下焦真气不充，清浊艰于升降，运谷无权，故腹膨便溺。六脉软弱无力，正合气血大虚、脾肾两亏之机，理当温补佐安神。", ["软", "弱", "无力"]], "2254": ["病机", "左脉弦动，略有烦躁，左脉候肝，弦动为肝阴亏虚、肝阳不潜，脾未输精上供，肝失濡养而亢动。故拟醒脾化气以助运化，参用柔肝法以敛浮阳，使肝脾调和。", ["弦", "动"]], "2255": ["病机", "脉象两手均称条达，惟重按少力，知中焦气机稍舒，而命门真火未能摄水，脾阳不克运动，水湿下注，故下体浮肿重滞，饮食能纳难化。仍拟和肝胃佐助元阳，以温运脾肾。", []], "2256": ["病机", "脉反弦数，弦为肝木偏旺，数为热象，结合腹胀不寐，显系木旺克土、肝阴内亏，土衰失运则胀，阴亏阳扰则不寐。就证参脉，未敢骤补，正因弦数属邪热未清，骤补恐助邪。", ["弦", "数"]], "2257": ["病机", "原文仅言「脉象动静」，未指具体脉形，故脉素从缺。中不胜湿，湿郁化热，气机不得快利，腐谷少权而二便不畅，脉之动静反映湿阻热郁、本虚标实之机，故以扶本为主、疏理为佐。", []], "2258": ["病机", "右弦左软，右候脾肺，弦为肝木侮土，故腹胀；左候肝肾，软为下焦无火、津不上供。深思抑郁、蓄血狂吐后肝失所养，气机呆钝，脉象正示木郁土困、下焦火衰之机。", ["弦", "软"]], "2259": ["病机", "狂失血后脉络空虚，气无所依而喘逆日甚，脉数无力乃阴血亏虚、气浮无根之象，数非实热，无力为虚，脾胃不强健，故属大虚候，当用甘温纳补以固本。", ["数", "虚"]], "2260": ["其他", "原文未识出具体脉名，仅言「病情脉象，未见进退」，故脉素从缺。前拟温补后病情脉象无进退，反映元气久虚、虚损难复，温补为唯一对策，舍此无策，属守方观察之论。", []], "2261": ["病机", "六脉洪大不柔，洪大为暑热邪盛、气分热炽之象，不柔则示邪热内蕴、阴分受灼。暑邪犯肺，咳痰带血，脉证相参，热势方张，故补阴剂不宜早服，恐滋腻恋邪。", ["洪", "大"]], "2262": ["病机", "脉象紧数，紧主邪束气机、数主热，咳逆咽痛音哑乃肺虚肝液亏，虚火循经上灼咽喉，紧数反映虚火内郁、肺金受灼，本虚标实，故曰棘手。", ["紧", "数"]], "2263": ["病机", "脉动无神，动为阳动不宁，无神则根本已亏。肾水不能制火，火克肺金，阴精不化气而咳逆音哑，此木郁水亏、虚火上炎之象，脉动无神正示虚阳浮动、根本失守。", ["动"]], "2264": ["病机", "原文言咳逆音哑似属阴亏火动，但脉象未见虚数，说明并非单纯阴虚火旺。脉不虚数则阴亏火动之象不显，反提示蕴邪未得清彻，邪郁于肺，故咳逆音哑。治宜轻剂和理，以清透蕴邪，而非滋阴降火。", []], "2265": ["病机", "上膈及臂胀痛不仁，六脉弦数。弦主络脉拘急不畅，数主温邪化热，温邪入络，气血壅滞，故胀痛不仁、坐卧不宁。原文恐肺气痿伤，因温邪灼肺、络阻气痹，须清通法以透络泄热，兼有痰喘更证肺络受累。", ["弦", "数"]], "2266": ["病机", "右胸肋高肿、络不通气而成痹，右寸关脉大。寸关候肺脾，脉大主邪壅气滞、络脉不通，痰浊郁于肺络则肿。原文恐肺气痿伤，因痰黑带腥稍咳，示痰浊久郁化热伤肺，故拟通络化痰佐理气以图松解。", ["大"]], "2267": ["病机", "咳呛秽痰带血，右脉弦数。弦主气郁络急，数主郁热，气郁络伤则血溢，肺金受克故咳呛带血。右脉候肺，弦数见于右，正合肺络郁热之机。冬至节近，阴气渐盛，故须宽怀调理以防气郁加重。", ["弦", "数"]], "2268": ["病机", "肺气素虚又感温邪，身热咳血，咯痰胶腻，六脉数大。数主温邪化热，大主邪热壅盛，热灼肺络则血溢，煎熬津液则痰胶腻。原文言正气虽虚，温补不合，因脉数大示邪热未清，温补助热，故不可温补。", ["数", "大"]], "2269": ["病机", "原文言气虚表弱，色脉少神，自汗属泄。色脉少神示正气亏虚、神气不充，气虚则表卫不固，腠理疏松而自汗，汗出属泄更伤气阴。法当培本，即补益气血以固表止汗，非单纯敛汗所能治。", []], "2270": ["病机", "表里交虚，形衰脉弱，病经三载。脉弱主气血不足、正气亏虚，形衰与脉弱相应，示气阴两伤、表里俱虚。病程三载，久病耗损，故须气阴并补，不可偏补一气一阴，当兼顾培补以复其本。", ["弱"]], "2271": ["病机", "食少痰多、火动不寐，六脉虚弦无力。虚主气阴不足，弦主虚火内动，无力示正气衰。气阴俱虚则脾不健运而食少痰多，虚火上扰则不寐。原文断为气阴俱不足，故以健中保肺为主，补土生金以复气阴。", ["虚", "弦"]], "2272": ["主病", "脉软为气血不足之象，表里俱虚，故见类疟兼呛恶寒。脉软主虚，表虚则恶寒，里虚则营卫不和而类疟。非补无策，强调虚证当补，脉软为虚证之凭。", ["软"]], "2273": ["预后", "脉数主热，然气喘咳血、恶寒自汗，显系虚火浮越。数而腹痛、大便不结，非实热内结，乃营液内亏、肝胃困败之候。脉数与症相悖，正虚邪恋，故曰非佳境。", ["数"]], "2274": ["病机", "脉动无神，乃肾水不能制火，虚火上炎之象。木郁水亏，阴精不化风而病燥，燥则痒咳、音哑嗌痛。动脉主惊主痛，此则无神，为虚阳浮越，故拟滋纳。", ["动"]], "2275": ["病机", "六脉并不弦数，排除实火。质弱火炎、牙痛口干，系肝肾虚而不克输津上供，虚火上浮。脉不弦数，说明非实热，不宜过投凉剂，当以滋填为要。", []], "2276": ["病机", "六脉不甚有力，示气亏表弱，营络空虚。不时寒热、气喘火升，乃气阴两虚、虚阳上浮。脉无力为虚，故须气阴兼顾，不可纯补纯清。", []], "2277": ["主病", "六脉细软无力，为肝肾虚损、下虚之候。失血兼精滑，血不养肝则筋拘，泄自汗则阴液外脱。细软无力主大虚，须重剂培补，以复元气。", ["细", "软"]], "2278": ["病机", "六脉沉弱无力，沉主里，弱主虚，乃中虚阴火不潜之象。中气不足，阴火失于潜藏，故脉沉弱无力。此虚火内郁，非实热，治当补中潜阳。", ["沉", "弱"]], "2279": ["预后", "六脉虚数无力，虚为阴亏，数为阳浮。素体阴亏，咳逆自汗脾泄，阳本大亏。虚数无力乃阴不敛阳，故宜填纳温补，然无虞未许，预后难料。", ["虚", "数"]], "2280": ["预后", "久嗽不止、多痰咽痛及气喘而见脉软软、举动无力，乃阴亏而中气大虚之象。脉软无力，正气衰惫，不能鼓动脉道，故主非吉兆。软脉在此非和缓之常，而是虚损难复之征，与久嗽气喘之症相应，提示中气阴分俱亏，预后不良。", ["软"]], "2281": ["病机", "相火旺而兼湿热下注，以致阳举精泄，六脉弦滑。弦为相火内动、肝木不柔，滑为湿热蕴结、痰浊内盛。脉弦滑并见，说明火与湿相合，下扰精室，故见阳举精泄。此脉象直接反映相火湿热之病机，治以滋清佐苦泄，正合脉证。", ["弦", "滑"]], "2282": ["病机", "精关不固、腰脊痿痛而六脉细软无力，细为阴血不足，软为阳气衰微，无力则中气亦虚。脉象显示肝肾下虚、精气不固，腰脊失养故痿痛。细软无力之脉与精关不固相应，说明虚损在肝肾，宜涩精温补以固其本。", ["细", "软"]], "2283": ["病机", "厥阴气郁、膈胀目昏，君火内迫而阴精属泄，脉不柔软。脉不柔软说明气郁化火、内迫阴精，非虚软之候。君火内迫则阴精不守，故见遗泄。脉象失柔，反映郁火内扰、心肾不交之病机，治当交心肾苦泄法，兼心悸则作肝火看。", []], "2284": ["病机", "坎离不交，惊恐自汗，近兼精滑，精气神俱亏，脉空无力。空脉主精血大亏、脉道不充，无力则元气衰惫。精气神俱亏，故脉空无力，足痿艰行亦由下元虚损。此脉象说明大虚之候，须重剂频补，以填精固本、交通心肾。", ["空"]], "2285": ["病机", "失血兼精滑，肝肾虚损，筋拘而坐卧不宁，六脉细软无力。细为阴血亏少，软为阳气不足，无力则中气大虚。下虚而血不养肝，故筋拘不宁；并泄自汗，乃大虚之候。脉细软无力正合肝肾虚损、气血两亏之病机，须重剂培补。", ["细", "软"]], "2286": ["预后", "咳血复萌，近兼遗泄，幸不脉数气喘。脉数主火旺阴伤，气喘为气逆不降。今脉不数、不气喘，说明阴分不致大亏，火势未炽，故病虽咳血遗泄，尚属阴络伤而非大虚。脉象未见数急，提示预后尚可，先理后补。", ["数"]], "2287": ["病机", "阴分不足，又兼湿火上冲，脑顶下陷，遗泄，督脉痿痛。原文未识脉名，故脉象要素从缺。所述症候显示阴亏于下、湿火上扰于上，清阳不升则脑顶下陷，督脉失养则痿痛，湿火下注则遗泄。病机为虚实夹杂，治以清上纳下。", []], "2288": ["病机", "原文谓“久浊元虚，六脉无力”，虽未点明具体脉名，但“无力”即虚象。久患浊病，元气亏虚，脉道不充，故六脉无力。此脉主中气不足、清阳不升之病机，治以“健中升清”，使元气渐复，则浊自安适。", []], "2289": ["病机", "脉沉弱为阳气不摄之象。原文谓“脾肾两虚，腰痛便浊”，又因“君火下陷”“命门阳气不摄”，致上脉沉弱、大便溏薄。沉主里、弱主虚，说明脾肾阳气亏虚，不能固摄，故用补中益气合滋肾法。", ["沉", "弱"]], "2290": ["病机", "原文“诊得六脉并不弦数”，排除热盛之脉。误服药酒，热注膀胱，小便下浊，久延不痊，烦渴肉削，似有热象，但脉不弦数，说明热非实火，乃气陷津伤所致。故用补中益气加减，升清培补。", []], "2291": ["病机", "原文未载脉象，仅言“便浊腰痛，督脉受伤”。督脉总督诸阳，受伤则阳气不固，精关失守，故便浊、腰痛。病机为督脉亏虚、精氣不固，治以固精补气，使督脉得养，精气得固。", []], "2292": ["病机", "原文“尿血溺痛，久延不痊，六脉无力”，脉无力为气血亏虚之征。久病尿血溺痛，耗伤气血，故六脉无力。此脉说明正虚为本，湿热为标，须标本兼顾，不可纯用清利。", []], "2293": ["病机", "六脉细软为气陷伤津之象。原文“尿血久缠，腰腹作痛，屡投利剂，气陷伤津”，致精神委顿、六脉细软。细主阴血不足，软主气虚，说明利剂过用，气陷津伤，故须升清培补，否则秋病加剧。", ["细", "软"]], "2294": ["病机", "原文“脉象亦未柔软”，说明脉尚欠柔和，正气未复。外症虽愈，小溲仍不爽，阴囊溃烂，脉未柔软，提示余邪未清、气化未复，故“大补不宜”，恐滋腻碍邪，当以缓图。", []], "2295": ["病机", "六脉沉弱为命门气亏、中虚气陷之征。原文“命门气亏，兼之中虚气陷，清气不升，小便溺塞”，沉弱说明阳气不足，不能升清降浊，故凉剂不宜多服，当温补升提。", ["沉", "弱"]], "2296": ["病机", "六脉弦紧，弦主痛、主饮，紧主寒主痛。湿火下注，小便溺痛，湿热蕴结下焦，膀胱气化不利，不通则痛，故脉见弦紧。此脉象反映湿火内蕴、气血壅滞之病机，主淋证溺痛，与小便涩痛、湿热下注之症相应。", ["弦", "紧"]], "2297": ["病机", "左脉细软，细为阴血不足，软为虚象。左脉候肾，细软乃少阴肾阴亏虚之征。肾阴不足，膀胱挟热，水道不利，故频解溺痛。此脉象说明肾阴亏虚为本，膀胱热结为标，主虚中夹实之淋痛，与少阴亏虚、膀胱挟热之症相应。", ["细", "软"]], "2298": ["病机", "脉沉且紧，沉主里，紧主实主痛。胸腹硬痛、舌苔湿腻带黄、大便数日不解，乃结胸重证，邪热与痰水互结于里。脉证均实，沉紧为邪结在里、气血壅滞之象，主大结胸证，与胸腹硬痛、心烦、便闭之症相应。", ["沉", "紧"]], "2299": ["预后", "脉沉亦起，不似以前之实而有力，说明邪气渐退，正气来复。舌苔尖退根化，中心宣浮，为邪从里出之兆。此脉象反映结胸重证经攻下后病势向愈，主预后良好，与苔化、脉起之症相应，故可改轻剂调理。", ["沉"]], "2300": ["预后", "脉沉而手足微凉，十指尤冷，头面自汗，气息微喘，乃太阳表证兼卫虚阳衰，有亡阳厥脱之危。脉沉为阳气不能外达，肢厥脉沉提示元阳衰微，病情危重。此脉象主阳气虚衰、表邪未解之危候，与自汗、肢冷、喘促之症相应，预后险恶。", ["沉"]], "2301": ["主病", "脉浮而紧，浮主表，紧主寒。妇人恶寒高热、头痛项强、体疼骨疼、周身无汗，乃寒邪束表，卫阳被遏，营阴郁滞。脉浮紧为伤寒表实证之典型脉象，主太阳伤寒，与无汗、身疼、恶寒发热之症相应。", ["浮", "紧"]], "2302": ["病机", "脉洪大而浮紧，洪大为热盛，浮紧为寒束。时寒时热、热多寒少、无汗、心烦、手足躁扰、体温41℃，乃寒邪外束，热郁于里，表寒里热之候。脉洪大浮紧说明寒束热盛、表里俱实之病机，主伤寒重证，与高热无汗、烦躁之症相应。", ["洪", "大", "浮", "紧"]], "2303": ["主病", "脉浮而紧，浮主表，紧主寒。冬月感寒，恶寒高热、头痛项强、腰脊酸痛、皮肤干热无汗，乃寒邪袭表，卫阳闭郁，营阴凝滞。脉浮紧为太阳伤寒表实证之脉，主正伤寒，与恶寒无汗、身疼骨痛之症相应。", ["浮", "紧"]], "2304": ["病机", "六脉迟缓与体温之高不相应，是湿温固有之脉象。湿性黏滞，困遏阳气，脉道不利，故脉来迟缓；虽热邪内蕴而体温高，但湿阻气机，脉不因热而数，反见迟缓。此脉象揭示了湿温病湿重于热、阳气被遏的病机，为诊断湿温的重要依据。", ["迟", "缓"]], "2305": ["病机", "湿温病延两周，热度颇高，忽发肠出血，肛门血出涓涓不止，体温渐降，周身苍白，面无血色，气息微促，手足厥冷，脉沉细而数。沉细为阴血亏虚、阳气衰微之象；数脉为热邪未清、虚热内扰。此乃热入营血、气随血脱、阴阳不相顺接之危候，故见厥冷而反赤膊赤足、欲得冷饮，为真热假寒之象。", ["沉", "细", "数"]], "2306": ["病机", "再诊脉沉细而数，两手冰冷，胸腹四肢发凉，而病者不怕冷、不盖被单，反畏热欲冷饮。沉细数脉主里虚有热，阳气内郁不能外达，故外显寒象而内蕴真热。此即《伤寒论》「身大寒，反不欲近衣者，寒在皮肤，热在骨髓也」之真热假寒证，脉象与症候合参，揭示热邪深伏、阳郁不达之病机。", ["沉", "细", "数"]], "2307": ["主病", "妇女季夏患热病，高热自汗，口干舌绛，大渴欲饮，周身肤红如中酒，烦躁不安，小便黄赤，脉洪大而数。洪大数脉为阳明气分热盛之典型脉象，热邪亢盛，气血涌沸，故脉来洪大而数。此脉主阳明热盛、气分大热之病，与白虎人参汤证相应，故用白虎加花粉清之而热退神安。", ["洪", "大", "数"]], "2308": ["主病", "诊脉时因烦躁而三脱其手，六脉皆形洪大而数，且欲饮冰水。洪大数脉为阳明气分热盛之象，热邪炽盛，充斥内外，故脉形洪大而数；烦躁、大渴欲冷饮，皆热盛伤津之候。此脉主阳明热盛之病，与白虎人参汤证相应，故令先食西瓜，继进白虎加花粉方。", ["洪", "大", "数"]], "2309": ["病机", "前次药后已痊，忽又发寒热，恶寒时欲盖衣被，发热时又去衣被，反复三四次，似疟而实非真疟。诊其脉弦而兼数，弦为少阳主脉，数主热，此乃阳明余邪未清，复传少阳，邪在半表半里之病机。弦数脉与寒热往来、口苦咽干等少阳症相应，故以小柴胡加槟榔、藿香和解少阳而痊。", ["弦", "数"]], "2310": ["主病", "妇人仲夏病热，延至四日，病势愈进，赤膊赤足，卧于地上，烦躁不安，反复颠倒，目赤肤红如中酒，多汗如珠，大渴引饮，脉洪大而数，舌绛而干。洪大数脉为阳明气分热盛之典型，热邪亢盛，气血沸腾，故脉洪大而数。此脉主阳明热盛、气分大热之病，与白虎人参汤加花粉方证相应。", ["洪", "大", "数"]], "2311": ["病机", "诊其脉洪大而数，重按之则微芤，舌绛而干，毫无润气。洪大数脉为阳明热盛之象，然重按微芤，提示热盛伤津、阴血亏耗，脉道失充。此脉象揭示阳明热盛而津气已伤之病机，故为白虎汤证，用白虎人参汤加花粉清热生津，先饮西瓜汁以救津液。", ["洪", "大", "数", "芤"]], "2312": ["病机", "脉洪大而数，为阳明气分热盛之象。洪大主热盛于经，数主热邪亢盛，与高热、自汗、心烦、口渴欲冷饮、舌绛而干、白睛发红等症相应，说明表里俱热，热盛伤津，故用白虎人参汤加味清热生津。", ["洪", "大", "数"]], "2313": ["病机", "脉洪大而数，舌干燥而绛，目白睛发红，肤癍疹色红而紫，口渴欲冷饮，说明热邪充斥表里，气分热盛，营分亦受波及。洪大数之脉为阳明热盛之典型，与心烦、抚胸等症相应，故断为表里之热。", ["洪", "大", "数"]], "2314": ["预后", "两脉亦渐平，说明高热已减，烦躁已安，癍疹色淡，为热退脉和之佳兆。然心下郁郁微烦，大便四日未解，舌根薄腻带燥黄，示余热未清，肠腑燥结，故改用竹叶石膏汤合调胃承气汤清余热、通腑实。", ["平"]], "2315": ["预后", "脉象已较平，为危机已去之征。患者呕吐止、身有微汗、热渐退、神识大清，说明邪热已衰，正气渐复。然余热未净，故用增液承气加葛根、黄芩、生石膏以清余热、通腑实、生津液。", ["平"]], "2316": ["预后", "脉细数之极，为阴液枯竭、热毒内陷之象。产后二十余日，昏糊更甚，顽热不退，自汗不止，眼珠上耸，回血如酱油水，说明毒已入血，阴液耗竭，正虚邪盛，故断为不治。", ["细", "数"]], "2317": ["其他", "本段未识别脉名，主要论述阳明实热之证，延至此时，下亦死，不下亦死，故用白虎承气合增液法，并静脉注射葡萄糖以增血液、强心脏，体现急下存阴、中西医结合救治的思路。", []], "2318": ["主病", "脉实而有力，为阳明腑实之征。腹部满如覆釜，按之如石，满腹皆痛，气息微喘，口干齿燥，舌苔焦黄，说明燥屎内结，腑气不通，热邪内盛。脉实有力与腹满痛相应，故主阳明实热证。", ["实", "有", "力"]], "2319": ["病机", "脉沉数而有力，沉主里，数主热，有力为实，说明热邪内结于里，腑实已成。肌肤炙手，胸部尤其，周身癍疹色带紫黑，唇焦齿垢，舌苔干燥焦黄，大便六日未解，小溲短赤，皆里热炽盛、燥屎内结之象，故脉沉数有力主阳明腑实热证。", ["沉", "数", "有", "力"]], "2320": ["病机", "原文未识脉名，仅言'脉息颜色，未犯绝象'，故脉象要素为空。此段核心在'食积为患'：患者病前异常健啖、晚膳后即就寝，食滞胃肠，久积化热生痰，蒙蔽神识，故状如中风而名'食中'。脉无绝象说明正气未败，病属实证可下，故决以大承气汤加莱菔子通腑泻积。", []], "2321": ["病机", "脉'沉实而有力'，沉主里、实主邪结，说明病位在里而正气尚充，邪实内结。身体四肢如常、不厥不热、呼吸略粗带鼾声、下颔随手而开无痉象，皆非外感痉厥；惟'按其脘口则颇满硬'，与沉实脉相应，提示宿食或燥屎结于脘腹，属里实之证。", ["沉", "实"]], "2322": ["病机", "脉'沉实而有力'，沉候在里、实主邪结，与'脘口及腹部均大呼疼痛'、'大便已三日未解'相合，说明燥屎或积滞内结肠腑，腑气不通而痛。面无人色、口唇发青、四肢发冷乃痛极气机闭阻之象，非虚寒；痛在满腹、右腿能伸，排除盲肠炎，脉证合参属里实腹痛。", ["沉", "实"]], "2323": ["病机", "脉'沉实有力'，沉主里、实主积，说明病本在里而邪实内结。患者饥饱不时、内伤饮食，又汗后当风、脘腹受寒，寒食互结，腑气不通，故腹痛渐剧、大便不通；痛极额汗、四肢微厥、呕吐乃寒凝气逆所致。脉沉实提示可下，故用大黄附子汤温下，合甘草干姜汤温中。", ["沉", "实"]], "2324": ["病机", "两脉'沉实而有力'，沉主里、实主结，说明邪实结于里。身体屈曲如虾、腹痛拒按、少腹尤甚、大便四日未解、舌苔厚腻微干，皆积滞内结之征；额汗清冷、四肢微厥、周身无热，则示寒凝。脉沉实与寒结相合，故断为寒结，非温下不为功。", ["沉", "实"]], "2325": ["病机", "此段未出具体脉象，仅引'尺以候肾、肾主下焦'之说，故脉象要素为空。原文批评后世将少腹病证一概责之于肾、妄引桂枝加桂汤伐肾邪，指出仲景原意本作寒断。其主旨在于辨明少腹病证之病机归属，纠尺脉候肾之说被滥用之弊，属病机讨论。", []], "2326": ["病机", "脉'微数'，微为正气虚衰、数主虚热内扰，与百合病'百脉一宗，悉致其病'相应。重病后身体惫极、正元难复，故意欲食不能食、欲卧不能卧、如寒无寒如热无热、口苦小便赤，皆阴虚内热、神志不宁之象；音哑为津亏。脉微数正示虚多邪少、虚热为患。", ["微", "数"]], "2327": ["病机", "脉'微弦数'，弦主肝郁气滞、数主郁而化热，与'气郁为患'相合。病由食后被责、肝郁逆脾，脾失运化，胃失和降，故腹满微痛、五日不便、舌根燥黄、肤微热。前医理气降逆不效，正因未疏肝醒脾，脉弦数提示郁热夹停食，治当疏肝醒脾以调胃。", ["弦", "数"]], "2328": ["病机", "脉沉细而弦，沉主里，细主虚，弦主痛。患者腹满硬而痛、苔黄腻干、便闭、呃逆、呓语，显系里实积滞、腑气不通，兼见阴伤。脉沉细为气血内困，弦为痛为积，故主里实腹痛、热结旁流之候。", ["沉", "细", "弦"]], "2329": ["预后", "前诊脉沉细而弦，今诊脉沉已较起、细已较大，说明里气渐通、正气来复。原文以脉象变化判断“已有转机”，结合大便得解、呓语呃逆不作，可知邪有出路，病势向愈。", ["沉", "细"]], "2330": ["治法", "本段未言脉象，专论肝热生风之治法。以羚羊角为主清肝息风，配石膏清表里之热，葛根解经枢之热，丹皮、生地凉血泻火，天麻、僵蚕、蝉衣疏风。全方针对肝热动风之病机，非凭脉辨证。", []], "2331": ["主病", "脉微沉迟，微为阳虚，沉主里，迟主寒。患者常年恶寒，盛夏亦需厚衣，显系阳气虚衰、阴寒内盛。然投温补之剂不效，终以气中而亡，说明脉证虽属虚寒，但病深药难及，非寻常阳虚可比。", ["微", "沉", "迟"]], "2332": ["病机", "脉微沉迟，尺部更沉，微为阳衰，沉迟主里寒。患者年过五旬，妻妾均无出，纵欲耗精，肾阳亏虚，故脉见微沉迟而尺尤甚。断为肾亏，然久服八味丸无效，提示肾精亏耗深重，非短期温补可复。", ["微", "沉", "迟"]], "2333": ["其他", "脉微大微数，原文谓“不足以为病脉”，即脉象略偏大数而无明显病态。患者暴食善饥，大便如常，食渣不知从何而去。脉无实热之象，故不属消谷善饥之胃火证，提示此症非典型病脉所主，当另寻机理。", ["大", "数"]], "2334": ["主病", "脉沉紧而微迟，沉主里，紧主痛主积，微迟为气血壅滞、阳气不伸。患者右腹肿痛如拳、右足不能伸直、寒热便闭，显系肠痈成脓、热毒壅结。脉沉紧为里实疼痛，微迟示正气受困，故主肠痈里实之候。", ["沉", "紧", "微", "迟"]], "2335": ["病机", "脉按之而不可得，即沉伏难寻，主阳气衰微、水湿泛滥。患者腰以下肿甚、按之冷如冰、呼吸短促、小便短少、阴囊缩入，显系阴水泛溢、肾阳衰败之候。脉伏不出，正合水气太过、阳气不能外达之病机。", []], "2336": ["主病", "湿温病主证脉弦细而濡。弦主湿阻气机，细主湿性黏滞、脉道不利，濡主湿邪偏盛、阳气不伸。湿温初起，湿遏卫阳则恶寒，湿郁化热则但热不寒；湿阻清阳则头痛、身重而疼；湿困中焦则胸中痞闷、不食不饥、口渴不欲饮；午后身热状若阴虚，皆湿温之候。脉与证合，故为湿温主脉。", ["弦", "细", "濡"]], "2337": ["治法", "三仁汤证脉弦细而濡，与头痛恶寒、舌白不渴、面色淡黄、胸闷不饥、午后高热、证若阴虚并见。弦细濡为湿温初起、湿遏气机之象：弦主湿阻，细主湿滞，濡主湿盛。湿温忌汗，故以三仁汤宣上畅中渗下，轻清宣化，使湿去热孤，此即原文所述湿温治疗之对证疗法。", ["弦", "细", "濡"]], "2338": ["治法", "本段未出脉象，专论湿温治法。前举诸方轻清取巧，仅宜病势较轻者；若胸闷特甚、病势较重，则须以经方为本，合时方化裁。遵仲景治风湿之法，取微微汗出、续续下行，使汗利两解，湿温之邪分两路而去。首用麻黄，非与桂枝同用则不能大汗，故无大汗害事之虑，此即其治法要旨。", []], "2339": ["主病", "百会疽初起，脉见洪数者属实，脉见细数者属虚。洪数主热毒壅盛、气血沸腾，故见高尖红肿、掀热疼痛、憎寒壮热、大渴便秘烦躁，为实热之证；细数主正虚而热，故见漫肿平塌、紫暗坚硬、掀痛根散、恶寒便泻，为虚热之候。脉与疮形合参，以辨虚实。", ["洪", "数", "细"]], "2340": ["病机", "本段未出脉象，论瘰疬病机。引《灵枢·寒热》谓鼠瘘寒热之毒气留于脉而不去，其本在脏，其末上出于颈腋之间；《外科证治全生集》述瘰疬初起小核在皮里膜外，不觉疼痛，皮色不异，渐大如桃李，旁增不一。诸名皆状其形，总由毒气留脉、脏本亏虚所致。", []], "2341": ["病机", "脉右数带滑，右脉候肺，数主热，滑主痰。肺移热于大肠，则咳呛便溏；热灼津伤，则身热渴饮、舌糙。数滑并见，为肺热痰壅之象，热移大肠故便溏。治仍以宣豁，宣肺豁痰以清其源，使肺热得解，大肠自安。", ["数", "滑"]], "2342": ["病机", "脉沉弦，沉主里、主气郁，弦主饮、主痛。痰湿内留，络道失宣，则咳呛肋痛、痰出不爽。由气虚饮胜所致：气虚则饮停，饮胜则络阻，故脉沉弦。法以通络导痰，使气机通畅，痰饮得化，则咳呛肋痛自减。", ["沉", "弦"]], "2343": ["病机", "脉小数，小主阴虚，数主热。阴虚生热，肺金失肃，则咳呛肋痛；气滞不行，则辄胀。小数并见，为阴虚内热之象，热灼肺金，气机郁滞。治从金郁泄之、木郁达之，泄肺达木以解郁清热，使阴复热退，肺肃气畅。", ["小", "数"]], "2344": ["病机", "脉小数，小为阴虚，数为火盛。肺虚火盛，灼津为痰，故咳呛气促、胁肋引痛；胃纳式微、便结溲涩，皆火盛耗津、肺失肃降之象。脉小数正合虚火内扰之机，法当降肺气以清痰火。", ["小", "数"]], "2345": ["病机", "脉濡小，濡主湿、小主虚。久咳肺元自虚，子盗母气，阳明生气不振，故杳不思纳、舌白腻。濡小为肺胃气虚兼湿之征，非实邪壅滞，故姑先降肺理胃，以复中焦生气。", ["濡", "小"]], "2346": ["病机", "脉濡弦，濡为湿滞，弦为木火内郁。湿热不澈，阳明受灼，灼津成痰，故咳呛痰少。濡弦并见，示湿郁化热、木火刑金之机，治当少阴、阳明并调，清火化湿。", ["濡", "弦"]], "2347": ["病机", "脉沉弦，沉主里、弦主饮主痛。痰火留肺，肺气𪱥郁，不得宣降，故咳呛气粗。沉弦为痰火内结、气机壅实之象，非表邪所致，故以泻肺法直折其壅。", ["沉", "弦"]], "2348": ["病机", "脉右数，右候肺卫，数为热。痎疟复感，邪郁肺卫，化热伤津，故咳呛身热；脘闷为湿滞中焦。右数独显，示病位在上焦肺卫，治先宣上，透邪外出。", ["数"]], "2349": ["病机", "脉濡弦，濡主湿滞，弦主肝郁。迭岁咳呛，肺气𪱥郁，气滞日久成疝，少腹攻痛。濡弦为肝肺气郁兼湿之征，气机不畅则痛，故以肝肺同治，调气化湿。", ["濡", "弦"]], "2350": ["病机", "脉弦小数，弦主痰饮络滞，小为阴伤，数为郁热。痰湿内留，肺胃失宣，络道被蒙，故胁肋抽痛。弦小数示痰湿郁而化热、络脉不和，以通络导痰法疏其壅滞。", ["弦", "小", "数"]], "2351": ["病机", "脉右数，右候肺，数为热。阴虚湿郁化热，肺金失肃，故咳呛自汗。右数独见，示热郁肺卫，非纯虚之候，乃湿郁化热、阴伤失肃之机，故以千金方清肃肺金。", ["数"]], "2352": ["病机", "脉右数，右寸主肺，数主热。久咳不已致肺火自旺，清肃失司，故脉右数。此脉象说明肺有火热，主肺热咳嗽，与久咳、肺火旺相应。", ["数"]], "2353": ["病机", "脉右滑数，滑主痰，数主热。内有郁火，外易招风，风火相煽，肺胃受灼，咳呛痰多，故脉右滑数。此脉象说明肺胃痰热内蕴，主痰热咳嗽，与咳呛痰多相应。", ["滑", "数"]], "2354": ["病机", "脉右数，右寸主肺，数主热。咳呛不已，肺火自旺，由阴虚生热所致，故脉右数。此脉象说明肺有虚热，主阴虚肺热咳嗽，与咳呛不已相应。", ["数"]], "2355": ["病机", "脉右小数，小主虚，数主热。久咳不已，肺阴自耗而咳逆，身热盗汗，故脉右小数。此脉象说明肺阴亏虚，虚热内生，主肺阴虚咳嗽，与身热盗汗相应。", ["小", "数"]], "2356": ["病机", "脉弦小数，弦主痛主肝，小主虚，数主热。复感寒，著食腹痛便血，脉弦小数。此脉象说明肝脾不和，寒热错杂，主腹痛便血，与感寒、著食、腹痛便血相应。", ["弦", "小", "数"]], "2357": ["病机", "脉濡数，濡主湿，数主热。湿困太阴，身热咳呛，脘闷腹胀，故脉濡数。此脉象说明湿遏热伏，太阴湿困，主湿热咳嗽，与身热、脘闷腹胀相应。", ["濡", "数"]], "2358": ["病机", "脉濡弦，濡主湿，弦主肝主饮。湿热内留，肺胃失宣，咳呛身热，故脉濡弦。此脉象说明湿热内蕴，肝肺不和，主湿热咳呛，与咳呛身热相应。", ["濡", "弦"]], "2359": ["病机", "脉右数，右寸主肺，数主热。久咳不已，肺元自虚，痰入络隧，胁肋抽疼，故脉右数。此脉象说明肺虚有热，痰阻络隧，主肺虚痰咳，与胁肋抽疼相应。", ["数"]], "2360": ["病机", "脉右小数，右寸关候肺胃，小为气阴不足，数为有热。原文“伤于风者，上先受之”言风邪袭肺，咳痰薄白、形寒为表邪未净，里热则脉数。风邪外束、肺胃内热，故脉右小数，主肺胃同病，治当清透肺胃。", ["小", "数"]], "2361": ["预后", "脉滑数主痰热内盛，滑为痰浊，数为热象。原文“痰阻络痹”致咳呛右胁肋痛、气逆不能平枕，苔腻亦痰湿之征。痰热壅阻肺络，气机逆乱，脉见滑数，防昏喘者，正虑痰热蒙窍、肺气欲竭之变。", ["滑", "数"]], "2362": ["病机", "脉右数左弦，右寸候肺，数主痰火；左关候肝，弦主木郁。原文“咳久肺元自虚，痰火𪱥郁，木叩金鸣”，肺虚而痰火内郁，肝木偏亢反侮肺金，故右数左弦。此脉示肺虚痰火、肝木犯肺之病机，治以泄金达木。", ["数", "弦"]], "2363": ["病机", "脉濡弦，濡为湿滞，弦主饮邪。原文“迭感咳呛，热灼饮泛”，热灼肺津则咳呛，饮邪泛溢则脉弦，湿滞中焦则脉濡。肺胃同病，热与饮结，故脉濡弦，主饮热互结、肺胃失降之病机。", ["濡", "弦"]], "2364": ["病机", "脉右数，右寸关候肺胃，数主热。原文“肺有郁火，自觉形寒”，郁火内伏，阳气不达肌表故形寒，脉数则内热之征。此脉主肺经郁火，火郁于内而外显假寒，治以西昌法清泄肺火。", ["数"]], "2365": ["病机", "脉右数，右候肺胃，数主热。原文“阴虚生热，肺胃升降失调”，阴虚不能制阳则生内热，热扰肺胃则升降失司，脉数即虚热之象。此脉主阴虚内热、肺胃气逆之病机，治以清泄。", ["数"]], "2366": ["病机", "脉小弦数，小为阴血不足，弦主木火，数为热盛。原文“木火内燔，凌心扰肺”，肝木化火，上灼心肺，故时咳逆、时舌疼。脉小弦数正示阴亏火旺、木火刑金之病机，还须怡养以柔肝清火。", ["小", "弦", "数"]], "2367": ["病机", "脉沉濡弦，沉主病在里，濡为湿滞，弦主饮邪。原文“通络导痰，疏泄厥阴”后脉仍沉濡弦，知痰饮湿浊深伏厥阴，络脉痹阻未解。此脉主痰湿内蕴、肝络不和之病机，故再从原议出入。", ["沉", "濡", "弦"]], "2368": ["病机", "脉右数，右寸候肺，数主热。暑风外袭，引动宿饮，咳呛痰薄、形寒身热，为外邪束表、饮邪内动，郁而化热之象。脉数示热势已起，病位在肺卫，故治以宣上，透邪宣肺以解外袭之暑风。", ["数"]], "2369": ["病机", "脉弦而数，弦主气机郁滞、饮邪内停，数主火热。气虚湿胜，湿郁化火，火烁肺金，故咳而呕逆、气粗肋痛、舌腻。弦为湿郁气滞，数为化火之征，脉症合参，示湿郁化火、肺金受烁之病机。", ["弦", "数"]], "2370": ["病机", "脉弦带芤，弦主火盛气逆，芤主阴血亏虚。肺虚火盛，咳呛痰稠，时或咯血，火灼肺络则血外溢，阴血耗伤故脉见芤。弦芤并见，示肺虚火盛、阴血受损之病机，故当清肺胃以折火势。", ["弦", "芤"]], "2371": ["病机", "脉右数，右寸候肺，数主火热。痰火上凌，肺气𪱥郁，音嘶咳逆，痰火壅阻肺窍则音嘶，肺失宣降则咳逆。脉数示痰火内盛，病位在肺，故发当宣泄，宣肺泄热以解痰火之郁。", ["数"]], "2372": ["病机", "二诊脉右数，右寸候肺，数主火旺。肺虚火盛，咳呛音嘶，火灼肺金则咳呛，金破不鸣则音嘶。脉数示火势未平，肺虚而火旺，木火刑金，故法当平木清金，泻肝火以保肺金。", ["数"]], "2373": ["病机", "脉细数，细主阴血亏虚，数主虚火内扰。久咳肺阴延虚，音嘶气粗气促，肺阴亏耗则金破不鸣而音嘶，阴虚不能纳气则气促。细数为阴虚火旺之典型脉象，示肺阴亏虚、虚火内炽之病机，故宜怡养。", ["细", "数"]], "2374": ["病机", "脉右数，右寸候肺，数主火旺。久咳不已，肺虚火旺，久咳伤肺，肺虚而火旺，火灼肺金则咳不止。脉数示火势未敛，病位在肺，肺虚为本、火旺为标，故以西昌法清金保肺、养阴降火。", ["数"]], "2375": ["病机", "脉右数，右寸候肺，数主火热。痰火留肺，肺气𪱥郁，音嘶咳逆，痰火壅肺则气郁，金实不鸣则音嘶。脉数示痰火内盛，病位在肺，痰火留滞为病机关键，故以西昌法清化痰火、宣畅肺气。", ["数"]], "2376": ["病机", "脉右滑数，右脉候肺，滑主痰，数主火，痰火交阻于肺，肺气𪱥郁，故音嘶咳逆。滑数并见，说明痰火内盛，肺失清肃，开上之法正为宣肺化痰清火而设。", ["滑", "数"]], "2377": ["病机", "脉沉小弦，沉主里，小主气虚，弦主饮逆。痰火内蒙，肺气𪱥郁，气机不得宣降，故哮嗽气促。沉小弦反映痰火郁闭于里，肺气不降，法当降肺气以清痰火。", ["沉", "小", "弦"]], "2378": ["病机", "脉沉弦，沉主里主水，弦主饮主痛。脾肺气虚，痰饮偏胜，下气上逆，动辄气促，乃饮邪内停、气机上逆之象。沉弦为痰饮内伏之脉，故以《金匮》方温化降逆。", ["沉", "弦"]], "2379": ["兼症", "脉仍沉弦，下气上逆、痰饮偏胜未减，又见自汗盗汗、胃钝纳、力懈，乃脾肺气虚、饮邪内停兼表虚不固。沉弦主饮停气逆，兼症虽多，病机仍属痰饮偏胜，故宗原议。", ["沉", "弦"]], "2380": ["病机", "脉沉弦，沉主里，弦主饮。中阳不足，湿邪挟饮为患，饮邪上逆则哮嗽气促。沉弦正是阳虚饮停、气机不利之脉，故以《金匮》方温阳化饮、降逆平喘。", ["沉", "弦"]], "2381": ["病机", "脉沉弦，沉主里主水，弦主饮。脾肺气虚，痰饮偏胜，饮邪上逆则咳呛气粗。沉弦为饮停气逆之征，说明病本在脾肺气虚、痰饮内伏，故以《金匮》方化饮降气。", ["沉", "弦"]], "2382": ["预后", "投《金匮》方后痰饮较平，而脉仍沉弦，说明饮邪虽减未净，病根未除。沉弦脉持续，提示痰饮内伏、气机未复，故再宗原议增删，继续温化降逆以巩固疗效。", ["沉", "弦"]], "2383": ["病机", "脉沉弦，沉主里，弦主饮。脾肺气虚，痰饮偏胜，饮邪内停、气机不利，故脉见沉弦。此脉象紧扣脾肺气虚、痰饮偏胜之病机，以《金匮》方温化饮邪、健脾益肺为治。", ["沉", "弦"]], "2384": ["病机", "脉濡弦者，濡主湿、主阳虚，弦主饮、主气机不达。原文谓「阳虚饮聚，湿留不澈，癣疥丛生」，阳虚不能化饮，湿浊留恋肌肤，故脉见濡弦。濡为湿困、弦为饮聚，合而示本虚标实、湿饮内蕴之机，与癣疥丛生之外症相应，故以补气逐湿为治。", ["濡", "弦"]], "2385": ["病机", "脉沉弦，沉主里、主水饮，弦主饮、主痛、主气机郁滞。原文谓「中阳不足，饮痰瘀聚」，中阳不振则饮停痰聚，痰瘀互结，气机不畅，故脉沉弦。咳呛气促、动则眩旋、睡中惊惕，皆饮痰上扰、阳气不布之候，舌黄腻更示饮郁化热，故以《金匮》方温阳化饮。", ["沉", "弦"]], "2386": ["病机", "脉沉弦小滑，沉主里、弦主饮、小示正气不足、滑主痰。原文谓「外感风寒，引动宿饮」，外寒引动内伏痰饮，饮邪上逆则哮嗽气促；身热口渴、舌白腻为寒束热郁、饮停之象。脉沉弦小滑正合宿饮内伏、外寒触发之机，故法当降气涤痰，并防喘汗脱变。", ["沉", "弦", "小", "滑"]], "2387": ["病机", "脉濡弦，濡主湿、主阳虚，弦主饮。原文谓「嗜酒伤阳，阳虚饮聚」，酒湿伤脾阳，阳不化饮，饮聚上逆则咳呛痰稠，神疲纳懈为阳虚湿困之征。濡弦并见，示湿饮内停而阳气不足，本虚标实，故以桑麻温胆化饮和阳，脉象与阳虚饮聚之机相合。", ["濡", "弦"]], "2388": ["病机", "脉沉弦，沉主里、弦主饮主气郁。原文谓「中阳不足，痰饮内凝」，投温胆汤眩旋稍减而脉仍沉弦，示饮邪未化、阳未复振。曾经失血，阴血已亏，痰饮上蒙、阳气不升，故防厥冒之变。沉弦在此明饮凝于里、气机不畅之病机，与眩旋、失血后防厥冒相应。", ["沉", "弦"]], "2389": ["病机", "脉弦数，弦主风、主肝，数主热。原文谓「风温外袭，肺胃先受」，风温之邪化热，热盛则脉数，风动则脉弦。咳呛痰音、颧红目赤、头疼气粗，皆风温袭肺胃、热邪上炎之候。弦数并见，示风热炽盛、有外发风痧之势，故防发风痧而以辛散法透邪外出。", ["弦", "数"]], "2390": ["病机", "脉右沉弦小滑，右关带数。沉主里、弦主饮、小示正虚、滑主痰，右关候脾胃。原文谓「劳倦阳弛，温邪乘袭，酿痰化热，引动素胜痰饮上泛」，痰热蒙蔽清窍则神识乍清乍糊，肺胃失宣则痰多纳微。脉象示痰饮内伏、温邪引动、正虚邪实之机，故治当宣肺涤痰、宁神清窍，防昏喘。", ["沉", "弦", "小", "滑"]], "2391": ["病机", "脉弦滑数，弦主风热、滑主痰、数主热。原文谓「风温郁肺，肺气失降」，风温化热酿痰，痰热壅肺则身热烦疼、咳嗽咽痛、痰出不爽；舌苔黄糙且腻，示痰热内蕴。弦滑数并见，明风温痰热交炽之机，热势有由气入营之势，故恐昏愦堪虞。", ["弦", "滑", "数"]], "2392": ["病机", "脉弦数，弦主肝风，数主热盛。风温外袭，由肺卫逆入心肝，热盛动风，故见肢厥目直、形同痉厥；咳呛痰鸣、气促壮热，为肺风痰喘之象。脉弦数反映热邪炽盛、肝风内动之病机，属肺风痰喘险候，防喘厥变幻。", ["弦", "数"]], "2393": ["病机", "脉沉弦略起，沉主里，弦主肝。昨投犀角地黄汤清营分之邪后，神识渐清、呕吐已止，但便溏未已、舌绛尖刺，脉沉弦略起，说明营分邪热渐退，肝经郁热未清，局势初定，仍需徐图转环。", ["沉", "弦"]], "2394": ["病机", "脉细弦小数，细主阴伤，弦主肝郁，小为细之甚，数主热。劳倦挟感，阴分延虚，邪未尽彻，故见寒热如疟、咳呛纯热、烦渴恣饮、神糊舌糙尖绛。脉细弦小数反映正气先虚、邪热未清、痰火内恋之病机，亟需养阴泄热兼清痰火，防热极生风。", ["细", "弦", "小", "数"]], "2395": ["病机", "脉弦数，弦主肝，数主热。劳倦风温乘袭，肺胃先受，壮热神糊、咳呛痰少、肋疼气阻、舌糙尖绛，为风温化热、肺胃热盛、肝风内动之象。脉弦数说明热邪炽盛、肝风欲动之病机，治当清解。", ["弦", "数"]], "2396": ["病机", "脉右数，右候肺，数主热。外感风寒，肺胃先受，形寒身热、咳呛有痰，为风寒束表、肺气失宣、郁而化热之象。脉右数反映肺胃热郁之病机，治当清解上焦。", ["数"]], "2397": ["病机", "脉小数，小主阴伤，数主热。春温化热酿痰，肺胃失宣，咳逆引痛、胸脘懊𢙐、苔黄腻，为痰热内蕴、肺胃气壅之象。脉小数说明热郁痰凝、阴分渐伤之病机，再以清泄上焦。", ["小", "数"]], "2398": ["病机", "脉仍小弦，小主阴伤，弦主肝郁。三诊后诸恙愈而咳逆引痛依然，胸脘懊𢙐渐平，舌苔黄腻，脉仍小弦，说明痰热渐化而肝肺气郁未舒、阴分未复之病机，治法仍踵原议增删。", ["小", "弦"]], "2399": ["病机", "脉右小弦而数，右候肺，小主阴伤，弦主肝郁，数主热。素嗜茶酒，聚湿成饮，湿蒸热郁，灼伤阳络，肝之左升太过，肺之右降不及，木火刑金，故咯血咳呛、痰热胶固、神识昏糊。脉右小弦而数反映肝肺郁热、痰火内闭之病机。", ["小", "弦", "数"]], "2400": ["病机", "脉右数，右脉候肺，数主热。风温外袭，肺胃先受，热邪内郁，故脉数。身热、咳呛等症相应，法当宣上，以解肺胃风热。", ["数"]], "2401": ["病机", "脉右弦数，弦主风，数主热。风温外泄，肺胃受邪，风热相搏，故脉弦数。咳呛身热，治当清解肺胃。", ["弦", "数"]], "2402": ["病机", "脉弦数，弦为风，数为热。风寒外袭，肺胃先受，身热形寒，风寒束表，郁而化热，故脉弦数。治以辛散，解表散寒。", ["弦", "数"]], "2403": ["病机", "脉右数，右候肺胃，数主热。风温挟湿，上犯肺胃，热邪偏盛，故脉数。咳呛头疼，身热鼻衄，舌糙，皆热伤肺胃之象，法当清解。", ["数"]], "2404": ["病机", "脉右细数，细主阴伤，数主热。风寒外袭，食滞内停，郁而化热，热灼阴津，故脉细数。呕吐身热，咳呛痰音，舌糙尖刺，治先开泄。", ["细", "数"]], "2405": ["病机", "脉弦数，弦主痰饮，数主热。痰热内蒙，肺胃受灼，热盛痰壅，故脉弦数。脘闷气逆壮热，开呛出痰乃吉，治以清解痰热。", ["弦", "数"]], "2406": ["预后", "脉滑数，滑主湿痰，数主热。湿温复感，热势转剧，湿热酿痰，故脉滑数。热盛痰蒙，尚虑昏愦，当防邪陷心包。", ["滑", "数"]], "2407": ["预后", "脉弦滑大，弦主痰热，滑主湿痰，大主热盛。劳倦湿温酿痰热，化热灼伤阳络，壮热鼻衄，咳逆无痰，胁肋抽痛，有时神糊，舌尖绛苔糙，局势非轻，尚防昏愦入营。", ["弦", "滑", "大"]], "2408": ["病机", "脉弦小滑，弦主邪郁气分，小示阴分已伤，滑为痰热内蕴。潮热起伏、汗出不衰是邪恋气分；神识乍糊、痰出不多、便秘溲赤、舌尖绛糙罩灰，为痰热蒙窍、津伤化燥之象。脉小而不洪，说明正虚不能托邪，故以甘凉清养，非单纯攻邪可解。", ["弦", "小", "滑"]], "2409": ["病机", "脉弦数，弦为邪郁气分、枢机不利，数为热盛。湿温一候，欲疟不达，身热有汗，少寐拒纳，舌黄腻，是湿热留恋气分、欲从少阳外达而不得。脉弦数正应邪郁化热之势，故法当轻清透达，使邪从气分外解，而非苦寒直折。", ["弦", "数"]], "2410": ["病机", "脉弦数，弦主邪郁、数主热盛。湿温挟食滞，乘劳倦而发，壮热汗少，脘格呕吐，舌黄糙，是湿热与食滞互结中焦、胃气上逆。脉弦数反映邪热郁遏、枢机不利。原文谓「成疟乃吉」，即邪能外达为顺，故尚防昏重，恐邪内陷心营。", ["弦", "数"]], "2411": ["病机", "脉弦数，弦为邪郁气分、枢机不畅，数为热邪内盛。劳倦湿温乘袭，欲疟不达，说明正气因劳倦而虚，邪留气分不能外透。脉见弦数而非虚软，示邪热仍盛、郁而未达。原文「防转重」，即恐邪郁日久内陷，故以脉测病机之进退。", ["弦", "数"]], "2412": ["病机", "脉小弦滑数，小为阴虚正虚，弦为邪郁，滑数为痰热内盛。湿温三候，白㾦空壳无神、舌光绛无苔，是阴液亏耗；喉间痰音漉漉、神识模糊，为痰热蒙窍。脉小示正虚不能载邪外达，弦滑数示痰热仍炽，故有热极生风、痉厥变幻之险。", ["小", "弦", "滑", "数"]], "2413": ["病机", "脉弦数，弦主邪郁气分，数主热盛。湿温旬余，从气分外泄为㾦，壮热烦渴，舌糙，是湿热久留气分、化燥伤津，邪欲外透而未彻。脉弦数应邪热郁蒸之势，故治以甘凉，清养气分津液，助邪外达而不伤正。", ["弦", "数"]], "2414": ["病机", "脉沉弦，沉主病在里，弦主饮邪内结、气机不畅。劳倦湿温乘袭，饮邪泛滥，蒙蔽清窍，神识气促，是饮邪内盛、上蒙心肺。脉沉弦正合饮停于里、气机郁滞之机。原文「防喘变」，即恐饮邪上逆迫肺，故脉沉弦为饮邪内伏之征。", ["沉", "弦"]], "2415": ["病机", "右部滑大，滑主痰热，大示邪盛；左寸关弦数，弦为风动，数为热盛。湿温酿痰化热，蒙蔽清窍，目直、妄笑撮空、谵语，是痰热内陷心营、肝风欲动。脉证合参，滑大弦数并见，示痰热风火交炽，故有风动闭厥之险，治以芳香宣窍、甘寒存津。", ["滑", "大", "弦", "数"]], "2416": ["病机", "右脉滑大，滑主痰热内盛，大示邪势鸱张；左部弦数，弦为风阳旋动，数为热邪燎原。痰热蒙蔽机窍故神识渐清而未澈、寤难成寐；阳易上浮、口渴恣饮、但热不寒，皆阴气先伤而阳邪独发之象，形同瘅疟。花甲高年阴液本亏，脉象与舌绛苔糜相参，示痰热未化、风阳未潜，故虽逾险岭而未入坦途。", ["滑", "大", "弦", "数"]], "2417": ["病机", "脉弦数左大，弦为风木鸱张，数为邪火燎原，左大乃肝阳旋动之征。湿温化热酿痰，由肺卫逆入心肝，机窍被蒙则语言蹇涩、神识昏糊；风阳旋动则惊惕瘛疭、手肢蠕动、妄言骂詈。齿板唇焦、舌苔燥黑无津，阴液已伤而邪火独炽，脉象与症相符，故有闭痉暴变、癫痫纠缠之虞。", ["弦", "数", "大"]], "2418": ["病机", "脉沉弦，轻取虚细而数，沉主邪入阴分，弦为风阳旋动，虚细数则阴液大伤、正气不支。湿温酿痰化热，由阳明逆犯厥阴，机窍被蒙故神识昏糊、语言蹇涩；风阳旋动故筋抽颧赤。舌绛剥苔花、白㾦虽露而邪未解，脉象虚细数正合阴液大伤之势，故断为势涉危途、行将痉闭。", ["沉", "弦", "虚", "细"]], "2419": ["病机", "脉右弦数未静，右主气分阳明，弦为热郁痰凝，数为邪热未清。湿温类伤寒阳明证，潮热两候、汗出不多、大便先溏后结、脘闷气粗、舌尖绛苔灰，皆阳明热郁、痰湿未化之候。脉象弦数未静，说明邪热尚在气分而未解，故治以甘凉清泄，徐图恢复，不可骤补。", ["弦", "数"]], "2420": ["病机", "脉细为阴血不足、络脉失养之征。春湿上袭，热迫大肠，灼伤阴络，故咳呛而便血；舌糙亦示津液受灼。热伤阴络则血溢，阴血耗损则脉道不充而见细。此脉细与咳呛便血相应，说明热邪虽在气分而阴络已伤，法当清泄，清其热则络自安。", ["细"]], "2421": ["病机", "脉细滑，细为津液被劫、正气不足，滑主痰热内蕴。劳倦阳弛，痰热乘发，症势虽属转机，然津液已伤，未足全恃。脉细而不洪，知非实热鸱张；脉滑而不涩，知痰热尚恋。苔薄亦示邪未深入。此脉象说明痰热未清而津液已亏，故仿痰门之法，涤痰之中须顾其津。", ["细", "滑"]], "2422": ["病机", "脉右滑数，右候肺卫上焦，滑主痰涎壅盛，数主热邪内迫。风温外袭，上焦先受，故咳呛、痰稠、喉痛音嘶，皆痰热壅阻肺系之象。脉滑数而见于右部，正合风温痰热在肺卫之病机，故治宜清肃肺金，使痰热得清则咳呛喉痛自减。", ["滑", "数"]], "2423": ["病机", "脉弦滑，弦为热郁风动，滑主痰湿内盛。湿温旬余，热迫便泄，邪未尽解而痰热内恋，脉象弦滑示风阳有旋动之势、痰浊有蒙蔽之机。便泄虽为热迫下行，然脉不见缓静，故防昏重，即防痰热上蒙心窍而致神识昏糊，与后文痉闭之变相呼应。", ["弦", "滑"]], "2424": ["病机", "脉弦滑左甚，弦主肝木偏旺，滑主痰湿内蕴。左脉候肝，左甚则肝旺尤著。原文谓“木旺而金郁失宣”，肝木亢盛反侮肺金，肺失宣降，故见便闭、痰音、热炽于里。此脉象揭示湿温挟食滞，表里虽通而里热痰闭，肝肺同病之机。", ["弦", "滑"]], "2425": ["预后", "脉弦数，弦主邪郁少阳或肝经，数主热盛。湿温㾦后热恋不澈，痞聚肢肿腹膨，神识昏糊，耳聋鼻衄，皆热邪内陷、痰瘀互结之象。脉弦数示邪热未清而肝风内动，故原文断“恐病伤不复”，预后堪忧。", ["弦", "数"]], "2426": ["病机", "脉弦滑数，弦主伏暑郁遏少阳，滑主痰湿内蕴，数主热邪亢盛。寒微热甚、汗出不多、脘闷便结、少寐烦渴、舌尖绛苔白糙，皆暑热内伏、痰湿阻滞之候。原文谓“成疟乃佳，否防发㾦神糊”，脉象示邪有外达之机，否则内陷心包。", ["弦", "滑", "数"]], "2427": ["预后", "脉弦数，弦主肝经郁热，数主热盛。湿温化热酿痰，络道失宣，故咳呛肋痛、夜寐不安、口渴气粗。痰热阻络，肝肺同病，脉弦数示邪热鸱张。原文“尚防昏重”，谓痰热有内蒙心包之势，预后须慎。", ["弦", "数"]], "2428": ["病机", "脉弦数，弦主络道拘急，数主热邪内盛。素有湿热，复感秋温，酿痰化热，阻痹络道，故咳逆无痰、脘肋抽疼、身热形寒、舌黄。脉弦数正合痰热阻络、肝肺气机不畅之机，故以通络导痰为法。", ["弦", "数"]], "2429": ["病机", "脉弦滑数，弦主肝郁络阻，滑主痰湿，数主热盛。二诊热势依然，痰蒙络道，咳逆抽疼、脘闷泛呕、肢酸头痛、夜少安寐、舌黄糙，皆痰热内郁、络道不通之象。原文谓“湿郁化热酿痰”，脉象示痰热胶结，故以开呛出痰为上。", ["弦", "滑", "数"]], "2430": ["病机", "脉濡滑数，濡主湿邪内蕴，滑主痰浊，数主热盛。秋温外袭，伏湿内蕴，两邪并发，湿温化热酿痰，阻痹络隧，阳明失通降，故身热不衰、胸痹呕恶、咳痰难爽、两肋引痛、舌黄根腻。脉象示湿痰热交阻，亟须宣上豁痰。", ["濡", "滑", "数"]], "2431": ["预后", "脉弦滑，弦主肝络郁滞，滑主痰热内蕴。湿温痰热阻蔽络隧，肺卫失宣，发热肋疼，深夜神昏，大便未通，腑阳失旷。脉弦滑示痰热胶结、邪渐逼近心胞，故原文“预防喘厥”，宜宣络导痰以杜内陷。", ["弦", "滑"]], "2432": ["病机", "脉弦滑且数，弦主肝郁，滑主痰湿，数主热，合而示湿痰阻络、肺胃宣降失司，痰热内蕴。肋痛虽衰而出痰未爽、泛呕胸痹、大便欠通，皆痰湿阻络、腑气不通之症，脉症相符，故仍宜宣泄上焦、佐以通腑。", ["弦", "滑", "数"]], "2433": ["病机", "脉弦滑而数，弦为肝火，滑为痰浊，数为热盛，示肝火挟痰入络、络瘀阻蔽。肋痛乍剧乍轻、倏寒倏热，乃痰火瘀阻络脉、正邪交争之象，脉症合参，故亟以通络导痰、平肝逐瘀为治。", ["弦", "滑", "数"]], "2434": ["病机", "脉小滑而数，小为阴伤，滑为痰，数为热，示肝火挟痰扰络、络瘀风胜。肋痛减而未止、呼吸辗转尤剧、抽掣口渴、内热神烦，皆痰火内扰、风动伤津之症，脉小数示阴液已伤，故防痉厥。", ["小", "滑", "数"]], "2435": ["病机", "脉象滑数且弦，滑主痰浊，数主热，弦主肝风，示风火较平而浊痰未出、伏邪犹盛。热势退而痛势亦缓，然舌苔糙黄而燥，阴液渐伤，脉仍滑数且弦，说明痰热未清、伏邪内蕴，故须防今夜反复。", ["滑", "数", "弦"]], "2436": ["预后", "右脉参伍不调，为脉律不整、胃气衰败之象，结合精神大惫、舌将起腐、苔尚糙黄，示肝火挟痰入络、内风焮旋而正气已溃。抽掣瘛疭、寤则惊惕乃风动之症，脉症俱逆，故断形势险恶、厥脱堪虞，勉以甘寒治风。", []], "2437": ["病机", "右脉数大而滑，数为热盛，大为阳明火炽，滑为痰浊，示阳明燎原不熄、痰热内盛。抽掣瘛疭较减而内热神迷，脉仍数大而滑，说明液涸风升尚在险途，故仍以甘凉为主清阳明痰火。", ["数", "大", "滑"]], "2438": ["预后", "脉滑数促，滑主痰，数主热，促为热盛气促、脉行急迫，示伏邪晚发、热伤津液、肝风鸱张。痉厥、神志时清时昏、胸闷气逆、苔黄尖绛，皆痰热内闭、风动液涸之症，脉促示正气不支，故防昏喘，势颇危险。", ["滑", "数", "促"]], "2439": ["病机", "右脉浮滑而数，浮主邪在表分，滑主痰，数主热，示伏暑晚发、酿痰化热、蒙蔽肺胃。白㾦叠见而汗出不多，阵咳出痰稠韧、形瘦里热、夜不安寐、苔黄糙尖绛，皆痰热壅肺胃之症，故仿喻氏法清上焦痰火，防喘汗变幻。", ["浮", "滑", "数"]], "2440": ["预后", "脉细而沉，细为精气内夺，沉为邪陷于里。案中神呆目定、喘促痰潮、循衣摸床、语言昏乱，皆精气俱伤、痰饮上蒙包络、肝风升动之象。脉证相参，正虚邪陷，脱象渐萌，故曰恐难挽治。", ["细", "沉"]], "2441": ["病机", "脉弦滑大，弦主伏邪郁遏膜原，滑主痰湿内蕴，大主热势鸱张。案中壮热不解、汗出不衰、烦渴恣饮、舌干糙少津，皆伏暑由膜原转出气分、邪热充斥之征。脉象与白㾦微露相应，示邪有外达之机。", ["弦", "滑", "大"]], "2442": ["病机", "脉弦滑大，弦为肝风，滑为痰浊，大为热盛。案中秋温化热，酿痰阻痹络道，故咳呛肋痛、壮热有汗；舌糙亦热灼津伤之征。脉象反映痰热内壅、络道不通之病机，故法当通络导痰。", ["弦", "滑", "大"]], "2443": ["预后", "脉濡涩不固，濡为正气不足，涩为邪滞血行不畅。案中伏暑晚发，邪由气入营，神昏谵语、妄笑搓空、舌干灰尖绛，而脉反濡涩不固，是正不敌邪、邪陷不宣之象。故断为内闭外脱之险，预后堪忧。", ["濡", "涩"]], "2444": ["病机", "脉弦滑，弦主风动，滑主痰盛。案中冬温化热，酿痰蒙蔽清窍，脉象恰示痰热生风、上扰清窍之机。原文谓“尚防昏愦”，正是痰蒙清窍、神明内乱之先兆，故当预为防范。", ["弦", "滑"]], "2445": ["病机", "脉滑数，滑主痰浊，数主热盛。案中冬温化热，酿痰阻于络道，肺失宣降，故咳呛肋痛。脉象直接反映痰热内蕴之病机，故治当清肺胃痰热，使痰热去则络道自宣。", ["滑", "数"]], "2446": ["预后", "脉濡弦，濡为湿郁不化，弦为邪伏少阳。案中秋温伏暑，郁遏不达，形寒壮热、汗出神糊、热迫便泄，脉象示邪踞膜原、正邪交争。原文谓“成疟乃吉”，因疟则邪有外达之机，故以转疟为顺。", ["濡", "弦"]], "2447": ["病机", "脉右数左弦，右数主气分热盛，左弦主肝风内动。案中病后余烬复燃，目直耳聋、神糊谵语、舌白糙尖绛，皆心肝神魂不藏、风热内扰之象。脉象示风热鸱张，故论治首先熄风，最防厥变。", ["数", "弦"]], "2448": ["病机", "脉弦滑数，弦主肝胆郁热，滑主痰湿内蕴，数主热盛。面黄未退而热势转剧，寒热三次、口渴恣饮、舌黄罩灰，皆湿热痰浊交蒸之象。脉数示热邪鸱张，滑为痰湿未化，弦乃木火偏亢，故防昏重，即热陷心包、痰蒙清窍之变。", ["弦", "滑", "数"]], "2449": ["病机", "脉右弦，右关候脾胃，弦为肝木之脉。原文谓「肝强犯胃，营卫不和」，肝气横逆乘脾犯胃，胃失和降则营卫化生失调。弦脉主痛、主气机郁滞，木旺克土，胃气受戕，故防厥脱，乃肝阳暴亢、胃气衰败、阴阳不相顺接之危候。", ["弦"]], "2450": ["病机", "脉弦数，弦主肝胆，数主热。风温外袭，身热鼻衄，热伤阳络则血上溢；少腹拒按、呕吐瘀沫，为热与瘀结于下焦小肠。弦数并见，示风温化热入里，肝胆火炽，瘀热互结，故原文断为「小肠症非轻小」，防热瘀内陷生变。", ["弦", "数"]], "2451": ["病机", "脉右弦滑，右候脾胃，弦主肝风，滑主痰浊。夙患肿胀，脾运本弱，外风引动内风，风痰上扰则神识昏迷、半身不活动。弦为肝阳化风，滑为痰湿内盛，风痰闭阻清窍经络，故防闭脱，即痰蒙心包之闭与正气外脱之脱。", ["弦", "滑"]], "2452": ["病机", "脉右小滑而濡，小为正气不足，滑为痰火未净，濡主湿浊留恋。神识渐清、手足渐仁，是痰火渐退之征；然精衰视异、苔黄厚腻，示痰火尚蒙心肝，正气已伤而余邪未清。小濡并见，正虚湿滞，故再以芳香宣豁佐熄肝阳，以图转机。", ["小", "滑", "濡"]], "2453": ["病机", "脉濡弦，濡主湿，弦主肝。痰火渐平、神识已清，而素有伏湿流入太阴，目窠浮肿渐及一身、便溏脘闷，皆脾虚湿盛之象。濡为湿邪黏滞，弦为木旺乘土，湿困脾运，水气泛溢，故原文谓「势颇纠缠，恐成肿胀」，防湿胜成水胀。", ["濡", "弦"]], "2454": ["病机", "脉弦滑，弦主热郁肝胆，滑主痰湿。白㾦微露，是邪从气分外泄之佳象；纯热不凉、舌糙，示里热尚炽。弦滑并见，为气分痰热内蕴、邪有外透之势，故治以甘凉，清透气分邪热，使白㾦畅达而热退。", ["弦", "滑"]], "2455": ["病机", "脉弦数，弦主气机郁滞，数主热盛。白㾦微露，邪从气分外泄，本为佳兆；然脉弦数，示里热仍炽、气分郁热未清。弦为热郁肝胆，数为邪热鸱张，故治以甘凉，清解气分邪热，助白㾦透发而防热邪内陷。", ["弦", "数"]], "2456": ["病机", "脉弦数大，弦主肝胆，数主热盛，大主邪实。暑温之邪由气入营，又转出气分，红白痦遍体沛露，热势反剧，神识乍清乍糊，烦闷口渴，此温邪散漫无序，充斥表里，脉象反映邪热炽盛、正气尚能抗邪，但弦大数之脉提示热势鸱张，有内陷昏愦之虞。", ["弦", "数", "大"]], "2457": ["病机", "脉左弦、右部滑数，左弦主肝胆邪热，右滑数主气分湿热未清。暑必夹湿，自呼吸而入气分不解，渐传营分，邪灼肝胆则神糊谵语，红白㾦沛露，溲赤便难，舌白苔糙边绛尖刺。昨投清营泄热，神识渐清，脉证相参，营分邪热尚未清澈，弦滑数脉正是湿热内蕴、肝胆火旺之征。", ["弦", "滑", "数"]], "2458": ["病机", "脉右部弦滑，左寸关带数，右弦滑主阳明痰热内结，左寸关数主厥阴气火升腾。暑湿症经两候，热恋便结，烦渴呕逆，脘格不舒，寤寐欠安，舌糙边绛，种种见证属阴伤热恋、阳明不司通降，厥阴气火上升。脉象揭示正不胜邪，肝胃同病，有呃脱变端之虑。", ["弦", "滑", "数"]], "2459": ["预后", "脉弦小数，弦主肝厥，小主阴伤，数主热炽。㾦点密布枯暗无神，鼻衄神糊，肝厥汗出，舌干唇焦，病在营阴，热灼阴伤，肝风内动。弦小数为阴亏热盛、正虚邪陷之象，最防厥脱，故曰病在营阴，最防厥脱，脉象已露危候。", ["弦", "小", "数"]], "2460": ["治法", "脉弦数，弦主少阳膜原，数主暑热。疟发不畅，暑邪从膜原转出气分，白㾦微露，头疼泛呕，舌黄，此邪郁少阳阳明，热势未透。脉弦数示邪热内蕴，法当清透，使邪从气分外达，白㾦透发则病解。", ["弦", "数"]], "2461": ["病机", "脉弦，弦主少阳胆经，亦主湿郁。疟发不畅，湿留胆胃，舌糙，脉弦，此湿浊内阻，胆胃不和，邪未透达。防转出气分，发为白㾦，脉弦提示湿郁气分，有外透之势，当因势利导。", ["弦"]], "2462": ["预后", "脉弦滑数，弦主暑邪膜原，滑主痰湿，数主热盛。暑邪由膜原转出气分，先疟后㾦已旬余，热迫便泻，神糊气粗，舌尖绛苔糙，此邪热炽盛，气营两燔，痰湿内蕴。脉弦滑数示邪势鸱张，局势未定，有内陷厥脱之变。", ["弦", "滑", "数"]], "2463": ["病机", "脉弦而数，弦主肝胆，数主热盛。毒㾦密如蚕种，热迫便溏，病经两候，热势稍退而便泻不已，神疲气粗，舌尖绛苔糙，此病在气营，热邪未清，正气已伤。脉弦数示邪热仍炽，当再凉解，局势非轻，须防正虚邪陷。", ["弦", "数"]], "2464": ["病机", "脉小弦而数，小为气阴耗伤，弦主邪郁少阳或湿遏气机，数示温毒化热内迫。原文暑湿夹温毒从气分外泄为㾦，热迫便泻、火升喉腐、舌尖绛，皆热盛伤津、邪欲入营之象；脉小数弦正合温邪由气入营、正气渐伤之机，故虑昏愦。", ["小", "弦", "数"]], "2465": ["病机", "脉弦滑，弦主伏暑痰热郁阻气分，滑为痰湿内盛、热蒸津液。原文痰留热恋、汗出不衰、舌灰、㾦现不多，说明暑湿伏于气分，痰热胶结不解，邪未透达；望六之年正气渐衰，脉见弦滑而病势缠绵，故复元不易。", ["弦", "滑"]], "2466": ["病机", "脉弦而数，弦主伏暑郁于少阳枢机，数示热邪内盛。原文伏暑晚发两旬、白㾦层出颇密、潮热起伏、汗出不衰、舌绛苔糜，皆暑热留恋气营、邪正交争之候；脉弦数正应热郁未清、营分受灼，故以参白虎清透气营。", ["弦", "数"]], "2467": ["病机", "脉弦数疾，弦主邪郁营阴，数疾为热极内燔、阴液受灼。原文先厥后热、昏狂谵语、唇焦齿黑、彻夜不寐、无汗肢厥、苔浮中剥，皆热陷营阴、内闭心包之危候；白㾦虽露而营邪郁遏不宣，脉数疾示热势鸱张，故有闭厥之虞。", ["弦", "数", "疾"]], "2468": ["病机", "脉弦小数，弦主余邪郁于气营，小为阴液已伤，数示余热未清。原文红疹白㾦遍体密布、神识乍清乍糊、咳呛有痰、胁肋引痛、舌黄糙罩灰尖绛，皆邪热留恋营分、痰热阻络之象；脉小弦数正合正虚邪恋、局势未定之机，故尚在险途。", ["弦", "小", "数"]], "2469": ["病机", "脉小弦，小为气阴不足、脉道不充，弦主病后余邪郁滞或筋脉失养。原文病后气阴未复、周以窒碍、腿麻肢酸，皆气阴亏虚、络脉不畅之候；脉小弦正应正虚未复而余滞未清，故冬藏投以滋补，以复气阴、柔筋通络。", ["小", "弦"]], "2470": ["病机", "脉弦数，弦主风湿窜经入络、邪郁不解，数示热邪内盛。原文左半身酸痛麻木、腿膝漫肿红痛、遍体发斑、白㾦隐约、舌黄腻，皆风湿化热、邪在气营、络脉壅滞之象；脉弦数正合邪热郁于气营，故尚防昏变。", ["弦", "数"]], "2471": ["病机", "脉小数，小为肺胃津伤、脉道不充，数示风燥化热、邪热偏盛。原文风燥上凌、肺胃先受、舌黄糙，皆燥热伤津、肺胃失润之候；脉小数正应燥热内郁而津液渐伤，故治以宣泄，透邪润燥。", ["小", "数"]], "2472": ["病机", "脉濡弦，濡主湿，弦主痛、主饮，亦主少阳。原文“感寒著湿，阳明受困”，湿邪困阻阳明，气机不畅，故脉见濡弦。形寒身热、舌黄，为湿郁化热之象。此脉主湿著阳明、气机郁滞之病机，与寒热、舌黄等症相应。", ["濡", "弦"]], "2473": ["病机", "脉弦小数，弦主疟、主痛，小为湿滞，数为热。原文“著寒停食从膜原外腾为疟”，寒食滞于膜原，邪正交争，故寒少热甚、汗出不爽；腹痛拒按为食滞内阻。脉弦小数主疟邪内郁、食滞化热之病机，与寒热、腹痛拒按相应。", ["弦", "小", "数"]], "2474": ["病机", "脉濡弦，濡主湿，弦主疟、主少阳。原文“疟发不畅，湿留胆胃”，湿邪留恋胆胃，枢机不利，疟发不畅，故脉见濡弦。此脉主湿留胆胃、少阳枢机不利之病机，与疟发不畅之症相应，法当和解。", ["濡", "弦"]], "2475": ["病机", "脉濡弦，濡主湿，弦主疟、主少阳。原文“复方疟湿渐化，胃气似有来复之机”，湿邪渐化而未尽，胃气初复，故脉仍见濡弦。此脉主湿邪未净、胃气渐复之病机，与疟湿渐化、胃气来复之症相应，仍以清渗。", ["濡", "弦"]], "2476": ["病机", "脉濡弦，濡主湿，弦主风、主疟。原文“风寒外袭，寒热如疟，肢酸头疼”，风寒外袭，湿邪内著，营卫不和，故寒热如疟、肢酸头疼。脉濡弦主风寒外袭、湿著三焦之病机，与寒热、肢酸头疼相应。", ["濡", "弦"]], "2477": ["病机", "脉濡弦，濡主湿，弦主疟、主少阳。原文“湿著胆胃，疟发连枝，汗出不多”，湿邪著于胆胃，枢机不利，疟发连枝，汗出不多。脉濡弦主湿著胆胃、疟邪留恋之病机，与疟发连枝、汗出不多相应，当达成正疟乃吉。", ["濡", "弦"]], "2478": ["病机", "脉濡弦，濡主湿，弦主气机郁滞。原文“湿著不化，阳明通降失司”，湿邪著而不化，阳明通降失常，气机壅滞，故脉见濡弦。此脉主湿著阳明、通降失司之病机，与湿著不化之症相应，法以清渗。", ["濡", "弦"]], "2479": ["病机", "脉小弦，小主食滞、正气不足，弦主痛、主疟。原文“过食发气，寒热如疟，热甚神烦，胃钝妨食，舌糙苔黄”，过食伤胃，食滞化热，气机不畅，故脉见小弦。此脉主食滞化热、胃气不和之病机，与寒热、神烦、妨食、苔黄相应。", ["小", "弦"]], "2480": ["病机", "脉濡主湿，弦主气机不畅。本案感寒引动伏湿，湿性黏滞，寒邪外束，致脉道濡软而兼弦象。濡弦并见，说明外寒与内湿相合，湿阻气机，三焦不利。故以河间三焦分理法，分消湿浊，宣通阳气。", ["濡", "弦"]], "2481": ["病机", "疟久阴伤，营卫迭偏，脉弦数。弦为疟邪未净、气机不和，数为阴伤内热。身热鼻衄、舌黄腻，皆阴亏热扰、营卫失调之象。劳倦则寒热自作，正虚邪恋。法当养阴泄热，兼和营卫，使阴复热退，营卫调和。", ["弦", "数"]], "2482": ["病机", "脾胃湿疟，脉弦数。弦主湿阻气滞、疟邪在经，数主湿热内蕴。发必吐泻腹胀、气闷，乃湿浊困阻脾胃，升降失司；肢酸头疼，湿邪外淫经络。脉症合参，病机为湿疟蕴阻脾胃，治以疏和，化湿畅中。", ["弦", "数"]], "2483": ["病机", "湿著胆胃，发为间疟，脉弦数。弦为胆胃气滞、湿阻枢机，数为湿热内蒸。脘闷呕恶、舌黄糙，湿浊中阻、胃失和降；头疼腰酸，湿邪上扰下注。脉弦数说明湿著胆胃、枢机不利，法以和解，疏利胆胃。", ["弦", "数"]], "2484": ["病机", "伏邪从膜原外腾为间疟，脉弦数。弦主膜原邪阻、气机郁滞，数主热邪内盛。热时神昏、身热不凉，邪热扰及心神；头疼呕吐、腹痛便溏，邪阻中焦、升降失常。舌糙黄，热伤津液。脉症示伏邪外腾，当以和解透达。", ["弦", "数"]], "2485": ["预后", "二诊疟来便溏，伏邪由表入里，脉仍弦数。弦数不退，说明邪热未衰，内陷之势未止。热甚神昏、肠中㽲痛、舌糙黄，皆邪热内传、伤及肠营之象。最虑疟邪内陷入营，脉仍弦数正是邪势鸱张之征，预后当防营分受累。", ["弦", "数"]], "2486": ["病机", "便泻稍减，热势亦缓，脉弦微和。弦为疟邪未尽、气机尚滞，微和示胃气渐复、邪势稍退。寤寐不安，乃余邪扰神；舌黄腻，湿浊未净。脉弦微和说明邪减而正渐复，但疟潮复来，仍宗原法佐以疏和，不可骤补。", ["弦", "微", "和"]], "2487": ["病机", "寒食互滞，引动痧秽伤中，脉濡弦。濡主湿浊内蕴，弦主气机壅滞。寒食互结，痧秽伤中，致腹痛吐泻，脉道濡软而兼弦急。濡弦并见，说明寒食湿浊阻滞中焦，气机不通。尚须疏和和运，化滞畅中，使邪去正安。", ["濡", "弦"]], "2488": ["病机", "脉小一弦，小为正气不足，弦主湿郁肝胆、气机不畅。原文“湿著胆胃，从膜原外腾为疟”，湿浊阻于胆胃，邪从膜原外发，故脉见小弦。小示湿困正伤，弦示胆胃气郁，主疟疾寒热，法宜和解，以疏利膜原、调畅胆胃。", ["小", "弦"]], "2489": ["病机", "脉弦数，弦主少阳胆经气郁，数主热。原文“湿著胆胃，间疟四度，寒热俱甚，脘膈辄嗳，饮啖式微，舌黄糙”，湿郁化热，胆胃不和，邪正交争，故脉弦数。主间疟寒热俱甚、脘嗳食少，法当和解少阳、阳明。", ["弦", "数"]], "2490": ["病机", "脉濡弦，濡主湿，弦主邪郁三阴、络脉不和。原文“湿著不化，深伏三阴为痎疟”，湿邪久伏，深入三阴，络脉痹阻，故脉濡弦。阴虚失血之体，湿伏更易伤络，主痎疟缠绵，法宜搜剔络邪。", ["濡", "弦"]], "2491": ["病机", "脉弦数，弦主少阳膜原之郁，数主暑热。原文“暑邪从膜原外腾为间疟”，暑热郁于膜原，外出与卫气争，故脉弦数。主间疟寒热，法当和解，以疏达膜原、清解暑热。", ["弦", "数"]], "2492": ["病机", "脉弦数，弦主寒湿郁阻气机，数主郁而化热。原文“寒湿阻中，形寒便泻”，寒湿困阻中焦，阳气不达，郁而脉数。成疟乃吉，示邪有外达之机。主寒湿阻中、形寒便泻，脉弦数反映郁热内蕴。", ["弦", "数"]], "2493": ["病机", "脉濡弦，濡主湿，弦主邪伏三阴、络脉不和。原文“湿伏三阴，痎疟连枝，不分经界，身热神疲”，湿邪深伏，弥漫三阴，络脉痹阻，故脉濡弦。主痎疟缠绵、身热神疲，法当搜剔络邪。", ["濡", "弦"]], "2494": ["病机", "脉弦数，弦主少阳枢机不利，数主热。原文“寒热甚重，汗出颇爽，咳呛肋痛，舌黄糙”，邪郁少阳，热势偏盛，故脉弦数。主疟疾寒热甚重、咳呛肋痛，治以和解，疏利少阳枢机。", ["弦", "数"]], "2495": ["病机", "脉小弦，小主气滞正伤，弦主气机郁滞。原文“投分利法，寒热依然不达，气滞失调，肢酸腹胀”，分利后邪未外达，气滞不通，故脉小弦。主气滞失调、肢酸腹胀，再以疏泄调畅气机。", ["小", "弦"]], "2496": ["病机", "脉右濡弦左关兼滑，濡主湿，弦主肝，滑主痰湿。右濡弦示湿留太阴，左关滑示肝脾同病。疟久气阴两虚，正虚湿邪留恋，故肢肿腹膨、神疲力懈。舌淡绛苔腻亦为湿郁之象。花甲高年，正虚难托，病机在肝脾，属虚实夹杂。", ["濡", "弦", "滑"]], "2497": ["病机", "脉伏为寒邪痧秽格拒中枢，阳气不能外达所致。吐泻交作、霍乱转筋、肢厥，皆因寒邪内闭，气机升降逆乱，阳郁不伸。汗多烦渴为津液外泄之象。脉伏与肢厥并见，提示邪闭正伤，亟需仲景法温通开闭。", ["伏"]], "2498": ["病机", "脉小弦，小主正虚，弦主寒邪痧秽挟食内阻。寒食格拒中枢，气机不畅，故泛呕腹泻、形寒腹痛。舌黄腻为湿食内蕴化热之征。脉小弦与形寒腹痛相应，示寒邪未深而正气已伤，治以疏和，调畅气机。", ["小", "弦"]], "2499": ["病机", "脉弦数，弦主寒邪痧秽格拒，数主邪郁化热。先泻后吐、形寒身热，为寒邪外束、内热渐生之象。舌黄糙示热伤津液。脉弦数与身热相应，说明寒邪痧秽引动内热，气机逆乱，治以疏和，透邪调中。", ["弦", "数"]]});